  quests = {
    [2] = {ot = "Leve a Garra de Garraguda para Senani Coração Trovejante no Posto Machadada, Vale Gris.", st = "O poderoso hipogrifo Garraguda foi abatido, e a garra da fera serve como prova da sua vitória. Senani Coração Trovejante, do Posto Machadada, sem dúvida ficará interessada em ver esse troféu como prova do seu feito.", t = "Garra de Garraguda"},
    [5] = {ot = "Fale com o Chef Goroba.", st = "Eu estou preso, escondido nesta cidade fantasma há semanas, e não tenho comido nada além de larvas e ervas daninhas! Eu preciso de alguma comida decente, e estou disposto a pagar bem por isso.$B$BTraga-me um banquete e lhe pagarei generosamente.$B$BOuvi dizer que o Chef Goroba, da Taberna Corvo Escarlate, lá da Vila Sombria, faz uns bolinhos de caranguejo crepuscular deliciosos...", t = "A barriga roncante de Medrisco"},
    [6] = {ot = "Mate Garrick Patatenra e leve a cabeça dele para o Cabo Vilém na Abadia de Vila Norte.", st = "Garrick Patatenra — um criminoso que atormenta nossos fazendeiros e mercadores há semanas — foi visto em uma cabana perto dos vinhedos, que ficam a leste da Abadia e do outro lado da ponte. Traga-me a cabeça do patife e ganhe a recompensa por matá-lo!$B$BMas tenha cuidado, $n. Garrick reuniu uma gangue de brutamontes. Não será fácil chegar até ele.", t = "Recompensa por Garrick Patatenra"},
    [7] = {ot = "Mate 10 Kobolds Daninhos, depois fale novamente com o Major Belmonte.", st = "Sua primeira tarefa é de purificação, $n. Um clã de kobolds está infestando o bosque ao norte daqui. Vá até lá e derrote todos os malditos kobolds que encontrar. Se você reduzir os números deles, a gente tem mais chances de expulsar os kobolds da Vila Norte de uma vez por todas.", t = "Limpeza no acampamento dos kobolds"},
    [8] = {ot = "Entregue a Carta Comum à Estalajadeira Geni nas Clareiras de Tirisfal.", st = "Ei, colega! Faz um favor para um jovem que tem combatido mais do que seu quinhão de aranhas e zumbis estúpidos?$B$BTenho aqui esta carta que precisa chegar a Montalvo... até uma estalajadeira chamada Geni qualquer coisa. O sobrenome dela não tem a menor importância.$B$BEnfim, é um lugar pequeno e aconchegante cheio de vítimas da peste tentando ganhar a vida. E seria um ótimo local para você descansar também se houver necessidade. Você deveria conferir... faça isso, que eu lhe pago bem.", t = "Palavra de ladino"},
    [9] = {ot = "O Fazendeiro Saldanha quer que você mate 20 Guarda-colheitas.", st = "Olha só o estado deste lugar! Estas terras já foram ocupadas por bons fazendeiros, mas os malditos ladrões botaram todos pra correr. Mas a mim, não! Acontece, porém, que alguns Guarda-colheitas tomaram posse dos campos.$b$bSe estiver dispost$go:a;, gostaria que você matasse vinte deles pra mim. Quando terminar, volte aqui que eu lhe darei uma boa recompensa. Depois que acabar com os que estiverem no meu campo, você também pode acabar com os que estiverem nos campos vizinhos.", t = "Campos mortais"},
    [11] = {ot = "Leve 8 Braçadeiras Pintadas dos Gnolls para o Delegado Ranieri no Quartel.", st = "Aquelas criaturas brutas e indecentes, os gnolls, tem sido vistas por aqui, nos limites da Floresta de Elwynn. Uma matilha grande, maior do que podemos enfrentar sozinhos, infestou o bosque ao sul daquela torre de guarda. Outro grupo infestou as áreas perto do Lago do Monumento, a leste daqui.$B$BO Exército de Ventobravo com certeza saberá recompensar quem ajudar a matar esses gnolls. Traga-me as braçadeiras pintadas que eles usam como prova.", t = "Caçando gnolls"},
    [12] = {ot = "Miguel Mantoforte quer que você mate 15 Coureadores Défias e 15 Contrabandistas Défias, e fale novamente com ele no Morro da Sentinela.", st = "A Milícia do Povo tem apenas um objetivo: defender as terras de Cerro Oeste e devolver a paz ao nosso entorno. Infelizmente, o preço da paz é muitas vezes pago com sangue.$b$bUm dos meus batedores informou que um bando de Coureadores Défias está causando problemas aqui perto. Eu tenho relatos de Coureadores Défias próximos da Mina Veiojango a noroeste, bem como na Fazenda dos Peçanha e na Plantação de Abóboras do Taturana. Se quiser se juntar a nós, mate 15 Coureadores Défias e 15 Contrabandistas Défias, e então venha falar comigo.", t = "A Milícia do Povo"},
    [13] = {ot = "Miguel Mantoforte quer que você mate 15 Pilhadores Défias e 15 Gatunos Défias, e fale novamente com ele no Morro da Sentinela.", st = "Um bando de pilhadores Défias foi visto saqueando a Pedreira Costa Dourada, o Arroio da Lua e a Fazenda dos Aleixo. A Milícia do Povo não vai tolerar esse tipo de comportamento. Liquide-os imediatamente, $n, e marque a presença da Luz no Cerro Oeste.$b$bA Pedreira Costa Dourada fica perto da costa, a oeste da torre. Para dar prosseguimento ao seu treinamento, quero que você mate 15 desses pilhadores Défias imundos e 15 gatunos Défias.", t = "A Milícia do Povo"},
    [14] = {ot = "Miguel Mantoforte quer que você mate 15 Bandoleiros Défias, 5 Tocaiantes Défias e 5 Rufiões Défias, e fale novamente com ele no Morro da Sentinela.", st = "Alguns Défias nos enganaram. Meu batedor mais confiável informou que esses Défias têm saqueado e pilhado do interior ao sul de Cerro Oeste. Nós achamos que eles estão se escondendo nos Obeliscos, planejando o próximo passo. Mate os malfeitores em nome da Milícia do Povo.", t = "A Milícia do Povo"},
    [15] = {ot = "Mate 10 Trabalhadores Kobolds e fale novamente com o Major Belmonte.", st = "$n, meus batedores me disseram que a infestação de kobolds é maior do que pensávamos. Um grupo de trabalhadores kobolds se assentou perto da Mina da Serra do Eco, ao norte.$B$BVá até a mina e remova-os. Sabemos que há pelo menos 10 deles. Mate-os, veja se tem mais, depois venha falar comigo.", t = "Investigue a Serra do Eco"},
    [18] = {ot = "Leve 12 Bandanas de Lona Vermelha para o Cabo Vilém diante da Abadia de Vila Norte.", st = "Nos últimos tempos, tem um grupo novo de ladrões na região de Vila Norte. Eles se intitulam a Irmandade Défias e foram vistos do outro lado do rio, a leste.$B$BNão sei o que estão aprontando, mas coisa boa é que não é! Traga para mim as bandanas que eles usam e eu te dou uma arma como recompensa.", t = "Irmandade dos Ladrões"},
    [19] = {ot = "Leve a Cabeça do Tharil'zun ao Oficial Marris em Cristarrubra.", st = "Vanguardeiros Rocha Negra e Proscritos estão armando emboscadas daqui até a Bastilha Mirante de Pedra. O líder dos Vanguardeiros é um orc chamado Tharil'zun. Precisamos detê-lo. Tragam-me a cabeça de Tharil'zun!", t = "Tharil'zun"},
    [20] = {ot = "Traga 10 Machados Gastos em Batalha para o Oficial Marris na Vila Plácida.", st = "Os orcs da Rocha Negra saíram das Estepes Ardentes e tomaram a Bastilha Mirante de Pedra, ao norte. A partir dali, saquearam as regiões ao norte da Vila Plácida e mantiveram os cidadãos dentro da cidade, cercados como gado.$B$BAjude a libertar a Vila Plácida dessa ameaça. Mate os orcs da Rocha Negra e me traga dez machados gastos em batalha como prova.$B$BApesar da ameaça vir do norte, recebemos relatos de mais Rochas Negras na parte sudeste de Cristarrubra. Se encontrar alguns lá, mate-os também.", t = "Ameaça dos Rochas Negras"},
    [21] = {ot = "Mate 12 Operários Kobold, depois fale novamente com o Major Belmonte na Abadia de Vila Norte.", st = "Suas pesquisas provaram que a Mina da Serra do Eco precisa de um expurgo. Volte à mina e ajude a acabar com os kobolds lá.$B$BNão perca tempo, $n. Quanto mais tempo os kobolds passarem na mina, mais estabelecidos eles estarão na Vila Norte.", t = "Escaramuça na Serra do Eco"},
    [22] = {ot = "Salma Saldanha precisa de 8 Fígados de Goretusco para fazer um Empadão de Fígado de Goretusco.", st = "Já descasquei as cebolas, triturei o alho e o alecrim, assei a crosta, piquei o endro, e o molho está cozinhando. Agora, eu só preciso de 8 fígados de goretusco para fazer o meu famoso empadão de carne!", t = "Empadão de Fígado de Goretusco"},
    [23] = {ot = "Leve a Pata de Ursangous para Senani Coração Trovejante no Posto Machadada, Vale Gris.", st = "<A pata do poderoso urso Ursangous é seu troféu nesta parte da Caçada do Vale Gris. Na pata, há um pequeno emblema em forma de lua crescente, mas seu significado permanece um mistério.$B$BA pata deve ser levada para Senani Coração Trovejante, no Posto Machadada, para provar que você derrotou a poderosa criatura e concluiu esta parte da caçada.>", t = "Pata de Ursangous"},
    [24] = {ot = "Leve a Cabeça de Shadumbra para Senani Coração Trovejante no Posto Machadada, Vale Gris.", st = "O outrora veloz Shadumbra agora permanece imóvel enquanto você declara vitória sobre ele. A cabeça do sabre-da-noite é um troféu apropriado para essa luta da Caçada do Vale Gris. Senani Coração Trovejante, no Posto Machadada, vai querer ver um troféu como esse para lhe dar crédito por esta parte da Caçada do Vale Gris.", t = "Cabeça de Shadumbra"},
    [25] = {ot = "Liquide 12 Elementais da Água Contaminados no Lago Mistral, a leste do Túnel Garracava e a sudoeste de Posto Machadada.$B$BFaça o reconhecimento do gazebo do Lago Mistral, que fica de frente para o Entreposto da Aliança mais próximo.$B$BFale novamente com Mastok Wrilehiss em Posto Machadada, no Vale Gris.", st = "Se quer ajudar, então por que não faz alguma coisa sobre a situação para os lados do Túnel Garracava?$B$BOs transportes entre Vale Gris e Torres de Pedra estão parados porque o lago ganhou vida e está atacando qualquer coisa que se aproxime... ou seja, qualquer um no caminho. Ainda mais útil do que simplesmente atacar os elementais da água por lá seria alguém fazer o reconhecimento do gazebo do Lago Mistral... aquele de onde dá pra ver bem o Entreposto da Aliança.$B$BPront$go:a; para fazer alguma coisa de útil?", t = "Paralisação nas Torres de Pedra"},
    [26] = {ot = "Fale com Dendrite Stellardor no vilarejo de Refúgio Noturno, na Clareira da Lua.", st = "$n, tenho acompanhado seu progresso com grande alegria. Você está mesmo se tornando $Gum:uma; protet$Gor:ora; e tanto da natureza.$B$BAgora chegou a sua hora de aprender mais sobre um dos muitos aspectos animais nos quais, pela graça de Cenarius, nós podemos nos transformar – o aspecto que concede o comando e a maestria da água. Para isso, você precisa viajar para a cidade de Refúgio Noturno, que fica na Clareira da Lua, e falar com Dendrite Stellardor no Círculo Cenariano. Ele informará os seus próximos passos.", t = "Uma lição a aprender"},
    [27] = {ot = "Fale com Dendrite Stellardor no vilarejo de Refúgio Noturno, na Clareira da Lua.", st = "$n, tenho acompanhado seu progresso com grande alegria. Você está mesmo se tornando $Gum:uma; protet$Gor:ora; e tanto da natureza.$B$BAgora chegou a sua hora de aprender mais sobre um dos muitos aspectos animais nos quais, pela graça de Cenarius, nós podemos nos transformar – o aspecto que concede o comando e a maestria da água. Para isso, você precisa viajar para a cidade de Refúgio Noturno, que fica na Clareira da Lua, e falar com Dendrite Stellardor no Círculo Cenariano. Ele lhe informará dos seus próximos passos.", t = "Uma lição a aprender"},
    [28] = {ot = "Encontre um Adorno de Altar no Lago Eluna'ara e leve-o para o Santuário de Remulos, na parte noroeste da Clareira da Lua. Use o Adorno de Altar lá dentro.$B$BVocê terá que falar com Tajarri, lá no santuário mesmo, para concluir a prova.", st = "Na sua primeira prova, você mergulhará nas profundezas do Lago Eluna'ara, atrás de um Adorno de Altar. Ele se desmancha bem rápido, então trate de levá-lo correndo para o Santuário de Remulos. Use o adorno dentro do santuário, depois fale com Tajarri lá mesmo. Ela é uma das guardiãs mais respeitadas pela Clareira da Lua.$B$BVocê não terá muito tempo para concluir a tarefa e talvez esteja competindo pelos adornos com outros druidas. Destreza física e mental serão essenciais para triunfar.$B$BBoa sorte, $n.", t = "A prova do lago"},
    [29] = {ot = "Encontre um Adorno de Altar no Lago Eluna'ara e leve-o para o Santuário de Remulos, na parte noroeste da Clareira da Lua. Use o Adorno de Altar lá dentro.$B$BVocê terá que falar com Tajarri, lá no santuário mesmo, para concluir a prova.", st = "Na sua primeira prova, você mergulhará nas profundezas do Lago Eluna'ara, atrás de um Adorno de Altar. Ele se desmancha bem rápido, então trate de levá-lo correndo para o Santuário de Remulos. Use o adorno dentro do santuário, depois fale com Tajarri lá mesmo. Ela é uma das guardiãs mais respeitadas pela Clareira da Lua.$B$BVocê não terá muito tempo para concluir a tarefa e talvez esteja competindo pelos adornos com outros druidas. Destreza física e mental serão essenciais para triunfar.$B$BBoa sorte, $n.", t = "A prova do lago"},
    [30] = {ot = "Encontre o Meio-pingente da Agilidade Aquática e o Meio-pingente da Resistência Aquática. Fale com os residentes da Clareira da Lua para obter pistas de onde esse itens podem estar.$B$BForme o Pingente do Leão Marinho a partir das duas metades. Você precisa estar perto do Santuário de Remulos para fazer isso.$B$BLeve o pingente reunido ao Dendrite Stellardor na vila de Refúgio Noturno, que fica na Clareira da Lua.", st = "Para a segunda prova, você vai precisar das duas metades que formam o Pingente do Leão Marinho. Uma delas extrai poder do aspecto da agilidade do leão marinho, que desliza pela água. A outra extrai poder do aspecto da inacreditável resistência do leão marinho. Os druidas se valem igualmente das duas características para encarnar o aspecto de sua forma aquática.$B$BFale com os moradores da Clareira da Lua para saber onde as partes podem estar, e traga ambas para cá, onde podemos reuni-las. Quando o pingente estiver formado, leve para Dendrite Stellardor.", t = "Missão do leão marinho"},
    [31] = {ot = "Volte ao Penhasco do Trovão e mostre a Turak Runa Totem o Pingente do Leão Marinho.", st = "Você completou as lições necessárias que todos os jovens druidas aprendem antes poderem adotar um aspecto aquático. Vá reencontrar seu treinador, Turak Runa Totem, no Penhasco do Trovão. Mostre-lhe o seu pingente e prove que você está $Gpronto:pronta; para aprender o que ele tem para lhe ensinar. Ele completará seu treinamento, permitindo que você entre em harmonia com a água.$B$BAdeus, jovem $Gdruida:druidesa;. Nos encontraremos novamente.", t = "Forma aquática"},
    [33] = {ot = "Leve 8 pedaços de Carne Dura de Lobo para Enzo Peleteiro nos arredores da Abadia de Vila Norte.", st = "Odeio aqueles lobos silvestres, mas não abro mão de um bife de lobo... Se me arranjar uma carne dura de lobo, trocarei por algo que você achará bem útil.$B$BCace os lobos silvestres e os lobinhos que andam nas áreas rurais da Vila Norte para coletar essa carne dura de lobo.", t = "Só louco não come lobo"},
    [34] = {ot = "Martie Jainrose, de Vila Plácida, quer que você mate Ronquifuça. Traga a presa dele como prova.", st = "Meu jardim foi pisoteado e saqueado. E sei quem é o brutamontes que está fazendo isso. É aquele maldito javali que o Oficial Marris começou a chamar de Ronquifuça.$b$bVou ter que esperar a próxima estação pra poder plantar meus narcisos de novo... Tudo arruinado! Tudo arruinado por aquele javali maldito. Dê cabo dessa praga! Traga a presa dele pra mim e ficarei feliz em recompensar você. Ele passa o tempo fuçando nos campos a sudoeste de Vila Plácida, mas de vez em quando vem pra cá e faz esse estrago no meu jardim...", t = "O penetra"},
    [35] = {ot = "O Delegado Durão quer que você fale com o Guarda Tomás.", st = "Se você está $gpreocupado:preocupada; quanto aos rumores sobre os murlocs, faça o seguinte: vá para a ponte leste de Elwynn e fale com o guarda Tomás. Ele está lá desde a semana passada e vai saber qual a situação do local.$B$BTraga-me o relatório dele.", t = "Mais preocupações"},
    [36] = {ot = "Vera Taturana quer que você entregue a receita de Ensopado de Cerro Oeste dela a Salma Saldanha.", st = "Nunca achei que chegaria o dia em que eu sairia da fazenda. Mas os campos estão infestados de ladrões, e agora está perigoso demais para nós aqui. Assim que o Fazendeiro Taturana concertar a carroça, a gente pega a estrada.$b$bSerá que você não podia me fazer um favor? Deixa eu anotar aqui a minha receita do ensopado de Cerro Oeste. Você leva pra Salma Saldanha, da outra fazenda? A fazenda dos Saldanha fica logo depois da bifurcação na estrada.", t = "Ensopado de Cerro Oeste"},
    [37] = {ot = "O Guarda Tomás quer que você vá para o norte, seguindo o rio, e encontre os dois guardas perdidos, Rodolfo e Malaquias.", st = "Já faz dois dias que mandamos dois guardas, Rodolfo e Malaquias, para investigar ao longo do rio. Eles ainda não voltaram. Para completar meu relatório, preciso saber o que aconteceu com eles.$B$BVá para norte, seguindo o rio, e encontre os guardas... ou o que restou deles.", t = "Encontre os guardas perdidos"},
    [38] = {ot = "Salma Saldanha quer 3 nacos de Acém de Abutre, 3 Focinhos de Goretusco, 3 Olhos de Murloc e 3 Quiabos.", st = "Ajude-me a fazer um ensopado de Cerro Oeste! Retorne com os seguintes ingredientes: $b $b 3 nacos de Acém de Abutre $b 3 Focinhos de Goretusco $b 3 Olhos de Murloc $b 3 Quiabos", t = "Ensopado de Cerro Oeste"},
    [39] = {ot = "Apresente-se ao Delegado Durão na Vila d'Ouro.", st = "Conte ao Delegado Durão sobre as mortes de Malaquias e Rodolfo. Conte também que os murlocs na área leste de Elwynn não podem ser contidos pelas tropas que temos lá.$B$BEu sei que não temos um grande contingente, mas com sorte Durão achará alguém.", t = "O relatório de Tomás"},
    [40] = {ot = "Remy \"Duas Vezes\" quer que você fale com o Delegado Durão em Vila d'Ouro.", st = "$n, há uma nova ameaça na Floresta de Elwynn! Os murlocs estão subindo pelos córregos da parte leste, espantando os peixes e atacando a população!$B$BEu avisei o delegado Durão, mas ele só se preocupa com gnolls e bandidos. Ele acha que os murlocs não são uma ameaça.$B$BPor favor, $n, fale com Durão e convença-o a mandar mais tropas para o leste!", t = "Perigo anfíbio"},
    [45] = {ot = "Vasculhe o vilarejo murloc e tente encontrar Rodolfo ou vestígios de sua morte.", st = "Vasculhando a área, você encontra pegadas com marcas de membranas seguindo para leste ao longo da costa até o Lago do Monumento. Ao longe, na direção leste, dá para discernir os contornos de um vilarejo murloc.$B$BTalvez tenha sido lá que Rodolfo tenha encontrado seu fim...", t = "Descubra o destino de Rodolfo"},
    [46] = {ot = "Leve 8 Barbatanas Rasgadas de Murloc para o Guarda Tomás na ponte leste de Elwynn.", st = "O Exército de Ventobravo está oferecendo recompensa por tocaieiros e colhedores murloc que forem encontrados em Elwynn. Mate-os e traga-me as barbatanas rasgadas deles, e o Exército de Ventobravo lhe dará uma generosa recompensa.$B$BOs murlocs construíram um vilarejo no Lago do Monumento, ao norte daqui, e outro ao sul, no ponto em que o córrego se bifurca.", t = "Barbatanas de molho"},
    [47] = {ot = "Traga 10 Pós de Ouro para Remy \"Duas Vezes\" em Vila d'Ouro. O Pó de Ouro é coletado dos Kobolds na Floresta de Elwynn.", st = "Os kobolds daqui às vezes carregam pó de ouro. Estou precisando de pó de ouro, pó de ouro... Me traga algum e eu lhe faço o melhor preço da cidade, o melhor preço da cidade!$B$BOs kobolds ficam na Mina Vailafundo, ao sul, e perto da Mina de Jaspe, a nordeste daqui, daqui.", t = "Trocando Pó de Ouro"},
    [52] = {ot = "Mate 8 Predadores e 5 Jovens Ursos da Floresta, e fale novamente com o Guarda Tomás na ponte leste de Elwynn.", st = "Saudações, $n. Os animais selvagens ficam mais agressivos à medida que nos afastamos de Vila d'Ouro. A Madeireira Vale do Leste está sofrendo com os ataques constantes de lobos e ursos!$B$BUma ajuda aqui seria bem-vinda.", t = "Proteja a fronteira"},
    [54] = {ot = "Entregue os Documentos do Major Belmonte para o Delegado Durão em Vila d'Ouro.", st = "$n, como você é $Gum:uma; $c com comprovado interesse pela segurança de Vila Norte, queremos $Gdesigná-lo:designá-la; para a proteção dos arredores da Floresta de Elwynn.$B$BSe aceitar a incumbência, preciso que você entregue uma papelada que preparei para o delegado Durão em Vila d'Ouro, que fica na estrada a sul, além dos portões da fronteira.", t = "Apresente-se em Vila d'Ouro"},
    [56] = {ot = "A Comandante Aldora Ebanez da Vila Sombria quer que você mate 8 Guerreiros Descarnados e 6 Magos Descarnados.", st = "Como Comandante da Vigília Noturna, é o meu dever proteger os cidadãos da Vila Sombria. Ventobravo retirou os guardas de seus postos aqui, e agora só contamos com os nossos próprios dispositivos.$b$bSe você acha que está à altura da tarefa, precisamos da sua ajuda! Auxilie a Vigília Noturna indo até os Jardins da Paz, que fica logo ao sul da Vila Sombria, e mate oito guerreiros descarnados e seis magos descarnados. A ameaça dos mortos-vivos precisa ser contida!", t = "A Vigília Noturna"},
    [57] = {ot = "A Comandante Aldora Ebanez da Vila Sombria quer que você mate 15 Malévolos Descarnados e 15 Horrores Descarnados.", st = "$n, estou recebendo relatos de uma infestação de mortos-vivos na floresta! Se você estiver à altura da tarefa, vá para o Monte Corvo e mate 15 daqueles vis malévolos descarnados e 15 horrores descarnados. Há também relatos de esqueletos logo ao sul de Vila Sombria, perto do Cemitério Jardins da Paz. Os mortos-vivos devem ser rechaçados da Floresta do Crepúsculo!", t = "A Vigília Noturna"},
    [59] = {ot = "Dê o Vale-armadura de Ventobravo para Sara Albernaz.", st = "Como recompensa por sua bravura e astúcia, tenho um molde aqui para uma peça de armadura. Quero que você leve o molde para Sara Albernaz na Madeireira Vale do Leste. Apresente o molde e ela vai montar a armadura pra você. Quando receber a armadura, $n, use-a para defender Elwynn.$B$BA Madeireira fica a leste, depois do posto do Guarda Tomás.", t = "Armadura de pano e couro"},
    [60] = {ot = "Leve 8 Velas Grandes para Durval Pilão em Vila d'Ouro.", st = "Olá, $Gmeu bom senhor:minha cara dama;! Você pode me dar um segundo de sua atenção?$B$BMeu irmão e eu somos donos de uma botica em Ventobravo, e vim aqui coletar velas grandes, pois precisamos da cera. Pode me ajudar?$B$BVocê vai encontrar velas grandes com os kobolds. Ouvi boatos de que eles estariam infestando as minas de Elwynn... a Mina Vailafundo, ao sul daqui, e a Mina de Jaspe, a leste. Sugiro procurar velas por lá.", t = "Velas dos kobolds"},
    [61] = {ot = "Leve o Carregamento do Guilherme para Morgado Pilão no Distrito Comercial de Ventobravo.", st = "Meu irmão Morgado está em Ventobravo esperando meu carregamento de velas. Eu mesmo não tenho tempo para fazer a viagem, mas, se você quiser fazer o frete, ele paga bem.$B$BJá embalei as velas. O Morgado fica na nossa loja, a Botica do Pilão, no Distrito Comercial.", t = "Frete para Ventobravo"},
    [62] = {ot = "Explore a Mina Vailafundo e depois fale novamente com o Delegado Durão em Vila d'Ouro.", st = "A mina de Vila Norte não é a única com problemas! Tenho relatórios aqui dizendo que a Mina Vailafundo, em Elwynn, também se tornou um antro de kobolds.$B$BExplore a mina, confirme esses relatórios e volte a falar comigo. A mina fica ao sul de Vila d'Ouro, entre as fazendas Campedra e Madruga.", t = "A Mina Vailafundo"},
    [63] = {ot = "Derrote a Manifestação da Água Corrompida e deposite as Braçadeiras da Manifestação Corrompida junto com as Gotas Restantes da Mais Pura Água no Braseiro da Fonteterna, que fica na Floresta de Pinhaprata.", st = "No litoral de Pinhaprata, a oeste do Sepulcro, você vai encontrar um altar que foi maculado pela peste. Os espíritos de lá não falam mais com o nosso povo, por isso cabe a você derrotar a manifestação e purificar a lagoa.$B$BPegue as braçadeiras dos elementais e as últimas gotas da poção de Salma e deposite no braseiro. O ritual deve bastar para evocar um espírito puro com que você possa se comunicar.$B$BTraga uma prova de que a tarefa foi cumprida e eu lhe recompensarei com o seu totem.", t = "Clamor da água"},
    [64] = {ot = "O Fazendeiro Taturana quer que você recupere o relógio de bolso dele no guarda-roupa da sede de sua fazenda de abóboras, a oeste.", st = "Foi horrível. A Vera me acordou quando ouviu uma balbúrdia nos campos, que estavam cheios de arruaceiros. Saímos correndo e acabei esquecendo meu relógio de bolso. O pai da Vera meu deu o relógio no nosso casamento, por isso eu fico doente só de pensar naqueles ladrões com meu presente. Deixei o relógio no guarda-roupa da sede. Procure os campos de abóbora a oeste, não dá para não ver. Se trouxer ele de volta para mim, eu ficarei muito grato.", t = "Herança esquecida"},
    [65] = {ot = "Miguel Mantoforte quer que você converse com Wiley, em Vila Plácida.", st = "O bando de canalhas responsável por expulsar o povo de Cerro Oeste se autointitula A Irmandade Défias. Preciso que você se infiltre nesse clã de bandidos. Precisamos saber quem comanda o cartel e onde estão escondidos. Em Vila Plácida, na estalagem, tem um ladino chamado Wiley que me deve um favor.$b$bViaje até Vila Plácida, que fica nas Montanhas Cristarrubra, a leste de Elwynn, e tente obter o máximo de informações possível.", t = "A Irmandade Défias"},
    [66] = {ot = "Encontre o Tabelião Azambuja na Prefeitura de Vila Sombria.", st = "Ontem à noite uma sensação horrível tomou conta do meu corpo. Eu senti que minha neta Alyssa corria grande perigo. Consultei as cartas e vi a morte na mesa.$b$bDepois de uma longa jornada por um transe sinistro, descobri uma pista a respeito desse mistério terrível. Um nome veio até mim, o nome Galvão.$b$bEncontre o Tabelião na Prefeitura e veja se consegue descobrir mais alguma coisa a respeito do sujeito. Eu temo por todos nós.", t = "A lenda de Galvão"},
    [67] = {ot = "Vá ao Liceu do Arroio da Lua e relate qualquer informação atualizada sobre Galvão ao Tabelião Azambuja.", st = "Galvão, é? Deixe-me ver o arquivo da cidade.$b$bGalvão... Galvão... vejamos. Ah, olha só! Tenho o registro de um sr. Galvão Brumanto. O último endereço conhecido foi o Liceu do Arroio da Lua. Nossa! Isso é que é desatualização!$b$bVocê me faz um favor, amig$go:a;? Se acontecer de você passar pelo Arroio da Lua, me conte se descobrir qualquer coisa sobre esse camarada. Eu gostaria de manter os registros em ordem.", t = "A lenda de Galvão"},
    [68] = {ot = "Leve a Carta Não Enviada e Empoeirada para o Tabelião Azambuja.", st = "Você encontra uma carta não enviada e empoeirada no velho baú.", t = "A lenda de Galvão"},
    [69] = {ot = "Vá à Estalagem do Leão Orgulhoso para ver se alguém ouviu falar de Galvão.", st = "Minha Luz! Devo ter deixado passar da primeira vez. No registro, logo abaixo do primeiro endereço de Galvão há outro listado, parcialmente raspado. Parece que ele estava indo para a Estalagem do Leão Orgulhoso, em Vila d'Ouro. Pode ser bom averiguar por lá, $n.", t = "A lenda de Galvão"},
    [70] = {ot = "Pegue a Carta Não Entregue de Galvão no baú entregue-a no Distrito do Canal, em Ventobravo.", st = "O nome Galvão não me é estranho. Agora eu lembro.$b$bMuitos anos atrás, em uma noite de tempestade, chegou um mensageiro em busca de um refúgio para passar a noite. Perto da meia-noite, o homem desceu correndo a escada, lívido de medo. Ainda de pijama, ele desapareceu no meio do temporal.$b$bNa pressa, ele esqueceu as cartas no baú lá em cima. Nunca voltou para buscar a correspondência. Ainda tem uma aqui, que aquele sujeito Galvão ia levar para o Distrito do Canal, em Ventobravo. Esteja à vontade para pegar.", t = "A lenda de Galvão"},
    [71] = {ot = "Entregue os Medalhões de Rodolfo e Malaquias para o Guarda Tomás na ponte leste de Elwynn.", st = "Agora que você tem os dois medalhões, entregue-os para o guarda Tomás na ponte, para que ele saiba do destino que se abateu sobre seus guardas.", t = "Apresente-se a Tomás"},
    [72] = {ot = "Procure alguma pista nos pertences guardados.", st = "Muito antes de mim, quem cuidava da propriedade era o meu pai. Ele que teve limpar toda a bagunça que ficou depois do massacre. Mas não importa.$b$bOs fundos dos Petracume acabaram. Agora os últimos pertences da família vão ser leiloados. Tudo culpa dos cobradores de impostos, aqueles abutres. Se tu tiver muito interessad$Go:a; em saber mais, pues fique à vontade para olhar aqui no meio dessa tranqueira. Quem sabe o que tu pode encontrar?", t = "A lenda de Galvão"},
    [76] = {ot = "Explore a Mina de Jaspe e, depois, fale com o Delegado Durão em Vila d'Ouro.", st = "Graças a você sabemos que a Mina Vailafundo está infestada de kobolds. Agora, precisamos de um batedor para investigar a Mina de Jaspe, que fica mais longe.$B$BExplore a Mina de Jaspe e confirme se há presença de kobolds. Para chegar à mina, vá para leste seguindo a estrada até que você chegue à Torre de Azora. Da torre, siga para o norte e você chegará à mina, ao pé das montanhas.", t = "A Mina de Jaspe"},
    [83] = {ot = "Leve 6 Bandanas de Linho Vermelhas para Sara Albernaz na Madeireira Vale do Leste.", st = "Os Défias de Vila Norte usam máscaras de lona, mas os Défias de Elwynn usam linho. Eu preciso desse material pra fabricar itens finos.$B$BMe traga umas bandanas vermelhas de linho e eu vou poder costurar alguma coisa pra você usar.$B$BOs Défias acampam em bandos por toda a Floresta de Elwynn.", t = "Além do linho vermelho"},
    [84] = {t = "...com a vontade de comer"},
    [85] = {ot = "Fale com Guinho Madruga.", st = "Perdi o meu colar... Aposto que foi aquele trombadinha do Guinho Madruga quem roubou! Ele está sempre se esgueirando feito um rato pelos Vinhedos dos Madruga, a leste daqui. $B$BRecupere meu colar, e você dará alento ao pobre coração de uma viúva...", t = "O colar perdido"},
    [86] = {ot = "Leve 4 Nacos de Carne de Javali Macia para a \"Titia\" Berenice Campedra na Fazenda dos Campedra.", st = "Se eu comesse tipo uma torta bem servida, acho que lembrava rapidinho de quem foi que pegou o colar. Sabe, a dona Berenice lá da outra fazenda faz uma Torta de Barriga de Porco muito da gostosa...$B$BQuem sabe se você não der pra ela uns nacos de carne de javali maciazinha, desses que vivem rondando por aqui, ela não faz uma torta pra você...?", t = "Juntando a fome..."},
    [87] = {ot = "Leve o Colar de Berenice para \"Titia\" Berenice Campedra na Fazenda dos Campedra, que fica na Floresta de Elwynn.", st = "Eu tava brincando perto da Mina Vailafundo e acho que deixei o, ahm, quer dizer, vi o colar da dona Berenice lá. Não me pergunte como ele chegou lá, não sei de nada!$B$BMas, enfim, eu vi um kobold grandão, com um dente de ouro, pegar o colar e correr pra dentro da mina. Encontre o kobold e você vai encontrar o colar, pode apostar!", t = "Dentadouro"},
    [88] = {ot = "Mate Princesa, pegue a coleira dela e leve-a para Mama Campedra na Fazenda dos Campedra.", st = "Os Braga tem uma porca premiada, chamada Princesa. A bicha é GIGANTE, e ficou assim de tanto vir aqui e devorar minha horta!$B$BPor isso, eu quero a Princesa morta antes que ela volte aqui aos nossos campos. Mate a porca e traga a coleira dela como prova, que eu lhe darei alguma coisa como pagamento!$B$BA Princesa geralmente está na nossa plantação de abóboras, que fica a leste, além da fazenda dos Madruga. Acabe com ela antes que volte aqui!", t = "Princesa tem que morrer!"},
    [89] = {ot = "Leve 5 Piques de Ferro e 5 Rebites de Ferro para o Encarregado Oslow, na Vila Plácida.", st = "Durante a última invasão órquica, tivemos que usar todo o nosso ferro para fazer projéteis, espadas e armaduras. Pedimos um novo carregamento de materiais para Ventobravo, mas um bando de gnolls Cristarrubra atacou a caravana e fugiu para as colinas que ficam atrás da Vila Plácida.$b$bAgora a gente ficou sem suprimentos para reconstruir essa ponte. Se você me trouxer 5 piques de ferro e 5 rebites de ferro, $n, vou te dar uma senhora recompensa.$b$bAgora, ao trabalho!", t = "A ponte do Lago Plácido"},
    [90] = {ot = "Colete 10 Lombos de Lobo Magro e volte ao Chef Goroba na Vila Sombria.", st = "Kebab Temperado de Lobo é um dos pratos favoritos da casa! É claro que posso fazer para você. Mas, antes, vou precisar dos ingredientes. Traga para mim 10 Lombos de Lobo Magro. Tem tanto lobo aqui na floresta que você não vai ter a menor dificuldade para encontrar os lombos. Para a sua sorte, eu acabei de receber um carregamento de Tempero de Ventobravo, então tudo que preciso é dos lombos para começar o preparo.", t = "Kebab Temperado de Lobo"},
    [91] = {ot = "Leve 10 Pingentes Umbrapele para o Meirinho Conacher na Prefeitura de Vila Plácida.", st = "Um inimigo de Ventobravo se instalou bem aos pés de Cristarrubra, na face leste das montanhas. O perverso vilão usa o poder Arcano para aterrorizar nossa cidade e nosso povo. É sob a alcunha de Morganth que ele conduz seus negócios maléficos.$b$bE agora, sob o domínio de Morganth, o clã Gnoll Umbrapele está fazendo o trabalho sujo dele. Conforme a Lei de Vila Plácida, a pena para ajudar um criminoso inimigo do Reino é a morte.$b$bEsses terríveis gnolls têm que morrer!$b$bMe traga 10 Pingentes Umbrapele e você será recompensad$Go:a;.", t = "A lei de Salomão"},
    [92] = {ot = "A Mestre-cuca Breanna de Vila Plácida quer 5 peças de carne dura de condor, 5 focinhos de grande goretusco e 5 porções de carne crocante de aranha.", st = "Nada me agradaria mais do que fazer um belo Gulache de Cristarrubra pra você, mas tem um probleminha. Durante a última revolta dos orcs, eu precisei alimentar uma brigada inteira das tropas de Ventobravo. Não sobrou nada na despensa. Se você me trouxer os ingredientes, preparo o prato com prazer.$b$bSão cinco peças de carne dura de condor, cinco focinhos de grande goretusco e cinco porções de carne crocante de aranha.", t = "Gulache de Cristarrubra"},
    [93] = {ot = "Colete 6 Pernas de Aranhas Pegajosas e leve para o Chef Goroba, na Vila Sombria.", st = "Vou te contar um segredinho — os bolinhos de caranguejo crepuscular são, na verdade, feitos de pernas de aranha! Eu sei que é um pouco nojento, mas os bolinhos ficam com um sabor pungente delicioso, além de darem um ótimo tira-gosto! Traga algumas pernas de aranha pegajosas que eu faço uns para você.$B$BOuvi dizer que as venaracnas dão muita carne. Os ninhos delas ficam a norte, no vale entre as montanhas e o rio. ", t = "Bolinhos de Caranguejo Crepuscular"},
    [94] = {ot = "Ponha o Glifo de Azora na Estátua de Leão perto da Torre de Ilgalar em Cristarrubra.", st = "Morganth, meu rival, é um mago cruel com grande poder que vive na Torre de Ilgalar, em Cristarrubra. Eu criei uma maneira de espionar o que ele faz, o Olho de Azora, e agora posso observar de longe.$B$BMas para perscrutar a mente dele... eu vou precisar de ajuda.$B$BSe você estiver dispost$Go:a;, leve meu Glifo de Azora até a Torre de Ilgalar. Ponha ele na Estátua de Leão ao lado da Torre.$B$BQuando você fizer isso, o Olho de Azora me permitirá ver os futuros planos de Morganth.", t = "Olho vigilante"},
    [95] = {ot = "Vá até a Fazenda do Noel e descubra o que foi enterrado atrás do velho cepo de madeira.", st = "Enquanto eu cuidava de uma das fazendas a sudeste... os Cavalgantes Negros da Trilha do Vento Morto invadiram minha fazenda e massacraram minha família!$B$BQuando voltei, notei uma figura sombria à espreita perto do celeiro, enterrando alguma coisa. Ele conseguiu fugir e eu não fui atrás porque estava no rastro dos Cavalgantes Negros. Então, nunca soube o que ele escondia.$B$BSe puder descobrir o que essa figura sombria enterrou lá, serei grato. O local do esconderijo fica atrás do velho cepo de madeira, perto do celeiro.", t = "A vingança de Noel"},
    [99] = {ot = "Leve 6 Grilhas de Lenhardente para Dalar Tessalba, no Sepulcro.", st = "Quanto mais aprendo sobre a magia de Arugal, maior o meu desprezo por aquele tolo desafortunado. Estou prestes a terminar minha pesquisa sobre o suposto remédio dele.$b$bMeu conhecimento estará completo quando descobrir qual é o encantamento que está causando um comportamento anômalo no Vilarejo Lenhardente. Durante o dia, os camponeses parecem ser humanos. Mas, assim que o sol se põe, os aldeões se transformam em Worgens Lunafúria.$b$bPreciso extrair energia das grilhas encantadas que Arugal usou neles. Traga-me seis Grilhas de Lenhardente encantadas, $n.", t = "A loucura de Arugal"},
    [101] = {ot = "Leve 10 Presas de Carniçal, 10 Dedos Descarnados e 5 Ampolas de Peçonha de Aranha para a Madame Eva na Vila Sombria.", st = "Um mal místico se espalha pela floresta, a necessidade de se proteger é inegável, $n. Os ventos sussurraram nos meus ouvidos que um grande perigo $Go:a; aguarda no futuro próximo.$b$bSe quiser se proteger, nobre $c, traga-me 10 presas de carniçal, 10 dedos descarnados e 5 ampolas de peçonha de aranha. Vou encantar um Totem do Castigo que vai retaliar todos que tentarem usar de violência contra você.", t = "O totem do castigo"},
    [102] = {ot = "Leve 8 Patas de Gnoll para o Capitão Danuvin no Morro da Sentinela.", st = "Ventobravo nos abandonou. Um vento rançoso sopra pelas planícies do Cerro Oeste. Aqui é a minha terra natal e eu não darei as costas a quem escolheu ficar. Nós, os fazendeiros de antigamente, vamos resistir.$b$bA sua tarefa, caso você a aceite, será patrulhar os campos do Cerro Oeste. Localize e mate esses gnolls malditos que, pelo que tudo indica, estão mancomunados com os bandidos das Minas Mortas. Traga-me oito patas de gnoll e eu $Go:a; recompensarei pela coragem.", t = "A patrulha do Cerro Oeste"},
    [103] = {ot = "Entregue 5 Frascos de Óleo para o Capitão Calvino no Farol de Cerro Oeste.", st = "A noite em que a família do faroleiro morreu foi terrível. Eu assisti, impotente, ao ataque liderado pelo Velho Olho-turvo. Mas o que está feito não se pode mudar. Agora, minha preocupação é com a vida dos marinheiros do Grande Oceano, cujos navios se aproximam dos perigosos rochedos da costa. Como não há vivalma para manter a chama do farol acesa, a responsabilidade recaiu sobre mim.$b$bAjude-me a manter a chama acesa trazendo cinco frascos de óleo dos monstros da colheita.", t = "A chama não pode apagar"},
    [104] = {ot = "Leve uma escama do Velho Olho-turvo para o Capitão Calvino no Farol de Cerro Oeste.", st = "Quando eu perdi a vida nesses rochedos, não fazia ideia do que a vida após a morte reservava para mim. Naquela noite, o Farol encontrava-se apagado, pois o Velho Olho-turvo afugentou a família do faroleiro, porém eles retornaram posteriormente e reacenderam o facho de luz. O Velho Olho-turvo então coagiu os murlocs de mente mais fraca a invadir novamente o farol com ele. Desta feita, a família não teve tanta sorte e pereceram todos diante dos meus olhos.$b$bMate o Velho Olho-turvo caso você o veja pela praia e traga-me uma de suas escamas. Garanto-lhe que minha recompensa será generosa.", t = "O mar não está para peixe"},
    [106] = {ot = "Entregue a Carta de Amor de Mabel para Tomasino Campedra.", st = "Ah, maldita sorte a minha! Meu coração pertence a Tomasino Campedra, mas nossas famílias se odeiam fervorosamente. Por isso não posso estar com ele, mesmo que meus olhos doam de vontade de ficar admirando aquele rosto lindo!$B$BPor favor, poderia entregar esta carta para ele, por mim? Ele costuma passar o tempo perto do rio a oeste daqui, depois da Fazenda dos Campedra.", t = "Jovens amantes"},
    [107] = {ot = "Leve o Bilhete da Vó Campedra para Durval Pilão.", st = "Aposto que Durval Pilão tem uma poção para unir jovens amantes!$B$BAqui, leve esse bilhete para ele. Ele está hospedado na Estalagem do Leão Orgulhoso em Vila d'Ouro.", t = "Bilhete para Durval"},
    [109] = {ot = "Fale com Miguel Mantoforte. Ele costuma ficar na torre de pedras do Morro da Sentinela, perto da estrada central do Cerro Oeste.", st = "Combate parece ter sido uma constante para você, $c. Se ainda não o fez, você deveria falar com Miguel Mantoforte. Ele chefia a Milícia do Povo, que busca proteger as fazendas do Cerro Oeste. Aposto que sua ajuda seria bem-vinda. Ele costuma ficar na torre de pedras do Morro da Sentinela, perto da estrada central do Cerro Oeste.", t = "Fale com Miguel Mantoforte"},
    [111] = {ot = "Fale com a Vovó Campedra.", st = "Por favor, $n, fale com minha avó. Se alguém pode pensar numa maneira de unir Mabel e eu, é ela.$B$BEla está na nossa casa, a leste daqui.", t = "Fale com a vovó"},
    [112] = {ot = "Leve 4 Folhas de Cristalga para Durval Pilão em Vila d'Ouro.", st = "Posso preparar um elixir de invisibilidade para Mabel. Assim ela poderá fugir dos Vinhedos dos Madruga e procurar Tomasino. Mas, para fazer o elixir, vou precisar de cristalgas.$B$BEmbora as algas cresçam no mar, às vezes os murlocs as recolhem. Veja se os murlocs do Lago de Cristal têm cristalgas. O Lago de Cristal fica a leste de Vila d'Ouro.", t = "Coletando alga"},
    [114] = {ot = "Leve o Elixir de Invisibilidade para Mabel Madruga.", st = "Leve esse elixir de invisibilidade para a jovem Mabel. Deve durar o suficiente para que ela se encontre com Tomasino.", t = "A fuga"},
    [115] = {ot = "Leve 3 Orbes da Meia-noite para o Oficial Marris em Vila Plácida.", st = "Os orcs Rocha Negra convocaram lança-sombras para ajudar no ataque a Cristarrubra, e eles trouxeram consigo artefatos de poder tenebroso: os orbes da meia-noite. Esses orbes vem desferindo golpes pesados contra os defensores de Cristarrubra, temos que removê-los do conflito urgentemente.$B$BRecolha os orbes dos Lança-sombras Rocha Negra mortos e traga para mim. Eu vou tratar de descartá-los, o mundo será um lugar bem melhor sem eles!", t = "Magia Sombria"},
    [118] = {ot = "Leve o Bilhete de Vervo para o Ferreiro Argus em Vila d'Ouro.", st = "Eu tenho usado tanto ferro para manter os Guardas de Ventobravo equipados, que não sobrou nem para fazer ferradura para os cavalos do estábulo!$B$BLeve esse bilhete para o Ferreiro Argus em Vila d'Ouro. Eu expliquei aí meu problema e fiz um pedido de ferraduras.", t = "O preço da ferradura"},
    [119] = {ot = "Fale novamente com Vervo Obom em Cristarrubra e entregue o Caixote de Ferraduras.", st = "Muito bem, eu vou mandar 50 ferraduras...$B$BAqui estão, encaixotadas e prontas para ir! Diga para o Vervo que foi um prazer fazer negócios, e não deixe ele esquecer de ler o bilhete que está no caixote!", t = "Fale novamente com Vervo"},
    [120] = {ot = "O Magistrado Salomão lhe entregou um relatório que deve ser entregue ao General Marcus Jonas em Ventobravo. O juiz quer que você fale novamente com ele assim que a entrega for feita.", st = "Estes são tempos difíceis, $c. A cidade está sob cerco constante. Sem reforços, nós certamente seremos derrotados. A mensagem que agora confio a você é da maior importância. Leve este relatório para o General Marcus Jonas de Ventobravo imediatamente. Uma vez que tiver realizado a entrega, traga qualquer notícia que tiver para mim, seja boa ou ruim.$b$bAgora, se apresse!", t = "Mensagem para Ventobravo"},
    [121] = {ot = "Leve a resposta do General Marcus Jonas para o Magistrado Salomão em Vila Plácida.", st = "Enquanto espero uma resposta do rei, eu quero que você leve esta carta para o Magistrado Salomão.$b$b$GDispensado:Dispensada;, $c!", t = "Mensagem para Ventobravo"},
    [122] = {ot = "Colete 6 Escamas de Ventre de Dragonete Negro e leve-as para Vervo Obom em Cristarrubra.", st = "Eu preciso de escamas do ventre de um filhote de dragonete negro para pagar as ferraduras que o Argus mandou de Vila d'Ouro. Se conseguir 6 delas, eu vou poder pagar o Argus... e guardar umas para fazer alguma coisa para você.$B$BOs filhotes de dragonete negro costumam voar lá pelo sul da Vila Plácida, mas gostam de perambular por aí. Você só precisa ficar de olho aberto e caçá-los quando os encontrar.", t = "Escamas do ventre"},
    [123] = {ot = "Fale com o Delegado Durão na Vila d'Ouro e lhe entregue a Escala do Coletor.", st = "O bilhete contém uma escala com os dias e horários em que uma pessoa – referida apenas como \"o Coletor\" – receberá um carregamento de ouro das minas da Floresta de Elwynn.$B$BPela escala, parece que o Coletor mora perto da Plantação de Abóboras dos Braga, na parte leste de Elwynn.$B$BIsso parece importante. Você deveria relatar isto ao Delegado Durão na Vila d'Ouro.", t = "O Coletor"},
    [124] = {ot = "Mate 10 Brutamontes de Cristarrubra e 8 Místicos de Cristarrubra e fale novamente com Vervo Obom.", st = "Como se orcs atacando não fosse suficiente! Agora tem gnolls brutamontes e místicos vagando ao norte do meu estábulo, roubando os cavalos que se perdem...$B$BSe você puder nos livrar desses gnolls, os meus cavalos e eu vamos ficar muito agradecidos.", t = "Gnoll que ladra também morde"},
    [125] = {ot = "O Encarregado Oslow quer que você recupere sua caixa de ferramentas no fundo do Lago Plácido.", st = "Eu estou precisando de uma mãozinha, $n. Com a cidade cercada, está sendo difícil conseguir suprimentos. As minhas ferramentas estavam vindo de carroça da Vila d'Ouro, mas a ponte foi destruída. Nós colocamos as ferramentas em um barco, mas os orcs acertaram ele com uma catapulta. Para o meu azar, a minha caixa de ferramentas foi parar no fundo do lago.$b$bRecupere a minha caixa de ferramentas, $n, e eu lhe darei uma boa recompensa.", t = "As ferramentas perdidas"},
    [126] = {ot = "Leve a Pata de Berrante para Vervo Obom na Vila Plácida.", st = "$n, os gnolls ainda estão por aí. Eu ouço o uivo quando eles caçam nas colinas acima da Vila Plácida. E um ladra mais alto do que o resto: Berrante, o líder.$B$BMate o Berrante e enxote o resto da matilha! Traga a pata dele como prova.$B$BMas tenha cuidado, esse gnoll não é o líder a toa. Ele não é um vira-lata qualquer...", t = "O gnoll de Vila Plácida"},
    [127] = {ot = "Leve 10 Peixes-lua Malhados para o Mestre de Doca Baren na Vila Plácida.", st = "O Lago Plácido é famoso pelo peixe-lua malhado. Eles estão sempre em demanda... e o meu estoque anda baixo!$B$BTraga 10 peixes e eu lhe darei algo em troca. Se não conseguir pescá-los... É capaz de você conseguir tomar os dos murlocs!", t = "O lago está para peixe"},
    [128] = {ot = "Mate 15 Campeões Rocha Negra e o Guarda Howe vai recompensar você na Vila Plácida.", st = "Precisamos destruir o Clã Rocha Negra. O inimigo invadiu nosso território. Essas montanhas estão sob direito soberano do Rei de Ventobravo. Nossas fontes informam que os líderes das unidades do Clã são denominados Campeões. Procure por eles no acampamento ao norte, a oeste da estrada para as Estepes Ardentes.$b$bO Magistrado Salomão quer que esses brutamontes pérfidos sejam eliminados. Mate 15 Campeões Rocha Negra e fale novamente comigo.", t = "Recompensa pelos Rocha Negra"},
    [129] = {ot = "Leve o Almoço do Florestan para o Guarda Florestan. Ele patrulha a estrada que leva à Vila Sombria.", st = "Me faz um favor? Fiz um almoço para o Guarda Florestan, mas ele saiu na patrulha... Ele é um guarda de Ventobravo forte, alto, que sabe se cuidar, mas para uma cidadã como eu é muito arriscado sair.$B$BEntão, se puder entregar o almoço por mim, eu darei a você um almoço de graça! Florestan faz patrulhas num trecho da estrada que leva à Floresta do Crepúsculo.", t = "Almoço grátis"},
    [130] = {ot = "Falar com a Herborista de Cristarrubra, Martie Jainrose.", st = "Antes de falar outra vez com a Darcy, será que você podia entregar umas flores a ela por mim? Passe na loja da herborista da Vila Plácida, na ponta oeste da vila.$B$BMas quando pegar as flores... não diga à Martie, a herborista, nem de quem nem para quem são.", t = "Visita à herborista"},
    [131] = {ot = "Dê para Darcy o Buquê de Narcisos.", st = "Aqui está o buquê. Escolhi Narcisos. São minhas favoritas!", t = "Narcisos para entrega"},
    [132] = {ot = "Leve o Bilhete do Wiley para Miguel Mantoforte no Cerro Oeste.", st = "O que vou revelar a você pode custar a minha vida. A gangue Défias está armando alguma coisa grande. A última coisa que fiquei sabendo é que estão em conluio com vários gnolls, kobolds e até goblins.$b$bLeve este bilhete para Mantoforte. Ele contém tudo que sei sobre isso.", t = "A Irmandade Défias"},
    [135] = {ot = "Leve o Bilhete do Wiley para Mathias Shaw em Ventobravo.", st = "O que será que o Wiley quis dizer ao mencionar os Alvanéis. Talvez tenha sido um ato falho. Será que a gangue dos Défias teria se envolvido com os Alvanéis? Só uma pessoa poderia dizer: Mathias Shaw, líder da AVIN. Mostre a ele o Bilhete do Wiley e veja se ele pode ajudar com esse mistério. Se tiver dificuldade em encontrá-lo, procure no Quartel da Cidade Velha.", t = "A Irmandade Défias"},
    [136] = {ot = "Encontre o baú do Capitão Albernaz e procure a próxima pista dentro dele.", st = "Se o campanha tá lendo isso, é porque o bom e velho Albernaz virou comida de peixe. Então o meu tesouro é seu, é só seguir os bizus. $b$bPrimeiro o campanha tem que achar o meu baú. Ele deve estar de agarra perto do naufrágio, na costa ocidental de Cerro Oeste, e já deve estar meio enterrado na areia. Tem um monte de navio a pique na costa, mas só uma âncora enferrujada. Encontre esse ferro e tá safo que vai achar o baú! O próximo bizu tá lá dentro.", t = "O tesouro escondido do Capitão Albernaz"},
    [138] = {ot = "Encontre o velho barril perto da chaminé em ruínas e procure a próxima pista dentro dele.", st = "A pista do tesouro diz: \"Bom trabalho, campanha! Agora levante ferro e pegue pra leste, pra riba dos penhascos, pela estrada. Fica de olho nas ruínas da chaminé do lado da estrada. O outro bizu tá ali, dentro de um barril\".", t = "O tesouro escondido do Capitão Albernaz"},
    [139] = {ot = "Procure a próxima pista dentro do garrafão vazio perto do moinho de vento.", st = "Ao olhar dentro do barril, você encontra outro fragmento de pergaminho. Neste, lê-se: \"A partir do barril, olhe pra norte. Vai batendo perna em linha reta como o voo do corvo até encontrar um garrafão vazio perto do moinho de vento abandonado na falésia. Se o campanha fuçar dentro do garrafão, vai achar o que procura\".", t = "O tesouro escondido do Capitão Albernaz"},
    [140] = {ot = "Encontre o baú do Capitão Albernaz e abra-o para receber sua recompensa.", st = "Como previsto, no fundo do velho garrafão havia uma pista para o tesouro do Albernaz. O papel cheira a uísque e a tinta está meio borrada, mas ainda é possível entender parte da mensagem: \"Agora que o campanha encontrou meu velho garrafão de uísque, o tesouro tá perto! É só olhar pra oeste, a partir do garrafão, e andar para a praia. Chegando na água, deixa de frescura, arregace as calças e vá em frente! Nade em direção ao oeste até topar com a ilha do tesouro!\"", t = "O tesouro escondido do Capitão Albernaz"},
    [141] = {ot = "Leve o Relatório do Shaw para Miguel Mantoforte no Cerro Oeste.", st = "A Guilda dos Alvanéis era controlada por Edwin VanCleef. VanCleef foi responsável pela reconstrução de Ventobravo depois que orcs a dizimaram na Primeira Guerra. Pelo visto, o tratamento que o Rei dispensou a VanCleef e seus homens após o término da reconstrução não lhes agradou. Isso explica um pouco as coisas.$b$bElaborei um relatório mais detalhado para o seu mestre no Cerro Oeste. Leve-o para ele imediatamente!", t = "A Irmandade Défias"},
    [142] = {ot = "Rastreie o Mensageiro Défias no Cerro Oeste e leve sua mensagem para Mantoforte.", st = "Precisamos descobrir a localização do esconderijo Défias. $n, meu batedor informa que um mensageiro Défias foi visto nas estradas entre o Arroio da Lua, a Pedreira Costa Dourada e a Mina Veiojango. Quero que você o capture. Se ele resistir, mate-o e traga a mensagem que ele carrega para mim.", t = "A Irmandade Défias"},
    [143] = {ot = "O Magistrado Salomão quer que você leve a súplica dele a Miguel Mantoforte em Cerro Oeste.", st = "Alguma coisa estranha aconteceu com o Exército de Ventobravo. Eles já deveriam ter chegado em grande número a essa altura. Mas o tempo é um luxo que não temos. Eu não vou ficar aqui assistindo o povo de Vila Plácida dar a própria vida sem tentar conseguir mais ajuda. Eu soube de uma milícia do povo se formando em Cerro Oeste.$b$bLeve esta súplica ao líder deles, Miguel Mantoforte. Talvez os homens de Mantoforte possam nos dar apoio aqui até que o Rei mande os reforços.", t = "Mensagem para Cerro Oeste"},
    [144] = {ot = "Fale novamente com o Magistrado Salomão e relate a resposta de Miguel Mantoforte.", st = "É doloroso para mim ler o bilhete do Magistrado Salomão. No entanto, está óbvio que ele não sabe da guerra aqui em Cerro Oeste, ou não esperaria ajuda da milícia. Se Ventobravo não tivesse nos abandonado também, não precisaríamos de da Milícia.$b$bLeve esta resposta a seu mestre na Cristarrubra, $c. Diga a ele o quando me pesa o coração a perda de tantos homens bons.", t = "Mensagem para Cerro Oeste"},
    [145] = {ot = "O Magistrado Salomão quer que você entregue uma carta ao senhor Ebanez na Vila Sombria.", st = "Preciso de sua ajuda novamente. Escrevi ao Lorde Ebanez solicitando que ele envie seus guardas, a Vigília Noturna, para ajudar na defesa da Vila Plácida. É essencial que essa mensagem chegue rápido a ele. Você precisa ser extremamente cautelos$go:a;. Ebanez é o prefeito da Vila Sombria, no coração da Floresta do Crepúsculo. Não se afaste da estrada.", t = "Mensagem para Vila Sombria"},
    [146] = {ot = "Fale novamente com o Magistrado Salomão e relate a resposta do senhor Ebanez.", st = "Se não conhecesse o Magistrado Salomão pessoalmente, diria que o homem pirou. Mandar a Vigília Noturna para Vila Plácida porque Ventobravo se recusa a ajudar? A Vigília Noturna foi formada porque Ventobravo nos abandonou quando essa magia nefasta se infiltrou nessas terras. Se eu enviasse a Vigília Noturna esta cidade seria tomada pelo mal antes mesmo que os guardas chegassem aos limites da floresta.$b$bLeve esta carta em resposta a seu mestre na Vila Plácida.", t = "Mensagem para Vila Sombria"},
    [147] = {ot = "Encontre e mate \"o Coletor\". Depois, entregue o Anel do Coletor para o Delegado Durão.", st = "Se o \"Coletor\" está pegando o ouro das nossas minas, então ele está roubando do reino! Faça o Coletor sentir o peso da justiça, além de me trazer o anel mencionado na escala de coleta que você me trouxe. Talvez possamos descobrir para quem o Coletor trabalha...$B$BA escala informa que o Coletor está escondido na Plantação de Abóboras dos Braga. Procure por ele lá.", t = "Perseguição implacável"},
    [148] = {ot = "Fale com Madame Eva.", st = "Ah, o que um pobre velho pode fazer? Preciso de suprimentos, mas a Vila Sombria fica tão longe e eu estou tão velho e fraco... Eu nunca sobreviveria à viagem.$B$BVocê poderia ir até lá e trazer para mim uma Linha de Cabelo de Fantasma? Madame Eva costuma ter dessas linhas em casa, na praça da Vila Sombria.", t = "Suprimentos da Vila Sombria"},
    [149] = {ot = "Leve o Pente Espectral para a Maria Cega.", st = "Há uma casa de fazenda abandonada, nas montanhas a sul da Vila Sombria, que é assombrada por um velho e melancólico fantasma chamado Maria Cega.$B$BPegue este pente espectral e peça à Maria Cega que penteie os cabelos. Em seguida, traga o pente para mim e catarei o cabelo de fantasma para fazer a linha que você quer.$B$BE cuidado, pois ultimamente criaturas sombrias têm espreitado a casa...", t = "Linha de Cabelo de Fantasma"},
    [150] = {ot = "Leve 8 Barbatanas de Murloc para o Mestre de Doca Baren em Vila Plácida.", st = "Os murlocs estão virando uma pedra no sapato. Grandes grupos de homens-peixe andam lançando âncora ao longo das margens do Lago Plácido e pescando como se não houvesse amanhã! Precisamos nos livrar deles antes que eles comam todos os peixes do lago!$B$BCace os murlocs! Traga-me oito barbatanas deles e talvez eu tenha alguma coisa para lhe dar...", t = "Caçadores de murlocs"},
    [151] = {ot = "Vera Taturana quer que você leve 8 Punhados de Aveia para ela em Cerro Oeste.", st = "Pobre Velha Brancurinha! A bichinha está tão cansada depois de tanto que a fizemos trabalhar. Eu a alimentei antes de sairmos da fazenda, mas não estávamos esperando que a carroça quebrasse na nossa mão. Se você puder trazer alguns punhados de aveia dos campos para ela, eu agradeceria muito.$B$BAposto que você vai achar nas fazendas de Cerro Oeste, se conseguir evitar aquelas máquinas horríveis que dominaram tudo. Há várias fazendas sudoeste daqui.", t = "Pobre Velha Brancurinha"},
    [152] = {ot = "Mate 7 Caçamarés, 7 Guerreiros, 7 Oráculos e 7 Correcostas e fale novamente om o Capitão Calvino no Farol de Cerro Oeste.", st = "Você provavelmente já reparou que há vários navios naufragados ao longo da costa. O Grande Oceano é deveras traiçoeiro. Precisamos manter a costa de Cerro Oeste livre, para que os marinheiros que chegarem à praia fiquem em segurança. Os murlocs dão problema demais.$b$bMate 7 Caçamarés, 7 Guerreiros, 7 Oráculos e 7 Correcostas, e eu farei com que você seja devidamente $Grecompensado:recompensada;.", t = "Há perigo na costa"},
    [153] = {ot = "Leve 15 Bandanas Vermelhas de Couro para o Batedor Galiaan no Morro da Sentinela.", st = "O Front dos Défias está sempre mudando. Já faz bastante tempo que eu acompanho os movimentos deles. Vale dizer que dei um jeito de usar as bandanas vermelhas de couro para rastrear vários membros da gangue.$b$bTraga 15 bandanas para mim que vou saber lhe recompensar bem.", t = "Bandanas vermelhas de couro"},
    [154] = {ot = "Devolva o Pente de Fantasma para Madame Eva na Vila Sombria.", st = "NÃO!!!!!$B$BLeve o pente para bem longe de mim!$B$BEu sou um monstro, e nunca mais alguém vai me achar bonita de novo!", t = "Devolva o pente"},
    [155] = {ot = "Escolte o Traidor Défias ao esconderijo secreto da Irmandade Défias. Quando o Traidor Défias mostrar onde VanCleef e seus comparsas estão escondidos, retorne a Miguel Mantoforte com a informação.", st = "O que deu na cabeça do Mantoforte para mandar $gum:uma; $r esquelétic$go:a; como você para me proteger? Bom, se não tem tu, vai tu mesmo. $b$bSabe como é, né? Você me dá cobertura e eu te levo ao esconderijo do Défias. Mas fica perto de mim. A gangue do Défias quer minha cabeça numa bandeja. Se me virem com você, vão querer me matar.$b$bReúna uns amigos e me avise quando estiver pront$go:a;.", t = "A Irmandade Défias"},
    [156] = {ot = "Colete 8 Flores do Mal e entregue-as ao Taberneiro Oseias em Vila Sombria.", st = "Se você me trouxer um maço de flores do mal, eu faço uma partida de suco de zumbi.$B$BAs flores do mal crescem em lugares estranhos. Fiquei sabendo que dá para encontrar algumas dentro do crânio de horrores descarnados e malévolos descarnados... mas nunca fui lá conferir, é claro!$B$BO Cemitério de Monte Corvo e os Jardins da Paz estão cheinhos de descarnados. Você pode até dar cabo de alguns enquanto procura as flores do mal. A Vila Sombria agradece.", t = "Coleta de flores do mal"},
    [157] = {ot = "Leve a Linha de Cabelo de Fantasma para Abercrombie na cabana dele, que fica ao norte do Cemitério de Monte Corvo.", st = "Aqui está a linha, $n. Ela tem mil e uma utilidades, desde prender espíritos do mal até dar vida a objetos inanimados costurados com ela.", t = "Entregue a linha"},
    [158] = {ot = "Fale com o Taberneiro Oseias.", st = "Preciso de uma garrafa de uma certa bebida — suco de zumbi. O Taberneiro Oseias, da Taberna Corvo Escarlate de Vila Sombria, deve ter em estoque.$B$BE, por favor, corra, $n. As noites estão frias, e eu preciso dessa bebida para botar fogo nas minhas veias de novo!", t = "Suco de zumbi"},
    [159] = {ot = "Leve o Suco de Zumbi para o Abercrombie na cabana dele.", st = "Está aqui o suco de zumbi...$B$B...E tenha cuidado com isso. É forte o suficiente para levantar os mortos!", t = "Alguém pediu um suco?"},
    [161] = {ot = "O Engenheiro-chefe Vedaçude quer que você leve o pó com cheiro estranho para Ashlan Risadura, o perito em explosivos, em Dun Modr.", st = "Se minhas suspeitas tiverem razão de ser, isso é uma espécie de pó explosivo. É bom um perito em explosivos analisar, pra gente saber com o que estamos lidando. O Ashlan Risadura tá com o regimento que protege Dun Modr e a Ponte Thandol. Preciso que tu faça uma jornada urgente e perigosa, $n.$b$bVai até o Portão de Algaz, segue a estrada que cruza o Pantanal e procura o Risadura em Dun Modr. Vou te dar um conselho: fica na estrada e não para por nada!", t = "Uma ameaça sombria à espreita"},
    [163] = {ot = "Descubra o que está assombrando o Monte Corvo.", st = "Tem alguma coisa errada no Monte Corvo, $n. O Petrônio jura que alguém, ou alguma coisa, está assombrando o lugar. Ele viu sombras se mexendo duas noites seguidas, e antes disso, ele disse que viu uma janela com a luz acesa.$b$bSe você se preocupa mesmo com a segurança da Floresta do Crepúsculo, descubra que monstro está assombrando o Monte Corvo.", t = "Monte Corvo"},
    [164] = {ot = "Entregue os suprimentos a Noel.", st = "Você conhece o Noel? Aquele sim é um homem que trabalha em prol da Luz! Ele fica com os seguidores num acampamento na margem noroeste da Floresta do Crepúsculo.$b$bInfelizmente, por serem muito poucos, eles não podem mandar ninguém para buscar suprimentos na cidade. Você pode levar esses suprimentos para eles?", t = "Entrega para Noel"},
    [165] = {ot = "Confira se o velho que vive na choupana perto do cemitério do Monte Corvo está bem.", st = "Um senhor vinha sempre à cidade comprar suprimentos, mas já faz algum tempo que eu não o vejo. Ele vive numa choupana de frente para o cemitério do Monte Corvo, se me lembro corretamente. Talvez fosse uma boa ideia você ir até lá ver se está tudo bem.", t = "O eremita"},
    [166] = {ot = "Mate Edwin VanCleef e leve a cabeça dele para Miguel Mantoforte.", st = "Falta apenas uma tarefa para você cumprir. Edwin VanCleef deve morrer. Me entristece condenar qualquer pessoa à morte, mas é para o bem maior do povo do Cerro Oeste que VanCleef seja tirado de circulação de uma vez por todas. Traga a cabeça do vilão para mim quando estiver feito.", t = "A Irmandade Défias"},
    [167] = {ot = "Leve a Insígnia da Liga dos Exploradores do Encarregado Urtigão para Wilder Urtigão em Ventobravo.", st = "A gente tava numa grande mina no Cerro Oeste, escondido debaixo de um celeiro no Arroio da Lua. Não sei de que buraco aqueles ladrõezinhos duma figa saíram. Pois então, como eu dizia, o túnel da mina desabou em cima da gente. Eu escapei, mas os outros... não faço ideia do que aconteceu com eles.$b$bDe repente tu te sai melhor nisso que eu. Se puder procurar meu irmão, eu agradeço muito. Ele tava com a Insígnia da Liga dos Exploradores. Se não conseguir achar ele, a insígnia já ia me dar uma paz de espírito.", t = "Meu irmão..."},
    [168] = {ot = "Recupere 4 Carteiras do Sindicato dos Mineradores e leve-as para Wilder Urtigão em Ventobravo.", st = "Muitos dos meus amigos sucumbiram naquele dia horrível, quando a mina desabou. Se, durante tuas aventuras, tu porventura passar por aquele lado da mina, no Arroio da Lua, vê se acha alguma coisa pra identificar eles. Se achar alguma Carteira do Sindicato dos Mineradores, traz pra mim. Assim as famílias deles vão ter alguma chance de superar esse acidente terrível.", t = "Lembranças dos que se foram"},
    [169] = {ot = "Mate Gath'Ilzogg e leve a cabeça dele para o Magistrado Salomão na Vila Plácida para receber a recompensa.", st = "Procura-se: Gath'Ilzogg, mandante dos ataques dos Rocha Negra à Bastilha Mirante de Pedra e dos raides contra o povoado de Vila Plácida. $b$bGath'Ilzogg é extremamente perigoso. Relatos dão conta de que ele está entocado na fortaleza recém-conquistada planejando novos crimes contra a humanidade a serem perpetrados pelo Clã Rocha Negra. A infestação dos orcs deve ser suprimida a qualquer custo. Uma vultosa recompensa será concedida à corajosa alma que trouxer a cabeça de Gath'Ilzogg ao Magistrado Salomão.", t = "PROCURA-SE: Gath'Ilzogg"},
    [170] = {ot = "Balir Gelomarra quer que você mate 6 Troggs Pedraqueixo e 6 Troggs Pedraqueixo Parrudos.", st = "Espero que tu tenha vindo dar uma mão pra gente, $c. Depois do último ataque dos troggs, qualquer ajuda é bem-vinda.$b$bOuvi dizer que esses topetudos têm aparecido em todo o vizindário, e o Vale Cristálgida não é exceção. Eles foram vistos de cima a baixo nas colinas a sudeste e perto do lago congelado.$b$bE não para aí. Umas noitinhas atrás, eles atacaram e causaram um estafaréu no nosso acampamento a oeste!$b$bA gente tá meio precisado aqui, jovem. Um braço forte pra rechaçar esses troggs viria a calhar.", t = "Uma nova ameaça"},
    [174] = {ot = "Vitório Prismado, da Vila Sombria, quer que você lhe providencie um tubo de bronze.", st = "O Roda, um gnomo amigo meu, prometeu me ajudar a construir um dispositivo que me permitirá observar as estrelas. Há uma verdade, para além da magia, capaz de explicar a estranha transformação da floresta.$b$bTraga-me um tubo de bronze feito por um engenheiro habilidoso. Esse é o primeiro passo segundo o diagrama do Roda.", t = "Ora (direis) ouvir estrelas!"},
    [175] = {ot = "Encontre Maria e convença-a a fornecer uma superfície refletora para o projeto de Vitório.", st = "Segundo o diagrama do Roda, o que eu preciso arranjar agora é um jeito de refletir a luz. Eu me lembro de uma tal de Maria que ficou conhecida por circular por aí sempre carregando um espelho. Você poderia encontrá-la e ver se ela nos empresta esse espelho? Acho que ela morava no sul da Floresta do Crepúsculo...", t = "Ora (direis) ouvir estrelas!"},
    [176] = {ot = "Mate o gnoll Hogger e leve sua Enorme Garra de Gnoll para o Delegado Durão.", st = "Procura-se: Hogger$B$BHogger, um gnoll enorme, está espreitando os bosques na parte sudoeste de Elwynn. Até agora, ele escapou de todas as emboscadas que armamos para apanhá-lo.$B$BO Exército de Ventobravo está oferecendo uma recompensa generosa pela captura desse Gnoll. Para coletar a recompensa, os caçadores de recompensa interessados devem apresentar provas da queda de Hogger ao Delegado Durão em Vila d'Ouro.", t = "PROCURA-SE: \"Hogger\""},
    [177] = {ot = "Recupere o Espelho de Maria do Carniçal Insano e entregue-o a Vitório na Vila Sombria.", st = "Aquele espelho era um dos meus mais preciosos tesouros até... o incidente. Depois do acontecido, eu o joguei fora atrás do celeiro. Um carniçal maluco costumava perambular por lá. Talvez ele tenha pegado o espelho. Dizem por aí que aquela criatura do demônio mora no Cemitério Jardins da Paz.", t = "Ora (direis) ouvir estrelas!"},
    [179] = {ot = "Sten Braçoforte quer 8 pedaços de Carne Dura de Lobo.", st = "Mas o que é que nós temos aqui? Parece que tu precisa é de alguma coisa para esquentar a mão, não?$b$bMas eu te conto o que é que ajuda: um bom par de luva quente. E, buenacho como sou, eu te arreglo um feliz da vida. Mas tem uma condição.$b$bTu precisa ir e me conseguir umas carnes de lobo. Tu me traz carne de lobo e eu cuido de que nenhum dedo teu caia de frio. Tás contratado?", t = "Provedores enânicos"},
    [180] = {ot = "Mate o Tenente Mordente e leve a pata dele para o Magistrado Salomão em Vila Plácida.", st = "Procura-se: Tenente Mordente.$b$bLíder conhecido do clã de gnolls Umbrapele, trabalha para Morganth, inimigo do condado e do reino. Por mandato do Magistrado Salomão, este vil traidor de Ventobravo é procurado morto. Apresente a pata dele ao Magistrado como prova de sua morte.", t = "PROCURA-SE: Tenente Mordente"},
    [182] = {ot = "Grolin Barbabranca quer que você mate 14 Jovens Trolls Jubafria.", st = "Eu e meu irmão Senir fomos mandados a partes diferentes de Dun Morogh para investigar a ameaça trólica. O Senado já está ocupado demais com os troggs e não precisa de ainda mais aborrecimentos.$b$bPelo que vi, acho que os trolls não estão bem situados aqui no Vale Cristálgida — no geral, estão na caverna mais ao sul. Eu diria que um exército não será necessário, alguns combatentes fortes já dão conta do recado.$b$bQue tal ajudar na empreitada? Tenho autonomia para oferecer uma boa compensação em troca da ajuda.", t = "A caverna dos trolls"},
    [183] = {ot = "Talin Olhobom quer que você mate 12 Rochetuscos Pequenos.", st = "Nada como um belo dia caçando javalis, né?$b$bPena que aqui, no Vale Cristálgida, tem tanto rochetusco que a coisa quase perde a graça. Nem precisamos fazer os bichos atacarem, eles já estão sempre furiosos e prontos para a briga. Na verdade, o número de javalis aumentou tanto nos últimos tempos que a minha caça diária está ficando cada vez mais perigosa.$b$bIndo direto ao ponto, se você me ajudar a matar uns rochetuscos, eu ficarei muito grato.", t = "Caçando javali"},
    [184] = {ot = "Leve a Escritura do Taturana para o Fazendeiro Taturana.", st = "Esta é a escritura de um trecho de terreno cultivável em Cerro Oeste. Está assinada por um tal de Teodoro Taturana e sua esposa, Vera. No verso da escritura, tem algumas palavras escritas às pressas:$B$B\"Nós apertamos o Taturana e conseguimos a escritura dele. Achamos que seria útil se você forjasse uma igual para sua casa.$B$BOs Taturana não vão causar problema. Da última vez em que os vi, eles estavam tentando sair de Cerro Oeste, mas estavam parados por conta de uma carroça quebrada.\"$B$BOs Taturana com certeza vão querer a escritura de volta...", t = "Escritura do Taturana"},
    [199] = {ot = "Fale novamente com o Engenheiro-chefe Vedaçude e mostre a ele a pista que você descobriu.", st = "Pegue uma amostra do pó com cheiro estranho.", t = "Uma ameaça sombria à espreita"},
    [214] = {ot = "A Batedora Riell, da Torre do Morro da Sentinela, quer que você lhe traga 10 Bandanas de Seda Vermelha.", st = "Não é segredo que a marca registrada da gangue Défias é a bandana vermelha. Mas descobrimos que o material da bandana simboliza a patente do membro.$b$bDito isto, quero que você elimine o maior número possível membros do alto escalão dos Défias. Os membros de maior patente podem ser encontrados, sem falta, no esconderijo secreto de VanCleef. Quando terminar, traga-me 10 bandanas de seda vermelha como prova de suas mortes, e eu lhe darei uma recompensa. Boa sorte, $n.", t = "Bandana de seda vermelha"},
    [216] = {ot = "Mate 12 Vingadores Pelocardo e 12 Xamãs Pelocardo; a maioria se localiza a leste da Praia de Zoram, na Aldeia dos Pelocardo. Uma vez concluído, fale novamente com Karang Amakkar no Assentamento Zoram'gar, Vale Gris.", st = "Os pelursos Pelocardo são uma ameaça à nossa expansão! A Aldeia dos Pelocardo, a leste daqui, está bloqueando o caminho entre nós e o Posto Machadada. A trilha contorna a vila de Astranaar, e, se não a controlarmos, daremos de bandeja mais uma via de expansão para a Aliança.$B$B$n, não podemos permitir... uma pedra no caminho da nossa expansão!$B$BAvance até a Aldeia dos Pelocardo e reduza o contingente deles. Você vai receber uma recompensa por cumprir a tarefa, mas o mais importante é que você vai cumprir o seu dever perante a Horda!", t = "No meio do caminho tinha uma pedra... e um pelocardo..."},
    [217] = {ot = "Mate o líder dos troggs, Gromug, e seus dois guardas, Triscadente e Brigão, e então fale novamente com o Capitão Balbúrdia na torre de guarda sul.", st = "$n, nossos batedores identificaram o líder dessa recente incursão de troggs. Parece que essas criaturas de Loch Modan estão sendo lideradas por um chefe conhecido como Gromug. Mas Gromug está fortemente protegido. Dois dos seus maiores guardas de elite, Triscadente e Brigão, nunca saem do lado dele.$b$bCaso você se sinta $Gmerecedor:merecedora; de tal encargo, $n, quero que você lidere a missão para assassinar Gromug e seus dois brutamontes. Com a liderança dos troggs morta, podemos ter uma chance de forçar aqueles monstros a voltar para a terra.", t = "Em defesa das terras do Rei"},
    [218] = {ot = "Grolin Barbabranca quer que você mate Grik'nir, o Frio, e recupere seu diário.", st = "Meu diário! Eles o levaram para a caverna. O sujeito que o pegou... era um brutamontes enorme com marcas estranhas na pele e no rosto. Eu não consegui ver muita coisa além disso.$b$bJá que você teve sorte com os trolls, será que poderia tentar recuperar o meu diário?", t = "O diário roubado"},
    [219] = {ot = "Proteja o Cabo Keeshan em sua jornada de volta a Cristarrubra.", st = "Finalmente, amigos da Aliança!$b$bAjude-me... por favor.... $b$bA última coisa de que me lembro é que aqueles orcs cruéis sobrepujaram o nosso regimento. A maioria dos homens foi morta. Eu levei um golpe forte na cabeça e apaguei. Agora estou preso nesta caverna. Ajude-me, estou muito ferido.$b$bVou precisar de ajuda para voltar à cidade... por favor... Você é a minha última esperança...", t = "Desaparecidos em ação"},
    [220] = {ot = "Leve a Ampola da Mais Pura Água para Islen Vidente da Água nos Sertões.", st = "Islen terá mais uma tarefa para você antes de recompensá-$Glo:la; com seu próximo totem. A ampola de água que eu lhe dei é necessário para qualquer que seja a tarefa. $B$BAgora vá e encontre-a. Tornaremos a nos ver algum dia.", t = "O clamor da Água"},
    [224] = {ot = "O Montanhista Sapatorro, da torre de guarda sul, quer que você mate 10 Troggs Lascapedra e 10 Batedores Lascapedra.", st = "Temos que proteger o Loch, $n! Com tantas tropas lutando bravamente em frentes longínquas, nós ficamos sobrecarregados com a defesa de casa. Tem troggs surgindo de cada fenda na rocha! Essa infestação é a maior ameaça a Altaforja hoje. Aqueles mutantes nojentos têm que ser destruídos.$b$bPrecisamos da sua ajuda, $Gbravo aventureiro:brava aventureira;, para dar fim a esse perigo. Mate 10 troggs Lascapedra e 10 batedores Lascapedra volte aqui.", t = "Em defesa das terras do Rei"},
    [226] = {ot = "Mate 12 Lobos Hediondos Famintos e 8 Lobos Hediondos Raivosos e fale novamente com Lars no Acampamento do Noel, na fronteira oeste da Floresta do Crepúsculo.", st = "Noel e eu temos dias perigosos pela frente, com o Necromante a leste e tudo o mais. E, aqui sozinhos como estamos, temos que caçar nossa própria comida. Parece que, toda vez que estou voltando para o acampamento trazendo carne, lobos famintos ou raivosos saem da floresta querendo uma mordida. Nem preciso dizer que viver aqui é um trabalho perigoso!$B$BMas se você puder nos livrar de alguns desses lobos, vai facilitar a nossa vida. Eles costumam rondar o norte e o leste daqui, perto do rio.", t = "Lobos nos nossos calcanhares"},
    [230] = {ot = "Leve o Livro da Fazenda de Noel para Noel.", st = "Cavando o monte, você encontra um pequeno livro sujo de terra.$B$BO livro não tem título, mas... contém informações que o Noel gostaria de saber.", t = "Acampamento do Noel"},
    [233] = {ot = "Entregue a Pilha de Cartas para Talin Olhobom.", st = "Hum, será que você poderia me fazer um favor, $grapaz:moça;? Eu recebi uma pilha de cartas hoje, mas não tenho tempo para encaminhá-las.$b$bElas são todas endereçadas a Talin Olhobom. Você pode encontrá-lo a oeste, na estrada. Ele montou acampamento ao lado do lago congelado.$b$bO que me diz?", t = "Correio de Vale Cristálgida"},
    [234] = {ot = "Entregue a Carta para Grolin Barbabranca.", st = "Se me lembro corretamente, o acampamento do Grolin fica seguindo a estrada para sudeste. Sem dúvida, ele vai estar ansioso para receber a carta dele.", t = "Correio de Vale Cristálgida"},
    [237] = {ot = "O Montanhista Cascalhaça, da torre de guarda sul, quer que você mate 10 Batecrânios Lascapedra e 10 Videntes Lascapedra e fale novamente com ele.", st = "O Montanhista Sapatorro foi só elogios em relação a você, $r. Por esse motivo, eu vou lhe confiar uma missão da maior importância. Precisamos manter a pressão sobre as forças invasoras de troggs até que os nossos irmãos anões retornem do front da Aliança.$b$bVá para as colinas ao sul e mate 10 Batecrânios Lascapedra e 10 Videntes Lascapedra. Seus ataques vão nos dar algum tempo. Reporte-se quando sua missão estiver concluída.", t = "Em defesa das terras do Rei"},
    [239] = {ot = "Vá até a Guarnição da Ribeira d'Oeste e fale com o Delegado Ranieri.", st = "A Guarnição na nossa fronteira ocidental informa que tem havido aumento da atividade de gnolls e ladrões. Eles estão requisitando mais soldados de Ventobravo... mas não temos ninguém para enviar!$B$BSe você puder ajudar, viria em boa hora. Fale com o Delegado Ranieri, na Guarnição da Ribeira d'Oeste, e veja o que ele quer.$B$BA Guarnição fica seguindo a estrada, na direção oeste. É só atravessar a ponte que passa pelo córrego. A Guarnição fica logo à direita.", t = "Ribeira d'Oeste precisa de ajuda!"},
    [240] = {ot = "Fale novamente com Medrisco levando Bolinhos de Caranguejo Crepuscular.", st = "Aqui está: bolinhos de caranguejo crepuscular à la Goroba!", t = "Fale novamente com Medrisco"},
    [244] = {ot = "Fale com o Subdelegado David.", st = "Salve, $c. Estou encarregado de patrulhar este trecho da estrada. Embora a estrada esteja segura por ora, eu vi acampamentos de gnolls ao norte e a leste daqui.$B$BA Vila Plácida deve ser avisada sobre as forças dos gnolls que estão se reunindo! Reporte-se ao Subdelegado David na Vila Plácida e conte a ele sobre os gnolls. Faça isso, e tenho certeza de que Feldon lhe oferecerá o salário de um batedor.$B$BFeldon costuma inspecionar a área ao sul da ponte para a Vila Plácida.", t = "Invasão de gnolls"},
    [245] = {ot = "Mate 15 Veneracnas Pigmeias, e depois apresente-se novamente ao Vigia Gouveia na Floresta do Crepúsculo.", st = "Salve, $c. Talvez você tenha visto aquelas aranhas que tomaram conta da fronteira ocidental. Essas ameaças de oito patas são demais para nós, e o Comandante não tem homens suficientes para atuar tão longe de Vila Sombria.$b$bDetesto lhe pedir isso, mas você me parece capaz de lidar com elas. Não posso lhe prometer nada de grande valor, mas posso recompensá-l$Go:a; se puder ajudar a erradicar esses pragas imundas.$b$bAh, um conselho: procure evitar o veneno delas, se puder.", t = "Ameaças de oito patas"},
    [246] = {ot = "Mate 10 Mestiços de Cristarrubra e 6 Caçadores Ilegais de Cristarrubra, e então apresente-se novamente ao Subdelegado David em Vila Plácida.", st = "Não temos homens sobrando, mas é preciso fazer algo com relação aos gnolls que você relatou.$B$BVasculhe o sul de Cristarrubra à procura de gnolls. Persiga-os, mate aqueles que puder e volte para me informar quantos são e a ameaça que representam. Você vai encontrar esses gnolls acampados ao longo da estrada sul de Cristarrubra.$B$BFaça isso pelo Exército de Ventobravo, $n, e você será recompensad$Go:a;.", t = "Avaliando a ameaça"},
    [247] = {t = "Caçada do Vale Gris terminada"},
    [248] = {ot = "Suba ao topo da torre de vigia intacta ao lado da Bastilha Mirante de Pedra.$B$BEncontre um recipiente adequado para colocar o Glifo de Azora.", st = "Tenho observado a Torre de Ilgalar, e percebo que Morganth está em conflito com os orcs na Bastilha Mirante de Pedra. Não sei o motivo por trás dessa disputa, mas você pode me ajudar a desvendar o mistério.$B$BPegue outro Glifo de Azora, então vá para o topo da torre de vigia intacta ao lado da Bastilha.$B$BEncontre um objeto adequado em que colocar o Glifo. Um baú ou um jarro — algum lugar onde o glifo não seja notado — servirá ao meu propósito.", t = "Vendo além"},
    [250] = {ot = "Investigue a área próxima à rampa leste do Dique e dê ao Engenheiro-chefe Vedaçude uma pista que possa indicar o que os Anões Ferro Negro estão tramando.", st = "Ainda bem que tem gente que se preocupa com a situação do Dique. Primeiro destroem a Ponte Thandol, agora a pilhagem de Dun Modr! O Dique é o próximo alvo dos Ferro Negro, isso é mais certo que geada no pastiçal quando inverna. A maior parte do destacamento de segurança daqui foi mandado pro Front da Aliança, incluindo meu melhor inspetor.$b$bÉ por isso que eu preciso de ti, $n. Eu avistei uns Sapadores Ferro Negro cheirando não sei o que perto da rampa leste do Dique. Vai lá campear e traz alguma pista.", t = "Uma ameaça sombria à espreita"},
    [255] = {ot = "O Magistrado Grã-narina de Thelsamar contratou você para matar 4 Ogros Mo'grosh, 4 Brutamontes Mo'grosh e 4 Impositores Mo'grosh.", st = "Pra tu vê, dois meses só para ouvir de Altaforja que receberemos um punhado de soldados para a nossa defesa, e mais dois meses até eles chegarem! Não bastasse nossa cidade estar desprotegida, a escavação e a represa — a represa, tchê! — também estão abertas a ataques.$b$bBah, não tenho escolha, ao que parece. Vou precisar contratar ajuda.$b$bE tu? Parece bem aprumad$Go:a;, $c. Um grupo de ogros montou acampamento a nordeste do lago. Talvez tu possa arrebanhar alguns outros para ajudar a pelear e eliminar a ameaça à nossa cidade?", t = "Mercenários"},
    [257] = {ot = "Mate 6 Urubus Montanheses e fale novamente com Dário, o Novato, no Pavilhão dos Andarilhos, dentro de 15 minutos.", st = "Você acredita mesmo que pode competir em inteligência com Dário, o Ousado, hein? Acho que não! É claro que tem todo o direito de tentar. Vou lhe propor um desafio que deve estar acima de suas habilidades, então não se sinta mal se não estiver à altura.$b$bUm bando de urubus aninhou-se aqui em Loch Modan. Por que não tenta se livrar de alguns desses bichos? Vamos fazer assim, se cumprir meu desafio em quinze minutos, eu lhe darei meu arco ou minha arma.$b$b<Dário $Go:a; encara com desdém.>$b$bParece que você não tem muito a perder, de qualquer maneira.", t = "Modéstia de Caçador"},
    [258] = {ot = "Mate 5 Javalis Montanheses Anciãos e fale novamente com Dário, o Novato, no Pavilhão dos Andarilhos, dentro de 12 minutos.", st = "$nath, é isso? Vejo que está explodindo de orgulho por ter completado o primeiro teste, não é mesmo? Como lhe disse antes, não foi nada demais.$b$bVocê deveria experimentar caçar javali. Confie em mim, isso aqui não se parece em nada com a caça ao javali do Vale Cristálgida, então é melhor tomar bastante cuidado. Vou lhe dar apenas doze minutos desta vez.$b$bNão se sinta mal se falhar. Sou capaz de lhe dar minha roupa do corpo se você conseguir!$b$bJá lhe contei a história de como arranjei minha famosa cicatriz? Não? Foi há dois anos...", t = "Desafio de caçador"},
    [262] = {ot = "Leve o livro que encontrou na fazenda de Noel e mostre-o aos cidadãos da Vila Sombria.", st = "Preciso saber quem era o vulto que estava se esgueirando nas sombras na noite em que minha família foi assassinada!$B$BPor favor, $n, você já demonstrou sua astúcia. Encontre aquela figura sombria, por favor. Preciso descobrir seus segredos!$B$BNão tenho nenhuma pista que você já não saiba, mas tome... leve o livro que você encontrou na minha fazenda. Talvez alguém na cidade consiga ligar o livro ao dono.", t = "O vulto sombrio"},
    [263] = {ot = "Montanhista Batemuro na torre de vigia sul quer que você mate 10 Xamãs Lascapedra and 10 Quebraossos Lascapedra.", st = "Os Montanhistas me contaram que você é muito competente e $Gcorajoso:corajosa;, $n. $GUm:Uma; $r como você seria muito útil por aqui. Os reservistas foram convocados para o front e ficamos desguarnecidos. Mas agora que temos $Gum:uma; $c $Gveterano:veterana; conosco, vamos ver o que podemos fazer.$b$bSaia em campo e mate 10 Xamãs Lascapedra e 10 Quebraossos Lascapedra. Vamos ver se você faz jus à sua reputação, $Gmatador:matadora; de troggs.", t = "Em defesa das terras do Rei"},
    [264] = {ot = "Coloque o Pingente da Clarice no Túmulo de Yuriv em Pinhaprata.", st = "Cachorro! Me deixar por causa dessa cruzada maldita. Tudo porque \"a Luz é o que temos de mais importante contra a ameaça que os mortos-vivos representam.\"$B$BE as crianças?! E EU?! Esperei sentada por ele, noite após noite, pacientemente... mas a porcaria do dever sempre veio primeiro!$B$BÉ isso aí, $n, veja bem o que você ganha com a \"justiça\"! Agora ele está morto e aquilo contra o que ele lutou toda a vida é o meu fardo!$B$BLeve esse lixo para a tumba dele lá no Sepulcro. Não quero ter mais nada a ver com isso... nem com ele!", t = "Até que a morte nos separe"},
    [265] = {ot = "Tente encontrar outras pistas sobre o vulto sombrio entre os aldeões.", st = "Aqui está o seu livro de volta, $n, e eu lhe desejo sorte na busca. Se você perguntar a outras pessoas na cidade, talvez alguém tenha pistas melhores para te dar.$B$BEnquanto isso, eu tenho mais uma para você: embora o autor deste livro seja um forasteiro em Vila Sombria, o livro em si foi comprado aqui.", t = "A busca sombria continua"},
    [266] = {ot = "Procure pistas sobre o vulto sombrio na estalagem", st = "Aqui está o seu livro e boa sorte com a investigação.$B$BAcho que pode ser uma boa ideia perguntar na estalagem. Se a pessoa que você procura passou algum tempo aqui na cidade, talvez alguém na estalagem possa ajudar.", t = "Perguntas na estalagem"},
    [267] = {ot = "Leve 8 Dentes de Pedra de Trogg para o Capitão Balbúrdia na torre de vigia sul.", st = "$C, não sei se você já soube da ameaça trogg que paira sobre as terras enânicas. Os Reservistas de Altaforja foram enviados ao front da Aliança. Com isso, nos restou apenas uma fração das tropas necessárias para manter a segurança destas terras. Meu regimento foi designado para vigiar o Portão e não podemos deixar nossos postos, por causa do perigo de invasão.$b$bMas temos que oferecer alguma resistência a estes malditos troggs que espreitam as montanhas. Ataque-os, se for capaz. E traga 8 Dentes de Pedra de Trogg como prova da façanha.", t = "A ameaça dos troggs"},
    [268] = {ot = "Leve o diário completo de Medrisco para Noel.", st = "O livro que você encontrou ainda não estava terminado. Tive que deixar na fazenda de Noel quando fugi...$B$BAqui, leve o meu diário completo para Noel, pois nele está descrito tudo o que aconteceu na fazenda dele.$B$BEmbora este diário tenha sido minha única companhia das últimas semanas, eu o entrego de bom grado se isso me livrar de ter que encarar a ira de Noel!", t = "Respostas a Noel"},
    [269] = {ot = "Entregue o Diário Completo de Medrisco para o Bispo Palhares em Ventobravo.", st = "Vá à cidade de Ventobravo e procure o Bispo Palhares na Catedral da Luz. Entregue o diário de Medrisco a ele e diga que você quer enfrentar Morbídio Vil.$B$BEmbora Ventobravo tenha renegado a Vila Sombria, Palhares é sábio, uma alma generosa. Talvez ele colabore com a sua missão de nos salvar.$B$BSua tarefa é perigosa, $n, mas é melhor se apressar. A cada hora que passa, as sombras da Floresta do Crepúsculo ficam mais escuras.", t = "Em busca da sabedoria"},
    [271] = {ot = "Mate o Velho Fumaça e mostre sua proeza a Dário, o Novato, no Pavilhão dos Andarilhos.", st = "Você estaria $Ginteressado:interessada; em dar o troco em Sua Excelência o Caçador? Até que o Dário tem talento. Me dói dizer isso, mas é verdade.$b$bHá um ano, todo o Pavilhão dos Andarilhos saiu atrás de um urso enorme, mas nenhum caçador teve sorte. Então, o Dário resolveu tentar também. E tudo que trouxe de volta foi aquela cicatriz horrorosa por cima do olho.$b$bSe você matasse aquele urso, tenho certeza que até o Dário ficaria sem palavras.$b$bO Velho Fumaça, nome que demos ao urso, costuma vagar perto da toca dele, nas montanhas que acimam Thelsamar.", t = "A vingança de Vyrin"},
    [272] = {ot = "Encontre o Meio-pingente da Agilidade Aquática e o Meio-pingente da Resistência Aquática. Fale com os residentes da Clareira da Lua para obter pistas de onde esse itens podem estar.$B$BForme o Pingente do Leão Marinho a partir das duas metades. Você precisa estar perto do Santuário de Remulos para fazer isso.$B$BLeve o pingente reunido ao Dendrite Stellardor na vila de Refúgio Noturno, que fica na Clareira da Lua.", st = "Para a segunda prova, você vai precisar das duas metades que formam o Pingente do Leão Marinho. Uma delas extrai poder do aspecto da agilidade do leão marinho, que desliza pela água. A outra extrai poder do aspecto da inacreditável resistência do leão marinho. Os druidas se valem igualmente das duas características para encarnar o aspecto de sua forma aquática.$B$BFale com os moradores da Clareira da Lua para saber onde as partes podem estar, e traga ambas para cá, onde podemos reuni-las. Quando o pingente estiver formado, leve para Dendrite Stellardor.", t = "Missão do leão marinho"},
    [273] = {ot = "Fale com Huldar", st = "Não é tarde demais, fique à vontade para procurar o Huldar.$B$BEle não deve ter ido muito longe. Fortes como são, Miran e Saean não conseguem ir muito rápido com todo aquele peso.$b$bEles foram para o sítio pela rota de sempre, que começa no sul da cidade e segue pelas margens do Loch.$b$bNão vai ser difícil encontrá-los, a não ser que já tenham chegado lá!", t = "Suprimentos para o sítio"},
    [275] = {ot = "Mate 12 Rastejantes do Pântano, depois fale novamente com Rethiel, o Verdião no Pantanal.", st = "Não sei por que, mas algo pútrido cresce dentro do Pantanal. Os rastejantes do pântano se ergueram. São pústulas doentes e febris na terra, e para acabar com a febre é preciso expulsá-los e permitir que se acomodem novamente nos pântanos.$B$BOs rastejantes do pântano andam trôpegos em meio aos cursos d'água do Pantanal.", t = "Pústulas na terra"},
    [276] = {ot = "Mate 15 Gnolls Pelemusgo e 10 Mestiços Pelemusgo, depois fale novamente com Rethiel, o Verdião no Pantanal.", st = "Os gnolls Pelemusgo viveram pacificamente no Pantanal por muito anos, mas agora eles são muitos. A pisoteada deles esmaga as flores e os arbustos do pântano, e seus malditos machados cortam madeira demais para alimentar suas fogueiras.$B$BEles estão em desequilíbrio com a terra. Para que o Pantanal sobreviva, é preciso reduzir a quantidade de gnolls.$B$BMate 15 Gnolls Pelemusgo e 10 Mestiços Pelemusgo. Cace-os no sul, perto do portão enânico de Algaz. Depois disso, fale novamente comigo.", t = "Patas pisoteantes"},
    [277] = {ot = "Leve 9 Pederneiras Grotescas para Rethiel, o Verdião.", st = "Os Pelemusgos estão cortando as árvores do Pantanal, usando a madeira para se aquecer com o fogo. Não vou mais tolerar essa dor!$B$BTire dos Pelemusgos as pederneiras grosseiras, as ferramentas que eles usam para fazer fogo. Todo Pelemusgo tem uma, com exceção dos gnolls Pelemusgo menores e dos mestiços Pelemusgo.", t = "Tabu do fogo"},
    [279] = {ot = "Mate 12 Murlocs Guelrazul.$B$BMate o Comilão e pegue a cabeça dele.$B$BLeve a Cabeça de Comilão para Carlos Borba no Porto de Menethil.", st = "Os murlocs estão saindo das águas profundas e construindo aldeias na costa. Eles estão atormentando os pescadores e comerciantes. Temos que dar um fim nisso.$B$BUm deles, o Comilão, costuma se juntar a outros murlocs Guelrazul para saquear os comerciantes na estrada. Depois, eles sempre fogem para as cabanas por perto. Os nossos comerciantes estão em perigo, e estamos dispostos a pagar a quem puder garantir a segurança deles.$B$BO Comilão ronda a baía do rio a norte daqui. Encontre-o, mate todo o bando e traga-me a cabeça dele.", t = "Garras das profundezas"},
    [281] = {ot = "Vasculhe os caixotes e barris nos acampamentos dos murlocs na costa.", st = "Pouco tempo atrás, um navio mercante, o Princesa Cega, foi atacado por murlocs. O navio não sofreu avarias, mas a maior parte da carga, que continha até uma estatueta muito valiosa de Terenas Menethil, foi roubada pelas criaturas. Queremos a estatueta de volta.$B$BProcure caixotes, barris e outros indícios da carga roubada nas cabanas dos murlocs na costa. Encontre a estatueta de Menethil e traga-a de volta.", t = "O que é nosso de direito"},
    [282] = {ot = "Fale com o Montanhista Thalos.", st = "Eu estava planejando mandar meu aprendiz levar o relatório para meu irmão Senir, mas eu ficaria muito mais tranquilo se o documento estivesse em mãos... mais confiáveis. Isso, é claro, se você não se importar.$b$bHum, você vai precisar pegar o túnel para chegar até Kharanos.$b$bFale com o Montanhista Thalos antes de passar pelo túnel. Está completamente infestado por troggs agora.$b$bSiga a estrada de volta para Sidermar, depois siga em direção leste para o túnel, Thalos está estacionado por perto.", t = "Observações de Senir"},
    [284] = {ot = "Procure a Estatueta de Menethil.", st = "Você vasculha o conjunto inteiro de cabanas dos murlocs e não encontra nem sinal da Estatueta de Menethil.$B$BTalvez uma das duas cabanas ao norte e ao nordeste tenha alguma pista.", t = "A busca continua"},
    [285] = {ot = "Continue vasculhando as cabanas dos Murlocs em busca da Estatueta de Menethil.", st = "Mesmo depois de uma busca completa, a aldeia murloc não oferece pista alguma.$B$BVocê tem certeza de que a próxima pista que encontrar será proveitosa.$B$BA estatueta de Menethil deve estar em uma das cabanas ao norte!", t = "Vasculhe mais cabanas"},
    [286] = {ot = "Entregue a Estatueta de Menethil para Carlos Borba.", st = "Depois de tirar o barril do lamaceiro e abri-lo, você encontra um artigo de prata no meio da palha. É uma imagem de um jovem paladino de cabelos longos com um martelo erguido.$B$BDeve ser a estatueta de Menethil! Leve-a a Carlos Borba no Porto de Menethil.", t = "Devolva a estatueta"},
    [287] = {ot = "Percorra a Fortaleza Jubafria e mate 5 Caçadores de Cabeças Jubafria a pedido de Senir Barbabranca em Kharanos.", st = "Estou atrasado com meu relatório, $n. Bem que você poderia me ajudar. Consegui descobrir onde os trolls estão entocados, mas eram tantos que fiquei com medo de entrar.$b$bEu preciso que você faça o seguinte: desça na caverna, dê uma fuçada no ambiente, mate alguns trolls e volte para cá.$b$bPegue a estrada que sai de Kharanos em direção ao norte. Ao chegar à ponte, siga a oeste ao longo do rio congelado até chegar ao Lago Nevado. A Aldeia da Cevada fica na margem oeste do lago, e a fortaleza fica a sudoeste da aldeia.", t = "A Fortaleza Jubafria"},
    [288] = {ot = "Compre uma Jarra de Hidromel para o Primeiro Oficial Simonez.", st = "Eu era Primeiro Oficial do Senhora das Ondas, um navio de linha da Terceira Frota de Kul Tiraz, a Esquadra Naufragada. Naufragada porque, na última viagem, foi atacada pelos Dragões Vermelhos... Dragões controlados por orcs!$B$BNão tivemos a mínima chance contra o fogo de dragão... A nossa frota inteira foi queimada e afundou perto da costa. Sou o único sobrevivente desses pobres navios...$B$BAi, minha cabeça não para de latejar! Preciso de uma bebida gelada para controlar a ressaca e continuar a contar a minha história.", t = "A terceira frota"},
    [291] = {ot = "Entregue o relatório de Senir ao Senador Barin Itarrubra em Altaforja.", st = "Excelente! Entregue meu relatório ao Senador Barin Itarrubra. Ele é um tipinho enfezado, então não deixe aquele humor de cão influenciar você. O Senador dá audiências em Altaforja, na sala de beija-mão do rei Magni.$b$bVocê não sabe como chegar em Altaforja? Pegue a estrada que sai de Kharanos em direção ao norte, cruze a ponte e, então, basta seguir a estrada a leste, montanha acima. Não tem erro, há várias bandeiras ao longo do caminho.$b$bA propósito, você se importa de não mencionar que me ajudou? Não quero que eles pensem que não estou dando duro aqui, sabe?", t = "Os relatórios"},
    [294] = {ot = "Ormer Trançaferro, no Sítio de Escavação Whelgar, quer que você mate 10 Guinchadores Mosqueados e 10 Raptores Mosqueados.", st = "A situação é grave, isso é certo. Quando descobrimos os ossos, eles atraíram os raptores para cá. Esses bichos imundos mataram meus irmãos e prenderam a mim, Marina e o pobre coitado do Prospector aqui.$b$bAjude a livrar o Pantanal dos Raptores, $n. Os Raptores Mosqueados e os Guinchadores Mosqueados estão a oeste do penhasco. Mate 10 de cada, se possível.$b$bVai ser um bom começo para a vingança que tenho em mente.", t = "A revanche de Ormer"},
    [297] = {ot = "Leve 8 Ídolos Esculpidos em Pedra para Magmar Machadeiro.", st = "Há pouco tempo, antes dos troggs aparecerem no sítio, nós desenterramos estranhos ídolos esculpidos. Mas não tivemos nem chance de estudá-los, porque logo depois da descoberta os troggs nos expulsaram das ruínas! E esses artefatos provocam estranhos efeitos nos troggs. Eles ficam enlouquecidos!$B$BTraga 8 ídolos para mim. Quero estudá-los e mantê-los longe dos troggs! Os ídolos estão com os troggs que infestam o sítio.", t = "Juntando ídolos"},
    [298] = {ot = "Entregue o Relatório de Progresso de Bandaferro para Jern Elmocorno em Thelsamar.", st = "Eu preciso enviar um relatório de andamento para Thelsamar – isso e uma reiteração do meu pedido de pólvora! Aqui está o relatório. Entregue-o para Jern Elmocorno. Ele é o nosso contato em Thelsamar.$B$BNão é lá uma tarefa muito desafiadora, mas tem que ser cumprida.", t = "Relatório de progresso da escavação"},
    [301] = {ot = "Entregue o Relatório de Progresso de Bandaferro para o Prospector Lançatroz.", st = "Precisamos de aprovação para enviar mais pólvora para o Bandaferro. Você vai ter que enviar o relatório dele para o quartel-general da Liga dos Exploradores, em Altaforja.$B$BAqui está o relatório. Entregue-o para o Prospector Lançatroz, e não esqueça de se abaixar após entregar o documento. O Lançatroz é muito esquentado e não vai ficar feliz ao saber do lento progresso da escavação.$B$BO Lançatroz está na Assembleia dos Exploradores.", t = "Apresente-se a Altaforja"},
    [302] = {ot = "Fale com Jern Elmocorno em Thelsamar.", st = "Se é pólvora o que o Bandaferro quer, por Magni, é isso o que ele vai ter! Já enviei um mensageiro entregar a aprovação do pedido para Jern Elmocorno, em Thelsamar. Ele vai preparar a pólvora e os outros suprimentos para enviarmos para o Bandaferro.$B$BMais uma coisa: quero que você acompanhe o carregamento de pólvora até o destino. O último não chegou, então mantenha os olhos abertos.", t = "Pólvora para Bandaferro"},
    [303] = {ot = "Rocio Garmason, de Dun Modr, quer que você mate 15 Anões Ferro Negro, 5 Escavadores Ferro Negro, 5 Sabotadores Ferro Negro e 5 Demolidores Ferro Negro.", st = "Há guerra em nosso lar e lá fora. Enquanto os soldados anões dão a vida em territórios distantes em nome da Aliança, nossas próprias terras sofrem com as crueldades dos anões Ferro Negro. Eles causaram devastação à Ponte Thandol. Dun Modr caiu logo em seguida.$b$bPrecisamos da tua força para fazer a linha de frente deles recuar. Se tu matar 15 Anões Ferro Negro, 5 Escavadores, 5 Sabotadores e 5 Demolidores, a força reserva deve chegar a tempo para concluir o ataque.$b$bVai, depressa!", t = "A guerra dos Ferro Negro"},
    [305] = {ot = "Tarrel Tecepedra quer que você viaje até o Sítio de Escavação e contate Marina Tecepedra.", st = "Você nem imagina como estou preocupado.$b$bMinha esposa, Marina, me mandou cartas toda semana no mês passado. Ela faz parte da equipe de escavação de Whelgar. Mas já se passaram quase duas semanas desde a última correspondência dela. Com certeza tem alguma coisa errada!$b$bTrançalonga disse que mandaria um batedor para checar as coisas se não tivéssemos notícias da equipe logo. Eu suponho que seja você, $n. Procure a Marina no local de escavação a leste!", t = "Em busca da equipe de escavação"},
    [306] = {ot = "Leve o bilhete de Marina para Tarrel Tecepedra.", st = "Foi horrível! Estávamos desenterrando alguns artefatos raros quando encontramos uns ossos grandes.$b$bAntes que nos déssemos conta do que estava acontecendo, aqueles raptores mosqueados tomaram o sítio de escavação. Muitas vidas foram perdidas.$b$bO Ormer aqui — tão valente — salvou a mim e ao Prospector. Ele nos defendeu enquanto corríamos em busca de abrigo. Agora estamos presos, e o nosso trabalho foi arruinado.$b$bAqui, leva este bilhete para o meu querido Tarrel. Vai explicar a situação toda para ele.", t = "Em busca da equipe de escavação"},
    [307] = {ot = "Vá até a Mina da Prata e recolha 4 cargas de Equipamento de Mineração.$B$BFale novamente com o Montanhista Lançatroz.", st = "A Mina da Prata, a leste daqui, está esgotada há muito tempo. A Liga dos Mineradores a transformou em armazém, mas agora os kobolds estão ocupando as galerias e botando aquelas patas nojentas em ferramentas enânicas de qualidade!$B$BNós vamos expulsar esses vermezinhos em breve, mas a Liga quer retirar os equipamentos antes que nós, guerreiros, invadamos o lugar e quebremos alguma coisa. Vai ser uma operação difícil, então sugiro que você leve alguns companheiros para ajudá-$Glo:la;.$B$BO equipamento está armazenado em caixotes da Liga dos Mineradores ao longo de toda a mina. Boa sorte.", t = "Patas nojentas"},
    [308] = {t = "Distraindo Jarven"},
    [309] = {ot = "Garanta que Miran e o carregamento cheguem ao sítio de escavação, depois informe ao Prospector Bandaferro.", st = "Tudo certo, $n?$b$bPrimeiro precisamos entregar a pólvora para o Bandaferro. É muita coisa para carregar, esta região costuma ser perigosa, e sabe-se lá o que os Ferro Negro podem estar tramando contra mim.$b$bEu me sentiria muito melhor se você me acompanhasse.", t = "Em defesa do carregamento"},
    [310] = {ot = "Troque um barril de Cerveja do Trovão por um barril de Grogue Cervevada no porão da Destilaria Cervaforte, que fica em Kharanos.", st = "Eu tenho que admitir: esses Cervaforte fazem umas cervejas até bem razoáveis. Mas eles têm que saber que a deles não é a única cerveja boa do mundo! Quem sabe você não possa me ajudar a ensinar uma lição àqueles convencidos...$B$BPegue este barril de Grogue do Cervevada. Entre de fininho no porão da Destilaria Cervaforte, em Kharanos, e troque um dos barris de Cerveja do Trovão por este aqui. Aí vamos ver o que os fregueses deles vão achar da minha cerveja!$B$BE, caso o porão seja vigiado, você talvez tenha que distrair o guarda...", t = "A guerra das cervejas"},
    [311] = {ot = "Entregue o barril de Cerveja do Trovão para Marleth Cervevada na Aldeia da Cevada.", st = "Depois de deixar um barril de Grogue do Marleth na adega da Destilaria de Kharanos, pegue um barril de Cerveja do Trovão como prova da façanha...", t = "Fale novamente com Marleth"},
    [312] = {ot = "Pegue de volta a carne-seca do Tundra MacGrann do armário de carnes roubado, na caverna do Velho Barbafria.", st = "Eu tinha um estoque de carne-seca suficiente para um mês separado para o inverno. Tudo muito bem trancado para manter os ursos longe das minhas provisões! Mas enquanto eu estava fora caçando cervos, aquele maldito urso, o Velho Barbafria, carregou o armário de carnes inteirinho! Pelo menos ele não vai conseguir arrebentar aquelas portas de tório. Mas eu vou morrer de fome se não pegar meu estoque de volta.$b$bVocê parece ser um pouco mais $Gdiscreto:discreta; do que eu. Será que poderia pegar meu estoque de volta? Eu nunca conseguiria entrar e sair correndo daquela caverna com essa minha perna imprestável.", t = "Por baixo da carne-seca"},
    [313] = {ot = "Colete 8 Crinas de Wendigo e leve-as para Piloto Marchapedra.", st = "Não é qualquer bobalhão que gineteia uma máquina de cerco. É pulso de ferro de um lado e nervos de aço do outro... Por sorte, me sobram as duas coisas! E tu? Te metes a tentar? Quer provar que tu sabe?$B$BOra bolas... Tô querendo aprumar mina máquina, a Lavratroll, deixar mais confortável. Que tal tu me trazer uma pilha de crinas de wendigo do Covil Cinzento, lá pro oeste de Kharanos? Essas crinas dariam um baita pelego pro interior do Lavratroll!", t = "O Covil Cinzento"},
    [314] = {ot = "Rudra Ambarmanso quer que você mate Ragash e leve sua presa para ela no rancho dos carneiros.", st = "Ouvimos o salseiro na calada da noite. Daí, pela manhã, certo era previsto, duas reses estavam faltando dos carneiros. Uma fera tranqueira, tratada por Ragash, vem caçando em nossas coxilhas. Como quase não se vê tropas de Altaforja por aqui, não se arranja um dente seco pra correr o Ragash.$b$bTerias coragem pra ir atrás da fera e desnucar a maldita? Traz-me uma das presas de Ragash que tu serás $Grecompensado:recompensada;. Ele vive se espreitando logo acima do rancho. Mas não te atires de sopetão, que a fera é letal.", t = "Amarre sua cabra pois Ragash está solto"},
    [315] = {ot = "Entregue 6 ramos de Tremulerva para Rejold Cervevada na Aldeia da Cevada.", st = "Já me decidi. Decidi que vou fazer a stout perfeita. Não se duvida isso, afinal, fazer cerveja está no sangue! Só me falta uma receita bagual...$B$BOs trolls Jubafria criam uma planta chamada tremulerva no alto da serra ao leste, para usar naqueles rituais tribais estranhos dele. Pra anão, ela não tem muita serventia, mas o sabor... Ah, o sabor é único. Quero ver se essa erva combina com cerveja!$B$BQuero que tu me traga um pouco de tremulerva dos videntes Jubafria ou tu me passa a mão nas cestas de tremulerva dos trolls.", t = "Em busca da cerveja perfeita"},
    [317] = {ot = "Junte 4 Nacos de Carne de Javali e 2 Pelames Grossos de Urso e entregue tudo para o Piloto Urrabolha na Garagem do Gradaço.", st = "Estou me preparando para sair em missão para a Brigada de Cerco. É uma missão longa, por isso tenho que abastecer a Vaporeta com suprimentos para um mês. Então, enquanto o Gradaço não libera o meu tanque, você poderia sair à caça por mim?$B$BVou precisar de peles para montar uma cama e de carne para comer. A pele você tira dos ursos, e a carne, dos javalis. Esses bichos costumam zanzar pelos campos nevados a sul do Covil Cinzento.", t = "Provisões para a Vaporeta"},
    [318] = {ot = "Pegue um barril de Sempre-aceso com o Rejold Cervevada na Aldeia da Cevada.", st = "O Rejold Cervevada costuma fazer experiências com as cervejas que faz. Umas ficam boas, algumas ficam ruins e outras... Bem, outras derrubam até anão velho.$B$BO Rejold mora na Aldeia da Cevada, a oeste de Kharanos. Estou atrás de uma das bebidas que ele faz, a Sempre-aceso. Isso vai me ajudar a esquentar os ossos enquanto eu estiver naquela estrada fria.$B$BE mais... Essa bendita bagaceira queima tanto que dá até para jogar na fornalha da Vaporeta para dar um gás na potência da bichinha! Esse truque já me tirou de poucas e boas...", t = "Sempre-aceso"},
    [319] = {ot = "Mate 6 Ursos Garra de Gelo, 8 Rochetuscos Adultos e 8 Leopardos da Neve. Em seguida, fale novamente com Rejold Cervevada na Aldeia da Cevada.", st = "Eu tenho um barrilete de Sempre-aceso prontinho, mas... Pode me fazer um favor? A Aldeia da Cevada está precisando de uma mãozinha com os bichos selvagens que vagam pela neve. Às vezes, eles se aproximam demais.$B$BNão que a gente esteja com medo desses ursinhos e gatinhos e javalizinhos – esses bichos não metem medo em nenhum anão de respeito – mas, se você desse cabo deles, a gente ia ter muito mais tempo para cultivar a arte de fazer cerveja.", t = "Tudo pela Sempre-aceso"},
    [320] = {ot = "Entregue o barrilete de Sempre-aceso para o Piloto Urrabolha na Garagem do Gradaço.", st = "Aqui está seu barrilete de Sempre-aceso, $n. E, mais uma vez, obrigado pela caçada de mais cedo.", t = "Fale novamente com Urrabolha"},
    [323] = {ot = "Mate 15 Saqueadores Descarnados, 3 Curandeiros Descarnados e 3 Guardadores Descarnados, e depois fale novamente com Noel.", st = "Morbídio Vil é um necromante, aliado dos Cavalgantes Negros. Mandaria você para confrontar o poder de Morbídio Vil, aquele sórdido infame, mas não sem antes testar sua força.$B$BVocê já provou sua bravura, mas se deseja mesmo encarar esse necromante, deve mostrar o que sabe contra os lacaios dele.", t = "Prova de valor"},
    [337] = {ot = "Devolva o livro \"A História de Ventobravo\" para a Biblioteca de Ventobravo.", st = "Apesar da capa toda marcada e enlameada, ainda se pode ler na lombada \"A História de Ventobravo\". Ao abrir o livro, o selo da Biblioteca de Ventobravo está visivelmente estampado no folha de rosto.$B$BParece que alguém retirou esse livro e nunca se deu ao trabalho de devolvê-lo...", t = "Um velho livro de história"},
    [343] = {ot = "Vá à Biblioteca Real na Bastilha Ventobravo e fale com Milton Resma. Ele pode encontrar para você o livro sobre metalurgia que o Irmão Kristoff precisa para o discurso.", st = "Estou fazendo um discurso sobre a Fortitude do Espírito, e gostaria de recitar passagens de um livro específico sobre metalurgia: \"Fadigas do Ferro\". Deve haver uma cópia deste livro na Biblioteca Real, dentro da Bastilha Ventobravo. Você pode trazê-lo para mim? Se puder, então que as bênçãos da Luz estejam com você!$B$BA Biblioteca Real é muito grande, mas o bibliotecário-chefe, Milton Resma, conhece cada prateleira como se fosse um filho. Fale com ele, e sei que encontrará o livro para você.", t = "Falando sobre fortitude"},
    [344] = {ot = "Fale com o Irmão Paxeco na Abadia de Vila Norte.", st = "Fadigas do Ferro? Sim, eu conheço o livro. É muito bom, foi escrito pelo mineiro anão Margulf Blaggon algumas décadas atrás. Ele passou a maior parte da vida nas montanhas de Khaz Modan, escavando minério. Camarada inteligente!$B$BMas onde eu estava? Ah, sim, o Fadigas do Ferro! Receio que o livro tenha sido transferido para a Abadia de Vila Norte. O zelador da biblioteca da abadia, Irmão Paxeco, queria fazer uma cópia do livro para as prateleiras dele.$B$BMas isso foi há meses. Não entendo por que ele está demorando tanto...", t = "Irmão Paxeco"},
    [345] = {ot = "Fale com o Encarregado Oslow em Vila Plácida e peça-lhe Minério de Ferro Retibano.", st = "Eu estava querendo terminar minha cópia de Fadigas do Ferro, mas...$B$BBem, copio os livros com a tinta que eu mesmo faço. A receita é minha. A tinta não escorre nem mancha, e seca bem depressa! Infelizmente, seca depressa demais! Meu último lote secou antes que eu pudesse terminar a cópia, e não tive chance de fazer mais tinta!$B$BPara preparar mais, preciso de minério de ferro retibano das Montanhas Cristarrubra. O Encarregado Oslow, em Vila Plácida, costuma ser meu fornecedor.", t = "Estoque de tinta"},
    [346] = {ot = "Fale novamente com Irmão Kristoff na Praça da Catedral. Dê a ele o livro Fadigas do Ferro.", st = "Agora que terminei de copiar o livro, aqui está o original de Fadigas do Ferro. Obrigado por sua paciência e, quando estiver com Milton, por favor, diga que sinto muito pela demora.", t = "De novo com Kristoff"},
    [347] = {ot = "Colete 5 porções de Minério Retibano e leve-as para o Irmão Paxeco na biblioteca de Vila Norte.", st = "O minério retibano tem esse nome em razão do primeiro homem que o encontrou, Bartolomeu Retiban. Quando fundido, não é tão forte quanto o ferro, mas o minério bruto tem uma cor escura e uniforme que alguns escribas usam em seus pigmentos. O minério pode ser encontrado nas Cavernas Retibanas, ao norte daqui.$B$BGeralmente temos um pouco em estoque, mas estamos ocupados demais nos preparando para ataques de orcs para extraí-lo. E, além disso... os gnolls de Cristarrubra agora estão morando nas Cavernas Retibanas, e seus Mourejantes estão extraindo o minério.$B$BEntão, se você está precisando, vai ter que ir atrás do minério sozinh$go:a;.", t = "Minério Retibano"},
    [350] = {ot = "Fale com Elling Trias em Ventobravo.", st = "Aquele Marzon estaria entrando em contato com alguém dos Défias e teria ligação com o Lescovar...$B$BCom VanCleef e Taborda mortos, seria difícil levar Lescovar a julgamento, já que as suas provas não são nada sem o testemunho deles. E isso sem levar em conta o fato de Lescovar ser nobre e muito bem-relacionado. Isso na prática o deixa acima da lei.$B$BVocê vai precisar de mais ajuda. Eu odeio fazer isso, mas conheço alguém que nos ajudará: Trias. Ele trabalha no Distrito Comercial.", t = "Procurando um velho amigo"},
    [353] = {ot = "Entregue o Pacote para Lançatroz para o Montanhista Lançatroz em Loch Modan.", st = "Os Lançatroz são um clã enânico muito respeitado, conhecidos pelo bom gosto e por serem muito exigentes. Então, não é surpresa que o Gringer Lançatroz, um montanhista de Altaforja, tenha encomendado uma arma comigo.$B$BJá acabei de fazer a arma, mas... O Gringer está de serviço em Loch Modan, que é muito longe daqui. Já que você estava pensando em ir para o norte, poderia entregar a encomenda para ele?$B$BNa última mensagem que me enviou, ele disse que estava aquartelado na torre de guarda norte, em Loch Modan.", t = "Entrega para Lançatroz"},
    [354] = {ot = "Obtenha os Restos Mortais de Gregor, os Restos Mortais de Nissa, os Restos Mortais de Timóteo para Eurico Palhares em Montalvo.", st = "A família Agamand era a família mais próspera nas Clareiras de Tirisfal. Eu costumava trabalhar nos moinhos deles... antes da peste.$B$BQuando o Flagelo chegou os Agamand fortificaram o terreno e convenceram os empregados a ficarem e ajudá-los com a defesa do local. Fomos tolos mas, ao menos, fomos tolos leais.$B$BOs Agamand, em seu orgulho, condenaram todos à morte-viva. Agora são lacaios do Flagelo!$B$BSirva aos Renegados derrotando os Agamand que sucumbiram à peste. Sirva a mim trazendo os restos deles.", t = "Mortes na família"},
    [355] = {ot = "Fale com o Magistrado Sevren em Montalvo.", st = "Você me deu os restos mortais dos Agamand e saciou minha sede de vingança. Mas os Moinhos dos Agamand representam uma ameaça a todos os Renegados, e não só a mim.$B$BContei ao Magistrado Sevren sobre suas façanhas contra os Agamand, e ele quer falar com você.", t = "Fale com Sevren"},
    [356] = {ot = "Mate 8 Horrores Sangrentos e 8 Espíritos Errantes. Depois, apresente seu relatório a Linnea no acampamento.", st = "Os defensores do Baluarte, que protege Tirisfal das Terras Pestilentas, ficam em alerta constante. Às vezes, porém, criaturas do Flagelo conseguem passar por eles.$B$BNosso sucesso no Baluarte depende de mantermos a batalha em uma só frente. Não podemos permitir um ataque pela retaguarda, nem permitir que as linhas de suprimentos dos defensores sejam cortadas.$B$BAjude o Baluarte. Patrulhe ao leste e mate quaisquer seres do Flagelo que você encontrar. Concentre mais esforços na Fazenda dos Balnir. Ela se tornou um refúgio para os infiltrados do Flagelo.", t = "Patrulha da retaguarda"},
    [357] = {ot = "Leve o Grimório do Lich para Boanerges Stalactus na Cidade Baixa.", st = "Há um lich na ilha no Lago Águas Claras, ao norte. Embora ele seja um Renegado com livre-arbítrio, ele crê que todos os outros mortos-vivos são escravos do Flagelo, e faz seus lacaios atacarem qualquer um que se aproxime.$B$BNo entanto, como ele é um Renegado, a Rainha quererá falar com ele. E, se ele for habilidoso com a necromancia, o conhecimento dele seria... bastante útil para nós.$B$BPara descobrir a identidade e os talentos dele, eu preciso ver o grimório dele. Entre incógnit$go:a; no acampamento, roube-o e venha falar comigo.", t = "A identidade do lich"},
    [358] = {ot = "Mate Roubacovas Putricouro e Mestiços Putricouro.$B$BLeve 8 frascos de Linfa Embalsamadora para o Magistrado Sevren, em Montalvo.", st = "As sepulturas coletivas a sudoeste do Sítio dos Garren, ao norte, foram feitas para acomodar o número... impressionante... de mortos em Tirisfal quando a Peste chegou.$B$BOs corpos nessas sepulturas escaparam à morte-viva até agora, mas o Flagelo enviou gnolls Putricouro para recolher os cadáveres e usá-los para os exércitos deles. Não podemos permitir isso!$B$BSua tarefa é dupla: mate os gnolls Putricouro na sepultura coletiva e no sítio dos Garren e extraia a Linfa Embalsamadora que lhes dá vida.", t = "Roubacovas"},
    [359] = {ot = "Fale com a Necroguarda Lina.", st = "Preciso de um relatório atualizado de nossa estação de passagem de necroguardas a leste daqui.$B$BPreciso saber se mais tropas do Flagelo conseguiram se infiltrar pelo Baluarte em Tirisfal. Nossa vigília nas fronteiras das Terras Pestilentas deve ser mantida. Não podemos permitir que o Flagelo finque o pé aqui!$B$BVá para o sul seguindo a estrada e então vire para leste na encruzilhada e siga até a estação de passagem. Fale com a Necroguarda Lina. Ela tem a informação de que preciso.", t = "Deveres Renegados"},
    [360] = {ot = "Fale novamente com o Magistrado Sevren em Montalvo.", st = "Apresente-se ao magistrado Sevren com a informação que eu lhe dei. Ele precisa das informações o quanto antes, então apresse-se.$B$BE se você vir qualquer criatura do Flagelo no caminho de volta, acabe com ela. Não podemos deixar que eles vaguem pelas nossas terras impunemente.", t = "De volta ao Magistrado"},
    [361] = {ot = "Encontre Ivete Palhares e entregue a carta de Timóteo Agamand.", st = "A carta é de Timóteo, filho mais velho de Gregor Agamand. Está endereçada a uma certa Ivete Palhares, mas parece não ter sido entregue...", t = "A carta que nunca chegou"},
    [362] = {ot = "Mate Delmiro Agamand e leve os Restos Mortais de Delmiro para Eurico Palhares em Montalvo.", st = "Delmiro Agamand era o mais novo dos dois filhos da família Agamand, e em vida os dois não poderiam ser mais diferentes. Timóteo era alto e gentil, enquanto o caçula era fraco e de língua ferina.$B$BQuando os Moinhos dos Agamand caíram perante a peste, não me surpreendeu saber que Delmiro sucumbiu rápido. Ainda se ouve o matraquear louco dele perto da estrada dos Moinhos dos Agamand.$B$BEstou coletando os restos mortais dos Agmand, e quero o pobre Delmiro. Encontre-o, destrua-o e traga-me os ossos dele.", t = "Os moinhos assombrados"},
    [363] = {ot = "Fale com o Sacerdote Sombrio Sarvis.", st = "Já era hora de acordar. Estávamos prontos para jogar você no fogo com os outros, mas parece que você despertou.$b$bSou Mordo, zelador da cripta de Plangemortis. E você não é mais escrav$go:a; do Lich Rei.$b$bFale com o Sacerdote Sombrio Sarvis na capela no pé da colina. Ele lhe contará mais coisas que você precisa saber.", t = "Despertar bruto"},
    [364] = {ot = "O Sacerdote Sombrio Sarvis quer que você mate 8 Zumbis Desmiolados e 8 Zumbis Atormentados.", st = "Nós Renegados estamos em guerra contra o exército do Flagelo do Lich Rei: fileiras de mortos-vivos reanimados com necromancia, feras imundas do norte e espectros atormentados.$b$bA parte norte da aldeia foi invadida pelos Desmiolados, e eles devem ser eliminados. Destrua-os, não tenha misericórdia, nossos antigos irmãos e irmãs ou não. Os caídos não passam de escravos do Lich Rei.", t = "Os desmiolados"},
    [365] = {ot = "Roube 10 abóboras da fazenda a oeste, que fica ao norte de Plangemortis, e leve-as para o Boticário Joaquino em Montalvo.", st = "O que traz você aqui? Você aparenta ser $gum:uma; aprendiz, $c. Se quiser provar o seu valor para a Dama Sombria, você precisa aprender o modo de vida dos Renegados.$b$bA oeste daqui você encontrará uma fazenda. Os humanos infestam a área como se fossem fungos num cadáver podre. Pior ainda, a Cruzada Escarlate faz patrulhas no local, partindo de uma das torres. Ensine uma lição àquela escória e roube dez das preciosas abóboras deles.$b$bQuando as tiver juntado, leve-as para o Boticário Joaquino em Montalvo.", t = "Campos de mágoa"},
    [366] = {ot = "Devolva o Grimório de Tertuliano a ele, na ilha do Refúgio de Tertuliano.", st = "Muito tempo atrás, Tertuliano e eu, mais o necromante do Flagelo Thule Corvinalle, éramos amigos e estudantes do Kirin Tor — uma sociedade de magos de Dalaran.$B$BTertuliano e eu sucumbimos à peste, mas eu pensei que ele tivesse permanecido morto, ou havia se juntado as fileiras do Lich Rei. É bom saber que ele está livre.$B$BNós precisamos dele do nosso lado. Eu coloquei um feitiço neste livro que, quando ele abrir, mostrará que também estou livre do Lich Rei. Depois que souber disso, eu espero que ele se junte a nós.", t = "Devolva o livro"},
    [367] = {ot = "O Boticário Joaquino na cidade de Montalvo quer que você colete 5 Ampolas de Sangue de Cão das Trevas.", st = "A Grande Dama Sylvana convocou a Real Sociedade de Boticários. Ela crê que nosso conhecimento, aliado à magia recém-adquirida, será crucial para a derrocada de Arthas. A Dama Sombria nos desafiou a preparar uma nova peste, mais mortal que qualquer mazela de Azeroth. Essa nova doença será a ruína do exército do Flagelo de Arthas.$b$bMeus estudos mostram que o sangue de certas feras pode ser a chave para o sucesso. Traga 5 ampolas com sangue de cão das trevas para que eu possa testar minha teoria.", t = "A nova peste"},
    [368] = {ot = "O Boticário Joaquino na cidade de Montalvo precisa de 5 Escamas de Pinavil dos Murlocs das Clareiras de Tirisfal.", st = "Enquanto você estava coletando amostras para mim, minhas experiências me fizeram compreender que mais reagentes serão necessários para que essa nova doença se espalhe adequadamente. Envenenar uma vítima indefesa é brincadeira de criança, mas empestear um mundo inteiro é um pouco mais complicado.$b$bEu vou precisar de 5 escamas de pinavil dos murlocs das redondezas. Você encontrará as criaturas vagando pela costa ao norte ou a oeste.", t = "A nova peste"},
    [369] = {ot = "O Boticário Joaquino na cidade de Montalvo quer que você leve 4 amostras de peçonha da Trevateia Malévola para ele.", st = "Enquanto você estava fora, eu encontrei alguns textos em um dos meus livros que indicam que uma praga antiga matou milhares de vítimas inocentes. Mais tarde se descobriu que o agente da praga foi preservado na peçonha das aranhas trevateias.$b$bTraga-me um pouco de peçonha de trevateia malévola para que eu possa completar este experimento. Eu quero ver se o elemento contagioso da peçonha funcionará com o meu novo composto. Dizem que as aranhas podem ser encontradas ao leste das Clareiras de Tirisfal.", t = "A nova peste"},
    [370] = {ot = "O Executor Zigano em Montalvo quer que você mate o Capitão Perrine, 3 Zelotes Escarlates e 3 Missionários Escarlates.", st = "Os documentos que recebemos do Executor Arren nos dão todos os detalhes necessários para acabarmos com a infestação humana nestas terras. De acordo com a informação, a Cruzada Escarlate designou o Capitão Perrine e uma brigada para ficar na torre em ruínas a sudoeste de Montalvo.$b$bMate o Capitão Perrine junto com 3 Zelotes Escarlates e 3 Missionários Escarlates, e então fale comigo novamente.", t = "Guerra à Cruzada Escarlate"},
    [371] = {ot = "O Executor Zigano em Montalvo ordenou que você mate o Capitão Vidálio e 5 Frades Escarlates.", st = "Ainda estamos em guerra e a Cruzada Escarlate continua a se fortalecer. O relatório que o Executor Arren me enviou indica que os ataques dos cruzados escarlates têm partido da torre em ruínas na parte sudeste de Tirisfal, perto da Fazenda dos Balnir. Eles estão sob o comando do Capitão Vidálio.$b$bMate Vidálio e 5 Frades Escarlates. Isso será um golpe devastador para a Cruzada!", t = "Guerra à Cruzada Escarlate"},
    [372] = {ot = "O Executor Zigano na cidade de Montalvo quer que você mate o Capitão Metrache e seus dois seguranças.", st = "Cruzado escarlates têm atacado da torre em ruínas que fica no norte de Tirisfal, além do Repouso de Faol. De acordo com as nossas informações, um impiedoso capitão chamado Metrache está a cargo desse grupo perverso.$b$bEu confio a você agora uma missão especial e perigosa. Mate o Capitão Metrache e seus dois seguranças em nome da Dama Sombria.", t = "Guerra à Cruzada Escarlate"},
    [373] = {ot = "Entregue a Carta para o Arquiteto da Cidade a Baros Aleixo em Ventobravo.", st = "Ao revistar o corpo de Edwin VanCleef, você encontra, entre outras coisas, uma carta não enviada. Ela está endereçada a Baros Aleixo, arquiteto da cidade de Ventobravo, Prefeitura, Praça da Catedral.$B$BParece que foi escrita e selada recentemente.", t = "Uma carta não enviada"},
    [374] = {ot = "Leve 10 Anéis com Insígnia Escarlates para o Necroguarda Belchior em Montalvo.", st = "Executor Zigano tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them.$b$bVarimathras, lieutenant to The Dark Lady, is seeing to it personally that the scum of Azeroth, the Human race, gets wiped into oblivion. Here in Tirisfal Glades we face a particularly annoying breed of humans: The Scarlet Crusade.$b$bVenture forth and wage an offensive on the Scarlet Crusade, $c. Bring me back 10 Scarlet Insignia Rings as proof of your loyalty to Varimathras and The Dark Lady.", t = "Prova da morte"},
    [375] = {ot = "Leve 5 Pelagens de Quiropúsculo e um pouco de Fio Grosso para Gretchen Dedamar em Montalvo.", st = "Está tão frio agora. A Peste da Morte-viva desliza em minhas veias como uma serpente de gelo. Logo a demência chegará. Mas nem mesmo um destino condenado me impedirá de servir a Dama Sombria. Quando veio o chamado, eu costurei sacos de corpos para os soldados caídos do poderoso exército de Sylvana.$b$bAgora minhas mãos tremem de frio. Se você me trouxer cinco pelagens de quiropúsculo e um pouco de fio grosso, vou poder costurar um cobertor pra mim. Me ajude, $n, e assim poderei continuar servindo à causa.", t = "O frio da morte"},
    [376] = {ot = "A Noviça Elvira precisa de 6 Patas de Carniceiro e 6 Asas de Quiropúsculo.", st = "As minhas obrigações incluem cuidar dos guerreiros feridos, costurar armaduras e roupas, e ajudar o sacerdote sombrio Sarvis com o que mais for preciso.$b$bEstá parecendo que você vai ficar sob o comando dele... Caçando os desmiolados, se eu o conheço bem. Bem, se você quiser continuar inteir$go:a; — e não tenho dúvida disso —, talvez eu possa ajudar. Eu estou ficando sem patas e asas aqui. Se me trouxer algumas, eu lhe arranjarei uma armadura. Você vai encontrar um bom número de lobos e morcegos ao sul daqui.", t = "Os malditos"},
    [377] = {ot = "O Conselheiro Millstipe da Vila Sombria quer que você leve a mão de Flávio Lúcio para ele.", st = "Como se o abandono dos cidadãos da Floresta do Crepúsculo não fosse ruim o bastante; agora a Câmara dos Nobres cospe no olho do Concílio da Vila Sombria com a decisão de aprisionar Flávio Lúcio em Ventobravo, em vez de decapitar o criminoso de acordo com a sentença do Lorde Ebanez.$b$bLúcio foi pego vendendo corpos do cemitério para Morbídio Vil, um crime punível com a morte. Ainda assim, Ventobravo fez dele um prisioneiro.$b$bMate Lúcio no Cárcere de Ventobravo. Traga-me a mão dele, e eu lhe recompensarei.", t = "Crime e castigo"},
    [378] = {ot = "Rocio Garmason quer que você leve a cabeça de Kam Fundafúria para ele em Dun Modr.", st = "Você provou tua lealdade ao rei Magni, $c. E o teu ódio pela escória dos Ferro Negro é tão grande quanto o meu.$b$bTem um trabalho que eu queria fazer, mas sou obrigado por honra a ficar ao lado de Trançalonga. Mas Roggo obteve informações que provam que Kam Fundafúria conspirou no ataque à Ponte Thandol. Foi por causa da traição de Fundafúria que Trançalonga perdeu seu irmão.$b$bFundafúria está sendo mantido no Cárcere de Ventobravo por razões políticas. Eu quero ele morto, $n. Por Trançalonga! Traga-me a cabeça dele!", t = "Fúria profunda"},
    [380] = {ot = "O Executor Arren quer que você mate 10 Trevateias Jovens e 8 Trevateias.", st = "Uma das nossas maiores lutas é para obter os recursos naturais que precisamos para sobreviver. O ouro sempre foi escasso, mesmo na época de maior poder da Aliança.$b$bHá uma mina de ouro a nordeste que foi invadida por aranhas. Precisamos do ouro desta mina, mas não conseguiremos enquanto as aranhas estiverem por lá. Não tenho muitos homens para pôr nesta tarefa, então vamos fazendo aos poucos.$B$BVá até lá e veja o que pode fazer por nós, $n.", t = "Vale Teia da Noite"},
    [381] = {ot = "Leve 12 Braçadeiras Escarlates de Neófitos Escarlates e Iniciados Escarlates para o Executor Arren.", st = "Você ficará feliz de saber que estamos fazendo progresso na mina, graças em grande parte aos seus esforços. Agora podemos nos concentrar em outros problemas.$b$bOs meus batedores relataram que um destacamento da Cruzada Escarlate montou acampamento a sudeste daqui. A Cruzada Escarlate é uma organização desprezível que nos caça, e eles não descansarão até que todos os mortos-vivos — Flagelo do Lich Rei ou não — sejam destruídos. Temos que atacar primeiro!$b$bTenha cuidado, seu fervor profano faz deles adversários perigosos.", t = "A Cruzada Escarlate"},
    [382] = {ot = "Mate Meven Korgal, o mensageiro, no acampamento da Cruzada, e leve as informações que encontrar para o Executor Arren.", st = "Relatos dos meus superiores em Montalvo indicam que um agente da Cruzada Escarlate foi despachado do Monastério Escarlate e enviado aqui para Plangemortis. De acordo esses relatos, o mensageiro carrega informações importantes consigo. Eu não tenho mais detalhes, mas seja o que for, nós precisamos interceptá-lo!$b$bVocê é a pessoa mais qualificada à disposição, $n. Encontre o mensageiro e traga qualquer informação que conseguir.", t = "O mensageiro escarlate"},
    [383] = {ot = "Entregue os Documentos da Cruzada Escarlate ao Executor Zigano, em Montalvo.", st = "Preciso levar esses documentos ao meu superior, o Executor Zigano, em Montalvo. Com essas informações, vamos poder efetuar um ataque decisivo contra a Cruzada Escarlate. Seus serviços foram úteis aqui em Plangemortis, mas preciso entregar isso a Zigano, e acredito que ele pode ter mais trabalhos para você.$b$bPegue a estrada ao norte para sair de Plangemortis. Logo depois de entrar em Tirisfal, você vai chegar a uma encruzilhada. Pegue a estrada leste e continue indo para o leste. Você vai passar pelo Casarão Lar Glacial no caminho.", t = "Informações cruciais"},
    [384] = {ot = "Ragnar Cervaforte, em Kharanos, quer que você lhe traga 6 Costeletas de Rochetusco e uma caneca de Malte Rapsódia.", st = "A freguesia aqui do estabelecimento adora nossas costelinhas de javali na cerveja! Só que o coureador que abastecia meu estoque se alistou no Exército do Rei para ajudar na guerra, no front da Aliança. $b$bQuem sabe você não podia me dar uma ajudinha? Se você me trouxer seis costelinhas de rochetusco e uma cerveja Malte Rapsódia da taberna, eu lhe dou a receita de família das minhas famosíssimas costelinhas de javali na cerveja. E você ainda leva uma amostra grátis de brinde! O segredo é o Malte!", t = "Costelinhas de javali na cerveja"},
    [385] = {ot = "Obtenha 5 peças de Carne de Crocolisco e 6 Peles de Crocolisco para Marek Ferrocordis no Pavilhão dos Andarilhos.", st = "Muitos caçadores vem para o Loch Modan caçar os famosos crocolisco. Tem muitos mercadores em busca de pele de crocolisco, que são boas para fazer roupas e armadoras, e tem até quem goste da carne do bicho.$b$bNós chegamos a entrar nesse comércio, mas em pequena escala, porque os crocoliscos são muito ferozes e se entrincheiraram nas ilhas do Loch. Mas não se assuste com o que eu digo, é uma experiência e tanto, lutar contra as mandíbulas dessas feras.$b$bTeve uma vez...", t = "Crocoliscos na mira"},
    [386] = {ot = "Leve a cabeça de Targorr, o Horror para o Guarda Berto em Vila Plácida.", st = "Targorr, o Horror serviu como Carrasco supremo sob as ordens de Gath'Ilzogg. Seus métodos eram cruéis demais, mesmo para o sinistro padrão dos orcs. Homens que lutaram bravamente para defender o Reino foram torturados a seu bel-prazer. Agora ele está preso no Cárcere de Ventobravo, condenado à morte. Um dos nobres burocratas ordenou a suspensão da execução. Tenho certeza de que estão tramando alguma coisa$b$bAcabe com Targorr, o Horror, $n. Viaje até O Cárcere e corte a cabeça dele antes que façam alguma tramoia.", t = "Tudo que vai..."},
    [387] = {ot = "O Carcereiro-chefe Thelágua de Ventobravo quer que você mate 10 Défias Prisioneiros, 8 Défias Condenados e 8 Défias Insurgentes em O Cárcere.", st = "A rebelião precisa ser sufocada! Preciso da sua ajuda. Se vazar a notícia de que a prisão se rebelou, eu perco o emprego! Quero morrer cego de um olho se isso não for alguma tramoia. Mas o que importa agora, pelo bem de Ventobravo, é dominar os prisioneiros.$b$bA punição por insurgência é a morte. Matem alguns desses marginais! Isso deve fazer as coisas voltarem ao controle.", t = "Sufoque a rebelião"},
    [388] = {ot = "Nikova Raskol, de Ventobravo, quer que você colete 10 Bandanas Vermelhas de Lã.", st = "O desgosto corre em minhas veias como as águas geladas de um rio. Marquinho, meu neto, era um menino de ouro. Apenas 14 anos. Quando o exército foi mandado para o front, o Marquinho pegou em armas para defender a cidade. Ele estava de guarda no Cárcere, onde a gangue dos Défias cumpria pena. O Marquinho repreendeu alguns prisioneiros por rasgar cobertores para cobrir o rosto, como eles costumam fazer. Por causa disso, esfaquearam o pobrezinho pelas costas.$b$bEu quero vingança. Traga 10 das Bandanas de Lã deles. Elas são vermelhas como sangue.", t = "A cor do sangue"},
    [389] = {ot = "Fale com o Carcereiro-chefe Thelágua no Cárcere.", st = "VanCleef e eu éramos membros da Guilda dos Alvanéis. Nossa principal incumbência era reconstruir Ventobravo depois da Guerra.$B$BQuando terminamos nossa tarefa, fomos traídos. Os nobres se recusaram a pagar pelo nosso trabalho. Alguns dos Alvanéis mais experientes foram convidados para trabalhar para o governo, mas VanCleef recusou por pura lealdade aos Alvanéis. Ele liderou uma rebelião e deixou a cidade jurando vingança.$b$bBasílio Taborda, um subordinado dele, deve saber mais sobre o que ele planeja. Basílio está preso no Cárcere.", t = "Basílio Taborda"},
    [391] = {ot = "Mate Basílio Taborda e leve a cabeça dele para o Carcereiro-chefe Thelágua no Cárcere.", st = "Vou deixar uma coisa clara, $n: eu não confio em você. Mas, do jeito que a situação está, dificilmente você vai fazer diferença.$B$BÉ o seguinte: pode ir lá falar com o Taborda. Se estiver mesmo do nosso lado, você vai acabar com a raça dele e me trazer a cabeça quando tiver feito o serviço. Se, no fim das contas, você estiver do lado dele e não voltar... aí você vai morrer com o resto dos vermes quando nós te acharmos.", t = "Rebelião no Cárcere"},
    [392] = {ot = "Leve a Descrição da Visita do Taborda Lacrada para Baros Aleixo em Ventobravo.", st = "Nos primeiros anos que passou preso, o Taborda não recebia muitas visitas. Eu imaginei que ele não servisse mais para a Irmandade, por isso tinha sido abandonado.$B$BO que aconteceu foi que, uns meses atrás, isso mudou. Ele começou a receber visitas com frequência... uma, duas vezes por semana. Era um homem estranho, desses tipos quietos. Eu fiquei desconfiado, mas os documentos dele estavam certos.$B$BSegundo a papelada, o nome dele era Maelik. Esta é a descrição dele. Acho que ele não deve visitar o Taborda tão cedo.", t = "Visitante suspeito"},
    [393] = {ot = "Leve a Descrição da Visita do Taborda Lacrada para o Mestre Mathias Shaw em Ventobravo.", st = "Eu não faço ideia mesmo, $n. Mas existe uma pessoa que talvez possa te ajudar, e essa pessoa me deve um favor por... bom, melhor deixar para lá. O Mestre Mathias Shaw, da AVIN, pode ser encontrado no quartel, na Cidade Velha. O Shaw sabe tudo sobre as mancomunações mais espúrias, sobre as negociatas mais questionáveis da cidade.$B$BSe alguém vai ter informações, é ele.", t = "Sombra do passado"},
    [394] = {ot = "Fale com Mathias Shaw em Ventobravo.", st = "Fale com Shaw na Cidade Velha. Diga a ele que Lescobar não representa mais ameaça e conte sobre o seu envolvimento com os planos do Lorde contra a cidade. Tenho certeza de que ele vai ficar contente em contar com mais um herói em Ventobravo.$B$BEle provavelmente vai apresentar você ao príncipe ou algum outro nobre. Não deixe isso subir à sua cabeça, $n. Os nobres pensam que controlam tudo que acontece na cidade, mas algumas coisas ainda dependem de nós.", t = "A cabeça da fera"},
    [395] = {ot = "Fale com Baros Aleixo em Ventobravo.", st = "Ah, eu quase esqueci. O Aleixo apareceu enquanto você estava fora. Ele quer falar com você. Com certeza ele quer informar os nobres a respeito da situação da Irmandade Défias.$B$BUm conselho, $n: se alguém perguntar, eu daria todos os detalhes, exceto que foi você quem matou Lescobar. Acredite em mim. Eu sei como a coisa funciona nesses meios.$B$BQuanto a Trias, bem, não fale dele para ninguém... nunca... se puder evitar.", t = "Fim da irmandade"},
    [396] = {ot = "Entregue o Relatório sobre a Irmandade Défias de Baros Aleixo ao Rei Varian Wrynn na Bastilha Ventobravo.", st = "Eu preparei um relatório para o rei, e acredito que você deveria entregá-lo, junto com um relato de suas descobertas. Não se preocupe, não há duvida de que ele louvará você por cumprir seu dever para com o povo de Ventobravo.$B$BA sua audiência está marcada para logo, então é melhor se apressar, o caminho até a Bastilha Ventobravo é longo.", t = "Uma audiência com o rei"},
    [398] = {ot = "Mate e leve a pata de Olho de Verme para o Executor Zigano em Montalvo para receber a recompensa.", st = "Procura-se: Olho de Verme!$b$bUma fera horrenda, mesmo para um gnoll, Olho de Verme foi sentenciado à morte por seus crimes contra os Renegados. Este bandido desprezível tem roubado cadáveres para o exército do Lich Rei. Olho de Verme foi visto pela última vez saqueando as terras próximas ao Sítio dos Garren, ao norte de Montalvo.$b$bA cidade de Montalvo oferece uma recompensa à alma caridosa que puder eliminá-lo. Mostre a pata do bandido para o Executor Zigano quando a tarefa for concluída.$b$bPiedade é para os fracos.", t = "PROCURA-SE: Olho de Verme"},
    [399] = {ot = "Vá até a casa de Baros Aleixo em Cerro Oeste e procure sua bússola, então a entregue para ele na Praça da Catedral de Ventobravo.", st = "Parece que faz uma eternidade desde que eu era um garoto trabalho na fazenda em Cerro Oeste. Dizem que não há como voltar atrás, e é verdade. Ainda mais no meu caso, a casa da minha família foi incendiada e tomada por ladrões.$b$bEu conversei com o meu pai sobre o destino de algumas das minhas coisas, incluindo a minha primeira bússola. Ele não foi capaz de salvá-la. No entanto, ele diz que ela deve estar escondida na fazenda.$b$bVocê vai encontrar a Fazenda dos Aleixo a oeste do Morro da Sentinela. Você poderia ir lá e recuperar a bússola para mim?", t = "Origens humildes"},
    [400] = {ot = "Entregue as Ferramentas do Gradaço para Beldin Gradaço.", st = "O Beldin Gradaço é o dono da oficina mecânica daqui e é o maior especialista em máquinas de cerco que há! Mas ele pega pesado com as ferramentas. Juro que ele quebra mais chaves de arco voltaico do que eu consigo repor!$B$BAcabamos de separar o último pedido de ferramentas que ele enviou. Se você entregar o pedido para ele, tenho certeza de que o bom e velho Gradaço vai retribuir à altura.$B$BA loja dele se chama Garagem do Gradaço e fica a nordeste de Kharanos. Lá é um ponto de encontro de veteranos de máquina de cerco daqui, então fique $Gatento:atenta;, pois pode aparecer alguma oportunidade boa para você.", t = "Ferramentas para Gradaço"},
    [404] = {ot = "Traga 7 Garras Pútridas para o Necroguarda Dinis em Montalvo.", st = "O Flagelo se infiltrou nas Clareiras de Tirisfal e infestou a área a oeste de Montalvo, perto da antiga ponte.$B$BVá e expulse os mortos podres e cadáveres assolados que encontrar. Vasculhe os ossos que sobrarem e me traga suas garras pútridas. Os necroguardas recompensarão você.", t = "Uma tarefa podre"},
    [405] = {ot = "Apresente as Ordens de Sevren a Boanerges Stalactus na Cidade Baixa.", st = "Boanerges Stalactus, um mago de alta patente poderoso ao sul da Cidade Baixa, me incumbiu de enviar um agente verdadeiramente digno contra o Flagelo. Você, $n, será esse agente.$B$BApresente estas ordens a Boanerges. Ele então lhe instruirá sobre a sua missão. Eu não sei os detalhes, mas envolve recrutar um lich desgarrado. E será perigoso.$B$BEntão se prepare, $C. Você não deve falhar.$B$BVocê deve encontrar Boanerges no Distrito da Magia da Cidade Baixa.", t = "O Lich pródigo"},
    [407] = {ot = "Leve a Abóbora Inoculada para o Zelote Escarlate Capturado que esta sendo mantido no porão da Taberna Nó da Forca.", st = "Abóboras inofensivas, certo? As aparências enganam. Se quisermos derrotar os avanços de Arthas ao norte e a infestação humana ao sul, precisamos começar a compreender o potencial integral de nossa dádiva de morte-viva.$b$bCom um pouco de engenhosidade, uma mera abóbora se torna um agente de nossa Dama Sombria. Esta abóbora, inoculada com minha última fórmula, é uma gostosura – e uma travessura também...$b$bOutro zelote escarlate foi capturado e está sendo mantido no porão da Taberna Nó da Forca. Leve esta abóbora para o cretino.", t = "Campos de mágoa"},
    [408] = {ot = "Mate 8 Ancestrais Ululantes e 8 Ancestrais Apodrecidos.$B$BMate o Capitão Dargol, e leve seu crânio para o Magistrado Sevren em Montalvo.", st = "A área dos Moinhos dos Agamand se tornou um refúgio para o Flagelo. O ponto mais protegido é a Cripta da Família Agamand, onde o líder militar local, um esqueleto chamado Capitão Dargol, se estabeleceu. Usando necromancia, ele ressuscitou os ancestrais dos Agamand e planeja usá-los contra nós.$B$BNão podemos permitir isso, e cabe a você detê-los. Vá para a Cripta da Família Agamand e derrote os ancestrais ressuscitados dos Agamand.$B$BE traga-me o crânio do Capitão Dargol.", t = "A cripta da família"},
    [409] = {ot = "Obtenha uma Vela de Sinalização.$B$BEvoque e mate Lillith Nefara.$B$BFale novamente com Tertuliano em sua ilha.", st = "Você diz que não está sob o jugo do Lich Rei, e que o encantamento que Boanerges colocou no meu livro corrobora isso. Mas, antes que eu acredite nisso, preciso de uma prova de que você é $gum inimigo:uma inimiga; do Flagelo.$B$BExiste um antigo altar manchado de sangue ao sul da costa desta ilha. Ele é usado por uma poderosa agente do Flagelo, Lillith Nefara.$B$BPegue uma Vela de Sinalização desse caixote. Acenda-a no altar e Lillith despertará. Destrua Lillith e eu acreditarei que você é $gum adversário:uma adversária; do Lich Rei.", t = "Prova de lealdade"},
    [411] = {ot = "Leve a Gema Etérea para Boanerges Stalactus na Cidade Baixa.", st = "Leve esta Gema Etérea para o meu velho amigo Boanerges. Ela permitirá que nos comuniquemos... Eu tenho muito o que tratar com ele.", t = "A volta do Lich pródigo"},
    [412] = {ot = "Leve 8 Rodas de Reestabilização e 8 Equipamentos Giromecânicos para Razzle Molavivaz em Kharanos.", st = "Ao analisar a situação de Gnomeregan mais a fundo, parece que nós não só falhamos em erradicar os troggs, como também transformamos a maior parte da raça gnômica em gnomos leprosos do mal.$b$bOzzie e eu planejamos reverter esse efeito horrível com a nossa mais recente invenção: o Recombobulador. A máquina está quase completa, mas nós estamos desesperados atrás de rodas de reestabilização e equipamentos giromecânicos. Recupere alguns para nós com os gnomos leprosos na frente de Gnomeregan.", t = "Operação remendão"},
    [413] = {ot = "Entregue o Barril de Cerveja Tremeluz para o Montanhista Cervevada.", st = "Eu gostaria muito que meu irmão Wellart provasse da minha nova cerveja, a Cerveja Tremeluz. Ele é montanhista e está aquartelado na torre de guarda do sul, uma das duas torres na fronteira do Loch Modan.$B$BEle não é cervejeiro como os outros Cervevada, mas adora tomar umas e outras, e tenho certeza de que vai adorar esta aqui.$B$BVocê poderia entregar esse barril de Cerveja Tremeluz para ele?", t = "Cerveja Tremeluz"},
    [414] = {ot = "Entregue o Barril de Cerveja Tremeluz para o Montanhista Kadrell.", st = "Venho bebendo dessa tal cerveja Tremeluz que meu irmão fez – que coisa boa! Quero que um montanhista camarada meu também prove. O nome dele é Kadrell, e ele costuma patrulhar a estrada que corta Thelsamar, no Loch Modan.$B$BPara chegar a Thelsamar, vá para sudeste, atravesse o túnel e, então, quando chegar a uma bifurcação, pegue a estrada a nordeste que leva direto a Thelsamar.$B$BEntregue este barril de Tremeluz para o montanhista Kadrell e veja o que ele acha da cerveja!", t = "Cerveja para Kadrell"},
    [416] = {ot = "Leve 12 Orelhas de Ratatúnel para o Montanhista Kadrell em Thelsamar.", st = "Estamos com um baita problema de infestação no oeste. Kobolds Ratatúnel se mudaram para os contrafortes, fazendo tocas e sujando nossas terras!$B$BQueremos que eles sejam eliminados. Cace-os, traga-me as orelhas dele e ganhe sua recompensa.$B$BVocê pode encontrar kobolds Ratatúnel e suas tocas a oeste de Thelsamar, espalhados ao longo da encosta da montanha.", t = "Caça ao rato"},
    [417] = {ot = "Mate o Ronhagarra.$B$BEntregue a Pata Sarnenta do urso e o Diário de Hildelve para o Piloto Pisafundo.", st = "Hildelve escreveu no diário que foi atacado pelo Ronhagarra, um \"imenso urso Garra de Gelo\". Apesar de ferido gravemente pela fera, conseguiu espantá-la.$B$BA julgar pelo estado do corpo de Hildelve, Ronhagarra provavelmente voltou em seguida para matá-lo.$B$BAinda assim, Hildelve ainda teve forças para anotar no diário o derradeiro pedido:$B$BVingança contra Ronhagarra.", t = "A vingança do piloto"},
    [418] = {ot = "Leve 3 pedaços de Carne de Urso, 3 Tripas de Javali e 3 Linfas de Aranha para Vidra Fornalenha, de Thelsamar.", st = "Sempre tem uma barriga roncando aqui em Thelsamar: crianças que correm o dia inteiro, operários dos sítios arqueológicos que voltam de um dia de trabalho... Nossos chouriços são muito famosos, já provou?$b$bNão? Bem, por estas bandas, ninguém ganha um prato de comida de graça, e não pense que você vai ser exceção só por ser $Gum:uma; $c $Gtodo:toda; chique.$b$bEu vou precisar de carne de urso, tripa de javali e linfa de aranha. Arranje os ingredientes, e Vidra trata de cozinhar!", t = "Chouriço de Thelsamar"},
    [419] = {ot = "Encontre o piloto Hildelve.", st = "Meu amigo Mori Hildelve, que também é piloto de máquina de cerco, desapareceu nas montanhas. Nós estávamos em campo procurando um minério raro para fazer pólvora de alta qualidade. Mas, durante as buscas, ele subiu um barranco com a máquina e o motor acabou explodindo!$B$BMori tinha certeza de que havia minério naquela serra, então me pediu para ficar vigiando as máquinas de cerco e seguiu a pé, procurando.$B$BMas isso já faz dias, e eu ouvi uns grunhidos alarmantes nas colinas à noite. O Mori é duro na queda, mas estou preocupado.$B$BPor favor, $n, encontre meu amigo.", t = "O piloto perdido"},
    [420] = {ot = "Entregue o relatório de Grolin para Senir Barbabranca em Kharanos.", st = "Os troggs no túnel são extremamente hostis e não demonstraram a mínima hesitação em atacar os viajantes que tentam atravessar. Você parece $Gdurão:durona; o suficiente, provavelmente vai ficar bem.$b$bAonde ir? Se você quiser falar com Senir, vai encontrá-lo em Kharanos.$b$bAtravesse o túnel e, depois que sair do outro lado, continue seguindo a estrada, que vai direto para Kharanos.", t = "Observações de Senir"},
    [421] = {ot = "Dalar Tessalba, do Sepulcro, quer que você mate 5 Grenhalvas Lunafúria.", st = "Lady Sylvana encarregou Varimatras com a conquista das terras humanas e enânicas ao sul.$b$bMas aquele idiota, o Arugal — charlatão de Dalaran e agora besta amaldiçoada da Bastilha da Presa Negra — causou estragos com sua magia imprudente na fortaleza estratégica da Floresta de Pinhaprata.$b$bEu preciso de alguém com habilidade em combate para me ajudar a limpar a bagunça do Arugal. Prove seu valor a mim matando 5 grenhalvas lunafúria. Os monstros miseráveis podem ser encontrados fora da estrada, descendo colina abaixo.", t = "Prove seu valor"},
    [422] = {ot = "Recupere o Remédio de Arugal para Dalar Tessalba, do Sepulcro.", st = "Eu não faço ideia de como Arugal ganhou aceitação dentro do Kirin Tor. Seu conhecimento de feitiços era tão transparente quanto um frasco de vidro soprado.$b$bO que importa agora é descobrirmos exatamente que magia Arugal usou para que eu possa virá-la contra ele e capturar a Floresta de Pinhaprata para a Dama Sombria.$b$bArugal ficou primeiro na fazenda de trigo ao norte da ponte. Um dos Sicários relatou ter visto alguns grimórios, mas não conseguiu pegá-los. Recupere para mim o feitiço intitulado Remédio de Arugal desses livros.", t = "A loucura de Arugal"},
    [423] = {ot = "Leve 6 Grilhões de Glutão e 3 Grilhões Almanegra para Dalar Tessalba, no Sepulcro.", st = " Depois de examinar o trabalho de Arugal, minhas piores suspeitas se confirmaram. O velho não era qualificado nem para limpar os penicos de Dalaran, muito menos para representar o Kirin Tor em sua hora mais terrível. Tolos!$b$bArugal usou itens encantados para reforçar sua magia fraca. Eu preciso examinar esses itens em primeira mão. Siga em frente e mate glutões Lunafúria e almanegras Lunafúria até que você tenha coletado o suficiente de seus grilhões encantados para a minha pesquisa. Aquelas criaturas vis foram avistadas ao norte e ao leste.", t = "A loucura de Arugal"},
    [424] = {ot = "Mate Severo, o Pálido, e leve sua cabeça para Dalar Tessalba no Sepulcro.", st = "De fato, levarei mais tempo do que eu pensava para descobrir os segredos obscuros por trás dos encantos que Arugal estava usando.$b$bMas, enquanto isso, preciso que você cuide de um probleminha que nossos Espreita-trevas descobriram. Parece que Arugal deixou sua magia se espalhar para a Mina Elenfunda, nas colinas a sudeste.$b$bA mina seria um bom recurso para o avanço de Varimatras.$b$bQuero que você decapite o capataz contaminado na mina, Severo, o Pálido. Com ele morto, a mina será nossa.", t = "A loucura de Arugal"},
    [425] = {ot = "Mate Ivar, o Imundo, e leve a Cabeça de Ivar para Rane Yorick, que está na Plantação do Ivar.", st = "Meu irmão Quintino e eu fomos encarregados de reconhecer a Floresta de Pinhaprata e nos reportar ao Alto-executor Hadrec. Mas não chegamos longe. Quando estávamos passando por esta fazenda, fomos atacados pelo carniçal Ivar, o Imundo.$B$BNós escapamos de Ivar, mas ele atacou gravemente o Quintino. Ele está se curando com poção que você deu a ele, mas Ivar pode retornar antes de Quinn se recuperar.$B$BMatar Ivar para que Quintino tenha tempo de se curar. Ivar, geralmente, fica no celeiro, esperando eu baixar a minha guarda.", t = "Ivar, o Imundo"},
    [426] = {ot = "Colete 5 Costelas Carcomidas e 3 Crânios Enegrecidos, depois fale novamente com o Necroguarda Dinis em Montalvo.", st = "O Flagelo vem tentando estabelecer uma base nos Moinhos dos Agamand. Se eles conseguirem, poderão lançar mais ataques em Tirisfal.$B$BAs ordens foram dadas. O Flagelo deve ser erradicado dos Moinhos.$B$BVá até os Moinhos. Reúna costelas carcomidas dos soldados Range-ossos e dos soldados do Crânio Partido e crânios enegrecidos dos osteurgos Olhonegro.$B$BPara chegar aos Moinhos, siga a estrada a oeste. Depois de cruzar a ponte, vá para o norte na próxima bifurcação e siga nessa direção. Quando você avistar os moinhos, a batalha vai começar.", t = "Os moinhos invadidos"},
    [427] = {ot = "O Executor Zigano, de Montalvo, quer que você mate 10 Guerreiros Escarlates.", st = "Os documentos que o Executor Arren forneceu são exatamente a vantagem que precisávamos em nossa batalha contra a maldita Cruzada Escarlate. Agora sabemos suas localizações exatas nas Clareiras de Tirisfal.$b$bMas a Necroguarda tem preocupações maiores. O exército do Lich Rei cresce em número a cada noite. Precisamos de alguém com \"iniciativa\" como você para mandar a Cruzada Escarlate para a cova.$b$bProve que você é capaz de servir à Dama Sombria e vá para oeste, para a torre que fica depois da Fazenda dos Solliden, e mate 10 guerreiros escarlate.", t = "Guerra à Cruzada Escarlate"},
    [429] = {ot = "Junte 3 Corações Descoloridos de Worg e leve-os para o Boticário Renferrel no Sepulcro.", st = "Meu irmão Quintino foi ferido gravemente pelo carniçal Ivar, o Imundo, e eu não sei se ele vai conseguir se curar direito sem ajuda alquímica. Embora eu não seja boticária, sei que é possível fazer poções de cura com corações descoloridos de worgs.$B$BJunte esses corações e leve-os para o Boticário Renferrel no Sepulcro, ao sul. Depois volte aqui com a poção.$B$BVocê vai encontrar muitos worgs no caminho daqui para o Horto dos Maldonado, a leste.", t = "Corações selvagens"},
    [430] = {ot = "Leve a poção para Quintino Yorick na Plantação do Ivar, ao norte do Sepulcro.", st = "Aqui está a poção para ajudar Quintino Yorick a se curar.$B$BAgora, se me dá licença, preciso voltar ao meu trabalho de suma importância...", t = "Reencontrando Quintino"},
    [432] = {ot = "Mate 6 Batecrânios Pedraqueixo para o Encarregado Pedracenho na Pedreira Gol'Bolar.", st = "Malditos troggs! Viraram meu sítio de cabeça para baixo! Vê só, lá se vai mais um barril de pólvora!$b$bAh, como eu queria ir até lá e esganar cada um daqueles pescocinhos de macaco magro! Quero acabar com todos!$b$bIsso não faz nada bem para a minha saúde... Muito stress, muita raiva... E o que eles deixaram para mim? Nada!$b$bEu daria cabo de todos eles sozinho, mas a minha mira não é mais a mesma. Então você é quem vai lá na pedreira para acabar com essa cambada de patifes! Pago bem! É pra matar mesmo, hein?", t = "Malditos troggs!"},
    [433] = {ot = "Mate 10 Quebraossos Pedraqueixo para o Senador Mehr Sacrapetra na Pedreira Gol'Bolar.", st = "Como membro do Senado e da Liga dos Exploradores, encarreguei-me de cuidar desta parte da infestação de troggs que assola nossas terras.$b$bSem o menor cabimento, eles causaram a maior desordem na Pedreira Gol'Bolar. Estávamos cavando as profundezas da terra quando, de repente, eles minaram como água lá de dentro, destruindo nossos equipamento e espantando os mineradores. Não há muito o que fazer além de exterminar todo o bando, reconstruir o que se estragou e voltar ao trabalho.$b$bSe você me ajudar com os troggs, receberá uma recompensa à altura.", t = "O funcionário público"},
    [434] = {ot = "Fiquei no jardim até que Lorde Gregor Lescobar e Marzon, a Lâmina Silente conversem. Depois, mate ambos antes de falar novamente com Elling Trias em Ventobravo.", st = "Vou pôr o disfarce no robô-espião e depois ele vai falar com Lescovar. Duvido que vá ter problemas para passar pelos guardas.$B$BEnquanto você estava buscando os materiais para mim, já cuidei de avisar a Marzon que já era hora dele e Lescovar se reencontrarem. Até deixei escapar umas informações falsas.$B$BLescovar vai dispensar os guardas e esperar Marzon aqui fora, no jardim. Depois que você entreouvir alguma coisa sobre Défias, ataque. Tem que matar os dois antes que os guardas retornem! Quando terminar, fale com Trias.", t = "O ataque!"},
    [435] = {ot = "Escolte Orlando a salvo dos lobos até encontrar-se com Rane Yorick.", st = "Os lobos do lado de fora não vão embora, e me olham com maldade cada vez que eu ponho o pé para fora daquela porta. Eles devem estar com muita fome para me considerar uma refeição aceitável.$B$BPreciso me reportar à minha colega, a Sicária Rane Yorick. E para chegar até ela, vou precisar de sua ajuda para sobreviver aos lobos.$B$BPor favor, me escolte! E como tem muitos lobos lá fora, teremos mais chance de conseguir se você trouxer amigos para ajudar...", t = "Uma escolta para Orlando"},
    [436] = {ot = "Fale com o Explorador Machadeiro.", st = "O Prospector Bandaferro lidera uma escavação de ruínas antigas a leste do lago. Nos últimos tempos, o progresso tem sido lento, ainda mais se considerarmos todos os suprimentos que mandamos para ele.$B$BBandaferro é um anão honesto e durão que se importa com os resultados, o que me deixa com receio de que haja forças trabalhando contra ele.$B$BVá à escavação de Bandaferro e fale com Magmar Machadeiro. Ele cuida dos detalhes da expedição e saberá o que está atrasando o processo.$B$BPara chegar ao sítio de escavação, contorne a ponta sul do lago e depois rume para leste.", t = "Sítio de Escavação de Bandaferro"},
    [437] = {ot = "Mate gnolls Putricouro nos Campos Estéreis.$B$BQuando Vergasta aparecer, mate-a.$B$BLeve a Essência de Vergasta para o Alto-executor Hadrec no Sepulcro.", st = "Os relatórios iniciais dos batedores de Pinhaprata mostram que os Putricouro têm uma base na velha fazenda ao norte, os Campos Estéreis. Já mandamos pequenas investidas contra eles, mas eles sempre recebem reforços da banshee Vergasta, que usa sua magia para nos derrotar.$B$BQueremos que Vergasta seja eliminada.$B$BVá aos Campos Estéreis e ataque os Putricouro. Se não vir Vergasta, vá matando os Putricouro até que ela apareça, e então, derrote-a.$B$BA essência dela virará pó. Traga o pó como prova.", t = "Os Campos Estéreis"},
    [438] = {ot = "Vá aos Campos Apodrecidos.$B$BDescubra o motivo pelo qual o Flagelo está lá.", st = "$n, descobrimos um novo covil do Flagelo: os Campos Apodrecidos. Os campos ficam a leste do Sepulcro, e o território é fortemente patrulhado pelos Putricouro e outros mortos-vivos.$B$BDeve haver um motivo para que o Flagelo ocupe a área. Vá aos Campos Apodrecidos e descubra por que o Flagelo esta lá.", t = "Os Campos Apodrecidos"},
    [439] = {ot = "Leve o Anel de Deliah para o Alto-executor Hadrec no Sepulcro.", st = "Dentre os cadáveres surge uma mão, descoberta. É a mão de uma mulher, com marcas da peste na pele, mas relativamente fresca.$B$BHá um anel na mão. Removendo-o e inspecionando-o, vê-se a gravação que diz:$B$B\"Para Deliah\"", t = "Pistas dos Putricouro"},
    [440] = {ot = "Leve o Anel de Deliah para o Magistrado Sevren em Montalvo.", st = "Se você quer encontrar o marido ou o ente querido que deu o anel para Deliah... então fale com o Magistrado Sevren em Montalvo. Ele deve ter os arquivos das mortes recentes e, se você tiver sorte, ele pode conseguir descobrir quem é Deliah.$B$BMas eu não teria muitas esperanças. Quem quer que tenha dado o anel a ela provavelmente está morto. E se for morto-vivo, então provavelmente não se importa mais com Deliah.", t = "O anel gravado"},
    [441] = {ot = "Leve o Anel de Deliah para Olavo.", st = "Deliah tinha um marido, Raleigh, que agora mora na Cidade Baixa. Se a Deliah que morava em Montalvo era mesmo a dona deste anel, então Olavo vai saber.$B$BProcure Raleigh no Centro Comercial da Cidade Baixa.", t = "Olavo e a Cidade Baixa"},
    [442] = {ot = "Leve a Cabeça de Thule para o Alto-executor Hadrec no Sepulcro.", st = "Agora chegou a hora de atacar o bastião do Flagelo em Pinhaprata: a Ilha de Fenris.$B$BVocê deve voltar à Ilha e destruir Thule Corvinalle. Quero a cabeça dele!$B$BEsta missão é tão perigosa quanto vital, $n. Você não deve falhar.", t = "Ataque à Ilha de Fenris"},
    [443] = {ot = "Leve 8 garrafas de Linfa de Putricouro para o Boticário Renferrel no Sepulcro.", st = "Antes do ataque à Ilha de Fenris, temos que determinar quem está por trás dos gnolls Putricouro. Nossos boticários acreditam que a origem dessa corja esteja no fluido estranho que corre pelo corpo deles.$B$BVá à Ilha de Fenris, a leste dos Campos Apodrecidos, e colete linfa de Putricouro nos gnolls que encontrar lá. Depois leve a linfa para o Boticário Renferrel, que fica do lado de fora do Sepulcro.", t = "Linfa de Putricouro"},
    [444] = {ot = "Leve a Amostra de Linfa para Boanerges Stalactus, na Cidade Baixa.", st = "Reduzi a linfa que me trouxe e separei seus componentes básicos. Minhas descobertas ainda não são conclusivas, mas consegui determinar que houve magias de bruxo e de necromante envolvidas na criação da linfa.$B$BVou continuar estudando o material e, enquanto isso, quero que você leve uma amostra dela para Boanerges Stalactus, na Cidade Baixa. Boanerges não é boticário, mas seu conhecimento em magia pode nos ajudar a desvendar o mistério dos Putricouro.$B$BAgora vá. Procure Boanerges no Distrito da Magia, na Cidade Baixa.", t = "A origem dos Putricouro"},
    [445] = {ot = "Leve as descobertas do Boticário Joaquino ao Boticário Renferrel na Floresta de Pinhaprata.", st = "O tempo é um luxo ao qual nós, os servos de Lady Sylvana, não podemos nos dar. A esta altura, você há de saber disso muito bem.$b$bComo membro da Real Sociedade de Boticários, tenho o dever de compartilhar meu conhecimento com meus colegas, para que um dia os nossos esforços coletivos resultem na Nova Peste que a Dama Sombria tanto deseja.$b$bLeve essas descobertas para o Boticário Renferrel, que fica no Sepulcro, na Floresta de Pinhaprata. Siga a estrada na direção sul a partir de Montalvo. Ao chegar na Cidade Baixa, siga para o sudoeste.", t = "Entrega na Floresta de Pinhaprata"},
    [446] = {ot = "Leve o Pergaminho de Boanerges para o Boticário Renferrel no Sepulcro de Pinhaprata.", st = "Este icor foi criado por um antigo colega meu: Thule Corvinalle. Ele era um mago jovem e promissor antes da grande guerra, mas quando o Lich Rei subiu ao poder, ele traiu seus irmãos e aliou-se ao Flagelo.$B$BNão sabia que ele ainda estava vivo, nem que liderava os Putricouro em suas incursões contra nós!$B$BConheço muitos dos feitiços dele e posso ajudar a preparar uma poção para combatê-los. Leve este pergaminho com os encantamentos necessários para a poção até o Boticário Renferrel.", t = "Thule Corvinalle"},
    [447] = {ot = "Colete 6 Corações de Urso Cinzento e 6 amostras de Sangue de Pateante e leve-os para o Mestre-boticário Faranello na Cidade Baixa.", st = "Os números de Arthas são impressionantes. Mas, com uma nova praga, poderíamos erradicar o Exército do Flagelo e a infestação humana de uma vez por todas.$b$bMeus estudos provaram que sangue de aranha combinado a uma toxina derivada do coração de um urso cinzento resulta em um elixir mortal. Colete amostras das aranhas da Penumbra Furtiva a noroeste e dos ursos da Floresta de Pinhaprata. Entregue os reagentes ao Mestre-boticário Faranello da Real Sociedade de Boticários, na Cidade Baixa.", t = "Receita mortal"},
    [448] = {ot = "Apresente-se ao Alto-executor Hadrec no Sepulcro.", st = "Antes de lançar um ataque à Ilha de Fenris, apresente-se ao Alto-executor Hadrec. Ele pode ter equipamentos ou informações adicionais de que você vai precisar.", t = "Relatório para Hadrec"},
    [449] = {ot = "Apresente o Relatório do Sicário ao Alto-executor Hadrec no Sepulcro.", st = "Embora Quintino esteja se curando dos ferimentos, quero apresentar o nosso relatório ao Alto-executor Hadrec o mais rápido possível. Temos informações que são vitais para a ocupação de Pinhaprata pelos Renegados.", t = "Relatório dos Sicários"},
    [450] = {ot = "Recupere o Diário do Boticário Berardo em Vilarejo Lenhardente e leve-o ao Boticário Renferrel no Sepulcro.", st = "Você ainda por ser útil para a Real Sociedade de Boticários, $n.$b$bQuando Arugal lançou sua magia vil na floresta, amaldiçoou um dos nossos membros mais promissores, o Boticário Berardo. Agora que virou um servo irracional de Arugal, Berardo é inútil para nós. Mas suas descobertas podem valer a pena. Ele estudava uma praga antiga que exterminou toda a vida aquática no Espelho de Lordaeron anos atrás.$b$bEncontre o Diário de Berardo em seu escritório na Estalagem de Vilarejo Lenhardente e leve-o ao Boticário Renferrel.", t = "Receita mortal"},
    [451] = {ot = "Leve 6 amostras de Musgo de Rastejante do Lago, 6 amostras de Musgo de Sorrateiro do Lago e um Tumor Endurecido para o Mestre-boticário Faranello na Cidade Baixa.", st = "De acordo com o Diário de Berardo, o musgo dos Sorrateiros e Rastejantes do Lago pode ser útil em nossa missão de criar uma nova praga. Essas criaturas habitam as ilhas do Espelho de Lordaeron, a leste.$b$bEle também menciona um Tumor Endurecido muito raro que descobriu em um murloc Pinavil. Aparentemente, o tumor é tão raro que Berardo só conseguiu um.$b$bColete amostras do musgo e do raro tumor endurecido, e leve-as ao Mestre-boticário Faranello, da Cidade Baixa.", t = "Receita mortal"},
    [452] = {ot = "Ajude a Sicária Fabiana a eliminar o Conselho de Lenhardente.", st = "Você chegou aqui na hora certa, $n!$b$bO Conselho de Lenhardente voltará a qualquer momento. Arugal tem outros assuntos para tratar na fortaleza. Ele faz do Conselho meros fantoches para manter os asseclas estúpidos de Lenhardente sob seu controle. Mas acredito que, sem a orientação do Conselho de Lenhardente, os filhos de Arugal se voltarão contra o mestre.$b$bNão consigo cuidar de todos eles sozinha. Preciso da sua ajuda. Juntos, podemos acabar com o Conselho para a Grande Dama Sylvana.", t = "Emboscada de Lenhardente"},
    [453] = {ot = "Encontre o Vulto Sombrio. Suas pistas:$B$BEle não é nativo de Vila Sombria.$B$BÉ uma pessoa nervosa e agitada.$B$BEle deixou Vila Sombria e seguiu para o oeste.", st = "Boa sorte, $n. Espero que você encontre o sujeito, e espero que ele esteja vivo.$B$BSe ele deixou a segurança de Vila Sombria, então pode ter se tornado presa das feras selvagens.", t = "À procura do Vulto Sombrio"},
    [454] = {ot = "Fale com Miran.", st = "A gente viajava para cima e para baixo entregando barris de pólvora até o... acontecido. Agora, temos que dividir o trabalho: Miran leva os barris e eu fico vigiando os restantes.$b$bMas não me sinto seguro em deixar o Miran levar o restante do carregamento sozinho. Quando ele estiver pronto para partir, você poderia escoltá-lo nessa próxima viagem?", t = "O rescaldo da emboscada"},
    [456] = {ot = "Mate 7 Sabres-da-noite Jovens e 4 Javalis-espinho Jovens e fale novamente com o Conservador Ilthalaine.", st = "Saudações, $n. Meu nome é Conservador Ilthalaine. Meu propósito em Umbravale é garantir que o equilíbrio da natureza seja mantido.$b$bEste ano, as chuvas de primavera foram inclementes e, enquanto algumas feras se deleitavam, outras sofriam.$b$bInfelizmente, a população de sabres-da-noite e porcos-espinho cresceu de tal maneira que, se não a reduzirmos, Umbravale não terá comida suficiente para todas as criaturas. Vá, jovem $c, reduza a população de porcos e sabres para que a harmonia da natureza seja mantida.", t = "O equilíbrio da natureza"},
    [457] = {ot = "O Conservador Ilthalaine precisa que você mate 7 Sabres-da-noite Sarnentos e 7 Javalis-espinho.", st = "Reduzir a população mais jovem de criaturas aqui em Umbravale foi um bom começo, $n, mas ainda há trabalho a fazer.$b$bOs recursos da floresta se esgotarão rapidamente se o problema não for resolvido. Matar feras da natureza é um mal necessário para o bem de todos os que compartilham a terra. Aventure-se pela floresta e mate sabres-da-noite sarnentos e javalis-espinho para garantir o equilíbrio.", t = "O equilíbrio da natureza"},
    [458] = {ot = "Procure a dríade conhecida como Tarindrella.", st = "Que bom que você está aqui, $c. Notícias estranhas chegaram aos meus ouvidos pelos sussurros dos espíritos da floresta.$b$bA misteriosa protetora dos bosques, Tarindrella, voltou a Umbravale. A presença da dríade não é sentida nas florestas de Kalimdor há anos. Algo certamente está errado se ela voltou a esta terra.$b$bProcure Tarindrella e veja o que ela faz em nosso bosque. Uma das sentinelas relatou tê-la visto a sudoeste de Aldrassil.", t = "A protetora dos bosques"},
    [459] = {ot = "Colete 8 Limos Vis e leve-os para Tarindrella.", st = "Algo maligno está se formando nas florestas de Teldrassil. Procure ao longo das colinas, onde moravam os pacíficos pelursos. Eles abandonaram suas casas e estão se reunindo sob o nome da tribo Masca-pinho.$b$bApenas a corrupção do maligno Limo Vil poderia causar tal transformação. Os capetas e capetinhas infestaram a área e estão ameaçando os moradores de Umbravale. $b$bConfronte esses capetas e tinhosos, $n, e veja se eles foram de fato apanhados pelo encantamento do maligno limo vil.", t = "A protetora dos bosques"},
    [460] = {ot = "Leve a Cabeça de Alaric ao seu túmulo.", st = "Você não me parece um Putricouro. Que bom. Já tinha perdido as esperanças...$B$BMeu nome é Alaric, e um dia já fui o guarda-costas e o criado principal de Thule. Ele usou sua magia para me \"proteger\" da Peste de Morte-viva, mas em vez disso seu feitiço me deu uma vida-morta da qual não posso escapar. E depois de criar os malditos gnolls Putricouro, Thule me decapitou... e deu minha cabeça aos gnolls como brinquedo!$B$BPor favor, leve-me ao meu corpo. Acho que os gnolls o enterraram aqui no Castelo Fenris, perto do estábulo, em um túmulo não identificado.", t = "Descanse em pedaços"},
    [461] = {ot = "Leve Alaric para a alcova escondida.", st = "Sei de um nicho escondido dentro da bastilha que guarda algo muito precioso para Thule e seus antigos colegas. Também guarda algo que você pode achar útil. Leve-me até lá!$B$BA alcova fica na torre sudoeste da bastilha, atrás de uma prateleira empoeirada.$B$BPegue meu corpo, mas deixe minhas botas. Elas nunca me serviram mesmo...", t = "O nicho escondido"},
    [463] = {ot = "Encontre o Verdião.", st = "Você já ouviu falar do Verdião? Não está procurando por ele, está? Se estiver, enlouqueceu. Mas quem sou eu para impedir $gum:uma; $gtolo:tola; de encontrar a morte?$B$BSe você está mesmo procurando aquela fera, pode encontrá-lo no pântano, a leste da estrada onde há a bifurcação para Dun Modr. Ele está por lá entre os crocodilos... e coisa pior!$B$BE deixe seu dinheiro aqui. Você não vai precisar dele aonde está indo... e não vai querer lascar o dente do velho Verdinho no seu dinheiro quando ele te cortar ao meio, não é?", t = "O Verdião"},
    [470] = {ot = "A bolsa de Cida está em uma das gosmas na Tumba dos Barbaférreos. Recupere a bolsa e leve de volta para ela no Porto de Menethil.", st = "Na minha visita semanal à Tumba dos Barbaférreos, fui atacada por gosmas medonhas e gotejantes! Naturalmente, entrei em pânico, tchê.$b$bAtirei minha bolsa para cima de uma delas, mas bah, não aconteceu nada! A gosma só sugou a bolsa para dentro... Felizmente, isso me deu tempo de fugir.$b$bA má notícia é que preciso muito do que está na minha bolsa!$b$bNão sei em que gosma atirei minha bolsa... todas pareciam iguais! A Tumba dos Barbaférreos fica a nordeste daqui, perto de Dun Modr. Muito obrigada, gur$Gi:ia;!", t = "Escavando a Gosma"},
    [471] = {ot = "Colete 6 Peles de Crocolisco Gigante e leve-as para Iago Halberque no Porto de Menethil.", st = "Mandei meu aprendiz ao pântano para esfolar alguns dos nossos famosos crocoliscos gigantes do Pantanal. Quando ele não voltou, saí para procurá-lo... Digamos apenas que a visão que encontrei não foi nada bonita.$b$bA parteira diz que ele deve sobreviver, mas, nesse meio tempo, ainda preciso das minhas peles!$b$b...Se você quisesse matar mais algumas das feras, eu não me oporia, depois do que elas fizeram. Você encontrará os crocoliscos ao norte da costa, além das choupanas dos murlocs.", t = "Deveres de aprendiz"},
    [475] = {ot = "Encontre Garyol Talvethren no Vilarejo Brisastral.\n", st = "Uma leve brisa sopra da floresta.$b$bGaryol Talvethren trabalha como Grande Guardião para os hibernantes Druidas do Gadanho na Gruta de Ban'ethil. O trabalho dele como protetor escolhido dos Adormecidos é garantir a segurança destes para que seus pactos com Ysera sejam cumpridos.$b$bMas há muito não recebo notícias de Garyol e isto muito me preocupa. Vá para leste do Vilarejo Brisastral e traga alguma notícia de Garyol para que minhas preocupações acabem. Preciso saber que meu sonhador confrade dorme em segurança.", t = "Uma leve brisa"},
    [476] = {ot = "Fale com Athridas Mantursino em Dolanaar.", st = "A tribo dos Masca-pinhos foi corrompida!$b$bOs pelursos, antes pacíficos, agora se voltaram contra os protetores da floresta. Eles me espreitaram no caminho para a Gruta de Ban'ethil e foram pilhar o Vilarejo Brisastral. O líder deles, Ursal, o Espancador, está usando os malignos poderes do limo vil para enlouquecê-los.$b$bEstou muito ferido para voltar e dar esta grave notícia para Athridas. Você precisa completar esta tarefa, jovem $c. Tudo que podemos fazer é torcer para que os loucos Masca-pinho não tenham chegado a Ban'ethil!", t = "Corrupção Masca-pinho"},
    [477] = {ot = "Recupere o conteúdo de um dos caixotes dos teurgos de Dalaran. Você vai encontrar o Vilarejo Lenhardente ao sul.", st = "Como você deve saber, a cidade de Lenhâmbar resiste como fonte de resistência humana, principalmente por causa do apoio que recebem dos teurgos de Dalaran.$b$bNão sei qual é o plano, mas o interesse deles em uma vila remota como Lenhâmbar indica que o lugar deve ter uma importância maior.$b$bEstão enviando carroças com caixotes de suprimentos a partir de Eira dos Montes. Vários desses suprimentos chegam a um pequeno acampamento a norte do Vilarejo Lenhardente. Recupere o conteúdo de um caixote e traga-o para mim.", t = "Cruzando fronteiras"},
    [478] = {ot = "Leve o estranho pingente para o Sacerdote Sombrio Allister, no Sepulcro.", st = "<Você retira o pingente do caixote e substitui a tampa.>", t = "Mapas e runas"},
    [479] = {ot = "Obtenha 8 Pingentes de Dalaran para o Sacerdote Sombrio Allister, no Sepulcro.", st = "Dalar está tentando localizar a fonte do lançamento do feitiço do teurgo. Por ora, precisamos fazer todo o possível para retardar o avanço deles...$b$bCom certeza os conjuradores, magos e protetores estão carregando os pingentes. Recupere-os.$b$bPegue a estrada principal para o sul e a bifurcação leste para Lenhâmbar.", t = "Investigações de Lenhâmbar"},
    [480] = {ot = "Mate o arquimago de Dalaran, depois leve o cajado dele para o Sacerdote Sombrio Allister, no Sepulcro.", st = "Um arquimago de grande poder está supervisionando a reativação do foco de energia meridiana. Com o progresso que fizeram até agora, nossa única esperança é matá-lo. Vai ser difícil, pois com certeza ele é protegido por muitos outros magos e guardiões.$b$bVá e acabe com ele rapidamente. Quando ele estiver morto, traga o cajado dele para mim. Vá.", t = "O tecelão"},
    [481] = {ot = "Leve o pingente inscrito em runas para Dalar Tessalba, no Sepulcro.", st = "Leve o pingente para Dalar Tessalba, talvez ele consiga descobrir quais são os planos dos teurgos.", t = "Análise de Dalar"},
    [482] = {ot = "Fale com o Sacerdote Sombrio Allister, no Sepulcro.", st = "Claro! Com é que eu fui me esquecer?$b$bLenhâmbar foi um dos lugares marcados pelo Kirin Tor, porque abriga um foco de energia meridiana latente. Os teurgos devem estar planejando reativar o foco e usar as energias para algum propósito maior.$b$bNão podemos permitir quer isso aconteça...$b$bVai ser necessário um grande volume de força para ativar as energias meridianas da cidade. Se roubarmos os pingentes dos teurgos, nós conseguiremos deter o progresso deles.$b$bLeve essa informação para Allister, ele vai decidir o que fazer.", t = "As intenções de Dalaran"},
    [483] = {ot = "Recupere as Relíquias do Despertar e leve para Athridas Mantursino, em Dolanaar.", st = "Invasores Masca-pinho foram vistos saqueando a Gruta de Ban'ethil, a oeste.$b$bOs druidas adormecidos ficarão presos dentro do Sonho Esmeralda por toda a eternidade, inconscientes de seus destinos, a não ser que ajudemos. O delicado ritual de hibernação não pode ser interrompido sem as Relíquias do Despertar.$b$bVá à Gruta e recupere o Talismã de Garra de Corvo, o Cálamo de Pena Negra, a Safira do Céu e a Runa da Nidificação. Os druidas as guardam em baús sagrados. Traga-as para mim para que eu prepare o ritual do despertar.", t = "As relíquias do despertar"},
    [484] = {ot = "Obtenha $1oa Peles de Crocolisco Jovem para Iago Halberque, no Porto de Menethil.", st = "Sou Iago Halberque, o curtumeiro. Minha peles de crocolisco curadas são muito procuradas, com carregamentos sendo enviados de navio para portos de todo o mundo.$b$bConheceu o Einar? Ele é um dos caçadores que traz peles para mim.$b$bMeu estoque de peles mais macias, de crocoliscos jovens, está meio baixo.$b$bPor conta disso, prometo lhe pagar muito bem por uma pilha dessas peles. Os crocoliscos jovens são encontrados nos Pântanos que ficam logo na saída da cidade.", t = "Crocolisco jovem é que dá pele boa"},
    [486] = {ot = "Mate Ursal, o Espancador, e fale novamente com Athridas Mantursino, em Dolanaar.", st = "É chegada a hora de salvarmos os Druidas do Gadanho. Se falharmos agora, $n, eles estarão perdidos para todo o sempre em seus próprios sonhos.$b$bPrepararei as Relíquias do Despertar e realizarei o ritual. Para que meu trabalho surta efeito, a fera amaldiçoada responsável por esta terrível situação deve ser morta. Só assim o ritual estará completo.$b$bFoi Ursal, o Espancador, quem se intrometeu com o chamado de nossos confrades e é ele quem deve morrer para que eles sejam libertados. Siga até o Acampamento Masca-pinho, a sudoeste, e mate-o.", t = "Ursal, o Espancador"},
    [487] = {ot = "Mate 6 Emboscadores Masca-pinho e fale novamente com a Sentinela Amara Noctívaga fora de Dolanaar.", st = "Devemos manter a estrada para Darnassus segura. Os viajantes que seguem de Dolanaar para Darnassus vêm relatando ataques constantes, feitos por pelursos corrompidos da tribo dos Masca-pinho.$b$bMercadores e informantes utilizam essa estrada diariamente. Não podemos permitir que um bando de ladinos pagãos aterrorizem as pessoas.$b$bEmpunhe suas armas em nome da floresta sagrada, $c. O covil deles fica em algum lugar abaixo desse ponto de observação. Mate seis desses emboscadores Masca-pinho e fale novamente comigo.", t = "A estrada para Darnassus"},
    [488] = {ot = "Leve para Zenn Cascovil, fora de Dolanaar, 3 Presas de Sabre-da-noite, 3 Penas Estrígidas de Coruja e 3 amostras de Seda de Aranha Lenhateia.", st = "$gÁvido:Ávida; por trabalho, estou certo? Por sorte, não existe um dia sequer que eu não anseie por ter $Gum novato:uma novata; $c para cumprir minhas tarefas.$b$bEntenda, $n, posso lhe fazer muito feliz e lhe dar presentes que você nunca sonhou. Mas para isto, preciso de alguns itens.$b$bMeu trabalho na floresta muitas vezes requer certos... reagentes. Consiga-me 3 presas de sabre-da-noite, 3 penas estrígidas de coruja e 3 amostras de seda de aranha lenhateia.$b$bVamos fazer disso o nosso segredinho, $r.", t = "O comando de Zenn"},
    [489] = {ot = "Colete 3 Pinhas Vis e entregue-as para Zenn Cascovil, fora de Dolanaar.", st = "O Conselho da Floresta recebeu notícias de que você ajudou Zenn Cascovil. Os sátiros são inimigos da floresta. Como $Gum:uma; $r, deveria saber que não se deve profaná-la, matando criaturas da Natureza.$b$bVocê deve conseguir redenção perante o Conselho caso pretenda permanecer amig$go:a; de Teldrassil.$b$bEnsine uma lição à Cascovil e você estará $Gredimido:redimida;. Pinhas vis são sementes corrompidas que caem das árvores. Elas produzem uma fumaça verde.$b$bDê algumas para Cascovil. Ele acreditará que você trouxe um petisco para ele.", t = "Consiga redenção!"},
    [490] = {ot = "Shayla Umbrísia, que está na estrada do lado de fora de Darnassus, quer que você lhe leve $1oa Presas de Masca-pinho.", st = "Por ordens estritas das Sentinelas, estou oferecendo uma recompensa pelos Masca-pinho. Eles não são mais amigos da floresta. A corrupção que habita neles tomou suas mentes e os tornou uma ameaça ao nosso povo e às criaturas da clareira.\n\nConforme decretado, você receberá uma recompensa por se livrar dos pelursos que ameaçam Teldrassil. Traga-me as presas deles como prova de seus feitos.\n\nVocê encontrará pelursos concentrados na Ravina de Ban'ethil, a oeste de Dolanaar e ao sul da estrada, e também no Vilarejo Brisastral, a leste.", t = "Recompensa: Pelurso Masca-pinho"},
    [492] = {ot = "Leve a Bebida Especial do Joaquino para o Montanhista Capturado.", st = "De acordo com a necroguarda, outro daqueles montanhistas anões foi capturado. A necroguarda gosta de usar a adega da Taberna Finda Forca como prisão provisória enquanto não é possível dar tratamento \"adequado\" aos prisioneiros.$b$bPor que você não vai lá e descobre se o montanhista capturado gosta deste aperitivo que fiz especialmente para ele? Isso é só um gostinho sutil daquilo que a Dama Sombria está preparando para o resto de Azeroth.", t = "Uma nova peste"},
    [493] = {ot = "Entregue as descobertas do Boticário Renferrel ao Boticário Lindolfo na cidade de Serraria Tarren, que fica no Contraforte de Eira dos Montes.", st = "A Real Sociedade de Boticários está sofrendo enorme pressão da Dama Sombria para desenvolver uma nova peste. Estamos trabalhando diligentemente, mas não fizemos muitos progressos. Acreditamos que conseguiríamos obter sucesso muito mais rápido de compartilhássemos informações entre a sociedade.$b$bPor essa razão, quero que você entregue minhas últimas descobertas ao Boticário Lindolfo, na Serraria Tarren, uma cidadezinha encarapitada no Contraforte de Eira dos Montes. A jornada vai ser longa.$b$bSiga para o sul e mantenha-se nas estradas. Siga as placas atentamente!", t = "Jornada ao Contraforte de Eira dos Montes"},
    [494] = {ot = "Viaje até Serraria Tarren para entregar a mensagem do Sicário Açoute para a Alta-executora Darthalia.", st = "Fique em silêncio e preste atenção, $c.$b$bFui mandado para esta posição com o objetivo de pesquisar a cidade de Eira dos Montes. Minha missão é de reconhecimento. É imprescindível que você leve notícias para a Alta-executora Darthalia na Serraria Tarren imediatamente. Diga-lhe que eu, o Sicário Açoute, enviei a seguinte mensagem:$b$b\"O grito do corvo do oeste chama.\"$b$bSiga a estrada para o leste e preste muita atenção às placas. Vá, vá! Siga para Serraria Tarren, é urgente!", t = "Hora de atacar"},
    [496] = {ot = "Boticário Lindolfo, de Serraria Tarren, quer 10 Línguas de Urso Cinzento e um pouco de Pus de Rastejante.", st = "Ah, mais um dia maldito na Serraria Tarren. Todo esse ar fresco me deixa de mau humor, $n.$b$bO quanto antes nós conseguirmos disseminar a peste entre os humanos daqui, melhor. Realizei estudos extensivos sobre possíveis agentes mortais a ser usados em minhas misturas, mas não tive tempo de coletar todos.$b$bQuer ser útil? Então procure os seguintes itens para mim: dez línguas de urso cinzento e uma coisa muito rara e difícil de achar, pus de rastejante. Ursos e rastejantes podem ser encontrados logo na saída de Serraria Tarren.", t = "Elixir do sofrimento"},
    [498] = {ot = "Krusk, da Serraria Tarren, precisa que você liberte Drull e Tog'thar do Forte do Desterro.", st = "Eu e alguns outros guerreiros fomos enviados pelo Chefe Guerreiro para recuperar um objeto do Desterro e investigar essa tal de Camarilha.$b$bFomos ao Desterro dar uma olhada, um grande número de humanos nos pegou de surpresa. Nós lutamos bravamente, mas eles estavam em número suficiente para nos derrotar. Eles levaram alguns de nós como prisioneiros, mas eu consegui escapar.$b$bO Desterro fica a sudeste daqui, do outro lado do rio. Drull e Tog'thar estão sendo mantidos lá, você precisa ir resgatá-los.", t = "O resgate"},
    [499] = {ot = "Dê o Elixir do Sofrimento a Umpi.", st = "Só vou precisar de um instante para misturar estes componentes no que eu espero que resulte em um Elixir do Sofrimento.$b$bLá vamos nós! Ah, nada ilumina um dia sombrio nestas colinas miseráveis como trazer um pouco de sofrimento ao mundo.$b$bVamos ver se a nossa pequena poção produzirá o efeito desejado.$b$bDê ao meu assistente, Umpi, uma amostra do que a Dama Sombria planejou, tanto para humanos quanto para o Flagelo.", t = "Elixir do Sofrimento"},
    [501] = {ot = "Leve 10 Ampolas de Sangue de Leão da Montanha para o Boticário Lindolfo na Serraria Tarren.", st = "Ah, $n... as flores estão desabrochando em Eira dos Montes, e o ar está tão fresco e vivo. Não posso deixar de me regozijar com a miséria em tudo isso. Olho pela minha janela encardida e anseio pelo dia em que nossa Nova Peste trará ao mundo a morte que ele merece.$b$bPor mais que eu adore ficar sentado refletindo o dia todo, meu dever para com a Dama Sombria me chama. Você poderia me ajudar? Minha pesquisa me leva a acreditar que posso criar a mais esplêndida bebida mortal com o sangue de um leão da montanha. Traga um pouco para mim e vamos nos divertir.", t = "Elixir da dor"},
    [502] = {ot = "Alimente Fido com o Elixir da Dor.", st = "Ah, nada como o cheiro de sangue fresco no sopé dos montes!$b$bAgora vamos misturar um pouco disso e um pouco daquilo e começar a verdadeira diversão! O que eu criei com esse sangue, gosto de chamar de Elixir da Dor. Se meus cálculos estiverem corretos, essa mistura pode ser o começo de algo muito bonito para a Grande Dama Sylvana. Mas precisamos de um teste.$b$bLeve esse elixir para a fazenda no norte dos Campos de Eira dos Montes, que ficam a sudoeste. Vamos ver o que o cachorrinho do Fazendeiro Raí, o Fido, vai achar dessa \"guloseima\".", t = "Elixir da dor"},
    [516] = {ot = "Encontre a Cilada de Beren, mate 6 Mourejantes Corvinalle e 6 Guardiões Corvinalle e depois fale novamente com o Sacerdote Sombrio Allister, no Sepulcro.", st = "Recebi relatos de que um ajuntamento de mortos-vivos estaria se preparando para nos atacar. De posse dessa informação, podemos virar o jogo e atacar primeiro, cortando o mal pela raiz de uma vez por todas.$b$bInfelizmente, meus dados são, na melhor das hipóteses, vagos. Acredita-se que eles estejam escondidos em um local conhecido como Cilada de Beren. Não se sabe ao certo onde fica, mas, ao que tudo indica, é uma caverna nas colinas, perto de um grupo de teurgos de Dalaran.$b$bConfio nas suas habilidades. Encontre e destrua os mortos-vivos.", t = "Cilada de Beren"},
    [527] = {ot = "Mate 6 Lavradores de Eira dos Montes, 6 Fazendeiros de Eira dos Montes, o Fazendeiro Raí e o Fazendeiro Pegaz, depois apresente-se novamente a Darthalia na Serraria Tarren.", st = "Posição de sentido ao me dirigir a palavra, $c.$b$bEu estou sob comando direto de Varimatras. Nós teremos que combater a infestação humana até nossos boticários desenvolverem a nova peste.$b$bInformações nos levam a crer que a cidade de Eira dos Montes está vulnerável. Sua primeira tarefa será sabotar o abastecimento de comida e a infraestrutura.$b$bViaje para o oeste. Saqueie as fazendas mais ao norte, nos Campos de Eira dos Montes. E certifique-se de executar o Fazendeiro Raí e o Fazendeiro Pegaz.", t = "A batalha de Eira dos Montes"},
    [528] = {ot = "Mate 15 Camponeses de Eira dos Montes e apresente-se novamente a Darthalia na Serraria Tarren.", st = "As notícias sobre o ataque nas fazendas ao norte deixaram os moradores da cidade em pânico. Formidável.$b$bSegundo nossos Sicários, os camponeses estão fugindo para os campos na parte sul de Eira dos Montes. Aqueles tolos acham que podem se esconder nos pomares e escapar da morte.$b$bMostre que estão equivocados, $n. Volte aos Campos de Eira dos Montes e vá atrás desses camponeses covardes. Extermine essa gente em nome da Dama Sombria.$b$bDispensad$Go:a;!", t = "A batalha de Eira dos Montes"},
    [530] = {ot = "Mate Valfrido Moray.$B$BLeve as mãos dele para Olavo Nascimento na Cidade Baixa.", st = "Valfrido, um bom amigo em tempos idos, foi o assassino da minha esposa. Embora incapaz de luto, eu anseio pela vingança. Se você matar Valfrido e me trouxer aquelas mãos amaldiçoadas, eu lhe darei uma recompensa.$B$BEu soube que ele estava na Muralha Greymane, na parte sul de Pinhaprata, tentando fugir para o reino de Guilnéas.", t = "A vingança do marido"},
    [531] = {ot = "Entregue a Cabeça do Velho Fumaça para Vyrin Velozvento no Pavilhão dos Andarilhos.", st = "Pela Luz! Não me traga mais essas coisas para o Pavilhão! É insalubre, é incômodo, é in... in... insalubre!$b$bLeve isso lá para fora, tá? Ninguém quer ver esse seu trofeuzinho ensanguentado! É sério!", t = "A vingança de Vyrin"},
    [544] = {ot = "Encontre os traidores e recupere os artefatos, depois volte a falar comigo, $n.", st = "Vim para Serraria Tarren fazer pesquisas, mas agora preciso solucionar uma crise. Quatro Renegados fugiram da Cidade Baixa alguns meses atrás. Viraram as costas para seus irmãos e, o que é pior... roubaram da Dama Sombria.\n\nEsses infelizes arrombaram um cofre e roubaram quatro artefatos, itens que os nossos boticários precisam usar em determinados estudos. Sylvana quer os artefatos de volta.\n\nOs ladrões fugiram para Dalaran, e os teurgos colocaram eles em quarentena no Campo de Internação de Lordaeron.", t = "Invasão da prisão"},
    [545] = {ot = "Mate $1oa Evocadores de Dalaran e $2oa Escravos Elementais, depois fale novamente com o Magus Olharvazio na Serraria Tarren.", st = "Antes de desaparecer misteriosamente, havia uma enorme barreira mágica envolvendo a recém-reconstruída cidade de Dalaran. Não me interessa o que levou tal maravilha mágica a falhar, mas sim os valiosos tesouros mágicos que podem estar escondidos nos arredores recém-revelados da cidade. Vestígios das ruínas sobre as quais a nova cidade foi construída.$B$BA área, porém, é patrulhada pelos magos e seus escravos elementais.$B$BCace-os e retorne quando os números deles estiverem suficientemente reduzidos.", t = "Patrulhas de Dalaran"},
    [546] = {ot = "O Necroguarda Sandoval da Serraria Tarren quer 30 Crânios Humanos de Eira dos Montes.", st = "Ouvi dizer que Darthalia convocou você para a guerra contra os humanos de Eira dos Montes. Que inveja!$b$bEnquanto você estava lá se divertindo, matando humanos, pilhando a cidade, aterrorizando inocentes, fiquei preso aqui na Serraria Tarren, montando guarda.$b$bMas talvez você se compadeça de um velho necroguarda como eu. O negócio é o seguinte: estou colecionando crânios humanos e sei que você vai lutar contra eles durante algum tempo. Traga 30 para mim, garanto que vai valer a pena.", t = "Lembrancinhas da morte"},
    [549] = {ot = "Mate 10 Ladinos da Camarilha e 10 Vigias da Camarilha. Fale novamente com a Alta-executora Darthalia na Serraria Tarren para receber sua recompensa.", st = "Pela autoridade a mim conferida por Lady Sylvana, ordeno a morte de todos os membros da organização conhecida como Camarilha. Os que forem trazidos sob custódia ou feitos prisioneiros serão sumariamente executados. Sabe-se que eles estão se reunindo nas ruínas do Forte do Desterro, a sudeste de Serraria Tarren.$b$bUma polpuda recompensa será concedida a quem trouxer provas dos planos deles à Alta-executora Darthalia.", t = "PROCURA-SE: integrantes da Camarilha"},
    [556] = {ot = "Leve 10 Fichas de Pedra Gasta para o Guardião Bel'varão, na Serraria Tarren.", st = "Um talento notável dos teurgos de Dalaran é a familiaridade com os elementais: criaturas poderosas de outras dimensões. Os teurgos usam fichas mágicas como formar de controlar esses elementais. O Magus Olharvazio gostaria de estudar algumas dessas fichas.$B$BEntre nos territórios dos teurgos de Dalaran, a oeste de Eira dos Montes, e colete as fichas.$B$BVocê vai achar as fichas com qualquer cidadão de Dalaran, mas eu sugiro que você cace no acampamento de internação. É mais seguro que a própria Dalaran.", t = "Fichas de pedra"},
    [557] = {ot = "Leve 4 Braçadeiras do Vínculo à Terra para o Guardião Bel'varão, na Serraria Tarren.", st = "O Magus estará ocupado estudando essas fichas de pedra que você juntou, mas eu sei que, uma hora, ele vai querer amostras da contraparte delas: braçadeiras da vinculação. Elas são presas em torno dos pulsos dos elementais, colocando-os a serviço do mago.$B$BCace elementais nas ruínas de Dalaran e recolha suas Braçadeiras do Vínculo à Terra. O Magus ficará satisfeito com isso.", t = "Braçadeiras da vinculação"},
    [590] = {ot = "Derrote Calvino Murão em Plangemortis.", st = " O quê?$B$BO quê?!$B$BÉ dinheiro que você quer? Eu não te devo nada.$B$BCarta? Que carta? Ah, então vai querer encarar? Está bem, camarada... vem pra mão! Imagina, eu, devendo dinheiro...", t = "Palavra de ladino"},
    [729] = {ot = "Vá para o sul e veja como está o Prospector Trilheiro.", st = "Barbaridade, foi uma honra e tanto quando o Mestre Suiçagris me designou para trabalhar sob a orientação do grande Prospector Trilheiro. Na academia em Altaforja, todos já tinham ouvido falar das grandes descobertas de Trilheiro.$b$bMas o Prospector é um tanto quanto... hã... alheio ao que há em volta.$b$bHavíamos descoberto evidências de uma grande sociedade. Golens horríveis saíram do chão e infestaram o local. Trilheiro nunca pareceu notar. Voltei num upa a Auberdine em busca de ajuda.$b$bPor favor, viaje de vereda até o sul e veja se o Prospector está bem!", t = "O prospector distraído"},
    [730] = {ot = "Vá até Auberdine e procure sinais da equipe de escavação enânica.", st = "Barbaridade, como é bom ver $Gum:uma $c interessad$Go:a; nas grandes maravilhas arqueológicas do nosso mundo.$b$bPor vezes, nosso trabalho é considerado um mero passatempo pelos nossos amigos da Aliança. Mas o que muitos não percebem é que as recentes descobertas em Khaz Modan provaram que uma força grande e poderosa ameaça toda Azeroth, de Lordaeron a Kalimdor.$b$bEstou muito preocupado com a equipe que enviei para Costa Negra, tchê. Eles se fizeram fumaça e não mandam notícias há semanas.$b$bVá até Auberdine e procure uma pista sobre o paradeiro deles.", t = "Problemas na Costa Negra?"},
    [731] = {ot = "Proteja o Prospector Trilheiro enquanto ele procura o fóssil misterioso, depois fale novamente com a Arqueóloga Hollee em Auberdine.", st = "Então, Hollee... ah, é, tu não é a Hollee. Cadê a Hollee?$b$bBah, não interessa. Temos que achar o pincel de pedra... Digo, o fóssil misterioso! Temos que encontrar aquele fóssil. A Liga dos Exploradores em Darnassus vai querer saber o que eu ando fazendo.$b$bMe avisa quando tu estiver pront$Go:a; e vamos caçar aquele pincel... quero dizer, fóssil! Precisamos encontrar algo e escrever para dar uma satisfação à Liga.$b$bEntão, já estás $Gpronto:pronta;, $Gguri:guria;?", t = "O prospector distraído"},
    [741] = {ot = "Leve o fóssil misterioso ao Arqueólogo-chefe Suiçagris em Darnassus.", st = "Então o Prospector quer enviar o misterioso fóssil para a Liga dos Exploradores em Darnassus? Não acho certo deixar Costa Negra sem ele.$b$bAqui, toma, $n, entregue o fóssil misterioso ao Arqueólogo-chefe Suiçagris em Darnassus.", t = "O prospector distraído"},
    [743] = {ot = "Leve 8 Garras de Ventofúria para Ruul Garra da Águia na Aldeia Casco Sangrento.", st = "Obrigado pela atenção de falar comigo, $n. Meu nome é Ruul, guerreiro e instrutor.$B$BVocê atingiu uma idade em que é necessário se preparar para as provas caso deseje se aventurar muito além dos limites de Mulgore.$B$BSe quiser testar sua força, comece procurando as harpias ventofúria a sudeste. Elas fazem seus ninhos nas encostas da montanha, longe da estrada.$B$BElas são um dos nossos inimigos naturais aqui em Mulgore e serão uma boa aferição da sua habilidade.", t = "Perigos das Ventofúria"},
    [744] = {ot = "Reúna 6 Penas Lazúli e 6 Penas Bronze, e leve-as para Eyahn Garra de Águia no Penhasco do Trovão.", st = "$n, em breve meu irmão estará diante do Chefe Casco Sangrento e terei a honra de confeccionar o cocar que ele usará na ocasião.$B$BEu gostaria de lhe pedir um favor, enquanto termino de curtir as tiras de couro. Eu não terei tempo para encontrar todas as penas e queria saber se você não poderia procurá-las para mim.$B$BAs penas das harpias que vivem a norte e a noroeste do Penhasco do Trovão têm o tamanho exato. Preciso apenas de seis penas lazúli e seis penas bronze para finalizar.", t = "Os preparativos da cerimônia"},
    [745] = {ot = "Mate 10 Coureiros Jubalba, 8 Esfoladores Jubalba, e 5 Larápios Jubalba, então fale novamente com Baine Casco Sangrento na Aldeia Casco Sangrento.", st = "$n, não são poucos os conflitos que castigam estas terras. Espero que você não tenha que testemunhar tantas lutas quanto eu. Contudo, há um confronto em que você precisa entrar. Assim, você terá uma ideia de como uma pequena ameaça à terra pode se tornar terrível quando ignorada.$B$BGnolls Jubalba estabeleceram-se ao sul de Casco Sangrento e em uma caverna a oeste. Eles ignoram nossas tentativas de comunicação e abatem os animais selvagens de Mulgore sem nenhum controle.$B$BPalavras já não surtem efeito.", t = "Dividindo a terra"},
    [746] = {ot = "Recolha 5 Picaretas do Prospector.$B$BEm uma forja, esmague as Picaretas do Prospector para criar Ferramentas Quebradas.$B$BLeve 5 Ferramentas Quebradas para Baine Casco Sangrento na Aldeia Casco Sangrento.", st = "Tem uns anões preparando um sítio de escavação a noroeste. Eles acham que a terra esconde segredos, e é verdade, mas abrir buracos e profaná-la não torna ninguém merecedor de seus ensinamentos.$B$BRecolha as ferramentas dos anões, esmague-as e traga-as para mim.$B$BEsmague as ferramentas em uma forja. Tem uma no Penhasco do Trovão, mas qualquer forja serve, até mesmo a do acampamento dos anões.", t = "Escavação enânica"},
    [747] = {ot = "Grull Vento do Falcão na Aldeia Narache quer que você lhe traga 7 Penas de Pinote e 7 pedaços de Carne de Pinote.", st = "Você tem um ar bastante promissor, e vai se provar para a tribo. Talvez em breve você seja bem-vind$Go:a; à grande cidade do Penhasco do Trovão. Mas, para que isso possa acontecer, você precisa se provar para o meu pai, o Chefe Vento do Falcão.$b$bAqui na Chapada Nuvem Vermelha, temos orgulho das nossas habilidades de caça. Taurens caçam por necessidade e por esporte. Nosso suprimento de carne está baixo e também precisamos de penas para as roupas. Cace os pinotes mais próximos e prove seu valor reabastecendo a aldeia.", t = "A caçada começa"},
    [748] = {ot = "Leve 6 Patas de Lobos-da-pradaria e 4 Garras de Pinotes para Mull Chifre Troante em Casco Sangrento.", st = "Goblins e os servos deles macularam nossos poços sagrados! Não podemos permitir isso.$B$BPara purificar os poços, preciso criar um totem de purificação. Em seguida, você o levará até o poço e realizará um ritual de purificação.$B$BPrimeiro vamos criar um totem de purificação para o Poço Casco Invernal. Para isso, vamos precisar da ajuda da terra. Cace lobos-da-pradaria para pegar as patas e pinotes adultos para pegar as garras. Eles ficam a sudoeste daqui.$B$BVolte com as patas e garras, $n.", t = "Água venenosa"},
    [749] = {ot = "Morin Espreita Nuvem quer que você examine o conteúdo de uma caixa de suprimentos na Caravana Devastada.", st = "Há alguns dias, encontramos uma caravana da Empreendimentos S.A. viajando na margem norte do Lago da Ferradura. Nós havíamos perdido dois dos nossos guerreiros em outra batalha, por isso corremos para atacar e destruir a caravana.$b$bDeixamos as caixas de suprimentos, certos de que nossas tochas destruiriam tudo o que fosse de valor, mas como catadores da Empreendimentos S.A. foram vistos perto das carroças queimadas, talvez estejamos errados.$b$bO que você acha de ir até a caravana e examinar o conteúdo das caixas?", t = "A caravana devastada"},
    [750] = {ot = "Grull Vento do Falcão na Aldeia Narache quer que você lhe traga 10 Pelagens de Puma da Montanha.", st = "Um tauren habilidoso na caça sabe que a presa não é um mero troféu. As feras das planícies nos fornecem um meio de sobrevivência. Você causará uma grande impressão nos anciões se puder trazer algumas Pelagens de Puma da Montanha, bastante procuradas e valorizadas. Você pode encontrar essas feras vagando furtivamente pelas colinas ao sul.$b$bNossas crianças precisam de roupas e nossas tendas precisam ser consertadas.", t = "A caçada continua"},
    [751] = {ot = "Entregue os Documentos da Empreendimentos S.A. para Morin Espreita Nuvem perto da Aldeia Casco Sangrento.", st = "Quando a tampa é aberta, um sortimento bem acondicionado de minério e minerais é revelado. Mais uma prova das operações da Empreendimentos S.A. em Mulgore. Você remove uma resma de papéis firmemente atada em cima do minério e dos minerais.$B$BVocê ouve sons de trabalho vindo das colinas a leste, e vê a fumaça que sobe de uma fogueira.", t = "A caravana devastada"},
    [752] = {ot = "Chefe Vento do Falcão quer que você procure a mãe dele perto do poço a sudeste da Aldeia Narache.", st = "Todos os membros da tribo compartilham a harmonia da vida. Vivemos juntos e trabalhamos juntos.$b$bNosso compromisso mútuo envolve um alto grau de responsabilidade. Peço a você agora uma humilde tarefa.$b$bMinha mãe saiu esta manhã para buscar água do poço a sudeste de Narache. Já faz algum tempo agora. Talvez você possa ver como ela está por mim enquanto cuido de alguns assuntos da tribo aqui?", t = "Uma humilde tarefa"},
    [753] = {ot = "Pegue uma Jarra d'Água do poço.$b$bLeve a Jarra para o Chefe Vento do Falcão na Aldeia Narache, que fica a noroeste do poço.", st = "Percorri muitos caminhos ao longo da vida, e essas pernas velhas já não têm o mesmo vigor de antes. Ainda posso cumprir meus deveres na tribo. Às vezes, uma velha só precisa de um pouco mais de tempo para fazer a tarefa.$b$bMas você me parece $Gum:uma; $c entusiasmad$Go:a;. Vamos colocar um pouco dessa vitalidade à prova. Pegue uma jarra d'água do poço e leve para o meu filho, o Chefe, na Aldeia Narache.$b$bLembre-se de que até mesmo a mais humilde das tarefas pode conquistar o reconhecimento dos anciões.", t = "Uma humilde tarefa"},
    [754] = {ot = "Use o Totem de Purificação Casco Invernal no Poço Casco Invernal, então fale novamente com Mull Chifre Troante.", st = "Entalhei o totem para purificar o Poço Casco Invernal. Agora, você precisa levá-lo ao poço e realizar o ritual de purificação. O poço fica a sudeste, guardado por terríveis goblins!$B$BNão será uma tarefa fácil, mas que precisa ser feita se quisermos voltar a usar as águas do poço um dia.$B$BBoa sorte, $n.", t = "A purificação de Casco Invernal"},
    [755] = {ot = "Vá ao Vidente Grislíngua que mora nas colinas ao sul da Aldeia Narache.", st = "Sua disposição em realizar uma humilde tarefa para os taurens de Narache e sua vontade de aprender são traços nobres, $n. Creio que um dia você será proclamad$Go:a; $Gum:uma; $c valoros$Go:a; no Penhasco do Trovão.$b$bAntes disso, você precisa embarcar nos Ritos da Mãe Terra, que são três.$b$bO primeiro teste é o Rito de força. Vá até o Vidente Grislíngua e diga-lhe que o Chefe Vento do Falcão mandou você.$b$bVocê encontrará a morada do vidente bem ao sul da Aldeia Narache, escondida nas colinas.", t = "Ritos da Mãe Terra"},
    [756] = {ot = "Leve 6 Garras de Espreitador e 6 Garras de Puma para Mull Chifre Troante.", st = "Para criar o Totem de Purificação Chifre Troante, você precisa reunir as garras dos predadores da planície de Mulgore. Cace espreitadores-da-pradaria para pegar as garras de espreitador e pumas das estepes para pegar as garras de puma. Em seguida, volte aqui.$B$BOs espreitadores-da-pradaria e os pumas das estepes ficam a leste e a oeste daqui.", t = "Totem de Chifre Troante"},
    [757] = {ot = "Mate alguns Costagulha na Ravina da Lâmina Espinhenta e leve 12 Cintos de Costagulha para o Chefe Vento do Falcão na Aldeia Narache.", st = "Os Ritos da Mãe Terra são os passos que um jovem tauren precisa dar para conquistar respeito no Penhasco do Trovão.$b$bPrimeiro você deve passar pelo Rito de Força. Nesse teste, você deve provar sua bravura matando os inimigos da tribo.$b$bOs Costagulha da Ravina da Lâmina Espinhenta, a leste, estão invadindo as terras da nossa tribo. Eles surpreendem nossas equipes de caça com emboscadas e roubam a aldeia à noite.$b$bMostre seu valor matando esses malfeitores e leve os cintos deles para o Chefe na Aldeia Narache como prova de seus feitos.", t = "Rito de força"},
    [758] = {ot = "Use o Totem de Purificação Chifre Troante no Poço Chifre Troante, então fale novamente com Mull.", st = "O totem está pronto, $n. E novamente é sua tarefa executar o ritual de purificação.$B$BVá ao Poço Chifre Troante, ao norte da aldeia, e use o Totem de Purificação Chifre Troante em seu ritual. Depois que terminar, fale novamente comigo.$B$BQue os espíritos guiem você.", t = "Purificação de Chifre Troante"},
    [759] = {ot = "Leve 8 Dentes de Lobos-da-pradaria alfas para Mull Chifre Troante na Aldeia Casco Sangrento.", st = "Ainda resta pelo menos um poço a ser purificado, que recebeu o nome do clã Juba Agreste. Para que ele fique puro, a terra tem que oferecer os dentes de um predador feroz, o lobo-da-pradaria alfa. Encontre os alfas ao norte e volte aqui quando a caçada terminar.$B$BOs alfas costumam vagar no sopé da nossa imponente cidade, Penhasco do Trovão.", t = "Totem de Juba Agreste"},
    [760] = {ot = "Use o Totem de Purificação Juba Agreste no Poço Juba Agreste, então fale novamente com Mull Chifre Troante.", st = "Os espíritos falam do seu feito de purificar os poços Casco Invernal e Chifre Troante, jovem $n. O totem de Juba Agreste está pronto e sua última tarefa $Go:a; aguarda.$B$BO poço Juba Agreste fica ao norte do Penhasco do Trovão. Realize o ritual! Cure a terra do veneno dos goblins! Que a água possa fluir pura de novo!", t = "Purificação de Juba Agreste"},
    [761] = {ot = "Leve 8 Troféus de Cálamo de Rapineiro para Harken Totem do Vento na Aldeia Casco Sangrento.", st = "O rapineiro é um pássaro astuto e difícil de encontrar e caçar. Para um caçador, uma coleção de cálamos de rapineiro é uma insígnia de inteligência e determinação.$B$BSe estiver $gdisposto:disposta; a aceitar a tarefa, vá para a planície e cace os rapineiros.$B$BTraga-me os cálamos e você honrará seu clã.$B$BOs rapineiros podem ser encontrados em qualquer lugar de Mulgore, mas é preciso olhos de lince para avistá-los, e cascos ligeiros para pegá-los.", t = "Caçada ao rapineiro"},
    [763] = {ot = "Leve o Totem do Vento do Falcão para Baine Casco Sangrento, na Aldeia Casco Sangrento. Siga a estrada que sai da Aldeia Narache.", st = "Para dar continuidade aos seus Ritos da Mãe Terra, você precisa passar por mais dois testes. Está na hora de você ampliar a sua experiência, $n.$b$bViaje para a Aldeia Casco Sangrento e procure o chefe, Baine Casco Sangrento, filho de Caerne. Lá, você poderá continuar a sua jornada e conquistar a aceitação dos anciões do Penhasco do Trovão.$b$bLeve este totem para Baine. Ele vai reconhecer os meus entalhes e ajudá-$Glo:la; em seu caminho.$b$bSiga a estrada que sai da Aldeia Narache e viaje depressa. Não se desvie do caminho para não se perder.", t = "Ritos da Mãe Terra"},
    [764] = {ot = "Mate 14 Trabalhadores da Empreendimentos S.A. e 6 Supervisores da Empreendimentos S.A. para Morin Espreita Nuvem na Aldeia Casco Sangrento.", st = "Isso explica o aumento do número de empregados e equipamentos da Empreendimentos S.A. que vimos em Mulgore. Esses goblins... A empresa deles está se expandindo rápido demais, e exclusivamente para o bem deles. É como se diz: mostre algo a um goblin e você logo ouve o som das moedas tilintando.$b$bCriaturinhas gananciosas, essas. Infelizmente para o empreendimento comercial deles, nós taurens não podemos permitir tais operações em nossas terras. Vá à mina deles, a nordeste da caravana devastada, e dê-lhes um recado.", t = "Empreendimentos S.A."},
    [765] = {ot = "Mate o Supervisor Geringonça e leve sua prancheta para Morin Espreita Nuvem na Aldeia Casco Sangrento.", st = "De acordo com os documentos que você resgatou da caravana, a Empreendimentos S.A. bolou muitos planos na tentativa de nos expulsar de nossas terras, para ter a liberdade de saqueá-las.$b$bA falta de limite para as baixezas de que são capazes para atingir as metas me enoja e aterroriza. Quero o mandante por trás dos planos morto. O nome dele é Supervisor Geringonça. Encontre-o na mina da Empreendimentos S.A., a leste da caravana devastada. Traga-me a prancheta dele, e veremos se conseguimos descobrir algo de útil.", t = "Supervisor Geringonça"},
    [766] = {ot = "Leve um Coração de Lobo-da-pradaria, um Fêmur de Puma das Estepes, uma Escama de Pinote e uma Moela de Rapineiro para Maur Clamachuva na Aldeia Casco Sangrento.", st = "Meu avô me contou histórias sobre as batalhas dele com um moa chamado Mazzranache. Ele me falou dos olhos vermelhos demoníacos, das garras afiadas como navalhas e da mordida venenosa.$b$bEntão, viajando pelas planícies, me deparei com Mazzranache. Ele é tão terrível quanto meu avô descreveu, e me deu uma bela mordida no ombro. Eu vou precisar de partes de animais difíceis de encontrar para limpar a infecção da mordida dele: um coração de lobo, um fêmur de puma, uma escama de pinote e uma moela de rapineiro.$b$bDepressa, o tempo urge!", t = "Mazzranache"},
    [767] = {ot = "Fale com Zarlman Duas Luas na Aldeia Casco Sangrento.", st = "O Rito de Visão, um dos Ritos da Mãe Terra, ajudará a guiá-$Glo:la; na conquista do respeito dos anciões do Penhasco do Trovão.$b$bNosso povo aprendeu que a terra é a nossa mais sagrada provedora. Para partilhar da visão ritualística, você precisa falar com o líder espiritual da aldeia, Zarlman Duas Luas.", t = "Rito de Visão"},
    [768] = {ot = "Leve 12 peças de Couro Leve a Veren Passo Alto, no Penhasco do Trovão.", st = "Saudações, jovem. Seus olhos brilham. Vejo que está $Gansioso:ansiosa; para aventurar-se nas planícies em novas caçadas. Que você leve honra ao seu clã!$B$BTrabalho com couros, confeccionando vestes e armaduras para o povo do Penhasco do Trovão.$B$BSe caçar algumas feras e me trouxer as peles delas, farei algo para você.", t = "Em busca de couro"},
    [769] = {ot = "Leve 4 Couros Leves e 4 Fios Grossos a Veren Passo Alto no Penhasco do Trovão.", st = "Os kodos de Mulgore têm a pele grossa e resistente, qualidades muito respeitadas entre nós. Caso tenha habilidade com couraria e queira aprender a confeccionar Bolsas de Pelego de Kodo, traga-me alguns suprimentos de que preciso.$B$BSe fizer isso, vou compartilhar meus conhecimentos com você.", t = "Bolsa de Pelego de Kodo"},
    [770] = {ot = "Encontre alguém que saiba do Uivo Fantasma.", st = "O pelego roto do Uivo Fantasma ainda exibe um terrível ferimento, consequência das lutas do lobo contra a Legião Ardente.$B$BTalvez alguém na Aldeia Casco Sangrento saiba da morte de Uivo Fantasma...", t = "O manto marcado por demônios"},
    [771] = {ot = "Colha 2 Pedras de Poço e 2 Pinhâmbar e leve-as para Zarlman Duas Luas na Aldeia Casco Sangrento.", st = "Para passar pelo Rito de visão, você precisa juntar os reagentes necessários para preparar a Água dos Videntes.$b$bVocê vai precisar de pedras de poço, que podem ser encontradas em torno de poços d'água em Mulgore. Com elas, eu vou combinar o pinhâmbar que cai das imponentes árvores da nossa terra.$b$bEsses reagentes contém elementos mágicos e, quando cozidos e consumidos diante da fogueira tribal, farão com você encontre uma visão. Siga-a, e ela $Go:a; levará para o próximo passo desta missão sagrada.", t = "Rito de visão"},
    [772] = {ot = "Beba a Água dos Videntes em frente à fogueira tribal na Aldeia Casco Sangrento e siga a visão quando ela aparecer.", st = "Agora, eu lhe apresento a Água dos Videntes.$b$bQuando estiver pront$Go:a;, consuma a água perto de uma fogueira tribal. Uma vez ingerida a água benta, levará alguns instantes para que a visão se materialize diante do fogo.$b$bQuando isso acontecer, caberá a você segui-la rumo ao seu destino...", t = "Rito de visão"},
    [773] = {ot = "Siga para o Rochedo Vermelho, a leste do Penhasco do Trovão, e procure o Espírito Ancestral.", st = "Para ser $Gaceito:aceita; entre os anciãos do Penhasco do Trovão é preciso concluir o rito de sabedoria.$b$bAgora que você concluiu o rito de visão, os espíritos ancestrais do Rochedo Vermelho lhe concederão a bênção dos nossos ancestrais. Somente os que beberam da água dos Videntes merecem a bênção.$b$bSiga para o leste do Penhasco do Trovão, para o Rochedo Vermelho, e procure o Espírito Ancestral, $n.", t = "Rito de sabedoria"},
    [775] = {ot = "Fale com Caerne Casco Sangrento no Penhasco do Trovão.", st = "Agora você será $greverenciado:reverenciada; em nossa bela cidade. Qualquer $r digno de concluir os Ritos da Mãe Terra merece essa honra.$b$bComo última missão, procure nosso nobre líder, Caerne Casco Sangrento, que habita o topo da chapada mais alta do Penhasco do Trovão.", t = "Siga para o Penhasco do Trovão"},
    [776] = {ot = "Caerne Casco Sangrento, no Penhasco do Trovão, quer que você leve para ele o Chifre de Arra'chea.", st = "Você concluiu os Ritos da Mãe Terra e conquistou seu lugar no Penhasco do Trovão.$b$bMas para conservar o posto que você lutou tanto para conseguir, é necessário que você continue provando seu valor para o seu povo.$b$bSomos caçadores, $n. Lá embaixo, em Mulgore, existe um poderoso kodo chamado Arra'chea. Para comprovar suas habilidades de rastreamento e caça, quero que me traga o Chifre de Arra'chea.", t = "Ritos da Mãe Terra"},
    [780] = {ot = "Grull Vento do Falcão, na Aldeia Narache, quer que você mate Javaliços e leve para ele 8 Focinhos de Javaliço e 8 Flancos de Javaliço.", st = "Os Javaliços da Ravina da Lâmina Espinhenta, ao leste, estão invadindo a nossa área tribal de caça. Os Javatuscos Costagulha, com quem estamos em guerra, estão treinando os Javaliços para que eles sejam muito cruéis$b$bVá até lá e mate essas criaturas vis. Traga de volta uns focinhos e uns flancos para nós fazermos comida para os mais jovens.", t = "Os javaliços"},
    [781] = {ot = "Leve o Plano de Ataque dos Costagulha para o Chefe Vento do Falcão, na Aldeia Narache.", st = "Depois de analisar o mapa com cuidado, você percebe que descobriu os planos do chefe guerreiro dos Costagulha para fazer um longo cerco à Aldeia Narache.$b$bO Chefe Vento do Falcão certamente vai querer saber dessa informação!", t = "Aldeia Narache sob ataque"},
    [783] = {ot = "Fale com o Major Belmonte.", st = "É bom se preparar, jovem $c, porque há muito trabalho para se fazer aqui na Vila Norte.$B$BE eu não estou falando de lavrar a terra.$B$BOs guardas de Ventobravo estão tendo bastante dificuldade de manter a paz aqui, já que tantos de nós estão em terras distantes enquanto tantas ameaças se assomam. Estamos aceitando a ajuda de todos os que estiverem dispostos a defender o nosso lar. E a nossa aliança.$B$BSe quiser atender ao nosso chamado, fale com o meu superior, o Major Belmonte. Ele está dentro desta abadia logo atrás de mim.", t = "A ameaça interna"},
    [784] = {ot = "Mate 10 Marinheiros de Kul Tiraz, 8 Fuzileiros de Kul Tiraz e o Tenente Bento. Depois, fale novamente com Gar'Thok no Monte Navalha.", st = "Liderados pelo Almirante Proudmore, os humanos de Kul Tiraz atacaram Durotar, violando o pacto que o Chefe Guerreiro havia feito com Jaina Proudmore para derrotar Arquimonde anos antes.$b$bO assalto humano foi contido e a Bastilha Tiragarde caiu. Mas recentemente os reforços do Almirante conseguiram retomar a bastilha, sob a liderança do Tenente Bento, e voltaram a representar uma ameaça à nossa terra. Esses humanos não demonstram o menor respeito pela diplomacia.$b$bPara provar que é honrad$Go:a;, viaje para o sul e elimine os invasores humanos da Bastilha Tiragarde.", t = "Aniquile os invasores"},
    [786] = {ot = "Larri Presador, junto à Aldeia Sen'jin, quer que você destrua 3 Planos de Ataque, que estão no Penedo de Kolkar.", st = "Fale baixo, $c. Os centauros Kolkar ficam no Penedo de Kolkar, que é logo além deste cume, ao oeste.$b$bOntem à noite, enquanto eles estavam fora para pilhar, eu me esgueirei pelo vilarejo deles e descobri que as bestas imundas bolaram um plano em três fases para atacar os trolls e os orcs de Durotar.$b$bNão podemos deixar a invasão se concretizar. Talvez você tenha a coragem necessária para se infiltrar no Penedo de Kolkar e destruir os planos de ataque.$b$bAté onde eu sei, eles dividiram os planos entre três líderes deles.", t = "Frustrando o ataque dos Kolkar"},
    [788] = {ot = "Mate 10 Mosquetuscos, depois fale novamente com Gornek no Covil.", st = "A primeira coisa a fazer é dar um pouco de firmeza ao seu caráter. Eu poderia enviar você até os Sertões para caçar kodos, mas, bem, com toda franqueza, você nos é mais útil viv$go:a; do que mort$go:a;.$b$bAcho que os mosquetuscos que vivem ao norte daqui vão ser um desafio à altura para você.", t = "Dentes cortantes"},
    [789] = {ot = "Leve 10 Caudas de Escorpídeo Operário a Gornek, no Covil.", st = "Tanto guerreiros poderosos quanto novatos desajeitados encontraram a morte na ferroada do escorpídeo. Você encontrará um grande número desses seres venenosos a noroeste daqui. Para provar seu talento no combate, me traga dez caudas de escorpídeo.$b$bO antídoto para a ferroada deles é feito do próprio veneno extraído dos aguilhões. Temos sempre à mão uma boa quantidade de antídoto para veneno de escorpídeo, para curar jovens como você...$b$bMas tenho certeza de que você não vai precisar de nada disso, não é?", t = "A ferroada do escorpídeo"},
    [790] = {ot = "Mate Sarkoth e leve a garra dele para Hana'zua.", st = "$C! Pensei que eu ia morrer aqui sem que ninguém soubesse. Enquanto eu caçava escorpídeos no Vale, encontrei um que parecia especialmente perigoso. Corri pra cima dele e consegui acertar um golpe forte na garra antes dela fechar na minha perna.$b$bMas eu não estava pronto para o ferrão, e ele foi bem no meu peito, abriu um buraco e me fez sangrar muito. Por favor, você tem que matar o escorpídeo para mim! Minha honra deve ser defendida! Eu combati ele no platô ao sul.", t = "Sarkoth"},
    [791] = {ot = "Férrano Escarnecenho na torre de vigia do Monte Navalha quer 8 Retalhos de Lona.", st = "A idade me tornou inútil na batalha. Agora me faço útil de outras maneiras.$b$bProcuro invasores a partir desse ponto de observação. À medida que a nossa força aqui cresce, me pego soprando cada vez menos a trompa sinalizadora.$b$bPara passar o tempo, invento apetrechos para ajudar os guerreiros mais jovens e capazes a defender nossa terra natal.$b$bPosso criar uma bolsa para você carregar seus pertences. Se isso for útil para você, traga-me uma lona, material que pode ser encontrado com humanos e centauros.", t = "Carregue suas tralhas"},
    [792] = {ot = "Mate 12 Familiares torpes.$B$BFale novamente com Zureta Vista-longa em frente ao Covil.", st = "Creio que o Vale das Provações ensinará muito a você, jovem $c.$B$BFui enviada ao Vale para guiá-l$Go:a;, mas descobri uma mácula crescente neste lugar...$B$BUm grupo que se autointitula Lâmina Ardente tem um conventículo aqui no Vale das Provações. Escondem-se em uma caverna a nordeste, e os Familiares torpes deles saíram por aí causando caos.$B$BA sua primeira tarefa contra a Lâmina Ardente será derrotar esses familiares. Mate muitos e, se você sobreviver, fale novamente comigo.", t = "Familiares torpes"},
    [794] = {ot = "Leve o Medalhão da Lâmina Ardente para Zureta Vista-longa em frente ao Covil.", st = "Através de minhas divinações, vejo que um item de grande poder se esconde nas profundezas do Covil da Lâmina Ardente, guardado por feras e magia negra.$B$BEle é chamado de Medalhão da Lâmina Ardente, e sua próxima tarefa é encontrá-lo e removê-lo do covil.$B$BMas tenha cuidado, pois um agente da Lâmina Ardente pode ter se apossado do medalhão, e, se for o caso, então ele teria mais poder do que os familiares que você já encontrou.$B$BVá, $n. Você encontrará o covil em uma caverna, a norte e a oeste.", t = "Medalhão da Lâmina Ardente"},
    [804] = {ot = "Leve as notícias sobre os apuros de Hana'zua a Gornek, no Covil.", st = "Ver o que você fez por mim fortalece o meu coração. Não posso cair tão facilmente! Preciso resistir!$b$bMas não consigo percorrer o caminho de volta ao Covil sem ajuda. Por favor, $n, volte e explique minha situação para Gornek. Talvez ele possa me ajudar.", t = "Sarkoth"},
    [805] = {ot = "Fale com o Mestre Gadrin na Aldeia Sen'jin.", st = "As suas provações contra a Lâmina Ardente terminaram... aqui, no Vale. Mas quero que você reporte as suas descobertas.$B$BVá à aldeia troll de Sen'jin e procure o Mestre Gadrin. A Aldeia Sen'jin fica a leste, fora do vale, e então à direita na bifurcação.$B$BAvise ao Gadrin a respeito da Lâmina Ardente, e que eles alcançaram o Vale das Provações. Descubra se eles já chegaram a Sen'jin.$B$BVá, $n, e seja rápid$Go:a;. Temo que o mal que encontramos dentro do Covil da Lâmina Ardente tenha sido apenas o prenúncio de uma ameaça maior...", t = "Apresente-se na Aldeia Sen'jin"},
    [806] = {ot = "Leve a Garra do Bulho para Orgnil Chaganalma no Monte Navalha.", st = "Não podemos permitir que a Lâmina Ardente se estabeleça em Durotar! Precisamos destruí-los antes que esse mal se espalhe!$B$BConduzi minhas próprias investigações e descobri que um bruxo da Lâmina Ardente, o goblin Bulho Tempesnigra, acampou no Desfiladeiro do Trovão a noroeste. Lá, ele e seus servos sectários espalharam o caos.$B$BEncontre e derrote Bulho, e traga-me a garra morta dele!", t = "Tempestades sombrias"},
    [808] = {ot = "Recupere o Crânio de Minshina do círculo do poder nas Ilhas do Eco.$B$BLeve-o para o Mestre Gadrin na Aldeia Sen'jin.", st = "Ouço a voz do meu irmão, Minshina, me chamando em meus sonhos.$B$BEle foi levado por Zalazane, o bruxo das Ilhas do Eco a leste. E está morto.$B$BMas a morte não significou a liberdade do meu irmão, parceir$Go:a;. O espírito de Minshina foi preso dentro do próprio crânio dele pelas magias de Zalazane. Nos meus sonhos, vejo ele junto de outros crânios, em um círculo de poder na maior Ilha do Eco. Enquanto ficar por lá, a alma do meu irmão está condenada.$B$BPor favor, $n. Encontra o círculo e recupera o crânio de Minshina. E traz aqui pra mim.$B$BLiberta o espírito dele!", t = "O crânio de Minshina"},
    [809] = {ot = "Fale com Ak'Zeloth nos Sertões.", st = "Desde a última grande guerra, quando a Legião Ardente foi derrotada, tenho buscado fontes de corrupção demoníaca na sociedade órquica. O colar que você trouxe confirma o que eu temia.$B$BEle pertence à Lâmina Ardente, um culto que se une em torno de um item de poder demoníaco, chamado de Semente Demoníaca. Esse item pode ser encontrado nos Sertões, no topo do Morro de Brumedo. E deve ser destruído!$B$B. Vá ao Posto Remoto, que fica à margem dos Sertões, a oeste daqui, e fale com o meu assistente, Ak'Zeloth. Ele lhe orientará melhor.", t = "Ak'Zeloth"},
    [812] = {ot = "Encontre Kor'ghan em Orgrimmar e pegue o Antídoto para Caudaçonha. Então leve o antídoto para Rhinag perto da fronteira noroeste de Durotar.", st = "$n... seu timing é perfeito. Só espero poder elogiar sua rapidez também.$B$BFui descuidado ao lutar com algumas das caudaçonhas aqui perto, e uma delas me picou pra valer. Posso sentir o veneno dela me enfraquecendo enquanto falamos. Nesse ritmo, talvez me reste uma hora de vida. Mas vou precisar da sua ajuda se quiser sobreviver...$B$BKor'ghan, em Orgrimmar, sabe como fazer o antídoto. Encontre ele... depressa, $n. Não vou conseguir resistir muito mais tempo. Ele deve estar no Antro das Sombras.", t = "Busca da cura"},
    [813] = {ot = "Leve 4 Vesículas de Veneno de Caudaçonha para Kor'ghan em Orgrimmar.", st = "Os Caudaçonhas são alguns dos escorpídeos mais mortais de Durotar. Rhinag não foi nada inteligente em caçá-los sem ter o antídoto, mas, neste momento, a última coisa de que ele precisa é punição.$B$BTraz pra mim algumas vesículas de veneno de caudaçonha de qualquer caudaçonha perto da entrada de Orgrimmar, que faço um antídoto para ele.$B$BDepressa, $n. Um dos nossos precisa da sua ajuda.", t = "Em busca do antídoto"},
    [815] = {ot = "Leve 3 Ovos de Açoitacauda para o Cozinheiro Torka no Monte Navalha.", st = "Bah! Quase me esqueci que preciso preparar o café da manhã.$B$B$n, mexa-se e me traga alguns ovos de açoitacauda. Precisarei de pelo menos três para a refeição de amanhã.$B$BOs açoitacaudas Garrasangre podem ser ferozes, e quase sempre protegem seus ovos até a morte. Às vezes, eles enterram os ovos bem fundo na terra para desenterrarem em segurança, mas, se você for para as Ilhas do Eco a sudeste da Aldeia Sen'jin, poderá encontrá-los por todas aquelas ilhas lá.", t = "Quebrar alguns ovos"},
    [816] = {ot = "Leve uma prova do destino de Kron para Misha Tor'kren na fazenda a noroeste do Monte Navalha.", st = "$n, por favor, você pode me ajudar? Meu filho Kron foi caçar dias atrás e ainda não voltou. Ele foi para o oeste em direção dos Sertões caçar crocoliscos ao longo do Rio Furiaustral. Temo pelo pior.$B$BPor mais forte que ele seja, seu orgulho teimoso sempre o colocou em apuros. Eu o avisei que os crocoliscos eram violentos e cruéis. Ele ficou bravo e saiu, furioso.$B$BSe você não conseguir encontrá-lo, pelo menos me traga uma prova do destino dele... mesmo que tenha que abrir o estômago de todos os crocoliscos ao longo das margens do Furiaustral.", t = "Em memória"},
    [817] = {ot = "Leve 4 Peles de Tigre de Durotar para Vel'rin Presa na Aldeia Sen'jin.", st = "Muitas das peles que usamos vêm dos tigres de Durotar, $n. Cobertores, armaduras, tendas: há várias razões pra caçarmos as feras e, ao mesmo tempo, várias pra deixarmos que prosperem.$B$BChegou a hora de abater o rebanho, por assim dizer, $Gmeu:minha; chapa. Aumentamos em número e nossas necessidades estão começando a exceder nossos estoques. Preciso de mais peles pra preparar bens adequados pro nosso povo.$B$BTraga-me 4 peles de tigre de Durotar e vou recompensá-l$Go:a;. Você pode encontrar os tigres nas ilhas ao sul daqui.", t = "Presa prática"},
    [818] = {ot = "Leve 4 Olhos de Makrura Intactos e 8 ampolas de Muco de Rastejante para Mestre Vornal na Aldeia Sen'jin.", st = "Embora meus olhos já não sejam os mesmo, ainda posso ver claro que chegue. Frequentemente, preciso confiar em minhas habilidades alquímicas pra me ajudar com magias que um dia me foram fáceis. Mas me recuso a aceitar um aprendiz — nenhum troll ou orc jamais se mostrou digno.$B$BTu é dign$Go:a;? Sim, claro que é... claro que tu pensa que é, camarada.$B$BPreciso de algumas coisas. Pode trazê-las para mim?$B$BPreciso de olhos de makrura intactos e ampolas de muco de rastejante. Tu pode pegá-los de qualquer makrura ou rastejante em Durotar. A gente se fala em breve.", t = "Um espírito solvente"},
    [819] = {ot = "Encontre alguém que saiba sobre o Barril Vazio do Chen.", st = "Um pequeno cartaz em uma das pontas do barril diz:$B$B\"Chen Malte do Trovão$B$BQue a bebida sempre possa animar seu espírito.\"", t = "Barril Vazio do Chen"},
    [821] = {ot = "Leve 5 Presas de Leão da Savana, 5 Rins de Pinote e 1 Chifre de Lagarto Trovejante para o Cervejeiro Drohn, em Vila Catraca.", st = "Quer experimentar a bebida que leva o nome do Chen? Ah, a malte do trovão é uma cerveja fantástica. Chen ensinou a receita ao meu mentor, que a repassou para mim. Preciso que você me traga algumas coisas, mas já lhe adianto: o sabor vale a pena!$B$BTraga pra mim cinco presas de qualquer leão da savana, cinco rins de qualquer raça de pinote e um chifre de qualquer espécie de lagarto trovejante. Isso vai bastar para mim.$B$BVocê acha esses ingredientes em qualquer parte dos Sertões.", t = "Barril Vazio do Chen"},
    [822] = {ot = "Leve 5 Glândulas Relampejantes, 1 Glândula Salivar de Falcotrom e 1 Fígado de Kodo para o Cervejeiro Drohn, em Vila Catraca.", st = "É boa essa malte do trovão, hein?$B$BTem outra receita que aprendi com o Chen. Interessa? Fica pronta rápido e pode ser útil se você pretende viver mais aventuras.$B$BTraga pra mim cinco glândulas relampejantes de qualquer tipo de borrascouro, uma glândula salivar de grande falcotrom e um fígado de qualquer tipo de kodo dos Sertões.$B$BComo eu disse, essa coisa é muito saborosa. É a cerveja trogg de que lhe falei antes.", t = "Barril Vazio do Chen"},
    [823] = {ot = "Fale com Orgnil Chaganalma no Monte Navalha.", st = "Nós da Aldeia Sen'jin temos nossos próprios problemas, e agradecemos a sua ajuda. Mas as notícias que você traz sobre a Lâmina Ardente podem ser um problema pra todos.$B$BTem um orc no Monte Navalha, Orgnil Chaganalma, que policia Durotar contra males como a Lâmina Ardente! Procura Orgnil e conta pra ele nossa situação, assim como as notícias que tu traz do Vale das Provações. Ele vai querer saber essas coisas.$B$BO Monte Navalha fica ao norte.", t = "Apresente-se a Orgnil"},
    [824] = {ot = "Leve o Globo d'Água Conspurcado para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris.", st = "A Harmonia Telúrica é um grupo xamanista dedicado ao estudo e à preservação dos elementos. Eles sabem mais de deuses malucos, lendas e histórias velhas do que qualquer estudioso jamais saberá.$B$BPor sorte, eu conheço um membro da Harmonia Telúrica aqui no Vale Gris. Vá até o Assentamento Zoram'gar, perto da Praia de Zoram, e mostre o globo para Je'neu Sancrea. Se há alguém capaz de descobrir o significado dessa coisa, esse alguém é ele.", t = "Je'neu da Harmonia Telúrica"},
    [825] = {ot = "Gar'Thok, do Monte Navalha, quer que você recupere 3 Ferramentas Gnômicas dos destroços junto à costa.", st = "Um dos meus batedores mais atentos informa que os destroços da frota de Proudmore ainda permanecem próximos à costa de Durotar, a leste da Bastilha Tiragarde.$b$bNão é nenhum segredo que os humanos, em aliança com aquelas criaturinhas torpes conhecidas como gnomos, têm um conhecimento avançado de mecânica. Devemos saber todo o possível sobre nossos inimigos em potencial. E o nosso povo também se beneficiará desse novo conhecimento.$b$bPercorra os destroços, $n, e recupere para mim as ferramentas da Aliança.", t = "Dos destroços..."},
    [826] = {ot = "Derrote Zalazane.$B$BMate 8 Trolls Vodu e 8 Trolls Bagateados.$B$BLeve a Cabeça do Zalazane para Gadrin.", st = "O mandingueiro Zalazane vive nas Ilhas do Eco, ao leste. Lá já foi o nosso lar.$B$BDe lá ele manda os trolls dele para o continente, para embagatar nosso povo e dominar mais e mais da gente.$B$BEle precisa ser detido.$B$BDerrote o Zalazane e os lacaios dele. Eles já foram trolls Lançanegra, mas hoje estão perdidos pra gente. Traz a cabeça dele pra mim, pra eu saber que o reino de terror dele acabou.", t = "Zalazane"},
    [827] = {ot = "Junte Colares Calcinantes dos sectários na Rocha da Caveira.$B$BLeve-os para Margoz no acampamento dele.", st = "$n, a Lâmina Ardente infestou a caverna a leste, conhecida em Orgrimmar como a Rocha da Caveira. Dentro dela, eles realizam rituais torpes e queimam a própria carne com colares calcinantes.$B$BUsando esses colares, acredito que os sectários se harmonizem com o poder demoníaco. Mas, para ter certeza, preciso estudar uma coleção de colares.$B$BVá até a Rocha da Caveira e obtenha os colares calcinantes dos sectários que você encontrar por lá. Traga-os a mim e descobrirei quais segredos eles escondem.", t = "A Rocha da Caveira"},
    [828] = {ot = "Fale com Margoz.", st = "Um dos nossos xamãs, Margoz, tem mais informações sobre a corrupção da Lâmina Ardente. Ele falou sobre uma caverna chamada Rocha da Caveira, nas montanhas próximas a Orgrimmar, que abriga um bando de sectários da Lâmina Ardente.$B$BAntes de você ir até a Rocha da Caveira, fale com Margoz. Ele é sábio e seus conselhos são valiosos.$B$BEle está acampado a nordeste daqui, entre a costa e o Barranco da Ravina Seca.$B$BSiga os conselhos dele, mas independente do que ele disser, $n, ainda quero que você esmague aqueles sectários!", t = "Margoz"},
    [829] = {ot = "Leve um Colar de Amostra para Neeru Cortafogo em Orgrimmar.", st = "Os colares calcinantes que você trouxe são implementos demoníacos poderosos. Receio que descobrir a origem destes colares vá além das minhas habilidades como xamã. Nós vamos precisar de um bruxo para conseguir estudá-los.$B$BLeve um colar calcinante para Neeru Cortafogo. Embora seja um bruxo habilidoso, ele garante que usa seus poderes contra os demônios, e que suas pesquisas em ocultismo são benignas. Verdade ou mentira, nós precisamos da ajuda dele contra a seita demoníaca em Durotar.$B$BEncontre Neeru em Orgrimmar, no Antro das Sombras.", t = "Neeru Cortafogo"},
    [830] = {ot = "Leve as Ordens do Almirante Proudmore para Gar'Thok no Monte Navalha.", st = "Você abre o envelope velho e surrado e descobre um documento de aparência oficial. Você reconhece o selo do Almirante Proudmore.$b$bParece importante. Talvez Gar'Thok, comandante do Monte Navalha, se interesse por esta informação.", t = "As ordens do almirante"},
    [831] = {ot = "Entregue as Ordens do Almirante Proudmore a Nazgrel nos aposentos de Thrall, em Orgrimmar.", st = "Não se pode confiar nos humanos. Nós lutamos ao lado deles com um peso no coração, sabendo que um dia eles nos trairiam.$b$bA morte do Almirante Proudmore não foi suficiente para acabar com o legado da escória traidora. Os planos do humano já estavam traçados muito antes do fim.$b$bO reino dele não vai sequer morrer com Bento. Quem sabe quanto tempo levará até que a próxima vaga dos Proudmore se lance sobre a nossa costa?$b$bPrecisamos levar essas ordens a Nazgrel, em Orgrimmar, imediatamente! Ele fica nos aposentos de Thrall.", t = "As ordens do almirante"},
    [832] = {ot = "Leve esse olho para Neeru Cortafogo.", st = "<Palavras emanam do pingente para sua mente.>$B$BGazz'uz?$B$BGazz'uz... responda!$B$BHá notícias de sua descoberta na Rocha da Caveira. Você precisa se preparar para um ataque!$B$BGazz'uz, eu ordeno que você fale! Fale ou eu vou garantir que Neeru Cortafogo saiba da sua presença, e ele será veloz e brutal.$B$BNão teste sua perícia contra Neeru...$B$B...Gazz'uz... você está aí?", t = "Sombras incandescentes"},
    [833] = {ot = "O Erudito Totem da Chuva quer que você mate 8 Traiçoeiros Costagulha no Rochedo Vermelho.", st = "Somente os mais valorosos taurens têm o direito de repousar no Rochedo Vermelho, nosso cemitério sagrado. Trata-se de uma honra concedida aos grandes guerreiros que ajudaram a fundar e defender o Penhasco do Trovão e àqueles que deram suas vidas pelo bem maior de suas tribos e chefes.$b$bContudo, uma horrível ameaça acaba de invadir nosso solo sagrado. Um bando de javatuscos Costagulha está saqueando o cemitério. E eu já não estou mais no meu auge, estou velho demais.$b$bÉ preciso expulsá-los à força, $n.", t = "Sepultamento sagrado"},
    [834] = {ot = "Recupere 5 Sacos de Suprimentos e entregue-os a Rezlak perto de Orgrimmar.", st = "Meu nome é Rezlak. Sou um dos rapazes do Gasganete. O chefe me mandou aqui para dar uma mãozinha pros orcs de Durotar. Até que estaria tudo numa boa se não fosse pelas caravanas. Não consigo manter a segurança delas! Isso dificulta o meu trabalho, sabia?$b$bO último carregamento que, aliás, eles juraram que seria entregue, foi surrupiado pelas harpias Lufareia de... onde é que foi mesmo... foi na Garganta do Vento Cortante?$b$bEu preciso daqueles suprimentos, ou eu não vou conseguir fazer nada aqui! Siga pelo grande cânion em direção ao sul e você encontrará uma ravina encravada a leste e oeste das muralhas de pedra.", t = "Ventos do deserto"},
    [835] = {ot = "Mate 12 Selvagens Sopravento e 8 Bruxas da Tempestade Sopravento para Rezlak perto do Barranco da Ravina Seca.", st = "O Gasganete me disse uma vez assim: \"Rezlak, olha só. Tem uma coisa que você tem que saber na vida. Se você quer uma coisa bem feita, faz você mesmo.\"$b$bEu não vou aguentar perder todas as caravanas, então eu vou é resolver do meu jeito. O Barranco da Ravina Seca fica do lado leste da Garganta do Vento Cortante. Se a gente matar as harpias de lá, vai ficar tudo bem com as caravanas.$b$bMas é claro que o Gasganete me ensinou outra coisa, também: \"Pagando bem tudo se arranja\". Então... E aí? Me ajuda nessa, $n?", t = "Faça o que eu digo..."},
    [837] = {ot = "Mate 4 Javatuscos Crinavalha, 4 Batedores Crinavalha, 4 Levanta-poeira Crinavalha e 4 Guardas de Batalha Crinavalha para Gar'Thok no Monte Navalha.", st = "Quando chegamos, os javatuscos Crinavalha dominavam grande parte da região e provaram ser um espinho em nossas vidas. Com muito esforço, conseguimos expulsar a maior parte deles, mas ainda permanecem firmemente estabelecidos em algumas áreas.$b$bSó que isso já se prolongou demais. Para nossa própria proteção, não podemos permitir que os Crinavalha dominem nenhuma área em nossas terras. Os acampamentos deles podem ser encontrados a oeste daqui. Procure os espinheiros e você os encontrará. Hoje nós os expulsamos de Durotar, amanhã, talvez de toda a Kalimdor.", t = "Invasão"},
    [840] = {ot = "Siga a estrada a oeste, de Monte Navalha para os Sertões, passando por uma ponte.$B$BPare no posto avançado órquico do outro lado da ponte.$B$BEntregue sua carta de recrutamento para Kargal Chaga de Guerra, no posto avançado dos Sertões.", st = "Hum, você me parece forte o bastante.$B$BEscute só: meu velho amigo Kargal está precisando de recrutas para servir nos Sertões. Eu sei que você quer fazer o melhor que puder pela Horda. Bem, a sua chance chegou.$B$BLeve esta carta de recrutamento para Kargal e veja se ele aceita o seu alistamento.", t = "Recruta da Horda"},
    [842] = {ot = "Siga a estrada a oeste a partir do Posto Remoto de Kargal.$B$BNa interseção em T, vire à esquerda e siga a estrada para o sul. $B$BEncontre Sergra Espinhonegro no cruzamento de estradas da Encruzilhada.", st = "Leve esta carta de recrutamento assinada para a Encruzilhada.$B$BSergra Espinhonegro, maldita seja, está no comando por lá. Ela é uma xamã terrível que vai deixá-l$Go:a; zonz$Go:a; de tanto falar antes de permitir que faça qualquer coisa útil. Thrall está convencido de que ela é especial, mas eu não tenho tanta certeza.$B$BVocê terá de chegar a uma conclusão sozinh$Go:a;, filhote...", t = "Recrutamento na Encruzilhada"},
    [843] = {ot = "Gann Agulha de Pedra quer que você mate 15 Escavadores de Bael'Dun e 5 Capatazes de Bael'dun.$b$bLeve o Diário de Khazgorm para Gann Agulha de Pedra.", st = "Em meio à solidão, vagueio pelas estradas.$b$bOs anões de Bael Modan não mostram nenhum respeito pela minha terra. Explosões horrendas fazem buracos no chão enquanto máquinas barulhentas rasgam as colinas. Terras que já serviram como lar e provedora para minha tribo agora estão repletas de anões destrutivos.$b$bTentativas de alcançar uma resolução diplomática falharam. Agora chegou a hora de uma ação decisiva.$b$bRemova os anões do Sítio Arqueológico Bael Modan à força e traga-me o diário do líder deles, o Prospector Khazgorm.", t = "Reivindicação de Gann"},
    [844] = {ot = "Colete 7 Bicos de Pinote e entregue-os a Sergra Espinhonegro na Encruzilhada.", st = "Sua primeira presa será fácil.$B$BOs pinotes a leste têm vindo atrás de nosso estoque de comida e se tornaram um verdadeiro incômodo.$B$BAcabe com os pinotes e me traga os bicos deles.", t = "A ameaça pinote"},
    [845] = {ot = "Mate Zevras Corredoras e leve 4 Cascos de Zevra para Sergra Espinhonegro na Encruzilhada.", st = "As zevras, embora não sejam as criaturas mais ferozes dos Sertões, são um pouco mais perigosas do que os pinotes. Não se preocupe... mandaremos você ir atrás de presas maiores no momento certo, mas, por enquanto, você precisa de um pouco mais de experiência.$B$BCace as zevras ao norte e ao sul, e colete seus cascos. Traga-os para mim e quem sabe em seguida não mandamos você atrás de uma presa mais difícil.", t = "As zevras"},
    [846] = {ot = "Gann Agulha de Pedra quer que você leve para ele 6 ampolas de Nitroglicerina, 6 feixes de Polpa de Madeira e 6 amostras de Nitrato de Sódio.", st = "Está claro que o prospector dependia de explosivos e daqueles veículos barulhentos para rasgar o solo. Podemos esperar que um novo encarregado assuma em breve.$b$bQuero dar aos anões uma prova do próprio remédio. De acordo com esses planos, se combinarmos nitroglicerina com polpa de madeira e nitrato de sódio, podemos criar uma carga explosiva. Os suprimentos podem ser encontrados com o carabineiro, os soldados e os oficiais da bastilha.$b$bArranje esses itens e traga-os para mim. Vou criar um explosivo que os anões não vão esquecer!", t = "A vingança de Gann"},
    [848] = {ot = "Leve 4 Esporos de Fungos ao Boticário Hermógenes na Encruzilhada.", st = "Os oásis dos Sertões ocultam um mistério. Emana de suas águas uma energia vital que revigora as plantas e feras que a sorvem.$B$BRevigora e altera.$B$BHá um cogumelo que cresce perto dos oásis. Seus esporos contêm propriedades que são úteis a nós, os boticários de Lordaeron.$B$BTraga-me os esporos e terá nossa gratidão.", t = "Esporos de Fungos"},
    [849] = {ot = "Destrua a máquina voadora em Bael Modan e fale novamente com Gann Agulha de Pedra.", st = "Seguindo o projeto de Khazgorm, não deve ser muito difícil criar uma carga explosiva.$b$bAh, pronto.$b$bAgora, $n, vou lhe confiar uma tarefa especial. Pegue este bastão explosivo e use-o para explodir a máquina voadora em Bael Modan.$b$bAlém de ser parte fundamental da infraestrutura do lugar, a máquina voadora serve de arma de guerra. E, mais importante que isso, é um símbolo de poder e um insulto à memória da minha tribo.$b$bMe deixe orgulhoso cumprindo essa tarefa heroica e você será recompensad$Go:a;.", t = "A vingança de Gann"},
    [850] = {ot = "Leve a Cabeça do Barak para Regthar Portões-da-morte a oeste da Encruzilhada.", st = "Os centauros já incomodam os taurens há anos. E agora os centauros Kolkar dos Sertões se tornaram uma verdadeira ameaça. Antes eram desorganizados, mas surgiram novos líderes entre eles que os uniram.$B$BPara preservarmos nossos assentamentos, é preciso aniquilar os líderes dos centauros.$B$BTraga-me a cabeça de Barak Findekodo. Ele se encontra num acampamento perto dos Charcos Esquecidos, ao norte.$B$BRetorne depois de derrotá-lo.", t = "Os líderes Kolkar"},
    [851] = {ot = "Leve a Cabeça do Verog para Regthar Portões-da-morte a oeste da Encruzilhada.", st = "O centauro Verog, o Dervixe, vagueia pelos Sertões – não vai ser fácil de achar. Mas ele está lotado na tenda de comando centáurea no Oásis Estagnado, a sudeste daqui. Talvez você consiga atrair ele.$B$BVá ao Oásis Estagnado, a sudeste, e ataque os centauros perto da tenda de comando. Vai ser perigoso, mas, se você conseguir matar centauros suficientes, eles vão ficar alarmados. Aí, o Verog dar as caras.$B$BTraga a cabeça dele para eu colocar junto da cabeça de Barak Findekodo.", t = "Verog, o Dervixe"},
    [852] = {ot = "Leve a Cabeça do Hezrul para Regthar Portões-da-morte a oeste da Encruzilhada.", st = "Hezrul Marca de Sangue é o líder dos centauros Kolkar nos Sertões. Ele é feroz, brutal e sagaz. Derrotá-lo desarticularia os Kolkar, reduzindo muito a ameaça que eles representam para nós.$B$BAssim, mate-o. Como no caso de Barak e Verog, traga-me a cabeça do Hezrul.$B$BEle comanda o povo dele a partir do Oásis das Águas Claras, ao sul.", t = "Hezrul Marca de Sangue"},
    [853] = {ot = "Leve os Esporos Entregues para a Boticária Zaqueia no Penhasco do Trovão antes que o tempo se esgote.", st = "Transformei os esporos que você me deu em uma emulsão. Agora preciso enviá-la a minha colaboradora, a Boticária Zaqueia. Se você levasse para ela, ela poderia lhe oferecer algo de nosso estoque de produtos alquímicos.$B$BEla está nos Poços das Visões, uma caverna abaixo de onde vivem os xamãs do Penhasco do Trovão. A trilha para a caverna fica bem escondida no promontório do Platô dos Espíritos, mas você deve conseguir encontrar.$B$BApresse-se. Essa emulsão só conservará a potência por pouco tempo, e precisa ser selada e processada logo.", t = "Boticária Zaqueia"},
    [854] = {ot = "Fale com Thork na Encruzilhada, nos Sertões.", st = "Previ sua chegada, jovem $c. Embora você talvez não seja mais tão jovem assim...$B$BAcho que está na hora de você ir mais fundo nessa terra. Eu consigo sentir que você está destinad$go:a; à grandeza.$B$BÉ a Encruzilhada que você deve buscar, pois nossas vidas e as dos orcs se entrelaçaram, e eles precisam de ajuda. Continue pela estrada do leste e siga o rumo norte até a Encruzilhada. Fale com Thork, dentro dos muros. A bênção da Mãe Terra está com ele.", t = "Jornada para a Encruzilhada"},
    [855] = {ot = "Leve 15 Braçadeiras de Centauro para Regthar Portões-da-morte a oeste da Encruzilhada.", st = "Os centauros Kolkar são uma ameaça ao domínio da Horda sobre os Sertões, e precisamos reduzir o contingente deles. Assim, eu lhe proponho uma tarefa a ser muito bem recompensada.$B$BEnquanto estiver em território Kolkar, mate os guerreiros deles e colete seus braceletes. Volte com um monte deles e a Horda $go:a; recompensará.", t = "Braçadeiras de centauro"},
    [857] = {ot = "Feegly, o Exilado, quer que você recupere a Lágrima das Luas para ele.", st = "O poder era meu! Estava nas minhas mãos! E eu o quero de volta! Eu disse que eu quero!$b$bAqueles escavadores imundos a descobriram... e era tão linda, ela. Chamaram de Lágrima das Luas. Foi a primeira grande descoberta em Bael Modan.$b$bEla para ela ter sido minha! Eu disse minha!$b$bO General Duas-tranças teve ciúme do poder que ela me deu. Ele a trancou na Bastilha. Disse que ela estava amaldiçoada! O ignorante!$b$bOutros a queriam, e precisavam ser detidos! Aquele desgraçado do Duas-tranças me expulsou!$b$bAgora... Eu a quero de volta! Eu quero! Eu já disse!", t = "A Lágrima das Luas"},
    [858] = {ot = "Consiga a Chave de Ignição para Manivela.", st = "Foi o Cobogó que te enviou? Tô numa enrascada. Pulei dentro sem nem pensar que ia precisar de uma chave para destravar a alavanca de movimentação do retalhador. Um dos pilotos me perguntou se estava tudo bem e eu entrei em pânico! Em vez de dizer que tava sem a chave, disse que tinha rolado um problema mecânico.$b$bPrecisamos vazar daqui, e rápido! Sobe lá na sala de controle na parte de cima do guindaste. Deve ter uma chave do Supervisor Rancatraca guardada lá.$b$bMe tira dessa!", t = "Ignição"},
    [862] = {ot = "Leve 8 Ratoupeiras para Grude a leste da Encruzilhada.", st = "$gUm:Uma; $c como você deve ficar com muita fome aqui nos Sertões. Eu? Eu estou morrendo de faminto aqui o dia todo.$b$bQuer saber? Eu arrumo um ensopado do bom. Só preciso de umas ratoupeiras.$b$bParece que aqueles anões nojentos em Bael Modan estão com uma praga que é um banquete. Agora vá até Bael Modan, no sul, e me traga umas boas ratoupeiras.$b$bVocê não pode se intitular aventureir$o:a; experiente se não tiver passado um tempo matando rato! Há!", t = "Ensopado de ratoupeira"},
    [863] = {ot = "Escolte o Manivela e o retalhador goblínico roubado até Cobogó, na Vila Catraca.", st = "Acho que vou ter que aprender no caminho... Não deve ser muito difícil. É só apertar uns botõezinhos, mexer na alavanca... E aí, tá $Gpronto:pronta; pra partir?", t = "A fuga"},
    [865] = {ot = "Obtenha 5 Chifres Intactos de Raptor de Garrafoices Helióscamos e leve-os para Cáliper Porcatraca na Vila Catraca.", st = "Os raptores dos Sertões são mais espertos que os de outros lugares. Acho que essa esperteza deles tá nos chifres! Se eu estiver certo, dá pra moer os chifres deles e usar o pó pra fazer \"drinques espertos\". Vou fazer fortuna, $Gmeu caro:minha cara;!$B$BE você pode quebrar o meu galho. Desenrola aí pra mim uns chifres de raptor intactos. Dos garrafoices helióscamos é que é a boa. Eles caçam no sul dos Sertões, e no norte também, perto da Floresta do Vale Gris.", t = "Chifres de raptor"},
    [866] = {ot = "Leve 8 Amostras de Raiz para Cáliper Porcatraca na Vila Catraca.", st = "As plantas dos Sertões não são como as plantas de outros lugares. As propriedades de ambas são praticamente as mesmas, mas a água do oásis altera as plantas. Elas ficam com uma leve diferença.$B$BQuero estudar as diferenças... pra ver se são lucrativas!$B$BSe tu tiver as manhas no herborismo, podia pegar umas amostras de raiz aí nos Sertões pra mim. Me traz as amostras, que eu vou comparar elas com plantas de outras regiões.", t = "Amostras de raiz"},
    [867] = {ot = "Obtenha 8 Garras de Asabruxa.$B$BLeve-as para Darsok Punhálacre na Encruzilhada.", st = "Essas harpias dos infernos já saquearam as nossas caravanas por tempo demais. Está na hora de cortar algumas gargantas e controlar essa praga.$B$BEu tenho rondado os ninhos delas e descoberto quem manda em quem. Precisamos de um ataque que atinja grande parte da cadeia de comando inferior e, com isso, poderemos galgar até o topo.$B$BVamos começar por baixo. Aniquile as harpias Asabruxa e as Asabruxas plumerrantes no noroeste e traga-me 8 garras delas. Isso já deve ser um bom começo...", t = "As harpias bandoleiras"},
    [868] = {ot = "Obtenha 12 Ovos de Silitídeo e devolva a Garra de Escavação para Korran na Encruzilhada.", st = "Ei, $n. Me mandaram para a Encruzilhada para vigiar a região e registrar eventos importantes para meus mestres em Orgrimmar.$B$BUm dos objetos de meus estudos são as criaturas insetoides encontradas ao sul, no Campo dos Gigantes. Sabemos pouco sobre as criaturas, e eu faço questão de descobrir mais. Elas parecem ter inteligência própria, mais que qualquer animal normal.$B$BLeve essa garra de escavação e colete alguns ovos das criaturas nos montículos delas, mas cuidado com os ninhos. Se alertadas, elas atacarão.", t = "Ovo tipo extra"},
    [869] = {ot = "Leve 12 Cabeças de Raptor para Gazrog na Encruzilhada.", st = "Não faz muito tempo, um carregamento de prata, que se destinava à folha de pagamento dos guardas da Encruzilhada, foi roubado da nossa torre de guarda. Nós queremos aquela prata de volta.$B$BO estranho é que pegamos um dos ladrões na noite do roubo e... era um raptor! Inacreditável!$B$BNão faço ideia do propósito que a prata teria para os raptores. Mas não importa... Quero eles mortos para que não voltem a roubar de nós!$B$BCace os raptores nos Sertões. Traga-me as cabeças deles!", t = "Raptores ladrões"},
    [870] = {ot = "Informe Tonga Runa Totem sobre as suas descobertas.", st = "Tempos atrás, os Sertões eram um lugar exuberante, a vida resplandecia. Mas a guerra e cataclismos devastaram a região, deixando apenas restos secos e calcinados. Quando isso aconteceu, meu coração se partiu.$B$BNos últimos anos, no entanto, novos oásis se formaram e a vida voltou aos Sertões. Nós druidas sentimos um poder afluir das entranhas da terra rumo à superfície.$B$BTemos que achar a origem dele. Vá até os Charcos Esquecidos, a noroeste da Encruzilhada. Procure a fonte desse poder nas águas e venha falar comigo de novo.", t = "Os Charcos Esquecidos"},
    [871] = {ot = "Da tribo dos Crinavalha, mate 8 Rabdomantes, 8 Tecespinhos e 3 Caçadores, depois fale novamente com Thork na Encruzilhada.", st = "Todos os javatuscos são inimigos, $n. Mas alguns se tornam uma verdadeira pedra no sapato.$B$BA tribo dos Crinavalha tem atacado nossas linhas de suprimentos vindas de Durotar, é uma dor de cabeça sem fim. Os batedores saíram à caça do líder dos raides, mas, enquanto não o encontramos, qualquer dano infligido aos porcos imundos nos ajudaria.$B$BComece pelo nordeste, na direção de Durotar. Os covis deles são muito fáceis de achar, basta procurar as vinhas espinhentas que brotam da terra. Encontre-os e mate-os.", t = "Cortando o ataque pela raiz"},
    [872] = {ot = "Mate 8 Geomantes Crinavalha, 8 Defensores Crinavalha e Kreenig Rosnento.$B$BDepois leve a Presa de Kreenig Rosnento para Thork, na Encruzilhada.", st = "Um dos meus batedores testemunhou um ataque contra uma caravana de Durotar, $n. Os responsáveis são da tribo de javatuscos Crinavalha. O javatusco que lidera os raides se chama Kreenig Rosnento. Ele foi visto a nordeste daqui, logo ao sul da estrada para Durotar. Só a morte de Kreenig vai dar fim a esta ameaça.$B$BPorém, para dar uma lição bem dada e acabar de vez com os ataques, é preciso ir além. Mate Kreenig e outros integrantes da tribo, depois me traga a presa dele.", t = "Adeus aos ataques"},
    [873] = {ot = "Leve o Coração de Isha Awak para Mahren Vidente do Céu.", st = "Estas águas são o domínio do grande Isha Awak. Grandiosa é sua força, e solene, seu orgulho. Os humanos da costa o temem, pois muitos foram suas vítimas.$B$BEu, porém, não o temo. Sou grata pela sua presença. Ele é um desafio digno e uma presa ainda mais honrosa.$B$BCaso sinta-se $Gpreparado:preparada;, mergulhe de cabeça e cace Isha Awak, a Ruína Profunda.$B$BO espírito dele reside no coração, cuja batida sela o destino de quem a ouve.", t = "Isha Awak"},
    [874] = {ot = "Fale com Mahren Vidente do Céu.", st = "Você já caçou as feras dos Sertões. Seu espírito é forte. Mas $Gum:uma; caçado$Gr:ra; de verdade tem que estar sempre preparad$Go:a;. $GUm:Uma; caçado$Gr:ra; de verdade persegue a presa por qualquer caminho. Montanhas e pântanos não são páreo para sua determinação.$B$BNem mesmo o oceano.$B$BEncontre a minha irmã, Mahren. Ela vive no litoral, caçando as feras da água. Ela ensinará a você os segredos delas.$B$BMas cuidado quando for procurar Mahreen, pois a costa dos Sertões é território dos humanos.", t = "Mahren Vidente do Céu"},
    [875] = {ot = "Obtenha 6 Anéis de Tenente Harpia de Asabruxas Matadoras e leve-os para Darsok Punhálacre na Encruzilhada.", st = "Hahaha, $n. Já voltou? Ótimo, gosto desse entusiasmo.$B$BDesta vez, quero que você mate umas tenentes harpias nos Montes Áridos. Apenas Asabruxas Matadoras podem virar tenentes, e dá para identificá-las pelo anel que elas usam. É um bando cruel, mas que lidera alguns subalternos nessa área. Eliminar uma meia dúzia delas será um golpe e tanto contra esse matriarcado.$B$BFaça com que sofram bastante antes de morrer, $n. Vamos mostrar para essas megeras o erro que cometeram quando compraram briga com a Horda.", t = "Tenentes harpias"},
    [876] = {ot = "Mate Serena Plumassangue e leve a cabeça dela para Darsok Punhálacre na Encruzilhada.", st = "Você se saiu muitíssimo bem contra tenentes e subalternos, por isso, quero que faça uma última coisa por mim.$B$BSerena Plumassangue é irmã de uma harpia chamada Plumassangue, que foi morta por Rexxar algum tempo atrás. Parece que os ataques às caravanas da Horda são uma vingança pela morte da irmã.$B$BQuero que você corte a garganta me traga a cabeça de Serena. Vou mandar exibi-la na próxima caravana que sair... e fazer essas harpias pensarem duas vezes.", t = "Serena Plumassangue"},
    [877] = {ot = "Fale novamente com Tonga na Encruzilhada depois de investigar o Oásis Estagnado.", st = "Outros oásis dos Sertões podem ter fissuras como a que você viu nos Charcos Esquecidos. Se for assim, talvez as fissuras sejam a fonte da vida dos oásis.$B$BTemos que fazer o teste.$B$BAqui, tome estas sementes. Elas estão mortas e inférteis, mas vá com elas para o Oásis Estagnado, a sudeste daqui. Se encontrar uma fissura lá, coloque as sementes no interior dela e... veja o que acontece.", t = "O Oásis Estagnado"},
    [878] = {ot = "Mate 6 Rabdomantes Costagulha, 12 Tecespinhos Costagulha e 12 Geomantes Costagulha e fale novamente com Denterroto no Acampamento Taurajo, nos Sertões.", st = "Quero que você ataque meus inimigos. <bufa> Para ajudar Denterroto e os Crinavalhas, você precisa enfraquecer os Costagulhas. As duas tribos são muito espiritualizadas, ligadas à terra e seu poder. <bufa> Isso nos dá força para tudo... especialmente para a guerra.$B$BSe quiser descobrir quem está causando tanta angústia a Thork <bufa> e à Horda, ajude Denterroto! Ataque os líderes espirituais dos Costagulhas ao norte. Enfraqueça eles para que os Crinavalhas possam acabar com eles e governar os Sertões.", t = "Tribos em guerra"},
    [879] = {ot = "Mate Nak, Kâz e Lok Mataorc e leve o crânio deles para Denterroto no Acampamento Taurajo, que fica nos Sertões.", st = "Três javatuscos da minha tribo saíram do Urzal para liderar raides contra a Horda, $r. <bufa> Impiedosos e ardilosos, mas se você acabar com eles, a Encruzilhada e boa parte dos Sertões terá paz... <bufa> pelo menos quanto à tribo Crinavalha. <bufa>$B$BVá atrás de Nak, Kâz e Lok Mataorc. Eles ficam no extremo sul dos Sertões. Um é lançador de feitiços, outro é um rastreador e o líder, o Mataorc, <bufa> um guerreiro. Acabe com eles, $r, assim como eles acabaram comigo.", t = "Traição fatal"},
    [880] = {ot = "Leve 8 Cascos Alterados de Mordelisca para Tonga Runa Totem, na Encruzilhada.", st = "Suas descobertas são incríveis, $n. As propriedades desses oásis devem vir de uma fonte externa. Ou talvez interna.$B$BQuero saber como essas fissuras estão afetando as feras que bebem a água dos oásis.$B$BVá ao Oásis das Águas Claras e ao Oásis Estagnado para caçar mordeliscas e traga os cascos para mim. Quero examiná-los.", t = "Seres alterados"},
    [881] = {ot = "Leve o Pelego de Echeyaki para Sergra Espinhonegro, na Encruzilhada.", st = "Alva Névoa, ou Echeyaki na língua taurahe, é o rei dos felinos da savana. Quando caça, é tão sorrateiro que diz-se ser apenas uma névoa fina e branca sobre o solo. Suas presas morrem tão rápido que nem têm tempo de sentir medo ou dor.$B$BDe acordo com os taurens, ele é ao mesmo tempo misericórdia e morte.$B$BE você vai descobrir por si mesm$go:a; se isso é verdade, pois quero que cace Echeyaki. O covil dele fica a nordeste da Encruzilhada, entre ossos de kodos gigantes.$B$BVá. Quando chegar ao covil, sopre este berrante e ele virá.", t = "Echeyaki"},
    [882] = {ot = "Leve a Presa de Ishamuhale para Jorn no Acampamento Taurajo.", st = "Ishamuhale, o Dente-de-lança, é o raptor helióscamo mais feroz dos Sertões. Ele não caça por esporte, nem para comer. Ele caça porque a caça é a paixão dele. Ele mata porque essa é a natureza dele.$B$BE você aprenderá sobre a natureza dele, $n, pois seu caminho agora segue no encalço de Ishamuhale.$B$BComece a caçada. Mate a presa favorita dele, uma zevra, e leve a carcaça até a árvore morta a noroeste da Vila Catraca. Ishamuhale farejará a carcaça, e ela o atrairá.$B$BEsteja $Gpreparado:preparada; quando ele chegar.", t = "Ishamuhale"},
    [883] = {ot = "Leve o Casco de Lakota'mani para Jorn no Acampamento Taurajo.", st = "O Casco de Lakota'mani é um símbolo da força do grande kodo.", t = "Lakota'mani"},
    [884] = {ot = "Leve a Ponta da Cauda de Owatanka para Jorn no Acampamento Taurajo.", st = "Quando tocado, o espigão da cauda de Owatanka solta faíscas.", t = "Owatanka"},
    [885] = {ot = "Leve a Pena de Anhan Guera para Jorn Vidente do Céu, no Acampamento Taurajo.", st = "Ao toque, a pena de Anhan Guera machuca.", t = "Anhan Guera"},
    [886] = {ot = "Fale com Tonga Runa Totem na Encruzilhada.", st = "Os druidas do Penhasco do Trovão sentiram uma força estranha se infiltrando nos Sertões, a leste de Mulgore.$B$BTonga Runa Totem foi enviado para descobrir a fonte dessa força, mas achamos que ele vai precisar de ajuda.$B$BViaje até os Sertões e fale com Tonga. Ele vai estar na Encruzilhada. Para chegar lá, pegue a estrada a leste para sair da vila de Casco Sangrento. Entre nos Sertões, depois vire para o norte quando a estrada se dividir. Continue para o norte e você chegará à Encruzilhada.$B$BAh, e não saia da estrada, $n, os Sertões são uma terra perigosa.", t = "Oásis nos Sertões"},
    [887] = {ot = "Mate 12 Bucaneiros dos Mares do Sul e 6 Canhoneiros dos Mares do Sul para Gasganete, que aguarda na Vila Catraca.", st = "Eu queria é que o Vice-almirante Grezzlik fizesse melhor o trabalho de segurança marítima pras nossas embarcações mercantes. Com o ouro todo que os príncipes mercadores botam nas Frotas Mercantes, me revolta ver tanto pirata por aí, atacando os meus navios como bem entendem e roubando a minha mercadoria!$b$bDisseram que os Flibusteiros dos Mares do Sul resolveram acampar mais pro sul daqui. Eles tão sendo uma pedra no meu sapato, e se o Grezzlik não vai dar jeito, bem... Você pode me ajudar a dar um sumiço neles.", t = "Os Flibusteiros dos Mares do Sul"},
    [888] = {ot = "Recupere o Carregamento de Botas e a Lente Telescópica para Gasganete na Vila Catraca.", st = "Eu adoraria recuperar meus bens, mas com certeza não deve ser possível. Mesmo assim, tem algumas coisas de que eu não posso abrir mão!$b$bComo você pode ver, o meu observatório está pronto, mas ainda falta a lente menor. A primeira chegou na caravana de Durotar, mas a segunda vinha de navio e nunca chegou. Minha encomenda de botas com o Drizzlik na Angra do Butim também não!$b$bVai lá no acampamento dos piratas e vê se acha as minhas coisas, pode ser?", t = "Butim Roubado"},
    [890] = {ot = "Leve o Livro-caixa do Gasganete para o Mestre Portuário Caruncho.", st = "Já faz uma cara que eu tô esperando meu último carregamento de mercadorias da Angra do Butim! Tô achando que os Flibusteiros roubaram, mas, só pra garantir, você pode dar uma chegadinha lá nas docas e perguntar pro Caruncho se as minhas paradas já foram pro armazém e ninguém me avisou?$b$bToma aqui meu livro-caixa. Entrega pro Caruncho e pede pra ele conferir o inventário e comparar com o registro dele.", t = "Carregamento perdido"},
    [891] = {ot = "O Capitão Thalo'thas Solaz de Vila Catraca quer que você obtenha 10 Medalhas de Theramore e mate a Capitão Amazona, o Canhoneiro Ocastro e o Canhoneiro Smythe.", st = "Mais uma navio da frota perdido para os humanos insensatos da Fortaleza da Guardanorte!$b$bTemos que dar um jeito naqueles canalhas. A paranoia cria neles um frenesi. Essa gentalha abjeta se apraz atirando em tudo que vê.$b$bSiga para o Sul, rumo à Fortaleza, pela Costa dos Mercadores e cerceie as forças deles. Traga-me as medalhas dos soldados abatidos como prova. E, pelo amor de minha frota, acabe de uma vez por todas com a Capitão Amazona e seus canhoneiros mentecaptos!", t = "Os canhões da Guardanorte"},
    [892] = {ot = "Leve o Livro-caixa do Gasganete para o Gasganete na Vila Catraca.", st = "Tá tudo certo nos meus registros, $n. Diz pro Gasganete que ele tá sem sorte. Bem capaz que piratas tenham roubado o material dele, mesmo.$b$bNão posso fazer nada. Ah... Aproveita e diz que eu tô com umas coisas da Inframina pra ele. Aí quando ele tiver um tempinho pra vir buscar...", t = "Carregamento perdido"},
    [893] = {ot = "Leve um Punhal Crinavalha, uma Varinha de Crinavalha Carbonizada e um Escudo de Guerra Crinavalha ao Trapista Forjaço no Acampamento Taurajo, que fica nos Sertões.", st = "Pelo que eu sei, os javatuscos Crinavalha do sul, pra lá do Campo dos Gigantes, não têm ferreiros de calibre, mas parece que começaram a projetar armas mais robustas. Se for possível, quero pôr as mãos em algumas amostras das armas deles para analisar.$B$BSe você deseja honrar a Horda, então me traga amostras dessas armas. Quero uma adaga dos espreitadores, uma varinha dos clarividentes e um escudo dos belicosos. Isso deve bastar!", t = "Armas preferidas"},
    [894] = {ot = "Acesse o Painel de Controle no laboratório da Empreendimentos S.A.", st = "A Empreendimentos S.A. montou um pequeno laboratório de pesquisa bem longe ao norte daqui, a sudoeste do Charco de Lodo. Não sei muito sobre o que estão fazendo, mas consegui descobrir que são experiências com um troço chamado \"rebimboca\".$b$bQue diabos é uma rebimboca? Não importa. Seja o que for, quero examiná-la, então preciso que alguém vá lá pegá-la.$b$bConsegui uma cópia do manual de operação do sistema de controle deles. Com ele você descobre como desencaixar a rebimboca.", t = "A rebimboca"},
    [895] = {ot = "Leve a cabeça do Barão Longacosta para Gasganete na Vila Catraca.", st = "PROCURA-SE!$b$bBarão Longacosta, Capitão do Imprudente$b$bO Capitão Longacosta de Guilnéas lidera a frota dos Flibusteiros dos Mares do Sul e é procurado por pirataria. Os restos mortais devem estar em condição identificável!$b$b– Gasganete", t = "PROCURA-SE: Barão Longacosta"},
    [896] = {ot = "Consiga a Esmeralda Olho-de-gato de um dos feitores ou seguranças da Empreendimentos S.A. e leve para o Mestre Portuário Caruncho, em Vila Catraca.", st = "Como Mestre de um porto movimentado como o de Vila Catraca, eu vivo de butuca pra saber tudo o que tá rolando. Fico ligado em todas as trocas de itens e dinheiro que acontecem entre a Vila e a Angra do Butim.$b$bA última que fiquei sabendo veio da mina Veio do Pedregulho, da Empreendimentos S.A., que fica a nordeste do Charco de Lodo. Um dos mineiros descobriu uma esmeralda do tamanho de uma mão fechada. Tenho contatos que estão interessados em comprar a pedra e estou disposto a dividir o valor meio a meio.", t = "A fortuna do mineiro"},
    [897] = {ot = "Leve a Cabeça do Ceifador para Jorn Vidente do Céu.", st = "Essa criatura estranha, insectoide, parece não fazer parte da ordem natural, como se não pertencesse aos Sertões.", t = "O ceifador"},
    [898] = {ot = "Escolte Gilthares Galhareda em segurança até o Capitão Solaz, que está na Vila Catraca.", st = "Até que enfim alguém veio me salvar!$b$bNão acredito que você passou pelos guardas. Aqueles fanáticos de Theramore piraram. Eles afundaram nosso navio e só eu sobrevivi, mas acabei preso. Fui acusado de traição e considerado uma ameaça à Aliança.$b$bQuem sou eu para ameaçar essa farsa gigantesca que é a Aliança? Fui marujo num navio que transportava pinga entre a Vila Catraca e a Angra do Butim.$b$bChega de conversa. Você vai me ajudar a voltar para a Vila Catraca, não vai? É só dar o sinal e damos o fora daqui.", t = "Ex-detento"},
    [899] = {ot = "Leve 60 Presas de Javatusco Costagulha para Mankrik na Encruzilhada.", st = "Talvez você já saiba bem como é a dor da incerteza, $c; talvez não. Mas saiba: eu fico aqui todos os dias, do alvorecer ao crepúsculo, perscrutando o horizonte em busca de mais monstros. Matei todos os homens-porcos que cruzaram o meu caminho, mas minha sede de sangue está longe de ser saciada. Em vez de vir para o norte, para a Encruzilhada, talvez eu devesse ter rumado para Taurajo.$B$BVocê, $c... você pode me ajudar.$B$BMate-os. Mate todos que encontrar. Traga-me suas presas e vamos celebrar juntos a morte deles.", t = "Consumido pelo ódio"},
    [900] = {ot = "Feche a Válvula de Controle de Combustível, a Válvula de Regulagem e a Válvula Principal e, em seguida, use o Painel de Controle.", st = "As três válvulas de controle estão abertas. A sequência de leituras disposta no painel leva você à conclusão de que é preciso fechar as válvulas para desligar o aparato.", t = "A rebimboca"},
    [901] = {ot = "Pegue a Chave do Painel do Engenhoqueiro Faísca para usar no painel de controle.", st = "Agora que o aparato está desativado, o painel de controle pode ser aberto e a rebimboca removida do painel. Agora só resta obter a chave do painel para destravar o console.", t = "A rebimboca"},
    [902] = {ot = "Leve a Rebimboca para Cobogó na Vila Catraca.", st = "Quando o painel é aberto, uma densa selva de cabos, fios e estranhos objetos mecânicos se revela, a maioria dos quais parece completamente inútil. Afastando-os, para alcançar o fundo do console, você encontra a rebimboca. Com um puxão você a remove do compartimento.", t = "A rebimboca"},
    [903] = {ot = "Colete 7 Garras de Predador de Predadores da Savana para Sergra Espinhonegro na Encruzilhada.", st = "Agora é hora de ir atrás de algo que morde pra valer. Os predadores dos Sertões são uma raça difícil. Difícil, engenhosa, astuta... e mortal. Você vai encontrá-los em meio à grama alta. Você encontrará muitos a sudoeste da Encruzilhada.$B$BNão se descuide, $n, ou você pode acabar passando de predador a presa.", t = "Predadores dos Sertões"},
    [905] = {ot = "Mate raptores Helióscamos e colete as penas. Use as penas em 3 dos ninhos de Garrafoices. Fale novamente com Sergra Espinhonegro na Encruzilhada.", st = "Agora, $n, a caçada se intensifica. Desta vez você terá de derrotar sua presa e depois encontrar o covil.$B$BCace os raptores helióscamo ao sul. Mate-os e retire suas penas. Deposite as penas nos ninhos de garrafoice, a sudoeste do Oásis Estagnado. Mostre a eles que você não tem medo deles!", t = "Garrafoices furiosos"},
    [906] = {ot = "Leve o Crânio de Lok para Thork na Encruzilhada, que fica nos Sertões.", st = "Leve a cabeça de Lok para Thork na Encruzilhada, $r. <bufa> Ele deveria saber o que aconteceu com a minha tribo sem qualquer palavra — rá, mas ele nunca acreditaria que Denterroto ajudou <bufa> nestas coisas. Tenho certeza de que ele vai lhe recompensar por cumprir uma missão tão importante. <bufa>$B$BVou continuar a abençoar você com o poder de Agamaggan durante o tempo em que eu permanecer nesta gaiola, $r. Até lá, adeus.", t = "Traição intestina"},
    [907] = {ot = "Leve 3 unidades de Sangue de Lagarto Trovejante para Jorn Vidente do Céu, no Acampamento Taurajo.", st = "Agora, $n, você deve enfrentar os grandes lagartos trovejantes. Essas criaturas são tão grandes que o chão ressoa quando atravessam pesadamente as planícies. Tome cuidado ao lutar com essas feras, pois qualquer passo em falso e você pode acabar sob os pés delas.$B$BVocê vai encontrar os lagartos trovejantes na parte sul dos Sertões. Eles são conhecidos como Eletrossauros, Borrascouros e Cabeças-de-trovão. Fale novamente comigo depois que derrotá-los.", t = "Lagartos trovejantes enfurecidos"},
    [913] = {ot = "Encontre e mate um falcotrom, depois leve as asas dele para Jorn Vidente do Céu, no Acampamento Taurajo.", st = "O falcotrom, $n, é uma fera muito poderosa. Chegou a sua hora de enfrentá-lo. Descubra o paradeiro dele e traga-me as asas da fera para comprovar que sua caça foi um sucesso.$B$BFaça isso, e seu tempo comigo estará próximo do fim.", t = "O grito do Falcotrom"},
    [914] = {ot = "Leve as Gemas de Cobrahn, Sucurina, Pítias e Serpentis para Nara Juba Agreste no Penhasco do Trovão.", st = "Aqueles druidas da Caverna Ululante, os Druidas da Presa, são umas aberrações. Eles já fizeram parte de uma ordem de druidas nobres cujo plano era curar os Sertões, mas passaram a buscar a recriação dessa terra à imagem e semelhança dos sonhos torpes deles.$B$BOs Druidas da Presa têm quatro líderes, cada um em posse de uma gema onírica. Mesmo acordada, eles conseguem me assombrar! Derrote os líderes e traga-me as gemas. Só assim os Sertões terão paz.$B$BVá, $n. Os druidas podem ser encontrados à espreita no fundo da Caverna Ululante.", t = "Líderes da Presa"},
    [916] = {ot = "Leve 10 Vesículas de Peçonha de Lenhateia para Gilshalan Andavento em Aldrassil.", st = "Eu vim para Umbravale no intuito de observar as aranhas lenhateia que vivem na Caverna Fionumbra. Elas são primas de uma variedade muito menor, o que me leva a crer que a Árvore do Mundo tenha um efeito profundo sobre elas. Por isso, eu gostaria de obter alguns espécimes para realizar estudos e confirmar isso.$B$BAntes, no entanto, preciso de um pouco do veneno delas. Pegue vesículas de peçonha de lenhateia das aranhas na Caverna Fionumbra, ao norte, e nas redondezas. Assim poderei examiná-las e confirmar se há similaridades entre a peçonha delas e a de suas primas menores.", t = "Peçonha de lenhateia"},
    [917] = {ot = "Leve um Ovo de Lenhateia para Gilshalan em Aldrassil.", st = "Agora que consegui peçonha de aranhas, preciso estudar espécimes vivos. Infelizmente, é demais pedir a você, jovem $c, que capture uma aranha gigante. E mesmo que você conseguisse, eu não daria conta de lidar com ela depois!$B$BMas se puder encontrar um ovo não eclodido, será mais fácil obter alguns espécimes, e posso dar um jeito de conter essas aranhas pré-natais também.$B$BAcredito que haja um ninho no fundo da Caverna Fionumbra. Por favor, encontre um ovo nesse ninho e traga-o para mim.", t = "Ovo de Lenhateia"},
    [918] = {ot = "Leve 8 Sementes de Muscoide para Denelan no Lago Al'Ameth.", st = "Os muscoides de Teldrassil são elementais da natureza. Eles refletem alguns aspectos da ordem natural de plantas e animais em nossa grande árvore.$B$BÉ preocupante vê-los se tornando tão raivosos.$B$BCreio que seja algo relacionado ao solo. Tenho trabalhado em diferentes métodos para o cultivo de plantas e gostaria de testá-los em sementes de muscoides. Por favor, poderia me trazer algumas sementes dos muscoides perto do Lago Al'Ameth?", t = "Sementes de muscoide"},
    [919] = {ot = "Leve 12 Brotos de Muscoide para Denalan no Lago Al'Ameth.", st = "Pequenos muscoides crescem ao redor das águas do Lago Al'Ameth. Temo que tais brotos não possam ser salvos. Devemos tirá-los da terra antes que cresçam ao ponto de nos causar problemas.$B$BQuando estiver andando pelo lago, por favor arranque os brotos de muscoides que encontrar. Ajude a manter este terra limpa!", t = "Brotos de muscoide"},
    [920] = {ot = "Fale com Tenaron Fortagarras no topo de Aldrassil, em Umbravale.", st = "$n, não é? Ouvi que Tenaron tem perguntado de você. Você o encontra no topo de Aldrassil, no salão mais alto.$b$bNossas vidas são longas, é verdade, mas é melhor não deixá-lo esperando.", t = "O chamado de Tenaron"},
    [921] = {ot = "Encha o Frasco de Cristal e leve-o de volta para Tenaron Fortagarras, no topo de Aldrassil.", st = "Chegou a hora de sair em busca do seu destino, $n. Mas, antes de se considerar pront$Go:a; para ganhar o mundo além das nossas florestas encantadas, você ainda precisa aprender mais sobre a nossa história recente.$b$bDesde a Batalha do Monte Hyjal, nosso povo passou por muitas mudanças. Nordrassil não passa de uma pálida sombra do que já foi, pois seu poder foi usado para derrotar Arquimonde e afugentar a Legião Ardente...$b$bVocê deve cumprir uma tarefa. Vá ao poço lunar ao norte de Aldrassil e traga-me um frasco da água de lá.", t = "Coroa da Terra"},
    [922] = {ot = "Leve uma Semente de Muscoide para Rellian Spiraverde, em Darnassus.", st = "$n, pode pegar uma dessas sementes que você me trouxe e levá-la para o meu amigo, Rellian Spiraverde? Ele é um druida de Darnassus e, da última vez em que nos falamos, ele demonstrou interesse em trabalhar com os Muscoides. Ele tinha algumas ideias boas e vai gostar de receber uma semente para suas pesquisas.$B$BObrigado, $n. Você me prestou um grande serviço. Espero que, um dia, você possa ver os frutos do meu trabalho.$B$BRellian costuma gostar de perambular pelas trilhas do Enclave Cenariano, em Darnassus.", t = "Rellian Spiraverde"},
    [923] = {ot = "Leve 5 Tumores Musguentos para Rellian Spiraverde, em Darnassus.", st = "Existe um mal crescente nos muscoides. Estamos tentando descobrir a origem, mas até lá... se quisermos manter Teldrassil a salvo, devemos acabar com os muscoides que não tem mais salvação. Aqueles que vagueiam perto do Lago Olho-d'água, ao norte de Teldrassil, são os mais maculados. Precisamos acabar com eles!$B$BDestrua os muscoides que encontrar lá e arranque os tumores musguentos que crescem neles. Traga-me os tumores para que sejam queimados.", t = "Tumores"},
    [924] = {ot = "Pegue uma Pedra do Poder Defeituosa. Leve-a ao Altar de Fogo antes que ela expire e fale novamente com Ak'Zeloth.", st = "A Semente Demoníaca é um instrumento poderoso da Legião Ardente. Ela fica num altar de fogo demoníaco, dentro de uma caverna do Morro de Brumedo.$B$BFiz algumas pedras de poder que bloqueiam a conexão da Semente com a Legião quando colocadas perto dela.$B$BPegue uma pedra na mesa e leve até o altar de fogo no cume do Morro de Brumedo. Vá para oeste e vire para o norte ao chegar numa encruzilhada. Você vai ver o morro à sua esquerda. É mais seguro subir o morro pela face norte.$B$BVá depressa, a energia da pedra não dura muito.", t = "A Semente Demoníaca"},
    [926] = {t = "Pedra do Poder Defeituosa"},
    [927] = {ot = "Leve o Coração Enroscado em Musgo para Denalan no Lago Al'Ameth.", st = "O coração do Limonegro, o Fétido, está coberto com um limo negro oleoso. A única coisa que o identifica como um coração é a lenta batida rítmica... uma batida que continua mesmo depois de morto.$B$BTalvez Denalan queira ver este coração.", t = "O coração enroscado em musgo"},
    [928] = {ot = "Leve o Recipiente Parcialmente Cheio a Corithras Lunafúria em Dolanaar.", st = "Ainda tenho muito a dizer sobre os poços lunares e sobre Teldrassil, mas você precisa ir. Corithras Lunafúria $Go:a; aguarda. Passei a água que me trouxe para este outro vidro, que você deve levar a ele.$b$bCorithras se encontra no poço lunar de Dolanaar. Siga a estrada ao sul de Aldrassil até sair de Umbravale e continue seguindo os paralelepípedos a oeste.$b$bAconselho que não saia da estrada, $n. Ultimamente, feras perigosas andam rondando a floresta.", t = "Coroa da Terra"},
    [929] = {ot = "Encha o Frasco de Jade e leve-o de volta para Corithras Lunafúria em Dolanaar.", st = "Antes, deixe-me contar mais sobre a tarefa que você precisa cumprir. Os druidas em Darnassus usam a água dos poços lunares de Teldrassil, que precisam ser reabastecidos regularmente. Usando estes frascos especialmente criados, apanhe a água desses poços.$b$bLeve este recipiente para o poço lunar a leste do Vilarejo Brisastral e encha-o com um pouco da água. Volte quando tiver acabado. Quando tiver concluído sua tarefa, continuarei a história de onde Tenaron parou...", t = "Coroa da Terra"},
    [930] = {ot = "Leve a Fruta Brilhante para Denalan no Lago Al'Ameth.", st = "Dependurada em meio à folhagem desta planta lustrosa há uma fruta grande e redonda.$B$BDenalan certamente gostará de estudá-la.", t = "A fruta brilhante"},
    [931] = {ot = "Leve uma Fronde Cintilante para Denalan no Lago Al'Ameth", st = "As frondes desta planta reluzem sob a luz da floresta, emitindo uma trançada aura pulsante.$B$BVocê acredita que Denalan gostaria de um espécime disto.", t = "A fronde cintilante"},
    [932] = {ot = "Mate o Senhor Málinus e leve a cabeça dele para Tallonkai Radicélere, em Dolanaar.", st = "Preciso alertá-$Glo:la;, $n, este assunto deve ficar entre nós. Os sátiros são um aborrecimento constante e um deles mora próximo demais do nosso lar.$B$BEle se chama Senhor Málinus e reside na caverna da Pedra Vil, onde reuniu um grande grupo de criaturinhas demoníacas. O coração dele é negro como a noite, e sei que ele planeja algo terrível.$B$BEncontre-o na caverna a norte daqui e traga-me a cabeça dele.", t = "Aversão pervertida"},
    [933] = {ot = "Encha o Frasco de Turmalina e leve-o de volta para Corithras Lunafúria em Dolanaar.", st = "Há outro poço lunar a sudeste da entrada de Darnassus, no litoral das Águas de Arlithrien. As Sentinelas estão tendo dificuldade para patrulhar a área por causa dos ataques decorrentes de um temperamento cada vez mais bravio por parte dos pelursos Masca-pinho.$b$bTenha cuidado quando for procurar pelo poço – e mantenha suas armas sempre à mão.", t = "Coroa da Terra"},
    [935] = {ot = "Leve o Recipiente Cheio para o Arquidruida Fandral Guenelmo em Darnassus.", st = "Sem as bênçãos de Alexstrasza, a Mãe da Vida, e Nozdormu, o Atemporal, o crescimento de Teldrassil foi prejudicado. Criaturas estranhas foram avistadas saindo do próprio solo da árvore, e pelursos enlouquecidos atacaram viajantes.$b$bSó me resta esperar que a solução que o Arquidruida procura seja encontrada em breve. Eu porei todos os frascos que você trouxe neste recipiente, para que você os entregue em Darnassus.$b$bLeve-o para Fandral Guenelmo. Você o encontra no bosque dos druidas.", t = "Coroa da Terra"},
    [937] = {ot = "Consiga 6 Cintos Plumassangue e leve-os para a Sentinela Arynia Rasganimbus, na Clareira do Oráculo.", st = "Fui enviada para cá com um pequeno grupo de Sentinelas para proteger a Árvore dos Oráculos das harpias que fizeram seus ninhos por toda a clareira. Aos poucos, estamos tentando expulsá-las.$B$BQuando a Árvore dos Oráculos tentou enviar um mensageiro para Darnassus com um relatório, ele foi atacado e morto por um grupo de harpias.$b$bSe quiser ajudar, vá até os ninhos e mate-as. Traga-me os cintos delas como prova.", t = "A Clareira Encantada"},
    [938] = {ot = "Escolte Bruma para a Sentinela Arynia Rasganimbus no poço lunar, perto da Árvore dos Oráculos.", st = "O pelame da gata-de-sabre é de um cinza inconfundível que se mistura com a floresta ao redor. Você observa que ela está gravemente ferida e com profundas lacerações nas costas e na barriga.$b$bEla levanta a cabeça e fixa o olhar em você, com brilhantes olhos azuis que transmitem sabedoria. Ela parece querer seguir você.", t = "Bruma"},
    [940] = {ot = "Entregue a Casca de Árvore Inscrita ao Arquidruida Fandral Guenelmo em Darnassus.", st = "A floresta me sussurra os seus feitos valorosos, $n. Senti as harpias sendo expulsas de seus ninhos e a calma que se espalhou pela floresta em seguida, com as criaturas novamente se sentindo em segurança. Eu estava com medo de enviar outra mensagem para o arquidruida, mas agora sei que você consegue cumprir a missão em segurança.$b$bEntregue isto a ele e fique tranquil$go:a;, a floresta vai proteger você no caminho até a floresta de pedra.", t = "Teldrassil"},
    [941] = {ot = "Plante o Coração Maculado na Sementeira do Denalan.", st = "Removi o limo pútrido do coração, mas ele ainda está maculado...$B$BTente colocá-lo na sementeira  que enchi de terra nutritiva. Talvez ela limpe e cure este coração.", t = "Plantando coração"},
    [942] = {ot = "Leve o fóssil misterioso ao Arqueólogo Pançacheia no Porto de Menethil.", st = "A estampa desse fóssil me recorda de outro que vi em Altaforja. Um arqueólogo que atende por Pançacheia trouxe na conferência anual da Liga dos Exploradores. Dava por certo que fóssil tinha um poder que dava para liberar.$b$bDa última notícia que tive, Pançacheia tinha se abancado na Taberna Aguafunda, lá no Porto de Menethil. Tá só esperando uma escolta pra picar a mula pro Sítio de Escavação de Whelgar. Alcança o vivente e mostra teu fóssil do Trilheiro. Se bobear, ele dá conta de te revelar esses mistérios do passado.$b$bO navio pra Menethil zarpa de Auberdine.", t = "O prospector distraído"},
    [943] = {ot = "Arqueólogo Pançacheia, no Porto de Menethil, quer que você traga a Pedra de Relu e o Fóssil do Pançacheia para ele.", st = "O fóssil original está com o Prospector Whelgar, enfiado no sítio de escavação dele no Pantanal. Quando me informei da Pedra de Relu, me dei conta de que ela podia ser a chave para decifrar o mistério do fóssil.$b$bQuando troteava para me encontrar com Whelgar, raptores me deram uma volteada e se foi a relíquia. Não sei qual das criaturas mosquetuscas papou a relíquia, mas, se deres conta de recuperá-la, vou poder liberar o poder desses artefatos.$B$BVê se me trazes a Pedra de Relu, e não te esquece do fóssil original dele.", t = "O prospector distraído"},
    [944] = {ot = "Reúna informações, depois use o Frasco de Vidência para criar uma Bacia de Vidência. Use a bacia para falar com Onu.", st = "Acho estranho que as nagas estejam aqui, na Costa Negra. Mas ainda mais estranho... é o Martelo do Crepúsculo. Esse culto venera os muito, muito antigos senhores da terra. Senhores há muito derrotados.$B$BUm desses antigos senhores foi derrotado na Glaive do Mestre, que fica ao sul daqui.$B$BVá até lá e procure mais sectários do Martelo do Crepúsculo.$B$BLeve este frasco de vidência. Depois de procurar na Glaive do Mestre, use o frasco para criar uma bacia de vidência, que você vai usar para falar comigo.", t = "Glaive do Mestre"},
    [945] = {ot = "Ajude Therylune a escapar e, depois, conte a Therysil, no Altar de Aessina, que a irmã dela está a salvo.", st = "Socorro!$B$BEu estava andando perto da Glaive do Mestre e esses sectários imundos me cercaram. Que bom que eu sou boa em me esconder!$B$BVocê pode me ajudar a sair daqui? E eu preciso dar notícias a Therysil, a minha irmã, dizendo que eu estou bem. Ela está no Vale Gris, mais pro sul, no Altar de Aessina.", t = "A fuga de Therylune"},
    [947] = {ot = "Leve 5 Galhos de Piolho e 1 Cogumelo-cicuta para Barithras Sombraluna, em Auberdine.", st = "Estou criando uma poção que requer cogumelos raros, cogumelos que só crescem em uma determinada caverna. A caverna fica por trás das Quedas do Fontescarpa, a leste e ligeiramente ao norte, ao longo das montanhas.$B$BEu mesmo iria até lá, mas fui aconselhado pelo Bosque dos Ancientes a ficar longe daquele lugar. Nossos veneráveis aliados sentem que a caverna é o esconderijo de um novo mal na Costa Negra.$B$BPor favor, $n, colha os cogumelos para mim. Aproveite, então, para explorar a caverna e ver se confirma o receio dos Ancientes.", t = "Cogumelos da caverna"},
    [948] = {ot = "Fale com Onu no Bosque dos Ancientes.", st = "Onu, um Anciente da Tradição no Bosque dos Ancientes, soube da sua jornada às Quedas Vertentes e deseja falar com você. O bosque fica ao sul, perto das montanhas.$B$BAncientes costumam ser pacientes e sábios, $n, mas se Onu busca sua opinião acerca do presenciado na queda d'água, creio que seja urgente.", t = "Onu"},
    [949] = {ot = "Encontre uma pista no acampamento do Martelo do Crepúsculo, que fica na Glaive do Mestre.", st = "Não se sabe o propósito do Martelo do Crepúsculo na Glaive do Mestre, mas deve ser sinistro.$B$BVasculhe o acampamento na Glaive... Encontre alguma coisa que nos dê uma pista sobre as intenções dele.$B$BÉ importante sabermos disso antes de traçarmos um plano.", t = "O Acampamento do Crepúsculo"},
    [950] = {ot = "Leve para Onu os Rabiscos Malucos.", st = "Perscrutar o Tomo do Crepúsculo é enlouquecedor. Num segundo o texto começa a oscilar e dançar, e as belas iluminuras se transformam em formas grotescas.$B$BArrancar uma página de rabiscos malucos é tudo o que é possível fazer antes de desfalecer.", t = "A volta a Onu"},
    [951] = {ot = "Leve 6 Relíquias de Mathistra para Onu no Bosque dos Ancientes.", st = "O pergaminho que você achou na Glaive do Mestre é uma página de um texto antigo... escrito por elfos! Está com maldições pesadas e maculado pela corrupção do Martelo do Crepúsculo, mas parece que a seita está usando magia élfica antiga para trazer seus antigos mestres de volta ao nosso mundo.$B$BVá às Ruínas de Mathistra, a nordeste, e procure relíquias antigas no meio da grama e das pedras ruídas. Estudando-as podemos adivinhar como o Martelo do Crepúsculo pretende explorar a magia dos elfos.", t = "Relíquias de Mathistra"},
    [952] = {ot = "Entregue a mensagem de Fandral para Onu no Bosque dos Ancientes, que fica na Costa Negra, ao sul de Auberdine.", st = "Se você teve tempo para sair levando recados para a Árvore dos Oráculos, devo insistir para que você entregue uma mensagem ao Bosque dos Ancientes na Costa Negra, ao sul de Auberdine.$b$bÉ bem provável que você precise viajar de hipogrifo, mas tenho plena confiança nas suas capacidades. Leve isto aqui para Onu, o Anciente da Tradição. Ele está esperando notícias minhas, assim como eu estava esperando notícias da Clareira do Oráculo.", t = "Bosque dos Ancientes"},
    [953] = {ot = "Estude as tabuletas que contam sobre Ameth'Aran e sua queda, depois fale novamente com a Sentinela Tysha Lamiluna na Costa Negra.", st = "A leste, você vai encontrar as ruínas de Ameth'Aran. O lugar agora é habitado pelos espíritos inquietos dos Altaneiros que um dia viveram dentro de seus muros, mas outrora foi um lugar em que os servos de Azshara praticavam livremente sua poderosa magia.$b$bFui enviada para explorar as ruínas e encontrei duas grandes tabuletas, que contam a história e a queda de Ameth'Aran. Enquanto lia as runas, fui acossada pelos espíritos e fugi.$b$bPor favor, se puder, entre nas ruínas e decifre as tabuletas por mim.", t = "A queda de Ameth'Aran"},
    [954] = {ot = "Encontre a fonte da estranha aura azul nas ruínas de Bashal'Aran.", st = "As ruínas de Bashal'Aran a leste estão infestadas de lacaios demoníacos. Os duendes e sátiros que se instalaram no local se alimentam das energias mágicas da área, e os poderes deles aumentam com a exposição continuada.$b$bMesmo com isso, notei que eles não se aproximam de um determinado santuário. No alto de um pequeno penhasco no lado oeste das ruínas, uma estranha aura azul permeia o lugar... Deve haver uma explicação para a relutância dos demônios.$b$bEu gostaria que você investigasse isso.", t = "Bashal'Aran"},
    [955] = {ot = "Consiga 8 Brinco de Capeta para Astérion em Bashal'Aran.", st = "Se eu contasse a história de minha vida, sem dúvida ela iria além do limite da sua paciência. Digamos apenas que minha vida foi longa e sofrida, e que essa forma espectral talvez seja o pior de todos os tormentos.$b$bEstou preso aqui por meios mágicos. Embora minhas palavras pareçam ingênuas, eu lhe garanto que ficarei indescritivelmente grato se você me ajudar a descobrir os meios de meu encarceramento. Um selo me agrilhoa, e examinando os brincos dos duendes e capetas eu posso encontrar alguma pista dele.", t = "Bashal'Aran"},
    [956] = {ot = "Obtenha o Selo Antigo de Pedra-da-lua e leve-o para Astérion em Bashal'Aran.", st = "Se os capetas tiveram contato com o selo que me aprisiona, tenho minhas suspeitas quanto ao motivo. Sem dúvida o selo está em posse do sátiro que os lidera.$b$bSinto que essa é a verdade, $n. Um dos sátiros deve estar com ele. Se conseguisse obtê-lo, você me deixaria tão perto de transpor as barras de minha prisão que eu iria às lágrimas.", t = "Bashal'Aran"},
    [957] = {ot = "Destrua o Selo Antigo de Pedra-da-lua na chama ancestral em Ameth'Aran, depois fale novamente com Astérion em Bashal'Aran.", st = "O selo que enforma minha prisão foi habilidosamente criado por um dos mais poderosos Altaneiros. Em Ameth'Aran, as ruínas ao sul que são exatamente iguais a estas, perdura ainda hoje uma chama ancestral, de cor azul. O selo pode ser destruído por ela.$b$bTenha cuidado quando estiver lá, $n...", t = "Bashal'Aran"},
    [958] = {ot = "Resgate 7 Relíquias dos Altaneiros para Trovejius Tecevento, em Auberdine.", st = "Tenho uma tarefa para você, $C.$b$bSabe onde ficam as ruínas de Ameth'Aran? Elas estão no lado leste da estrada principal, em direção ao sul. Já foram a casa de Altaneiros poderosos, agora são apenas um testemunho da destruição causada por seus malfeitos.$b$bAs Sentinelas me disseram que os espíritos dos Altaneiros ainda persistem por lá, e estão de posse de seus antigos implementos mágicos. Precisamos nos apropriar dessas relíquias para poder destruí-las.", t = "Ferramentas dos Altaneiros"},
    [959] = {ot = "O Operador de Grua Mafuá, em Vila Catraca, quer que você recupere a garrafa de Xerez de 99 Anos com Maluc Insano, que se refugiou na Caverna Ululante.", st = "Ops!$b$bDá para ver que tive um pequeno contratempo, né? O carregamento matinal da Angra do Butim era muito grande. Muito grande mesmo! Nunca vi tantas caixas no mesmo lugar. Comecei a descarregar, pegando um pouco mais de carga do que de costume, para dar um adianto no serviço, mas acabei pegando mais do que devia. Aí tudo começou a desmoronar.$b$bEu estava mais perdido que cego em tiroteio, mas vi aquele maldito do Maluc Insano fugindo com uma garrafa de xerez de 99 anos. Fui atrás dele até a Caverna Ululante, mas eu só entraria lá se tivesse pirado na batatinha.$b$bSe você tiver nervos de aço, pode ir atrás dele.", t = "Encrencas nas docas"},
    [962] = {ot = "A Boticária Zaqueia, no Penhasco do Trovão, quer que você colete 10 Ofídeas.", st = "A Real Sociedade de Boticários, que fica na grande Cidade Baixa, em Lordaeron, me mandou aqui para fazer um serviço muito específico, $n. Talvez você possa ajudar a mim e, consequentemente, à Dama Sombria em nossos esforços pelo progresso dos Renegados.$b$bNão faz muito tempo, comecei a estudar um raro espécime da flora chamado Ofídea. Acredito que, em grandes quantidades, essa planta pode ter grande potencial.$b$bInfelizmente a Ofídea só pode ser encontrada nos recônditos mais sombrios da Caverna Ululante, uma perigosa rede de cavernas que fica nos Sertões.", t = "Ofídeas"},
    [963] = {ot = "Liberte o espírito de Anaya Correalba e leve seu pingente para Cerellean Garralva em Auberdine.", st = "Após as batalhas da Nascente da Eternidade, ouvi que Ameth'Aran fora destruída e seu povo perecera, inclusive Anaya, meu grande amor.$b$bEu jamais pensei que, milhares de anos depois, as lembranças de Anaya ainda assombrariam meus sonhos. Vagando pela Costa Negra em estado de estupor, vi-me nas ruínas de Ameth'Aran... onde me deparei com o espírito assolado de minha amada.$b$bEla tem de ser libertada, mas me falta a coragem para fazê-lo. O espírito dela tem de ser destruído.", t = "Amor eterno"},
    [965] = {ot = "Encontre Balthule Umbrataque perto da Torre de Althalaxx, que fica na Costa Negra.", st = "Salve, jovem $r. Sou Elissa Brisastral e é meu dever proteger Auberdine contra o mal.$b$bPara tanto, mandei Balthule Umbrataque a nordeste para investigar ocorrências estranhas nos arredores da Torre de Althalaxx.$b$bEle já devia ter voltado. Fico preocupada de que ele possa ter sido vítima de um perigo inesperado na floresta. Ficaria muito grata se você o encontrasse e cuidasse para ele ficar bem.", t = "A Torre de Althalaxx"},
    [966] = {ot = "Colete 4 Pergaminhos Gastos para Balthule Umbrataque, perto da Torre de Althalaxx.", st = "Um grupo de bruxos se estabeleceu dentro e nos arredores da torre. Eu teria regressado antes a Auberdine para relatar o ocorrido a Elissa, mas fiquei preocupado de que acontecesse alguma coisa entanto eu estivesse fora.$b$bDinis suspeitava que um grupo como esse estivesse se reunindo na torre, mas não sabia a razão.$b$bAlguns pedaços de pergaminho carregados pelos bruxos chegaram até as minhas mãos, mas preciso de mais para completar o quebra-cabeça. Meu conselho: não entre na torre, porque os bruxos de lá são muito mais poderosos.", t = "A Torre de Althalaxx"},
    [967] = {ot = "Entregue a carta de Balthule a Dinis, o Purificador, na Floresta do Vale Gris.", st = "Meu mestre, Dinis, o Purificador, é um paladino que graciosamente nos ofereceu sua ajuda na defesa de nossas florestas contra as forças dos demônios e dos mortos-vivos. Ele me ensinou tudo o que sei sobre a Luz Sagrada e a arte da guerra.$b$bDinis precisa ser informado imediatamente sobre as operações da seita.$b$bVocê vai encontrá-lo bem ao sul daqui, no Entreposto de Maestra, que fica na Floresta do Vale Gris. Não demore, pois a ameaça da Linhagem das Trevas cresce a cada minuto.", t = "A Torre de Althalaxx"},
    [968] = {ot = "Leve o Livro: Os Poderes de Baixo para Gerrig Agarrosso na Caverna Esquecida, em Altaforja.", st = "Embora muito gasto e arranhado, o título do livro ainda está legível na capa:$B$BOs Poderes de Baixo$B$BO livro traz uma lista de nomes impronunciáveis com títulos agourentos, métodos de adoração e sacrifícios preferenciais... muitos dos quais envolvem seres vivos e humanoides.$B$BNa contracapa está escrito: \"Runas e Ruínas de Agarrosso, Caverna Esquecida, Altaforja. Proprietário: Gerrig Agarrosso\".$B$BSe Agarrosso vende livros como esse, talvez ele se interesse em comprar de volta.", t = "Os Poderes de Baixo"},
    [970] = {ot = "Colete uma Gema Anímica Faiscante e fale novamente com Dinis, o Purificador, no Entreposto de Maestra.", st = "A carta de Balthule é atroz. A Seita da Linhagem das Trevas é uma pedra no meu sapato e quero me livrar logo deles. Já enfrentei alguns exemplares dessa escória da Linhagem das Trevas a nordeste daqui, em Ordil'Aran. Um deles possui uma gema anímica que, acho eu, guarda os segredos do poder da seita.$b$bTraga a gema para mim que eu conseguirei decifrar os segredos que ela guarda.", t = "A Torre de Althalaxx"},
    [971] = {ot = "Leve o Manuscrito de Lorgalis para Gerrig Agarrosso na Caverna Esquecida, em Altaforja.", st = "Talvez você já saiba que eu coleciono lendas. Lendas antigas. Lendas poderosas. Lendas que abrem portas e lendas que podem acordar Aqueles Que Dormem.$B$BCorrem rumores sobre uma lenda, o Manuscrito de Lorgalis, que estaria no fundo das Profundezas Negras no Vale Gris. Lá é o antigo lar de elfos que há muito já se foram. Elfos que eram detentores de grande conhecimento antes que sua cidade virasse ruínas.$B$BProcure o manuscrito nas Profundezas Negras. Faça isso por mim e eu nunca vou me esquecer. Nem mesmo depois... do fim dos dias.", t = "Conhecimento nas Profundezas"},
    [973] = {ot = "Leve o Tomo de Ilkrud Magthrull para Dinis, o Purificador, no Entreposto de Maestra.", st = "Ilkrud Magthrull. Sim, já ouvi falar dele, é um bruxo orc poderoso que reside no Santuário Cicatriz de Fogo, um lugar profundamente maligno na parte sudoeste do Vale Gris.$b$bEle pouco tinha feito além de incomodar até agora, por isso não me ocupei dele antes, mas parece que a hora chegou.", t = "A Torre de Althalaxx"},
    [982] = {ot = "Recupere o Baú do Aurora de Prata e o Baú do Véu das Brumas para Gorbold Manácero em Auberdine. Os dois itens podem ser encontrados nos destroços dos navios a norte da aldeia.", st = "No litoral da Costa Negra, a norte de onde estamos, há dois navios naufragados: o Aurora Prateada e o Véu das Brumas. Tempos atrás, os dois foram atacados por esses murlocs lazarentos quando cruzavam o vasto mar em direção a Auberdine. Agora estão no fundo do mar, como troféus desses demônios.$B$BOs dois capitães afundaram junto às embarcações, e seus diários de bordo e outros pertences ainda estão lá nos destroços, guardados em baús. Quero que tu traga isso para nós. Significaria muito pros tripulante que sobreviveram.", t = "Nas profundezas do mar"},
    [983] = {ot = "Colete 6 Patas de Rastejante e coloque-as na Caixazorra 827.", st = "Ei! Preciso de ajuda com a minha última invenção, a caixazorra. Com ela, você pode falar com pessoas que estão muito longe.$B$BTalvez você já tenha visto, é uma caixa com alavancas. O negócio é que elas precisam de manutenção constante.$B$BCada uma tem um problema diferente, mas eu tomei uma decisão muito inteligente. Coloquei cada uma perto de criaturas que têm as peças necessárias para consertar aquela máquina específica. No momento, é a Caixazorra 827 que tá quebrada. Ela está ao sul de Auberdine, pertinho daqui. Preciso conseguir 6 patas de rastejante para consertar. Pago bem...", t = "Caixazorra 827"},
    [984] = {ot = "Encontre um acampamento de pelursos corrompidos na Costa Negra e fale novamente com Terenthis em Auberdine.", st = "Alguns dos meus irmãos foram salvos de um pelurso corrompido em Teldrassil e jurei dar um fim às atrocidades antes que mais algum dos nossos se ferisse... ou algo pior.$B$BJá percebi alguns indícios de corrupção na Costa Negra, mas ainda não vi sinal de epidemia. Acho que seria lógico continuar a investigação com os pelursos. Gostaria que você encontrasse um acampamento de pelursos e falasse novamente comigo se visse algum sinal de corrupção.", t = "Uma grande ameaça?"},
    [985] = {ot = "Mate 8 Desbravadores Bosquenero e 5 Vozes-do-vento, depois fale novamente com Terenthis, em Auberdine.", st = "Você já comprovou suas habilidades ao fazer o reconhecimento do nosso inimigo, $n. Agora, será que é capaz também de lutar contra ele?$B$BNão são todos os aventureiros que preferem o combate direto em vez da furtividade e evasão.$B$BSe achar que está à altura da tarefa, no momento, a maior ameaça ao nosso povo é acampamento de pelursos ao sul de Auberdine. Lá também há alguns membros da tribo Bosquenero. Mate 8 desbravadores e 5 vozes-do-vento e depois venha falar comigo.", t = "Uma grande ameaça"},
    [986] = {ot = "Encontre 5 Pelagens de Espreitaluna Finas e leve-as para Terenthis, em Auberdine.", st = "$n, suas habilidades já me ajudaram em minha missão. Será que eu poderia contar com você de novo para ajudar Garratroz e o mestre dele, Volcor? Além disso, posso criar um manto mágico que lhe permitirá passar despercebido pelas criaturas da Costa Negra enquanto procura por ele.$B$BPara criar o manto, precisarei de cinco pelagens finas de um espreitaluna macho ou matriarca para ter material suficiente. Os gatos podem ser encontrados perto do Rio Crenado, ao sul, ou ainda mais ao sul, perto de Vale Gris.", t = "Um mestre perdido"},
    [990] = {ot = "Encontre Raene Correlobos, no Vale Gris.", st = "$n, minha senhora, Raene Correlobos, espera por você na cidade de Astranaar, que fica no Vale Gris. Com a sua ajuda, talvez a gente consiga pelo menos minimizar a corrupção que tomou conta de lá.$B$BSiga para o sul a partir daqui e fique perto da estrada — você vai chegar lá sem grandes problemas se seguir as instruções.", t = "Viagem ao Vale Gris"},
    [991] = {ot = "Procure Teronis no Vale Gris.", st = "$n, um amigo meu de longa data também está ajudando as Sentinelas aqui no Vale Gris, mas ele ainda não voltou.$B$BEle tinha pistas para encontrar um item que pensava poder retardar os ataques de pelurso ao nosso povo — um bastão criado por um mago maligno, agora morto.$B$BAntes de ir embora, ele disse estar à procura de uma gema para o bastão.$B$BEle comentou que a gema provavelmente estava escondida no santuário do Lago Falathim, na base da montanha a oeste. A gema estava sendo mantida lá antes do local ser invadido.$B$BEncontre meu amigo, $n, por favor.", t = "O expurgo de Raene"},
    [993] = {ot = "Encontre Volcor na Costa Negra e entregue a ele o Manto Encantado de Espreitaluna.", st = "O manto está terminado, $n. Chegou a hora a hora de encontrar Volcor, e só posso torcer para que ainda haja tempo.$B$BUma vez invocada, a magia do manto não vai durar muito, talvez uns cinco minutos. Você vai ter que saber o melhor momento de usá-la. Sugiro esperar até encontrar Garratroz.$B$BSe ele estava falando a verdade, você encontrará o mestre dele em uma caverna ao sul daqui. Garratroz estará perto da estrada esperando pelo seu sinal. Quando o avistar, acene para ele e ele irá indicar o caminho que levará ao mestre dele.", t = "Um mestre perdido"},
    [995] = {ot = "Fuja da caverna do Pelurso e encontre Terenthis em Auberdine.", st = "Muito bem... se você tem certeza, vamos dar um jeito de sair daqui. Seguimos quando você estiver pront$go:a;.$B$BNão se esqueça, depois de escapar, encontre Terenthis em Auberdine. Vou pra lá por conta própria, porque devo chegar mais rápido que você.", t = "Fuga furtiva"},
    [997] = {ot = "Leve o pacote de Terra Rara para Denalan no Lago Al'Ameth.", st = "Está indo para o sul? Para o Lago Al'Ameth? Então tenho um favor para pedir...$B$BMeu colega Denalan tem um acampamento perto da margem leste do lago, onde estuda e realiza experimentos com a flora de Teldrassil. Ele solicitou um pacote de terras raras de Darnassus que só chegou a Dolanaar recentemente.$B$BPode levar o pacote até ele?", t = "A terra de Denalan"},
    [1001] = {ot = "Recolha 3 Olhos de Mangual dos Manguais da Costa Negra no fundo do mar, perto da Caixazorra 411.", st = "Lá do fundo da máquina, sai uma vozinha esganiçada.$B$B\"Aqui fala o Xafetim! A próxima caixazorra está ao norte de Auberdine, na praia.$B$BOlha só, o número dessa caixazorra é 411 e vai precisar de três olhos de mangual pra manutenção. Esses bichos vivem no litoral! Os manguais da Costa Negra... *Hic*... Perdão...$B$BAssim que você botar o negócio na caixazorra, ela vai cuspir a recompensa pra fora, que nem da outra vez. *Hic*... O que foi? Não, eu tô ferpeito!\"", t = "Caixazorra 411"},
    [1002] = {ot = "Recolha 6 Presas de Espreitaluna e deposite-as na Caixazorra 323.", st = "A voz do Xafetim sai de dentro da caixa, abafada por um barulhão de estática.$B$B\"O número da próxima caixazorra é 323. Ela tá ao norte de Auberdine, só que... cadê a breja? Quê? Ah, fica no meio da estrada, pertim da ponte, não tem como deixar de ver.\"$B$BO Xafetim balbucia algumas palavras e logo depois toma um trago de alguma coisa.$B$B\"Ezze aqui picisa de presa de espreitaluna... uãs seis.\"", t = "Caixazorra 323"},
    [1003] = {ot = "Recolha 4 Escalpos Grisalhos dos Ursocardos Grisalhos ao sul de Auberdine e deposite-os na Caixazorra 525.", st = "Por cima do borbulhar e do gargolejar da máquina, ouve-se a voz trêmula do Xafetim.$B$B\"A prózima fica na estrada, beeem ao zul. Num tem erro... fica à beira da estrada... perto duma cerca. Acho que escondi a caixa num matagalho... matagal. Hehehe... isso memo, a caixazorra 525 picisa de escalpos grisalhos, escalpo de ursocardo grisalho. Rapaz, que negoço gostoso. Grisaldo... hehehe...\"$B$BAntes de cortar a transmissão ainda dá para ouvir mais umas goladas. E eis que, de repente, a máquina volta à vida.$B$B\"Traz quatro!\"", t = "Caixazorra 525"},
    [1007] = {ot = "Leve a Estatueta Ancestral para Talen, no acampamento perto da Praia de Zoram.", st = "Vou dar uma tarefa para você, $n.$B$BEu estava no meu barquinho, deslizando pelas águas sobre as ruínas submersas de Zoram, quando algumas nagas me atacaram. Elas surgiram da água e partiram para cima de mim com aquelas garras imensas! Eu consegui fugir com alguns suprimentos e montei esse arremedo de acampamento.$B$BMas enquanto corria praia afora... acabei perdendo meu maior tesouro.$B$BPor favor, $n, você iria ao local onde fui emboscado atrás de uma estatueta ancestral? Foi por ela que enfrentei os perigos todos da Praia de Zoram.", t = "A estatueta ancestral"},
    [1008] = {ot = "Entregue 20 Cabeças de Iracauda para Shindrell Fogofugaz em Astranaar.", st = "O mal anda à espreita no litoral a noroeste, na Praia de Zoram.$B$BLá jaz a cidade de Zoram, destruída durante a Cisão e coberta pelas águas. Os elfos noturnos a consideram desaparecida há eras. Desaparecida e quase esquecida.$B$BAgora as nagas voltaram, e ainda não sabemos o porquê. Mas o motivo pouco importa: temos que matar essas diabas e mandá-las de volta para as profundezas, de onde nunca deveriam ter saído!$B$BVolte com a missão cumprida.", t = "Praia de Zoram"},
    [1009] = {ot = "Leve o Anel de Zoram para Talen, perto da Praia de Zoram.", st = "Receio que os segredos das estatuetas ancestrais continuem escondidos para sempre, a não ser que você encontre a chave de uma antiga fechadura.$B$BA chave na verdade é um anel, o Anel de Zoram. Ele pertencia aos líderes da cidade antes das ondas da Cisão tomarem conta de tudo.$B$BO anel ficou perdido por muitos anos, mas há pouco tempo as nagas o encontraram.$B$BA líder delas, Ruuzel, habita a ilha na ponta norte de Zoram. Por favor, $n, consiga esse anel para mim!", t = "Ruuzel"},
    [1010] = {ot = "Leve 5 Cabelos-de-bathran para Orendil Folharga no Vale Gris.", st = "Tinha uma planta que crescia nas ruínas do Refúgio de Bathran, ao norte. O nome da planta era cabelo-de-bathran, dizem que ela curava os males do espírito.$B$BTem uma criança doente no vilarejo e eu acredito que não seja apenas um mal do corpo. Você iria ao Refúgio de Bathran atrás de um pouco de cabelo-de-bathran? Vou precisar da planta para tratar dessa criança.$B$BO Refúgio de Bathran fica ao norte do Entreposto de Maestra, que é logo a sul da fronteira da Costa Negra.", t = "Cabelo-de-bathran"},
    [1011] = {ot = "Leve uma Garrafa de Moléstia para Kainet Brisacalma em Cantilenda.", st = "A ala de mortos-vivos da Horda, os Renegados, se infiltrou no Vale Gris e anda à espreita pelas nossas ruínas e cemitérios. Suspeitamos que o objetivo deles seja espalhar doenças pelas terras noctiélficas. Precisamos confirmar se é isso mesmo!$B$BOs Renegados montaram acampamento ao sul daqui, perto do Retiro de Dor'Danil, onde vêm engarrafando suas poções e moléstias. Entre no acampamento à força e roube um frasco. Volte com uma garrafa. Eu vou testá-la para descobrir para que servem.", t = "Moléstias renegadas"},
    [1013] = {ot = "Leve o Livro de Ur para o Guardião Bel'dugur no Boticarium da Cidade Baixa.", st = "$n, tem um livro na Bastilha da Presa Negra, o Livro de Ur, que ficaria muito bem na minha coleção. Ur foi um grande mago de Dalaran, antes da chegada do Flagelo. Seus estudos sobre outros mundos são de grande valia para... certos Renegados.$B$BAdentre a Bastilha da Presa Negra e encontre o livro. Traga-o para mim e eu farei com que a Dama Sombria saiba do serviço que você nos prestou...", t = "O Livro de Ur"},
    [1014] = {ot = "Mate Arugal e leve sua cabeça para Dalar Tessalba no Sepulcro.", st = "Arugal continua na Bastilha da Presa Negra. Não temos como transformar Pinhaprata em ponto estratégico para a Dama Sombria enquanto ele estiver vivo.$b$bEu mesmo dissiparei as magias dele, $n. Mas conto com você para fazer com que Arugal receba a morte que tanto merece.$b$bVá para a Bastilha da Presa Negra e ponha fim nos feitiços de Arugal de uma vez por todas. Traga-me a cabeça daquele feiticeiro degenerado!", t = "Arugal tem que morrer"},
    [1016] = {ot = "Recolha 5 Braçadeiras Elementais Intactas e use o Pergaminho Divinatório nelas. Depois, leve o Pergaminho Vaticinado para a Sentinela Velene Golpestela no Refúgio Brisaprata.", st = "Tome este pergaminho divinatório, ele vai identificar quem foi o criador dos elementais. Mas você vai precisar de alguma coisa deles para usar como reagente e canalizar a magia do pergaminho: as braçadeiras devem servir.$B$BAlgumas braçadeiras intactas já vão bastar. As mais desgastadas não servirão aos nossos propósitos, mas talvez você consiga vendê-las para os comerciantes por aí. Depois que estiver com as braçadeiras intactas, é só usar o pergaminho. Volte com os resultados e nós daremos prosseguimento à missão.", t = "Braçadeiras Elementais"},
    [1017] = {ot = "Mate Sarilus Malnato e leve a cabeça dele para a Sentinela Velene Golpestela no Refúgio Brisaprata.", st = "Só tem um mago morto-vivo em toda a região dos Sertões capaz de perverter tantos elementais d'água assim. E só ele é tolo o bastante para fazer isso. Sarilus Malnato deve estar encarapitado no alto do Morro de Brumedo, rindo da minha cara.$B$B$n, você tem que adentrar o território inimigo e destruir esse infiel. Eu já estou farta dessas idiotices, temos que mostrar a ele o que acontece com quem vem importunar as Sentinelas.$B$BDestrua-o e traga-me sua cabeça. Mas tome cuidado, a Horda estará de olho em você.", t = "O mago evocador"},
    [1020] = {ot = "Entregue a Cura de Orendil a Pelturas Lunalva em Astranaar.", st = "$n, eu preparei um medicamento que pode curar a criança doente. Leve-o para Astranaar e entregue-o ao pai da menina, Pelturas Lunalva.$B$BPara chegar lá, siga pela estrada em direção ao sul e, em seguida, ao leste.", t = "Cura de Orendil"},
    [1021] = {ot = "Encontre Anilia em Xavian.", st = "Escute aqui, eu não sei quem é você, mas preciso da sua ajuda. Minhas irmãs foram pegar o Ramo de Cenarius de volta dos sátiros. Elas disseram que voltariam rápido, mas já se passaram dois dias inteiros!$B$B$n, você tem que encontrá-las! Elas estavam procurando as ruínas de um templo noctiélfico em Xavian, a nordeste daqui. Eu não sei mais o que pensar. Procure Anilia, ela era a responsável pela expedição.", t = "Malditos sátiros! Dríades em perigo!"},
    [1022] = {ot = "Vá para o Vale Uivante estudar o Tomo de Mel'Thandris, depois fale novamente com a Sentinela Melyria Algissombra no Altar de Aessina.", st = "Por mais que tenhamos empregado nossos recursos e energia para expulsar os demônios da Selva Maleva, ao norte, não fomos muito bem-sucedidos. Pelo menos, mantivemos os demônios afastados do Vale Gris.$b$bAo norte, perto da fronteira com a Selva Maleva, o santuário arruinado de Mel'Thandris foi tomado por misteriosos lobisomens. Por causa dos uivos incessantes, a região acabou ficando conhecida como Vale Uivante. Talvez o Tomo de Mel'Thandris, que jaz no santuário, ajude a explicar o surgimento dos lobisomens.", t = "Vale Uivante"},
    [1023] = {ot = "Encontre a Gema Faiscante e fale novamente com Raene Correlobos em Astranaar, em posse do Diário de Teronis.", st = "Ao revirar os pertences de Teronis, você encontra um diário ainda em boas condições.$B$BVocê pega o diário e deixa o corpo de Teronis como estava.$B$BAgora só falta encontrar a gema que Teronis vinha procurando. Segundo Raene, ela estava por ali. Pode ser que esteja com os murlocs...", t = "O expurgo de Raene"},
    [1024] = {ot = "Encontre Shael'dryn no poço lunar a nordeste.", st = "Você terá que fazer a pesquisa por conta própria, mas pelas anotações de Teronis, eu diria que o próximo passo é encontrar as outras partes do bastão de Dartol. Eu começaria pelo poço lunar a leste do Lago Íris. Quanto estiver pront$Go:a;, pegue a estrada e dobre para o norte ao passar por uns banquinhos à sua esquerda.$B$BLá, uma dríade chamada Shael'dryn poderá orientá-$Glo:la; melhor. Vá atrás dela.$B$BE guarde bem a gema. Shael'dryn vai precisar dela para ajudá-$Glo:la; a reconstruir o bastão.", t = "O expurgo de Raene"},
    [1025] = {ot = "Mate 1 Vigia do Covil, 2 Ursinos, 10 Totêmicos e 12 Guerreiros da tribo Torpeflora, depois fale novamente com Raene Correlobos em Astranaar.", st = "Antes de partir para o poço lunar, eu tenho outra tarefa para lhe dar que ajudará o povo do Vale Gris, caso você queira colocar suas habilidades à prova.$B$BAo longo da estrada, rumo ao leste, antes do Rio Felfarren, pelursos vêm atacando os viajantes. Suas mentes torturadas alimentando-se do medo e seu apetite saciando-se com sangue de inocentes.$B$BAjude as Sentinelas a proteger a região, tenha tanta piedade dos monstros quanto eles têm nós.$B$BAcredito que o assentamento deles fique ao sul da estrada... tome cuidado.", t = "Uma defesa agressiva"},
    [1026] = {ot = "Encontre a Chave de Madeira e uma parte do Bastão de Dartol antes de falar novamente com Shael'dryn no poço lunar.", st = "Quisera eu receber notícias melhores.$B$BRaene está certa. Eu sei da criação de Dartol e conheço os arvorosos daqui... ou pelo menos conhecia. Todos foram corrompidos, suas naturezas desvirtuadas.$B$BPara encontrar a outra parte do bastão, você vai precisar de uma chave para abrir o baú onde a peça está guardada.$B$BA chave de madeira está com um dos arvorosos, a nordeste daqui. Após pegar a chave, procure uma pequena clareira, a oeste da estrada, perto da fronteira com a Selva Maleva... O baú deve estar escondido por ali.", t = "O expurgo de Raene"},
    [1027] = {ot = "Encontre a última peça do Bastão de Dartol e fale novamente com Shael'dryn no poço lunar.", st = "A última parte do bastão foi confiada aos druidas de Dor'Danil por razões de segurança. Não faço ideia de onde a esconderam. Lamento não poder ajudar mais.$B$BSó posso lhe dizer para seguir a estrada que leva aos Sertões. Os druidas se abrigavam ao leste dessa estrada, mas eles tampouco serão de grande ajuda: foram todos mortos não faz muito tempo... não gosto nem de pensar no assunto.$B$BDepois que tiver encontrado a peça, traga-a para mim e eu $Go:a; ajudarei a montar o bastão.", t = "O expurgo de Raene"},
    [1028] = {ot = "Encontre o santuário oculto e encante o Bastão de Dartol.", st = "Aqui está o bastão inteirinho, $n. Reconstruí-lo foi fácil... o difícil vai ser encontrar o altar que tem o poder de encantar a peça.$B$BCom um pouquinho de empenho não vai ser tão difícil assim para você, que já chegou tão longe.$B$BSiga rumo ao sudeste – as estradas são poucas, então tenha cuidado – e fique sempre voltado para o norte. O altar se esconde entre as montanhas que margeiam a clareira.$B$BChegando lá, bote o bastão no altar... o resto vai se dar num passe de mágica. Hehe.", t = "O expurgo de Raene"},
    [1029] = {ot = "Fale novamente com Raene Correlobos em Astranaar.", st = "Eu sugiro que você encontre Raene e diga a ela que o bastão está pronto. Ela saberá dizer qual é o próximo passo a dar.$B$BBoa sorte, $n.", t = "O expurgo de Raene"},
    [1030] = {ot = "Encontre um pelurso não corrompido e use o poder do Bastão de Transformação de Dartol para falar com ele.", st = "Infelizmente, não sei muito bem o que ele planejou.$B$BSe o que ele disse sobre o poder do bastão for verdade, você poderá assumir outra forma. Que forma é essa, eu não sei.$B$BTalvez o objetivo dele fosse se aproximar dos pelursos corrompidos, mas mesmo os não corrompidos poderiam matá-lo caso não fosse cuidadoso. Transformado pelo poder do bastão, Dartol teria que falar com algum pelurso livre dos efeitos do limo vil.$B$BEu começaria a busca a sudeste do Lago Mistral.", t = "O expurgo de Raene"},
    [1031] = {ot = "Mate Geltharis e leve o Ramo de Cenarius para Iliana no Altar de Aessina.", st = "Anilia põe a mão sobre os seus ombros e puxa você para perto. Ofegante, ela aponta para o arco ao norte, antes de fechar os olhos e exalar o último suspiro. \"Ele pegou o ramo... Geltharis...\" Você sente em sua alma que o último pedido de Anilia é devolver o Ramo de Cenarius às dríades.", t = "O ramo de Cenarius"},
    [1032] = {ot = "Leve 16 Chifres de Sátiro para Iliana no Altar de Aessina.", st = "Nem acredito que Anilia se foi... Nós sempre brincávamos nas florestas. Eu estou quase... triste.$B$BMas eu sei de uma coisa que vai me fazer sentir melhor. Por favor, mate os sátiros que tiraram Anilia de mim! Traga os chifres desses facínoras como prova de seu feito, e lhe serei eternamente grata.", t = "Temporada de caça aos sátiros"},
    [1033] = {ot = "Leve a Lágrima de Eluna para Pelturas em Astranaar.", st = "Eu tinha esperanças de que a cura de Orendil fosse salvar Relira, mas ela apenas reduziu o avanço do mal. Temos que encontrar um remédio mais poderoso! Mas, graças a Eluna, Orendil mencionou outros remédios, caso o primeiro não funcionasse.$B$BA lágrima de Eluna é um cristal que só existe em um lugar: na ilha do Lago Íris, a leste de Astranaar. Orendil disse que esse cristal vai livrá-la da corrupção... Por favor, $n, traga-me a lágrima de Eluna e reze para que ela dê um fim ao mal de minha filha!", t = "Lágrima de Eluna"},
    [1034] = {ot = "Leve 5 Punhados de Poeira Estelar para Pelturas em Astranaar.", st = "A Lágrima de Eluna levou embora parte da doença. Os pesadelos dela se abrandaram e eu agradeço à deusa pela bênção. Mas... ela continua queimando de febre.$B$BOrendil falou de um pó das Ruínas de Poeira Estelar. Pode ser que ele ajude a aliviar a febre de Relira. Vá buscar um pouquinho e volte aqui.$B$BAs Ruínas de Poeira Estelar ficam ao sul, $n. Que Eluna abençoe sua jornada.", t = "Ruínas de Poeira Estelar"},
    [1035] = {ot = "Recolha uma Pedra-da-lua Caída do Oráculo Umbrárvore, depois leve-a para Pelturas em Astranaar.", st = "A febre de Relira passou, mas ela continua muito fraca. Acho que só a passagem do tempo não vai bastar para lhe devolver as forças perdidas. Ela vai precisar de uma pedra-da-lua.$B$BNós costumávamos buscar essas pedras no Lago Céu Caído, a sudeste... Isso até chegarem os Umbrárvores.$B$BO líder deles, o Oráculo Umbrárvore, juntou todas as pedras e passou a guardá-las como um tesouro. Você vai que ter tomar uma pedra-da-lua dele.$B$BPara fazer isso, receio que só matando-o.", t = "Lago Céu Caído"},
    [1037] = {ot = "Fale com Thyn'tel Tecelâmina no Terraço dos Guerreiros, em Darnassus.", st = "Velinde Stelacanto foi minha predecessora na Floresta do Vale Gris. A princípio, parecia que ela tinha a Selva Maleva sob controle, mas de pouco em pouco foi vacilando. Um dia, sumiu sem mais nem menos.$b$bMandaram-me para cá para substituí-la. Receio não saber mais nada sobre a sacerdotisa. De repente Thyn'tel Tecelâmina, uma das comandantes das Sentinelas, tenha detalhes que eu desconheço sobre o sumiço.$b$bEstou certa de que ela compreenderá a importância de tais informações.", t = "Velinde Stelacanto"},
    [1038] = {ot = "Vasculhe o baú de Velinde atrás do seu diário, depois leve-o junto com a chave para Thyn'tel Tecelâmina em Darnassus.", st = "Foi isso que você viu no Tomo de Mel'Thandris? Imagino que não vá ter nenhum problema se você mexer nas coisas dela. Esta chave abre o baú onde guardamos as coisas da sacerdotisa, no alojamento das Sentinelas. Ela registrava seus deveres em um diário. Se for para descobrir alguma coisa, vai ser nele.$b$bÉ melhor você ficar avisad$Go:a;: as Sentinelas acreditam que ela tinha seus motivos para partir e que pode voltar a qualquer momento. A sacerdotisa fez muito por nós e conquistou nossa confiança.", t = "Os efeitos de Velinde"},
    [1039] = {ot = "Fale com o Mestre Portuário Caruncho na Vila Catraca.", st = "Vila Catraca é o único porto em toda a região dos Sertões. O provável é que Velinde tenha encontrado um navio mercante em Vila Catraca para levá-la à Angra Aguanegra. Não tivemos muito contato com os goblins que cuidam do porto, mas o mestre da doca deve ter mais informações sobre as idas e vindas dos passageiros.$b$bSiga a estrada a sudeste passando pelo Vale Gris e você chegará nos Sertões. Cuidado onde pisa, $n, pois a área é patrulhada pela Horda. Você estará em segurança quando chegar ao porto.", t = "O porto dos Sertões"},
    [1045] = {ot = "Mate 4 Guardas Dente Sangrento e leve o Crânio de Ran Dente Sangrento para Krolg no Lago Mistral.", st = "Os elfos noturnos são tão antigos quanto o próprio tempo, mas são tão arrogantes que só fazem destruir o próprio mundo. Isso está saindo de controle e começando a destruir também as nossas vidas...$B$BMuito mal ocorre por culpa dos elfos, mas isso não nos isenta de responsabilidade pelas nossas próprias ações. Para além da corrupção, nós mesmos somos capazes de causar grande mal.$B$BRan Dente Sangrento é um desses males. Ganancioso, avarento... a corrupção só o deixa mais forte. Tenho ódio profundo pelos elfos, mas não desejo mal aos filhos deles, e é por isso que precisamos policiar os nossos.", t = "O expurgo de Raene"},
    [1046] = {ot = "Leve o Crânio de Ran Dente Sangrento e o Bastão de Transformação de Dartol para Raene Correlobos em Astranaar.", st = "Volte à sua tribo e conte a todos sobre a sua vitória aqui.$B$BMostre a todos o seu troféu e se regale em sua glória...", t = "O expurgo de Raene"},
    [1054] = {ot = "Leve o Crânio de Dal Sangarra para Raene Correlobos em Astranaar.", st = "Os pelursos Pelocardo ocupam a área logo ao norte de Astranaar. Meus batedores relataram que aquela população aumentou muito nos últimos meses. Se eles se expandirem mais, é possível que tomem coragem para fazer um ataque direto a Astranaar.$B$BMate tantos quanto puder, mas me traga o crânio do chefe deles para comprovar que eles foram contidos... por ora.$B$BEu ficarei aqui em Astranaar aguardando notícias. Que Eluna esteja com você.", t = "Contendo a ameaça"},
    [1055] = {ot = "Fale novamente com Shael'dryn no poço lunar.", st = "O bastão, agora reconstruído, está em suas mãos. Shael'dryn vai querer saber tudo sobre o seu sucesso.", t = "O expurgo de Raene"},
    [1056] = {ot = "Vá até o Guardião Albagorm no Morro das Torres de Pedra.", st = "Os espíritos da floresta me revelam que você tem coragem e disposição para viajar.$b$bAo sul, não muito longe do Lago Mistral, há um túnel chamado Garracava. Atravessando esse túnel você chegará a uma área conhecida como Rochedo Cortavento, na Cordilheira das Torres de Pedra. Chegando lá, rume para o sudoeste, passando pelo Lago do Rochedo, e depois para o norte, subindo a montanha íngreme, até chegar ao Morro das Torres de Pedra.$b$bO Guardião Albagorm estará esperando por você lá. Atenda ao pedido dele, $r.$b$bA jornada será perigosa.", t = "A jornada para o Morro das Torres de Pedra"},
    [1057] = {ot = "O Guardião Albagorm, no Morro das Torres de Pedra, quer que você mate 6 Harpias Furissangue, 6 Emboscadoras Furissangue, 6 Matadoras Furissangue e 6 Plumerrantes Furissangue.", st = "Sendo eu um protetor dos espíritos da floresta, você pode certamente imaginar por que estou tão alarmado.$b$bVocê viajou por estas montanhas para alcançar este pico. Sem dúvida, você já viu a farsa que aflige a terra. A cobiça nos levou à destruição destas montanhas sagradas.$b$bO Vale Carbonizado ao sul foi incendiado pelo ganancioso exército mecanizado de industrialistas. Pior ainda, as furissangues que se apossaram destas terras nos negam passagem para que comecemos a recuperação.$b$bExpulse as malditas harpias, $n!", t = "Reivindicando o Vale Carbonizado"},
    [1058] = {ot = "O Mandingueiro Jin'Zil, em Malaka'jin, quer 5 porções de Seiva das Torres de Pedra, 5 Bigodes de Felino do Crepúsculo, 30 Olhos de Corcel e uma Escama de Dragão Encantado.", st = "Tão excitado estou!$b$bTrês pequenas jaulas para três pequenos elfos! Mas o que devemos fazer com nosso adoráveis amigos abraçadores de árvores? Bem, vamos dar a eles uma amostra de... como se chama isso mesmo... magia florestal!$b$bPreciso de uma boa quantidade de seiva das Torres de Pedra. Daqueles gatos horríveis, traga-me alguns bigodes de felinos do crepúsculo. Isto pede também por muitos olhos de corcel, claro. Quanto mais, melhor. Ah, e, antes que esqueçamos, uma preciosa escama de um dragão encantado.$b$bCorra para o Morro das Torres de Pedra, $n, para que eu possa preparar um pouco de magia da floresta!", t = "A magia florestal de Jin'Zil"},
    [1060] = {ot = "Entregue a carta de Darsok a Jin'Zil em sua caverna em Malaka'jin, nas Torres de Pedra.", st = "Você me ajudou tanto, $n. Você é tipo um pé de coelho da sorte, e eu queria te mostrar uma coisa.$B$BAs harpias não são aqui dos Sertões. Elas vêm de um lugar chamado Torres de Pedra, que ficam lá longe, a noroeste daqui. Embora o lugar talvez seja um pouco perigoso para você, preciso que essa carta seja entregue a um velho amigo que mora por lá, um mandingueiro chamado Jin'Zil.$B$BEle vai ficar feliz em saber que Serena Plumassangue está morta, e algo que diz que você vai achar Torres de Pedra um lugar interessante.", t = "Uma carta para Jin'Zil"},
    [1061] = {ot = "Fale com Seereth Quebra-pedra na Cordilheira das Torres de Pedra.", st = "Os espíritos da Cordilheira das Torres de Pedra estão enraivecidos, pois os goblins e seus servos estão pilhando e queimando a terra. Então a terra pediu ajuda, e aqueles que sabem ouvir... escutaram.$B$BSeereth Quebra-pedra, uma promissora xamã da Horda, foi enviada às Torres de Pedra. Ela relatou que os goblins estão produzindo desmatamentos em massa, e pediu ajuda.$B$BEncontre Seereth nas Torres de Pedra. Você precisa seguir a estrada a oeste da Encruzilhada, nos Sertões. Ela está acampada perto do Vale Matagrande.", t = "Os espíritos das Torres de Pedra"},
    [1062] = {ot = "Mate 15 Madeireiros da Empreendimentos S.A. e, então, fale novamente com Seereth Quebra-pedra na fronteira entre as Torres de Pedra e os Sertões.", st = "A empreitada goblínica Empreendimentos S.A. se mudou para a Cordilheira das Torres de Pedra e já chegou derrubando árvores e fazendo queimadas extensivas. Os espíritos deste lugar estão cegos de dor e raiva. Precisamos parar a Empreendimentos S.A.!$B$BVá para o noroeste passando pelo Vale Matagrande e você chegará ao Rochedo Cortavento. É lá que os goblins e seus servos estão trabalhando. Mostre a eles que a Horda não permite a exploração das Torres de Pedra. Use a língua que eles mais entendem...$B$BA violência.", t = "Invasores goblins"},
    [1063] = {ot = "Fale com Magatha no Penhasco do Trovão.", st = "Para aplacar os espíritos das Torres de Pedra, precisamos consultar os anciãos taurens.$B$BNão conheço muitos líderes pelo nome, mas conheço uma: Magatha. Ouvi dizer que ela é muito velha, e muito sábia. Se tem alguém que pode liderar a ajuda espiritual taurena, é ela.$B$BMagatha mora na capital taurena de Penhasco do Trovão, no Platô dos Anciãos — o penhasco mais ao nordeste da cidade. Fale com Magatha e conte a ela sobre os perigos que assolam a Cordilheira das Torres de Pedra.", t = "A Bruxa Anciã"},
    [1064] = {ot = "Fale com a Boticária Zaqueia nos Poços das Visões, que ficam no Penhasco do Trovão.", st = "Os taurens têm um vínculo forte com a terra, e lamento saber das agruras das Torres de Pedra. Contudo, sinto informar que, para curar a terra, primeiro precisamos erradicar a doença que a permeia.$B$BAssim sendo, não é uma sorte que os Renegados sejam nossos aliados? Eles entendem muito de doenças. Acredito que eles poderão nos ajudar, fortalecendo, assim, os laços com o nosso povo.$B$BFale com a Boticária Zaqueia, uma estudiosa que também é emissária dos Renegados. Você a encontra nos Poços das Visões, abaixo do Platô dos Espíritos.", t = "Ajuda Renegada"},
    [1065] = {ot = "Leve o Bilhete de Zaqueia para o Boticário Lindolfo na Serraria Tarren.", st = "Para livrar as Torres de Pedra da Empreendimentos S.A., precisamos tomar medidas extremas. O que não significa derramamento de sangue.$B$BUm colega meu pode ter o que precisamos. Ele se chama Lindolfo e mora na cidade de Serraria Tarren, no Contraforte de Eira dos Montes, na longínqua terra de Lordaeron.$B$BPara ir para Eira dos Montes, pegue o zepelim até a nossa capital, a Cidade Baixa. Depois, vá para o norte rumo às Clareiras de Tirisfal, depois sudoeste até Pinhaprata e siga para o sul, chegando em Eira dos Montes.$B$BEncontre Lindolfo e entregue a ele este bilhete que explica o que nós precisamos.", t = "A jornada para Serraria Tarren"},
    [1066] = {ot = "Leve 5 Ampolas de Sangue Inocente para o Boticário Lindolfo na Serraria Tarren.", st = "Criarei uma toxina para minar a violência da Empreendimentos S.A., deixando-os fracos e dóceis. Isso deve resolver o problema da Horda nas Torres de Pedra, sim?$B$BMas para criar a toxina, eu preciso do sangue de inocentes, um ingrediente muito difícil de se obter.$B$BPara nossa sorte, essa área tem a Camarilha, um grupo de bandoleiros humanos que trabalham com magos das sombras... e esses magos coletam sangue inocente para satisfazer seus próprios desígnios nada agradáveis.$B$BOs magos das sombras da Camarilha podem ser encontrados no Forte do Desterro, a sudeste daqui.", t = "Sangue dos Inocentes"},
    [1067] = {ot = "Leve a Toxina do Lindolfo para a Boticária Zaqueia no Penhasco do Trovão.", st = "Aqui está a toxina. Usá-la contra a Empreendimentos S.A. deve render resultados interessantes, quem sabe até vire uma febre. Devo dizer que é deveras emocionante ver minha obra sendo aplicada!$B$BMas antes de disso, leve-a à Boticária Zaqueia. Ela deve criar um método de dispersão para maximizar os efeitos.", t = "Volte ao Penhasco do Trovão"},
    [1068] = {ot = "Destrua os retalhadores XT:4 e XT:9 e, então, fale novamente com Seereth Quebra-pedra na fronteira entre a Cordilheira das Torres de Pedra e os Sertões.", st = "Existe uma conexão entre a magia espiritual dos xamãs e a natural dos druidas. É por isso que nós, xamãs, ouvimos a súplica dos espíritos das Torres de Pedra. Não consigo distinguir grande parte dos murmurinhos, mas uma mensagem, uma visão, é bem nítida...$B$BVi duas máquinas humanoides no Rochedo Cortavento, a noroeste do Vale Matagrande, derrubando a floresta com uma rapidez inconcebível. Temos que deter essas feras metálicas!$B$BNa visão, tinha uns símbolos estranhos nessas máquinas:$B$BXT:4 e XT:9.", t = "Retalhando as máquinas retalhadoras"},
    [1069] = {ot = "Leve 15 Ovos de Fundolimo para Cáliper Porcatraca em Vila Catraca.", st = "Omeletes de ovos de aranha são a nova sensação na Angra do Butim! Só tem um problema... nada de ovos na Angra do Butim.$B$BSinto cheiro de oportunidade!$B$BNo Rochedo Cortavento e no Desfiladeiro Sishir, lá pro noroeste da Cordilheira das Torres de Pedra, existe a aranha de fundolimo. Arranja ovos dessa aranha pra mim que te pago uma bolada!$B$BNo Rochedo Cortavento, tem um bocado de ovos nas árvores que sobraram por lá.$B$BNo Desfiladeiro Sishir..., bem, é melhor catar ovos no Rochedo Cortavento se tiver estômago fraco...", t = "Ovos de Aranha de Fundolimo"},
    [1070] = {ot = "Encontre Kaela Umbralança, que está de frente para o vale que adentra o Rochedo Cortavento, na Cordilheira das Torres de Pedra.", st = "Olá, $n.$B$BParece que o bicho da exploração pegou você. Já esteve na Cordilheira das Torres de Pedra? É uma terra assolada pela Empreendimentos S.A. e outros inimigos dos elfos noturnos.$B$BNão faz muito, a Sentinela Correlobos despachou minha amiga Kaela Umbralança para lá numa investigação sobre a situação na região, mas ainda não tive notícias. O que mais me preocupa é a Aliança ter enviado um mago gnomo junto... receita para encrenca.$B$BPoderia procurar por ela e me trazer notícias?", t = "Em guarda nas Torres de Pedra"},
    [1071] = {ot = "Mate 10 Madeireiros da Empreendimentos S.A. e 10 Desmatadores da Empreendimentos S.A. e fale novamente com Gaxim Deuxabu nas Torres de Pedra.", st = "Veja bem, $n, sou membro da Assembleia Esclarecida de Arcanologia, Alquimia e Ciências da Engenharia, e é meu objetivo... não, meu DEVER!... mostrar aos elfos noturnos que um uma misturazinha de magia, preparados e mecanismos pode ajudar a salvar suas florestas.$B$BMas é uma guerra dura, e os goblins parecem se reproduzir como coelhos. Sequer tive tempo de trabalhar nas minhas invenções!$B$BPreciso de um tempinho para planejar e organizar, mas, para isso, preciso da sua ajuda para manter os goblins sob controle no Rochedo Cortavento, a leste daqui.", t = "Adiamento gnômico"},
    [1072] = {ot = "Fale com Lomac Motopista em Altaforja.", st = "O dispositivo que tenho em mente é minha versão mais avançada até o momento. No entanto, será necessária uma poçãozinha especial para que ele funcione. Acho que, como esta pode ser a sua última missão, podemos muito bem usar o que temos de melhor.$B$BAssim sendo, precisaremos de explosivos potentes: nitromirglicerônio.$B$BA única pessoa que sabe fazer NG-5 é um velho amigo meu: Lomac Motopista. Procure por ele no Beco da Gambiarra.$B$BVocê o convence a fazer um pouco de NG-5 para nós e eu vou preparando os suportes para os meus aparelhos.", t = "Um velho colega"},
    [1073] = {ot = "Leve 4 Poções Menores de Mana e 2 Elixires de Fortitude Menor para Lomac Motopista em Altaforja.", st = "Hahaha... você precisa de Nitromirglicerônio para impedir que os goblins destruam a floresta?!$B$BNão me importa se você conhece Gaxim ou não... Vou lhe dar a mercadoria só para ver você ou eles explodindo em pedacinhos bem pequenininhos.$B$BSó tem um problema: acabou o meu estoque.$B$BMas olha só: me traga as poções certas e eu faço um pouquinho para você em dois tempos.$B$BO mínimo que você pode fazer é se provar um alquimista competente antes receber uma amostra da minha maior criação.", t = "Inaptidão + Reagentes = Diversão"},
    [1075] = {ot = "Encontre Collin Mauren em Ventobravo.", st = "Bem, quanto à parte do meu plano em que acionamos os explosivos remotamente... ah, ainda não expliquei essa parte, não é?$B$BEstá bem. Resumindo, a situação é a seguinte: com um pouquinho de magia, consigo fazer com que os explosivos só explodam quando você não estiver por perto. Estou montando um dispositivo que permitirá a você explodir o NG-5 ao apertar de um botãozinho, mas só quando você estiver $gpronto:pronta;.$B$BPorém, preciso de um feitiço de um amigo de Ventobravo. O nome dele é Collin Mauren. Você pode encontrá-lo no distrito dos magos. Ele é humano, então não deve ser fácil deixar de notá-lo.", t = "Um pergaminho de Mauren"},
    [1076] = {ot = "Leve os Destroços do Redemoinho de Poeira para Álvaro Columba em Ventobravo.", st = "Ah, já sei... um feitiço de mensagem. Acho que é esse o efeito que ele busca.$B$BTerei de criar um pergaminho impresso com o feitiço. Para isso, precisarei de destroços de um redemoinho de poeira.$B$BEnquanto eu reúno o resto dos componentes, porque você não vai até Cerro Oeste atrás dessas criaturas ignóbeis? Elas são perigosas, mas se você está $Gdisposto:disposta; a servir de cobaia nos experimentos de Gaxim, acho que dará conta do recado.$B$BEstarei aqui quando retornar.", t = "Redemoinhos no Cerro Oeste"},
    [1078] = {ot = "Leve 8 Escamas Cristalizadas para Álvaro Columba em Ventobravo.", st = "Os viajantes sempre me perguntam sobre a Cordilheira das Torres de Pedra. Parece ser um lugar famoso para se aventurar, seja em busca de mantícoras, elementais ou para quem tenha pendências a tratar com a Empreendimentos S.A.$B$BNo Vale Carbonizado, no meio das Torres de Pedra, vivia uma espécie de basilisco cujas escamas, pulverizadas, davam um excelente reagente para alguns dos feitiços que criei.$B$BSe esses basiliscos ainda existirem, adoraria conseguir um pouco de escamas.$B$BQuando puder, não se apresse, mas lembre que pagarei bem.", t = "Coleta para Columba"},
    [1085] = {ot = "Fale com Gaxim.", st = "A situação aqui nas Torres de Pedra é obviamente grave para um elfo noturno e um gnomo estarem trabalhando juntos.$B$BA Empreendimentos S.A. vem devastando estas terras e gastei a maior parte do meu tempo pondo fim à destruição.$B$BNão julgue Gaxim prematuramente. Ele entende a importância de trabalharmos juntos.$B$BSe você quiser nos ajudar, comece falando com Gaxim.$B$BLamento por eu ainda não poder mandar você de volta a Tara com boas notícias. Talvez em breve.", t = "Em guarda nas Torres de Pedra"},
    [1086] = {ot = "Leve o Vaporizador Tóxico até o aeródromo da Empreendimentos S.A. e depois fale com a Boticária Zaqueia.", st = "A toxina está pronta. Só falta entregar a encomenda. Você, $n, fará a entrega.$B$BA Empreendimentos S.A. deve ter uma forma de transportar mensagens e cargas leves entre o quartel general e as operações nas Torres de Pedra. Deve ser algum aeródromo pequeno demais para um zepelim, mas perfeito pra uma máquina voadora. Vasculhe a região nas mãos da Empreendimentos S.A em Torres de Pedra e ache esse aeródromo, se ele existir. Quando o encontrar, é só largar a toxina lá.$B$BLargue e dê o fora.", t = "Aeroporto de máquinas voadoras"},
    [1087] = {ot = "Mate 4 Filhos de Cenarius, 4 Filhas de Cenarius e 4 Botânicos Cenarianos para Braelyn Manígnea, no Retiro Rocha do Sol.", st = "Você não pode imaginar o ódio que sinto por esta terra infame. A laia de Cenarius e os druidas kaldorei no Morro das Torres de Pedra empregam seus poderes patéticos na supressão do fluxo da magia, mesmo tão longe ao sul da floresta patética que tanto amam.$b$bEu gostaria de poder voltar a Jaedenar e me regozijar no fluxo da magia, mas meu mestre não permitirá meu retorno até que meu trabalho esteja concluído.$b$bNão me resta dúvida de que você nutre tão pouco apreço pelos elfos noturnos e seus aliados quanto eu. Auxilie-me e nossos objetivos serão ambos satisfeitos.", t = "O legado de Cenarius"},
    [1088] = {ot = "Leve a Cabeça de Ornanos a Braelyn Manígnea no Retiro Rocha do Sol.", st = "Eles acreditaram que seriam capazes de estancar o fluxo da magia. Estavam errados. Pensaram que conseguiriam ocultar Ornanos, mas terei a cabeça dele!$b$bA magia me concede a verdadeira visão. Sim... lá está ele. Uma encruzilhada... No topo de uma grande árvore na Floresta do Vale Gris. Um nome... Bosque Real. Um dos filhos mais velhos do deus da floresta. Eles retiraram Ornanos do morro antes que eu conseguisse encontrá-lo, mas o tempo dele está acabando.$b$bTraga a cabeça dele para mim e partilharei com você uma poderosa dádiva.", t = "Ornanos"},
    [1090] = {ot = "Pegue o minério misterioso com Piznik depois que ele terminar de minerá-lo.", st = "Sabe, eu já fui a segunda pessoa mais importante aqui. Mas tudo mudou quando o Hanfritz tomou o comando. Ele despediu o meu chefe, o Zé Fízzica, e me mandou pra cá pra baixo pra trabalhar na mina. Mas o Zé me falou pra ficar e ver o que está rolando. O novo chefe dele vai pagar bem se a gente conseguir descobrir o plano do Hanfritz.$b$bDe qualquer forma, tudo que eu sei é que o Hanfritz mandou pegar muito desse minério verde dourado aí. Eu posso te dar um pedaço pra levar pro Zé, mas você vai ter que olhar os guardas enquanto eu pego.", t = "Ordens de Hanfritz"},
    [1092] = {ot = "Entregue o Minério Não Identificado a Zé Fízzica na Cordilheira das Torres de Pedra.", st = "Eu acho melhor eu pensar em sair daqui, também. Não vai demorar muito até a notícia do que aconteceu aqui chegar nos gerentes, e eles não vão ser muito simpáticos se me encontrarem de novo.$B$BEu vou de fininho encontrar o Zé. Espero que ele consiga me arranjar um emprego novo!$b$bE eu vou tentar arrumar um pouco essa bagunça, mas é melhor você levar logo esse pedaço do minério pro Zé. Ele me disse que ia montar acampamento em algum logar no lado oeste do Rochedo Cortavento. Boa sorte.", t = "Ordens de Hanfritz"},
    [1093] = {ot = "Consiga os Diagramas do Super Ceifador 6000 e entregue-os a Zé Fízzica na Cordilheira das Torres de Pedra.", st = "Mas que coisa horrível a Empreendimentos S.A. fez aqui, hein? O que diabos eles estavam pensando? Uma empresa goblínica contratando um gnomo!$b$bPra minha sorte, o Cobogó reconhece um gênio quando dá de cara com um. Ele me contratou logo depois de terem me chutado!$b$bParece que eles construíram uma máquina gigante de cortar lenha, e o Sput quer que eu roube os diagramas pra ele. Infelizmente, o Hanfritz... maldito gnomo!... quer me ver morto. Você não quer roubar os diagramas pra mim? Eles devem estar com um dos operadores.", t = "Super Ceifador 6000"},
    [1094] = {ot = "Entregue o Envelope Selado para Cobogó nos Sertões.", st = "Nesse envelope aí estão todas as informações que eu consegui pescar enquanto eles estavam me chutando porta afora. Documentos internos da Empreendimentos S.A., alguns manuais, coisas técnicas... Ah, e, claro, os diagramas do Ceifador 6000.$b$bO Cobogó está morando na Vila Catraca, lá nos Sertões. Eu não acho que vai ser difícil achar ele. Tipo... o cara é um sujeitinho verde.", t = "Instruções adicionais"},
    [1095] = {ot = "Leve as novas ordens a Zé Fízzica na Cordilheira das Torres de Pedra.", st = "Esse lance do gnomo contratado pela Empreendimentos S.A. anda causando um fuzuê na Inframina. Os príncipes mercadores não aprovam o Frustrus andar de conchavo com esse tal Hanfritz.$b$bCharadox pediu pra eu dar um jeito nisso e aposto que foi um, ou vários, príncipes mercadores que deu a ordem. Claro, o Diretor não disse nada. Vamos dizer que é só um palpite.$b$bVerdade ou não, Hanfritz já era, e mandar o Fízzica cuidar dele já serve de teste pra ele.", t = "Instruções adicionais"},
    [1096] = {ot = "Leve o Braço Mecânico do Hanfritz a Zé Fízzica na Cordilheira das Torres de Pedra.", st = "Eu já encontrei o Hanfritz uma vez, mas, cá entre nós, o cara é feio de doer. A carne dele dá impressão de que está caindo de podre, ele inventou de pôr metal e engrenagens no próprio corpo e trocou alguns membros por outros mecânicos.$b$bMais pro nordeste daqui, em cima do Lago do Rochedo, lá perto da roda d'água. É de lá que o Hanfritz vigia tudo. Eu não tenho como abrir caminho na marra até lá, e muito menos lutar com o Hanfritz... mas você parece capaz de conseguir.$b$bSe você matar ele pra mim, o que eu faço valer o seu esforço!", t = "Hanfritz Schaventorck"},
    [1097] = {ot = "Fale com Grimand Elmore.", st = "Um dos armeiros de Ventobravo, o Grimand Elmore, mandou avisar que precisa de ajuda com uma entrega. Acho que ele quer enviar uma encomenda para a cidade natal dele, no norte.$B$BQue pernas fortes você tem, hein? Então, se estiver $Ginteressado:interessada; em botá-las para trabalhar, fale com o Grimand. Você até nos seria útil aqui, mas sempre é bom fortalecer os laços com os anões.$B$BO Grimand Elmore fica na loja de armas do Distrito dos Anões, em Ventobravo, na parte nordeste da cidade.", t = "Tarefa de Elmore"},
    [1098] = {ot = "Encontre o Sicário Admeto e o Sicário Vicente.", st = "Nos preparativos do ataque à Presa Negra, dois sicários forma enviados para coletar informações. Já faz vários dias e nada de notícias, mas precisamos desse relatório se quisermos que o ataque dê certo!$B$BEntão, você vai fazer o seguinte, $n. Vá para o sul, na Bastilha da Presa Negra, e procure pelos Sicários Admeto e Vicente. Encontre-os e, caso necessário, auxilie-os.$B$BEssa é uma missão crítica, mas perigosa, $n. Não fracasse.", t = "Sicários na Presa Negra"},
    [1100] = {ot = "Leia o Diário de Henrig Monocelha.", st = "Você abre, com cuidado, o diário desgastado de Henrig Monocelha...", t = "Diário do Monocelha"},
    [1101] = {ot = "Leve o Medalhão da Talhaflanco para Falfindel Trilhemas em Thalanaar.", st = "Coitado do Heralath! E desse anão... o Monocelha, que alma valente.$b$bDevemos honrar a bravura deles. Essa bruxa... Charlga Talhaflanco... precisa ser detida.$b$bClaro, infiltrar o Urzal será arriscado. Não há tempo para comunicar Darnassus. $n, reúna um grupo e assassine a bruxa.$b$bTraga-me o medalhão da Talhaflanco como indício de sua morte.", t = "A bruxa má do Urzal"},
    [1102] = {ot = "Leve o Coração da Talhaflanco para Auld Agulha de Pedra no Penhasco do Trovão.", st = "Caerne é um nobre líder por ter unificado nosso povo aqui no Penhasco do Trovão.$b$bMas, diferente de outros, não perdoo tão facilmente quem nos expulsou de nossas terras ancestrais. Meu povo habita os Sertões Meridionais há décadas. Essa terra era sagrada para nós.$b$bUm destino vingativo está reservado para a bruxa Charlga Talhaflanco, que está formando um exército vil no interior do Urzal dos Tuscos.$b$bTraga-me o coração de Talhaflanco para que eu repouse em paz, $n.", t = "Um destino vingativo"},
    [1109] = {ot = "Leve 1 porção de Guano de Morcego para o Mestre-boticário Faranello na Cidade Baixa.", st = "Como pode ver, $n, aqui na Real Sociedade de Boticários nos engajamos em experimentos muito... interessantes.$b$bComo mestre aqui, meu dever é supervisionar as investigações alquímicas mais ambiciosas. Tanto trabalho e tão pouco tempo!$b$bVocê para ter viajado muito para $Gum:uma; $c. Talvez possa me ajudar.$b$bPreciso de uma substância rara. É um material podre derivado de uma rara espécie de morcego encontrada apenas naquele buraco nojento do Urzal dos Tuscos. Traga-me o guano dos morcegos do Urzal para darmos início aos trabalhos...", t = "Matéria orguânica"},
    [1111] = {ot = "Leve a Encomenda de Peças de Kravel para o Mestre Portuário Caruncho na Vila Catraca.", st = "Meu trampo é arranjar o que me pedem, e aqueles gnomos ali querem encomendar umas peças. As peças já foram bandeadas para a Vila Catraca faz uma semana, mas não consegui me atinar de fazer essa troteada.$B$BTás a fim de dar uma pernada? Te dirige até a Vila Catraca e passa este pedido de peças para o Mestre Portuário Caruncho. Tu encontras ele pelas docas.$B$BTu me faz essa mão e te arranjo mais serviços.$B$BServiços, bagual, serviços bem rentáveis...", t = "Mestre Portuário Caruncho"},
    [1112] = {ot = "Leve as Peças de Kravel para Kravel Barbakarvão no Salar Cintilante.", st = "Taí a encomenda do Kravel, $n. Quando entregar, diz pra ele que... se ele quiser mais encomendas especiais, é melhor pagar o que tá pendurado!", t = "Peças para Kravel"},
    [1131] = {ot = "Leve a Costela do Estalaço para Melor Casco de Pedra no Penhasco do Trovão.", st = "Às vezes caçamos em busca de comida. Às vezes caçamos em busca de honra. Às vezes caçamos para receber os ensinamentos da Mãe Terra.$B$BMas a caçada em questão não se encaixa em nenhuma dessas categorias. A criatura que você vai abater não tem a bênção da Mãe Terra.$B$BA hiena Estalaço ronda as Mil Agulhas, ao sul dos Sertões. É um bicho tirano, que atrai outras hienas para espalhar medo e derramar o sangue dos bichos mais mansos.$B$BEncontre o Estalaço, $n. Encontre-o e derrote-o.", t = "Estalaço"},
    [1134] = {ot = "Leve 12 Vesículas de Peçonha de Asaltiva para Shindrell Fogofugaz em Astranaar.", st = "Não estamos em guerra declarada contra a Horda, mas a paz é frágil. Seus agentes estão sempre agindo contra nós, porém em segredo.$B$BUma dessas manobras nos foi revelada por fontes secretas em Theramore, segundo as quais os orcs vêm recolhendo veneno das asaltivas, perto do Lago Mirkfallon, na Cordilheira das Torres de Pedra ao sul. Depois os assassinos orcs usam o veneno em massacres perpetrados contra a Aliança!$B$BSe isso for verdade, nós temos que detê-los, $n. Precisamos secar a fonte do veneno.", t = "Os asaltivas das Torres de Pedra"},
    [1138] = {ot = "Recolha 6 Pedaços Delicados de Caranguejo para Gubber Blump em Auberdine.", st = "Eu adoro caranguejo. O caranguejo é o verdadeiro fruto do mar! Dá para assar, grelhar e cozinhar. Fica bom frito, refogado e salteado. Tem também a salada de caranguejo, a sopa de caranguejo, o caranguejo de panela, o caranguejo picante, o caranguejo-limão, o caranguejo-raiz e o caranguejo-surpresa-de-Altaforja. É... acho que é isso.$B$BNo momento, eu estou pescando, então não tenho como catar caranguejo. Dá para catar nos tiscorais e nos maretiscos incrustados. Dá para fazer muita coisa. Dá para assar, grelhar e cozinhar...", t = "Frutos do mar"},
    [1140] = {ot = "Liberte a alma dos Altaneiros na Trilha da Noite e em Satyrnaar, depois fale novamente com Dinis, o Purificador, no Entreposto de Maestra.", st = "A caligrafia dos orcs é pouco mais legível que os garranchos de uma criança. Muitos membros da ordem desdenharam de mim quando decidi aprender a língua deles, porém isso ajudaria a compreender melhor o inimigo.$b$bPelos rabiscos de Ilkrud, eu diria que Athrikus ainda está com duas gemas anímicas, uma na Trilha da Noite e a outra em Satyrnaar, duas regiões dominadas por sátiros, na parte nordeste do Vale Gris.$b$bTome cuidado, $n, os templos macabros dos sátiros são perturbadores, mesmo para um $c calejad$Go:a; como você.", t = "A torre de Althalaxx"},
    [1141] = {ot = "Pesque 6 Garoupas da Costa Negra para Gubber Blump em Auberdine.", st = "Eu adoro pescar. A família Blump tem fama de pescadora. Meu nome é Gubber Blump, eu sou pescador.$B$BTem um peixe que eu gosto de pescar por estas bandas chamado Garoupa da Costa Negra. Eu saía de barco para pescar garoupa, mas quase não saem mais barcos desde que os murlocs pintaram na área. Aposto que estão comendo todas as garoupas.$B$BDiga lá, que tal me ajudar a pescar umas Garoupas da Costa Negra? Eu lhe dou uma Vara de Pescar da Família Blump se você me ajudar! É uma vara boa que só para pegar peixe.", t = "Vara de canoeiro, prefere pescar"},
    [1142] = {ot = "Encontre e devolva o Pingente de Treshala para Treshala Corregofulvo em Darnassus.", st = "Não tenho muito mais tempo de vida... me sinto... fraco.$b$b...mandaram o Monocelha, um anão corajoso, alertar Falfindel...$b$bMas antes que eu... morra...$b$b...minha esposa, Treshala... nosso pingente de casal... roubado... por um dos agressores...$b$bEncontre-o, por favor... e devolva-o a Treshala em Darnassus...$b$b...junto com a notícia de minha morte... solitária...", t = "A mortalidade se esvanece"},
    [1144] = {ot = "Escolte o Importador Willix para fora do Urzal dos Tuscos.", st = "Finalmente a ajuda chegou!$b$bVocê não faz ideia de há quanto tempo eu estou preso aqui. Não consigo nem me lembrar quando foi a última vez que vi o lado de fora.$b$bEu sou um empreendedor, sabe? Sempre atrás do cobre, como dizem por aí. Eu soube que Cáliper Porcatraca estava pagando bem pelos Tubérculos Carmins desse urzal. Imaginei que seria vapt-vupt. Como dá para ver, eu estava equivocado!$b$bDe qualquer forma, se você puder fazer a gentileza de me ajudar a sair daqui, eu lhe garanto que vai valer a pena.", t = "Importador Willix"},
    [1145] = {ot = "Leve o Bilhete Selado de Korran para Belgrom Pedramalho em Orgrimmar.", st = "Muitos viajantes que passaram pela Encruzilhada me ajudaram a recolher ovos no Campo dos Gigantes, e vários contaram casos de como aquelas criaturas são perigosas. Eu ouvi tantos casos que já considero aqueles insetos um perigo muito maior do que meu mestre imaginava.$B$BEu preciso de um mensageiro que vá até Belgrom Pedramalho, em Orgrimmar. Não será uma tarefa simples, preciso de alguém que vá levá-la a sério.$B$BBelgrom costuma ficar em frente a guilda dos guerreiros.", t = "O enxame se adensa"},
    [1146] = {ot = "Leve o Bilhete Selado de Belgrom para Moktar Krin em Mil Agulhas.", st = "Então Korran chegou a uma conclusão parecida sobre os insetos... parece que são maiores do que pensávamos.$B$BUns dias atrás um caçador voltou das Mil Agulhas à beira da morte. Ele estava com um grupo de busca que tinha ido resgatar uma equipe de escavação enânica no Salar Cintilante. Durante o ataque, um monte de insetos irrompeu da caverna no sítio de escavação e quase matou o grupo.$B$BEles estavam sob a liderança de Moktar Krin, e se refugiaram na beira do Salar Cintilante. Leve esse bilhete para ele.", t = "O enxame se adensa"},
    [1149] = {ot = "Se tiver fé, pule lá de cima das tábuas, no topo de Mil Agulhas.", st = "Então você veio atrás de mim, ou vai ver foi o destino quem $Go:a; trouxe aqui? Pouco importa. Cá está você para iniciar uma nova jornada.$B$BMuitas são as facetas de um ser: o espírito, o corpo, a mente... Algumas se pode medir pelas tradições de uma cultura. Outras, só nos resta ter fé de que existem no âmago do ser. Se você estiver de acordo, eu colocarei algumas das suas facetas à prova.$B$BSe passar no teste, você ficará mais forte. Se fracassar, você perceberá como é vasto o Éter.$B$BO primeiro é o teste da fé.", t = "Teste da Fé"},
    [1150] = {ot = "Leve a Garra da Grenka para Dorn Espreitaprados em Mil Agulhas.", st = "Fico feliz em ver de sua coragem continua a mesma depois de tudo que você já passou. Já que sua fé permanece intacta, é hora de testar seu corpo.$B$BPrimeiro vem o teste de resistência. Vá com alguns amigos ao Covil Plumerrante, a oeste da Aldeia Vento Livre. Desbrave as profundezas do covil e destrua os alimentos que encontrar por lá. Isso vai provocar a fúria das harpias. Se você sobreviver, uma hora Grenka Sangrunhidos vai atrás de você. Mate-a e traga as garras dela para concluir o teste.", t = "Teste de resistência"},
    [1151] = {ot = "Leve os Fragmentos de Rok'Alim para Dorn Espreitaprados em Mil Agulhas.", st = "Na época dos Deuses Antigos, os elementais habitavam boa parte do mundo. Eles adoravam os Deuses Antigos, e os Deuses, por meio de seus poderes, mantinham os elementais vinculados a este mundo. Quando os Deuses Antigos foram banidos, os elementais sumiram do nosso mundo e agora só conseguem se manifestar sob o comando de magos poderosos.$B$BMas existem algumas exceções. Alguns elementais eram poderosos o bastante para permanecer aqui por conta própria. Rok'Alim é um desses elementais.$B$BPara testar sua força, encontre Rok'Alim em Mil Agulhas e mate-o.", t = "Teste de força"},
    [1153] = {ot = "Obtenha uma Amostra Não Refinada de Minério de um Escavador Britanapa ou de um Topógrafo e leve para Trapista Forjaço no Acampamento Taurajo, que fica nos Sertões.", st = "$C, você já me ajudou bastante. O Chefe Guerreiro está satisfeito com tudo que fizemos e me pediu para manter a mesma determinação. O mais honrado seria dar-lhe o reconhecimento diante do Chefe Guerreiro, mas antes vou pedir sua ajuda mais uma vez.$B$BNão faz muito, passaram alguns viajantes vindo do sul, de um lugar chamado Mil Agulhas. Lá, eles mataram um kobold que possuía um minério um tanto incomum, mas não quiseram vendê-lo. Eu quero uma amostra do minério para examiná-la.", t = "Uma nova amostra de minério"},
    [1167] = {ot = "Fale com Balthule Umbrataque perto da Torre de Althalaxx.", st = "Antes de confrontar Athrikus, seria melhor você consultar Balthule. Sem dúvida, ele andou vigiando a torre com bastante atenção e deve ter informações sobre os últimos desdobramentos.", t = "A torre de Althalaxx"},
    [1195] = {ot = "Leve o Frasco Cinzelado Cheio para Zangan Casco de Pedra no Penhasco do Trovão.", st = "Os centauros Galath em Mil Agulhas protegem um artefato da época de sua criação.$b$bNós gostaríamos de obtê-lo, mas precisamos de um frasco de água de um dos poços lunares dos elfos noturnos.$b$bPara coletar a água, você precisará primeiro obter um dos frascos das dríades próximas ao Refúgio Bosque Real, no coração da Floresta do Vale Gris. Há um poço lunar perto da margem oeste do Rio Felfarren, ao sul da estrada principal, onde você poderá encher o frasco.", t = "A Chama Sagrada"},
    [1196] = {ot = "Entregue o Frasco Cinzelado Cheio a Rau Corta Montes na Aldeia Vento Livre.", st = "Leve o frasco preenchido para Rau Corta Montes na Aldeia Vento Livre, ao sudeste de Mil Agulhas. Você pode chegar a Mil Agulhas pegando o Grande Elevador na extremidade sul dos Sertões.$b$bEu não ficaria surpreso se você puder nos ajudar mais um pouco.", t = "A Chama Sagrada"},
    [1197] = {ot = "Recupere o Casco Fendido para Rau Corta Montes na Aldeia Vento Livre.", st = "Usando a água que você trouxe, será possível apagar temporariamente a chama que envolve a relíquia dos centauros. O efeito não será permanente, no entanto, então você terá que agir rápido.$b$bVocê encontrará o Rochedo do Casco Fendido, a fortaleza dos centauros, ao norte daqui. A chama é mantida no Castelo do Casco Fendido, uma parte muito bem protegida do rochedo.$b$bTenha cuidado, os centauros Galath estarão em grande número e relutarão em entregar algo que lhes é tão valioso.", t = "A Chama Sagrada"},
    [1198] = {ot = "Procure o Guarda Argênteo Thaelrid nas Profundezas Negras.", st = "Há muito rumores circulando hoje em dia sobre a união do Martelo do Crepúsculo e das nagas das Profundezas Negras na costa do Vale Gris.$b$bMinha função na Aurora Argêntea é coletar o máximo de informações possível, para que saibamos quando e onde a ajuda é necessária.$b$bFaz semanas que eu enviei um batedor para verificar a atividade nas Profundezas Negras. O Guarda Argênteo Thaelrid ainda não reportou de volta.$b$bOs meus outros batedores estão ocupados com assuntos mais urgentes.$b$bEncontre e ajude Thaelrid por mim, $n.", t = "Procurando Thaelrid"},
    [1199] = {ot = "Leve 10 Pingentes do Crepúsculo para o Guarda Argênteo Manados em Darnassus.", st = "Encorajados pelos velhos rituais dos caóticos Deuses Antigos, os membros do Martelo do Crepúsculo se esforçam para trazer os sombrios patronos de volta e espalhar morte e terror pelo mundo.$b$bNós acreditamos que o Martelo do Crepúsculo se aliou às nagas e está se reunindo nas Profundezas Negras, que fica na costa do Vale Gris.$b$bQualquer plano maligno que esteja sendo preparado nas profundezas do antigo templo deve ser impedido.$b$bAtaque o Martelo e traga provas dos seus feitos. Os seus esforços serão muito bem recompensados.", t = "A Hora do Crepúsculo"},
    [1200] = {ot = "Leve a cabeça do Senhor do Crepúsculo Kelris para o Vigilalva Selgorm em Darnassus.", st = "Eu estou sem forças. Vou precisar da sua ajuda!$b$bMuito tempo atrás, este local abrigava o grande templo de Eluna. Mas a desgraça levou à ruína quando a corrupção do deus antigo se infiltrou das profundezas da terra e contaminou o poço lunar sagrado.$b$bAku'mai, servo do deus antigo, se ergueu das águas.$b$bOs sectários do Martelo do Crepúsculo se aliaram às nagas para ocupar este local. Os cultistas, liderados por Kelris, sacrificam inocentes ao poder de Aku'mai.$b$bMate Kelris e leve sua cabeça para Selgorm em Darnassus, $n, por favor.", t = "Vilania das Profundezas"},
    [1221] = {ot = "Pegue um Caixote com Furos.$BPegue um Bastão de Adestramento do Fungafuça.$BPegue e leia o Manual de Proprietário do Fungafuça.$B$BNo Urzal dos Tuscos, use o Caixote com Furos para evocar uma Marmota Fungafuça, e use o Bastão de Adestramento do Fungafuça para fazer ela farejar os tubérculos.$B$BLeve 6 Tubérculos Folhazul, o Bastão de Adestramento do Fungafuça e o Caixote com Furos para Cáliper Porcatraca na Vila Catraca.", st = "Os tubérculos folhazul são uma iguaria no mundo todo! Mas eles são raros, muito raros. Só dá para encontrar aqui nos Sertões, bem fundo na terra, no Urzal dos Tuscos.$B$BE, mesmo assim, eles são difíceis de achar, a não ser que você saiba onde procurar! É por isso que eu treinei essas marmotas fungafuça para farejar eles. Elas têm focinhos incríveis e podem farejar um tubérculo a uns cinquenta passos de distância.$B$BNão vai ser fácil, mas se conseguir uns tubérculos para mim, eu vou ser muito generoso com você.", t = "Tubérculos Folhazul"},
    [1275] = {ot = "Gershala Umbrurmúrio em Auberdine quer 8 Troncos Encefálicos Corrompidos.", st = "Esses elfos sangrentos ignorantes brincam com magia demoníaca. Eles não viram o que aconteceu com as nagas e os sátiros de Kalimdor?$b$bEu temo que os elfos sangrentos adquiram uma deformação parecida. Azeroth não se pode dar ao luxo de criar outra raça de monstros depravados.$b$bEu quero estudar os troncos encefálicos dos sátiros e nagas para tentar entender para onde os elfos estão se dirigindo. Nas Profundezas Negras, que fica na costa do Vale Gris, você encontrará tanto sátiros quanto nagas.$b$bEsta será uma viagem muito longa, $n.", t = "Pesquisar a corrupção"},
    [1338] = {ot = "Entregue o Pedido de Lançatroz para Furen Barbalonga em Ventobravo.", st = "Eu conheço um ferreiro de armaduras cujo trabalho admiro muito. O nome dele é Furen Barbalonga, e habilidade como a dele não há. Estou precisando de um escudo novo, quero um dos dele!$b$bMas tem um problema... O Furen mora longe, lá para o sul, no distrito enânico de Ventobravo. Em terras humanas! Nem imagino o que o fez morar tão longe de Altaforja. Os humanos devem pagar muito bem para segurar um anão de qualidade como ele por lá!$B$BEntão, se você quer viajar e ainda ganhar umas moedinhas, poderia entregar o meu pedido para o Furen?", t = "Ordens dos Lançatroz"},
    [1339] = {ot = "Fale com o Montanhista Lançatroz.", st = "Ouvi dizer que o Montanhista Lançatroz anda atrás de um corredor. Alguém para fazer umas viagens para ele. Interessa? Será você $Uo:a; $r que procuro?$B$BSe for, encontre Lançatroz no topo da torre de vigia norte.", t = "Uma tarefa do Montanhista Lançatroz"},
    [1358] = {ot = "Leve a Amostra de Coração de Lobo para Boticário Hermógenes nos Sertões.", st = "Um colega de Kalimdor, o boticário Hermógenes, está pesquisando os efeitos das toxinas de Lordaeron nas feras de Kalimdor. Ele teria muito interesse em uma amostra dos corações de lobo que Renferrel me enviou.$B$BHermógenes está nos Sertões, numa vila chamada Encruzilhada. Para chegar até ele, viaje por zepelim até a capital orc de Orgrimmar, depois siga a pé para o sul, rumo a Durotar. Adentre os Sertões indo a oeste e logo você estará na Encruzilhada.", t = "Uma amostra para Hermógenes"},
    [1359] = {ot = "Leve a Amostras de Coração de Lobo para Boticária Zilda na Cidade Baixa.", st = "Os corações de lobo que você arranjou exibem características inusitadas, jamais vistas em espécimes similares. A toxicidade deles deveria ser letal até para os lobos cujo sangue eles bombeiam!$B$BIsso é surpreendente e requer mais estudos. Separei umas amostras dos corações obtidos. Leve-as para minha colega, a boticária Zilda. Você a encontra em nossa sede na Cidade Baixa.", t = "Entrega para Zilda"},
    [1431] = {ot = "Fale com Keldran em Orgrimmar.", st = "Fique $gquieto:quieta; um pouco, $c, e me permita compartilhar com você algo importante para nosso povo.$B$BSomos uma raça orgulhosa, e a guerra contra os humanos testou até mesmo a grande paciência de Thrall. Nosso Chefe Guerreiro é sábio e prudente, e ele continua a colocar os interesses do povo em primeiro lugar. No final, ele é um diplomata, e o tempo que ele passou ao lado dos humanos lhe ensinou muito a respeito dessa raça.$B$BSe essa história interessou você, procure Keldran perto da saída ocidental da cidade. É lá que ele mora.", t = "Relações da Aliança"},
    [1442] = {ot = "Leve a Gema Kor para Trovejius Tecevento, na Costa Negra.", st = "Saudações, $n. Como posso ajudar alguém que trilha o caminho sagrado?$B$BAh, sim, Calmafonte, o ferreiro... quanto tempo. Eu me lembro bem dele, mas faz muito tempo que não escuto esse nome.$B$BEle nunca me pareceu um homem afeito a brincadeiras, então creio que o pedido dele de uma gema Kor seja justo.$B$BSe você realmente quer encontrar uma das gemas, vá para a região noroeste do Vale Gris. Lá, por entre as ruínas ancestrais, há um lugar chamado Profundezas Negras, lar de nagas que ainda usam as gemas. Não vá $Gsozinho:sozinha;, $c.", t = "Em busca da Gema Kor"},
    [1470] = {ot = "Leve 3 Crânios de Range-ossos para Vênia Martingil.", st = "Saudações, criança. Posso ver que você ainda engatinha no caminho dos bruxos, que o poder ainda lhe escapa. Consigo sentir seu desejo de aprender.$b$bE você vai aprender.$b$bNão existe força na ignorância. O conhecimento é o nosso maior poder. Por meio de sua aplicação podemos controlar a magia e os seres do caos, curvando-os à nossa vontade.$b$bEu lhe mostrarei como vincular um servo a sua vontade, mas antes você precisa me trazer três crânios dos esqueletos range-ossos lá de perto da ferraria abandonada.", t = "Perfurando o véu"},
    [1471] = {ot = "Usando as Runas de Evocação, evoque e subjugue um Emissário do Caos. Depois, devolva os Glifos de Evocação para Silvério Hidalgo no Distrito da Magia na Cidade Baixa.", st = "Você viu o círculo de evocação aqui abaixo? É o único lugar em que você conseguirá invocar um andarilho do caos livre.$b$bUsando essas runas você conseguirá invocá-lo, e em seguida precisará dominá-lo com força e magia.$b$bQuando for subjugado, ele se tornará seu servo. Então, venha a mim para que eu elucide o feitiço de evocação. Assim ele $go:a; servirá em todos os seus objetivos.", t = "A vinculação"},
    [1473] = {ot = "Recupere o Grimório de Egalin e leve-o para Silvério Hidalgo no Templo dos Malditos.", st = "Parece que o consenso é de que você está pront$go:a; para evocar um andarilho do caos.$b$bUm ser criado a partir do caos do além... Se você evocar um, mas não conseguir controlá-lo, você será destroçad$go:a;.$b$bO primeiro andarilho do caos foi evocado por Egalin, e o processo está explicado no grimório dele.$b$bInfelizmente porém, ele foi roubado de nós por um agente da Cruzada Escarlate, que o escondeu na própria base, uma torre pro oeste daqui. Traga o grimório e eu passarei esse conhecimento a você.", t = "Criatura do caos"},
    [1478] = {ot = "Fale com Silvério Hidalgo na Cidade Baixa.", st = "Ah, $n! Acabei de receber uma mensagem de Silvério Hidalgo, dizendo que ele gostaria de falar com você para aprofundar o seu treinamento.$b$bVocê devia se orgulhar, $n. Não é todo dia que o Mestre Halgar em pessoa julga conveniente treinar um jovem bruxo.$b$bVocê vai encontrá-lo no Distrito da Magia da Cidade Baixa, perto do Templo dos Malditos.", t = "Convocação de Hidalgo"},
    [1483] = {ot = "Fale com Zé Fízzica em Rochedo Cortavento.", st = "A Empreendimentos S.A. roubou muitos dos melhores cérebros goblínicos, mas, de tempos em tempos, temos a oportunidade de roubar alguns de volta.$b$bUm tempo atrás, a Empreendimentos S.A das Cordilheira das Torres de Pedra contratou Hanfritz Schaventorck — um gnomo! O outro engenheiro deles, Zé Fízzica, ficou tão passado com isso que me pediu pra arranjar outro emprego pra ele no Sindicato dos Faz-tudo. Eu passei algumas tarefas pra ele, mas acho que o cara vai precisar de ajuda.$b$bSerá que você pode dar um confere nele pra mim? Ele está na beirada oeste do Rochedo Cortavento.", t = "Zé Fízzica"},
    [1485] = {ot = "Leve 6 Cabeças de Demônios Familiares Vis para Ruzan.", st = "Esses bruxos que vieram antes de nós ganharam a desconfiança da Horda e, apesar de sermos tolerados, não somos queridos.$b$bMas isso não uniu os bruxos, já que muitos escolhem levar uma vida reclusa, fazendo seus experimentos mágicos sozinhos. Eu não vou pretendo guiar você por esse ou aquele caminho, só quero ajudar no seu amadurecimento.$b$bAntes de eu lhe ensinar a arte da invocação, traga seis cabeças de demônios familiares vis da caverna a nordeste.", t = "Familiares Vis"},
    [1486] = {ot = "Nalpak na Caverna Ululante quer 20 Pelegos Anormais.", st = "Enquanto Naralex descia mais e mais fundo no pesadelo, uma raça estranha de feras surgiu nos Sertões e fez da Caverna Ululante o seu lar.$b$bEssas criaturas anormais têm características estranhas, que parecem de outro mundo. Apesar de sua natureza maligna, na minha opinião, podemos tirar algo de bom da existência deles aqui em Kalimdor. Acredito que o pelego deles será particularmente útil no estudo da couraria.$b$bSe você se sente à altura do desafio, mate quantas feras puder e me traga alguns pelegos anormais.", t = "Pelegos anormais"},
    [1487] = {ot = "Ebru, na Caverna Ululante, quer que você mate 7 Assoladores Anormais, 7 Víboras Anormais, 7 Trôpegos Anormais e 7 Presáteras Anormais.", st = "Naralex tinha um objetivo nobre.$b$bNosso grande líder almejava entrar no Sonho Esmeralda e ajudar estas terras áridas a serem novamente a floresta pujante que outrora havia aqui. Entretanto, aconteceu algo muito errado.$b$bO sonho de Naralex virou um pesadelo, e criaturas corrompidas começaram a habitar as cavernas.$b$bEnquanto alguns Discípulos de Naralex tentam acordar o nosso mestre, minha preocupação está em livrar as cavernas dos monstros malignos.$b$bExplore as cavernas, $n, e erradique essa cria perversa.", t = "Erradicação de Anormais"},
    [1489] = {ot = "Fale com Hamuul Runa Totem", st = "As carapaças que você me trouxe têm uma mácula de um tipo que eu nunca vi antes. Tenho certeza de que as águas do Oásis são a causa, e eu sinto a confusão que elas causam a esta terra. É como se a terra sonhasse e não pudesse acordar.$B$BA Caverna Ululante deve ser a fonte dessa corrupção. Mas antes de ir, fale com Hamuul Runa Totem, o druida ancião. Eu mandei um aviso a ele do que está acontecendo nos Sertões. Ele é sábio e pode lhe aconselhar.$B$BVocê pode encontrá-lo no Penhasco do Trovão, no Platô dos Anciãos.", t = "Hamuul Runa Totem"},
    [1490] = {ot = "Fale com Nara Juba Agreste.", st = "Eu entrei na terra dos sonhos e sonhei com uma seita de druidas que habitavam a Caverna Ululante. Eu vi que seus objetivos já foram nobres, mas eles se desviaram do caminho. Agora são servos da mácula que toma os Sertões.$B$BEu sou velho, e já não tenho mais forças. Eu não consegui ficar mais tempo naquele lugar onírico para saber mais sobre os druidas corrompidos. Mas Nara é jovem, e seu espírito é bravio. Ela ficou no sonho quando eu fugi.$B$BFale com Nara. Ela está na tenda, logo ali.", t = "Nara Juba Agreste"},
    [1491] = {ot = "Leve 6 porções de Essência Ululante para Cáliper Porcatraca na Vila Catraca.", st = "Tá, então os chifres de raptor não deram certo. Mas não tem problema! Ninguém fica rico logo de cara! Além disso, eu acho que encontramos uma coisa que vai funcionar ainda melhor nas minhas bebidas inteligentes!$B$BExiste uma substância chamada essência ululante, e eu acho que ela é a causa dos animais e plantas estranhos nos Sertões. Me traga um pouco para eu testar na minha bebida!$B$BOuvi dizer que essa essência se acumula em criaturas ectoplasmáticas na Caverna Ululante, a oeste. Cace essas criaturas e colha a essência.", t = "Bebidas inteligentes"},
    [1492] = {ot = "Leve o Caixote Fechado para o Mestre Portuário Caruncho na Vila Catraca.", st = "Eu preciso mandar caixas de poções, reagentes e outros artigos para os meus sócios no Velho Mundo. Mas não tenho tempo para levar tudo até a doca na Vila Catraca, e a última caravana já partiu.$b$bSe você puder, leve isto para o Mestre Portuário Caruncho. Ele vai garantir que coloquem a carga no próximo barco para Angra Aguanegra.", t = "Mestre Portuário Caruncho"},
    [1499] = {ot = "Fale com Zureta Vista-longa.", st = "Zureta tem mandado novatos e novatas como você para ajudar a diminuir o número de criaturas na caverna perto de onde você lutou com os familiares torpes.$b$bAcho que lhe faria bem ganhar experiência ajudando-a. Não se esqueça de dizer a ela que foi você quem a ajudou com o problema dos diabretes, provavelmente ela tem uma recompensa para você.", t = "Familiares torpes"},
    [1501] = {ot = "Recupere a Tabuleta de Verga para Gan'rul Olho de Sangue em Orgrimmar.", st = "Então, restaram alguns bruxos... Nós arriscamos muita coisa, mas os riscos fazem sentido. Você precisa amadurecer suas habilidades se quiser ser útil à Horda e ao Chefe Guerreiro.$b$bEstá na hora de você aprender um feitiço de evocação novo.$b$bPrimeiro, você precisa recuperar a Tabuleta de Verga, que foi roubada pelos bruxos da Lâmina Ardente e é mantida agora no covil deles, na Rocha da Caveira, a leste da cidade. Com a tabuleta, eu vou lhe mostrar as runas necessárias para evocar um Emissário do Caos.", t = "Criatura do caos"},
    [1504] = {ot = "Usando os Glifos de Evocação, evoque e subjugue um Emissário do Caos; depois, devolva os Glifos de Evocação para Gan'rul Olho de Sangue em Orgrimmar.", st = "Agora, observe a Tabuleta de Verga, porque ela contém os glifos de que você vai precisar para a evocação. Leve-os ao círculo na tenda de Neeru Cortafogo, no outro lado da caverna. Lá, você poderá evocar o Emissário do Caos.$b$bVocê tem que derrotá-lo usando quaisquer meios físicos ou mágicos que tiver à mão. Quando terminar, volte aqui com os glifos de evocação, e eu vou demonstrar como você pode vincular criatura à sua vontade.", t = "A vinculação"},
    [1506] = {ot = "Fale com Gan'rul Olho de Sangue em Orgrimmar.", st = "Você aí. $n, não é?$b$bEspero que a sua agenda não esteja cheia, porque Gan'rul quer falar com você imediatamente. Ele está junto com os bruxos veteranos no Antro das Sombras.$b$bBaseado nas minhas experiências com o Gan'rul, essa convocação é uma notícia ótima ou horrível.", t = "Convocação de Gan'rul"},
    [1507] = {ot = "Fale com Cazul no Antro das Sombras.", st = "Chegou a hora de você aprender mais sobre magias de evocação. Você aprenderá a evocar um sayaad, uma criatura de poderes mentais formidáveis. Ela pode submeter seres de mente fraca à servidão — mas não precisa ter medo! Sei que você estará à altura do desafio.$b$bUm sayaad só pode ser evocado quando atraído com um item que representa grande amor e devoção. Vou deixar em suas mãos encontrar esse objeto.$b$bUma dica? Fale com Cazul... Parece que não existem muitas coisas que o velho bruxo não saiba.", t = "Devoradora de almas"},
    [1508] = {ot = "Fale com Zankaja em Orgrimmar.", st = "Se Gan'rul mandou você me procurar, deve ser porque você quer evocar um súcubo, uma fêmea da raça sayaad, e precisa de um objeto para atrair o demônio.\n\nHum... Se confia na orientação de um homem cego, escute, $n. Nos penhascos de Orgrimmar, a oeste da torre das mantícoras, vive Zankaja. Ela espera o retorno de seu amor.\n\nFale com ela.", t = "Cazul cego"},
    [1509] = {ot = "Fale com Gazrog na Encruzilhada.", st = "Meu companheiro, Dogran, foi destacado recentemente para a Encruzilhada. Foi uma promoção, e ele estava muito orgulhoso.$b$bEu fiquei triste, é claro, mas eu não deixei que ele soubesse disso. Fiquei preocupada também. Os Sertões são um lugar mais perigoso que Orgrimmar, e eu temia pelo pior.$b$bAgora já faz uma semana que ele deveria ter voltado, e eu não recebi nenhuma notícia dele...$b$bSerá que você pode ir até a Encruzilhada e ver se descobre alguma coisa? Ele trabalhava com Gazrog, que ainda deve estar destacado lá.", t = "Notícias de Dogran"},
    [1510] = {ot = "Fale com Ken'zigla em Malaka'jin.", st = "Ele estava destacado para o Acampamento Taurajo, que estamos tentando livrar dos javatuscos. Ele liderou uma tropa de brutos até um dos acampamentos deles e acabou ferido. Os outros voltaram e tentaram resgatá-lo. A situação dele é ruim, as feridas infeccionaram, por isso estão com receio de carregá-lo sem tratar as feridas dele antes.$b$bEles mandaram uma mensagem para cá, pedindo um trago curativo dos trolls de Malaka'jin, no sopé da Cordilheira das Torres de Pedra. Nós mandamos alguém lá para buscar, mas ele não voltou mais.", t = "Notícias de Dogran"},
    [1511] = {ot = "Leve o Trago do Ken'zigla para o Bruto Logmar no Acampamento Taurajo.", st = "Imaginei que outra pessoa viria atrás do trago, por isso já deixei ele preparado.$b$bProntinho, $n. Mas lembre-se: você só pode dar metade pra ele! Isso já vai dar força suficiente pra ele se mexer sem sangrar litros. Espere uma noite, depois dê a outra metade.$b$bEnfim, você precisa levar isso para Logmar, no Acampamento Taurajo. Pelo que o primeiro rapaz me disse, ele deve ter alguma ideia de onde encontrar o Dogran.", t = "Trago do Ken'zigla"},
    [1512] = {ot = "Leve o Pingente Coberto de Terra para Gan'rul Olho de Sangue em Orgrimmar.", st = "Zankaja é jovem e bonita. Ficar assim, presa a um inválido... Eu não vou permitir que ela sofra essa injustiça.$b$bPode ir, $n. E obrigado. Eu quero terminar a minha vida em uma batalha gloriosa, e não como uma carcaça sem vida.$b$bE, por favor, não diga nada à minha companheira. Não quero que ela se sinta culpada.", t = "Presente do amor"},
    [1513] = {ot = "Com o Pingente de Dogran, evoque e subjugue uma Súcubo; depois, devolva o Pingente de Dogran a Gan'rul Olho de Sangue, em Orgrimmar.", st = "Leve isto para o círculo de evocação na tenda de Neeru, $n. Evoque uma Súcubo perversa e mostre a ela sua maestria. Eu acredito na força da sua magia. Mas, como sempre, aconselho cautela, pois o orgulho e a autoconfiança exacerbada já derrotaram muitos bruxos promissores.$b$bQuando você a tiver derrotado, traga-me o pingente de volta para que eu possa levar as notícias para Zankaja.", t = "A vinculação"},
    [1515] = {ot = "Leve o Trago do Ken'zigla para Dogran nos Sertões.", st = "Como você já passou por tudo isso, se quiser ver como essa história acaba, eu não vou impedi-$glo:la;. Mas eu não posso lhe disponibilizar mais homens, você está por conta própria.$b$bDogran está preso em um acampamento de javatuscos ao norte daqui. Procure um par de cabanas. Ele estará fortemente protegido — digo, se é que não o mataram ainda ou se ele não tiver sucumbido aos ferimentos.$b$bBoa sorte.", t = "O cativeiro de Dogran"},
    [1516] = {ot = "Leve 2 Cascos de Espreitador Vil para Ranago Arauto da Terra no Vale das Provações.", st = "Chegou a hora, jovem $c. Você cresceu e seu espírito ficou forte como a terra. Seguir o caminho dos xamãs é a prova de que você é $Gsábio:sábia; antes mesmo de provar seu valor.$B$BO elemento da terra guiará seus passos, tornando-se parte do seu ser se você estiver $Gpronto:pronta;. Mas você precisa se pôr à frente da terra. Se estiver na hora, você verá coisas que só um xamã pode enxergar.$B$BProcure os Espreitadores Vis ao norte e traga-me dois cascos deles. Aí, sim, falaremos do seu futuro.\n", t = "Clamor da Terra"},
    [1517] = {ot = "Encontre a Rocha dos Espíritos e beba o Sapta da Terra.", st = "Um Sapta é uma bebida criada para vincular o nosso espírito aos elementos. Infundida com magia, a poção permitirá aos de vontade férrea enxergar os elementos como ninguém mais pode. Seu espírito se conectará ao elemento para o qual o sapta foi criado, e somente um seleto grupo de xamãs conhece a receita.$B$BO sapta sempre é bebido em um local sagrado, e nunca em qualquer outro lugar — lembre-se disso.$B$BProcure a Rocha dos Espíritos a sudoeste daqui — ela fica no final do Caminho Oculto. Beba o seu sapta lá e... bem, você verá.", t = "Clamor da Terra"},
    [1518] = {ot = "Leve o Quartzo Grosseiro para Ranago Arauto da Terra no Vale das Provações.", st = "Pague este quartzo grosseiro e leve até Ranago Arauto da Terra como prova do nosso encontro. Ele vai lhe fazer um totem que terá este quartzo como coração. Por menor que ele possa parecer, você vai acabar descobrindo que tamanho não é documento, e que mesmo as menores coisas podem durar mais que muitas outras.$B$BTenha paciência, $n. Tenha força. E busque a sabedoria. É tudo o que a terra lhe pede. No fim, você e a terra serão uma coisa só, respeite-a como ela respeita você.", t = "Clamor da Terra"},
    [1519] = {ot = "Leve 2 aplicações de Unguento de Ritual à Vidente Pena do Corvo na Aldeia Narache.", st = "Chegou o momento, jovem $c. Seu corpo amadurece e se fortalece, e seu espírito resiste como a terra. Vejo isso dentro de você — já há sabedoria aí.$B$BA terra guia o nosso povo, ela fala conosco, assim como falará com você em seu devido tempo. Mas você precisa passar pelo testo. Se estiver $Gpronto:pronta;, então você verá coisas que só o nosso povo conhece.$B$BProcure os xamãs Costagulha na ravina ao leste e tome deles um unguento que eles usam em rituais. Só volte aqui quando tiver suficiente para a sua própria poção.", t = "Clamor da Terra"},
    [1520] = {ot = "Encontre a Rocha dos Kodos e beba o Sapta da Terra.", st = "O Sapta é uma bebida criada para vincular o nosso espírito aos elementos. Infundida com magia, a poção permitirá aos de mente aberta enxergar os elementos como ninguém jamais enxergou. Seu espírito se ligará para sempre ao elemento para o qual o sapta foi criado, e somente um seleto grupo da nossa raça conhece a receita.$B$BO sapta sempre é ingerido em um local sagrado, e nunca em qualquer outro lugar.$B$BProcure o santuário do xamã a leste daqui e beba o sapta.", t = "Clamor da Terra"},
    [1521] = {ot = "Leve o Quartzo Grosseiro à Vidente Pena do Corvo na Aldeia Narache.", st = "Pegue este quartzo grosseiro e leve até a Vidente Pena do Corvo como prova do nosso encontro. Ela vai lhe fazer um totem, que terá este quartzo como coração. Por menor que possa parecer, você vai acabar descobrindo que tamanho não é documento, e que mesmo as menores coisas podem durar mais que montanhas.$B$BTenha paciência, $n. Tenha força. E busque a sabedoria. É tudo o que a terra lhe pede. No fim, você e a terra serão uma coisa só. Respeite-a como ela respeita você.", t = "Clamor da Terra"},
    [1524] = {ot = "Leve a Tocha da Chama Latente para Telf Joolam em Durotar.", st = "Você tem poder suficiente para empunhar o totem do fogo, mas isso não significa que esteja pront$go:a;.$B$BNas margens do Rio Furiaustral, em Durotar, antes do Grande Oceano, fica uma trilha oculta que leva a um dos picos mais altos da região. Faça o caminho até o cume e encontre o altar sagrado vigiado por Telf Joolam, o Altar da Chama Latente.$B$BEntregue e ele esta tocha. Ela mostra que você está tentando domar o fogo. Acenda no braseiro do altar, traga de volta para cá e cuidarei para que você receba o totem do fogo.", t = "Clamor do Fogo"},
    [1525] = {ot = "Traga 1 Piche Ígneo e 1 Bornal de Reagentes para Telf Joolam em Durotar.", st = "Mas você não veio aqui estudar história, não é? Veio em busca da Chama Eterna e do totem do fogo.$B$BO primeiro passo é criar um sapta e se vincular à chama.$B$BConsigo criar o sapta do fogo se você me trouxer dois itens. Um é o piche ígneo, algo que os feiticeiros Crinavalha dos Sertões Orientais costumam carregar sempre com eles.$B$BO outro é mais perigoso, o bornal de reagentes de um dos sectários da Lâmina Ardente. Eles costumam ficar em uma caverna no alto das ravinas a nordeste do Monte Navalha.", t = "Clamor do Fogo"},
    [1526] = {ot = "Derrote a Manifestação Menor do Fogo e coloque a Brasa Faiscante no braseiro do Altar da Chama Eterna.", st = "O sapta do fogo está pronto. Chegou a hora de você encarar a chama. Use o sapta no altar e siga até o cume da montanha para encontrar a manifestação lá em cima. Ele não vai atacar enquanto você não estiver pront$go:a;, mas vai perceber que você consegue vê-lo.$B$BAcabe com ele rapidamente, $n, porque vai ficar mais forte a cada minuto que passa. Depois de derrotá-lo, coloque as brasas faiscantes no braseiro e acenda a tocha.", t = "Clamor do fogo"},
    [1527] = {ot = "Leve a Tocha da Chama Eterna a Kranal Fiss nos Sertões.", st = "Segure a tocha com firmeza, afaste-se do braseiro e olhe para fora na direção de Durotar. Você vai sentir a empolgação enlaçando seu espírito enquanto o vento entra e obriga a chama a dançar violentamente.$B$BFaça o caminho de volta até os Sertões em busca de Kranal Fiss.", t = "Clamor do Fogo"},
    [1530] = {ot = "Encontre Salma nos Sertões Meridionais.", st = "Se tem uma lição que a água pode lhe ensinar, é a seguinte: água significa renascimento.$B$BSeu poder flui, erode e limpa todos os tipos de coisas. Você vai descobrir uma habilidade de cura e reabastecimento incomparável, mas só quando a água é pura.$B$BQuando entender que a água poluída pode destruir tudo em que toca, você vai perceber que ela é um recurso vital.$B$BSe quiser um sapta da água, encontre Salma no coração dos Sertões Meridionais. A casa dela é molestada ininterruptamente pelos javatuscos.", t = "O clamor da água"},
    [1531] = {ot = "Encontre Pradosa Fita Nuvens em Mil Agulhas.", st = "Tu fez um grande progresso, fera. Já tá prontinh$go:a; para mostrar se é dign$go:a; do totem do ar, mas, pra isso, tu precisa encontrar a Pradosa Fita Nuvens em Mil Agulhas. Se tu mostrar respeito, ela pode te ensinar como conseguir um totem do ar.$B$BSegue para o sul em direção aos Sertões e, depois que chegar a Mil Agulhas, segue para o leste. Ela vai tá escondida num buraco com o namorado — haha, não conta pra ela que eu falei isso, ela vai ficar pistola.", t = "Clamor do ar"},
    [1534] = {ot = "Encha o Odre Azul Vazio nas Ruínas de Poeira Estelar, que fica no Vale Gris, e devolva-o para Salma nos Sertões.", st = "Pegue este odre e embrenhe-se pela densa floresta que os elfos noturnos chamam de Vale Gris. Fica no extremo norte dos Sertões.$B$BDepois que entrar, siga em direção oeste. Margeando as montanhas que separam Torres de Pedra e Vale Gris, depois do Lago Mistral, você vai encontrar um lugar sagrado: as Ruínas de Poeira Estelar. No meio do lago tem uma pequena fonte.$B$BTraga uma amostra da água da fonte para mim. É o último componente que você vai precisar antes que eu mande você de volta a Islen.", t = "O clamor da água"},
    [1535] = {ot = "Encha o Odre Marrom Vazio no laguinho abaixo da cabana de Salma e leve para ela nos Sertões.", st = "Para encontrar o conhecimento e ganhar o sapta, você precisa procurar as formas mais puras de água. Ao encontrar as amostras para mim, faça anotações sobre os arredores. Fique atent$go:a; às criaturas que precisam da água, que a protegem. Veja como ela afeta florestas e desertos. Veja como a substância que sustenta a vida obriga criaturas e dar cabo de outras vidas.$B$BVamos começar com uma tarefa simples: abaixo da minha cabana tem um laguinho do líquido precioso. Encha este odre e traga para mim.", t = "O clamor da água"},
    [1536] = {ot = "Encha o Odre Vermelho Vazio no poço da Serraria Tarren e entregue-o para Salma nos Sertões.", st = "Muito tempo atrás eu fui com alguns companheiros até o Contraforte de Eira dos Montes. Nós nos defendemos de humanos tenazes que viviam ali e acabamos indo parar em uma cidadezinha que os Renegados haviam tomado: Serraria Tarren.$B$BFoi lá que encontrei algo bastante peculiar: no centro da cidade havia um pequeno poço com água fresca da fonte. Nem sei se aqueles cidadãos pestilentos tinham noção do valor daquilo: um ínfimo vestígio sagrado em um mar de profanidades.$B$BTraga-me uma amostra da água neste odre.", t = "O clamor da água"},
    [1578] = {ot = "Entregue 6 Machados de Cobre e 6 Cintos Encadeados de Cobre para Thorvald, na torre de vigia sul de Loch Modan", st = "Os montanhistas de Loch Modan estão combatendo os troggs e andam muito ocupados! Eles vão precisar de um reabastecimento constante de armas e armaduras, se quiserem ganhar a peleja com os troggs.$B$BÉ por isso que o meu sócio, Thorvald, está lá, tentando dar conta da reposição do armamento dos montanhistas. Então, se você pudesse forjar alguns machados e cintos encadeados de cobre e levá-los para o Thorvald, ele ficaria muito agradecido. Talvez ele até divida parte do que sabe com você.$B$BO Thorvald está na torre de guarda sul de Loch Modan.", t = "Suprimentos para o front"},
    [1579] = {ot = "Entregue 8 Deschanfradores para Xafetim Manigiro em Auberdine.", st = "Eu vim para Auberdine porque é um lugar silencioso. Quero inventar minhas invenções onde faz silêncio, porque depois de uma carraspana eu não gosto da barulheira de Altaforja!$B$BEntão peguei o barco para Auberdine e bebi um tiquinho a mais no caminho e acabei deixando a minha caixa de deschanfradores cair no mar. Preciso dos meus deschanfradores!$B$BNão sei onde caíram, mas se você tentar pescar, quem sabe consegue encontrar...", t = "Deschanfradores"},
    [1580] = {ot = "Entregue 12 Eletromolas para o Xafetim Manigiro em Auberdine.", st = "Você tem sorte... Mas tem sorte de verdade mesmo, $n?$B$BCerta noite eu estava andando pelas ruas da Costa Negra, procurando um rio ou lago para testar o meu engabela-patos explosivo com autopropulsão. Só que eu devia estar meio ébrio... porque desmaiei e acordei horas depois em Auberdine. Meu cabelo estava chamuscado e minha bolsa de eletromolas tinha desaparecido! Devo ter deixado cair na água!$B$BPreciso das minhas eletromolas! Será que você consegue pescar eles em algum riacho ou lago da Costa Negra.", t = "Eletromolas"},
    [1581] = {ot = "Traga 6 Elixires de Força de Leão e 2 Elixires de Defesa Menor para Syral Folhâmina, em Dolanaar.", st = "Nossas lojas de plantas e alquimia estão lucrando incrivelmente, mas meu marido gasta tanto tempo preparando poções que nunca temos tempo para nós.$B$BPoderia nos ajudar?$B$BSe puder me trazer um suprimento de elixires já preparados, ficarei grata em realizar uma troca. Tenho umas plantas raras que talvez lhe sejam úteis.", t = "Elixires para os Folhâminas"},
    [1598] = {ot = "Tome Poderes do Caos para Drusilla La Salle.", st = "Você aí! $n, não é?$b$bEspero que você queira mesmo se tornar $Gum:uma; brux$Go:a;, porque se não conseguir segurar a barra, você já era.$b$bEu vou treinar você, mas antes preciso ter certeza de que você tem força suficiente.$b$bUm noviço que estudava na Abadia fugiu para entrar para a Irmandade Défias. Eu não daria a mínima para isso, mas eles roubou livros importantes.$b$bPor coincidência, um deles é um livro que eu queria: Poderes do Caos. Vá lá roubar para mim. Ele está escondido na tenda deles, nos Vinhedos.", t = "Ladrão que rouba ladrão..."},
    [1599] = {ot = "Leve 3 Patuás de Penas para Alamar Carranca em Sidermar.", st = "Você deve ser $Go:a; nov$Go:a; brux$Go:a; de quem todos estão falando à boca miúda. Alguém deve gostar mesmo de você, para virem me pedir para fazer uma pausa na minha pesquisa e começar o seu treinamento.$b$bNão precisa se preocupar, eu sei que a culpa não é sua.$b$bO feitiço mais simples de evocação é o do diabrete. No entanto, antes de dividir isso com você, você tem que provar que tem a habilidade física e o poder mágico necessários.$b$bTraga aqui três amuletos de penas dos noviços jubafria que estão na caverna a sudoeste.", t = "Primeiros passos"},
    [1618] = {ot = "Tormus Baixaforja quer que você dê 4 Cintos Rúnicos de Cobre e 4 Malhos Pesados de Cobre para Vervo Obom, em Cristarrubra.", st = "Os anões não são os únicos que estão em guerra. Nossos aliados humanos também estão na peleja!$B$BCristarrubra está sob ataques constantes dos orcs Rocha Negra, e o estoque de equipamentos deles está sempre baixo. Se ajudá-los, tenho certeza que o ferreiro deles, Vervo Obom, ensinará uma coisinha ou outra para você.", t = "Armamentos para Cristarrubra"},
    [1638] = {ot = "Fale com Ari Barbotina.", st = "Você provou ser u$Gm:ma; guerreir$Go:a; capaz, $n. Mas você ainda é jovem e tem muito a aprender.$B$BFale com Ari Barbotina. Ele geralmente fica na taberna Javatusco Saltitante, na Cidade Velha de Ventobravo. Além de veterano, o Ari é um bom professor. Ele pode te ensinar umas técnicas que vão te ajudar a manter o fôlego por mais tempo.", t = "Treinamento de guerreiro"},
    [1639] = {ot = "Fale com Bartolino.", st = "Sim, eu posso te ensinar, sim. Mas antes quero ver o que você já sabe.$B$BEstá vendo aquele bebum lá no canto? É o Bartolino. Eu quero que você vá lá tomar a caneca dele.$B$BSe você conhece o Bartolino, sabe que ele não vai deixar isso barato.", t = "Bartolino, o bebum"},
    [1640] = {ot = "Vença o Bartolino e converse com ele.", st = "Você quer o quê? Endoidou, foi?$B$BSe quiser essa caneca, vai ter que me matar antes...", t = "Que surra, Bartolino!"},
    [1641] = {t = "Tomo de Divindade"},
    [1642] = {ot = "Fale com Benedito Brião em Ventobravo.", st = "Acima de tudo, um paladino deve refletir a Luz que alimenta nossa força. A nossa determinação para alcançar a divindade não se manifesta na luta para ser um deus, mas pela bondade em toda e qualquer ação.$B$BOs tempos são duros e clamam por nós para punir o mal, mas você precisa se lembrar sempre de que é o socorro prestado aos outros que verdadeiramente separa um paladino dos habitantes de Azeroth. Compaixão, paciência, bravura... são valores que significam tanto para nós quanto a força na batalha.$B$BSaiba-o em seu coração, e nunca se esqueça.", t = "Tomo de Divindade"},
    [1643] = {ot = "Procure Stephanie Turner no Distrito Comercial de Ventobravo.", st = "Portanto, $n, sua tarefa é achar alguém aqui em Ventobravo que precise de ajuda. Alguém que tenha coração puro e determinação. Talvez alguém que esteja ajudando o próximo. Ou alguém que precise de um guia. Seja como for, é preciso que seja alguém com intenções nobres e que dependa da sua gentileza.$B$BFaça isso e venha falar comigo quando terminar. Aí, conversaremos mais sobre o caminho à sua espera e o que significa ser paladino da Luz.", t = "Tomo de Divindade"},
    [1644] = {ot = "Leve 10 pedaços de Linho para Stephanie Turner em Ventobravo.", st = "Pobrezinhos, a maioria nem família tem mais, depois dos ataques do Flagelo nos últimos dez anos.$B$BMeu marido João coleta a matéria-prima e eu faço calças e camisas para as crianças, mas ainda não tive tempo. Tenho me concentrado em pôr comida no prato delas e garantir um teto para as coitadinhas.$B$BComo é que é? Você quer me ajudar? Ai, graças à Luz. Muito obrigada, $n.$B$BSe você pudesse trazer um pouco de linho para eu costurar roupas para as crianças, seria de grande ajuda.", t = "Tomo de Divindade"},
    [1645] = {t = "Tomo da Divindade"},
    [1646] = {ot = "Fale com Tiza Beloforja em Altaforja.", st = "Acima de tudo, um paladino deve refletir a Luz que alimenta nossa força. A nossa determinação para alcançar a divindade não se manifesta na luta para ser um deus, mas pela bondade em toda e qualquer ação.$B$BOs tempos são duros e clamam por nós para punir o mal, mas você precisa se lembrar sempre que é o socorro prestado aos outros que verdadeiramente separa um paladino dos habitantes de Azeroth. Compaixão, paciência, bravura... são valores significam tanto para nós quanto a força na batalha.$B$BSaiba-o em seu coração, e nunca se esqueça.", t = "Tomo da Divindade"},
    [1647] = {ot = "Vasculhe o anel externo de Altaforja para João Turner.", st = "Portanto, $n, sua tarefa é achar alguém aqui em Altaforja que precise de ajuda. Alguém que tenha pureza de coração e determinação. Talvez alguém que esteja ajudando uma outra pessoa. Ou alguém que precise de um guia. Seja como for, é preciso que seja alguém com uma intenção nobre e que dependa da sua gentileza.$B$BFaça isso e venha falar comigo quando terminar. Aí, conversaremos mais sobre o caminho à sua espera e o que significa ser paladino da Luz.", t = "Tomo da Divindade"},
    [1648] = {ot = "Leve 10 peças de Linho para João Turner em Altaforja.", st = "Eu e minha esposa cuidamos de um orfanato em Ventobravo, para atender principalmente crianças que perderam os pais nos ataques do Flagelo dos últimos dez anos. Eu venho a Altaforja mais ou menos uma vez por mês para coletar suprimentos dos habitantes daqui, e converso com diversos grupos, para ver se eles podem contribuir de alguma forma.$B$BEsta viagem tem sido agonizantemente lenta, sem falar em pouco produtiva.$B$BSe eu conseguisse pegar mais linho para minha esposa fazer umas roupas, eu poderia finalmente mandar um carregamento para casa.", t = "Tomo da Divindade"},
    [1649] = {ot = "Fale com Benedito Brião em Ventobravo.", st = "A bravura, e todas as virtudes que a acompanham, são como joias raras: é preciso reconhecer o valor que elas têm e cuidar bem delas, mas também é preciso coletá-las com cuidado, e lapidá-las. Quando polidas da forma correta, força nenhuma é capaz de quebrá-las.$B$BSua força, sua fé, sua bravura, devem ser postas à prova. Você tem que aprender a nunca perder a fé e perceber que, com o poder da Luz, é capaz de superar coisas que a maioria consegue.", t = "Tomo da Bravura"},
    [1650] = {ot = "Encontre Dafne Calmafonte no Cerro Oeste.", st = "Ótimo! Sua falta de hesitação demonstra que você está pront$Go:a; e determinad$Go:a; para provar sua força. Que assim seja.$B$BNo fim da Praia Grande do Cerro Oeste, há uma pequena casa de frente para o mar. Um casal vive lá, os Calmafonte. Jardel, um artesão incrível, foi para Altaforja passar algum tempo com os anões. Com isso, sua esposa, Dafne, ficou sozinha e sem proteção.$B$BRelatórios sugerem que os Défias praticamente tomaram o controle da área. Dafne talvez precise de ajuda para se proteger dos bandidos. Vá até lá.", t = "Tomo da Bravura"},
    [1651] = {ot = "Proteja Dafne Calmafonte do ataque dos Défias.$B$BPara obter êxito, seus espíritos não podem ser despidos do lodo mortal.$B$BQuando você conseguir, fale novamente com Dafne Calmafonte.", st = "Eu aposto que logo, logo eles vão estar aqui de novo, então é bom se preparar.$B$BEu tenho uma arma na casa. Vou pegar para tentar te ajudar, mas, na maior parte do tempo, você vai estar por conta própria.$B$BNão faço ideia de quantos eles vão mandar, mas tenho certeza de que vão ser mais do que mandaram mais cedo.$B$BRogue à Luz que lhe conceda todas as bênçãos que puder, porque... Ouviu isso? Acho que eles vêm aí.$B$BVamos ficar na casa e lutar!", t = "Tomo da Bravura"},
    [1652] = {ot = "Fale com Benedito Brião em Ventobravo.", st = "Por favor, fale novamente com Duthorian e avise que eu estou em segurança. Graças a você e à Igreja.$B$BEle deve mandar uma mensagem para Altaforja, para avisar o Jardel de que não há nada a temer.$B$BOh, que saudade do meu marido. Mal posso esperar a volta dele.", t = "Tomo da Bravura"},
    [1653] = {ot = "Fale com Jardel Calmafonte em Altaforja.", st = "A bem da verdade, não duvido que o próprio Jardel queira agradecer pessoalmente, e como eu preciso mesmo de um mensageiro para avisar que a esposa dele está segura, acho que você seria a escolha ideal.$B$BJardel se preparava para se tornar um paladino da Luz quando a dedicação ao ofício do pai o levou por outros caminhos. Ele está muito bem familiarizado com o nosso modo de vida e é considerado um dos mais fervorosos entre nós.$B$BEle ainda deve estar em Altaforja, e gosta de trabalhar fora dos portões durante o dia. Segundo ele, tem a ver com a brisa fresca da montanha.", t = "A prova da retidão"},
    [1654] = {ot = "Usando as Anotações do Jardel sobre Armas, encontre Madeira de Carvalho de Pedralva, o Carregamento de Minério Refinado do Bailor, o Martelo de Ferreiro de Jardel e uma Gema Kor. Depois, entregue tudo a Jardel Calmafonte em Altaforja.", st = "Eu gostaria de lhe oferecer uma recompensa, se você aceitar. Não me entenda mal, minha generosidade depende de quanta ajuda você pode me dar, mas eu acho que nós dois vamos nos beneficiar muito de uma aliança assim.$B$BEu vou criar para você uma arma digna do que você alcançou, um símbolo do paladinismo e da Luz, mas você terá que conseguir os itens que eu preciso para criá-lo. Eu já comecei a fazer uma lista dos itens, agora só preciso de alguém com coragem e habilidade para obtê-los. O que me diz, $c?", t = "A prova da retidão"},
    [1656] = {ot = "Leve a Trouxa de Peles para o Estalajadeiro Kauth na Aldeia Casco Sangrento.", st = "Por favor, $n, eu imploro. Você pode me ajudar? Não terminei meus afazeres na Chapada – estou no meio do meu Rito de Força – e meu pai pediu para entregar essas peles na estalagem de Casco Sangrento.$B$BEstou no meio do rito, da tarefa do meu pai e não descansei nada. Você pode ir no meu lugar?$B$BA estalagem é agradável, um lugar perfeito para descansar durante suas longas viagens. Tenho certeza de que você vai concordar quando puser os olhos nela.", t = "Serviço pela metade"},
    [1665] = {ot = "Leve a Caneca do Bartolino para o Barbotina", st = "Tá, tá, toma aqui a minha caneca. Peraí! Deixa só eu terminar... pronto.", t = "A caneca do Bartolino"},
    [1680] = {ot = "Fale com Tormus Baixaforja.", st = "Agora que você aprendeu algumas técnicas, hora de arranjar uma arma decente. Fale com Tormus Baixaforja. Ele vai fazer uma arma que eu sei que você vai gostar.$B$BO Tormus vive aqui em Altaforja, na Grande Forja.", t = "Tormus Baixaforja"},
    [1683] = {ot = "Leve a Trompa de Vorlus para Elanaria em Darnassus.", st = "Para eu poder lhe ensinar, você terá que provar sua determinação.$B$BO sátiro Vorlus Cascruel achou um dos nossos poços lunares mais distantes, a sudeste da Gruta de Ban'ethil. Agora ele se banha lá, conspurcando as águas imaculadas com sua imundície.$B$BEncontre-o no poço lunar e acabe com Vorlus. Traga a trompa dele e nós daremos início ao seu treinamento avançado de guerreir$go:a;.$B$BA trilha que leva ao poço lunar é bem escondida, $n, mas basta se concentrar e se manter alerta para encontrá-la.", t = "Vorlus Cascruel"},
    [1684] = {ot = "Fale com Elanaria.", st = "Saudações, guerreir$go:a;. Sua habilidade aumenta, mas há muito mais envolvido no ofício do que você imagina. Para avançar mais, logo será preciso encontrar um mestre.$B$BA guerreira Elanaria vive em Darnassus, no Terraço dos Guerreiros. Ela poderá instruir você.", t = "Elanaria"},
    [1685] = {ot = "Apresente-se a Gakin, o Neromante, no Distrito dos Magos de Ventobravo.", st = "Não é sempre assim? Procurei você o dia todo e não encontrei e, agora, quando menos espero, você aparece na minha frente.$b$bJá perdi muito tempo tentando te achar, por isso não vou fazer você perder mais tempo. O mestre Gakin convocou você para um treinamento adicional. Me parece que é melhor você ir até ele quanto antes.$b$bEle está no porão da taverna Cordeiro Imolado. Inclusive, é uma boa ideia evitar alarde sobre aquele lugar. Não quero que todo mundo fique sabendo.", t = "Convocação de Gakin"},
    [1688] = {ot = "Recupere a Gargantilha de Surena e entregue-a a Gakin, o Neromante, em Ventobravo.", st = "Eu tive uma aluna chamada Surena Caledon. Ela estava na posição que você ocupa agora, sedenta por aprender a magia dos bruxos, e demonstrava muito talento. Além disso, ela era jovem e um verdadeiro colírio. Eu bem que devia ter ficado de olhos abertos naquela pilantra!$b$bA rampeira farsante fugiu com Erlan Mourejardo, um Défias. Ela mesma não tem nenhuma importância, mas eu a presenteei com uma gargantilha de pedra-sangrenta que preciso ter de volta.$b$bA vida dela não significa nada para mim. Ela agora está na Plantação de Abóboras dos Braga. Vá buscar o que é meu.", t = "Surena Caledon"},
    [1689] = {ot = "Usando a Gargantilha de Pedra-sangrenta, evoque e sobrepuje um emissário do caos. Depois, devolva a Gargantilha de Pedra-sangrenta a Gakin, o Neromante, em Ventobravo.", st = "Recuperando minha gargantilha e sobrepujando Surena você provou ter ao menos tanto potencial quanto ela.$b$bNo entanto, é visível que você precisa de treinamento. Sim, você é capaz de controlar fluxos mágicos, mas ser u$Gm:ma; brux$Go:a; é muito mais que isso.$b$bEu mostrarei a você como dominar um emissário do caos, mas antes você terá que trazer um num círculo de evocação e o subjugar usando quaisquer armas – físicas e mágicas – à sua disposição. Use a magia da gargantilha no círculo de evocação logo abaixo.", t = "A vinculação"},
    [1699] = {ot = "Entre nas Cavernas Retibanas, chegue à primeira bifurcação e volte até Yorus Cervevada no tempo estipulado.$B$BMorrer e libertar o espírito não é permitido.", st = "Eu batizei esse desafio como Desafio da Retibana. Pra passar por ele, tu só tem que entrar nas Cavernas Retibanas, ir até a primeira bifurcação e voltar aqui. Mais fácil que tirar doce de guri! Só tem uns detalhezinhos...$B$BTu tem uma hora pra voltar.$B$BTem uma pá de gnolls cristarrubra no caminho.$B$BAntes de começar, tu tem que virar um copo do drinque especial da minha família: o grogue Cervevada!$B$BE aí, o que me diz? As Cavernas Retibanas ficam no contraforte ao norte da Vila Plácida. Tu tem peito pra encarar a Provação Retibana ou o quê?", t = "Desafio da Retibana"},
    [1701] = {ot = "Colete as matérias-primas pedidas por Furen Barbalonga e leve-as para ele em Ventobravo.", st = "Te arrumei um belo escudo, mas a gente não tem que parar nele. Eu sei como criar uma armadura de malha buenaça, de primeira. Não é fácil, e requer umas matérias-primas raríssimas, mas se tu tiver a disposição pra ir atrás delas, eu te ajeito.$B$BO que me diz, $n? Se tu topar o desafio, eu te dou uma lista do que vou precisar e onde tu pode arrumar.", t = "Malha endurecida a fogo"},
    [1702] = {ot = "Leve o Barril de Grogue para Furen Barbalonga.", st = "Você mostrou mesmo que tem fibra ao enfrentar o desafio da Retibana, $n. E eu sou anão de palavra. Vou te dar a recompensa...$B$BMas ela está em Ventobravo.$B$BFala lá com o meu amigo, Furen Barbalonga, no Distrito dos Anões em Ventobravo. Ele é o melhor fabricante de escudos que tu vai ver na vida, e ele me deve um favor.$B$BAqui, leva esse barrilete de Grogue Cervevada e fala com ele. Ele vai te dar um baita de um escudo.", t = "O fabricante de escudos"},
    [1716] = {ot = "Fale com Takar, o Vidente, nos Sertões.", st = "Sayaades são devoradores de almas, dominadores de livres-arbítrios, provocadores de corações.\n\nHistórias lascivas se referem a esses demônios pelo nome comum: súcubo para as fêmeas, íncubo para os machos.\n\nÉ necessário um estímulo para atrair a criatura. Com um símbolo de amor servindo de isca, ela certamente ouvirá seu chamado. Depois de derrotado, o demônio se tornará uma ferramenta em suas mãos.\n\nEntretanto, será difícil encontrar algo dessa natureza. Você devia falar com Takar, o Vidente. Ele deve estar nos Sertões de Kalimdor, perto do Acampamento Taurajo.", t = "Devoradora de almas"},
    [1718] = {ot = "Fale com Klannoc Macleod.", st = "Seu renome como guerreir$go:a; esta crescendo, $n. Chegou a hora de encarar seus pares e ver como se sai.$B$BHá uma ilha perto da costa dos Sertões, ao sul da Vila Catraca. Ela se chama Ilha da Peleja, um lugar onde guerreiros se encontram.$B$BSe encontram e se enfrentam.$B$BFale com o guerreiro chefe da Ilha da Peleja, Klannoc Macleod. Se achar você dign$go:a;, Klannoc $go:a; levará adiante no caminho dos guerreiros.$B$BPara chegar à Ilha da Peleja, procure as partes rasas e os bancos de areia da Costa dos Mercadores.", t = "O ilhéu"},
    [1719] = {ot = "Mate o Grande Gui. Em seguida, fale com Klannoc Macleod na Ilha da Peleja.", st = "Se quiser aprender comigo, primeiro tem que passar pela Contenda. É um desafio que nós da Ilha da Peleja gostamos de apresentar a guerreiros em ascensão que se acham durões. Se você passar no teste, eu saberei que você é dur$gão:ona; mesmo.$B$BPara começar, vá até aquele pessoal ali e pise na grade. Isso vai sinalizar para o Kabe Sashata que você está pront$go:a;, e ele vai mandar os desafiantes contra você.$B$BDerrote todos os desafiantes e o Kabe chamará o Grande Gui. Mate o Grande Gui, e então fale novamente comigo logo depois.", t = "A contenda"},
    [1738] = {ot = "Obtenha o Palocórdio no Vale Gris e leve-o a Gakin, o Neromante, no Distrito dos Magos de Ventobravo.", st = "Preparando-me para sua vinda, usei minha visão para procurar pelo mundo e através das brumas do tempo. Encontrei o que você procura.$b$bNa Guerra dos Antigos, dois amantes caíram juntos em batalha. Onde deram juntos seu último suspiro, cresceu uma árvore conhecida como palocórdio, um símbolo de seu amor imortal.$b$bDeve ser tentação suficiente para uma súcubo. Ela fica nas ruínas de Ordil'Aran, no noroeste da floresta do Vale Gris.", t = "Palocórdio"},
    [1739] = {ot = "Usando o Cerne de Palocórdio, evoque e sobrepuje uma súcubo. Em seguida, devolva o Cerne de Palocórdio a Gakin, o Neromante, no Cordeiro Imolado.", st = "Usando o cerne do palocórdio, você conseguirá lançar um feitiço no círculo de evocação na cripta aqui embaixo para abrir um portal para a súcubo.$b$bCuidado, $n. Súcubos podem sobrepujar até mesmo as mentes mais fortes.$b$bUma vez que você a tenha derrotado e banido de volta para o caos, fale novamente comigo. Mostrarei como convocá-la e controlá-la.", t = "A vinculação"},
    [1740] = {ot = "Encontre 3 Fragmentos de Soran'ruk e 1 Fragmento Grande de Soran'ruk e entregue-os a Doan Karhan nos Sertões.", st = "Quando os demônios da Legião perdem prestígio, os espíritos deles são aprisionados em orbes e distribuídos para os magos e bruxos deles.$b$bMuitos desses foram usados pelos servos da Legião em Azeroth. Mesmo fragmentados, eles ainda têm os poderes dos demônios aprisionados em seu interior.$b$bO orbe de Soran'ruk foi partido em dois pedaços, um dos quais foi ainda mais fragmentado para ser usado pelos acólitos do Martelo do Crepúsculo nas Profundezas Negras. A outra metade permaneceu em posse de um mago da Bastilha da Presa Negra. Encontre todos os fragmentos e eu conseguirei restaurar o orbe.", t = "O orbe de Soran'ruk"},
    [1778] = {ot = "Fale com Tiza Beloforja em Altaforja.", st = "Vou tratar de planejar minha volta para casa em breve. Com sorte a Stephanie está bem lá em Ventobravo. Mal posso esperar para vê-la de novo. Até a próxima, $c.", t = "Tomo da Divindade"},
    [1779] = {ot = "Pegue o Símbolo da Vida e fale com Muiredon Beloforja em Altaforja.", st = "Quero que você leve isso, $n. Se chama Símbolo da Vida.$B$BVocê se provou caridos$go:a; e paciente, e agora eu quero que prove quão competente se tornou no combate e no uso do poder.$B$BMuiredon, meu marido, voltou recentemente de um confronto com alguns anões Ferro Negro, e mal escapou com vida. Ele está ali, tratando as feridas com um de nossos sacerdotes.$B$BPegue o Símbolo e fale com ele. Se você conseguir ajudá-lo, poderemos voltar a conversar logo. Que a Luz $go:a; ilumine.", t = "Tomo da Divindade"},
    [1780] = {ot = "Fale com Benedito Brião em Ventobravo.", st = "Vou levar para as crianças todos os dias. Por favor, cuide-se, $c. É raro vir à cidade gente de caráter como o seu, mas você provou que os paladinos aqui de Ventobravo jamais darão as costas aos necessitados.$B$BAdeus.", t = "Tomo da Divindade"},
    [1781] = {ot = "Leve o Símbolo da Vida para Gazin Tenorm em Ventobravo.", st = "Quero que você leve isso, $n. Chama-se Símbolo da Vida.$B$BVocê provou ser caridos$go:a; e paciente, e agora chegou a hora de ver se você é poderos$go:a; o suficiente para ser um foco de uma das maiores dádivas da Luz.$B$BGazin voltou recentemente de um confronto com alguns Défias em Elwynn, perto da Vigia dos Heróis, e mal escapou com vida. Ele está ali, perto do altar, tratando as feridas com um de nossos sacerdotes.$B$BPegue o Símbolo e fale com ele. Se você conseguir ajudá-lo, poderemos voltar a conversar logo. Vá na glória da Luz.", t = "Tomo da Divindade"},
    [1783] = {ot = "Leve o Símbolo da Vida e ressuscite Narm Faulk em Dun Morogh.", st = "Estava eu e ele espiando uns anões Ferro Negro que se abancaram ao sul do Lago Helm. Não era boa coisa, aquilo, então eu e o Narm achamos bom fazer o reponte de perto... e nós conseguimos ver o líder dando ordem pros peões lá dele.$B$BNarm e eu aproveitamos a chance de matar uns, mas era uma pandilha mais chucra que crocolisco buzina, e os outros pularam na peleia também. O Narm disse pra eu riscar de lá e chamar reforço, e aqui estou eu.$B$BO Narm precisa de ajuda, e eu é que não vou alçar até mandar alguma.$B$BE tu? Pode ajudar, $n?", t = "Tomo da Divindade"},
    [1784] = {ot = "Obtenha uma Carta de Ferro Negro com os anões Ferro Negro perto do Lago Helm e fale novamente com Muiredon Beloforja em Altaforja.", st = "Antes de eu tombar em batalha, Muiredon e eu havíamos quase derrotado um dos espiões Ferro Negro perto daquela casinhola. Flagramos o capitão entregando as ordens para eles, e tentamos matar o espião para pegá-las.$B$BParte do conselho de Altaforja ainda não acredita que há anões Ferro Negro em Dun Morogh. Obtendo uma dessas cartas nós não só teremos provas dessas movimentações, mas também quem sabe uma ideia do que eles estão planejando.$B$BConsiga uma daquelas cartas e leve para o Muiredon, $n.", t = "Tomo da Divindade"},
    [1785] = {ot = "Fale com Tiza Beloforja em Altaforja.", st = "Dá pra ver que a esposa já está é ali, ó, mais orgulhosa que dona de carneiro premiado. Risca pra lá já, que eu acho que ela quer parar e pautear contigo.$B$BQue a Luz vá contigo, poderos$go:a; $c. Te espero no campo de batalha contra o Flagelo e os Ferro Negro quando chegar a hora.", t = "Tomo da Divindade"},
    [1786] = {ot = "Leve o Símbolo da Vida e ressuscite Henze Faulk em Elwynn.", st = "Henze e eu havíamos chegado à Vigia dos Heróis, uma ilha no meio do Lago do Monumento, no nordeste de Elwynn. Tínhamos ouvido que os Défias haviam se infiltrado no nosso território, e precisávamos de provas para levar aos conselheiros do rei.$B$BAvistamos um grupo de vermes lendo uns documentos e atacamos. Infelizmente fomos subjugados por magos que apareceram como reforço.$B$BHenze os segurou enquanto eu fugia... o idiota, resolvendo ser corajoso.$B$BE ele está lá ainda, o Henze. Você pode nos ajudar, $n?", t = "Tomo da Divindade"},
    [1787] = {ot = "Obtenha uma Carta de Défias dos Teurgos Proscritos em Elwynn e fale novamente com Gazin Tenorm em Ventobravo.", st = "Depois teremos tempo para falar mais sobre o Símbolo. Agora o importante é obter aqueles papéis que vimos com os Défias. Se conseguirmos pôr as mãos naquilo, poderemos provar que os Défias se infiltraram em Elwynn e, quem sabe, ter um vislumbre dos planos deles.$B$BNão estou em condições de lutar agora, $n. Você acha que é poderos$go:a; o suficiente para tomar os papéis dos Défias aqui na ilha?$B$BSe você conseguir, leve tudo para o Gazin e diga a ele que eu estou bem.", t = "Tomo da Divindade"},
    [1788] = {ot = "Fale com Benedito Brião em Ventobravo.", st = "Levarei as cartas aos conselheiros do rei depois que o Benedito tiver dado uma olhada nelas. Por enquanto, é melhor você falar com ele. Com certeza ele quererá parabenizá-l$go:a;.$B$BObrigado novamente, $n. Espero que nos encontremos de novo. Você é $gum aliado:uma aliada;, e eu me orgulho de tê-l$go:a; como amig$go:a;.", t = "Tomo da Divindade"},
    [1791] = {ot = "Fale com Bath'rah, o Vigia dos Ventos.", st = "Agora que aprendeu a postura berserker, você vai precisar de uma boa arma com a qual usá-la.$B$BFale com Bath'rah, o Vigia dos Ventos, um troll eremita que mora entre as Montanhas de Alterac e as Terras Pestilentas Ocidentais. Ele é um armeiro habilidoso, e um xamã poderoso.$B$BPara encontrar o Bath'rah, chegue ao rio que passa ao leste da Serraria Tarren e siga por ele para o norte. O Bath'rah acampa perto de umas ruínas na margem oriental.", t = "O vigia dos ventos"},
    [1793] = {t = "Tomo da Bravura"},
    [1818] = {ot = "Fale com o Necroguarda Dinis em Montalvo.", st = "Ouvi dizer que Necroguarda Dinis tem um trabalho para alguém como você. Se quiser provar o seu valor para s forças da Dama Sombria, procure Dinis agora mesmo.$B$BO posto do Necroguarda Dinis fica na ponta oeste de Montalvo, perto do cemitério.", t = "Uma conversa com Dinis"},
    [1819] = {ot = "Mate Ulag, o Cutelo, depois fale com Necroguarda Dinis.", st = "Quando o Flagelo varreu as Clareiras de Tirisfal, capturamos um deles para estudar. Ele era lúcido e se intitulava Ulag, o Cutelo. Mas embora a vontade dele não estivesse aprisionada, ele era escravo do Lich Rei.$B$BAinda tentamos romper o controle que o rei exercia sobre Ulag, mas falhamos. Agora finalmente chegou a hora de libertá-lo.$B$BLiberte Ulag e mate-o.$B$BAtive o gatilho de caveira de pedra perto do mausoléu mais ao norte. Isso vai romper o lacre mágico que o prende.$B$BE depois... esteja $Gpreparado:preparada;, $n.", t = "Ulag, o Cutelo"},
    [1820] = {ot = "Fale com Eurico Palhares.", st = "Você provou o seu valor para a Dama Sombria, agora que tal se provar para um dos súditos dela?$B$BEurico Palhares está à espera de alguém que queira ser o instrumento da vingança dele contra os inimigos dos Renegados.$B$BEle está na Taberna Nó da Forca, em Montalvo leste.", t = "Encontrando Eurico"},
    [1821] = {ot = "Leve para Eurico Palhares o Machado da Família Agamand, a Espada da Família Agamand, a Maça da Família Agamand e a adaga da Família Agamand.", st = "Quando vivo, eu trabalhava para a família Agamand e foi por causa deles que eu morri! Acho bem feito que eles tenham virado lacaios sem cérebro do Lich Rei.$B$BÉ justo que eu fique com os últimos vestígios de honra deles. Vá à cripta da família e roube as heranças deles: uma espada, um machado, uma adaga e uma maça. Traga tudo para mim!$B$BA cripta fica na extremidade norte dos moinhos dos Agamand, protegida por flagelos sorrateiros e pelos Agamand mortos.", t = "A herança dos Agamand"},
    [1822] = {t = "Meu ódio será sua herança"},
    [1823] = {ot = "Fale com Ruga Totem da Fúria.", st = "Você é $gum:uma; guerreir$go:a; de grande habilidade e fama crescente. Será que está pront$go:a; para a provação de Ruga Totem da Fúria? Se quiser arriscar, encontre Ruga no Acampamento Taurajo, nos Sertões.$B$BEle está sempre à espera de guerreiros que atendam chamado dele.", t = "Fale com Ruga"},
    [1824] = {ot = "Leve 5 antenas tremelicantes para Ruga Totem da Fúria no Acampamento Taurajo", st = "Para passar, você tem que viajar para o Campo dos Gigantes, ao sul. Lá, encontrará uma área apinhada de insetos. Chegaram há pouco tempo nos Sertões e a presença deles é um mau agouro.$B$BTraga para mim as antenas deles, ainda tremelicando, e vê se não perde tempo, $n, porque antenas arrancadas não tremelicam durante muito tempo. Traga as antenas dentro do tempo estipulado e você terá passado na provação.", t = "Provação no Campo dos Gigantes"},
    [1838] = {ot = "Leve para Thun'grim Olhafogo 15 Lingotes Fumegantes de Ferro, 10 Azuritas Pulverizadas, 10 Barras de Ferro e a Ampola de Flogisto.", st = "Já ouvi muitas lendas sobre a sua força e coragem e quero te dar de presente uma armadura, uma armadura que vai ajudar você a conquistar ainda mais feitos lendários.$B$BMas a própria construção da armadura já é um feito, $n. Preciso da sua ajuda e da ajuda de outros ferreiros da Horda.$B$BTome aqui esse pergaminho. Foram muitas as noites que passei lutando contra os meus olhos quase cegos para anotar o que preciso para fazer a armadura. Traga os itens deste pergaminho e eu farei a primeira peça da armadura.", t = "Armadura brutal"},
    [1858] = {ot = "Roube a chave de Tazan e use-a para abrir a Algibeira dele, levando o conteúdo para Therzok no Antro das Sombras, em Orgrimmar.", st = "Seu trabalho será abrir a algibeira de Tazan e trazer o conteúdo para mim. A tranca é um mecanismo muito complexo, então o mais fácil é arrumar a chave.$b$bComo não estava no cadáver de Tazan, só posso presumir que ele a deixou com outra... ah, sim, isso mesmo. Ele tinha um assistente chamado Gamon. É um beberrão de marca maior, então deve estar na taberna. Talvez você consiga tomar a chave dele na surdina.", t = "A Mão Despedaçada"},
    [1859] = {ot = "Fale com Therzok no Antro das Sombras em Orgrimmar.", st = "Fale baixo, $n. Sim, eu sei quem você é. Me disseram para ficar de olho vivo para $Gum:uma; orc com as suas características.$b$bPelo que dizem, você consegue se virar muito bem no combate e não se opõe a um pouco de gatunagem de tempos em tempos.$b$bNão é mesmo?$b$bEnfim, procure o Therzok em Orgrimmar. Ele tem uma oferta para você.", t = "Therzok"},
    [1860] = {ot = "Fale com Jana Catão em Ventobravo.", st = "Nós, magos, temos uma tarefa a cumprir. Uma tarefa vital para a segurança de Ventobravo e a floresta de Elwynn.$B$BJana Catão terá os detalhes. Ela estuda no sacrário dos teurgos, no distrito dos Magos de Ventobravo. Convém que você a procure o quanto antes.", t = "Fale com Jana"},
    [1879] = {ot = "Fale com Bink em Altaforja.", st = "$n! Bink, minha colega gnomida de Altaforja, mandou uma mensagem. Ela tem uma tarefa urgente é só confia em $gum mago:uma maga; para cumpri-la! Você é $gmago:maga;, $n?$B$BSe for, fale com a Bink. Ela costuma ficar no Salão dos Mistérios da Ala Mística de Altaforja.", t = "Fale com Bink"},
    [1881] = {ot = "Fale com Anastácia Cordato.", st = "$n, Anastácia Cordato tem uma tarefa perfeita para alguém com seus talentos. Fale com ela no Distrito da Magia da Cidade Baixa e se prepare para cumprir a primeira tarefa para os magos dos Renegados.", t = "Fale com Anastácia Cordato"},
    [1882] = {ot = "Traga Bocas-de-Leão de Balnir para Anastácia Cordato no Distrito dos Magos da Cidade Baixa.", st = "As Terras Pestilentas a leste são uma aberração. Criadas pelo Lich Rei, espalharam sua magia pelo solo, corrompendo e matando tudo que vive. Embora as forças destrutivas da peste tenham algum encanto, nós, os magos dos Renegados, acreditamos que ela é incontrolável e precisa ser restringida.$B$BAntes, porém, é preciso descobrir se ela já se espalhou muito por Tirisfal. Vá até a Fazenda dos Balnir, no leste em Tirisfal, recolha as bocas-de-leão do jardim e traga-as pra cá.", t = "A Fazenda dos Balnir"},
    [1885] = {ot = "Fale com Júnio Aquino no Distrito dos Ladinos da Cidade Baixa.", st = "$n? Não era bem o que eu estava esperando, em vista do interesse que o Aquino demonstrou. Mas, quem vê cara não vê coração, né?$b$bSeja como for, você precisa falar com ele o quanto antes. Se eu fosse você, nem iria querer saber o que aconteceu com quem não atendeu a convocação.", t = "Júnio Aquino"},
    [1886] = {ot = "Obtenha a Carta de Apresentação do Astolfo e leve até Júnio Aquino no Distrito dos Ladinos.", st = "Para fazer parte dos Sicários, a guarda de elite do Lorde Varimatras, você precisa mostrar seu valor.$b$bNão vou mentir, $n, esta missão pode ser fatal.$b$bTem algumas coisas que preciso resolver. Traga-me os dados pessoais de Astolfo Hadren, um mensageiro que circula entre Pinhaprata e a Cidade Baixa. Como você vai fazer isso é problema seu.$b$bMas é melhor que você não saiba mais nada sobre o motivo dessa missão. Se você for bem-sucedi:$go:a;, eu conto mais.", t = "Os Sicários"},
    [1898] = {ot = "Fale com Andron Gante na Cidade Baixa.", st = "A carta de apresentação deve bastar para convencer Andron de que você é o mensageiro que ele estava esperando. Já o encontrei antes, ele não tem capacidade mental para ser tão desconfiado.$b$bLorde Varimatras suspeita que Andron esteja ajudando algum outro grupo. Ele quer saber que organização é essa e precisa de provas da ajuda.$b$bQuero que você converse com Andron e obtenha essa informação. Ele deve estar em uma loja próxima ao Boticarium.", t = "Os Sicários"},
    [1899] = {ot = "Entregue o Livro-caixa de Astor a Júnio Aquino no Distrito dos Ladinos da Cidade Baixa.", st = "Você vai encontrar o livro-caixa com as informações que seus empregadores buscam na prateleira atrás de mim. Entregue-o com os meus cumprimentos e diga a eles que eu prefiro que mandem você, se acharem que o conteúdo vale a pena e quiserem prolongar nosso acordo.", t = "Os Sicários"},
    [1918] = {ot = "Entregue o Globo d'Água Conspurcado a Mastok Wrilehiss no Posto Machadada, no Vale Gris.", st = "O elemental morto libera um globo de água intensamente brilhante. O conteúdo do globo é, no mínimo, repulsivo. É certo supor que, seja lá o que for, o que corrompeu a água do Lago Mistral também esteja presente na água do globo.$B$BNão é muito fácil descobrir alguém que se interesse em um achado dessa natureza. Talvez a pessoa que mandou você para o lago, Mastok Wrilehiss, do Posto Machadada, tenha alguma ideia.", t = "O elemento conspurcado"},
    [1919] = {ot = "Fale com Jana Catão em Ventobravo.", st = "Você domina cada vez mais essa arte, jovem $n. Está pront$go:a; para começar a lição de verdade? Está pront$go:a; para tomar seu lugar na nossa guerra secreta?$B$BSe estiver, fale com Jana Catão que está no Sacrário dos Teurgos, no Distrito dos Magos de Ventobravo. Ela tem uma tarefa que pode lhe abrir a primeira janela para o mundo invisível.", t = "Jana tem uma missão"},
    [1920] = {ot = "Obtenha um Cantochão da Manifestação e um Baú de Cofres de Contenção atrás de Jana Catão. Leve 3 Cofres de Contenção Cheios para Jana no Sacrário dos Teurgos.", st = "Ouvimos relatos de um distúrbio na taberna Recôndito Azulego do Distrito dos Magos. É estranho, criaturas invisíveis estão perambulando pela taberna, e acho que uma fenda de mana se formou lá.$B$BQuero que você investigue a taberna e capture as criaturas. Use o cantochão da manifestação para tornar a criaturas visíveis, depois é só dominar e capturar em um cofre de contenção. Quando tiver bastante, volte aqui com os cofres cheios, os vazios e o cantochão.", t = "Investigue o Recôndito Azulego"},
    [1960] = {ot = "Obtenha um Cantochão da Manifestação e um Baú de Cofres de Contenção atrás de Anastácia Cordato. Traga 3 Cofres de Contenção Cheios, o Baú de Cofres de Contenção e o Cantochão da Manifestação para Anastácia na Cidade Baixa.", st = "A loja do alquimista de Algernon no Boticarium é foco de um estranho distúrbio. Criaturas invisíveis, feitas somente de magia, vagam pela loja. Deve haver alguma razão para isso, e precisamos descobrir qual!$B$BInvestigue o distúrbio e capture essas criaturas. Pegue um baú de cofres e um pergaminho atrás de mim. Use o pergaminho na loja para tornar as criaturas visíveis, domine-as com seus feitiços e depois lance um cofre para capturá-las. Retorne com os cofres cheios, os cofres vazios e o cantochão.", t = "Investigue a Loja de Alquimia"},
    [1961] = {ot = "Leve 10 Linhos e 6 Gemas de Mana de Dalaran para Josefo Gregório.", st = "Está na hora de envergar suas primeiras vestes de mag$go:a;, $n. Elas são um símbolo da sua posição e do seu valor.$B$BPara ganhar as vestes, você precisa reunir as gemas de mana dos magos de Dalaran em Pinhaprata. Eles têm crenças parecidas com as nossas, por isso, matá-los é algo desagradável, mas, se não têm força para resistir a nós, então não merecem as próprias vidas.$B$BLeve as gemas e um suprimento de linho para Josefo Gregório da loja de alfaiataria do Distrito da Magia.", t = "Em busca de materiais"},
    [1962] = {t = "Vestes de fogo místico"},
    [1963] = {ot = "Mate Tazan e leve a Algibeira dele para Therzok no Antro das Sombras, que fica em Orgrimmar.", st = "O Chefe Guerreiro é sutil demais em seus métodos. É cauteloso na hora de libertar a fúria da Horda. Já fomos mais fortes, todos grandes conquistadores. Orgulho precisamos reconquistar, isso que a Mão Despedaçada vai fazer.$b$bTiramos força das sombras e atacamos os expostos, matando os inimigos secretamente. Uma tarefa você precisa concluir para provar seu valor.$b$bO troll Tazan comercia com piratas perto da Vila Catraca. Ele tem informações de que preciso. Mate-o e me traga a algibeira dele.", t = "A Mão Despedaçada"},
    [1978] = {ot = "Entregue o Livro-caixa de Andron a Varimatras no Salão da Dama Sombria, que fica na Cidade Baixa.", st = "A Camarilha? Eu jamais suspeitaria. Parece que os lordes de Alterac entraram em decadência nos anos que se seguiram à traição.$b$bLorde Varimatras vai ficar feliz ao saber disso. Por ter sido essencial para essa descoberta, nada mais justo que você faça a entrega para ele.$b$bAh, quase que eu me esqueço!$b$b$gBem-vindo:Bem-vinda; aos Sicários.", t = "Os Sicários"},
    [1998] = {ot = "Mate Fernão Thatros e leve a cabeça dele para Júnio Aquino no Distrito dos Ladinos da Cidade Baixa.", st = "Lorde Varimatras acabou de me mandar uma carta sobre uma ameaça aos Renegados que precisa ser eliminada imediatamente. Seu nome é Fernão Thatros, que Lorde Varimatras acredita ser um líder dos mortos-vivos que fincou raízes na Floresta de Pinhaprata.$b$bPensei imediatamente em você, $n. Confio demais nas suas habilidades e sei que você vai cumprir essa missão sem erros.$b$bOs últimos relatórios dos Sicários de Pinhaprata indicam que Thatros pode ser encontrado na doca decrépita de Lordaeron.", t = "Fernão Thatros"},
    [2038] = {ot = "Encontre e devolva os suprimentos do Gomez:$B$BChave de Boca do Gomez, Chave de Fenda do Gomez, Martelo do Gomez e Detona-cuca do Gomez.", st = "Como se cair no Loch já não fosse ruim que chegasse, os troggs da ilha aqui perto me atacaram. Os cretinos roubaram as minhas ferramentas e meus explosivos detona-cuca ultraplosivos especiais. Sem girocóptero e sem explosivos, o movimento tá lascado!$B$BTraz minhas ferramentas de volta, e vê se acha meus detona-cucas, $n. Por Gnomeregan! ", t = "Os suprimentos desaparecidos do Gomez"},
    [2039] = {ot = "Encontre Gomez Plosivo em Loch Modan.", st = "Perdemos contato com o Bingles! Ele foi enviado para uma missão de reconhecimento em Gnomeregan e não manda notícias há mais de uma semana. Ele só pode ter se explodido.$B$BDa última vez que ele foi visto, estava sobrevoando o Loch. Você poderia investigar isso, $n?", t = "Cadê o Bingles?"},
    [2040] = {ot = "Recupere o Engrenotreco Gnomo das Minas Mortas e devolva a Shoni, a Shilenchiosa, em Ventobravo.", st = "Gnomeregan caiu e está sob o controle desses malditos troggs! A situação é grave, mas talvez você consiga ajudar, $n.$B$BNas profundezas das Minas Mortas tem um retalhador goblínico. Encontre esse retalhador e traga a fonte de energia intacta. Com ela, podemos fornecer a energia necessária para que nossos escavacionadores girobrocamáticos penetrem nas fronteiras rochosas submersas de Gnomeregan, abrindo caminho para um ataque gnômico!", t = "Ataque subterrâneo"},
    [2041] = {ot = "Fale com Shoni, a Shilenchiosa, em Ventobravo.", st = "Talvez você possa nos ajudar na batalha por Gnomeregan.$B$BEm Ventobravo você encontrará a comandante da nossa equipe de ataque subterrâneo, Shoni, a Shilenchiosa. Shoni precisa de ajuda com os escavacionadores girobrocamáticos dela.$B$BA comandante provavelmente está em meio aos anões de Ventobravo.$B$BBoa sorte, $n. ", t = "Fale com Shoni"},
    [2078] = {ot = "Encontre o Imediato de Gelkak e o Mangual-eliminator Pro Giramastro 4100, e leve-o de volta a Gelkak.", st = "Ô, marujo de água doce, vai procurar meu imediato.$B$BPega essa chave, enfia nele e traz de volta pra servir o capitão.$B$BQuero ver a alegria desses murlocs e do chefe do banco quando o meu imediato der conta deles!", t = "A revanche de Giramastro"},
    [2098] = {ot = "Encontre e devolva as três partes da Chave de Gelkak para Gelkak Giramastro.", st = "Vida de pirata não é mar de rosas, não, malhado. Não é só pilhagem e bebedeira! Meu navio afundou perto da praia por causa desses manguadontes dos infernos.$B$BPreciso do meu imediato aqui, pronto pro trabalho, imediatamente!$B$BQuando dei na praia, a chave para o meu imediato quebrou nas pedras e os bichos da Costa Negra afanaram. De rabo de olho vi murlocs, tiscorais furiosos e florestruzes furiosos remexendo nos destroços, aí quem ficou furioso fui eu...", t = "Uma mão para Giramastro"},
    [2118] = {ot = "Capture um ursocardo raivoso e traga de volta para Tharnariun.$B$BSe não conseguir capturar um ursocardo raivoso e perder a armadilha, fale novamente com Tharnariun Tratárvore e solicite outra.", st = "Uma doença se espalha pela Costa Negra, dominando as mentes e os corpos de todos aqueles que toca.$B$BOs ursocardos foram as piores vítimas dessa peste. As outrora nobres feras são agora um instrumento de destruição: raivosos e enlouquecidos. Talvez eu tenha a cura para esse mal.$B$BLeve esta armadilha para a floresta e coloque no chão. Qualquer ursocardo raivoso que cruzar a luz vai ficar dócil por algum tempo. Quando isso acontecer, ele vai seguir você. Traga até aqui, $n.", t = "Terras pestilentas"},
    [2138] = {ot = "Purifique a floresta matando 20 Ursocardos Raivosos e fale novamente com Tharnariun Tratárvore na Costa Negra.", st = "Como temi, a cura não funciona.$B$BÉ com grande tristeza que ordeno o abate de qualquer fera da natureza, mas os ursocardos doentes e maculados precisam ser mortos.$B$BVolte à floresta e execute vinte ursocardos raivosos, $n. Com certeza eu não vou conseguir acabar com a peste, mas pelo menos posso reduzir os danos que os animais estão causando à floresta e a seus habitantes no curto prazo.", t = "Purificação dos infectados"},
    [2139] = {ot = "Encontre e mate a Matriarca do Covil.", st = "A sobrevivência do nosso povo e de nossas terras vai ter um custo alto, $n.\n\nVocê derramou o sangue de servos da natureza, e muitos animais doentes foram abatidos. O povo de Auberdine tem uma dívida com você, pois a dor da floresta foi amenizada, mesmo que só por um momento.\n\nTenho uma tarefa final para você, e será preciso matar de novo. Espero que seja a última vez que lhe peço para fazer isso, $n.\n\nEm uma caverna a nordeste, perto de Bashal'Aran, mora a Matriarca do Covil. Acabe com ela.", t = "Esperança de Tharnariun"},
    [2158] = {ot = "Fale com o Estalajadeiro Fábio na Estalagem do Leão Orgulhoso.", st = "Todo aventureiro deve descansar quando bate o cansaço. E não há lugar melhor para repousar e relaxar do que a Estalagem do Leão Orgulhoso!$B$BMeu melhor amigo, o estalajadeiro Fábio, é o dono da estalagem. Se você disser que foi indicação minha, ele pode te dar descontos especiais na comida e na bebida.$B$BA Estalagem do Leão Orgulhoso fica pro sul, seguindo a estrada. Não dá pra errar!", t = "Repouso e relaxamento"},
    [2159] = {ot = "Leve a Entrega para Dolanaar para o Estalajadeiro Keldamyr.", st = "Saudações, jovem $c. Poderia me ajudar? Tenho um pacote de plantas para ser entregue na cidade de Dolanaar. Infelizmente, ainda tenho assuntos a tratar com os druidas de Umbravale e não posso ir até lá.$B$BPoderia levá-lo para mim? Deve ser entregue ao estalajadeiro Keldamyr na estalagem de Dolanaar. Pegue a estrada que segue para o sul.", t = "Entrega para Dolanaar"},
    [2160] = {ot = "Entregue um Caixote com Provisões para Estalagem a Tannok Marrãogélido, em Kharanos.", st = "Ei! Você parece ser $gum aventureiro:uma aventureira; forte. Se estiver planejando enfrentar a passagem, será que você poderia levar um pacote até a estalagem em Kharanos?$b$bJá estava nos seus planos parar na estalagem, não estava? Se você conseguir atravessar a passagem, com certeza, vai querer se recompor lá.$b$bDe qualquer forma, leve isto para Tannok Marrãogélido, o assistente da estalagem. Eu não consigo atravessar a passagem sozinho, e vai levar dias para uma escolta de montanheiros passar por aqui!", t = "Suprimentos para Tannok"},
    [2161] = {ot = "Leve o Fardo de Ulkor para o Estalajadeiro Grosk no Monte Navalha.", st = "Com licença! Você pode me ajudar?$B$BEu tenho um carregamento de comida aqui. Eu caminhei pela estrada e enfrentei escorpídeos, aranhas e coisas piores! Eu trouxe comida ao Vale das Provações porque imaginei que precisassem dela lá e resolvi ajudar. Mas eles não precisam de comida! Agora eu tenho que levar isto de volta para o Monte Navalha e estou com medo de todos aqueles monstros no caminho...$B$BVocê pode fazer isso por mim? Eu sou só um peão, mas você é $gum herói:uma heroína. Você nada teme!$B$BLeve isto para o Estalajadeiro Grosk, na estalagem do Monte Navalha. Obrigado!", t = "O fardo de um peão"},
    [2178] = {ot = "Leve 5 porções de Carne de Moa para Alanndária Noturcanto, em Auberdine.", st = "Está sentindo esse aroma delicioso? É a minha receita secreta, $n: ensopado de moa fresca. Delícia!$B$BVocê gostaria de aprender a receita?$B$BAntes de lhe ensinar a receita, quero que você prove que consegue enfrentar aquelas feras.$B$BAgora, eu não espero que você vá até lá, dome uma e volte cavalgando ela até mim, mas se você conseguir matar algumas e trazer um pouco da carne suculenta delas, posso me sentir persuadido a lhe mostrar como preparar o ensopado de moa.", t = "Moa a quem moer"},
    [2205] = {ot = "Entregue o pacote de Anabela Cabreira para o mestre Mathias Shaw nos Quartel de Ventobravo.", st = "O distintivo? Ah, nem esquenta... Você não ia dar conta mesmo. Olhando assim, o Mathias vai acabar achando que você é $Go entregador:a entregadora; de queijos, e não $Gum ladino:uma ladina; de verdade. Enfim, eles me deram uma tarefa, e eu prometi cumprir.$B$BSem delongas: entregue esse pacote ao Mathias, que ele deve arrumar uns trabalhinhos para você.$B$BAnda... circulando. \n", t = "Em busca da AVIN"},
    [2218] = {ot = "Fale com Hulfdan Barbanegra em Altaforja.", st = "Outra alma em busca de orientação? Aposto que está procurando um propósito... o seu propósito. Já vi essa história um milhões de vezes; mais um herói querendo trabalho.$B$BSeus problemas acabaram, $Gguri:guria;! O Hogral aqui tem a solução.$B$BPois bem, tu vais subir essa estrada até Altaforja e entrar na Caverna Esquecida. Lá dentro, quero que encontre a Guilda dos Ladrões e fale com Hulfdan Barbanegra. Ele vai te mostrar a estrada da salvação.\n", t = "Estrada para a salvação"},
    [2241] = {ot = "Leve a flor de Jannok para Syurna em Darnassus.", st = "Dizem que estou \"apaixonado\", seja lá o que isso signifique.$B$BClaro, passo cada segundo pensando em Syurna. Claro, minha casa está cheia de quadros e desenhos de Syurna. Claro, muitas vezes passo dias sem comer, dormir ou beber, enquanto lamento sobre o amor que poderíamos ter. Qual é o problema nisso?$B$BAgora ela não quer me ver! A MIM! Eu tentei mandar mensagens para ela, mas ela não quer falar com ninguém, a menos que seja um ladino.$B$BVocê poderia entregar esta flor para ela? Não se esqueça de dizer a ela que é de Jannok.", t = "Amor só dura em liberdade"},
    [2242] = {ot = "Encontre Sethir, o Antigo, e leve qualquer pista a respeito de Syurna.\n", st = "Acreditamos que haja um ser que possa nos ajudar a compreender o que está acontecendo nas florestas de Teldrassil. Infelizmente, foi desastroso quando tentamos convencê-lo a nos ajudar.$B$BEle se esconde em um dos galhos na beirada da Clareira do Oráculo. Todos que tentaram se aproximar do sátiro, tanto por força quanto por diplomacia, tiveram um triste fim. Talvez furtividade seja a solução, $n.$B$BDescubra o que Sethir, o Antigo, carrega nos bolsos e depois volte aqui.\n", t = "O destino chama"},
    [2281] = {ot = "Vá até a Vila Plácida, nas Montanhas Cristarrubra, e fale com Lucius.\n", st = "Mandar você para campo agora seria suicídio. Renzik não precisa de mais $Gum ladino morto:uma ladina morta; nas mãos. Mas não se preocupe, $n — Renzik vai te deixar a par de tudo.$B$BVá até as Montanhas Cristarrubra e fale com um associado da AVIN chamado Lucius. Você vai encontrá-lo nas docas da Vila Plácida com os outros imprestáveis.", t = "Encontro em Cristarrubra"},
    [2282] = {ot = "Abra o Baú do Lucius, recupere o Símbolo de Ladroagem e devolva-o ao Lucius na Vila Plácida.", st = "Nós treinamos ladrões aqui há anos! Afinal, nem todo larápio nasce com a graça e finesse do velho Lucius.$B$BSubindo por fora da estrada aqui, você vai encontrar a Serraria Alther. Eu deixei um baú lá com uma coisa importante dentro. Vá lá buscá-lo para mim! Traga-me aquele símbolo e eu lhe darei o Certificado de Ladroagem!", t = "Serraria Alther"},
    [2298] = {ot = "Viaje para Ventobravo e procure Renzik, \"O Bicudo\".", st = "Daí a gente tava lá, caraminholando a fase três, quando alguns brutamontes do Magni chegaram se intrometendo, falando de algum assalto e prendendo um pessoal do Círculo Oculto.$B$BOra, ninguém algema o velho Barbanegra! O bate-boca esquentou e deixaram escapar o teu nome!$B$BQuer um conselho? Pega o primeiro grifo pra fora de Altaforja e te pica pra Ventobravo. Vai pra Cidade Velha e, chegando lá, fala com um velho amigo meu, Renzik, \"O Bicudo\".", t = "Aperto régio"},
    [2359] = {ot = "Roube a chave, entre na Torre Défias e descubra o que tem dentro do Baú da Floresta do Crepúsculo. Leve todas as informações que coletar para Mathias Shaw em Ventobravo. Consulte o Diário de Marta se quiser mais detalhes sobre a torre.\n", st = "Eu tenho vigiado esta torre há semanas, $n. Recentemente, uma grande remessa chegou da Floresta do Crepúsculo e, junto com ela, vieram aqueles guardas.$B$BO que são eles? Eu sei tanto quanto você. Mas posso lhe assegurar uma coisa: eles não são humanos.$B$BDe qualquer forma, o carregamento tinha um baú — que é o que eu presumo que essas abominações estão guardando. O zumbi com espinhos está coma a chave de que precisamos.$B$BPegue aquela chave, entre na torre e descubra o que tem naquele baú. Leve suas descobertas ao Mathias.", t = "Torre do Filipe"},
    [2360] = {ot = "Viaje para Cerro Oeste e encontre a Agente Marta Hari para receber instruções.", st = "Até que enfim, $n. O reconhecimento da AVIN relata atividade particularmente pesada dos Défias em Cerro Oeste.$B$BAparentemente, os Défias ocuparam uma torre de vigia abandonada da Aliança a sudeste do Morro da Sentinela, e a usam como base das operações de recepção de contrabando da rota de suprimentos da Cristarrubra.$B$BVá até Cerro Oeste e fale com a Agente Marta Hari para receber mais instruções. Ela está escondida perto da torre.$B$BE, $n, caso descubram sua presença, a AVIN negará ter conhecimento da sua existência. ", t = "Mathias e os Défias"},
    [2378] = {ot = "Vá até Orgrimmar e fale com Shenthul no Antro das Sombras.\n", st = "Você tem sido de muita serventia aos Sicários, $n, mas talvez esteja na hora de seguir em frente. Embora seja $Gtalentoso:talentosa; nos quesitos furtividade e enganação, você ainda precisa de muito treino.$B$BOs Sicários têm aliados na Mão Despedaçada. Vá atrás daqueles dispostos a nos ajudar. Fale com Shenthul em Orgrimmar.\n", t = "Encontre a Mão Despedaçada"},
    [2379] = {ot = "Fale com Zando'zan no Antro das Sombras.", st = "A sua determinação não é o bastante para superar os obstáculos à nossa frente.$B$BFale com Zando'zan para começar o treinamento como agente da Mão Despedaçada.$B$BSó depois de dominar as artes da furtividade e da ladroagem, você poderá dar os próximos passos rumo ao seu destino.\n", t = "Zando'zan"},
    [2381] = {ot = "Leve o Tesouro dos Mares do Sul para Wrenix, o Ignóbil, na Vila Catraca. Não se esqueça de pegar um B.E.C.A. e as Ferramentas de Ladrões no Aparato Mercadotrônico do Wrenix. Você precisará desses dois itens para cumprir a missão.$B$BCaso seja atacado por papagaios nada amigáveis, use o B.E.C.A!\n\n", st = "Sem querer te assustar, $n, os últimos cinco ladinos que tentaram roubar o tesouro voltaram em pedacinhos.$B$BAtracado no sul da costa está o Lâmina das Marés, o navio dos flibusteiros, que guarda o tesouro dos Mares do Sul. No piso inferior fica o covil dos piratas, onde eles treinam todos os ladrões.$B$BSuba a bordo do navio, roube o tesouro e traga-o para mim. Use o covil dos piratas se precisar treinar suas técnicas de ladroagem, mas tome cuidado!\n", t = "Saqueando os saqueadores"},
    [2382] = {ot = "Viaje para a Vila Catraca e fale com Wrenix, o Ignóbil.", st = "Zando'zan viu, sim! O dia vai chegar! A morte de Thrall... A adaga nas costas, o veneno correndo nas veias dele... Zando'zan já falou demais.$B$B$n! Zando'zan tem tarefa para $n! $n tem que ir à Vila Catraca, a leste da Encruzilhada, e falar com Wrenix, o Ignóbil. Anda! Vai logo!\n", t = "Wrenix da Vila Catraca"},
    [2383] = {ot = "Leia o Pergaminho Simples e fale com Frang no Vale das Provações.", st = "Ah, enquanto você estava fora, chegou um pergaminho para você, $n.$B$BLeia quando tiver tempo. Se não me engano, é do instrutor de guerreiros Frang. Ele quer falar com você assim que você estiver $gpronto:pronta;. Ele fica na entrada do Covil, protegido na sombra.", t = "Pergaminho simples"},
    [2399] = {t = "As frondes desenvolvidas"},
    [2438] = {ot = "Leve o Apanhador de Sonhos de Esmeralda para Tallonkai Radicélere em Dolanaar.", st = "Certa vez, Garyol Talvethren, guardião dos druidas na Gruta de Ban'ethil, me presenteou com um apanhador de sonhos de esmeralda. Este poderoso amuleto é capaz de canalizar a energia do Sonho Esmeralda, concedendo sorte a quem o possuir.$B$BInfelizmente, não consegui recuperá-lo de meu armário no Vilarejo Brisastral... Embora Brisastral já tenha sido um lugar tranquilo, hoje sucumbe à corrupção dos pelursos que lá vivem.$B$BPoderia me ajudar a recuperar meu apanhador de sonhos, $c?", t = "O apanhador de sonhos de esmeralda"},
    [2458] = {ot = "Vá à Torre da Empreendimentos S.A., ao norte do Charco de Lodo, e entre em contato com o agente secreto da Mão Despedaçada, o Capataz Arruela.$B$BQuando a torre estiver à vista, use o Sinalizador para anunciar sua chegada ao Capataz Arruela. Dispare DUAS vezes, depois aproxime-se do Capataz e faça a /continencia dos Mão Despedaçada.$B$BEstas ações devem ser executadas na ordem correta, já que Arruela vai atacar e eliminar qualquer pessoa que não reconheça.", st = "A Empreendimentos S.A.... Já ouviu falar deles?$B$BPor um ano inteiro nós fizemos de tudo para infiltrar um agente lá dentro. Depois de muito esforço e planejamento, nós conseguimos.$B$BRecentemente, ficamos sabendo que a Empreendimentos S.A. está tramando alguma coisa em grande escala. Vá para o norte do Charco de Lodo, até a torre deles, e entre em contato com o nosso agente infiltrado, o Capataz Arruela.$B$BQuando encontrar a torre, dispare este sinalizador, aborde o Arruela e bata a continência da Mão Despedaçada.\n", t = "Missão secreta"},
    [2459] = {ot = "Tallonkai Radicélere, em Dolanaar, quer que você mate 7 Místicos Masca-pinho e encontre a Joia Roubada.", st = "A esmeralda... desapareceu! Meu apanhador de sonhos foi danificado!$B$BExiste um bando de místicos Masca-pinho ao norte de Brisastral. Ouvi relatos de que o líder deles, Ferócitas, o Comedor de Sonhos, está usando um colar que emite um brilho verde à noite. E agora, vendo o que aconteceu com o meu apanhador de sonhos, tenho certeza de que ele roubou minha esmeralda... Ferócitas nunca entenderá que o poder da pedra é inútil para ele.$B$BEncontre a joia roubada, $n. E, quando estiver lá, aproveite para acabar com alguns místicos corrompidos.", t = "Ferócitas, o Comedor de Sonhos"},
    [2460] = {ot = "Faça a Continência dos Mãos Despedaçada para Shenthul.", st = "Como um ladino da Mão Despedaçada, é imperativo que você aprenda a Continência dos Mãos Despedaçada. É a única maneira de realmente identificar outro membro da Mão.$B$BObserve, aprenda, repita.", t = "A saudação dos Mão Despedaçada"},
    [2478] = {ot = "Roube a Chave da Torre do Capataz Biela e, em seguida, mate 2 Peões Mutantes da Empreendimentos S.A., 2 Patrulheiros da Empreendimentos S.A. e 2 Vigias da Empreendimentos S.A.$B$BArranque a cabeça do Capataz-chefe Gallywix, arrombe o cofre dele e roube o Esconderijo do Preparado Adulterado do Zanzil. Leve-o junto com a cabeça para Shenthul em Orgrimmar para receber mais instruções.\n", st = "Você precisará roubar a chave da torre do Capataz Biela, $n. Quando consegui-la, guarde bem... posso precisar dela mais tarde.$B$BLembre-se, o veneno enfraqueceu tudo nesta torre. Use suas habilidades para trazer o caos e a destruição aos moradores. Mate todos eles — não tenha piedade!$B$BAssim que terminar o derramamento de sangue no interior da torre, pegue o cofre de Gallywix e roube o estoque do Preparado de Zanzil guardada lá dentro. Leve a cabeça de Gallywix e a mistura para Shenthul, em Orgrimmar.", t = "Missão: possível, mas não provável"},
    [2479] = {ot = "Vá até a Serraria Tarren, que fica no Contraforte de Eira dos Montes, e entregue a Amostra do Preparado de Zanzil a Serguei Hinoto.$B$BPara chegar à Serraria Tarren, pegue o Zepelim até a Cidade Baixa e siga a estrada em direção ao sul além de Pinhaprata, rumo à Eira dos Montes. É só seguir as placas!\n\n", st = "Leva uma amostra dessa mistura pro Serguei Hinoto, na Serraria Tarren.$B$BVou falar, cara, se alguém pode curar você, é o Serguei. E se tu viver o suficiente, o Serguei pode até te mostrar as manhas de como criar e usar os venenos.", t = "A ajuda de Hinoto"},
    [2480] = {ot = "Espere Serguei Hinoto concluir a cura.", st = "Nunca vi um veneno trazer resultados tão formidáveis! Zanzil, não é mesmo? Nunca ouvi falar dele, no entanto, devo louvá-lo pela criação desta mistura.$B$BEntão, devo curá-l$Go:a; disso e depois ensiná-l$Go:a; a usar o veneno?$B$BDê-me alguns instantes para examinar a toxina, $n.", t = "A ajuda de Hinoto"},
    [2498] = {ot = "Rellian Spiraverde quer que você fale com Denalan, no Lago Al'Ameth.", st = "Acabo de receber a notícia de que Denalan, no Lago Al'Ameth, descobriu o que pode ser a causa dos tumores que afligem os muscoides. Por favor, fale com ele e diga-lhe que $Go:a; enviei.$B$BAnde logo, $n: ele precisa da nossa ajuda.", t = "Fale com Denalan"},
    [2499] = {ot = "Denalan, no Lago Al'Ameth, quer que você remova o Tumor Gigantesco de Carrancarvalho.", st = "Em uma caverna à margem sul do lago, um muscoide chamado Carrancarvalho está espalhando a corrupção para todas as criaturas que fazem do Lago Al'Ameth seu lar.$B$BNão ousei me aproximar demais, mas, mesmo à distância, é óbvio: Carrancarvalho está sendo envenenado pelo maior tumor que já vi... gigantesco, até.$B$B$n, você já fez muito pela minha causa, mas lhe peço mais um favor. Vá atrás de Carrancarvalho e remova o tumor. Elimine essa fonte de corrupção do meu lar.", t = "Carrancarvalho"},
    [2518] = {ot = "A Sacerdotisa A'mura no Templo da Lua, em Darnassus, quer que você lhe traga as Fiandeiras Prateadas de Lady Sathrah.", st = "Lady Sathrah já foi amada por Eluna. Graciosa e pura, a aranha tecia seus fios prateados sob a luz da lua, capturando a bruma da noite. O orvalho prateado possuía fortes poderes curativos e costumava ser guardado aqui no templo.$B$BMas, nos últimos tempos, Sathrah sucumbiu à loucura, ameaçando também suas gerações futuras.$B$BEncontre Lady Sathrah, $n, e acabe com o sofrimento dela. Ela vive na fronteira norte de Teldrassil, perto do Lago Olho-d'Água. Pegue as fiandeiras prateadas dela e traga-as para mim.", t = "Lágrima da Lua"},
    [2519] = {ot = "Irmã Aquinne quer que você fale com a Sacerdotisa A'mura no Templo da Lua.", st = "Uma criatura outrora grandiosa da floresta precisa de ajuda, $r.$B$BUma difícil tarefa precisa ser cumprida.$B$BProcure a Sacerdotisa A'mura, ela lhe explicará tudo. Encontre-a a sudeste daqui, dentro do Templo da Lua.", t = "O Templo da Lua"},
    [2520] = {ot = "A Sacerdotisa A'mura quer que você coloque as fiandeiras prateadas de Lady Sathrah na fonte dentro do templo, e depois fale novamente com ela.", st = "Agora você deve concluir a tarefa para a qual foi designad$Go:a;. Leve as fiandeiras e ofereça o sacrifício de Lady Sathrah à Eluna. Faça com que a grande aranha encontre seu descanso final.$B$BEncontre a fonte central dentro deste templo. É onde você deve deixar o sacrifício. As águas sagradas vão purificar e limpar a corrupção que enlouqueceu Sathrah.$B$BQuando terminar, fale novamente comigo.", t = "Sacrifício de Sathrah"},
    [2541] = {ot = "Traga o Patuá Vodu de Xamã para Oben Patafúria na Gruta de Ban'ethil.", st = "Os xamãs Masca-pinho que habitam este lugar descobriram um jeito de separar o espírito de um druida adormecido do corpo físico dele. Os pelursos reanimaram meu corpo e estão usando-o para atacar qualquer um que tente explorar a Gruta de Ban'ethil. Agora estou preso no Sonho Esmeralda, incapaz de impedir isso.$B$BVocê precisa me ajudar. Os xamãs Masca-pinho carregam um estranho patuá que usam para realizar este ritual. Gostaria de examiná-lo. Por favor, $n, traga um para mim.", t = "O druida adormecido"},
    [2561] = {ot = "Oben Patafúria quer que você mate seu corpo sem alma e, em seguida, use o Patuá Vodu.", st = "Após examinar este patuá, $n, descobri o que precisa ser feito. Por favor, pegue-o e faça o que eu disser.$B$BVocê deve explorar as áreas mais profundas da Gruta de Ban'ethil. Lá dentro, você encontrará meu corpo sem alma... Lamento muito pelo que vou lhe pedir, mas não vejo outra maneira de me libertar do controle dos Masca-pinho.$B$BPara que eu possa escapar deles, você terá de matar minha forma física e usar o Patuá Vodu em meu corpo inerte. Após completar esta tarefa, fale novamente comigo.", t = "Druida da Garra"},
    [2607] = {ot = "Fale com o Doutor Mixilpixil no porão do Quartel.", st = "Parece que você trouxe muito mais informações do que eu esperava. De fato, é uma reviravolta peculiar, $n.$B$BUma cura? Hm... vá até o porão e fale com o Doutor Mixilpixil, talvez ele possa ajudar.", t = "O toque de Zanzil"},
    [2608] = {ot = "Você precisa /deitar para ser $Gexaminado:examinada; pelo Doutor Mixilpixil. Como é que ele vai descobrir a cura se não puder identificar a causa do problema?\n", st = "Carambola, você está a cara da morte. Correção: eu já vi a morte, você está ainda pior. Você, mocinh$Go:a;, seria algo que a morte escarraria no derradeiro exame médico.$B$BRá! Ouviu essa, Quilo? Pois trate de anotar essa!$B$B*Tosse* Hm, sim, posso te ajudar, mas primeiro preciso coletar seu sangue. Não se preocupe, só dói nas primeiras... cinquenta vezes... $n, quando estiver pront$go:a; para o tratamento, é só deitar.", t = "O toque de Zanzil"},
    [2609] = {ot = "Leve para o Doutor Mixilpixil um pacote de Flores Silvestres Simples, uma Ampola Chumbada, um Tubo de Bronze e uma Bobina de Seda Chartreuse Leve. \"Ite\" nenhuma se cura sozinha, $Gmeu:minha; jovem. ", st = "É unânime, $n. Você está com \"ite\".$B$BPor sorte, eu conheço a cura para \"ite\".$B$BEu preciso de umas coisinhas: um ramalhete de flores silvestres simples, uma ampola chumbada, um tubo de bronze e por último, mas não menos importante, uma bobina de seda chartreuse leve. A Tia Bia deixou um rolo para mim no Ao Fio d'Ouro. A loja fica na margem dos canais.$B$BEntão vá logo, bem depressinha, $n, e tente não encostar em ninguém até se curar. Ah, e o dr. Monteiro disse que você está precisando de um banho... ele que disse, estou só passando o recado!", t = "O toque de Zanzil"},
    [2745] = {ot = "Fale com Tyrion no Castelo Ventobravo.", st = "Hum, uma história interessante, que deve ser levada a sério. Sim, eu posso ajudar, mas o que você precisa fazer é aplicar uma forma de justiça que seja... ilegal, se quiser chegar ao fim de tudo isso.$B$BLescovar e Marzon precisam ser derrotados rapidamente. Você acha que consegue?$B$BA decisão é sua. Se acha que sim, corra para o castelo e encontre um velho amigo meu, um gnomo chamado Tyrion. Ele está vigiando Lescovar há algumas semanas e deve conseguir ajudar você a dar um fim nisso.", t = "Infiltrando-se no castelo"},
    [2746] = {ot = "Leve 3 Sedas e 2 Maçãs Frescas da Clara para Tyrion em Ventobravo.", st = "Trias está apressando as coisas, hein? Certo, nós podemos fazer isso, mas ainda não estou pronto. Fique sabendo de uma coisa, estou encarregado da parte mais difícil, mas é você que vai ter que sujar as mãos, entendido? Muito bem.$B$BPreciso que você me traga algumas coisas antes de dar início ao meu plano. Consegui o disfarce perfeito que vai fazer o robô-espião passar pelos guardas.$B$BTraga seda e maçãs para mim. Você se vira para conseguir a seda, mas a fazendinha da Clara, que fica logo após a saída da cidade, tem maçãs do tamanho perfeito.", t = "Itens de alguma consequência"},
    [2841] = {ot = "Pegue a Combinação do Cofre do Termaplugue e o Projeto de Mecatraje e leve-os para Nogg em Orgrimmar.\n", st = "Tecnologia gnômica. Dois anos atrás só era usada em piadas infames. Os tempos mudaram... Agora eles construíram um robô melhor que todos os nossos retalhadores juntos. Eu preciso do projeto, $n!$B$BO problema é que ele está trancado num cofre perto do Mecangenheiro Termaplugue. Pra piorar, só ele sabe a combinação!$B$BFaça o que for preciso para descobrir a combinação, $n. Depois abra o cofre e me traga aquele projeto!\n", t = "Guerra dos robôs"},
    [2842] = {ot = "Fale com Scooty na Angra do Butim.", st = "Assim que Kernobill nos alertou sobre a nova perfuratriz gnômica, Scooty e eu começamos a trabalhar no Transpoliportador 6000, a maneira mais rápida e confiável de chegar a Gnomeregan.$B$BFinalmente ele está pronto para o transporte de passageiros, $n. Se quiser experimentar, vá até Angra do Butim e fale com Scooty no ninho de mantícoras. Para chegar a Angra do Butim, pegue o barco que sai de Vila Catraca.$B$BSe preferir, você pode tentar correr até Gnomeregan passando pelas montanhas Dun Morogh, que estão infestadas de anões.", t = "Engenheiro-chefe Scooty"},
    [2843] = {ot = "Esperar até Scooty calibrar o Transponder Goblínico.", st = "Enquanto você estiver com o transponder, basta subir na plataforma para ser $Gteleportado:teleportada; até Gnomeregan.$B$BVocê corre o risco de sentir alguns efeitos colaterais, mas nada muito permanente... na teoria.$B$BEu já ia me esquecendo de algo muito importante: a volta. Quando quiser voltar, é só subir no transpoliportador lá em Gnomeregan!$B$BAgora, vamos calibrar o transponder com seu peso e altura.\n", t = "E lá vamos nós!"},
    [2904] = {ot = "Escolte Kernobill até a saída do Corredor dos Mecanismos, depois apresente-se a Scooty na Angra do Butim.", st = "<Kernobill solta um grunhido.> Quê... O que aconteceu?$B$BA última coisa de que me lembro foi ser capturado por um grupo de anões ferro negro, apanhar até ficar à beira da morte e depois ser jogado no meio desses troggs imundos.$B$BTire-me daqui, $n!$B$BO plano é o seguinte: é só me levar até a saída. Se escaparmos vivos, vá para a Angra do Butim e avise o Scooty que eu fui para a Vila Catraca, alertar o Guariba de que os Ferro Negro estão envolvidos no surgimento da superbroca.$B$BVamos logo!", t = "Uma bela bagunça"},
    [2922] = {ot = "Leve o Núcleo de Memória do Tecnobô para o Mestre-faz-tudo Superchispa em Altaforja.", st = "Quando nossa amada cidade de Gnomeregan sucumbiu, minha pobre criação, o Tecnobô, deve ter sofrido um curto do mal. Ele ajudava a mim e aos meus parceiros com artifícios incontáveis e um banco de dados sem limites, porém seu cérebro positrônico polarizou. Ficou negatrônico... e o comportamento do Tecnobô se inverteu. Ele vaga por Gnomeregan em frenesi!$B$BMas talvez seja possível reciclá-lo. Se você trouxer o núcleo de memória dele, eu posso descobrir qual foi a causa da polarização e consertar meu pobre Tecnobô.$B$B", t = "Salve o cérebro do Tecnobô!"},
    [2923] = {ot = "Fale com o Mestre-faz-tudo Superchispa em Altaforja.", st = "O Mestre-faz-tudo Superchispa ficou muito chateado com o fim que teve sua criação mecânica, o Tecnobô. Eu me lembro de que era muito útil para os gnomos, mas o Mestre-faz-tudo me disse que ele estragou.$B$BQue coisa triste. Mas talvez seja possível consertá-lo!$B$BFale com o Mestre-faz-tudo Superchispa no Beco da Gambiarra, lá em Altaforja. Ele ficará agradecido pela ajuda.", t = "Mestre-faz-tudo Superchispa"},
    [2924] = {ot = "Leve 12 Artifícios Essenciais para Cronomorfus Espanafuso em Altaforja.", st = "Um componente mecânico praticamente universal, o artifício essencial, foi de grande valia para os faz-tudo e ferreiros de Gnomeregan. Mas na pressa do êxodo, ninguém se lembrou de trazer nenhuma dessas peças! E eu vou precisar de um estoque para o projeto que vou iniciar logo, logo.$B$BPor favor, vá buscar um punhado de artifícios essenciais para mim em Gnomeregan. Eles ficam nas partes mais profundas da cidade, guardados em extrapoladores artificiais.$B$BMuito obrigado, $n, só peço que não demore!", t = "Artifícios Essenciais"},
    [2926] = {ot = "Use o Coletor de Chumbo Vazio nos Invasores Irradiados ou nos Pilhadores Irradiados para recolher resíduos radioativos. Depois que ele ficar cheio, leve-o de volta para Ozzie Mudavolt em Kharanos.", st = "Desde o acidente, Gnoarn só fala em livrar Gnomeregan da infestação trogg e em descobrir a cura para a doença que aflige a cidade, $n.$B$BPor sorte, eu e o Razzle estamos perto de descobrir a cura... Se não é a cura, é uma receita forte para caramba de rum. Só vamos saber depois de testar! Mas para testar nossa teoria, vamos precisar de algumas coisinhas naturalmente. A saber: resíduos radioativos dos troggs em Gnomeregan. Traga-me esse coletor cheio de brilho verde!", t = "Gnogaína"},
    [2927] = {ot = "Fale com Ozzie Mudavolt em Kharanos.", st = "Você não achou que eu tivesse nascido careca, não é? Não, senho$Gr:ra;! Foi o vazamento de radiação em Gnomeregan que provocou essa tragédia capilar. Antes daquilo, eu tinha o único gnomafro de toda Azeroth.$B$B<Gnoarn ergue o punho cerrado no ar.>$B$BMalditos sejam aqueles troggs imundos... malditos sejam!$B$BTalvez ainda não seja tarde demais, $n. Talvez ainda seja possível reverter a situação... da cidade, digo! Fale com Ozzie Mudavolt em Kharanos. Ele e seu parceiro Razzle estão bolando uma solução para o problema.", t = "O dia seguinte"},
    [2928] = {ot = "Leve 24 Tripas Mecanobóticas para Shoni em Ventobravo.", st = "Que tragédia, $n! Não vamos ter peças suficientes para levarmos nossa frota de escavacionadores girobrocamáticos até Dun Morogh.$B$BPrecisamos de peças de reposição, $n. E sabe onde tem um monte delas? Lá em Gnomeregan! Fiquei sabendo que mecas vagueiam por lá como se fossem gado no pasto.$B$BEu preciso que você vá até Gnomeregan, desmanche esses mecas e me traga suas entranhas robóticas. Duas dúzias devem bastar.\n", t = "Escavacionadores girobrocamáticos"},
    [2929] = {ot = "Vá para Gnomeregan e mate o Mecangenheiro Termaplugue. Fale novamente com o Grão-faz-tudo Mekkatorque depois que tiver terminado a tarefa.", st = "Eu confiava no Termaplugue, $r. Nunca imaginei que ele fosse trair a mim e a todo o povo gnômico. E a troco de quê? Poder? Riqueza? Coisas que ele conquistaria no devido tempo. Agora fomos retirados da nossa casa e aquele lunático ficou no comando. O rei de coisa nenhuma...$B$BNós retomaremos Gnomeregan, $n. Não vamos dar trégua enquanto não tivermos a cidade sob controle. Se quiser se juntar à luta, eu tenho uma tarefa bem simples para você: matar o traidor. Destruir o Mecangenheiro Termaplugue.", t = "A grande traição"},
    [2930] = {ot = "Leve o Cartão Perfurado Prismático para o Mestre Mecânico Fundecano em Altaforja.", st = "Quando fugimos de Gnomeregan, deixamos muitos dados para trás! Dados de importância vital!$B$BEu preciso de dados salvos em um cartão perfurado prismático, no terminal de segurança máxima da Matriz Perfuradora 3005-D, na Gnomeregan profunda. Você terá que acessar o terminal, mas vai precisar de permissão... e para obter permissão, vai precisar acessar os terminais de segurança mínima A, B e C. Mas PARA ISSO, vai precisar de uns cartões perfurados, a começar pelo branco... E nós deixamos todos os cartões perfurados na cidade.$B$BÉ uma catástrofe! Você pode ajudar?", t = "O resgate dos dados"},
    [2945] = {ot = "Descubra uma maneira de remover a crosta de sujeira do Anel Encardido.", st = "No cadáver de um dos anões Ferro Negro, você encontrou o que parece ser um anel. Mas é difícil dizer que tipo de anel, pois ele está completamente incrustado de sujeira e não é possível nem mesmo usá-lo. Examinando de perto, você percebe o brilho tênue de um metal valioso e o que parece ser uma pedra preciosa em meio à crosta de sujeira.$B$BSe você deseja restaurar e usar o anel, primeiro terá que achar uma maneira de limpá-lo.", t = "Anel Encardido"},
    [2947] = {ot = "Você pode ficar com o anel ou achar a pessoa que faz a gravação no interior dele.", st = "Ao abrir a caixa que saiu da Brastematic 5200, você encontra o que esperava: um anel limpo e brilhante! Colocando o anel no dedo, você sente um tremendo poder mágico correr pelo seu corpo.$B$BGravado na parte interior do anel, é possível ver o selo de Altaforja. Próximo ao selo, três iniciais estão gravadas: \"DdM\". Elas podem ser tanto as iniciais do antigo proprietário do anel quanto do próprio criador dele. Ficar com o anel ou entregá-lo ao dono... eis a questão! Decisões, decisões...", t = "Ficar ou não ficar... eis a questão!"},
    [2948] = {ot = "Entregue o Anel de Ouro Brilhante, uma Barra de Prata, uma Ágata Musgosa e 30 moedas de prata para Didiê Du Mocó, em Altaforja.", st = "Veja bem, $n, o anel é seu, é claro... Mas eu posso fazer um melhor ainda para você! Esse modelo de anel, como eu disse, é muito simples. Eu agora estou mais capacitado ainda, então, pela módica quantia de trinta moedas de ouro, posso dar uma guaribada no seu anel! Bem, por um pouco mais que trinta moedas, na verdade...$B$BEu estou meio apertado agora – meu estoque de matéria-prima está vazio. Se você me trouxer uma barra de prata e uma ágata musgosa, eu consigo fazer um arabesco que vai deixar o seu anel nos trinques!$B$BAguarde e confie!", t = "Aperfeiçoamento gnômico"},
    [2949] = {ot = "Você pode ficar com o anel ou achar a pessoa que faz a gravação no interior dele.", st = "Ao abrir a caixa que saiu da Brastematic 5200, você encontra o que esperava: um anel limpo e brilhante! Colocando o anel no dedo, você sente um tremendo poder mágico correr pelo seu corpo.$B$BGravado no interior do anel, é possível ver o selo de Orgrimmar. Próximo ao selo, há algumas letras gravadas, porém somente as três primeiras são compreensíveis depois da limpeza: \"NOG...\". Elas podem ser tanto as iniciais do antigo proprietário do anel quanto do próprio criador dele. Ficar com o anel ou entregá-lo ao seu dono, o \"NOG\"... eis a questão! Decisões, decisões...", t = "Ficar ou não ficar... eis a questão!"},
    [2950] = {ot = "Leve o Anel de Ouro Brilhante, uma Barra de Prata, uma Ágata Musgosa e 30 moedas de Prata para Nogg em Orgrimmar.", st = "Não, não, não. Não estou dizendo duma hora pra outra que o anel é meu. Normalmente eu não faço isso, mas a informação que você trouxe a respeito dos Ferro Negro foi bem útil. Eu melhorarei o anel pra você, melhor do que quem fez essa bijuteria jamais poderia imaginar. Deve ter sido algum gnomo...$B$BMe traga um lingote de prata, uma ágata musgosa e trinta moedas de prata. Eu adicionarei uma treliça de ágata e prata ao anel que fortalecerá a magia do item. Te interessa?", t = "Recauchutagem do anel do Nogg"},
    [2951] = {ot = "Coloque um Objeto Encardido e três moedas de prata na Brastematic 5200 para iniciar o processo de limpeza.", st = "Observando o aparelho, você nota que ele se destaca em meio aos gnomos que resistem à confusão do lado de fora da sala. Em uma pequena placa é possível ler \"Brastematic 5200\", e logo em seguida: \"Crostas de sujeira incrustam seus pertences? A Brastematic 5200 resolve todos os seus problemas de limpeza! Coloque o objeto na máquina, três moedas de prata no compartimento e, tcharam! O fim da sujeira e um brilho jamais visto!\".", t = "A Brastematic 5200!"},
    [2952] = {t = "A Brastematic 5200!"},
    [2962] = {ot = "Vá até Gnomeregan e traga o Resíduo Radioativo de Alta Potência. Tome cuidado, pois a radiação é instável e pode se esvair rapidamente.$B$BOzzie também vai precisar do seu Coletor de Chumbo Pesado quando tiver terminado.\n", st = "Não só a amostra foi insuficiente em quantidade, como estava impura.$B$BNós precisamos de mais brilho verde. Os troggs não sofreram radiação suficiente para atender aos nossos propósitos. Você terá que adentrar Gnomeregan e recolher o resíduo radioativo na fonte. Estou falando dos visgos, tocaieiros e horrores irradiados. Esteja avisad$Go:a; de que armazenar esse tipo de resíduo não é fácil. Você vai ter que fazer várias tentativas com o frasco até conseguir uma amostra decente.", t = "A única cura é mais brilho verde"},
    [2983] = {ot = "Encontre Kranal Fiss nos Sertões.", st = "Já faz algum tempo desde que você foi testad$go:a;, $n. Você demonstrou muita paciência em seus estudos até agora, mas chegou a hora de aprender sobre poderes maiores — o verdadeiro poder. O elemento do fogo será seu, desde que você esteja dispost$go:a; a pagar o preço.$B$BProcure por Kranal Fiss nos Sertões. Ele vive em uma casinha ao norte da Encruzilhada, mas preste atenção para não passar direto e chegar até a terra dos elfos noturnos, o que significa que você terá ido longe demais.", t = "Clamor do Fogo"},
    [2984] = {ot = "Encontre Kranal Fiss nos Sertões.", st = "Já faz algum tempo desde que você foi testad$go:a;, $n. Você demonstrou muita paciência em seus estudos até agora, mas chegou a hora de aprender ainda mais. Chegou a hora de aprender sobre destruição... e caos. O elemento do fogo está ao alcance da sua compreensão, desde que você esteja dispost$go:a; a pagar.$B$BProcure por Kranal Fiss nos Sertões. Ele vive em uma casinha ao norte da Encruzilhada, mas, atenção, se você passar direto e chegar à terra dos elfos noturnos, terá ido longe demais.", t = "Clamor do Fogo"},
    [2998] = {ot = "Fale com Benedito Brião em Ventobravo.", st = "Saudações, $Girmão:irmã;. Benedito Brião, um de nossos mais influentes paladinos, estava falando sobre você recentemente. Escutei ele dizendo que já estava na hora de testar você... além de um rol de elogios sobre o seu desempenho até o momento.$B$BSe eu fosse você, iria para Ventobravo e falaria com ele assim que tivesse tempo. Com certeza, ele está na Catedral da Luz — é lá que ele fica a maior parte do tempo.", t = "Tomo de Divindade"},
    [2999] = {ot = "Fale com Tiza Beloforja em Altaforja.", st = "Olá, $n. Eu sei que tu tá $Gocupado:ocupada; ajudando o povo de Dun Morogh, mas, quando tiver um tempinho, tu precisa dar um pulo no andar de cima pra falar com um de nossos mais respeitados membros: Tiza Beloforja. É ela que os paladinos mais jovens procuram quando chega a hora de aprender mais sobre a Luz e o que se espera de ti.", t = "Tomo de Divindade"},
    [3065] = {ot = "Leia a Tabuleta Simples e fale com Frang no Vale das Provações.", st = "Ah, enquanto você estava fora, chegou uma tabuleta para você, $n.$B$BLeia quando tiver tempo. Se não me engano, é do instrutor de guerreiros Frang. Ele quer falar com você assim que você estiver $gpronto:pronta;. Ele fica na entrada do Covil, protegido na sombra.", t = "Tabuleta Simples"},
    [3082] = {ot = "Encontre Jen'shan no Vale das Provações.", st = "Ah, enquanto você estava fora, chegou uma tabuleta para você, $n.$B$BLeia quando tiver tempo. Se não me engano, é da instrutora de caçadores Jen'shan. Ela quer falar com você assim que você estiver $gpronto:pronta;.", t = "Tabuleta cinzelada"},
    [3083] = {ot = "Leia a Tabuleta Cifrada e fale com Rwag no Vale das Provações.", st = "Ah, enquanto você estava fora, chegou uma tabuleta para você, $n.$B$BLeia quando tiver tempo. Se não me engano, é do instrutor de ladinos Rwag. Ele quer falar com você assim que você estiver $gpronto:pronta;.", t = "Tabuleta cifrada"},
    [3084] = {ot = "Fale com Shikrik no Vale das Provações.", st = "Ah, enquanto você estava fora, chegou uma tabuleta para você, $n.$B$BLeia quando tiver tempo. Se não me engano, é da instrutora de xamãs Shikrik. Ela quer falar com você assim que você estiver $gpronto:pronta;.", t = "Tabuleta inscrita em runas"},
    [3085] = {ot = "Leia a Tabuleta Consagrada e fale com Ken'jai, do lado de fora do Covil, no Vale das Provações.", st = "Ah, enquanto você estava fora, chegou uma tabuleta para você, $n.$B$BLeia quando tiver tempo. Se não me engano, é do instrutor de sacerdotes Ken'jai. Ele quer falar com você assim que você estiver $gpronto:pronta;.", t = "Tabuleta consagrada"},
    [3086] = {ot = "Leia a Tabuleta Glífica e fale com Mai'ah perto do Covil, no Vale das Provações.", st = "Ah, enquanto você estava fora, chegou uma tabuleta para você, $n.$B$BLeia quando tiver tempo. Se não me engano, é da instrutora de magos Mai'ah. Ela quer falar com você assim que você estiver $gpronto:pronta;.", t = "Tabuleta glífica"},
    [3087] = {ot = "Leia o Pergaminho Cinzelado e fale com Jen'shan no Vale das Provações.", st = "Ah, enquanto você estava fora, chegou um pergaminho para você, $n.$B$BLeia quando tiver tempo. Se não me engano, é da instrutora de caçadores Jen'shan. Ela quer falar com você assim que você estiver $gpronto:pronta;.", t = "Pergaminho cinzelado"},
    [3088] = {ot = "Leia o Pergaminho Cifrado e fale com Rwag no Vale das Provações.", st = "Ah, enquanto você estava fora, chegou um pergaminho para você, $n.$B$BLeia quando tiver tempo. Se não me engano, é do instrutor de ladinos Rwag. Ele quer falar com você assim que você estiver $gpronto:pronta;.", t = "Pergaminho cifrado"},
    [3089] = {ot = "Leia o Pergaminho Inscrito em Runas e fale com Shikrik no Vale das Provações.", st = "Ah, enquanto você estava fora, chegou um pergaminho para você, $n.$B$BLeia quando tiver tempo. Se não me engano, é da instrutora de xamãs Shikrik. Ela quer falar com você assim que você estiver $gpronto:pronta;.", t = "Pergaminho inscrito em runas"},
    [3090] = {ot = "Leia o Pergaminho Conspurcado e fale com Nartok dentro do Covil, no Vale das Provações.", st = "Ah, chegou um pergaminho para você enquanto você estava fora, $n.$B$BGeralmente eu evito lidar com bruxos, mas melhor você ler o pergaminho assim que tiver tempo. Se não me engano, é do instrutor recém-designado, Nartok. Ele quer falar com você assim que você estiver $gpronto:pronta;.", t = "Pergaminho maculado"},
    [3091] = {ot = "Leia o Bilhete e fale com Harutt Chifre Troante, na Aldeia Narache.", st = "Não faz muito tempo, passou uma mensageira à sua procura, $n. Creio que foi enviada pelo instrutor de guerreiros Harutt. Se o bilhete foi mesmo enviado por Harutt, eu não demoraria a ler, se fosse você.", t = "Bilhete"},
    [3092] = {ot = "Leia o Bilhete Cinzelado e fale com Lanka Tiro Distante na Chapada Nuvem Vermelha.", st = "Não faz muito tempo, passou uma mensageira à sua procura, $n. Creio que foi enviada pelo instrutor de caçadores Lanka. Se o bilhete foi mesmo enviado por Lanka, eu não demoraria a ler, se fosse você.\n", t = "Bilhete cinzelado"},
    [3093] = {ot = "Leia o Bilhete Inscrito em Runas e fale com Meela Anda com a Aurora na Aldeia Narache.", st = "Não faz muito tempo, passou uma mensageira à sua procura, $n. Creio que foi enviada pela instrutora de xamãs Meela. Se o bilhete foi mesmo enviado por Meela, eu não demoraria a ler, se fosse você.\n", t = "Bilhete inscrito em runas"},
    [3094] = {ot = "Leia o Bilhete Verdejante e fale com Gart Corre com a Névoa, na Aldeia Narache.", st = "Não faz muito tempo, passou uma mensageira à sua procura, $n. Creio que foi enviada pelo instrutor de druidas Gart. Se o bilhete foi mesmo enviado por Gart, eu o leria o mais rápido possível, se fosse você.", t = "Bilhete verdejante"},
    [3095] = {ot = "Leia o Pergaminho Simples e fale com Dannal Stern em Plangemortis.", st = "Ah, enquanto esteve fora lidando com os Flagelos desmiolados, este pergaminho chegou para você. Deve ser algo de certa importância, já que parece ter o selo do instrutor de guerreiros Danna. Melhor ler isso antes de sair novamente.", t = "Pergaminho simples"},
    [3096] = {ot = "Leia o Pergaminho Cifrado e fale com o Davi Trias em Plangemortis.", st = "Ah, enquanto esteve fora lidando com os Flagelos desmiolados, este pergaminho chegou para você. Deve ser algo de certa importância, já que parece ter o selo do instrutor de ladinos Davi Trias. Melhor ler isso antes de sair novamente.", t = "Pergaminho cifrado"},
    [3097] = {ot = "Leia o Pergaminho Consagrado e fale com o Clérigo das Trevas Duesten, na igreja em Plangemortis.", st = "Ah, enquanto esteve fora lidando com os Flagelos desmiolados, este pergaminho chegou para você. Deve ser algo de certa importância, já que parece ter o selo do instrutor de sacerdotes Duesten. Melhor ler isso antes de sair novamente.", t = "Pergaminho consagrado"},
    [3098] = {ot = "Leia o Pergaminho Glífico e fale com Isabella na igreja em Plangemortis.", st = "Ah, enquanto esteve fora lidando com os Flagelos desmiolados, este pergaminho chegou para você. Deve ser algo de certa importância, já que parece ter o selo da instrutora de magos Isabella. Melhor ler isso antes de sair novamente.", t = "Pergaminho glífico"},
    [3099] = {ot = "Leia o Pergaminho Conspurcado e fale com Maximillion em Plangemortis.", st = "Ah, enquanto esteve fora lidando com os Flagelos desmiolados, este pergaminho chegou para você. Acredito que se trate de algo importante, já que traz o selo do instrutor de bruxos Maximillion. Sugiro que você leia isso antes de sair novamente.", t = "Pergaminho conspurcado"},
    [3100] = {ot = "Leia a Carta Simples e fale com Hipólito Valentim na Abadia de Vila Norte.", st = "Pediram-me para lhe entregar isto assim que você voltasse dos assentamentos de kobolds, $n. Parece ser uma carta selada com a insígnia de Hipólito, nosso instrutor de guerreiros local. Eu não hesitaria em lê-la antes de tratar de qualquer outro assunto aqui na Abadia.", t = "Carta simples"},
    [3101] = {ot = "Leia a Carta Consagrada e fale com o Irmão Samuel na Abadia de Vila Norte.", st = "Pediram-me para lhe entregar isto assim que você voltasse dos assentamentos de kobolds, $n. Parece ser uma carta selada com a insígnia do Irmão Samuel, nosso instrutor de paladinos local. Eu não hesitaria em lê-la antes de tratar de qualquer outro assunto aqui na Abadia.", t = "Carta consagrada"},
    [3102] = {ot = "Leia a Carta Cifrada e fale com Rufino Raposo no estábulo atrás da Abadia de Vila Norte.", st = "Pediram-me para lhe entregar isto assim que você voltasse dos assentamentos de kobolds, $n. Parece ser uma carta selada com a insígnia de Rufino, um dos nossos instrutores locais. Eu não hesitaria em lê-la antes de tratar de qualquer outro assunto aqui na Abadia.", t = "Carta cifrada"},
    [3103] = {ot = "Lei a Carta Santificada e fale com a Sacerdotisa Anita na Abadia de Vila Norte.", st = "Pediram-me para lhe entregar isto assim que você voltasse dos assentamentos de kobolds, $n. Parece ser uma carta selada com a insígnia da Sacerdotisa Anita, nossa instrutora de sacerdotes local. Eu não hesitaria em lê-la antes de tratar de qualquer outro assunto aqui na Abadia.", t = "Carta santificada"},
    [3104] = {ot = "Leia a Carta Glífica e fale com Gaspar Melchior dentro da Abadia de Vila Norte.", st = "Pediram-me para lhe entregar isto assim que você voltasse dos assentamentos de kobolds, $n. Parece ser uma carta selada com a insígnia de Gaspar, nossa instrutor de magos local. Eu não hesitaria em lê-la antes de tratar de qualquer outro assunto aqui na Abadia.", t = "Carta glífica"},
    [3105] = {ot = "Leia a Carta Maculada e fale com Drusilla La Salle perto da Abadia de Vila Norte.", st = "Pediram-me para lhe entregar isto assim que você voltasse dos assentamentos de kobolds, $n. Parece ser uma carta selada com a insígnia de Drusilla, uma de nossos instrutores locais. Eu não hesitaria em lê-la antes de tratar de qualquer outro assunto aqui na Abadia.", t = "Carta maculada"},
    [3106] = {ot = "Leia a Runa Simples e fale com Thran Khorman no Vale Cristálgida.", st = "Enquanto tu me ajudava, recebi esta runa para ti. Te acomode uma hora para ler o que ela diz. Penso eu que foi o instrutor de guerreiros Thran quem a enviou. Dá uma olhada e depois fale com ele em Sidermar quando tiver a oportunidade.", t = "Runa simples"},
    [3107] = {ot = "Leia a Runa Consagrada e fale com Bromos Grummner no Vale Cristálgida.", st = "Enquanto tu me ajudava, recebi esta runa para ti. Te acomode uma hora para ler o que ela diz. Penso eu que foi o instrutor de paladinos Bromos quem a enviou. Dá uma olhada e depois fale com ele em Sidermar quando tiver a oportunidade.", t = "Runa consagrada"},
    [3108] = {ot = "Leia a Runa Cinzelada e fale com Thorgas Grimson no Vale Cristálgida.", st = "Enquanto tu me ajudava, recebi esta runa para ti. Te acomode uma hora para ler o que ela diz. Penso eu que foi o instrutor de caçadores Thorgas quem a enviou. Dá uma olhada e depois fale com ele em Sidermar quando tiver a oportunidade.", t = "Runa cinzelada"},
    [3109] = {ot = "Leia a Runa Cifrada e fale com Solm Hargrin no Vale Cristálgida.", st = "Enquanto tu me ajudava, recebi esta runa para ti. Te acomode uma hora para ler o que ela diz. Penso eu que foi o instrutor de ladinos Solm quem a enviou. Dá uma olhada e depois fale com ele em Sidermar quando tiver a oportunidade.", t = "Runa cifrada"},
    [3110] = {ot = "Leia a Runa Santificada e fale com Branstock Khalder em Sidermar.", st = "Enquanto tu me ajudava, recebi esta runa para ti. Te acomode uma hora para ler o que ela diz. Penso eu que foi o instrutor de sacerdotes Branstock quem a enviou. Dá uma olhada e depois fale com ele em Sidermar quando tiver a oportunidade.", t = "Runa santificada"},
    [3112] = {ot = "Leia o Memorando Simples e fale com Thran Khorman no Vale Cristálgida.", st = "Enquanto tu me ajudava, recebi este memorando para ti. Te acomode uma hora para ler o que ele diz. Penso eu que foi o instrutor de guerreiros Thran quem o enviou. Dá uma olhada e depois fale com ele em Sidermar quando tiver a oportunidade.", t = "Memorando simples"},
    [3113] = {ot = "Leia o Memorando Cifrado e fale com Solm Hargrin no Vale Cristálgida.", st = "Enquanto tu me ajudava, recebi este memorando para ti. Te acomode uma hora para ler o que ele diz. Penso eu que foi o instrutor de ladinos Solm quem o enviou. Dá uma olhada e depois fale com ele em Sidermar quando tiver a oportunidade.", t = "Memorando cifrado"},
    [3114] = {ot = "Leia o Memorando Glífico e fale com Marryk Nurribit em Sidermar, no alto do Vale Cristálgida.", st = "Enquanto tu me ajudava, recebi este memorando para ti. Te acomode uma hora para ler o que ele diz. Penso eu que foi o instrutor de magos Marryk quem o enviou. Dá uma olhada e depois fale com ele em Sidermar quando tiver a oportunidade.", t = "Memorando Glífico"},
    [3115] = {ot = "Leia o Memorando Maculado e fale com Alamar Carranca em Sidermar, no alto do Vale Cristálgida.", st = "Enquanto tu me ajudava, recebi este memorando para ti. Te acomode uma hora para ler o que ele diz. Penso eu que foi o instrutor de bruxos Alamar quem o enviou. Dá uma olhada e depois fale com ele em Sidermar quando tiver a oportunidade.$B$BE te cuida, $n, por aqui o povo olha torto para gente como tu.", t = "Memorando Maculado"},
    [3116] = {ot = "Leia o Selo Simples e fale com Alyissia em Umbravale.", st = "Este selo me foi entregue por um mensageiro enviado por nossa instrutora de guerreiros, Alyissia. Parece que ela deseja conversar com você quando tiver algum tempo livre. Leia o recado e, depois, leve-o a ela.", t = "O selo simples"},
    [3117] = {ot = "Leia o Selo Cinzelado e fale com Ayanna Perenanda no topo de Aldrassil, em Umbravale.", st = "Este selo foi-me entregue por um mensageiro enviado por nossa instrutora de caçadores, Ayanna. Parece que ela deseja conversar com você quando tiver algum tempo livre. Leia o recado e, depois, leve-o a ela.", t = "O selo cinzelado"},
    [3118] = {ot = "Leia o Selo Cifrado e fale com Frahun Umbrurmúrio em Umbravale.", st = "Este selo me foi entregue por um mensageiro enviado por nosso instrutor de ladinos, Frahun. Parece que ele deseja conversar com você quando tiver algum tempo livre. Leia o recado e, depois, leve-o a ele.", t = "O selo cifrado"},
    [3119] = {ot = "Leia o Selo Sagrado e fale com Shanda em Aldrassil.", st = "Este selo me foi entregue por um mensageiro enviado por nossa instrutora de sacerdotes, Shanda. Parece que ela deseja conversar com você quando tiver algum tempo livre. Leia o recado e, depois, leve-o a ela.", t = "O selo sagrado"},
    [3120] = {ot = "Leia o Selo Verdejante e fale com Mardant Carvalhaço na ávore Aldrassil, em Umbravale.", st = "Este selo me foi entregue por um mensageiro enviado por nosso instrutor de druidas, Mardant. Parece que Mardant deseja conversar com você quando tiver algum tempo livre. Leia o recado e, depois, leve-o a ele.", t = "O selo verdejante"},
    [3221] = {ot = "Fale com o Boticário Renferrel no Sepulcro.", st = "Enquanto você auxiliava os sicários, o Boticário Renferrel mandou convocar-lhe. Ele não forneceu detalhes, mas queria discutir com você sobre os corações de lobo que você lhe deu.", t = "Fale com Renferrel"},
    [3261] = {ot = "Fale com Jorn Vidente do Céu no Acampamento Taurajo.", st = "Seu tempo comigo chegou ao fim, $n. Para aprender mais, vá ao Acampamento Taurajo ao sul e fale com Jorn Vidente do Céu. Ele vai continuar a sua orientação.", t = "Jorn Vidente do Céu"},
    [3281] = {ot = "Leve a Prata Roubada para Gazrog na Encruzilhada.", st = "Você matou os raptores, mas alguém ainda tem que recuperar a prata que eles roubaram! Recebi relatos de que eles fizeram um punhado de ninhos ao sul da Vila Catraca, na Terra dos Raptores. Eles devem ter levado nossa prata roubada lá.$B$BProcure esse raptor e encontre a prata roubada. Depois, traga a prata para mim.", t = "Prata roubada"},
    [3301] = {ot = "Fale com Mura Runa Totem no Sepulcro.", st = "Minha colega de clã, Mura Runa Totem, foi até Pinhaprata para auxiliar nossos aliados mortos-vivos. Pinhaprata é uma floresta sôfrega, moribunda, e Mura tem esperança de recuperá-la. Talvez essa forma de vida estranha dos Sertões possa ajudá-la em Pinhaprata.$B$BPegue uma amostra das conchas que você coletou e leve-a para Mura em Pinhaprata. Ela fica no Sepulcro. Com sorte, estudar essa concha pode ser a inspiração que falta para ela curar esse lugar decadente.", t = "Mura Runa Totem"},
    [3361] = {ot = "Leve a Caixa do Félix, o Baú do Félix e o Balde de Parafusos do Félix para Félix Reclamofuso em Sidermar.", st = "Expulsamos os troggs de Gnomeregan, mas depois tudo foi por água abaixo! A radiação tomou conta do nosso lar e nós, gnomos, nos espalhamos por toda Dun Morogh.$B$BNa pressa de escapar da radiação, perdi meus pertences e ferramentas. Foram os trolls que pegaram. Eles roubaram meu baú, minha caixa e meu balde de parafusos! Levaram tudo para o acampamento deles, a sudoeste de Sidermar.$B$BNão sou de aventuras. Será que você podia procurar minhas coisas e recuperá-las para mim, por favor?", t = "Um dia na vida de um refugiado"},
    [3364] = {ot = "Leve um Rabo-de-Galo Escaldante para Durnan Cortapelo em Sidermar em cinco minutos, antes que esfrie!", st = "Cuê-pucha! Nesta manhã, eu devia ter levado este rabo-de-galo escaldante para Durnan Cortapelo já faz um tempo, mas eu tava em cima do laço na entrega do Grolin aqui. Nunca que chego em Sidermar sem que isto esfrie!$B$BTu pareces ágil como um leopardo da neve. Talvez tu consiga. É cinco minutos pra isto aqui ficar que é um gelo de frio, e Durnan não pediu um rabo-de-galo \"refrescante\", então te manda. Sidermar fica pro nordeste, num assentamento cavado na montanha.$B$BTe fico muito grato, $n, e não te bobeie: quero minha caneca de volta!", t = "Rabo-de-galo em domicílio"},
    [3365] = {ot = "Devolva a Caneca de Nóri para Nóri Fluiorgulho.", st = "Isso é que é caldo de lei! Nada como um rabo-de-galo fervente, não, ESCALDANTE pra tirar a friagem do bucho nessa invernada que trinca até dentadura.$B$BTome isto, $n. Agora não te mixa e me faz uma mão: leva de volta esta caneca pro Nori.", t = "Devolva a caneca"},
    [3369] = {ot = "Leve a Lasca de Pesadelo para Hamuul Runa Totem no Platô dos Anciãos.", st = "Essa lasca guarda muitos segredos, é a pura essência do Sonho Esmeralda. Todavia, o que vejo aqui não é um sonho, alguns até diriam se tratar de uma visão pesadelar.$B$BNão tenho intenção de alarmar você, $n, mas acho que deveria levar essa lasca à atenção de um sábio druida o quanto antes...$B$BHamuul Runa Totem, no Platô dos Anciãos, é quem você deve procurar. Dirija-se ao Penhasco do Trovão. É só o que posso dizer. ", t = "Em pesadelos"},
    [3370] = {ot = "Leve a Lasca de Pesadelo para Mathrengyl Ursivagus em Darnassus.", st = "Essa lasca guarda muitos segredos, é a pura essência do Sonho Esmeralda. Todavia, o que vejo aqui não é um sonho, alguns até diriam se tratar de uma visão pesadelar.$B$BNão tenho intenção de alarmar você, $n, mas acho que deveria levar essa lasca à atenção de um sábio druida o quanto antes...$B$BMathrengyl Ursivagus, do Círculo Cenariano, é quem você deve procurar. Dirija-se a Darnassus. É só o que posso dizer.", t = "Em pesadelos"},
    [3376] = {ot = "Leve a cabeça do Chefe Presadura Mantospinho para a Valente Pena ao Vento na Chapada Nuvem Vermelha.", st = "$n... Ouvi falar de você, $Gneófito:neófita;. Talvez possa nos ajudar onde tantos outros falharam.$B$BNós, os taurens, fizemos desta terra o nosso lar, mas pagamos um preço alto. Os javatuscos Costagulha da Ravina da Lâmina Espinhenta, liderados pelo Chefe Presadura Mantospinho, tornaram nossa vida difícil por meio de guerras contínuas contra a nossa tribo. Comando que me traga a cabeça do chefe!$B$BEncontre-o na ravina a leste, na vila rústica dos javatuscos.", t = "Quebra-presadura!"},
    [3519] = {ot = "Fale com Dirânia Pratafulge em Umbravale.", st = "Uuuugh... Fui picado em cheio por uma aranha chamada Githyiss, a Torpe, quando estava explorando a caverna das aranhas aqui perto. Com certeza fui seriamente envenenado, e você precisa me socorrer.$B$BPor favor, conte à Dirânia Pratafulge. Ela conseguirá me ajudar.$B$BRápido... Já estou... ficando... tonto...", t = "Um amigo em apuros"},
    [3521] = {ot = "Colete 7 Cogumelos Jacinto, 4 Lírios Lunapétala e 1 Linfa de Lenhateia para Dirânia Pratafulge em Umbravale.", st = "Pode ser possível ajudar Iverron. Eu conheço um antídoto que deve ajudar com o veneno. Porém... ele exige alguns ingredientes.$B$BVou precisar de cogumelos jacinto. Você pode colhê-los embaixo das árvores, ou encontrá-los com os capetas ao sul daqui. Eles parecem apreciá-los também. E eu também precisarei de pétalas de lunapétala, que só crescem às margens de pequenos lagos.$B$BO último ingrediente pode se provar ser o mais difícil. Das próprias aranhas que envenenaram Iverron, extraia a linfa das lenhateia.", t = "O antídoto de Iverron"},
    [3522] = {ot = "Leve o Antídoto de Iverron para Iverron antes que o tempo se esgote. Iverron está na caverna ao norte.", st = "O antídoto está pronto, $n. Por favor, cuide para que o Iverron beba.$B$BTem uma coisa que você precisa saber: o antídoto... só dura 5 minutos. Você precisa chegar até ele a tempo.$B$BVá célere, $n.", t = "O antídoto de Iverron"},
    [3524] = {ot = "Obtenha Ossos de Criaturas Marinhas da criatura marinha encalhada logo ao sul Auberdine e leve para Gwennyth Bly'Leggonde em Auberdine.", st = "Sabe-se que criaturas marinhas majestosas se lançam de encontro à Costa Negra, onde terminam encalhadas até a morte. Ultimamente essas feras têm aparecido em número cada vez maior. O Templo da Lua me enviou para investigar, mas a presença de murlocs na água dificultou minha pesquisa.$B$BHá uma criatura gigante que encalhou logo ao sul de Auberdine, mas ela está cercada por aqueles murlocs Brumagris imundos. Você poderia ir até lá e extrair ossos da criatura para nosso estudo?", t = "Deixa a água me levar"},
    [3741] = {ot = "Encontre e devolva o Colar da Hilária na Vila Plácida.", st = "Minha amiga Hilária perdeu o colar, e não conseguimos encontrá-lo. Nós temos pescado aqui o dia todo, e já procuramos por toda a área. O único lugar que falta olhar... é dentro do lago. Nossos pais não querem que a gente entre no lago... A mamãe diz que tem bicho feio na água, mas você não parece ter medo de bicho feio...$B$BVocê pode achar o colar da Hilária? Por favor?", t = "Colar da Hilária"},
    [3765] = {ot = "Fale com Gershala Umbrurmúrio em Auberdine.", st = "Ventobravo... um centro de atividade tão movimentado.$b$bEu vim de longe para obter auxílio. Muitas vezes se ouve dizer que aventureiros corajosos caminham por essas ruas.$b$bO meu irmão, Gershala, precisa de ajuda na Costa Negra. Ele vive na cidade costeira de Auberdine.$b$bA viagem até lá é longa e épica. É por essa razão que peço a ajuda de $gum:uma; $c experiente como você.", t = "A corrupção estrangeira"},
    [3901] = {ot = "Mate 12 Esqueletos Range-ossos e fale novamente com o Sacerdote Sombrio Sarvis em Plangemortis quando terminar.", st = "Em circunstâncias normais, você já provou aos Renegados que tem potencial, $n – agora vamos ver como se sai sob pressão.$B$BOs esqueletos Range-ossos, os lacaios mais descerebrados do Lich Rei, são um desafio maior que os zumbis que você enfrentou até agora. Vá lá mais uma vez, reduza os números deles e mostre aos Renegados do que você é capaz. Não perca tempo. Quando terminar, venha falar de novo comigo.", t = "Desossando alguns Range-ossos"},
    [3902] = {ot = "Procure 6 peças de Material Reaproveitado nas redondezas de Plangemortis e fale novamente com o Necroguarda Saulo.", st = "Você aí! Se quiser ser útil, venha aqui um instante!$B$BPrecisamos de recrutas recém-desenterrados para ir até Plangemortis atrás de equipamentos úteis de toda sorte. Eles provavelmente estarão encaixotados e empilhados. Esperamos mais recrutas erguidos em breve e, como não queremos ninguém perambulando sem nada para cobrir os ossos, vamos ter que trabalhar!$B$BEntão, hora de pôr a mão na massa, saco miserável de ossos! Eu não vou recompensar ninguém que não dê duro.", t = "Vasculhando Plangemortis"},
    [3903] = {ot = "Fale com Madel Quintana.", st = "Você mostrou ser u$Gm:ma; $c dign$Go:a; de confiança, $n. Além disso, você não tem medo de sujar as mãos, não é?$B$BEu tenho uma amiga que se chama Madel Quintana que está tendo alguns problemas. Ela está com a carroça dela do outro lado da abadia, perto do estábulo. Tenho certeza de que você seria de grande ajuda para ela.", t = "Madel Quintana"},
    [3904] = {ot = "Leve 8 caixotes da Colheita da Madel para Madel Quintana na Abadia de Vila Norte.", st = "Os Défias, uma gangue de bandoleiros, se instalou nos Vinhedos de Vila Norte enquanto eu fazia a colheita! Eu avisei aos guardas de Vila Norte e eles me asseguraram que cuidariam de tudo, mas... eu estou preocupada com as minhas uvas! Se os Défias não roubarem todas, eu tenho medo que os guardas as estraguem na hora de rechaçar aqueles bandidos.$B$BPor favor, você tem que me ajudar! Eu pus a maior partes das uvas em baldes, mas eles ficaram nos vinhedos a sudeste.$B$BTraga aquelas caixas para mim! Salve a minha colheita!", t = "Colheita da Madel"},
    [3905] = {ot = "Leve o Manifesto da Uva para o Irmão Neals na Abadia de Vila Norte.", st = "Agora que a minha produção está salva, leve este Manifesto da Uva para o Irmão Neals. Ele cuida da loja de comida e bebida de Vila Norte, e eu tenho certeza de que ele vai adorar saber sobre as uvas fresquinhas.$B$BO Irmão Neals está na abadia, na torre do sino... onde ele gosta de degustar seus vinhos.", t = "Manifesto da Uva"},
    [3921] = {ot = "Leve a Rebimboca Quebrada para Juntatudy Jogafora.", st = "Hm, acho que eu quebrei essa rebimboca. Vou ter que dar um jeito nisso, porque já contei dela pra uns colegas na Inframina e eles ficaram muito intrigados. A gente vai ter que dar um jeito de consertar!$B$BLeva a rebimboca quebrada pra Juntatudy Jogafora, logo ao sul da Paliçada Mor'shan, o posto avançado da Horda entre os Sertões e o Vale Gris. Ela é crânio, se interessa pelas coisas. Se você mostrar a rebimboca pra ela, aposto que ela vai querer tentar consertar.", t = "Juntatudy Jogafora"},
    [3922] = {ot = "Leve 15 Chumbalheiras para Juntatudy Jogafora nos Sertões.", st = "Eu quero consertar essa rebimboca, mas pra fazer isso vou precisar de umas coisinhas. Tô sem chumbalheiras 7.5 e vou precisar de várias delas.$B$BO lugar mais perto em que dá pra encontrar essas peças é no Charco de Lodo, a leste daqui. A Empreendimentos S.A. sempre deixa elas nos baldes de ferramentas. Vai lá no Charco de Lodo e procura nos baldes de ferramentas. Quando tiver juntado bastante chumbalheiras, vem trazer pra mim.", t = "Chumbalheiras"},
    [3923] = {ot = "Leve a Rebimboca Quebrada e Surrada para o Rilli Passomal em Orgrimmar.", st = "Bom, não funcionou. Eu pus mais uns medidores pra checar a integridade estrutural da rebimboca, e eles mostraram que a integridade tá mais baixa que nunca. Dá pra adicionar mais uns sintonizadores, talvez uma ou duas alavancas pra tentar dar um jeito, mas... acho que isso pode até piorar a situação.$B$BÉ melhor levar essa rebimboca pro Rilli Passomal. Ele trabalhava pra Empreendimentos S.A. — se alguém vai saber arrumar, é o Rilli.$B$BEle vai estar na Oficina do Nogg. Fica em Orgrimmar, no Vale da Honra.", t = "Rilli Passomal"},
    [3924] = {ot = "Leve o Manual da Rebimboca para Rilli Passomal em Orgrimmar.", st = "Acho que eu consigo consertar essa rebimboca, mas vou precisar do manual de instruções. Quando trabalhava na Empreendimentos S.A., tinha um cara, o Chefe Cobreplugue, que controlava o que todo mundo sabia sobre a rebimboca. Ele só repassava informação pros amiguinhos dele, e como não ia muito com a minha cara...$B$BO Chefe Cobreplugue ficava na Mina Veio do Pedregulho, no nordeste dos Sertões. Pega o manual e traz pra mim. Talvez ele tenha passado algumas páginas pra alguém, aí você vai ter que ir atrás delas.", t = "Manual da rebimboca"},
    [4021] = {ot = "Leve um Pedaço do Estandarte de Krom'zar para Regthar Portões-da-morte, a oeste da Encruzilhada.", st = "A Horda comemora os êxitos que obteve contra os Kolkar, mas os Kolkar, por sua vez, estão enfurecidos. Há relatos de que um contingente dos Kolkar viajou do lar deles, na Desolação, até os Sertões, em busca de vingança. O último relatório indica que, neste exato momento, eles investem contra as trincheiras, vindos do oeste!$B$BEnfrente os invasores Kolkar e dê fim à ameaça que eles representam aos Sertões. Mate-os até que seu líder, o Senhor da Guerra Krom'zar, apareça. Derrote-o e traga-me um pedaço de seu estandarte como prova.$B$BContamos com você, $n.", t = "Contra-ataque!"},
    [4161] = {ot = "Colete 7 Pernas Pequenas de Aranha para Zarrin, de Dolanaar.", st = "Muito tempo atrás, os elfos noturnos eram chamados de kaldorei, um nome que significa \"filhos das estrelas\". Aprender sobre o passado é um passo importante em seu caminho como $c, $n, portanto, ouça bem o que eu tenho a lhe dizer.$B$BOs kaldorei sempre se orgulharam de sua relação harmoniosa com a natureza. Isso significa que só tiramos dela o que é necessário e retribuímos na mesma medida. Esse equilíbrio nos proporcionou muito, $n.$B$BVá e colete sete pernas pequenas de aranha — não mais do que isso — e volte aqui.", t = "Receita dos Kaldorei"},
    [4402] = {ot = "Leve 10 Sabras para Galgar. Você lembra que ele disse que se encontram sabras perto dos cactos.", st = "Mas é quente mesmo aqui no Vale das Provações.$B$B<Galgar seca o suor da testa.>$B$BSe ao menos eu tivesse algumas sabras, eu poderia preparar a minha famosa surpresa de sabra! Nada refresca tão rápido quanto um pedaço daquela delícia.$B$BTive uma ideia, $n. Se você me trouxer 10 sabras, eu preparo umas porções da surpresa de sabra para você levar nas suas aventuras e também um manual de treinamento grátis. Se tiver interesse, poderá encontrar sabras perto dos cactos que existem por aqui.", t = "A surpresa de sabra do Galgar"},
    [4495] = {ot = "Encontre Iverron perto da caverna ao norte.", st = "Um amigo meu chamado Iverron costuma me visitar à mesma hora todos os dias. O estranho é que ele não apareceu hoje... está várias horas atrasado, na verdade.$B$BAdmito que estou um pouco preocupada, $n. Iverron passa muito tempo para os lados da caverna ao norte, e tenho certeza de que você sabe como o lugar é perigoso — aranhas por toda parte!$B$BSe por acaso você passar por lá, pode ver se o encontra?", t = "Um bom amigo"},
    [4542] = {ot = "Leve a Mensagem Urgente ao Vigia do Rochedo Chifre Longo na Aldeia Vento Livre.", st = "Brav$Go:a; viajante, os centauros intensificaram os ataques na região. A Aldeia Vento Livre precisa ser informada imediatamente! Vá atrás do Vigia do Rochedo Chifre Longo na Aldeia Vento Livre a sudeste e transmita-lhe essa mensagem urgente.$b$bMas passe longe do Clã Temível Totem... eles têm se comportado de forma estranha ultimamente.\n\n\n", t = "Mensagem para a Aldeia Vento Livre"},
    [4581] = {ot = "Leve o Bilhete de Shindrell para Kainet Brisacalma em Cantilenda.", st = "O druida Kainet Brisacalma me enviou uma mensagem. Ele quer um relato dos acontecimentos ao longo da nossa costa e das florestas ao redor de Astranaar. Ele teme que uma corrupção esteja se espalhando pelo Vale Gris... e pode estar certo.$B$BAqui, leve meu relatório até ele. Você o encontrará no santuário de Cantilenda, na Floresta Noturcanto, a leste.", t = "Kainet Brisacalma"},
    [4641] = {ot = "Fale com Gornek. Kaltunk marcou o paradeiro dele no mapa e mencionou que ele morava no Covil, ao oeste. \n\n", st = "Finalmente, você já tem idade, $n... idade suficiente para lutar pela Horda. Para conquistar glórias em nome do Chefe Guerreiro.$B$BSim...$B$B<Kaltunk analisa você.>$B$BVocê se sairá bem.$B$BSem dúvida, você quer encontrar um grande dragão ou demônio e estrangulá-lo com as próprias mãos, mas talvez seja mais sábio começar por alguma coisa menos... perigosa.$B$B<Kaltunk ri.>$B$BApresente-se a Gornek, ele deve lhe designar missão mais adequada a $gum:uma; jovem $c. Gornek se encontra no Covil, ao oeste.\n", t = "O seu lugar no mundo"},
    [4681] = {ot = "Recupere a Carcaça de Tartaruga Marinha da Tartaruga Marinha Descarnada nas águas a oeste de Auberdine, e então fale com Gwennyth Bly'Leggonde em Auberdine.", st = "Aquela criatura encalhada não é um incidente isolado aqui em Costa Negra. Há outras ao longo da costa e até mesmo na água. Gostaria que você investigasse outra de que tivemos notícia. Pelo que soubemos, a criatura está na água, a oeste de Auberdine, perto de um navio afundado. Traga-me qualquer coisa que você consiga recuperar que nos ajude em nossa pesquisa.$B$BAlém disso, talvez você encontre outras criaturas em suas viagens. Caso descubra alguma coisa, não deixe de trazer à nossa atenção!", t = "Deixa a água me levar"},
    [4722] = {ot = "Leve a Carcaça de Tartaruga Marinha para Gwennyth Bly'Leggonde em Auberdine.", st = "Você encontra a carcaça de uma tartaruga marinha que encalhou na praia da Costa Negra há algum tempo. Os restos da criatura já foram revirados pelos murlocs que acamparam em torno deles. Ainda assim, parecem ter sobrado algumas boas amostras da carcaça, que poderiam ser úteis à Gwennyth Bly'Leggonde, em Auberdine.", t = "Tartaruga Marinha Encalhada"},
    [4723] = {ot = "Leve os Ossos de Criaturas Marinhas para Gwennyth Bly'Leggonde em Auberdine.", st = "Os restos de um mangual gigante — muito maior do que se esperaria encontrar em Costa Negra — encontram-se encalhados na costa de Beira das Névoas. Como esta criatura veio parar aqui não se sabe. O grupo de murlocs que agora se banqueteia com a carcaça parece ser muito fraco, mesmo em grandes números, para ter abatido o animal. $B$BEmbora parte dele já tenha sido retirada, resta o suficiente para levar uma amostra para Gwennyth Bly'Leggonde, em Auberdine, estudar.", t = "Criatura Marinha Encalhada"},
    [4725] = {ot = "Leve a Caixa com Marcações Estranhas para Gwennyth Bly'Leggonde em Auberdine.", st = "Mais uma carcaça de tartaruga marinha foi encontrada encalhada na costa. Este conjunto em particular tem uma carruagem abandonada presa ao casco da tartaruga. Talvez essa criatura tenha sido levada para o litoral por seres desconhecidos, em vez de encalhar, como algumas das outras carcaças sugerem. Os murlocs Brumagris fizeram dos restos dessa criatura seu lar, banqueteando-se com a carniça.$B$BNa carruagem, você encontra uma caixa com marcas estranhas. Talvez Gwennyth Bly'Leggonde em Auberdine consiga entender.", t = "Tartaruga marinha encalhada"},
    [4727] = {ot = "Leve a Carcaça de Tartaruga Marinha para Gwennyth Bly'Leggonde em Auberdine.", st = "Há um esqueleto de tartaruga marinha na areia das praias setentrionais da Costa Negra. Os murlocs Brumagris ainda não encontraram essa carcaça, ou talvez tenham encontrado e estão mantendo distância por algum motivo desconhecido. Independente disso, sobrou o suficiente da tartaruga para levar uma amostra para Gwennyth Bly'Leggonde em Auberdine, para que o Templo da Lua possa estudá-la.", t = "Tartaruga Marinha Encalhada"},
    [4728] = {ot = "Leve os Ossos de Criaturas Marinhas para Gwennyth Bly'Leggonde em Auberdine.", st = "Há uma carcaça de uma espécie de mamífero marinho gigante parcialmente esviscerada na praia. Um carrinho de mão e várias ferramentas foram abandonados perto da criatura encalhada, como se alguém tivesse tentado estudá-la. Apesar de os murlocs a terem destroçado, há o suficiente para levar uma amostra a Gwennyth Bly'Leggonde em Auberdine.", t = "Criatura Marinha Encalhada"},
    [4730] = {ot = "Leve os Ossos de Criaturas Marinhas para Gwennyth Bly'Leggonde em Auberdine.", st = "Há um cadáver semidevorado de uma espécie de mamífero marinho gigante na praia. Um bando de murlocs, mais fortes do que aqueles encontrados perto de Auberdine, se estabeleceram em torno da criatura caída. Há o suficiente dela para levar uma amostra de seus ossos para Gwennyth Bly'Leggonde em Auberdine.", t = "Criatura Marinha Encalhada"},
    [4731] = {ot = "Leve a Caixa com Marcações Estranhas para Gwennyth Bly'Leggonde em Auberdine.", st = "Há outra carcaça de tartaruga marinha encalhada na costa. Esse cadáver tem uma carruagem abandonada presa ao casco. Talvez essa criatura tenha sido levada para o litoral por seres desconhecidos, em vez de encalhar, como algumas das outras carcaças sugerem. Os poderosos murlocs Brumagris se instalaram na carcaça.$B$BNa carruagem, você encontra uma caixa com marcas estranhas. Talvez Gwennyth Bly'Leggonde em Auberdine consiga entender.", t = "Tartaruga Marinha Encalhada"},
    [4732] = {ot = "Leve a Carcaça de Tartaruga Marinha para Gwennyth Bly'Leggonde em Auberdine.", st = "Você encontra a carcaça de uma tartaruga marinha que encalhou na praia de Costa Negra há algum tempo. Ela foi quase toda devorada pelos murlocs Brumagris, os mesmos que agora estão acampados em torno dos restos da criatura. Ainda assim, parecem ter sobrado algumas boas amostras da carcaça que poderiam ser úteis a Gwennyth Bly'Leggonde, em Auberdine.", t = "Tartaruga Marinha Encalhada"},
    [4733] = {ot = "Leve os Ossos de Criaturas Marinhas para Gwennyth Bly'Leggonde em Auberdine.", st = "Os restos do que parece ser um segador gigante apareceram na enseada rochosa da Costa do Crepúsculo. Esse é muito maior do que os outros segadores vistos nas redondezas. De onde quer que tenha vindo, essa criatura não parece ser nativa da Costa Negra.$B$BApesar dr ela ter sido estraçalhada, sobrou o suficiente para recolher uma amostra para Gwennyth Bly'Leggonde em Auberdine.", t = "Criatura Marinha Encalhada"},
    [4740] = {ot = "Encontre e mate o murloc conhecido como Lodofundo. Acredita-se que a criatura esteja defendendo as tendas dos murlocs ao sul de Auberdine, ao longo da costa.$B$BRelate a morte de Lodofundo à Sentinela Glynda Nal'Shea em Auberdine.", st = "Atenção!$B$BOferece-se uma recompensa pela cabeça do murloc conhecido como \"Lodofundo\". Essa fera desprezível é responsável pela morte de pelo menos uma sentinela, e é suspeita de causar o naufrágio de pelo menos dois cargueiros nas águas da Costa Negra.$B$BLodofundo foi visto pela última vez em um acampamento murloc ao sul de Auberdine, e acredita-se que esteja protegendo as tendas de lá. A recompensa deve ser solicitada à Sentinela Glynda Nal'Shea, em Auberdine.$B$BConselho da Aldeia de Auberdine", t = "PROCURA-SE: Lodofundo!"},
    [4761] = {ot = "Fale com Trovejius Tecevento em Auberdine.", st = "A sua observação do acampamento dos pelursos deve chegar ao conhecimento de Trovejius Tecevento. Ele serve graciosamente como o ancião de Auberdine, oferecendo orientação sábia e justa ao dia a dia da aldeia. Por favor, compartilhe suas descobertas sobre a situação dos pelursos com ele.$B$BEu acredito que ele terá uma opinião sobre o que está por trás da corrupção. Talvez você possa trabalhar com ele em um plano para restaurar o equilíbrio da natureza por lá!", t = "Trovejius Tecevento"},
    [4762] = {ot = "Vá para o norte de Auberdine até a primeira queda d'água ao longo do Rio Fontescarpa e consiga uma amostra do charco.$B$BLeve a Amostra do Rio Fontescarpa para Trovejius Tecevento em Auberdine.", st = "O Rio Fontescarpa começou a ficar sujo e corrompido. Ele deságua na Beira das Névoas, e eu temo que os resíduos alcancem Auberdine em breve. Eu suspeito que os pelursos de Bosquenero rio acima são a causa da corrupção. Mas também suspeito que eles não são a origem dela.$B$BPegue este tubo de amostragem e vá até a foz do rio ao norte. Siga por terra até a primeira queda d'água e recolha uma amostra. Você verá uma ponte. Assim que conseguir a amostra, fale novamente comigo em Auberdine.", t = "Rio Fontescarpa"},
    [4763] = {ot = "Encha a Bacia de Limpeza Vazia no Poço Lunar de Auberdine.$B$BObtenha uma amostra de fruta, noz e grão dos acampamentos dos pelursos Bosquenero ao norte.$B$BMisture tudo na bacia e coloque junto à fogueira próxima ao Rio Fontescarpa, no acampamento norte. E assim atraia o sátiro corruptor.$B$BPegue o Talismã de Corrupção e o leve para Trovejius Tecevento em Auberdine.", st = "Nós aprendemos que os sátiros são a fonte de corrupção dos pelursos. Eles exercem sua influência por meio de talismãs que canalizam sua magia. Para os pelursos terem alguma chance de salvação, nós devemos atrair o sátiro corruptor e tomar seu talismã!$B$BEncha esta bacia no nosso poço lunar e obtenha amostras da comida dos pelursos em seu acampamento ao norte. Misture e coloque-as junto à fogueira próxima ao rio. Qualquer pelurso que comê-la será purificado tempo suficiente para chamar a atenção do sátiro corruptor... O qual você deve eliminar!", t = "Os Bosquenero corrompidos"},
    [4767] = {ot = "Leve 10 Ovos de Mantícora de Alcândora para Elu, na Aldeia Vento Livre.", st = "Recebi a missão de recrutar mais mantícoras para os mestres de mantícoras. Tem cada vez mais por aí e eu espero me tornar um mestre de mantícoras também. O problema é que não temos mantícoras suficientes para atender à demanda de treinamento. Talvez você possa me ajudar, $n.$B$BPreciso que você viaje até Alcândora para coletar ovos de mantícora. Daqui, siga em direção noroeste ao longo das paredes do cânion até chegar a uma rampa que vai te levar até Alcândora. Mas tenha cuidado, mantícoras protegem seus ovos com unhas e dentes.", t = "Mantícora"},
    [4770] = {ot = "Escolte Pae'ka Monte Veloz para fora de Alcândora, depois converse com Motega Barba de Fogo, no Posto Confinalvo.", st = "Por favor, me ajude, $c. Estou escondido aqui em Alcândora há algum tempo e não vejo um rosto amigo há vários dias. Cheguei aqui para estudar as mantícoras e acho que acabei chegando perto demais. Depois de fugir correndo de um ninho, eu acabei me perdendo.$B$BPreciso voltar ao Posto Confinalvo. Motega não sabe que estou perdido e vai ficar furioso ao descobrir que entrei em Alcândora por conta própria.$B$BO Posto Confinalvo fica logo a leste daqui... me leve até lá, por favor!", t = "Vínculo fraterno"},
    [4811] = {ot = "Viaje para o leste de Auberdine e procure por um grande cristal vermelho na montanha leste da Costa Negra. Relate o que você descobriu à Sentinela Glynda Nal'Shea, em Auberdine.", st = "Luniscantes hostis vagam em grupos cada vez maiores a leste de nós. Acredita-se que já foram criaturas gentis, quase místicas. Tem gente que ainda os reverencia, mas, em nome da segurança de Auberdine, preciso adotar uma visão mais realista.$B$BRecebi relatos de que os luniscantes estão sendo atraídos para um grande cristal vermelho na montanha leste da Costa Negra. Ninguém faz a menor ideia do que seja esse cristal, nem mesmo se ele existe de verdade. Quero que você o localize e depois me relate o que descobriu.", t = "O cristal vermelho"},
    [4812] = {ot = "Encha o Tubo de Água Vazio no poço lunar de Auberdine, e depois investigue o cristal vermelho na encosta da montanha leste da Costa Negra.", st = "Use esta ampola vazia e encha com a água de algum poço lunar aqui em Auberdine. Uma magia poderosa como essa deve nos fornecer alguma pista sobre a composição do cristal. Para fazer isso, verta o líquido sobre o cristal e deixe acontecer naturalmente.$B$BDuvido que algo de mau possa acontecer com você, mas mesmo assim é melhor ter cuidado. Acima de nós, para o leste, fica a Selva Maleva. Se o cristal estiver vinculado a esse lugar, como acho que está, ele pode ser muito perigoso.", t = "Como cascatas"},
    [4813] = {ot = "Relate o que você descobriu à Sentinela Glynda Nal'Shea, em Auberdine.", st = "A água do poço lunar revelou que há pequenos fragmentos de ossos e metade de uma mandíbula incrustados no cristal. A mandíbula parece ser de um humanoide, mas não dá para ter certeza sem quebrar o cristal, uma tarefa quase impossível, mesmo com a magia mais poderosa.$B$BCom a tarefa cumprida, tudo o que resta fazer é falar novamente com a Sentinela Glynda Nal'Shea, em Auberdine.", t = "Fragmentos incrustados"},
    [4821] = {ot = "Leve o Ovo Alienígena a Hagar Casco de Raio, na Aldeia Vento Livre.", st = "Corre um boato em Mil Agulhas que um ovo alienígena apareceu por aqui. Todos que dizem ter visto o ovo não conseguiram nem chegar perto para examinar em detalhes. Tem serpentes protegendo o ovo como se fosse delas.$B$BQuero que você vá atrás desse ovo alienígena e traga para mim para que eu possa examiná-lo. Dizem que o ovo está guardado dentro de um ninho de serpentes, mas existem vários ninhos nas bases das encostas sul e nordeste da Aldeia Vento Livre.", t = "Ovo alienígena"},
    [4841] = {ot = "Mate 12 Batedores Galath, 10 Cavalgantes Galath e 6 Ventilhões Galath, depois fale novamente com o Vigia do Rochedo Chifre Longo na Aldeia Vento Livre.", st = "$n, eu lhe imploro: vá atrás desses centauros. Eles vão sentir a ira da nossa vingança. Ataque o acampamento centauro ao norte da Aldeia Vento Livre! Deixe a ira conduzir seus punhos!\n", t = "Pacifique o Centauro"},
    [4865] = {ot = "Relate suas descobertas a Motega Barba de Fogo.", st = "Se não tivesse visto com meus próprios olhos, eu nunca acreditaria. A vingança chegou a Mil Agulhas!$B$B<Hagar limpa a testa.>$B$B$n, você precisa agir rápido! Vá e procure por Motega Barba de Fogo, que está no Posto Confinalvo, que fica a noroeste da Aldeia Vento Livre, ao longo da estrada. Ele vai saber o que fazer.", t = "Selva da serpente"},
    [4881] = {ot = "Alerte Kanati Nuvem Cinzenta, no Posto Confinalvo, do plano para assassiná-lo.", st = "É muita audácia do tauren Kanati Nuvem Cinzenta transformar Mil Agulhas em área de caça. Temos que matá-lo para nos livrarmos dele e de possíveis seguidores. Vamos nos encontrar em um pequeno entreposto a sudoeste do Grande Elevador.\n", t = "Plano de assassinato"},
    [4904] = {ot = "Escolte Lakota Cantéolo para fora do Pináculo da Nuvem Negra e depois fale com Thalia Couro Âmbar, na Aldeia Vento Livre.", st = "Arnak achava que nós iríamos nos casar... mas depois que eu não aceitei o pedido ele foi atrás de mim, à noite, e me raptou. Meu irmão tentou impedi-lo, mas Arnak é forte demais. Ele... Ele matou o meu irmão e me trouxe para cá. Meu irmãozinho...$B$B$n, pode me escoltar para fora do Pináculo da Nuvem Negra? Por favor... preciso voltar para Thalia! Ele deve estar preocupadíssima comigo.", t = "Liberdade, liberdade"},
    [4921] = {ot = "Encontre a Mulher de Mankrik e depois fale novamente com ele na Encruzilhada.", st = "Estávamos em batalha em um acampamento taureno quando nos separamos. Ela conteve três Costagulhas sozinha, mas logo a desvantagem numérica cobrou seu preço. Consegui afastar alguns, mas vi que ela tinha sido cercada por novos atacantes. Em minha fúria, me voltei contra os inimigos, mas eram muitos e me derrubaram facilmente.$B$BAcordei com um druida tauren cuidando das minhas feridas. Ele me encontrou na Estrada do Ouro, onde caí.$B$BPor favor, $c, encontre algum sinal da minha mulher.", t = "Perdida em combate"},
    [4966] = {ot = "Proteja Kanati Nuvem Cinzenta do ataque dos centauros.", st = "Porém, se tiver mais centauros de que eu pensava, vou precisar que você, $n, lute comigo contra esses assassinos vis.", t = "Proteja Kanati Nuvem Cinzenta"},
    [5041] = {ot = "Encontre e devolva os Caixotes de Suprimentos da Encruzilhada a Thork, nos Sertões.", st = "A caravana atacada continha suprimentos de que precisávamos desesperadamente.$B$BVocê foi $Gcorajoso:corajosa; o suficiente para enfrentar a tribo Crinavalha até agora, e eu quero lhe pedir que faça isso de novo, mas, desta vez, queria saber também se você pode tentar encontrar alguns de nossos suprimentos perdidos. Provavelmente, você vai encontrá-los nos acampamentos daqueles javatuscos, que estão engordando com seus atos desonrosos.$B$BO povo da Encruzilhada ficará muito grato a você.", t = "Suprimentos para a Encruzilhada"},
    [5052] = {ot = "Leve um Estilhaço de Sangue para Denterroto no Acampamento Taurajo, que fica nos Sertões.$B$BColete mais Estilhaços de Sangue se você quiser que ele $Go:a; abençoe com o poder de Agamaggan.", st = "Junto com os espinhos, o sangue afetou <bufa> outros aspectos da terra: pedras vermelhas-sangue misturaram-se a outros minerais. Os Costagulha desenterravam esses estilhaços e os carregavam <bufa> para lhes dar força em batalha e como totens para suas magias. <bufa>$B$BEu conheço os segredos dessa magia.$B$BLeve a Denterroto um desses estilhaços de sangue para mostrar que você entende. Leve muitos fragmentos a Denterroto, e ele $Go:a; abençoará com magia de javatusco — a magia de Agamaggan! <bufa>", t = "Estilhaços de Sangue de Agamaggan"},
    [5061] = {ot = "Volte a Darnassus e mostre a Mathrengyl Ursivagus o Pingente do Leão Marinho.", st = "Você completou as lições necessárias que todos os jovens druidas aprendem antes poderem adotar um aspecto aquático. Vá reencontrar seu treinador, Mathrengyl Ursivagus, em Darnassus. Mostre-lhe o seu pingente e prove que você está $Gpreparado:preparada; para aprender o que ele tem para lhe ensinar. Ele completará seu treinamento, permitindo que você entre em harmonia com a água.$B$BAdeus, jovem $Gdruida:druidesa;. Nos encontraremos novamente.", t = "Forma aquática"},
    [5062] = {ot = "Reúna 10 punhados de Agave Incendia, depois consulte Magatha Temível Totem no Platô dos Anciãos, que fica no Penhasco do Trovão.", st = "Arikara é uma criatura letal, que deve ser eliminada rapidamente. Para caçá-la, você precisará acender o fogo da vida sagrado — isso evocará Arikara.$B$BAgora vá e colha a rara planta agave Incendia. Depois de ter colhido agave suficiente, busque o conselho de Magatha Temível Totem no Platô dos Anciãos, no Penhasco do Trovão. Ela é uma xamã poderosa, que pode encantar a planta agave para criar um pó para acender o fogo.$B$BSiga na direção nordeste até o Lagoa Fervente e colha agave incendia.", t = "Fogo sagrado"},
    [5064] = {ot = "Localize e recupere os três Bilhetes Secretos no Pináculo da Nuvem Negra.", st = "$n, você já nos prestou um grande serviço, por isso vou lhe confiar uma missão importante. O Clã Temível Totem está armando alguma. Três agentes de origem desconhecida visitaram os Temível Totem nas últimas semanas. Nós descobrimos que estão guardando as mensagens trocadas em baús no Pináculo da Nuvem Negra.$b$b$n, se você triunfar nesta missão perigosa, eu lhe darei uma recompensa à altura.", t = "Espiando os Temível Totem"},
    [5088] = {ot = "Mate Arikara. Leve seus restos mortais e o Pó de Incendia a Motega Barba de Fogo no Posto Confinalvo como prova do seu feito.", st = "Leve este Pó de Incendia refinado e purificado a Mil Agulhas e jogue-o no fogo sagrado da vida. Ele fica no Pináculo da Nuvem Negra, em uma agulha isolada onde eles enterram seus mortos.$B$BO encantamento que eu teci no pó de Incendia evocará Arikara até você, $n.$B$BInfelizmente, creio que ela esteja perseguindo Caerne Casco Sangrento. Muita coisa mudou na história dos taurens, e temo que isso tenha enfurecido Arikara. Aja rápido, antes que tudo esteja perdido, $c!", t = "Arikara"},
    [5147] = {ot = "Mate Arnak Temível Totem e leve uma prova de seu feito para o Vigia do Rochedo Chifre Longo, na Aldeia Vento Livre.", st = "Procura-se: Arnak Temível Totem$B$BArnak, o proscrito, é procurado pelos crimes hediondos de assassinato e sequestro. Uma bela recompensa aguarda aquele que for corajoso o suficiente para trazer esse criminoso à justiça.$B$BArnak foi visto pela última vez nos penhascos perto do Pináculo da Nuvem Negra. Quem levar uma prova do feito para o Vigia do Rochedo Chifre Longo, na Aldeia Vento Livre, receberá a recompensa.", t = "PROCURA-SE: Arnak Temível Totem"},
    [5151] = {ot = "Mate a fera e traga de volta o Dispositivo Hipercapacitador e a Chave da Jaula da Pantera para Vizlo Limpajunta.", st = "Eu fui o único sobrevivente do ataque dos centauros à caravana! Minha traquitana mais valiosa tá protegida por uma pantera rara e muito forte, bem no pescocinho do bicho. Ha! Até os centauros se tremem todos na presença daquela fera selvagem!$B$BTá aqui a chave da jaula. Eles levaram tudo, mas deixaram o bichano em paz. Mata o bicho e traz meu hipercapacitador, que eu te dou um salve.$b$bA caravana tá logo ao norte, toda estropiada.\n", t = "Dispositivo hipercapacitador"},
    [5261] = {ot = "Fale com Enzo Peleteiro.", st = "O Enzo Peleteiro está atrás de alguém que vá caçar lobos. É uma boa notícia, porque tem aparecido muitos lobos no Vale de Vila Norte ultimamente.$B$BSe tiver interesse, vá falar com o Enzo. Ele se acha à esquerda da abadia.", t = "Enzo Peleteiro"},
    [5321] = {ot = "Escolte Kerlonian Perenumbra até Liladris Luneflúvia pela estrada sul para encontrar a bolsa dele na Costa Negra.", st = "Eu estava a caminho do Entreposto de Maestra para encontrar Liladris Luneflúvia, mas decidi parar aqui para tirar um cochilo. Desde que despertei do Sonho Esmeralda, ando muito sonolento...\n\n<Bocejo>\n\nE eu não acho minhas coisas em lugar nenhum! Você poderia me ajudar a procurar?\n\nPelo que sei, o Entreposto de Maestra fica ao sul, ao longo da estrada do Vale Gris. Eu vinha de lá...\n\nAh, e pode ser que eu caia no sono! Se precisar me acordar, é só tocar minha corneta. Ela está ali no baú.", t = "A adormecida despertou"},
    [5441] = {ot = "Use o Cassetete do Encarregado nos Peões Preguiçosos enquanto estiverem dormindo. Acorde 5 peões, depois devolva o Cassetete do Encarregado ao Encarregado Thazz'ril, no Vale das Provações.", st = "Malditos peões! Eles trabalham duro cortando lenha das árvores do vale, mas vivem cochilando! Preciso que alguém me ajude a manter os peões na linha.$B$BVocê parece $go:a; $r cert$go:a; para essa tarefa. Aqui, pegue este cassetete e use ele nos peões preguiçosos que você encontrar dormindo durante o expediente. Uma boa cacetada e eles voltarão ao trabalho! Devolva o cassetete quando você terminar.$B$BEssas porcarias de peões preguiçosos...", t = "Peões preguiçosos"},
    [5481] = {ot = "Colha 3 Ervas-do-emo e entregue para o Boticário-júnior Hollanda, no cemitério de Montalvo.", st = "Mestre querer ervas. Nós ter mão grande e não conseguir pegar direito. Você ajuda nós e nós não machuca você. Nós precisa de ervas-do-emo. Ter muita aqui, muita perto de estrada.$b$bPega erva-do-emo e leva pro mestre Hollanda no cemitério de Montalvo.\n", t = "Beijo do Gordo"},
    [5482] = {ot = "Colha 10 Ervas-do-demo e entregue para o Boticário-júnior Hollanda.\n", st = "Você entende o aperto em que estou, $n? Aquela coisa imprestável saiu para colher a erva errada! Farei com que valha a pena se você trouxer o que eu preciso. Traga erva-do-demo em quantidade suficiente e eu lhe darei uma recompensa adequada.$B$BPelo que sei, essa erva infesta a flora perto da sepultura coletiva, ao norte do cemitério de Montalvo. Apresse-se e tome cuidado com os gnolls na área.", t = "Erva-do-demo"},
    [5541] = {ot = "Entregue a Munição do Estremetiro para Hegnar Estremetiro em Dun Morogh.", st = "Hegnar Estremetiro tem uma loja de armas na estrada para Sidermar. Vários carabineiros e lançadores de morteiro costumam treinar perto da loja; portanto, o Hegnar sempre está precisando de mais munição.$B$BMas... o último carregamento de munição que enviei para o ele se perdeu no caminho. O entregador contou que estava acampado perto do Covil Cinzento quando foi atacado por wendigos... E largou a carga para trás!$B$B$n, você poderia pegar a munição de volta e entregá-la para o Estremetiro? Ele está esperando por essa remessa e tenho certeza de que o estoque já deve estar no final.", t = "Sem munição não tem negócio"},
    [5545] = {ot = "Leve 8 Feixes de Madeira para Raquel na Madeireira Vale do Leste.", st = "Estou com uma grande encrenca nas mãos. Tenho madeira pra entregar e o prazo está ficando apertado... Os lobos e ursos a norte daqui espantaram os meus trabalhadores, e agora tem um monte de madeira já cortada lá sem ninguém pra coletar.$B$BJá falei com o delegado Ranieri sobre abater os animais, mas ainda preciso que alguém vá lá pegar a madeira pra mim. Se você coletasse oito feixes de madeira pra mim, eu conseguiria cumprir meus prazos.", t = "Um feixe de encrenca"},
    [5621] = {ot = "Encontre a Sentinela Shaya e cure suas feridas usando Cura Inferior (Grau 2). Depois disso, conceda a ela Palavra de Poder: Fortitude e fale novamente com Laurna Luzalbor em Dolanaar.", st = "Preciso da sua ajuda, $n. Precisam de mim aqui para treinar outros alunos, mas você pode ajudar uma de nossas Sentinelas, que se feriu patrulhando a cidade. Ela está logo ao sul de Dolanaar. O nome dela é Shaya.$B$BQuando encontrá-la, cure as feridas dela, depois fortifique o corpo dela com seus feitiços. Isso vai protegê-la pelo menos um pouco mais contra ferimentos caso ela encontre problemas. Fale novamente comigo depois que tiver cumprido seu dever para com Eluna.", t = "Vestes da lua"},
    [5622] = {ot = "Fale com Laurna Luzalbor em Teldrassil.", st = "$n, você precisa viajar para Dolanaar quando seu dever aqui em Umbravale tiver terminado. Lá, você encontrará Laurna Luzalbor, que lhe ensinará mais sobre o caminho de Eluna, e é com ela que você receberá suas primeiras vestes indicando o seu posto como $Gsacerdote:sacerdotisa; de Eluna.$B$BCuide-se, e que suas jornadas sejam sempre seguras.", t = "Em favor de Eluna"},
    [5623] = {ot = "Fale com a Sacerdotisa Joselita na Floresta de Elwynn.", st = "Olá de novo, jovem $Gsacerdote:sacerdotisa;. Chegou a hora de você aprender mais sobre a nossa religião. Depois que você tiver completado suas tarefas aqui em Vila Norte, procure a Sacerdotisa Joselita na Vila d'Ouro. Ela tem mais a lhe ensinar e está ciente de que você tem ficado cada vez mais forte no caminho da Luz. Ela está ansiosa para lhe ensinar mais coisas.", t = "Em favor da Luz"},
    [5624] = {ot = "Encontre a Guarda Roberts e cure suas feridas usando Cura Inferior (Grau 2). Depois disso, conceda a ele Palavra de Poder: Fortitude e fale novamente com a Sacerdotisa Joselita em Vila d'Ouro.", st = "Geralmente, eu proponho um pequeno desafio para que os seguidores da Luz testem suas habilidades. Eu quero ver se eles são dignos de usar suas primeiras vestes — um sinal de que a igreja aprova publicamente $Go sacerdote:a sacerdotisa; e lhe dá apoio.$B$BMas esta situação é um pouco diferente. Um dos cidadãos da Vila d'Ouro viu um guarda ferido perto do lago a leste daqui. O nome dele é Roberts. Encontre-o e cure-o, fortifique seu corpo e volte aqui. Se você puder fazer isso por mim, considerarei seu teste completo.", t = "Vestes da Luz"},
    [5625] = {ot = "Encontre o Montanhista Dolf e cure suas feridas usando Cura Inferior (Grau 2). Depois disso, conceda a ele Palavra de Poder: Fortitude e fale novamente com Maxan Begurno em Kharanos.", st = "É mais ou menos a essa altura que costumamos testar pessoas com o seu poder para ver se são dignas de usar as vestes que denotam seu lugar na igreja. Mas a questão é que tenho coisas mais urgentes para tratar. Um cidadão de Kharanos acabou de vir aqui me contar que um montanhista se feriu ao sul da cidade, um tal de Dolf.$B$BSe você curar o Dolf e conceder Fortitude a ele, considerarei sua prova concluída. O que você acha?", t = "Vestes da Luz"},
    [5626] = {ot = "Fale com Maxan Begurno em Dun Morogh.", st = "Ei, $n! Tem um minuto?$B$BJá faz algum tempo que tu tem seguido a Luz, o suficiente pra tu procurar o Maxan Begurno em Kharanos. Ele vai te ensinar mais sobre o caminho que tu está seguindo e, se provar ser $Gdigno:digna;, vai te dar suas primeiras vestes pra te identificar como $Gum sacerdote:uma sacerdotisa;.$B$BAgora, vai-te $Gligeiro:ligeira;! Assim que tiveres terminado aqui, atravessa o túnel — ele vai estar te esperando.", t = "Em favor da Luz"},
    [5629] = {ot = "Fale com a Sacerdotisa Alathea em Darnassus.", st = "Olá, $n. Sei que está $gocupado:ocupada; e que muito ajuda nosso povo, mas também precisa de um tempo para si $gmesmo:mesma;. A sacerdotisa Alathea mandou alguém aqui para $gprocurá-lo:procurá-la;. Parece-me que seus atos chamaram a atenção dos anciãos e eles acham que você está $gpronto:pronta; para atos maiores. Vá ao Templo da Lua de Darnassus e procure Alathea. Ela $go:a; aguarda. Boa sorte, $n, que Eluna guie seus passos.", t = "O retorno ao lar"},
    [5634] = {ot = "Fale com o Sumo Sacerdote Rohan em Altaforja.", st = "Não há muito tempo, um sacerdote esteve em nossos salões à sua procura, jovem $r. Ele disse que estava em uma missão para encontrá-$Glo:la; e que você precisava retornar ao Salão dos Mistérios, em Altaforja, o mais rápido possível. Quando chegar, procure o sumo sacerdote Rohan e ele informará melhor.$B$BQue a Luz esteja convosco, $n.", t = "Prece desesperada"},
    [5641] = {t = "Castigar"},
    [5642] = {ot = "Fale com Ur'kyo em Orgrimmar.", st = "Algo importante está acontecendo em Orgrimmar, $n.$B$BOs mensageiros que passam por aqui procurando sacerdotes trolls geralmente são mais relaxados. Dessa vez, eles pareceram bem mais apressados. Não se demore muito no Penhasco do Trovão. Se eu fosse você, retornaria para o Vale dos Espíritos assim que possível.", t = "Guarda Sombria"},
    [5644] = {ot = "Fale com Aelthalyste na Cidade Baixa.", st = "Ah, um ótimo dia para você, $n. Acho que, pelas lições que você aprendeu, já é hora de enviá-l$go:a; a Aelthalyste. Há coisas que apenas ela pode ensinar a você, e mesmo assim apenas se você seu merecimento.$B$BNão vou estragar a surpresa, mas me lembro de quando eu era um jovem sacerdote aprendendo sobre o poder verdadeiro... o poder divino. Bons tempos...$B$BBom, volte a falar com Aelthalyste na Cidade Baixa, $n. Ela estará a sua espera no Distrito Bélico.", t = "Sacrifício sombrio"},
    [5648] = {ot = "Encontre a Bruta Kor'ja e cure suas feridas usando Cura Inferior (Grau 2). Depois disso, conceda a ela Palavra de Poder: Fortitude e fale novamente com Tai'jin no Monte Navalha.", st = "Te prepara pro teu primeiro teste, $n. Ao sul do Monte Navalha, logo saindo da cidade, uma de nossas brutas, Kor'ja, se feriu lutando com alguns velhos soldados do Proudmore. Ela não tá nada bem, e seria muito útil pra ela se alguém como você a ajudasse. Acha ela, cura as feridas dela e dê a ela a bênção dos nossos ancestrais.$B$BSe tu fizer isso, pra mim, já vai ser prova suficiente de que tu tá $Gpronto:pronta; pra seguir o teu próprio caminho.", t = "Vestes da espiritualidade"},
    [5649] = {ot = "Fale com Tai'jin em Durotar.", st = "É, cara. Nossa raça se juntou à Horda porque eles foram bons pra gente. Eles são leais e nos ensinam muita coisa bacana, como honra. Mas nossos velhos costumes são persistentes. Os orcs podem não aprovar todas as nossas tradições, mas isso não significa que não podemos praticar algumas delas em segredo.$B$BTu sabe disso, e é por isso que eu tô te mandando pra falar com a Tai'jin no Monte Navalha. Ela vai te ensinar mais sobre a nossa história. Ela vai te ensinar sobre os caminhos da nossa tribo. Vai procurar ela quando estiver $Gpronto:pronta;.", t = "Em favor da espiritualidade"},
    [5650] = {ot = "Encontre o Necroguarda Querêncio e cure suas feridas usando Cura Inferior (Grau 2). Depois disso, conceda a ele Palavra de Poder: Fortitude e fale novamente com Clérigo das Trevas Beryl em Montalvo.", st = "Nosso poder vem da escuridão e das sombras, $n, mas seu papel não se restringe a isso. Você reconhece que existe mérito em conhecer as artes de cura. Isso é sábio. Mas, antes que você possa conhecer as trevas, deve conhecer também a luz. E, por isso, eu tenho um teste para você.$B$BAo norte do cemitério, há um necroguarda — Querêncio é o nome dele — que nos protegeu dos gnolls por um tempo e agora precisa de cura. Mas você também precisa fortificar seu corpo para que ele possa retomar sua tarefa. Use os dois feitiços, depois, venha falar comigo novamente.", t = "Vestes da escuridão"},
    [5651] = {ot = "Fale com o Clérigo das Trevas Beryl nas Clareiras de Tirisfal.", st = "A experiência ensinou muitas lições aos Renegados — coisas que algumas raças nem sonham em compreender. E, embora o nosso caminho resida na escuridão, você descobrirá que muitas coisas grandiosas dependem tanto da luz quanto das trevas. Seus estudos lhe ensinarão a usar ambos... e com discrição. Mas escute bem o que lhe digo: nunca se esqueça de que fomos forjados pela corrupção e deixados para apodrecer como carniça. A escuridão é o nosso lar.$B$BProcure o Clérigo das Trevas Beryl em Montalvo quando estiver $Gpronto:pronta; para aprender mais.", t = "Em favor da escuridão"},
    [5654] = {ot = "Fale com Ur'kyo em Orgrimmar.", st = "Tá na hora de você conhecer o Ur'kyo, $n. Ele tá no Vale dos Espíritos, na cidade dos orcs. Vai até lá e fala com ele. Tá na hora de você aprender mais sobre a antiga tradição da nossa raça. Tá na hora de você ser $Gconduzido:conduzida; ao círculo e se tornar $Gum verdadeiro sacerdote:uma verdadeira sacerdotisa; para a nossa tribo.", t = "Bagata da Fraqueza"},
    [5658] = {t = "Toque de Fraqueza"},
    [5672] = {t = "A graça de Eluna"},
    [5676] = {t = "Fluxo arcano"},
    [5713] = {ot = "Proteja a Sentinela Aynasha. Em seguida, fale com Onaeya no Entreposto de Maestra, que fica no Vale Gris.", st = "Eu estava levando uma mensagem importante a Auberdine quando fui atacada por Marosh e seu grupo de mateiros pelursos. Fui envenenada na luta e mal consigo ficar de pé. Eu sei fazer um antídoto, mas leva algum tempo para ficar pronto.$B$BVocê poderia me proteger até que eu possa usar o antídoto? Darei o melhor de mim para $Gajudá-lo:ajudá-la; com meu arco.$B$BSe sobrevivermos, levarei a mensagem a Auberdine enquanto você vai para o Entreposto de Maestra avisar a Onaeya sobre este incidente.", t = "Um tiro, uma morte"},
    [5722] = {ot = "Investigue as Cavernas Ígneas em busca do corpo de Mauren Temível Totem e procure quaisquer itens de interesse.", st = "Os troggs não são a única coisa que interessa a Magatha nas Cavernas Ígneas. Ela foi informada que um de seus servos, Mauren Temível Totem, encontrou uma coisa peculiar nas Cavernas, mas não conseguiu sair com vida para mostrar a ela o que era. Ela quer que encontrem o corpo de Mauren — se ele ainda existir — e qualquer sinal do que ele encontrou enquanto tentava falar com os troggs.$B$BDevolva a Magatha quaisquer itens de interesse, e tenho certeza de que ela lhe dará uma recompensa generosa.$B$BMais uma vez, procure as Cavernas nas áreas mais escuras de Orgrimmar.", t = "Em busca da algibeira perdida"},
    [5723] = {ot = "Procure as Cavernas Ígneas em Orgrimmar e mate 8 Troggs Iraflama e 8 Xamãs Iraflama, depois fale novamente com Rahauro no Penhasco do Trovão.", st = "Debaixo da cidade de Orgrimmar, criaturas corpulentas conhecidas como troggs começaram a emergir de túneis repletos de lava. Em sua enorme benevolência, Magatha tentou firmar um acordo de paz com as criaturas, mas elas atacaram os diplomatas, matando-os. Magatha não aceita esse tipo de tratamento para com o povo tauren e agora considera as criaturas uma ameaça a toda a Horda.$B$BMagatha pede que você coloque um fim nessa ameaça antes que a Horda seja subjugada a partir das profundezas. Encontre as Cavernas Ígneas e destrua todos os troggs.", t = "Testando a força do inimigo"},
    [5724] = {ot = "Leve a Algibeira do Temível Totem para Rahauro no Penhasco do Trovão.", st = "Você encontrou uma algibeira debaixo do corpo do tauren. Ele ainda a está segurando firmemente com os braços, como se estivesse tentando protegê-la durante o ataque dos troggs.$B$BDepois de remover a algibeira das mãos enrijecidas como aço do tauren, você a guarda junto com o seu equipamento e se prepara para deixar os túneis e reencontrar Rahauro no Penhasco do Trovão.", t = "Devolvendo a algibeira perdida"},
    [5725] = {ot = "Leve os livros \"Feitiços da Sombra\" e \"Encantamentos do Éter\" para Varimatras na Cidade Baixa.", st = "Muitos integrantes da Legião dão presentes para seus seguidores, como você deve saber. Alguns desses presentes, a Dama Sombria acha que estariam melhor nas mãos dela, em vez de nas de pessoas com... visão inferior.$B$BUma seita do Concílio das Sombras que fica escondida nas cavernas sob Orgrimmar e é conhecida como Lâmina Calcinante é um exemplo ideal. A Grande Dama me informou que membros da Lâmina Calcinante se apossaram de dois poderosos livros de feitiços — e ela gostaria de \"tomar emprestados\" esses livros. Vá buscá-los para ela.", t = "O poder de destruir..."},
    [5726] = {ot = "Leve uma Insígnia do Tenente para Thrall em Orgrimmar.", st = "Uma coisa que eu não tolero é traidores entre nós, $n. Mas seria tolice eu fazer a minha jogada tão cedo — além de não extirpar suficientemente a corrupção de nossas terras, isso faria a infecção crescer ainda mais.$B$BMas $Gum jovem aventureiro:uma jovem aventureira; como você pode ir a lugares que meus agentes não podem... pode descobrir a verdade... pode encontrar a verdadeira cabeça da besta.$B$BSe você for valente o bastante, entre na Rocha da Caveira a leste de Orgrimmar, encontre a insígnia de um tenente da Lâmina Ardente lá e traga-a para mim.", t = "Inimigos ocultos"},
    [5727] = {ot = "Leve a Insígnia do Tenente para Neeru Cortafogo e fale com ele. Avalie se ele acredita que você é um membro da Lâmina Ardente e, depois, fale novamente com Thrall em Orgrimmar.", st = "Agora, vamos ver se esta insígnia que você encontrou vale o esforço.$B$BTem um bruxo na cidade que acredita ter a minha confiança. Ele não sabe que estou plenamente ciente de sua lealdade fajuta. Na verdade, ele é o líder da Lâmina Ardente. Mas não se apresse em confrontá-lo — ele tem um propósito, e vamos usá-lo contra os nossos inimigos.$B$BLeve esta insígnia para o Antro das Sombras, aqui em Orgrimmar, entregue-a ao Neeru e veja se ele acredita que você é um membro da Lâmina Ardente. Depois, volte aqui.", t = "Inimigos ocultos"},
    [5728] = {ot = "Mate Bazzalan e Jergosh, o Invocador e fale novamente com Thrall em Orgrimmar.", st = "Hum, líderes da Lâmina Calcinante... isso é muito preocupante. Se eles têm valor para Neeru, então, devem ser nosso primeiro alvo. Esse sátiro... Bazzalan e o outro que Neeru mencionou — ele era o que mesmo, um bruxo? — devem ser eliminados.$B$BVolte para o Antro das Sombras e entre nas Cavernas Ígneas, $n. Encontre esses dois líderes da Lâmina Calcinante e mate-os. Mas tome cuidado para que Neeru não descubra que foi você quem fez isso. Você precisa manter seu disfarce de $Girmão:irmã; de armas.", t = "Inimigos ocultos"},
    [5729] = {ot = "Fale com Neeru Cortafogo em Orgrimmar.", st = "Acho que o nosso próximo passo deveria ser colocar você mais próximo de Neeru. Se ele estiver tão abalado quanto os relatórios sugerem, talvez seja possível matarmos dois vermingues com uma cajadada só. Primeiro, você poderá obter informações valiosas sobre o Concílio ou, pelo menos, sobre a Lâmina Ardente; segundo, ele pode começar a confiar em você o bastante para começar a pedir sua assistência. É provável que ele veja você como alguém capaz de preencher a lacuna, agora que a liderança dele está agitada.$B$BVolte ao Antro e fale com ele novamente, mas seja $Gdiscreto:discreta;.", t = "Inimigos ocultos"},
    [5730] = {ot = "Fale com Thrall em Orgrimmar e conte a ele o que você descobriu.", st = "Você é $Gum dos meus:uma das minhas; tenentes! Prepare-se, $c. Vou precisar de você em breve.$B$BO tempo que eu passei na Lâmina Calcinante pode não ter sido de muita valia, mas isso não significa que o os esquemas do Concílio das Sombras em outros lugares devam sofrer. Farei o que for possível para minimizar o dano aqui nas Cavernas Ígneas. Enquanto isso, mandarei meus agentes nos Sertões e no Vale Gris começarem a trabalhar a nossa agenda. Venha falar comigo de novo em breve.", t = "Inimigos ocultos"},
    [5761] = {ot = "Entre nas Cavernas Ígneas e mate Taragaman, o Famélico, depois leve o coração dele para Neeru Cortafogo em Orgrimmar.", st = "A primeira tarefa que o grande Chefe Guerreiro me outorgou é extirpar as criaturas responsáveis por infestar com sua influência demoníaca a gloriosa cidade do meu senhor. A Lâmina Ardente é uma ameaça, mas existem outras — a Lâmina Calcinante, por exemplo, que habita as Cavernas Ígneas, tentando, secretamente, corromper membros inocentes da Horda.$B$BSe quisermos detê-los, temos que matar o líder deles, um Guarda Vil chamado Taragaman, o Famélico.$B$BMate-o e traga seu coração — Thrall ficará muito satisfeito, tenho certeza.", t = "Mate a besta"},
    [5881] = {ot = "Maggran quer que você entregue uma carta a Grish Pisaléguas no Grande Elevador, que fica nos Sertões.", st = "A Horda faz bem em manter nossas tropas bem descansadas. Desde a Grande Guerra, prosperamos aqui em Kalimdor.$B$BPreciso de um favor seu: um jovem chamado Grish Pisaléguas está protegendo o Grande Elevador no sul dos Sertões. Dê esta carta a ele; a carta o informará de que um guerreiro reserva meu está a caminho para rendê-lo, de maneira que ele possa visitar a família. Já faz algum tempo que ele me pediu isso, e é provável que ele fique feliz com a notícia.", t = "Chamando as reservas"},
    [5921] = {ot = "Use o feitiço \"Teleporte: Clareira da Lua\" para viajar para a Clareira da Lua. Ao chegar, fale com Dendrite Stellardor, no vilarejo de Refúgio Noturno.", st = "Todos os druidas são bem-vindos nas terras sagradas da Clareira da Lua, a despeito das tensões no Círculo Cenariano entre o Arquidruida Guenelmo e Remulos, o guardião da Clareira da Lua. Agora que você está aprendendo o caminho da Garra, vou ensinar o feitiço para que você se teletransporte para lá. Lance o feitiço sempre que precisar da sabedoria ou do apoio da Clareira da Lua$B$BPara a sua primeira missão, viaje para a Clareira da Lua e fale com Dendrite Stellardor, no Refúgio Noturno, sobre o caminho que você está trilhando agora. Boa sorte, jovem druid$Ga:esa;.", t = "Clareira da Lua"},
    [5922] = {ot = "Use o feitiço \"Teleporte: Clareira da Lua\" para viajar para a Clareira da Lua. Ao chegar, fale com Dendrite Stellardor, no vilarejo de Refúgio Noturno.", st = "Todos os druidas são bem-vindos nas terras sagradas da Clareira da Lua, tanto taurens quanto elfos noturnos. Remulos, o Guardião da Clareira da Lua, cuida de todos os druidas que lá hibernam. Agora que você está aprendendo o caminho da Garra, vou ensinar o feitiço para que você se teletransporte para lá. Lance o feitiço sempre que precisar da sabedoria ou do apoio da Clareira da Lua$B$BPara a sua primeira missão, viaje para a Clareira da Lua e fale com Dendrite Stellardor, no Refúgio Noturno, sobre o caminho que você está trilhando agora. Boa sorte, jovem druid$Ga:esa;.", t = "Clareira da Lua"},
    [5923] = {ot = "Fale com Mathrengyl Ursivagus no Enclave Cenariano, em Darnassus.", st = "Com licença, amig$Go:a;...$B$BChegou ao meu conhecimento que Mathrengyl Ursivagus deseja falar com você. Parece que sua formação como $Gdruida:druidesa; tomará um novo rumo, pois ele treinará você pessoalmente. Mathrengyl é o assistente imediato do próprio Arquidruida e é um dos druidas mais sábios e veneráveis de Teldrassil.$B$BVocê pode encontrá-lo no Enclave Cenariano de Darnassus, no segundo nível da árvore de Fandral Guenelmo.", t = "Atendendo o chamado"},
    [5928] = {ot = "Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão.", st = "Com licença, amig$Go:a;...$B$BChegou ao meu conhecimento que Turak Runa Totem deseja falar com você. Parece que sua formação como $Gdruida:druidesa; tomará um novo rumo, pois ele treinará você pessoalmente. Turak é um dos assistentes do Arquidruida. É reconhecido por sua sabedoria e paciência, e deve lhe ensinar bem.$B$BVocê pode encontrá-lo no Penhasco do Trovão, dentro da tenda principal do Círculo Cenariano, no Platô dos Anciãos.", t = "Atendendo o chamado"},
    [5929] = {ot = "Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua.", st = "Na região noroeste da Clareira da Lua encontra-se a casa de um ser sábio e nobre que chamamos de Espírito do Grande Urso. Ele tem servido como tutor e mentor para todos os druidas em busca da primeira verdadeira compreensão natural do que é o urso. Todos os druidas em determinado momento buscam a sabedoria do espírito, e você não será exceção.$B$BVá ao Espírito do Grande Urso agora e aprenda o que ele tem a lhe ensinar. Quando ele tiver terminado, fale novamente comigo aqui no Refúgio Noturno. E então veremos se você compreendeu verdadeiramente as lições que ele ensina.", t = "Espírito do Grande Urso"},
    [5930] = {ot = "Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua.", st = "Na região noroeste da Clareira da Lua encontra-se a casa de um ser sábio e nobre que chamamos de Espírito do Grande Urso. Ele tem servido como tutor e mentor para todos os druidas em busca da primeira verdadeira compreensão natural do que é o urso. Todos os druidas em determinado momento buscam a sabedoria do espírito, e você não será exceção.$B$BVá ao Espírito do Grande Urso agora e aprenda o que ele tem a lhe ensinar. Quando ele tiver terminado, fale novamente comigo aqui no Refúgio Noturno. E então veremos então se você compreendeu verdadeiramente as lições que ele ensina.", t = "Espírito do Grande Urso"},
    [5931] = {ot = "Volte a Darnassus e fale com Mathrengyl Ursivagus no Enclave Cenariano.", st = "Chegou a hora de nos separarmos, jovem, já que a prática das lições leva você de volta àquele que $Go:a; enviou a mim. Mathrengyl Ursivagus caminha em verdadeiro equilíbrio com a natureza, ainda que more perigosamente perto de onde o equilíbrio se desbalanceou. Ouça as instruções dele, e em breve você completará suas primeiras lições no papel de proteto$Gr:ra; do equilíbrio.$B$BVá agora, jovem. Nós voltaremos a nos encontrar.", t = "De volta a Darnassus"},
    [5932] = {ot = "Volte ao Penhasco do Trovão e fale com Turak Runa Totem no Platô dos Anciãos.", st = "Chegou a hora de nos separarmos, jovem, já que a prática das lições leva você de volta àquele que $Go:a; enviou a mim. Embora os taurens sejam considerados jovens nos caminhos de Cenarius, Turak Runa Totem caminha com muito equilíbrio na presença da natureza. Ouça as instruções dele, e em breve você completará suas primeiras lições no papel de proteto$Gr:ra; do equilíbrio.$B$BVá agora, jovem. Nós voltaremos a nos encontrar.", t = "De volta ao Penhasco do Trovão"},
    [6001] = {ot = "Aplique Poeira de Lua Cenariana na Pedra Luniscante de Auberdine para trazer Lunagarra. Então, enfrente Lunagarra e ganhe a força de corpo e coração que ele possui.$B$BFale com Mathrengyl Ursivagus em Darnassus quando você terminar.", st = "À leste de Auberdine, há muitas cavernas luniscantes. Dentro da que fica mais perto de Auberdine, há uma Pedra Luniscante. Lunagarra, o defensor da pedra, só enfrentará você quando a Poeira de Lua Cenariana for aplicada à pedra. Lunagarra possui dentro de si uma força que você deve usar como $Gum dos:uma das; Garras.$B$BVocê ganhou o direito de usar esta Poeira de Lua Cenariana, $n... agora me mostre que você conquistou o direito de possuir a força do corpo e do coração necessárias como $Gdruida:druidesa;!", t = "Corpo e coração"},
    [6002] = {ot = "Aplique Poeira Lunar Cenariana na Pedra Luniscante entre Mulgore e os Sertões para evocar Lunagarra. Então, enfrente Lunagarra e ganhe a força de corpo e coração que ele possui.$B$BFale com Turak Runa Totem no Penhasco do Trovão quando terminar.", st = "Nas terras a oeste de Taurajo, nos Sertões — pouco antes de darem lugar a Mulgore —, há uma Pedra Luniscante. Os luniscantes são criaturas especiais, não nativas dessas bandas. Lunagarra, o defensor da pedra, enfrentará você quando Poeira Lunar Cenariana for aplicada à pedra. Lunagarra possui dentro de si uma força que você deve usar como $Gum dos:uma das; que trilham o caminho da Garra.$B$BVocê ganhou o direito de usar esta Poeira de Lua Cenariana, $n... agora mostre-me que você conquistou o direito de possuir a força de corpo e coração necessária como $Gdruida:druidesa;!", t = "Corpo e coração"},
    [6061] = {ot = "Use o Bastão de Adestramento para domar um Pinote Adulto. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Yaw Crina Cortante na Aldeia Casco Sangrento.", st = "Como um tauren, é importante lutar contra criaturas poderosas para seguir as tradições de nossos ancestrais. Ao vencer essas criaturas, podemos incorporar seus espíritos, permitindo uma aproximação maior com a Mãe Terra.$B$BDa mesma forma, domar uma fera para lutar ao nosso lado ajuda a nos integrarmos à natureza ao nosso redor. Uma hora, você aprenderá a domar a fera que escolher. Mas todas as coisas exigem prática e você tem muito a aprender. Tome este bastão de adestramento. Para começar, você precisa domar um pinote adulto.", t = "Domando a fera"},
    [6062] = {ot = "Use o Bastão de Adestramento para domar uma Mosquetusco Hediondo. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Thotar no Monte Navalha.", st = "É uma habilidade admirável impor sua autoridade sobre a natureza. Como caçado$Gr:ra;, você deve aprender a usar a força e o poder inerentes a qualquer criatura que escolha.$B$BControlar um animal não é tarefa fácil. É preciso encará-la com muita determinação.$B$BComo primeira tarefa, pegue este bastão de adestramento e use-o para domar um mosquetusco hediondo. Você pode encontrá-los bem perto do Monte Navalha. Pratique suas habilidades em batalha com o moquetusco ao seu lado, depois fale novamente comigo.", t = "Domando a fera"},
    [6063] = {ot = "Use o Bastão de Adestramento para domar uma Tocaieira Lenhateia. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Dazalar em Dolanaar.", st = "Como $Gcaçador:caçadora;, é importante lembrar a responsabilidade que você tem em mãos. A natureza não é um poder que possa ser forçado a atender nossos desejos — deve ser respeitado e reconhecido como algo mais forte do que nossa própria existência.$B$B$n, você deve provar que compreende isso antes de ganhar a habilidade de domar um animal para ser seu ajudante.$B$BA primeira coisa a fazer é pegar este bastão de adestramento. Com ele, você será capaz de domar uma tocaieira lenhateia. Dome-a e pratique suas habilidades como $Gcaçador:caçadora;.", t = "Domando a fera"},
    [6064] = {ot = "Use o Bastão de Adestramento para domar uma Rochetusco Grande. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Grif Selvacuore em Kharanos.", st = "Olá, $Gguri:guria;! Então tu estás se perguntando como pode ganhar seu próprio ajudante, tchê?$B$BBem, vamos começar. Não há nada mais importante do que o equipamento quando se trata de caça, mas podemos conversar sobre o meu novo Trabuco de Estilhaços outra hora. No momento, vamos nos concentrar em algo que tenho certeza de que tu estás bastante interessad$Go:a;: um animal ajudante!$B$BA melhor maneira de escolher é experimentar várias criaturas como mascote e ver de qual tu mais gosta. Então encontre um rochetusco grande e use o bastão de adestramento para domá-lo.", t = "Domando a fera"},
    [6081] = {ot = "Fale com Ormak Tiroatroz em Orgrimmar.", st = "Agora você tem o poder de domar um ajudante, mas também precisa aprender a treiná-lo.$B$BVá a Orgrimmar. Lá, procure Ormak Tiroatroz, um dos nossos caçadores mais respeitados. Ele lhe ensinará a treinar seu novo ajudante. Você vai encontrá-lo perto do Salão dos Valentes.$B$BBoa sorte, $n.", t = "Treinando a fera"},
    [6082] = {ot = "Use o Bastão de Adestramento para domar um Escorpídeo Encouraçado. Pratique sua habilidade e depois fale novamente com Thotar no Monte Navalha.", st = "Você deveria se espelhar na última criatura que terá que domar: o escorpídeo encouraçado. Ele ataca com velocidade e confiança. Dominar tal criatura é o seu destino de caçado$Gr:ra;.$B$BQuando você voltar, eu transmitirei a você o conhecimento de que você precisará para domar o animal que você escolher. A criatura ficará sob seu comando. Seu mascote ganhará experiência ao seu lado. Também mostrarei como chamá-lo e dispensá-lo quando quiser.\n", t = "Domando a fera"},
    [6083] = {ot = "Use o Bastão de Adestramento para domar uma Surfatisco. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Thotar no Monte Navalha.", st = "A vantagem que um animal ajudante lhe oferece contra seus rivais é bem clara, $n. Quando você ganha controle sobre outra criatura, aumenta a própria força. Seu ajudante deve se tornar uma extensão de você mesmo.$B$BA tarefa seguinte exigirá que você se afaste da terra, pois vai encontrar a próxima criatura nas águas da costa. Do outro lado da Aldeia Sen'jin, perto das Ilhas do Eco. Procure um caranguejo espirituoso chamado surfatisco. Use o bastão de adestramento para domá-lo e depois pratique suas habilidades.", t = "Domando a fera"},
    [6084] = {ot = "Use o Bastão de Adestramento para domar uma Leopardo da Neve. Pratique sua habilidade e depois fale novamente com Grif Selvacuore em Kharanos.", st = "Bah, esses rochetuscos são bastante corpulentos. Talvez tu prefira um animal com um pouco mais de finesse? Está bem, então, acho que tenho a fera certa para ti. A sul e leste daqui, tu vai encontrar grandes felinos brancos chamados leopardos da neve. Assim como um rifle elegantemente esculpido, por trás de seu belo exterior há um poderoso guerreiro capaz de causar danos extremos. Tu descobrirá que eles são muito mais ágeis e rápidos do que o rochetusco que domaste, tchê.$B$BPegue este bastão de adestramento e veja se você gosta do leopardo das neve.", t = "Domando a fera"},
    [6085] = {ot = "Use o Bastão de Adestramento para domar um Urso Garra de Gelo. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Grif Selvacuore em Kharanos.", st = "Vai ver tu tá atrás de uma criatura que possua algo além de força bruta. O urso garra de gelo é um excelente ajudante pra $Gum caçador novato:uma caçadora novata;, é um bicho que vive a leste de Kharanos. Aqui o bastão de adestramento. Experimenta esse mascote pra ver se te agrada!$B$BQuando tu voltar, eu te transmitirei o conhecimento de que tu vai precisar pra domar o animal que tu escolher. A criatura enfrentará os mesmos desafios que tu, e ganhará experiência ao seu lado. Também vou mostrar como chamar e dispensar ela quando te der na telha.\n", t = "Domando a fera"},
    [6086] = {ot = "Fale com Bélia Granitrondo em Altaforja.", st = "$n, agora tu já tens capacidade pra domar um mascote, mas ainda precisa de habilidade pra treinar o bicho.$B$BVai para Altaforja e procura o Salão das Armas. Lá, é só trocar uma palavra com Bélia Granitrondo, uma das nossas domadoras de feras mais respeitadas. Ela vai te ensinar a treinar teu mascote. Anda, te apressa gur$Gi:ia;!$B$BBélia é camarada que só, na certa que vai gostar de ti. Boa sorte, $n.\n", t = "Treinando a fera"},
    [6087] = {ot = "Use o Bastão de Adestramento para domar um Espreitador-da-pradaria. Pratique sua habilidade e depois devolva o Bastão a Yaw Crina Cortante na Aldeia Casco Sangrento.", st = "Você tem um espírito forte, $Gcaçador:caçadora;, preparado para o seu próximo desafio.$B$BA próxima tarefa é conquistar a companhia de um lobo conhecido como espreitador-da-pradaria. Essa criatura é veloz e destemida. Para fazer dessa fera sua ajudante, você também deve assumir essas qualidades.$B$BDurante uma batalha, você aprenderá como formar uma equipe com seu ajudante. Por fim, vocês deverão trabalhar como se fossem um, músculo com músculo.$B$BAqui está o bastão de adestramento, $n. Domine um espreitador-da-pradaria e pratique suas habilidades.", t = "Domando a fera"},
    [6088] = {ot = "Use o Bastão de Adestramento para domar uma Rapineiro. Pratique sua habilidade e depois devolva o Bastão a Yaw Crina Cortante na Aldeia Casco Sangrento.", st = "A última tarefa que tenho para você é domar uma criatura do céu. O rapineiro é um adversário difícil, mas quando for seu aliado, você herdará dele os ataques ferozes e a presença ameaçadora.$B$BSe a Mãe Terra assim quiser, quando você voltar, eu transmitirei a você o conhecimento de que você precisará para domar o animal que você escolher para ser seu ajudante. A criatura enfrentará os mesmos desafios que você, e ganhará experiência ao seu lado. Também mostrarei como chamá-lo e dispensá-lo quando quiser.\n", t = "Domando a fera"},
    [6089] = {ot = "Fale com Holto Chifre Troante no Platô dos Caçadores, que fica no Penhasco do Trovão.", st = "Agora você tem o poder de domar um ajudante, mas também precisa aprender a treiná-lo.$B$BVá até o Penhasco do Trovão. Fale com Holto Chifre Troante, um dos nossos caçadores mais respeitados. Se achar que você está à altura, ele lhe ensinará a treinar seu novo ajudante.$B$BHolto sobrepujou a mais poderosas e temidas feras de Azeroth, e agora tem sob seu controle muitas criaturas de grande força. Os laços que ele mantém com a Mãe Terra são profundos, portanto há muito o que aprender com ele. Boa sorte, $n.\n", t = "Treinando a fera"},
    [6101] = {ot = "Use o Bastão de Adestramento para domar um Espreitador Sabre-da-noite. Treine sua perícia, e depois devolva o Bastão de Adestramento a Dazalar em Dolanaar.", st = "A variação na natureza é algo com que se pode contar, $n. Ela é previsível no sentido de jamais permanecer igual, de estar sempre em mudança.$B$BAs tarefas que eu lhe dou $go:a; ajudarão a ver e apreciar as vastas diferenças das criaturas você pode escolher como ajudantes.$B$BLeve este bastão de adestramento e use para domar um espreitador sabre-da-noite, ao sul daqui. Treine sua perícia de caçador$go:a;. Então você começará a entender as similaridades e diferenças da natureza.", t = "Domando a fera"},
    [6102] = {ot = "Use o Bastão de Adestramento para domar uma Guinchadora Estrígida. Treine sua perícia, e depois devolva o Bastão de Adestramento a Dazalar em Dolanaar.", st = "Você domou duas criaturas da terra, e agora precisa domar uma que voe pelos céus. Use o bastão de adestramento para domar uma guinchadora estrígida, das que vivem a oeste daqui. Treine sua perícia com essa coruja poderosa a seu lado.$B$BQuando você voltar, eu transmitirei a você o conhecimento de que você precisará para domar o animal que você escolher para ser seu ajudante. A criatura enfrentará os mesmos desafios que você, e ganhará experiência ao seu lado. Também mostrarei como chamá-lo e dispensá-lo quando quiser.", t = "Domando a fera"},
    [6103] = {ot = "Fale com Jocasta no Enclave Cenariano, que fica em Darnassus.", st = "Agora você tem o poder de domar um ajudante, mas também precisa obter a habilidade de treiná-lo.$B$BVá a Darnassus. Lá você terá que falar com Jocasta, uma das nossas caçadoras mais respeitadas. Ela lhe ensinará a habilidade de treinar seu novo ajudante, então se apresse.$B$BEmbora Jocasta possa parecer severa, ela fica sempre feliz ao ver outr$go:a; caçado$gr:ra; subindo na carreira. Trate-a com respeito e ela retribuirá. Boa sorte, $n.", t = "Treinando a fera"},
    [6121] = {ot = "Vá à Clareira da Lua e fale com Dendrite Stellardor no vilarejo de Refúgio Noturno.", st = "Agora você está pront$go:a; para aprender sobre venenos e o poder que nós druidas temos sobre eles, $n. Cenarius nos abençoou com a habilidade de purgar os mais torpes venenos com um simples encanto. Esse dom não é nada trivial. E, para garantir que você aprenda essa lição, você cuidará dos efeitos de envenenamentos como o fariam os leigos.$B$BVá à Clareira da Lua e fale com Dendrite Stellardor. Ele está à sua espera para dar sua aula.", t = "Novas lições"},
    [6122] = {ot = "Use o Coletor Vazio das Quedas de Fontescarpa para coletar uma amostra de água da entrada da caverna da cachoeira.$B$BEntregue o Coletor Cheio das Quedas de Fontescarpa para Alanndária Noturcanto em Auberdine, na Costa Negra.", st = "As Quedas do Fontescarpa, na Costa Negra, são a principal fonte de água potável da região, e agora eu suspeito que seja a principal fonte do veneno que está prejudicando a fauna local, especificamente os cervos. Use esse coletor para trazer um pouco de água da entrada da caverna, mas tome cuidado. Agora há nagas perigosas vivendo na caverna.$B$BQuando terminar, entregue a Alanndária Noturcanto, em Auberdine. Foi ela que pediu nossa ajuda, e é com ela que você trabalhará para tratar esse mal.", t = "A fonte principal"},
    [6123] = {ot = "Leve 5 Raízes-telúricas e 12 Fungos Lunares para Alanndária Noturcanto em Auberdine para que ela possa preparar o bálsamo curativo.", st = "A água servirá como base do bálsamo curativo para os cervos. Pelas propriedades curativas, preciso de um pouco de raiz telúrica. Os herboristas sabem como encontrar. Se formos azarad$go:a;s e você não for herborista, você precisará achar alguém que nos ajude.$B$BE por fim, para dar fortalecer, preciso de fungo lunar. É fácil achar floresceres fúngicos; as cavernas a leste daqui são repletas deles. No entanto, moram luniscantes lá, e eles andam irritadiços ultimamente. Tome cuidado.", t = "Colhendo a cura"},
    [6124] = {ot = "Use o Bálsamo Curativo para Animais em 10 Cervos Adoentados espalhados pela Costa Negra. Isso deve curá-los. Cervos Adoentados foram avistados da região ao sul do Rio Fontescarpa, seguindo até a área ao norte de Auberdine, até a Costa Negra meridional, na fronteira do Vale Gris.", st = "A quantidade de bálsamo feita com os reagentes que você me trouxe dá para dez doses, $n. Enquanto eu trabalho aqui com a vila para tentar fazer mais bálsamo, eu gostaria que você adiantasse parte do trabalho. Há cervos doentes por toda a Costa Negra. Dê o bálsamo a eles e cure esse mal.$B$BTenho certeza de que Dendrite Stellardor deve querer conversar com você lá na Clareira da Lua quando você terminar. Transmita também ao Círculo Cenariano os agradecimentos de Auberdine, e... Permita-me agradecer a você diretamente pela ajuda que você nos prestou!", t = "Curando os doentes"},
    [6125] = {ot = "Fale novamente com Mathrengyl Ursivagus no Enclave Cenariano, em Darnassus.", st = "Você aprendeu o que é curar venenos sem se beneficiar de ajuda espiritual. Lembre-se do que os outros precisam suportar ao enfrentar a aflição dos venenos enquanto abraça seu novo poder sobre eles.$B$BAgora você deve falar novamente com Mathrengyl Ursivagus em Darnassus, $n. Sem dúvida ele terá um feitiço importante a lhe ensinar agora que $go:a; estudante entende as lições que recebe.$B$BAdeus, jovem druid$ga:esa;. Nós nos encontraremos de novo.", t = "O poder sobre os venenos"},
    [6181] = {ot = "Mostre o Bilhete do Ludovico a Thor, o mestre de grifos.", st = "Nós não obtemos muito suporte diretamente de Ventobravo, mas tenho um contato lá que nos ajuda com os suprimentos de armaduras. O nome dele é Larso Norde. A loja dele, \"Imunidade Limitada\", fica na Cidade Velha, em Ventobravo.$B$BNosso estoque de armaduras está no fim, e preciso contatar Osric e encomendar mais. Você pode levar esse bilhete pra ele?$B$BO jeito mais rápido de chegar em Ventobravo é falando com nosso mestre de grifos, o Thor. Ele fica ali embaixo, descendo a colina; leve meu bilhete para ele e pegue um grifo para Ventobravo.", t = "Mensagem rápida"},
    [6261] = {ot = "Leve o Caixote de Larso para Dungar Tragolongo, o mestre de grifos.", st = "$n, eu pus aqui nesse caixote tudo o que Ludovico pediu. Você pode entregar para ele?$B$BSe você já conversou com Thor em Cerro Oeste, então você pode pegar um grifo e voltar pra lá. Dungar Tragolongo é o mestre de grifos lá no distrito comercial.$B$BFale com Dungar e leve esse caixote para Ludovico o mais rápido possível. Não queremos que nossos homens e mulheres lutando em Cerro Oeste fiquem sem equipamento.", t = "Dungar Tragolongo"},
    [6281] = {ot = "Compre uma passagem de grifo do mestre de grifos Thor, e leve o Bilhete do Ludovico para Larso Norde na loja Imunidade Limitada, que fica na Cidade Velha, em Ventobravo.", st = "Por uma taxa módica, você pode ir de grifo para Ventobravo e entregar o bilhete de Ludovico para Larso. É a maneira mais rápida de chegar lá.$B$BSe você quiser fazer negócio, fale novamente comigo quando estiver $gpronto:pronta; pra partir. Vai custar um pouco, mas acredite, vai valer a pena!", t = "Siga para Ventobravo"},
    [6282] = {ot = "Maggran Ata Terra, no Retiro Rocha do Sol, quer que você mate 7 Hapias Furissague, 7 Emboscadoras Furissangue, 7 Matadoras Furissangue e 7 Plumerrantes Furissangue.", st = "Os taurens têm orgulho de serem os protetores destas terras. Sem dúvida, você consegue imaginar por que estou tão alarmado com o número de harpias que vivem aqui nas Torres de Pedra.$B$BAs furissangues são a fonte do crescente número de harpias em Kalimdor. Elas avançam sobre tudo que vive, impedindo que os inocentes deixem seu domínio.$B$BPreciso que você abata as harpias, $n!", t = "Harpias ameaçadoras"},
    [6283] = {ot = "Maggram, no Retiro Rocha do Sol, quer que você mate a Estripadora Furissangue e traga os restos mortais dela como prova de seu feito.", st = "Limitar o número de harpias furissangue não será o bastante. A única cura real para a doença que elas são seria matar a líder delas, a Estripadora Furissangue!$B$BEla é tudo, exceto uma rainha para aquelas criaturas imundas. Mate-a e é certo que as fileiras delas diminuirão.$B$BVolte ao Vale Carbonizado e você a encontrará nas colinas a oeste. Não será fácil eliminá-la, mas a recompensa será vultuosa.", t = "O sangue das Furissangue"},
    [6284] = {ot = "Mate Besseleth e leve a Presa de Besseleth a Maggran no Retiro Rocha do Sol.", st = "Alerta: Adentre o Desfiladeiro Sishir, a oeste, por sua própria conta e risco.$B$BBesseleth e sua prole octópode proclamaram esta cordilheira seu lar.$B$BMaggran Ata Terra, no Retiro Rocha do Sol, está oferecendo uma recompensa por Besseleth. Mate-a e leve uma prova de que você a eliminou a Maggran. Assim você receberá sua recompensa por exterminar essa ameaça.", t = "Aracnofobia"},
    [6285] = {ot = "Compre uma passagem para o Morro da Sentinela do mestre de grifos Dungar Tragolongo. Em seguida, leve o Caixote de Larso para Ludovico, no Morro da Sentinela.", st = "O mestre de grifos de Cerro Oeste é o Thor. Se você já o conhece, pode ir de grifo até ele.$B$BNão se esqueça disto: os grifos são treinados para chegar à capital, mas eles só $Go:a; levarão para lugares mais remotos se você já tiver estado lá antes e falado com o tratador local.$B$BVocê já conhece o Thor, então é só falar comigo de novo quando quiser pegar um grifo para Cerro Oeste. Chegando lá, entregue o Caixote de Larso ao Intendente Ludovico.", t = "Entrega para Ludovico"},
    [6301] = {ot = "Tammra Campo de Vento, no Retiro Rocha do Sol, quer que você colete 10 Sementes de Gaia.", st = "A ganância industrial e a guerra contínua arrasaram as terras das Torres de Pedra. Apenas as bênçãos da Mãe Terra podem curar tamanha ferida.$B$B$n, preciso que você procure uma semente especial, a semente de Gaia. Elas só existem aqui nas Torres de Pedra, ao norte do Retiro Rocha do Sol, próximo às margens do Lago Mirkfallon.$B$BUma vez que você me tenha trazido as sementes, eu as imbuirei com poder xamanístico para acelerar seu crescimento.", t = "Ciclo de renascimento"},
    [6321] = {ot = "Leve as Ordens do Rodrigo para Carlos Razok.", st = "O Executor Hadrec me pediu para inventariar nosso equipamento aqui no Sepulcro. Com o Flagelo e outras coisas ainda piores lá na floresta, ele não quer que os necroguardas fiquem desguarnecidos.$B$BNo geral, nós estamos bem supridos, mas é bom pedirmos mais armas para substituir as que perdemos em campo.$B$BAqui está uma lista de pedidos com tudo de que precisamos, que deve ser entregue ao mercador de armas Antônio Nunes, na Cidade Baixa. Mostre a lista para nosso tratador de morcegos, Carlos Razok, e fale com ele sobre como chegar na Cidade Baixa.", t = "Suprimentos para o Sepulcro"},
    [6322] = {ot = "Leve o Caixote do Antônio até Miguel Garreta.", st = "Eu coloquei os suprimentos para o Sepulcro nesse caixote. Se você já visitou o Sepulcro e falou com o tratador de morcegos local, então pode pegar um morcego de volta até ele.$B$BFale com o tratador de morcegos da Cidade Baixa, Miguel Garreta. Ele poderá lhe arranjar um morcego para o Sepulcro.", t = "Miguel Garreta"},
    [6323] = {ot = "Adquira uma viagem de morcego até a Cidade Baixa com o tratador de morcegos Carlos Razok. Em seguida, leve as Ordens do Rodrigo para Antônio Nunes, na Cidade Baixa.", st = "Um dos meus morcegos pode levar você para a Cidade Baixa por uma tarifa módica. Fale comigo assim que estiver $gpronto:pronta; e eu cuidarei do seu transporte.$B$BAntônio Nunes fica no Centro Comercial da Cidade Baixa. É lá que meus morcegos pousam.", t = "Carona para a Cidade Baixa"},
    [6324] = {ot = "Adquira um voo de morcego para o Sepulcro do tratador de morcegos Miguel Garreta, depois entregue o Caixote do Antônio para o Necroguarda Rodrigo, no Sepulcro.", st = "O tratador de morcegos no Sepulcro se chama Carlos Razok. Se você já a conheceu, então poderei arranjar um voo de morcego até ele.$B$BNossos morcegos sempre voam até a Cidade Baixa, mas para ir a locais mais distantes você deve primeiro visitar a área e falar com o tratador de morcegos local.$B$BVocê conheceu Carlos no Sepulcro, então pode voar para lá. Avise-me quando estiver $Gpronto:pronta; para partir.", t = "Fale novamente com Rodrigo"},
    [6341] = {ot = "Leve a Coleção de Nessa para Vesprystus.", st = "Os pescadores de Rut'theran vão muito bem, obrigado. Os peixes daqui são grandes e abundantes. Eu gostaria de comparar o butim daqui com o do continente.$B$BTenho um a colação de ossos e escamas de peixe que gostaria de levar para um colega meu da Costa Negra. Ele se chama Laird e é peixeiro na cidade de Auberdine.$B$BLeve a minha coleção para o nosso mestre de hipogrifos, Vesprystus, e fale com ele sobre a viagem a Auberdine.", t = "O butim de Teldrassil"},
    [6342] = {ot = "Viaje de hipogrifo para Auberdine com o mestre de hipogrifos Vesprystus, depois leve a Coleção de Nessa para Laird.", st = "Tem duas formas de viajar de Rut'theran para Auberdine: de balsa ou de hipogrifo. As duas são rápidas e confiáveis, mas, se você ainda não voou para Auberdine de hipogrifo, sugiro que o faça.$B$BMeu com conselho é: fale com o mestre de hipogrifos em todas as cidades em que houver um. Depois de falar com o mestre, você pode voar de uma cidade a outra.$B$BAqui está a coleção de Nessa. Fale comigo novamente quando estiver pront$Go:a; para voar para Auberdine e entregar a coleção de Nessa a Laird.", t = "Voo para Auberdine"},
    [6343] = {ot = "Leve a Resposta de Laird para Nessa Cantonegro.", st = "Preciso mandar uma resposta para Nessa. Ele vai ficar muito interessada na grande diferença entre os peixes daqui e os encontrados no litoral de Teldrassil. Só posso especular, mas imagino que a Árvore do Mundo esteja afetando a fauna em torno dele.$B$BLeve essa resposta para Nessa. Se quiser pegar um hipogrifo de volta para Rut'theran, fale com o mestre de hipogrifos Caylais Plumaluna. Se quiser pegar a balsa, tem uma que sai em horários regulares das docas a noroeste.", t = "Resposta para Nessa"},
    [6344] = {ot = "Fale com Nessa Cantonegro.", st = "Uma amiga minha, Nessa Cantonegro, é mercadora de peixes na Vila de Rut'theran. Ela precisa entregar uma encomenda na Costa Negra e está procurando alguém para ajudá-la.$B$BSe for do seu interesse, para falar com Nessa você precisa cruzar o portal de Darnassus para a Vila de Rut'theran. O portal fica a oeste dos Jardins do Templo.", t = "Nessa Cantonegro"},
    [6361] = {ot = "Leve o Pacote de Peles para o mestre de mantícoras Devrak, na Encruzilhada.", st = "Tenho um pacote de peles de animais dos Sertões que precisa chegar ao Penhasco do Trovão. Um colega de lá, Ahanu, vai usar as peles para criar artigos em couro.$B$BVocê pode levar as peles para ele?$B$BO modo mais rápido de chegar ao Penhasco do Trovão é nas costas de uma mantícora. Leve o pacote de peles para Devrak, o mestre de mantícoras da Encruzilhada, e fale com ele sobre o transporte para o Penhasco do Trovão.", t = "Um pacote de peles"},
    [6362] = {ot = "Pegue uma mantícora com o mestre de mantícoras Devrak e leve o Pacote de Peles para Ahanu, no Penhasco do Trovão.", st = "Por um preço módico, eu lhe forneço uma mantícora para o Penhasco do Trovão. É o modo mais rápido de chegar à cidade!$B$BSe o valor for aceitável, fale comigo novamente quando estiver $Gpronto:pronta; para partir.$B$BSe as peles forem para Ahanu, creio que ele está no Arsenal de Hewa, que fica na base da torre das mantícoras do Penhasco do Trovão. E é lá mesmo que você vai pousar!", t = "Voo para o Penhasco do Trovão"},
    [6363] = {ot = "Leve os Artigos em Couro do Ahanu para Tal no Penhasco do Trovão.", st = "Confeccionei artigos em couro para Jahan vender na Encruzilhada. Você os leva para ele?$B$BSe já tiver ido à Encruzilhada e falado com o mestre de mantícoras, você pode voar de volta em uma das mantícoras do Penhasco do Trovão.$B$BLeve os artigos em couro para Tal, o mestre de mantícoras do Penhasco do Trovão, e peça transporte para a Encruzilhada.", t = "Tal, o Mestre de Mantícoras"},
    [6364] = {ot = "Pegue uma mantícora para a Encruzilhada com o mestre de mantícoras Tal e leve os Artigos em Couro do Ahanu para Jahan Asa de Falcão.", st = "Para poder voar até uma cidade, é preciso ter estado lá e falado com o mestre de mantícoras daquela cidade. Você já esteve na Encruzilhada e falou com o mestre de mantícoras Devrak. Então, por um preço módico, você pode levar uma mantícora daqui até ele.$B$BFale comigo novamente quando estiver $gpronto:pronta;. Quando chegar à Encruzilhada, você pode entregar os artigos em couro para Jahan Asa de Falcão.", t = "Fale novamente com Jahan"},
    [6365] = {ot = "Leve as Carnes de Zargh para Devrak, na Encruzilhada.", st = "Quero mandar alguns cortes de carne especiais para uma amiga. A Gryshka, que é a estalajadeira de Orgrimmar. Você poderia entregar essa encomenda para mim?$B$BO jeito mais rápido de chegar lá é voando de mantícora. Leve os cortes de carne até Devrak, o mestre de mantícoras da Encruzilhada, e fale com ele sobre como chegar a Orgrimmar.", t = "Encomenda para Gryshka"},
    [6381] = {ot = "Plante 10 Sementes de Gaia em Montículos de Terra de Gaia e, então, devolva as Sementes Encantadas de Gaia restantes a Tammra, no Retiro Rocha do Sol.", st = "Como você bem viu, $c, apesar do sofrimento da terra, o ciclo da vida é algo poderoso. Agora, devemos fazer a nossa parte. Você deve plantar estas sementes no centro da destruição, a oeste, no Vale Carbonizado. Tenha cautela, pois harpias e elementais do fogo enfurecidos infestam aquela terra maculada.$B$B$n, pegue estas sementes encantadas de Gaia e plante-as em montículos de solo fértil. O ciclo da vida não pode parar!", t = "Vida nova"},
    [6382] = {ot = "Fale com Senani Coração Trovejante no Posto Machadada, que fica no Vale Gris.", st = "Sua força me impressiona, $c. Sua vontade de abraçar a caça me dá confiança de que você pode enfrentar tarefas mais difíceis... e vencê-las.$B$BAs florestas do Vale Gris representam uma região selvagem indomada, sobre a qual a Horda pretende impor sua vontade, política e espiritualmente. Se quiser provar seu valor em uma terra de provações, busque os conselhos de Senani Coração Trovejante, no Posto Machadada. O posto avançado fica ao norte do caminho que tem ligação com os Sertões.", t = "A caçada do Vale Gris"},
    [6383] = {t = "A Caçada do Vale Gris"},
    [6384] = {ot = "Pegue uma mantícora para a Orgrimmar com o mestre de mantícoras Devrak, depois leve as Carnes de Zargh para Orgrimmar.", st = "Por apenas algumas moedas, posso botar você numa mantícora para Orgrimmar. Ao chegar lá, entregue as carnes do Zargh para a Gryshka. A estalagem dela fica no Vale da Força, que fica perto da Torre Celeste, onde a minha mantícora vai deixar você.$B$BMe procure de novo quando estiver $Gpronto:pronta; para partir.", t = "Carona para Orgrimmar"},
    [6385] = {ot = "Entregue a Carta de Gryshka para Doraso em Orgrimmar.", st = "Escrevi uma carta de agradecimento para o Zargh. Você poderia entregá-la para mim? Se você já tiver ido a Encruzilhada e falado com o mestre de mantícoras local, então já pode pegar uma mantícora de volta para lá.$B$BLeve minha carta até Doraso, o mestre de mantícoras de Orgrimmar, e pergunte como chegar à Encruzilhada.", t = "Doraso, o mestre de mantícoras"},
    [6386] = {ot = "Pegue uma mantícora para a Encruzilhada com o mestre de mantícoras Doraso e leve a Carta de Gryshka para Zargh, na Encruzilhada.", st = "Minhas mantícoras são treinadas para voar a vários lugares, desde que o passageiro já tenha estado no destino e falado com o mestre de mantícoras local.$B$BComo você já esteve na Encruzilhada e já falou com o mestre de mantícoras Devrak, pode voar direto daqui para lá. E, ao chegar, entregue a carta de Gryshka para Zargh.$B$BFale comigo quando você estiver $Gpronto:pronta; para ir.", t = "Retorno à Encruzilhada"},
    [6387] = {ot = "Leve a Lista de Brock para Thorgrum Borrelson, em Thelsamar.", st = "Tem um monte de jovens anões batendo à minha porta, todos famintos para aprender o ofício da mineração. E se há uma coisa de que um mineiro precisa, é uma picareta!$B$BTenho aqui uma relação de estudantes de mineração que foram bem nas aulas e por isso serão homenageados com uma picareta de honra. Entregue essa lista para Golnir Topadão em Altaforja. Ele é o fornecedor das picaretas.$B$BO jeito mais rápido de ir até Altaforja é voando de grifo. Então, leve a lista para Thorgrum Borrelson, nosso mestre de grifos, e converse com ele sobre como chegar à capital.", t = "Alunos brilhantes"},
    [6388] = {ot = "Entregue as Picaretas Honorárias para Grif Trovino em Altaforja.", st = "Aqui estão as picaretas de honra para os alunos do Brock. Se você já esteve em Thelsamar, então pode pegar um grifo de volta para lá!$B$BLeve as picaretas para nosso mestre de grifos, Grif Trovino, e peça a ele uma carona de volta para Kharanos.", t = "Grif Trovino"},
    [6391] = {ot = "Compre um voo de grifo para Altaforja do mestre de grifos Thorgrum Borrelson. Chegando lá, entregue a Lista de Brock para Golnir Topadão.", st = "Por algumas moedas, um dos meus grifos pode levar você até Altaforja. Quando chegar lá, entregue a lista de Brock para Golnir Topadão. Você o encontrará na Guilda de Mineração Montanhas Profundas, que fica no Distrito da Grande Forja, bem perto de onde o grifo vai te deixar!$B$BMe procure de novo quando estiver $Gpronto:pronta; para a viagem.", t = "Carona para Altaforja"},
    [6392] = {ot = "Compre um voo de grifo para Thelsamar do mestre de grifos Grif Trovino. Chegando lá, entregue as Picaretas Honorárias para Brock Buscapedra.", st = "Por uma módica quantia você pode pegar um grifo de volta para Thelsamar... Desde que já tenha estado lá. Os grifos só levam você a lugares aonde você já foi. Então, lembre-se de falar com todos os mestres de grifos que encontrar para depois poder voar até eles.$B$BComo você já falou com Thorgrum, o mestre de grifos de Thelsamar, pode voar até ele. Ao chegar lá, entregue a encomenda de Brock Buscapedra.$B$BMe avise quando estiver $Gpronto:pronta; para partir.", t = "Fale novamente com Brock"},
    [6393] = {ot = "Leve 10 Incenderitas a Tsunomem no Retiro Rocha do Sol.", st = "O Tribunal das Marés me enviou para travar uma guerra contra os elementais do fogo nas Torres de Pedra. Neptulon, o Caçador das Marés, senhor de todos elementais da água, está especialmente interessado em ver nossos primos flamejantes apagados.$B$B$n, você pode me ajudar a ganhar a confiança do Tribunal destruindo os elementais do fogo no Vale Carbonizado. Quando destruídos, os elementais do fogo deixam incenderitas. Traga-as a mim para receber uma recompensa.", t = "Guerra elemental"},
    [6394] = {ot = "Leve a Picareta de Thazz'ril para o Encarregado Thazz'ril.", st = "$n, você é $gum:uma; $r confiável. Posso contar com você para mais uma tarefa?$B$BAlgum tempo atrás, eu estava inspecionando a caverna ao norte em busca de minerais e deixei a minha picareta para trás. Depois, quando voltei para buscá-la, descobri que a caverna estava cheia de feras cruéis! Você pode ir lá no Covil da Lâmina Ardente para buscar a minha picareta?$B$BEu a deixei em uma câmara com quedas d'água. A minha picareta tem um feitiço que a faz brilhar no escuro, então encontrá-la não será problema... o problema é o que está guardando ela!", t = "A picareta de Thazz'ril"},
    [6395] = {ot = "Leve os Restos de Saulo Mitos para o Túmulo de Marla, depois fale novamente com a Noviça Elvira.", st = "Minha amiga Marla Mitos era casada com Saulo Mitos. Quando a peste veio, Saulo sucumbiu e se juntou ao Flagelo.$B$BMarla escapou da morte-viva, mas acabou assassinada pelas mãos do marido transformado em ser irracional. Só que o amor dos dois era tão forte que o último desejo dela foi ser enterrada ao lado de seu amado Saulo.$B$BSaulo Mitos vaga por um acampamento arruinado à beira da estrada nordeste de Plangemortis. Derrote-o e realize o último desejo de Marla: enterre-o na cova dela, na primeira fileira do nosso cemitério.", t = "O último desejo de Marla"},
    [6401] = {ot = "Conte a boa notícia a Tammra Campo de Vento no Retiro Rocha do Sol.\n", st = "Conte a boa notícia a Tammra Campo de Vento, tia de Kaya, que está no Retiro Rocha do Sol! Kaya está viva! Nós achamos que ela tinha sucumbido ao ataque brutal contra nossa aldeia. Siga a trilha a oeste para chegar ao Retiro Rocha do Sol.\n\n", t = "Kaya está viva"},
    [6421] = {ot = "Explore as profundezas da caverna na Ravina da Avalanche e colete 10 Cristais de Ressonita para que Mor'rogal, no Retiro Rocha do Sol, os analise.", st = "Algo está errado aqui nas Torres de Pedra. Você sente a tensão no ar, $n?$B$BA sudeste daqui, na Ravina da Avalanche, fica uma profunda caverna. Os kobolds de lá estão minerando freneticamente um cristal raro chamado ressonita. Preciso que você colete algumas amostras do minério para que eu possa entender o que está acontecendo na caverna. Também preciso que você investigue as áreas mais profundas de lá.$B$BVá, jovem $c. É imperativo que eu saiba que mal espreita sob estas montanhas.", t = "Ravina da Avalanche"},
    [6441] = {ot = "Consiga 16 Chifres de Sátiro para Pixel no Posto Machadada.", st = "Fala aí! Eu estava passando pelo Vale Gris, indo pra Vila Catraca, e resolvi dar uma paradinha aqui no Machadada. Eu estou sempre de olho nas oportunidades, e parece que a demanda por chifre de sátiro na Vila Catraca anda bem alta.$B$BFiz umas perguntinhas aqui e ali, e descobri que os chifres dos sátiros da Trilha da Noite, de Satyrnaar e de Xavian são exatamente o que eu tô procurando. Só que eu não dou conta de sátiros grandões assim... Mas você parece ser do tipo que consegue dar conta de uns bichos desses!$B$BO negócio é o seguinte: você arruma os chifres e eu pago à altura do perrengue.", t = "Chifres de Sátiro"},
    [6442] = {ot = "Entregue 20 Cabeças de Iracauda a Marukai, na Praia de Zoram.", st = "O mal está à espreita na costa, $r.$B$BLá jazem as ruínas da cidade de Zoram, destruída e submersa pelas águas há muito tempo, desaparecida e quase esquecida.$B$BAgora as nagas voltaram, e o porquê ainda não sabemos. Mas pouco importa: temos que defender as terras que lutamos tanto para conquistar.$B$BVolte aqui trazendo vinte cabeças de naga! Mande as nagas de volta para as profundezas, de onde jamais deveriam ter saído!", t = "Nagas na Praia de Zoram"},
    [6461] = {ot = "Xen'Zilla, em Malaka'Jin, precisa que você mate 10 Rastejadoras de Fundolimo e 7 Cospeçonhas de Fundolimo.", st = "A gente aqui, os trolls de Malaka'jin, tira a nossa prosperidade da terra, cara. A Cordilheira das Torres de Pedra tem uma caça ótima, e a gente come bem e tal.$B$BMas pô, de uns tempos pra cá vêm aparecendo uns convidados barra pesada pro jantar... As aranhas tão atacando os nossos acampamentos de noite pra roubar a nossa caça.$B$BSe tu ajudar a matar esses bichos sinistros, o pessoal aqui em Malaka'Jin vai ficar te devendo uma. As aranhas tão por toda parte nas Torres de Pedra. É só seguir pro noroeste pra ver do quê que eu tô falando.", t = "Fome sangrenta"},
    [6462] = {ot = "Entregue 8 Patuás Troll para Mitsuwa, no Assentamento Zoram'gar.", st = "Minha família viajou para Zoram'gar levando muitos patuás sagrados, mas os pelursos Pelocardo mataram todos antes de chegarem ao destino! Malditos pelursos!$B$BEstou com saudade dos meus irmãos e irmãs que morreram, mas sei que nós vamos nos ver de novo no outro mundo. O problema é o valor dos patuás neste mundo aqui. É um absurdo que eles estejam nas mãos de pelursos!$B$B$n, você tem que pegar os patuás de volta! Os pelursos guardaram todos dentro de baús no Covil dos Pelocardo, uma caverna no final da Aldeia dos Pelocardo, que fica a norte de Astranaar.", t = "Patuá troll"},
    [6481] = {ot = "Abra o esquife de ressonita com o Cristal de Ressonita Encantado e, então, mate Goggeroc. Fale novamente com Mor'rogal levando as notícias e o Cristal de Ressonita Encantado.", st = "Você descobriu uma ameaça sombria para esta terra, $c. O esquife de ressonita que você encontrou naquela caverna abriga um terrano adormecido chamado Goggeroc.$B$BAlterei a composição dos cristais de ressonita que você coletou com meus poderes xamanísticos. Leve o cristal de ressonita encantado e quebre o esquife de ressonita.$B$BGoggeroc estará enfraquecido ao despertar... Mate-o, $n!", t = "O terrano se ergue"},
    [6482] = {ot = "Escolte Ruul e, em seguida, fale com Yama Casco de Neve, no Posto Machadada.", st = "Hein? Quem é você?$B$B$n? Você não é pelurso. Eles são uns malditos! Acharam que eu fosse um urso e me pegaram, e agora estão me matando de fome! Estou ficando muito fraco...$B$BMe ajude a fugir daqui, e depois fale com minha irmã, Yama, no Posto Machadada, a leste daqui.$B$B$n! Tenho que sair daqui!", t = "Liberdade para Ruul!"},
    [6503] = {ot = "Mate 9 Vanguardeiros do Vale Gris, depois fale novamente com Koray'bin, no Posto Machadada.", st = "Fomos informados que os vanguardeiros do Vale Gris deixaram o Posto Avançado Asa de Prata e agora andam bisbilhotando perto nossos territórios na floresta. Não queremos que coletem informações sobre nossas defesas!$B$BVasculhe as florestas ao sul do nosso posto daqui e a leste do posto avançado da Aliança em Asa de Prata. Encontre e mate os vanguardeiros, depois fale novamente comigo.", t = "Vanguardeiros do Vale Gris"},
    [6522] = {ot = "Leve o Pergaminho Pequeno para Varimatras, na Cidade Baixa.", st = "Grande Dama,$B$BA senhora está ciente do que oferecemos. É uma grande oportunidade para a senhora tomar os Sertões e as terras além. Em troca, só queremos a sua ajuda. Quando dizemos ajuda, isso significa simplesmente nos conceder a liberdade para agir nessa área.$B$BPor favor, permita-nos discutir o assunto consigo. Nosso poderio é grande e estamos dispostos a compartilhá-lo com aqueles sábios o bastante para unirem-se a nós. Permanecerei fora de Urzal dos Mortos por ora.$B$BCordialmente,$BEmbaixador Malcin", t = "Uma aliança profana"},
    [6523] = {ot = "Escolte Kaya Casco Chato até a Aldeia Apareje e, então, fale novamente com Makaba Casco Chato perto da extremidade sudeste das Torres de Pedra.", st = "Obrigada por me resgatar! Devemos ir embora rápido antes que eles descubram que estou livre. Por favor, escolte-me até a Aldeia Apareje. A partir de lá, conheço meu caminho.$b$bMeu pai, Makaba Casco Chato, estará desesperado para saber que se estou em segurança.", t = "Proteja Kaya"},
    [6541] = {ot = "Apresente-se a Kadrak na torre de vigia dos Sertões Setentrionais.", st = "Você já foi ao Vale Gris, ao norte? Há pouco tempo, a Horda montou um assentamento lá, na Praia de Zoram, e estamos precisando de recrutas para defender os novos fronts.$B$BCaso você se considere à altura do trabalho, procure Kadrak, nos Sertões Setentrionais, na torre de vigia. Ele está liderando a campanha do Vale Gris e poderá lhe dar mais orientações.", t = "Apresente-se a Kadrak"},
    [6543] = {ot = "Abra o Monte de Relatórios e entregue os Relatórios dos Brado Guerreiro ao Batedor do Brado Guerreiro, o Mensageiro do Brado Guerreiro e o Pioneiro do Brado Guerreiro. Em seguida, entregue o informe sobre a situação atual que você receberá de cada um deles para Kadrak, na torre de vigia do norte dos Sertões.", st = "Há pouco tempo, eu destaquei alguns batedores para o Vale Gris, e preciso de um mensageiro para entregar ordens para eles e trazer de volta um informe sobre a situação.$B$BA primeira parada será no Assentamento Zoram'gar, na Praia de Zoram, para encontrar o primeiro batedor. Chega-se lá seguindo pela costa em direção ao oeste. Você também deverá passar no Posto Machadada, a norte, e pela estrada em direção ao leste, perto de Azshara.$B$BEntregue um relatório para cada batedor e receba deles um informe sobre a situação atual.", t = "Os relatórios dos Brado Guerreiro"},
    [6544] = {ot = "Acompanhe Torek no ataque ao Posto Avançado Asa de Prata e sua comandante, Duriel Flameluna. Em seguida, apresente-se a Ertog Raivatusco no Posto Machadada.", st = "Ei! $C! Vem cá!$B$BEu e meus saqueadores estamos nos preparando para atacar o Posto Avançado Asa de Prata, a oeste daqui. Nosso alvo é a líder deles, Duriel Flameluna. Os batedores relataram que o posto está fortemente guardado por sentinelas e guerreiros. Vai ser uma batalha gloriosa!$B$BVocê gostaria de dividir essa glória conosco, $n, nos ajudando? Caso sim, quando tudo acabar, comunique o sucesso da operação ao meu superior, Ertog Raivatusco, no Posto Machadada.$B$BE então, o que você me diz? Vem conosco?", t = "Junte-se aos bons"},
    [6548] = {ot = "Mate 8 Rufiões Temível Totem e 6 Mercenários Temível Totem para, então, voltar a falar com Makaba Casco Chato perto da extremidade sudoeste das Torres de Pedra.", st = "O clã Temível Totem invadiu minha vila e matou quase todos. Matei o máximo que pude, mas mal escapei vivo.$b$b$n, a única vontade que me resta é que mais deles morram. Você os encontrará a oeste daqui.", t = "Vingue minha vila"},
    [6561] = {ot = "Leve a cabeça do Senhor do Crepúsculo Kelris para Bashana Runa Totem, no Penhasco do Trovão.", st = "Eu estou sem forças. Vou precisar da sua ajuda!$b$bMuito tempo atrás, este local abrigava o grande templo de Eluna. Mas a desgraça levou à ruína quando a corrupção do deus antigo se infiltrou das profundezas da terra e contaminou o poço lunar sagrado.$b$bAku'mai, servo do deus antigo, se ergueu das águas.$b$bOs sectários do Martelo do Crepúsculo se aliaram às nagas para ocupar este local. Os cultistas, liderados por Kelris, sacrificam inocentes ao poder de Aku'mai.$b$bMate Kelris e leve a cabeça para Bashana, no Penhasco do Trovão, $n, por favor.", t = "Vilania das Profundezas"},
    [6562] = {ot = "Fale com Je'neu Sancrea no Vale Gris.", st = "Je'neu Sancrea precisa de ajuda. Ele está no Assentamento Zoram'gar, no Vale Gris. A floresta dos elfos noturnos fica ao norte das montanhas Torres de Pedra. Para chegar lá, passe pelo Rochedo Cortavento ou siga para o norte através dos Sertões. A Praia de Zoram fica no extremo oeste da floresta. Tome cuidado, $n. Existem forças que não vão aceitar sua presença pacificamente.", t = "Problemas nas Profundezas"},
    [6563] = {ot = "Entregue 20 Safiras de Aku'Mai a Je'neu Sancrea no Vale Gris.", st = "Dentro dos primeiros túneis das Profundezas Negras há muitas drusas de safira. Há pouco tempo, notou-se que as nagas estão extraindo os cristais. Até descobrir por quê, não podemos permitir que elas continuem. Parece que os cristais têm um imenso poder elemental e, se forem usados do jeito errado, podem se tornar um material arcano poderoso.$B$BVocê pode me ajudar, $n? As Profundezas Negras ficam no mar, perto da Praia de Zoram, ao norte de nosso assentamento.", t = "A essência de Aku'mai"},
    [6564] = {ot = "Leve o Bilhete Úmido para Je'neu Sancrea, no Vale Gris.", st = "O bilhete está todo amassado e a caligrafia da escrita é muito ruim:$B$B\"Sim, diga a todas as sacerdotisas para trazer os cristais para mim. Os espíritos elementais da água são fortes dentro deles e vão ajudar muito os nossos aquamantes e fazerem suas evocações.$B$BQuando controlarmos o poder dentro dos cristais, vamos apaziguar Aku'mai. Um dia teremos poder suficiente para trazer Aku'mai de volta e o mundo vai voltar à sua grande era. Uma era governada pelos deuses antigos!\"", t = "Lealdade aos Deuses Antigos"},
    [6565] = {ot = "Mate Lorgus Jett nas Profundezas Negras e depois fale novamente com Je'neu Sancrea no Vale Gris.", st = "Esse seguidor do Martelo do Crepúsculo não pode levar o plano dele a cabo. O Martelo do Crepúsculo não saca os espíritos da natureza. Eles acreditam nos Deuses Antigos, criaturas do caos e da treta que foram derrotadas faz uma cara. Esse tal Lorgus não pode triunfar. Você tem que dar um trato nele, $n. Eu não tenho como... sou fraco demais.$B$BVai pras Profundezas Negras, encontra o cara e passa no fio da navalha. Depois é só voltar pra Zoram'gar.", t = "Lealdade aos Deuses Antigos"},
    [6607] = {t = "Nat Pagle, o pescador supremo"},
    [6629] = {ot = "Mate Grundig Nuvem Negra e 6 Brutos Temível Totem, e fale novamente com Makaba Casco Chato perto da extremidade sudeste das Torres de Pedra.", st = "$n, você fez um ótimo trabalho atacando os Temível Totem. Se você se atrever, Grundig Nuvem Negra e seu bando pessoal de brutamontes são, sem dúvida, os piores do grupo. Foi ele que liderou o ataque brutal contra minha vila.$b$bVocê o encontrará no Aldeia do Temível Totem, um pouco mais adiante no caminho a oeste. Mate-o e lhe serei eternamente grato.", t = "Mate Grundig Nuvem Negra"},
    [6641] = {ot = "Escolte Muglash em segurança até o braseiro. Ajude-o a apagar o braseiro, e proteja-o na luta contra as nagas.$B$BSe cumprir a missão, volte ao Assentamento Zoram'gar e informe o Mensageiro do Brado Guerreiro da morte de Vorsha, a Açoitadora.", st = "Vorsha, a Açoitadora... A diabólica hidra que vaga pelos mares...$B$BEla vem atacando o posto avançado, sempre sem motivo, acabando com tudo que atravesse seu caminho.$B$BMas eu estou pronto, $n. Estou preparado para vencer a hidra e dar um fim aos ataques a Zoram'gar.$B$BAs nagas prestam homenagem à natureza malévola daquela fera mantendo um braseiro sempre aceso numa ilha perto da costa. Acho que, se apagarmos a chama, a Vorsha vai aparecer, furiosa.$B$BVamos precisar de ajuda. Portanto, chame seus amigos mais fortes.", t = "Vorsha, a Açoitadora"},
    [6661] = {ot = "Capture 5 Ratos Correfundo com a Flauta do Pegador de Ratos. Conduza os ratos até o Monty. Não se esqueça de entregar a flauta quando terminar.", st = "Alto lá, $Gpulguento:pulguenta;! Arrr... Tá procurando faina? O tombadilho tá pegando com a rataria e não tem marujada que dê conta.$B$BQue qui é? Tu só tem que pegar a flauta do pegador de rato e soprar meia dúzia de notas perto desses vermes. Aí eles vão te seguir até o quinto dos infernos!$B$BTu pega cinco sarnentos e traz aqui de volta pro velho Monty. Mas tudo vivo, hein?$B$BArrr....", t = "Ratos de porão"},
    [6662] = {ot = "Entregue a Caixa de Carne Duvidosa para Nipsy, na estação do Metrô Correfundo de Ventobravo.", st = "Meu mano Nipsy tem um negócio de espetinhos de rato do outro lado do metrô. $GO:A; camarada é $Gsafo:safa; e vai entregar o caixote de rato pro Nipsy, arrr? Antes que fique tudo podre, arrr? Anda logo!$B$BJá andou de metrô antes, arrr? Mole, mole! Tu só tem que entrar lá e largar vela. Só não vai dar uma de afobado e ficar de bobeira com braço e perna pra fora. É assim que a marujada arruma perna de pau pra vida inteira...", t = "Espetinhos de... rato"},
    [6921] = {ot = "Leve o Núcleo das Profundezas para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris.", st = "O Martelo do Crepúsculo se instalou nas Ruínas do Sacrário Lunar, nas Profundezas Negras. A presença deles só pode ter o fim de coagir os elementos a trabalhar contra nós. Se não forem contidos, dominarão essa região em definitivo.$B$B$n, adentre as Profundezas Negras e encontre a pedra das profundezas da ruína. Ela deve estar próxima, na água. Nela há um núcleo das profundezas, um dispositivo que, caso seja interpretado corretamente, nos dará um registro de toda atividade elemental. Com ele, talvez eu e a Harmonia Telúrica possamos fazer algo para impedir nossos inimigos!", t = "Nas ruínas"},
    [6922] = {ot = "Leve o Globo d'Água Estranho para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris.", st = "O elemental da água, derrotado, deixa para trás um globo d'água estranho. Você supõe que o objeto era a fonte de energia da criatura. Dentro do globo, uma forma aquática de aparência pútrida move-se para lá e para cá. O globo em si parece invulnerável a qualquer tipo de força física.$B$BSe existe alguém que possa saber o que é esse objeto, esse alguém é Je'neu Sancrea, da Harmonia Telúrica. Ele está no Assentamento Zoram'gar, um posto avançado da Horda no Vale Gris.", t = "O Barão Aquanis"},
    [6981] = {ot = "Viaje para a Vila Catraca e procure alguém que possa contar mais alguma coisa sobre a lasca faiscante.$B$BDepois, entregue a lasca conforme as orientações.", st = "O verde da lasca brilha e, apesar de sólida, algo meio túrbido parece se contorcer logo abaixo da superfície. Você não consegue desviar o olhar do abismo no cristal e, ao mesmo tempo, sabe que há algo muito perturbador nisso.$B$BTalvez você devesse ver se alguém na Vila Catraca sabe o que é essa lasca estranha.", t = "A lasca faiscante"},
    [7383] = {ot = "Encha o Frasco de Ametista e leve-o de volta para Corithras Lunafúria em Dolanaar.", st = "Mas nem tudo estava bem com Teldrassil. Os planos cuidadosamente elaborados por Guenelmo para a nova Árvore do Mundo transcorreram como ele esperava, mas havia um pequeno problema, um problema ao qual muitos dos transtornos em Teldrassil podem ser atribuídos.$b$bNo entanto, não vou entrar nessa questão ainda. Você deve visitar o último poço lunar, a noroeste, na Clareira do Oráculo. Sob os galhos da Árvore dos Oráculos está o primeiro e mais poderoso de nossos poços. Busque um frasco de sua água e fale novamente comigo.", t = "Coroa da Terra"},
    [65601] = {ot = "Fale com Magar em Orgrimmar.", st = "O macho sayaad é conhecido como íncubo. Uma criatura de maldade profunda e mente singular.\n\nO demônio deve ser atraído para o nosso mundo com uma isca, um objeto que represente amor e devoção.\n\nSe confia na orientação de um homem cego, escute, $n. A leste do Antro das Sombras, à margem da principal via de Orgrimmar, vive Magar. Ele anseia pelo retorno de Krilge.\n\nVá falar com ele. Ele vai pedir que você busque algo precioso. É a chave que você deve levar para Gan'rul.", t = "O amor machuca"},
    [65602] = {ot = "Obtenha a Estatueta de Madeira e leve para Gakin, o Neromante, no Distrito dos Magos de Ventobravo.", st = "Para atrair um íncubo você precisará de um reagente poderoso, um objeto que represente grande devoção e amor.\n\nUsando minha vidência, localizei uma pequena estatueta que pode servir para o ritual.\n\nMilhares de anos atrás, a peça pertencia a um jovem casal. Seus proprietários originais já não estão mais entre nós, mas o objeto, que foi dado de presente, perdura até hoje.\n\nSiga a estrada ao norte até o Vale Gris, depois siga para o oeste, passando pelo Entreposto de Maestra. Você verá uma casa entre as árvores. Nela, você encontrará o que busca.", t = "Amar é..."},
    [65603] = {ot = "Usando a Estatueta de Madeira, evoque e subjugue um íncubo. Depois, devolva a Estatueta de Madeira para Gakin, o Neromante, no Cordeiro Imolado.", st = "A hora chegou. Pegue a estatueta e acesse as criptas abaixo. Um círculo de evocação foi preparado, e você deve pôr a estatueta no centro dele.\n\nCom isso, o portal se abrirá e o íncubo cruzará para o nosso mundo.\n\nNão se deve subestimar um sayaad. O demônio não hesitará em atacar quando perceber o que você pretende. Lance mão de tudo que aprendeu para derrotá-lo.\n\nSe obtiver êxito, fale novamente comigo e eu vincularei a criatura à sua vontade. Se fracassar, sua alma estará perdida.", t = "A vinculação"},
    [65604] = {ot = "Usando o Lenço Fenecido, evoque e subjugue um íncubo. Depois, devolva o Lenço Fenecido para Gan'rul Olho de Sangue em Orgrimmar.", st = "Sim... Eu sinto as emoções residuais que permanecem em cada fio. O amor passou a fazer parte da própria urdidura. O íncubo não vai resistir.\n\nLeve isto para o círculo de evocação na tenda de Neeru, $n. Evoque um íncubo malévolo e mostre-lhe sua maestria. Não espere que a criatura se renda facilmente. Prepare sua magia para o combate. Subestimar demônios é o erro fatal de muitos bruxos.\n\nDepois de derrotá-lo, traga o pano de volta. Avisarei a Magar sobre o que você encontrou.", t = "A vinculação"},
    [65610] = {ot = "Investigue o Lago Céu Caído, que fica no Vale Gris, e relate suas descobertas a Gan'rul Olho de Sangue em Orgrimmar.", st = "Eu conheci Krilge tecendo lunatrama no Vale Gris. Ele estava incumbido de proteger os civis lá, até que despareceu...\n\nAs buscas foram encerradas, e ele foi considerado um desertor, mas eu não acredito nisso.\n\nNos encontrávamos sempre no Lago Céu Caído, antes do lugar ficar tomado de feras do brejo agressivas.\n\nNão sou muito de pedir favores, mas se você puder ir ao Vale Gris para procurar por qualquer sinal dele, eu agradeço muito.", t = "A esperança é a última que morre"},
    [76156] = {ot = "Penetre na mina da Empreendimentos S.A. a sudeste do Penhasco do Trovão e colete 5 Cargas de Mineração de Cequatrum nos vagonetes de suprimentos explosivos e devolva-as a Javaton Totem das Sombras, no Penhasco do Trovão.", st = "Sinto em você um talento oculto para as artes sutis, $c. Use esta máscara para se infiltrar na mina da Empreendimentos S.A. aqui perto e roubar seus suprimentos. Pode não parecer um disfarce convincente, mas $Gum ladino:uma ladina; experiente passa por qualquer guarda apenas com um sorriso vitorioso e uma distração astuta. Creio que você também possui essa habilidade.", t = "À espreita com a Mãe Terra"},
    [76160] = {ot = "Colete 8 Cones de Fúria dos Ventos a norte do Penhasco do Trovão, use Almofariz e Pilão neles e leve o resultado a Javaton Totem das Sombras, no Penhasco do Trovão.", st = "Talvez o seu forte sejam as poções, não disfarces. As harpias ao norte abrigam-se em uma árvore que produz uma resina extremamente tóxica. Macere os cones caídos dos ninhos para fazer uma pomada. Aplique-a em lâminas para calcinar os ferimentos de oponentes e transformar o sangue deles em sal.", t = "À espreita com a Mãe Terra"},
    [76240] = {ot = "Compre ou pesque um Peixinho Brilhante Cru e use o Jogo de Facas para filetar, em frente a Javaton Totem das Sombras, no Penhasco do Trovão.", st = "Tenho uma última ideia que pode nos levar ao sucesso. Ainda acho que você tem algum talento escondido, mas vamos tentar descobrir com uma abordagem menos direta.\n\nVá, obtenha um peixinho brilhante cru e traga de volta para cá. Use estas adagas para limpar e filetar. Não pense muito, faça o que der na cabeça.", t = "À espreita com a Mãe Terra"},
    [79008] = {t = "... e aquele bilhete, hein?"},
    [79360] = {ot = "Derrote Charlga Talhaflanco no Urzal dos Tuscos e colete informações sobre os planos dos javatuscos.", st = "Agora que dominou os elementos, você tem uma obrigação com eles e, por consequência, com toda Azeroth. Não exigimos o poder deles, e sim pedimos sua ajuda. Está na hora de você retribuir os favores que lhe foram concedidos, e acho que eu sei um jeito de fazer isso.\n\nOs javatuscos deturpam os elementos para seus próprios fins, e parece que estão estendendo seu raio de ação para além das fronteiras. Entre naquele urzal e acabe com os planos deles. Precisamos proteger essas terras.", t = "Auxílio elemental"},
    [79364] = {ot = "Encontre Pradosa Fita Nuvens em Mil Agulhas.", st = "O bilhete que você encontrou diz que os Crinavalha se entocaram em Mil Agulhas para realizar algum tipo de ritual. Tempestades furiosas e marés subindo...\n\nOs javatuscos devem estar usando alguma feitiçaria cruel que aprenderam com Hirzek, um xamã que fez de tudo para deturpar os elementos. Se o plano é inundar o cânion, vão precisar de poderes elementais devastadores.\n\nNão estamos equipados a contento para lidar com isso, mas $Gum xamã poderoso:uma xamã poderosa; como você deve ter alguma ideia. Fale outra vez com seus aliados e veja se não encontram uma resposta.", t = "De olhos no céu"},
    [86574] = {ot = "Colete $1oa Provisões das Torres de Pedra de Mantícoras Asaltiva e entregue-as à Estalajadeira Faralia.", st = "<Este pobre corpo traz marcas de muitos golpes de mantícoras asaltivas. A mochila próxima está amarrotada e descartada, sem o conteúdo, e há apenas uma pequena nota presa à mão da mensageira indicando o que foi perdido: uma remessa destinada à Estalajadeira Faralia, no Morro das Torres de Pedra.>\n\n<As mantícoras provavelmente levaram os fardos de provisões para forrar seus ninhos.>", t = "Entrega nas Torres de Pedra"},
    [86576] = {ot = "Leve $1oa Pedras Solares Lampejantes para Mor'rogal.", st = "Além de espalhar sujeira pelo Vale Carbonizado, as harpias Furissangue não resistem a qualquer coisa que brilhe. Ouvi dizer que elas usam pedras solares de um amarelo dourado como enfeites. Para mim, esses berloques não têm serventia, mas Mor'rogal já comentou que as usou antes.\n\nEnquanto estiver combatendo as harpias do Vale, fique de olho em pedras solares lampejantes. Leve a Mor'rogal as que encontrar. Ele está nas colinas acima de nós.", t = "Berloques Furissangue"},
    [86585] = {ot = "Erga o estandarte de Altaforja, chame o trogg Rachacrânio, mate-o, e depois fale com o Capitão Balbúrdia.", st = "A montanhista caída tem um brasão de Altaforja. Talvez ela estivesse patrulhando ou fazendo uma investida desastrosa. Seja como for, o brasão foi derrubado e pisoteado. A montanhista foi atingida na cabeça com tanta força que perdeu o elmo e foi morta imediatamente por um trogg, provavelmente com um tacape de espinhos.\n\nO trogg que matou ela provavelmente está por perto, e deve se lembrar do estandarte. Erguer o estandarte de Altaforja outra vez deve atraí-lo.", t = "Estandarte dos Caídos"},
    [86613] = {ot = "Devolva $1oa Ferramentas de Escavação para Magmar Machadeiro.", st = "As ferramentas de escavação, deixadas para trás quando os anões fugiram dos troggs, parecem praticamente intocadas. Devolvê-las aos escavadores com certeza vai ajudar no trabalho deles.", t = "Ferramentas de Escavação"},
    [86614] = {ot = "Devolva a Presilha de Prata com Monograma à proprietária.", st = "<Entre as quinquilharias de pesca nos destroços, há alguns anzóis enferrujados, carretéis de arame quebrados e uma presilha de prata ligeiramente corroída, mas ornada, com o monograma \"K.A.\">", t = "Prata das ondas"},
    [86667] = {ot = "Entregue um Pote de Neve a Norric Lochthane na casa dele, na costa noroeste do lago.", st = "Meu velho mentor, o Norric, mandou um elemental menor com um pedido dos mais esquisitos. Ele precisa de um jarro de neve para umas lidas xamânicas! Não sei o que ele vai fazer com isso, mas aprendi há muito tempo a não questionar o jeito dele de lidar com magia.\n\nTô ocupada aprendendo sobre os elementais da região, então não posso sair pra ajudar. Vai até a entrada do túnel no Desfiladeiro do Portão Sul, onde tem neve o ano inteiro. Enche este jarro de cerâmica e leva para ele antes que derreta. O pote deve mantê-la fria.", t = "Preso na neve"},
    [86758] = {ot = "Encontre e derrote o crocolisco Presadaga e traga de volta a faca de Marek.", st = "Já contei pra ti de quando um crocolisco quase me arrancou a mão? Consegui cravar a faca na queixada do bicho e saí correndo. Jurava que tinha largado a faca por algum canto aqui, mas não acho de jeito nenhum.\n\nDe qualquer forma, é bem capaz que a fera ainda esteja rondando pelas barrancas do lago. Alguém precisa dar um jeito naquele brutamontes asqueroso, antes que ataque outro caçador.\n\nComecei a chamar o bicho de Presadaga. Se tu der com ele, manda um abraço amigo por mim! E quando digo \"abraço\", quero dizer \"uma bela facada\".", t = "Faca na ferida"},
    [86784] = {ot = "Colete $1oa Galhos Secos e leve-os para Eleonora Grilhões.", st = "Minha associada Eleonora Grilhões se orgulha de viajar por terras selvagens e sobreviver ao clima e aos monstros. Ela está acampada não muito longe daqui, nas colinas a oeste, e lembro-me de um conselho que me deu certa vez: \"Quando achar que tem lenha suficiente, junte cinco vezes mais.\"\n\nSe tiver algum tempo livre, você poderia recolher lenha neste cesto e levá-la ao acampamento dela. Tenho certeza de que ela poderá lhe dar alguns conselhos sobre como sobreviver em aventuras longe de casa.", t = "Paus e ossos"},
    [87288] = {ot = "Leve $1oa Pelagens de Sabre-da-noite Macias a Aldria.", st = "Olá, viajante! Espero que você esteja gostando da sua visita à nossa aldeia. Eu gosto de Dolanaar porque ela é pequena e rústica, e todo mundo é simpático.\n\nSou uma comerciante local e trago todo tipo de ferramentas e berloques que podem ser úteis nas suas viagens. Se você tiver interesse em trocar, estou precisando de pelagens de sabres-da-noite. Apesar da beleza dessas criaturas majestosas, as locais são bem agressivas, então não se sinta mal por se defender.", t = "Pelagens de sabre-da-noite macias"},
    [87760] = {ot = "Encontre uma Senhora das Feras Escamarraio, mate-a e traga de volta seu Bastão do Domínio Profundo.", st = "Recebi uma resposta de Darnassus, $n!\n\nCom a ajuda das amostras dos animais, descobrimos que as nagas dominaram essas criaturas marinhas para usá-las como suas relutantes montarias e bestas de carga. As que eram inflexíveis, velhas ou feridas demais eram expulsas por esporte. Uma monstruosidade sem tamanho!\n\nÉ nosso dever sagrado pôr um fim nisso!\n\nAs nagas têm forças nas Ruínas de Mathistra, e devem estar capturando manguais na costa. Encontre sua senhora das feras, mate-a e traga de volta seus instrumentos de dominação!", t = "Mergulhador sagrado"},
    [90902] = {ot = "Cure $1oa Necroguardas Feridos com sua habilidade Luz Sagrada.", st = "Me orgulha dar as boas-vindas a $Goutro paladino recém-revivido:outra paladina recém-revivida;. À medida que a sua conexão com a Luz se refaz, você perceberá que certas habilidades que outrora lhe pareciam fáceis como respirar se tornaram consideravelmente dolorosas, sobretudo aquelas que envolvem canalizar a Luz para curar a si e a outrem.\n\nA única solução para esse problema é — lamento informar — encará-lo de frente. É como um músculo atrofiado: é preciso exercitá-lo para que se recupere, por mais excruciante que a dor seja.", t = "Redescobrindo a Luz"},
    [91208] = {ot = "Encontre a Paladina Assustada em Plangemortis.", st = "Nem todos os paladinos que voltam do além-túmulo se acostumam tão rapidamente à sua nova realidade. Alguns sofrem para aceitar que são, de certa forma, aquilo que passaram a vida toda combatendo.\n\nEsses indivíduos não precisam de nada além de um gesto de bondade e um ombro amigo. Infelizmente, há aqueles que se entregam à violência. Encontre a paladina amedrontada que fugiu para as colinas a oeste desta capela. Estenda-lhe uma mão amiga. Traga-a de volta ao caminho da Luz, se puder.", t = "Aprender a conviver"},
    [91209] = {ot = "Siga pela estrada rumo a leste, saindo de Plangemortis, até chegar a Montalvo. Apresente-se a Shária Calmafonte para continuar seu treinamento.", st = "Lordaeron pode não ser mais o que era, mas nosso lar ainda precisa de proteção contra todos os tipos de ameaças, e está na hora de você enfrentar o mundo. Sua próxima parada será a cidade de Montalvo nas Clareiras de Tirisfal. Lá, procure por Shária Calmafonte. Ela pode continuar o seu treinamento. \n\nMas um último conselho antes de partir: como $Gpaladino:paladina; viajando pelas terras dos Renegados, tome muito cuidado. Vários fiéis da Dama Sombria desconfiam de nós e da nossa proximidade com a Luz.", t = "Continue seu treinamento"},
    [91282] = {ot = "Encontre a fortaleza da Bastilha de Bandarion e apresente-se a Bretônio Samuel.", st = "É revigorante ver meus irmãos e irmãs recém-revividos prosperando como você prosperou. Todavia, é só por meio da comunhão e da fé partilhada que podemos concretizar todo o nosso potencial, e é justamente por isso que começamos a formar uma nova ordem de paladinos aqui em Tirisfal. \n\nSe quiser saber mais, visite o nosso monastério na beira da Floresta do Sussurro. Ele se chama Bastilha de Bandarion. Fica nos penhascos a noroeste da Fazenda dos Solliden. É fácil de achar.", t = "Um segundo lar"},
    [91285] = {ot = "Mate $1oa Atacantes Pinavil e $2oa Videntes Pinavil e fale novamente com Bretônio Samuel quando terminar.", st = "Em geral, somos mais hospitaleiros com os recém-chegados, mas temos um probleminha que envolve murlocs no momento.\n\nUma tribo de murlocs usava a bastilha para desova. O problema é recorrente desde que chegamos, e já os escorraçamos, mas a situação está começando a fugir ao controle. Você, pelo visto, tem experiência em combate. Acha que pode nos ajudar a expulsar essas pragas? Eles espreitam os penhascos ao longo da estrada a leste daqui e os acampamentos ao redor do lago a oeste.", t = "Murlocs nos portões"},
    [91294] = {ot = "Fale com os moradores da Bastilha de Bandarion.", st = "Agora que a ameaça dos ataques de murlocs está sob controle, gostaria de convidar você a explorar a nossa bastilha. Ela ainda é humilde, mas é o nosso lar.\n\nQuando tiver explorado a contento, procure Danitha Morr, nossa líder. Ela pode $Gajudá-lo:ajudá-la; a se acomodar.\n\nÉ um prazer conhecer você, $n. Que a Luz $Go:a; guie.", t = "Um passeio pelo pátio"},
    [91316] = {ot = "Colete 12 pedaços de Lenha Robusta do Vale das Sombras nas Clareiras de Tirisfal.", st = "Tão longe assim da Cidade Baixa, a logística é um desafio, e temos uma escassez terrível dos materiais de construção necessários para restaurar a fortaleza.\n\nA aldeia arruinada do Vale das Sombras se encontra na Floresta do Sussurro, logo a sudoeste daqui. Uma das construções tem uma adega da raiz antiga onde se guarda todo tipo de coisa. Certamente, há materiais por lá que podemos usar. Pegue o que der para aproveitar e depois volte aqui.", t = "Reformas"},
    [91317] = {ot = "Mate 8 Labutadores Manchados, 6 Zelotes Manchados e colete a cabeça do Comandante Rudolph Gelhardt nas Clareiras de Tirisfal.", st = "Nem todos os paladinos reerguidos se aclimatizaram à nossa nova existência, como você pode ter visto por si $Gmesmo:mesma;. Alguns carregaram consigo os preconceitos que tinham em vida e continuam a agir com violência para com seus pares Renegados.\n\nNa atual conjuntura, despertamos a desconfiança do nosso povo, que lembra bem da perseguição que lhe fora infligida pelos vivos em nome da Luz, e esses ataques não ajudam. Alguns destes manchados firmaram residência no Vale das Sombras a sudoeste. Acabe com eles e traga a cabeça de seu líder.", t = "Os manchados"},
    [91723] = {ot = "Mate 8 Geomantes Kobolds na Mina de Jaspe e volte a falar com Hamish Montavarga na Torre de Azora.", st = "Droga! Esses instrumentos arcanos são tão sensíveis que, toda vez que tento calibrá-los, um pico de energia os desregula.\nParece que é uma energia que emana do norte, onde aqueles kobolds primitivos praticam a magia rudimentar deles. Pode eliminar alguns deles para que eu consiga trabalhar em paz?", t = "Instrumentos delicados"},
    [91724] = {ot = "Mate $1oa Teurgos Ladinos Défias no Lago do Monumento e volte a falar com Hamish Montavarga na Torre de Azora.", st = "Quase lá... Ah, pelo Éter! Ainda tem algo interferindo nos meus instrumentos.\n\nQue frustração terrível, $n. Ouvi boatos de que bandidos da região praticam feitiços perto do Lago do Monumento. Pode detê-los, para que eu finalmente me veja livre de tantas perturbações e consiga trabalhar em paz?", t = "Instrumentos delicados"},
    [91725] = {ot = "Colete 5 Suprimentos de Encantamento Roubados em acampamentos de gnolls nos entornos do Lago do Monumento e devolva-os a Blixie Fitzpisca perto da Torre de Azora.", st = "Fui enviada pelo Mestre Teócrito para buscar alguns suprimentos de encantamento do posto comercial, mas no meu caminho de volta fui emboscada por um bando de gnolls!\n\nEu larguei o pacote e fugi, mas ai de mim se voltar sem ele! Vou passar semanas limpando os experimentos de polimorfia como castigo! Você acha que pode achar os suprimentos pra mim?", t = "Suprimentos de encantamento roubados"},
    [91732] = {ot = "Colete 4 Ferramentas de Mineração na Mina de Jaspe e volte a falar com Hagar Leal na Madeireira Vale do Leste.", st = "Aço de boa qualidade anda escasso depois da guerra, e isso está começando a afetar a qualidade das nossas ferramentas. Os mineiros de Jaspe usavam picaretas de altíssima qualidade. Ainda deve haver algumas largadas nas profundezas da mina. Pode buscar algumas para eu ver se consigo reaproveitar o aço?", t = "Aço de primeira"},
    [91733] = {ot = "Colete o Machado Encharcado, a Serra Encharcada e a Caixa de Ferramentas Encharcada a jusante da Madeireira Vale do Leste e volte a falar com Ormino Pelfórdio.", st = "Estava trazendo um carregamento de suprimentos do posto comercial, mas a minha carroça tombou e os suprimentos caíram no rio. Eles já tinham ido por água abaixo antes de eu conseguir apanhá-los.\n\nCom os murlocs e os lobos que rondam mais para a frente, a chance de eu conseguir recuperar a minha mercadoria por conta própria é zero. Já você parece bem $Gdurão:durona;. Acha que pode recuperá-la para mim?", t = "A jusante"},
    [91740] = {ot = "Entregue a Cabeça de Coaxinho a Mirella Rosa na Torre Serrana.", st = "Sem dúvida, esse murloc vem aterrorizando as estradas da região há algum tempo. Você desconfia de que a notícia da morte dele interessará aos guardas da vigília que trabalham por perto.", t = "Cabeça de Coaxinho"},
    [91741] = {ot = "Devolva o livro ao Irmão Paxeco.", st = "<Um dos kobolds deixou este livro cair. Parece que o kobold pode ter tentado devorá-lo.\n\nO Irmão Paxeco mantém uma pequena biblioteca no interior da abadia. O livro deve ter vindo de lá.>", t = "Livro mordiscado"},
    [91743] = {ot = "Recupere $1oa Livros Roubados dos kobolds no Vale de Vila Norte e devolva-os para o Irmão Paxeco.", st = "Esses malditos kobolds estão comendo meus livros! Você tem que pegá-los de volta antes que eles devorem toda a minha biblioteca.", t = "Fome de conhecimento"},
    [91745] = {ot = "Fale com Kelsey Fargo na entrada da Mina da Serra do Eco, no Vale de Vila Norte.", st = "Fale com Kelsey Fargo, a nova aprendiz de mineração. Ela trabalha na entrada da mina e provavelmente viu o que os kobolds estão aprontando. Aproveitando a viagem, talvez ela possa lhe ensinar uma coisa ou outra sobre mineração.", t = "Consultoria em mineração"},
    [91746] = {ot = "Entregue a Cabeça de Patolmo a Helene Esfoladora perto da Vila d'Ouro.", st = "O troféu é uma recordação impressionante da sua vitória sobre Patolmo. Talvez haja algum caçador ou esfolador da região que queira ouvir a história.", t = "Cabeça de Patolmo"},
    [91751] = {ot = "Esfole lobos dos entornos da Floresta de Elwynn até coletar $1oa Pelagens de Lobo Ásperas e entregue-as a Helene Esfoladora perto da Vila d'Ouro.", st = "Quer praticar esfolamento? Meu marido costuma me ajudar caçando lobos, mas ele está ocupado lá perto da abadia. Agradeceria se me ajudasse a coletar as pelagens que faltam para terminar as encomendas em que estou trabalhando.", t = "Pelagens de lobo ásperas"},
    [91752] = {ot = "Recupere um Saco de Livros com \"Ilustrações\" de Narf Descobrilho. Leve o saco para o Major Belmonte no interior da Abadia de Vila Norte.", st = "De tempos em tempos, um kobold passa gritando \"Desenho pro Narf!\". Eu não sei quem é Narf. Talvez um dos líderes kobold no fundo da mina? Eu aposto que ele já deve ter um saco repleto de livros a esta altura.\n\nVá pegar esses livros e leve-os para o Major Belmonte, nossa autoridade da região. Você deve levar companhia. Os kobolds dentro da mina são bem mais ameaçadores.", t = "Livro com figura também é leitura"},
    [91753] = {ot = "Kitta Ventígnea na Torre de Azora quer que você colete 3 Resíduos Luminosos.\n\nVocê pode obter Resíduos Luminosos desencantando Efígies de Cera Rústicas deixadas por Geomantes Kobolds.", st = "O rigor acadêmico é essencial para o ofício de encantadores, é claro, mas uma básica de prática pode render bons frutos. Imagine um kobold simples, por exemplo. Sem educação formal, ele ainda demonstra um tipo de aptidão inata à feitiçaria e aos encantamentos.\n\nConsiga algumas efígies de cera deles e desfaça os encantamentos que eles têm. Talvez isso seja esclarecedor.", t = "Uma aula encantadora"},
    [91758] = {ot = "Fale com Tordrin Rigilâmina perto do estábulo atrás da Abadia de Vila Norte.", st = "Seus assuntos com os kobolds ainda não terminaram. Acabamos de saber pela Kelsey que um kobold deixou a mina carregando um saco grande de livros. Preciso que você encontre esse kobold para que possamos recuperar os livros do Irmão Paxeco.\n\nVá falar com Tordrin Rigilâmina. Ele é o novo treinador de Caçadores que acabou de chegar de Altaforja. Você o encontra atrás da abadia, perto do estábulo. Ele pode ajudar você a achar esse ladrão kobold.", t = "Siga aquele kobold!"},
    [91772] = {ot = "Siga os rastros do kobold e apresente-se ao Delegado Durão em Vila d'Ouro com as suas descobertas e o Kit de Rastreamento de Kobolds.", st = "Buenas. Pega esse kit de rastreamento de kobolds. Com ele, tu vai conseguir ir no encalço do kobold com o qual o Major Belmonte tá preocupado.\n\nSegue as pegadas e leva o que tu encontrar pro Delegado Durão em Vila d'Ouro.\n\nTô com um pressentimento de que esses bagaceiros tão aprontando alguma fora de Vila Norte. Então tu vai precisar da ajuda do Delegado, tchê.", t = "Silêncio! Área de caça a kobolds"},
    [91775] = {ot = "Encontre 6 Livros Perdidos e \"Diversão com Elementais\" e devolva-os ao Delegado Durão.", st = "Enquanto estiver investigando a Mina Vailafundo, veja se consegue recuperar algum dos livros do Irmão Paxeco. Ele está particularmente preocupado com um livro chamado \"Diversão com Elementais\". Ele acha que até um kobold conseguiria usá-lo para evocar um servo elemental. Esteja ciente de que as profundezas da mina são bastante perigosas. Você deve levar companhia.\n\nLeve esta bolsa de livros para guardar bem os livros assim que encontrá-los!", t = "Devolução de livros"},
    [91777] = {ot = "Recupere os livros \"Geomancia para Jovens Magos Curiosos\" e \"Explicador Arcano: Coisas Mágicas em Palavras Simples\" e devolva-os ao Irmão Paxeco na Abadia de Vila Norte.", st = "Há apenas mais dois livros faltando da lista do Irmão Paxeco: \"Geomancia para Jovens Magos Curiosos\" e \"Explicador Arcano: Coisas Mágicas em Palavras Simples\".\n\nOs kobolds devem ter levado para a Mina de Jaspe. Faça a gentileza de localizar esses dois livros e leve-os de volta ao Irmão Paxeco.\n\nTemo que será bastante perigoso. Se o \"aprendiz\" kobold estava evocando um elemental, quem sabe o que o mestre é capaz de fazer... Eu levaria alguns amigos se fosse você.", t = "Livros raros"},
    [91858] = {ot = "Vá até o Sepulcro, na Floresta de Pinhaprata, e fale com Trevano Rol dos membros desaparecidos da Harmonia Telúrica.", st = "Graças a uma reviravolta extremamente infeliz em Pinhaprata, temos a chance de provar o nosso valor aos olhos da Horda.\n\nDois dignitários da Harmonia Telúrica que estavam a caminho da Serraria Tarren despareceram na Floresta de Pinhaprata. Temos pouquíssimas informações no momento, mas, segundo boatos, esta situação pode desencadear um incidente diplomático e tanto. Se conseguirmos encontrar as pessoas desaparecidas, poderemos ganhar a legitimidade de que tanto precisamos.\n\nTemos um agente no Sepulcro, Trevano Rol. Vá até lá e fale com ele.", t = "Incidente diplomático"},
    [91859] = {ot = "Fale com o Necroguarda Baldreno dos viajantes misteriosos da Harmonia Telúrica que passaram pelo Sepulcro recentemente.", st = "Sendo bem direto, os tais \"dignitários\" não eram diplomatas quaisquer. Um deles era tauren, o que é bastante comum quando se trata da Harmonia Telúrica. Já a outra — e sei que receberá a informação com bastante incredulidade — era elfa. Elfa *superior*. Estava de manto, mas eu já vi quel'dorei antes e apostaria o meu dedo mindinho que se tratava de uma.\n\nO que uma elfa fazia com um tauren em território da Horda? É um mistério que estou tão próximo de esclarecer quanto você. Isso é tudo o que sei. Sugiro que se informe melhor com o Necroguarda Baldreno, perto da entrada da cidade.", t = "Dupla intrigante"},
    [91860] = {ot = "Investigue na Ilha de Fenris, a leste, o que aconteceu com o grupo de viajantes da Harmonia Telúrica.", st = "Ao fazer a ronda na noite passada, vi um bando de gnolls lançar um cadáver muito grande numa pira, na costa da Ilha de Fenris. Não vi elfo nenhum, nem outros cadáveres menores, mas a situação os faz parecer muito suspeitos.\n\nSe não lhe falta coragem ou burrice, fique à vontade para ir à Ilha de Fenris e passar a história a limpo, mas, na minha opinião, é trabalho demais para encontrar uma elfa arrogante que já deve estar morta.\n\nSei bem que os paladinos amam fazer juramentos e enfrentar causas perdidas, mas essa não vale a pena. Pode acreditar.", t = "Destino sórdido"},
    [91861] = {ot = "Investigue o Castelo Fenris ao norte e tente localizar o membro desaparecido do grupo da Harmonia Telúrica.", st = "<O fato de você ter encontrado apenas um corpo é um sinal de esperança. Será que a elfa superior descrita por Trevano e Hadrec ainda está viva nas profundezas da fortaleza nas proximidades?>", t = "Entrando no Castelo Fenris"},
    [91862] = {ot = "Recupere a Chave da Ilha de Fenris dos Gnolls Putricouro e use-a para libertar Lúmina Cantavento.", st = "Quel'dorei? Eu não sou \"quel'dorei\", não. Sou Lúmina Cantavento, uma shen'dorei. Sou uma Moldavento celonata.\n\nCheguei aqui como convidada da Harmonia Telúrica. Eu e Banon, meu companheiro, estávamos passando por Pinhaprata rumo ao Planalto Arathi para estudar as convergências elementais de lá. Obviamente, não chegamos ao nosso destino.\n\nMas não temos tempo para essa conversa. Mate os gnolls aqui perto. Pegue a chave desta jaula e me liberte. Conto o resto da história quando estivermos longe e em segurança.", t = "Lúmina Cantavento"},
    [91920] = {ot = "Junte 3 Olhos de Murloc e leve-os para o Boticário Renferrel no Sepulcro.", st = "Longe de mim questionar a eficiência das fórmulas do Boticário Renferrel, mas seria mentira se eu dissesse que a poção surtiu qualquer efeito perceptível.\n\nHá um bando de murlocs que ronda as margens do Espelho de Lordaeron, e vale ressaltar que os murlocs são dotados de olhos. Suspeito que a disposição do boticário a tentar coisas novas tenha sido deixada de lado em prol da sua recém-adquirida obsessão por corações. Leve alguns a eles.\n\nSe me cabe escolher entre morrer uma segunda vez ou ser morto por Renferrel por questionar os métodos dele, prefiro a segunda opção.", t = "Olhos selvagens"},
    [91921] = {ot = "Leve a poção para Quintino Yorick na Plantação do Ivar, ao norte do Sepulcro.", st = "Aqui está a nova poção para ajudar na recuperação de Quintino, feita com amor extraído de seis corações inteiros.\n\nAgora, por favor, retire-se antes que a sua presença exija mais papelada.", t = "Reencontrando Quintino (de novo)"},
    [92109] = {ot = "Leve 5 Ampolas Vazias, 5 Folhas-prata e 5 Botões-da-paz para a jovem aspirante a alquimista no celeiro em Arroio da Lua, em Cerro Oeste.", st = "Err... Oi, $Gmoço:moça;. Eu não devia falar com estranhos, mas... pra que servem essas garrafas brilhantes brotando da sua mochila? Você é alquimista? Isso é tão legal!\n\nQuando eu crescer, também quero ser alquimista. O papai não me deixa brincar com as plantas dele... Ele diz que é muito perigoso.\n\nBom, eu quero começar a aprender já. Você arranjaria uns materiais pra mim, por favorzinho?", t = "Meu primeiro conjunto de alquimia"},
    [92110] = {ot = "Reúna 3 Olhos de Murloc para a jovem aspirante a alquimista no celeiro em Arroio da Lua, em Cerro Oeste.", st = "Uau, minha primeira poção! Quando você começou, já sabia que misturar essas duas plantas mudava a cor da poção pra um vermelho vibrante?\n\nIsso foi legal, mas misturar flor não parece o tipo de alquimia que o papai faz. Ele também usa outros ingredientes.\n\nEu não sei o que mais usar, então vamos tentar a primeira coisa que vier à mente! Vamos ver... talvez olho de murloc? Parece nojento, mas aposto que vai acontecer alguma coisa.", t = "Minha primeira poção de verdade"},
    [92124] = {ot = "Fale com Daniel, o assistente do Irmão Paxeco, na biblioteca.", st = "Precisamos fazer um balanço de quantos livros sumiram!\n\nVá falar com o inútil do meu assistente, o Daniel. Ele pode fazer um inventário rápido e dizer a gravidade do problema.\n\nEle é obcecado pelas várias profissões da Floresta de Elwynn. O garoto foca mais nelas do que no trabalho importantíssimo de me ajudar.\n\nNão deixe que ele fique tagarelando sobre profissões. Descubra o que aconteceu aos meus livros!", t = "Inventário de livros"},
    [92401] = {ot = "Investigue o desaparecimento de Edward Tececórdio nas Ruínas de Lordaeron.", st = "É meu marido, Edward...\n\nEle ainda não voltou de sua visita semanal ao cemitério nas Ruínas de Lordaeron. Perdemos nosso filho quando Arthas arrasou a cidade, e meu querido Edward ainda carrega a culpa e a tristeza de nunca termos encontrado o corpo dele. Já tentei alertá-lo dos perigos de vasculhar aquelas ruínas infestadas, mas ele se recusa a desistir. Tento não me preocupar, mas já se passaram dias.\n\nHá coisas naquele lugar que estão além das minhas forças, mas, se puder me ajudar, preciso saber o que aconteceu com meu marido.", t = "Pedido desesperado"},
    [92415] = {ot = "Leve a Carta Manchada de Sangue para a Matriarca Ananéri em Ventobravo.", st = "<Um maço de pergaminho rasgado e manchado mal sobreviveu ao solo pisoteado por mortos-vivos do cemitério. Ele menciona uma criança desaparecida da família Tececórdio. Talvez a matriarca de Ventobravo saiba mais.>", t = "Lembre-se de que eu te amo"},
    [92421] = {ot = "Colete $1oa Membros Intactos nas Ruínas de Lordaeron para Morbin Ruinaluz, na Cidade Baixa.", st = "Como paladino dos Renegados, é meu dever cumprir a vontade da nossa Dama Sombria e atender às necessidades do nosso povo. É muito oportuno que possamos fazer as duas coisas ao mesmo tempo.\n\nSobre a Cidade Baixa, o Flagelo continua a vagar sem rumo, em grandes números. Nossas forças vão sendo limadas conforme tentamos reconquistar a nossa terra, e não se pode regenerar carne putrescente. Só é possível substituí-la.\n\nSei o que o glorioso Capitão Garek Bandarion desejaria, estivesse ele ainda entre nós. Terminar o que começou e curar o nosso povo. Por Lordaeron!", t = "Justiça da Luz"},
    [92422] = {ot = "Mate Rath'mael nas Ruínas de Lordaeron para o Necroguarda Kristof em Montalvo.", st = "Recebemos relatos do Mirante de Lordaeron, nas profundezas das Ruínas de Lordaeron. Uma névoa profana tomou as ruas e o cemitério, dando ao Flagelo dali alguma cobertura.\n\nNossos batedores indicam que ela está sendo conjurada por uma nova força, um necromante conhecido como Rath'mael. Não podemos simplesmente esperar que isso passe, $n.\n\nSe tiver aliados, convoque-os para ajudar os Renegados. Expulse essa criatura de nossas terras.", t = "A ira de Rath'mael"},
    [92432] = {ot = "Apresente-se à Imagem da Arquimaga Modera nos arredores de Dalaran.", st = "Trago más notícias de Dalaran. Algo desestabilizou nossos meridianos, causando um comportamento errático e destrutivo dos nossos constructos na cidade.\n\nAinda não sabemos o que causou tamanha desordem. O alto conselho ordenou que mantenhamos esse assunto em segredo para não trazer vergonha à nossa ordem. Mas não podemos manter essa farsa para sempre. A cidade está sendo tomada neste exato momento!\n\nA Arquimaga Modera me enviou para solicitar ajuda externa. Procure-a nos arredores de Dalaran, ao lado do Espelho de Lordaeron.", t = "Um pedido alarmante"},
    [92434] = {ot = "Encontre um caminho para Dalaran ao longo do Espelho de Lordaeron.", st = "O que quer que tenha feito a barreira de Dalaran ceder deixou a cidade um caos completo. Agora que você deu conta das patrulhas, é o momento ideal para nos infiltrarmos e descobrirmos os segredos deles.\n\nLeve a chave que você achou no acampamento e procure o esgoto ao longo da fronteira norte da cidade. Com sorte, aqueles magos não puseram uma proteção num ponto de entrada tão... desagradável.", t = "Sangue nas ruas"},
    [92456] = {ot = "Colete uma Flor Infusa em Vileza de Dalaran para Shylamiir em Ventobravo.", st = "Se você vai me importunar, ao menos seja útil. Tenho uma tarefa para você.\n\nPara uma cidade de magos, Dalaran tem um interesse surpreendente em botânica. O Kirin Tor é bem reservado, mas eu adoraria uma amostra da vegetação imbuída de mana deles.\n\nVocê é claramente alguém que se sente à vontade em lugares onde não é benquist$Go:a;. Talvez possa dar um jeito de entrar na cidade. Se conseguir, traga para mim o que estiver crescendo no jardim central deles.", t = "Uma amostra verde"},
    [92457] = {ot = "Derrote $1oa Resquícios Caçadores, $2oa Resquícios Saturados e $3oa Ecos de Mana em Dalaran a pedido da Arquimaga Modera, nos arredores de Dalaran.", st = "O rompimento afetou muitos dos nossos serviçais e encantamentos por toda a cidade, incluindo vários que estão encarregados das nossas defesas. Essa energia arcana fragmentada atraiu elementais renegados que buscam se alimentar dessa magia que flui livremente.\n\nEnquanto estamos ocupados mantendo as proteções e lidando com outros incidentes maiores, seria um favor ao Kirin Tor se você pudesse exterminar essa corja elemental.", t = "Fome arcana"},
    [92458] = {ot = "Colete a Partícula Arcana para a Imagem da Arquimaga Modera nos arredores de Dalaran.", st = "O que quer que tenha desestabilizado os meridianos começou no topo da Cidadela Violeta. Um estrondo ensurdecedor ressoou dos salões acima, e agora estamos inundados por um poder arcano desenfreado. Estamos dando tudo de nós apenas para manter as barreiras de pé.\n\nNão podemos mais perder tempo. Precisamos de ajuda.\n\nO Kirin Tor está ocupado lá dentro, mas você ainda precisará de um jeito mais discreto para conseguir entrar. Leve esta chave e me encontre na cidadela assim que abrir caminho para dentro da cidade. Precisamos dar um fim a essa instabilidade.", t = "No centro da instabilidade"},
    [92460] = {ot = "Fale com Rorian, o Caça-alva, no Bosque Thendal.", st = "Olhe para você, com os olhos brilhando e $Gpronto:pronta; para a aventura! Precisamos de toda ajuda possível aqui na Aldeia Thendal, e a sua chegada é muito bem-vinda. Imagino que você esteja transbordando de nervosismo com o que está por vir. Afinal, só se entra na idade adulta uma vez na vida.\n\nVá, procure o líder da nossa aldeia — Rorian, o Caça-alva — na entrada da árvore ancestral, a oeste daqui. Ele dará início à sua jornada.", t = "A maturidade"},
    [92461] = {ot = "Mate 8 Vuldrens Juvenis no Bosque Thendal.", st = "Vivemos em tempos de grande incerteza para nosso povo. Enfrentamos desafios sem precedentes que podem exigir soluções ousadas, mas também devemos lidar com o ordinário e o mundano aqui no Bosque Thendal. Tome como exemplo a recente escalada na população de vuldrens, que se tornou insustentável.\n\nOs vuldrens são uma parte vital do nosso ecossistema. No entanto, desequilíbrios devem ser corrigidos para manter a delicada harmonia da qual todas as criaturas no Bosque Thendal partilham.\n\nVá para leste e abata alguns dos vuldrens por lá.", t = "Harmonia em equilíbrio"},
    [92462] = {ot = "Extermine 8 Cirromoscas Irritantes no Bosque Thendal.", st = "Um de nossos patrulheiros relatou recentemente uma infestação de cirromoscas aqui no Bosque Thendal.\n\nAs cirromoscas podem ser perigosas se o enxame crescer demais, então vá para a extremidade leste do Bosque e extermine quantas puder.", t = "Investigação da infestação"},
    [92463] = {ot = "Mate a Rainha Cirromosca no Bosque Thendal.", st = "Se a floresta estiver tão infestada desses insetos como parece, matar apenas os operários não vai ser suficiente.\n\nVá mais fundo na floresta e encontre a rainha. Ela estará perto da colmeia e rodeada por soldados maiores e mais agressivos, então tenha cuidado.\n\nAcabe com ela e volte a mim quando terminar o serviço. Será um problema a menos para me preocupar por aqui.", t = "A rainha cirromosca"},
    [92464] = {ot = "Fale com Yala Vigivento no Bosque Thendal.", st = "Desde que nossos benfeitores elementais nos deixaram, parece que estamos simplesmente passando de uma agitação para outra. O problema que enfrentamos agora é que as manifestações dos ventos perto das pedras erguidas, a nordeste, estão agitadas.\n\nNão sendo de fato autoconscientes como os espíritos do vento sencientes que um dia viveram aqui, esses espíritos elementais simples reagem de acordo com as forças, emoções e intenções das criaturas ao seu redor.\n\nMinha aprendiz Yala Vigivento foi observá-los. Procure-a e descubra o que ela aprendeu.", t = "Agitação elemental"},
    [92465] = {ot = "Mate $2oa Ventos Turbulentos e $1oa Convertidos Al'Aketh no Bosque Thendal.", st = "A seita Al'Aketh é uma praga nesta ilha. Esses sectários são certamente os responsáveis por irritar os espíritos do vento que aqui residem e torná-los violentos.\n\nInfelizmente, precisaremos dispersar esses ventos turbulentos antes que machuquem alguém. Também precisamos enviar uma mensagem clara à seita de que eles não são bem-vindos no bosque.\n\nVocê me ajudará, $c?", t = "Agitadores"},
    [92466] = {ot = "Leve um Sinete de Akir para o Moldavento Boro.", st = "Embora devamos grande parte da nossa prosperidade aos elementos do vento, o caminho que trilhamos exige que obedeçamos ao chamado de todos os quatro elementos primordiais e realizemos uma provação para cada um deles. Antes de iniciar sua primeira provação a sério, porém, você deve atestar a força de sua determinação.\n\nViaje até as pedras erguidas a leste. Um grupo de convertidos Al'Aketh foi avistado por lá e precisa ser rechaçado. Confronte os sectários no local e me traga um dos sinetes deles como prova de seus feitos.", t = "O chamado da terra"},
    [92467] = {ot = "Encontre o Cerro dos Espíritos e beba o Sapta da Terra.", st = "Uma sapta é uma bebida criada para vincular o nosso espírito aos elementos. Infundida com magia, a poção permitirá a quem tem vontade férrea enxergar os elementos como ninguém mais pode. Seu espírito vai se conectar ao elemento para o qual a sapta foi criada, e somente um seleto grupo de xamãs conhece a receita.$B$BA sapta sempre é bebida em um local sagrado, e nunca em qualquer outro lugar. Lembre-se disso.$B$BProcure pelo Cerro dos Espíritos subindo a trilha a leste daqui. Beba a sua sapta lá e... bem, você verá o que precisa ver.", t = "O chamado da terra"},
    [92468] = {ot = "Leve o Quartzo Grosseiro ao Moldavento Boro na Bosque Thendal.", st = "Pegue este Quartzo Grosseiro e leve-o àquele que você chama de Moldavento Boro como prova do nosso encontro. Ele forjará um totem para você, e este fragmento será o coração dele. Por menor que pareça, você descobrirá que o tamanho não importa e que até as menores coisas podem resistir muito mais que as outras.$B$BTenha paciência, $n. Permaneça forte. E busque sabedoria. É isso que os elementos pedem a você. No fim, você entrará em comunhão com a terra. Respeite-a, assim como ela respeitará você.", t = "O chamado da terra"},
    [92469] = {ot = "Leve a notícia da presença do Al'Aketh para Rorian, o Caça-alva, no Bosque Thendal.", st = "Você já fez o bastante aqui, $c. Eu vou ficar e cuidar de quaisquer remanescentes lá embaixo.\n\n Volte para a aldeia e conte a Rorian a respeito da presença do culto. Ele não ficará nada satisfeito.", t = "Fale novamente com Rorian"},
    [92470] = {ot = "Mate 8 Catadores Ursera e colete a cabeça da matriarca do covil, Urs'anah, no Bosque Thendal.", st = "Rorian avisou que eu tenho observado você. Agora eu lhe ofereço um teste de determinação. No entanto, esteja ciente: ele enviará você a um grande perigo.\n\nVá às cavernas a oeste. Reduza o número de urseras por lá e encontre a matriarca deles, a quem um dos patrulheiros chama de \"Urs'anah\". Elimine-a e traga-me a prova da morte dela. Depois de fazer isso, você terá dado um passo importante em seu caminho.", t = "Má-triarca"},
    [92471] = {ot = "Fale com Aetheen das Ventanias no Bosque Thendal.", st = "Você pode não perceber, mas tudo o que fez foi, de certa forma, uma provação. Um teste do que está por vir para você. A ilha é grande, e Zefras precisa de jovens $Gaventureiros determinados:aventureiras determinadas; como você se quisermos sobreviver aos desafios que o nosso povo enfrenta.\n\nAquela a quem chamam de Aetheen das Ventanias é uma das líderes do nosso povo aqui na Ilha de Zefras, e ela vem observando você. Ela tem uma tarefa que você precisa cumprir. Fale com ela para saber mais.", t = "Aetheen das Ventanias"},
    [92472] = {ot = "Apresente-se à Oficial Aonda na Aldeia de Shen'dar.", st = "Uma das ameaças mais disseminadas na Ilha de Zefras é a Seita Al'Aketh. Eles são fanáticos religiosos dedicados à adoração do suposto governante elemental da Muralha Celeste, Al'Akir, o Senhor do Vento. Eles são brutais e obstinados, e o poder e as ambições deles estão se tornando mais letais a cada dia.\n\nSeu caminho logo levará você à Aldeia de Shen'dar, ao sul. Apresente-se à Oficial Aonda quando chegar. O culto ameaça Shen'dar, e eles precisam de ajuda. Diga a Aonda que eu enviei você.", t = "O próximo passo"},
    [92473] = {ot = "Colete 6 Garras de Ursera Delgado de Urseras Delgado no Bosque Thendal.", st = "A toca dos urseras, a sudoeste, está se tornando rapidamente um problema. Só na semana passada, os patrulheiros tiveram que matar um ursera adolescente que se aproximou demais da aldeia e tentou atacar um garoto que brincava perto da base da árvore ancestral.\n\nTivemos sorte de o menino ter escapado com vida. A fome e o desespero tornam essas feras perigosas demais para serem deixadas sem controle. Vá para o sul e abata os mais magros entre os urseras. Traga as garras deles como prova do feito.", t = "Ocupação agressiva"},
    [92474] = {ot = "Salte do topo da torre de guarda no Bosque Thendal e use sua habilidade de Andar no Ar para desacelerar a queda.", st = "Ora, como vai, $n? Que tal uma brincadeira?\n\nVocê só precisa subir naquela saliência... e depois saltar! Use sua habilidade inata de andar sobre o ar para desacelerar sua queda e veja até onde você consegue caminhar.\n\nAs regras são inventadas e os pontos não importam, mas você ganha pontos bônus se conseguir cair bem na frente do Rorian, o Caça-alva, e assustá-lo! Ele não vai gostar, mas com certeza eu vou dar boas risadas se você conseguir deixá-lo todo irritado! Rá!", t = "Caindo com estilo"},
    [92479] = {ot = "Leia a Carta Garranchada e fale com o Tordrin Caulâmina na Abadia de Vila Norte.", st = "Pediram-me para lhe entregar isto assim que você voltasse dos assentamentos de kobolds, $n. Parece ser uma carta selada com a marca de Tordrin Caulâmina, nosso instrutor de caçadores local. Vale a pena lê-la antes de tratar de qualquer outro assunto aqui na Abadia.", t = "Carta garranchada"},
    [92481] = {ot = "Examine o Cristal de Recordação Chamejante e depois fale com Dorii Soproluz no Bosque Thendal.", st = "Enquanto você estava fora lidando com o nosso problema com os vuldrens, nossa instrutora de magos residente, Dorii Soproluz, lhe deixou este cristal de recordação. Ele contém algum tipo de mensagem para você, então dê uma olhada. Depois disso, você pode encontrar Dorii na estrutura logo atrás de mim.", t = "Estudante do arcano"},
    [92482] = {ot = "Leia a Anotação Rabiscada e depois fale com Tai'ree Fitalonge no Bosque Thendal.", st = "Enquanto você estava fora lidando com o nosso problema com os vuldrens, nossa instrutora de caçadores residente, Tai'ree Fitalonge, deixou esta anotação para você. Você pode encontrá-la logo ali, perto do centro da aldeia. Leia a anotação e vá atrás dela.", t = "O caminho do caçador"},
    [92483] = {ot = "Leia o Bilhete e depois fale com Akeri Gumúmbrio na Torre de Guarda do Bosque Thendal.", st = "Enquanto você estava fora lidando com o nosso problema com os vuldrens, nosso instrutor de ladinos residente, Akeri Gumúmbrio, pediu para falar com você. Ele deixou este bilhete, então leia-o e depois procure por Akeri na torre de guarda aqui na aldeia.\n\nEle é um sujeito meio suspeito, mas você também é. Creio que vocês vão se dar bem.", t = "Um lar nas sombras"},
    [92484] = {ot = "Examine o Cristal de Recordação Murmurante e depois fale com Moldavento Boro no Bosque Thendal.", st = "Enquanto você estava fora lidando com o nosso problema com os vuldrens, nosso instrutor de xamãs residente, Moldavento Boro, deixou este cristal de recordação para você. Examine-o e depois fale com Boro logo ali, perto do centro da aldeia.", t = "Comunhão com os elementos"},
    [92485] = {ot = "Leia o Pergaminho Dobrado e depois fale com Xyton Brisaprata no Bosque Thendal.", st = "Enquanto você estava fora lidando com o nosso problema com os vuldrens, nosso instrutor de druidas residente, Xyton Brisaprata, deixou este bilhete para você. Leia-o assim que puder e depois procure por Brisaprata na base dessa grande árvore logo atrás de mim.\n\nOuça suas palavras e conselhos, pois ele tem muito a lhe ensinar.", t = "Estudante da natureza"},
    [92489] = {ot = "Mate o Elemental de Mana em Dalaran a pedido do Grão-Feiticeiro Andromath em Ventobravo.", st = "O Kirin Tor é aliado de longa data da Aliança. Com a destruição de sua cidade nas mãos do arquidemônio Arquimonde, a outrora orgulhosa cidade dos magos se tornou reclusa e pouco afeita a forasteiros.\n\nNos últimos anos, eles têm feito esforços para reconstruir Dalaran e devolvê-la à glória de outros tempos. Há, porém, relatos de que eles estão lutando para conter um surto de energias arcanas descontroladas.\n\nPrecisamos ajudá-los a dispersar esses ataques para preservar um dos nossos mais poderosos aliados.", t = "Poder esmagador"},
    [92514] = {ot = "Fale com Illaya Ventâmbar e Coriella Ventocalmo na Aldeia de Shen'dar.", st = "Você tem um certo ar de \"Moldavento\". Sei porque sinto algo como uma leve estática em minha pele sempre que estou perto de alguém Tocado no Espírito. Antes de colocar você para trabalhar decentemente aqui, fale com nossa anciã Moldavento residente, Illaya Ventâmbar. Ela está lá fora, perto do centro da cidade.\n\nAh, e fale também com Coriella Ventocalmo. Ela administra a estalagem local e pode fornecer hospedagem e suprimentos, se você precisar.", t = "Boas-vindas à Aldeia de Shen'dar"},
    [92515] = {ot = "Colete 10 Pelagens de Garraltiva de Garraltivas no Planalto de Shen'dar.", st = "Como se não bastassem bandidos e sectários malucos, as colinas também estão apinhadas de garraltivas. Elas estão começando a avançar sobre as fronteiras da aldeia e ficando cada vez mais ousadas. É questão de tempo até o bichinho ou o filho de alguém sumir. Seria muito melhor reduzir o contingente delas agora, em vez de esperar uma tragédia acontecer.\n\nTraga umas dez pelagens. Posso transformá-las em todo tipo de mercadoria útil para a aldeia.", t = "O gargalo das garraltivas"},
    [92516] = {ot = "Mate 8 Jovens Hipogrifos, 6 Protetores Hipogrifos e uma Matriarca Hipogrifo no Planalto de Shen'dar.", st = "Recentemente, um bando de Hipogrifos montou um ninhal a sudeste da Aldeia de Shen'dar e está causando transtorno aos viajantes na estrada. Preciso que alguém vá até lá e elimine alguns deles.", t = "Hipogrifos hostis"},
    [92517] = {ot = "Elimine 10 Bandidos do Planalto e o líder deles, Bennic \"Malevento\", no Planalto de Shen'dar.", st = "Há uma caverna perto daqui, ao norte, escondida atrás de uma cachoeira. É fato que um grupo de bandidos opera a partir de lá. Eles já eram um problema antes da chegada da seita, mas agora são um verdadeiro terror. Infelizmente, não tenho gente suficiente pra ir até lá dar um jeito neles.\n\nPreciso que você faça isso por mim. Elimine quantos puder e, se possível, acabe com o líder deles, aquele que chamam de Bennic \"Malevento\". A caverna é perigosa, tenha cuidado.", t = "O elemento criminoso"},
    [92528] = {ot = "Explore a Aldeia de Falaath para descobrir as intenções da seita no Planalto de Shen'dar.", st = "Os fiéis de Al'Akir ficam cada vez mais fortes a cada $Gnoviço:noviça; como você. Como você pode ver, nossa força molda a própria tempestade!\n\nO normal seria enviar você ao Sacerdote do Céu Aanders para avaliação, mas ele está ocupado recebendo um convidado na estalagem na parte norte da cidade. Peço que evite aquela área por ora. Seria impróprio alguém $Ghirsuto:hirsuta; como você na presença de tal convidado.\n\nPor enquanto, apenas não atrapalhe ninguém.", t = "Entre os fiéis"},
    [92529] = {ot = "Procure o Missionário Jasaan perto da entrada da Aldeia de Falaath.\n\nSe você perder sua Marca de Akir, fale com Sania Fluviprata na Aldeia de Shen'dar para recuperar o efeito.", st = "Fico muito feliz por saber que você deseja servir a Al'Akir. Nossas provações como povo vêm da nossa própria complacência. Nós nos tornamos orgulhosos e passamos a subestimar as bênçãos dos ventos. Por causa da estagnação resultante disso, os espíritos do vento nos abandonaram.\n\nSomente por meio de atos de contrição poderemos sentir novamente o afago do vento. Se você busca a comunhão com shen'dorei que pensam como você, vá até a Aldeia de Falaath e procure o Missionário Jasaan. Eu marcarei você para que os fiéis $Go:a; reconheçam como $Gnoviço:noviça;.", t = "Aldeia de Falaath"},
    [92532] = {ot = "Leia o Bilhete Amarrotado que lhe foi dado, depois procure pela Mestre de Espadas Ren na torre de guarda da Aldeia Thendal.", st = "Enquanto você estava fora, nossa instrutora de guerreiros, Mestre de Espadas Ren, pediu que enviássemos você até ela quando retornasse. Ela também lhe deixou este bilhete.\n\nLeia-o e depois encontre a Mestre de Espadas Ren na torre de guarda da aldeia.", t = "O caminho do guerreiro"},
    [92544] = {ot = "Mate 6 Brutamontes Al'Aketh, 4 Neófitos Al'Aketh, e Malduko Nubismaga no Bosque Thendal.", st = "Um bando de rufiões da seita Al'Aketh se instalou perto das ruínas do templo a sudoeste daqui, liderado por um verdadeiro monstro chamado Malduko Nubismaga. Essa ralé foi sem dúvida enviada para cá pela Alta-sacerdotisa Lorthuna, no Santuário de Akir, para atacar viajantes e coagir nosso povo a se juntar à seita.\n\nPreciso permanecer aqui no meu posto para alertar os viajantes que saem do bosque sobre o perigo, mas ficaria agradecida se você pudesse fazer algo a respeito desses sectários e seu líder por mim.", t = "Bandido Al'Aketh"},
    [92550] = {ot = "Vá até as ruínas da Aldeia de Falaath e mate 6 Tempestários Al'Aketh, 4 Raios Vivos e pegue a cabeça do Comandante Ciclas.", st = "Talvez a nossa melhor defesa seja um ataque forte. Nossa vantagem é que esperamos um ataque iminente. O que eles não esperam é que nós vamos atacá-los primeiro.\n\nJá pedi muito de você, mas peço que volte para a Aldeia de Falaath. Mate o máximo de sectários possível e, se conseguir se aproximar mais, mate o comandante e traga a cabeça dele. Vou ficar aqui organizando os cidadãos e nossos poucos pacificadores para preparar uma defesa... só para o caso de você não voltar.", t = "Pânico no planalto"},
    [92551] = {ot = "Colete 10 pacotes de Suprimentos Roubados de Shen'dar na Aldeia de Falaath, no Planalto de Shen'dar.", st = "Fiquei sabendo que talvez você vá para a Aldeia de Falaath. Enquanto estiver por lá, peço que fique de olho pra ver se encontra nossos depósitos de suprimentos roubados.\n\nJá faz alguns meses que os Al'Aketh atacam nossas caravanas de suprimentos, que levam mercadorias como comida e pedras pelas baixadas. É claro que eles culpam bandidos, mas todo mundo sabe que tudo acaba indo pro mesmo lugar. Se ainda tiver sobrado alguma coisa em Falaath, seria muito útil pra gente.", t = "Suprimentos roubados"},
    [92553] = {ot = "Colete $1oa Ovos Pequenos e $2oa Carnes de Moa de criaturas que vivem no Planalto de Shen'dar.", st = "Tem interesse num trabalho? A força de alguém como você, que vive uma vida de aventuras, seria muito útil pra mim. As coisas estão ficando perigosas por aqui, e ninguém teve muito tempo pra caçar ou coletar alimentos ultimamente. Preciso de alguém pra buscar ovos frescos e carne de moa pra alimentar a aldeia.\n\nTraga o que eu preciso e vou ter o maior prazer de ensinar a você uma das minhas receitas famosas. O que acha?", t = "Reabastecendo a despensa"},
    [92579] = {ot = "Entregue o relatório por escrito de Aonda a Valennia Tempespunho em Valanaar.", st = "Aparentemente, o pilar e a aldeia estão seguros. Por isso, peço que entregue este relatório a Valennia Tempespunho em Valanaar, no extremo sudeste da ilha. Valennia é a líder dos pacificadores da ilha e precisa saber o que aconteceu aqui.\n\nA seita está se expandindo rapidamente, e os pacificadores evitaram o conflito direto até o momento, mas a situação mudou. Valanaar terá que se preparar para uma luta.\n\nDe qualquer forma, agradeço. Você sempre terá amigos em Shen'dar, $n.", t = "Rumo a Valanaar"},
    [92595] = {ot = "Ouça o que Illaya Ventâmbar tem a dizer.", st = "<Illaya lhe lança um sorriso caloroso.> \n\nFico feliz que você tenha voltado para falar comigo, $Gfilho:filha; dos ventos. Eu soube desde o momento em que você veio à minha presença que você era forte na Visão do Céu. Acha isso surpreendente? Até quem não tem treinamento de xamã pode ter o dom.\n\nVenha, vamos falar do mandato dos Moldavento, da natureza de nossas pelejas em Zefras e do tormento de nosso povo.", t = "Os Moldavento"},
    [92596] = {ot = "Sente-se e converse com Rathiril Arrebol.", st = "A aura de energia arcana que rodeia você é forte, mesmo que você não tenha se iniciado como $Gmago:maga;. Tenho quase certeza de que você será $Gum bom aventureiro:uma boa aventureira;, e a sua ligação com nossa magia ancestral sempre lhe será uma dádiva, mesmo que você jamais chegue a pronunciar uma palavra sequer de poder ao lançar feitiços.\n\nVenha, vamos nos sentar e falar um pouco da natureza do arcano aqui em Zefras e do tormento do nosso povo.", t = "A Alta Ordem"},
    [92597] = {ot = "Use sua habilidade racial Leitura de Meridiano no meridiano do Bosque Thendal.", st = "Aqui no plano elemental, obtemos grande parte do nosso poder arcano dos meridianos que ainda correm pelo solo sob nossos pés. Ultimamente, esses meridianos começaram a romper a superfície, dando acesso mais direto e poderoso a essas energias arcanas latentes.\n\nVá até as pedras erguidas a nordeste. Há um meridiano ali. Conecte-se ao seu direito de nascença e absorva a energia dele.", t = "Leitura dos meridianos"},
    [92598] = {ot = "Use a habilidade Visão do Céu, inerente à sua raça, em uma Convergência Elemental no Bosque Thendal.", st = "Como Moldavento, você tem a habilidade de usar a sagrada visão do céu concedida a nós pelos espíritos elementais. Viaje até as pedras erguidas a nordeste da aldeia. Encontre a convergência elemental no local e use seu dom.\n\nVocê descobrirá que pode canalizar a visão do céu em qualquer lugar, mas a bênção dela é muito mais poderosa se fizer isso na presença de uma convergência elemental. Às vezes, você também poderá receber outros fragmentos de sabedoria dos espíritos que são atraídos para esses locais de poder.", t = "O dom da visão do céu"},
    [92640] = {ot = "Fale com Valennia Tempespunho em Valanaar e siga as instruções dela.", st = "Como enfrentar a seita abertamente não é viável, nossa melhor chance será aproveitar esta oportunidade para atacar o próprio santuário. Podemos tirar Lorthuna da jogada antes que ela consiga terminar sua parte neste plano.\n\nPor acaso Valennia já vem preparando uma estratégia para um possível ataque ao Santuário há algum tempo. O único problema é que precisaremos de ajuda.\n\nFale com Valennia para saber os detalhes.", t = "Tempos desesperados"},
    [92642] = {ot = "Mate 4 Curandeiros Al'Aketh e 8 Brigões Al'Aketh nos Baixios dos Lufopomos.", st = "Valennia enviou apenas uma pessoa para ajudar a repelir um ataque em grande escala... pelos ventos.\n\nVocê não parece grande coisa, mas aceito qualquer ajuda. Precisamos causar o máximo de dano possível para acabar logo com isso. Meu pessoal não vai aguentar muito tempo.\n\nDesça a colina e sabote a logística deles. Os curandeiros inimigos mantêm o fluxo de atacantes; se os eliminarmos, talvez possamos nos reagrupar e forçá-los a recuar. Qualquer outro sectário que você matar por lá também será de grande ajuda.", t = "Sabotando a logística"},
    [92643] = {ot = "Encontre o desertor da seita na casa logo na entrada do planalto, a noroeste de Valanaar.", st = "Há um desertor entre os Al'Aketh. Ele alega saber as verdadeiras intenções do culto para a ilha e quer se entregar, mas só fará isso mediante garantias de proteção.\n\nEsse desertor está escondido em uma residência isolada logo a noroeste de Valanaar, dentro do planalto. Preciso de alguém que possa ir até lá com discrição, encontrar o traidor e escoltá-lo de volta até nós. Pode ser uma armadilha, mas, se essa informação for tão importante quanto esse traidor afirma, vale a pena correr algum risco.", t = "O desertor"},
    [92644] = {ot = "Entregue o cristal brilhante para Talaanis Cantonegro em Valanaar.", st = "<Você põe a mão por baixo do corpo ainda quente do sectário desertor e recupera um pequeno e brilhante cristal. Ele parece estar danificado, mas ainda pode ser importante. Talvez o Sumo Ancião Cantonegro se interesse por isso.>", t = "Uma notícia infeliz"},
    [92645] = {ot = "Mate a Comandante Belguilos nos Baixios dos Lufopomos.", st = "Este ataque será difícil de repelir se não conseguirmos eliminar a comandante da seita. Eles a chamam de Belguilos, a Quebradora, e ela é um verdadeiro terror. Ela era uma pacificadora antes de a seita sair do controle, e mesmo naquela época já era meio... perturbada. Como sectária, imagino que ela deve ter piorado muito.\n\nTalvez eu esteja mandando você para a morte, mas alguém precisa eliminar Belguilos se quisermos sobreviver aqui. Você pode encontrá-la na vila na base da colina. Boa sorte, $c.", t = "Quebrando a quebradora"},
    [92646] = {ot = "Pegue o portal para os Pináculos Rohashi e junte-se a Elaadrin Plenovento e Ayessa Cantalva no confronto contra a Alta-sacerdotisa Lorthuna.", st = "Lorthuna fugiu para os pináculos lá no alto usando algum tipo de portal. Ayessa e Elaadrin entraram atrás dela. Isso foi há poucos instantes.\n\nReceio não estar em condições de ir. Atravesse o portal, encontre Ayessa e ajude-os a deter Lorthuna.\n\nA menos que a ajuda que Elaadrin e Ayessa disseram ter solicitado chegue logo, você está por conta própria a partir daqui. Boa sorte, $c.", t = "Confronto com Lorthuna"},
    [92679] = {ot = "Ouça o que Alvarion Campo de Vento tem a dizer e encontre Aamelia Campo de Vento no Pomar dos Campo de Vento.", st = "O-Olá, viajante. Você tem o porte de $Gum aventureiro:uma aventureira; capaz. Eu...\n\n<O celonato se contorce, claramente sofrendo com uma dor terrível.>\n\n... Eu queria saber se você está em busca de trabalho. Vim a Valanaar recrutar combatentes para ajudar a salvar minha fazenda. Se houver interesse, por favor, procure minha esposa Aamelia Campo de Vento em nosso pomar a oeste de Valanaar, nos baixios.", t = "Dízimo de sangue"},
    [92682] = {ot = "Colha 10 Maçãs-dos-raios Maduras e mate 5 Bandidos Famintos no Pomar dos Campo de Vento.", st = "Ah, então você tem mais coragem do que juízo? Tudo bem, não vou discutir.\n\nFerauu e seus capangas ainda vão demorar para buscar a parte deles da colheita, então vou colocar você para trabalhar em troca de comida até que cheguem.\n\nVá lá fora e colha a remessa de maçãs-dos-raios de hoje para mim. Ah, e os bandidos à espreita perto das macieiras-dos-raios... Eles julgam ser sorrateiros. Pois não são. Mate-os para mim. \n\nVamos ver do que você é capaz em uma luta.", t = "Faça alguma coisa útil"},
    [92683] = {ot = "Colete 5 punhados de Pó de Asaleve das Asaleves ao redor dos Baixios dos Lufopomos.", st = "Tenho certeza de que você notou as asaleves gigantes nos campos mais afastados perto do pomar, certo? Elas são bonitas de se ver, mas também oferecem outras vantagens: mais especificamente, o pó de suas asas. Pode fazer sujeira, mas, se você conseguir juntar uma grande quantidade, ele tem utilidades domésticas muito práticas.\n\nPegue esse mata-asaleves e dê um bom golpe naqueles insetões para mim. Geralmente, elas só se assustam e fogem, mas às vezes podem se irritar. De qualquer forma, vão dar uma sacudida no traseiro e largar um monte de pó.", t = "Pó de asaleve"},
    [92684] = {ot = "Colete 7 Lombos de Vagaventos das Terras Baixas dos Vagaventos Turrões encontrados pelos Baixios dos Lufopomos.", st = "Como se a colheita já não estivesse escassa o suficiente este ano, os vagaventos da região começaram a invadir o pomar para roubar minhas maçãs-dos-raios. Acha que consegue ir até os campos e abater alguns para mim?\n\nMas tome cuidado, viajante. Esses vagaventos dos baixios são maiores e mais furiosos do que os do planalto. Fique alerta. Um chute na hora certa é tudo de que precisam para derrubar você de vez se não estiver prestando atenção.\n\nTraga um pouco da carne deles para mim e poderei preparar uma refeição quente para nós também.", t = "Vagaventos turrões turrões"},
    [92685] = {ot = "Saqueie 7 Máscaras de Bandido Manchadas de Sangue de Bandidos Bandoleiros nos Baixios dos Lufopomos.", st = "Os bandidos têm acampamentos por todo lado, e há um pequeno nas colinas bem ao norte daqui. Suba até lá e comece a rachar uns crânios. Se conseguirmos pegá-los desprevenidos e acabar com eles antes que venham atrás de nós, podemos equilibrar as forças o suficiente para termos uma chance.\n\nTraga as máscaras deles para mim. Quanto mais ensanguentadas, melhor.", t = "As colinas têm olhos"},
    [92693] = {ot = "Fale com Aamelia Campo de Vento quando estiver com tudo pronto para confrontar o líder dos bandidos.", st = "Você fez muito para nos dar uma chance de lutar. Mesmo que a gente morra hoje, pelo menos saberemos que demos tudo de nós.\n\nEsta é sua última chance, viajante. Se quiser voltar para Valanaar e viver mais um dia, não culpo você.\n\nPor outro lado, se você realmente tem uma queda por causas perdidas, é só me avisar quando estiver $Gpronto:pronta;. Vamos sair de lá de cabeça erguida e o que será, será.", t = "Defendendo o que é nosso"},
    [92698] = {ot = "Fale com Aamelia Campo de Vento a respeito do Construto Ciclônico Defeituoso.", st = "<Você se aproxima para tentar ouvir as palavras que vêm de baixo das placas de armadura do constructo gigante.>\n\n... Erro de função...\n\n... Pergunta...\n\n... Qual é a...\n\n... Função...\n\n<Essas palavras e frases fragmentadas parecem apenas se repetir. Talvez alguém por perto saiba mais sobre este constructo.>", t = "Qual é o meu propósito?"},
    [92699] = {ot = "Encontre Elaadrin Plenovento em Valanaar.", st = "Agora que você chegou a Valanaar, provavelmente vai querer falar com os outros membros da Alta Ordem. Elaadrin Plenovento, o atual Magíster Supremo, e sua gente operam no alojamento no extremo sudeste de Valanaar.\n\nFique alerta, pois a Alta Ordem e os Moldavento não se dão muito bem por aqui. Tome cuidado e mantenha uma boa distância dos Moldavento. Já temos muitas preocupações com a seita. Não vou tolerar violência de facções nas ruas de Valanaar.", t = "O Magíster Supremo"},
    [92700] = {ot = "Encontre Ayessa Cantalva em Valanaar.", st = "Agora que você chegou a Valanaar, provavelmente vai querer falar com os outros membros dos Moldavento. A Grande Vidente do Céu atual e seu povo operam no alojamento perto do centro de Valanaar.\n\nSaiba também que os Moldavento e a Alta Ordem não se dão muito bem por esses lados. Tome cuidado e mantenha uma boa distância da Alta Ordem. Já temos muitas preocupações com a seita. Não vou tolerar violência de facções nas ruas de Valanaar.", t = "A Grande Vidente do Céu"},
    [92701] = {ot = "Entregue o relatório por escrito de Aonda a Valennia Tempespunho em Valanaar.", st = "Aparentemente, o pilar e a aldeia estão seguros. Por isso, peço que entregue este relatório a Valennia Tempespunho em Valanaar, no extremo sudeste da ilha. Valennia é a líder dos pacificadores da ilha e precisa saber o que aconteceu aqui.\n\nA seita está se expandindo rapidamente, e os pacificadores evitaram o conflito direto até o momento, mas a situação mudou. Valanaar terá que se preparar para uma luta.\n\nDe qualquer forma, agradeço. Você sempre terá amigos em Shen'dar, $n.", t = "Rumo a Valanaar"},
    [92703] = {ot = "Fale com Alvarion Campo de Vento em Valanaar.", st = "Não me parece certo continuar chamando você de viajante depois de tudo isso, então... obrigada, $n. \n\nSe não se importar e for tomar aquele caminho de volta, por favor, conte a Alvarion o que aconteceu aqui. Além disso, diga a ele que, assim que estiver recuperado, precisa trazer um Moldavento de volta para examinar aquele constructo e garantir que é seguro tê-lo perto da nossa... nossa família.\n\n<Aamelia toca o ventre com delicadeza.>\n\nEle ainda não sabe dessa parte. Vamos manter isso apenas entre nós por enquanto.", t = "Dê as boas novas"},
    [92706] = {ot = "Leve a Barbatana Dorsal de Bruuz para o Gasganete na Vila Catraca.", st = "Chamando todos os pescadores!\n\nTem um tubarão gigante rondando as águas perto da doca e atacando marinheiros e pequenas embarcações. Os estivadores apelidaram ele de Bruuz. Quem me trouxer a barbatana dorsal dele ganha uma recompensa gorda!\n\n— Gasganete", t = "PROCURA-SE: Bruuz"},
    [92708] = {ot = "Ouça o que Ayessa Cantalva tem a dizer.", st = "Os Moldavento têm trabalhado arduamente na tentativa de responder à crise atual na Ilha de Zefras. Fizemos várias descobertas surpreendentes em nossa busca pelos espíritos do vento desaparecidos e estamos desenvolvendo um plano de ação que pode nos ajudar a obter os meios para salvar a ilha.\n\nNo entanto, precisaremos de jovens aventureiros fortes como você para que isso funcione. Se tiver um momento, vamos conversar mais a respeito.", t = "Uma grande aventura"},
    [92709] = {ot = "Escute o que Elaadrin Plenovento tem a dizer em Valanaar.", st = "Sua linhagem altaneira brilha em seus olhos tão claramente quanto o céu lá no alto. Você é dos nossos, e são jovens como você que nos ajudarão a salvar nosso lar. Mas, antes, deixe-me falar mais sobre nossa missão e nossos planos, aqui em Zefras... e além.", t = "Uma grande aventura"},
    [92727] = {ot = "Descubra o paradeiro de Filião Brisardente.", st = "Buscar conhecimento é a principal missão da Alta Ordem, mas este trabalho nunca foi tão perigoso quanto é agora em Zefras.\n\nUm de nossos estudiosos, Filião Brisardente, estava a caminho do Planalto de Shen'dar para coletar dados sobre a magia pairavento que se concentra em algumas daquelas áreas. Lamentavelmente, ele não retornou, e tememos que algo possa ter lhe acontecido na estrada.\n\nSe puder, por favor, localize-o para nós. Ele foi visto por último na estrada que segue a oeste de Valanaar, em direção ao Planalto de Shen'dar.", t = "O erudito desaparecido"},
    [92741] = {ot = "Vá até a Floresta Umbréola e colete 8 Garras de Guinchote para Iaadaria Ventamargo em Valanaar.", st = "A Floresta Umbréola é incrivelmente perigosa e costuma ser proibida para aventureiros comuns. Nos últimos meses, houve uma explosão na população de guinchotes, e eles começaram a expandir seu território para fora dos bosques, o que é um problema em potencial. Tenho interesse nas propriedades alquímicas das garras de guinchote, portanto um abate muito necessário também representa uma oportunidade de ganho acadêmico.\n\nViaje para a Floresta Umbréola e cace as feras. Traga-me o maior número de garras que conseguir.", t = "Visitantes indesejados"},
    [92742] = {ot = "Use o Kit de Amostras de Água de Poço para coletar amostras dos poços no Sítio dos Jansen e na Fazenda dos Peçanha.", st = "Precisamos determinar a fonte e a natureza do veneno que corrompe esta terra. Comecemos pelas águas subterrâneas sob as fazendas da região.\n\nVá ao Sítio dos Jansen, ao norte, e à Fazenda dos Peçanha, a noroeste daqui, e colete amostras dos poços de lá.", t = "Testando os poços"},
    [92744] = {ot = "Alba Belua quer que você colete 7 Guelras de Murloc da Praia Grande ao longo da costa de Cerro Oeste.", st = "A corrupção que afeta as plantações de Cerro Oeste pode ter se infiltrado no oceano também. Se os peixes locais também forem afetados, Ventobravo pode estar fadada à fome.\nColete guelras dos murlocs ao longo da costa e traga para mim. Murlocs são bastante resistentes, mas sua fisiologia é extremamente sensível a contaminantes. Se houver alguma toxina na água do mar, ficará evidente nas guelras que você encontrar.", t = "Guelras de Murloc"},
    [92745] = {ot = "Mate 4 Escavadores Kobolds na Mina Veiojango e 6 Mineradores Pata Molhada na Pedreira Costa Dourada.", st = "As amostras dos poços que você coletou contêm metais tóxicos! Se não dermos fim a esta corrupção depressa, levará décadas até que plantações possam voltar a crescer neste solo.\nOs Défias tomaram as minas de Cerro Oeste e usam criaturas como mão de obra para extrair recursos. Atrapalhe-os matando os mineradores deles na Mina Veiojango, ao norte, e na Pedreira Costa Dourada, a oeste.", t = "A situação das minas"},
    [92747] = {ot = "Colete 8 Suprimentos Industriais Suspeitos no Arroio da Lua.", st = "Que estranho. O veneno não parece se originar das minas que você investigou.\n\nDisseram que as Minas Mortas abaixo do Arroio da Lua são as maiores e mais profundas de Cerro Oeste, mas estão abandonadas desde a Primeira Guerra. Será que as Minas Mortas voltaram à atividade?\n\nPeço que vá até o Arroio da Lua, $n, para procurar provas de qualquer atividade industrial de mineração. É a última pista que temos!", t = "Espionagem no Arroio da Lua"},
    [92748] = {ot = "Viaje até o Distrito dos Anões em Ventobravo e encontre uma engenheira que possa ajudar.", st = "Os suprimentos que você encontrou apontam para uma operação industrial gigantesca em algum lugar das Minas Mortas. Não há dúvida de que seja a fonte das toxinas que assolam as fazendas de Cerro Oeste. Precisamos impedir essa operação, e rápido.\n\nNão sei o que há lá embaixo, mas será difícil de destruir. Vá até o Distrito dos Anões de Ventobravo e encontre um engenheiro que possa nos fornecer explosivos.", t = "Consulta explosiva"},
    [92749] = {ot = "Obtenha $1oa Dinamites Grosseiras por meio de criação, troca ou na casa de leilões, depois fale novamente com Lorien Grenagem no Distrito dos Anões em Ventobravo.", st = "Sabotagem industrial? Agora você conseguiu minha atenção!\nVamos começar com um pouco de dinamite...", t = "Um plano explosivo"},
    [92750] = {ot = "Fale com alguém da Inteligência de Ventobravo sobre como obter um detonador remoto.", st = "Suponho que você queira uma explosão \"controlada\". Não é tão divertido, mas é uma boa escolha se você quiser continuar com todos os membros no lugar.\nÉ uma pena, mas eu não tenho um detonador remoto. Que tal conferir com os marotos da Inteligência de Ventobravo? Eles devem conseguir algo pra nós.", t = "Detonação à distância"},
    [92751] = {ot = "Leve o Kit de Detonador Remoto para Lorien Grenagem no Distrito dos Anões de Ventobravo.", st = "Você precisa destruir alguma coisa? Isso teria algo a ver com as suas atividades no Arroio da Lua? Ah, não se surpreenda. A AVIN se mantém informada sobre tudo que acontece nas terras de Ventobravo.\n\nSe você pretende causar uma explosão nas cavernas abaixo de Cerro Oeste, é melhor estar bem longe antes. Leve este detonador remoto. É um protótipo recente dos nossos próprios engenheiros.\n\nAh, e seria melhor não mencionar meu envolvimento à sua amiga elfa.", t = "Detonação à distância"},
    [92752] = {ot = "Retorne para Alba Belua em Cerro Oeste.", st = "É isso. A bomba tá pronta! Cuidado com esse detonador, hein.", t = "Consulta explosiva"},
    [92753] = {ot = "Ache a forja escondida nas Minas Mortas e arme os Explosivos Extradestrutivos nas imediações dela. Depois, encontre Alba Belua na saída das Minas Mortas.", st = "A origem do veneno provavelmente está ligada a algum tipo de forja metalúrgica de grandes proporções. Ache um meio de entrar nas Minas Mortas, localize a forja e arme os explosivos.\nEstarei à sua espera nas colinas atrás do Arroio da Lua. Quando retornar, poderemos detoná-los. Tomara que, com a forja destruída, a terra possa começar a se reabilitar.", t = "Destruição nas Minas Mortas"},
    [92819] = {ot = "Use o Detonador.", st = "Estamos quase terminando. Use o detonador e acabe com isso.", t = "Destruição nas Minas Mortas"},
    [92834] = {ot = "Colete 10 Patuás da Pedra Eólica de Al'Aketh dos sectários Al'Aketh encontrados ao norte de Valanaar, nos Campos Lufopomo ou no Santuário de Akir.", st = "Quando o culto começou sua campanha de violência, os Pacificadores e os Moldavento responderam com bravatas. Encarei isso como uma escalada tola, então defendi um diálogo pacífico. Ontem, enviei meu amigo Belathaan Desebrilho ao Santuário de Akir, na esperança de estabelecer esse diálogo.\n\nAcaba de chegar uma caixa contendo a língua de Belathaan, mergulhada em pigmento prateado. \n\nAgora está claro para mim que não há como argumentar com o culto. Mate qualquer sectário que encontrar e traga-me os patuás de oração que eles carregam.", t = "Paz não é opção"},
    [92840] = {ot = "Leve o Cartapácio Esotérico até as Pedras Erguidas do Mirante no Planalto de Shen'dar e use-o nas Formações de Pedra Eólica da área para coletar dados.", st = "Filião foi enviado às Pedras Erguidas do Mirante com um dispositivo especial usado para medir e estudar a energia elemental que existe lá.\n\nPegue isto: é um Cartapácio Esotérico. Use-o para extrair dados das enormes formações de pedra eólica que se concentram no local. Mas fique alerta, pois os Moldavento provavelmente estão guardando este local com zelo agora.\n\nSe algum deles tentar obstruir seu caminho, bom... faça o que for preciso. Não tenho mais paciência com a interferência deles.", t = "Caça ao vento"},
    [92849] = {ot = "Continue buscando por Filião Brisardente.", st = "<A julgar pelo que você acabou de encontrar, é muito provável que Filião tenha sofrido algum infortúnio aqui. Ele ainda pode estar por perto e talvez precise de ajuda. Você nota uma caverna logo ao norte da sua localização atual. Seria bom continuar procurando por ele lá.>", t = "O erudito desaparecido"},
    [92850] = {ot = "Mate a Matriarca Guinchote no Covil dos Guinchotes e depois leve a cabeça dela a Filião Brisardente em Valanaar.", st = "Já me sinto muito melhor. Tenho certa habilidade com as artes arcanas e estamos a uma curta distância de Valanaar. Consigo voltar por conta própria. Mais importante que a minha segurança, no entanto, é o quão perto de Valanaar aqueles guinchotes fizeram seus ninhos e o perigo que eles representam. Se não for muito incômodo, volte lá para dentro e traga a cabeça daquela fera!\n\nDepois que terminar, você me encontrará de volta em Valanaar. Preciso relatar ao Magíster Supremo o que aconteceu aqui e a situação da minha missão.", t = "O erudito desaparecido"},
    [92860] = {ot = "Apresente-se a Valennia Tempespunho e informe-a de que a Alta Ordem os apoiará em sua luta contra os Al'Aketh.", st = "A Alta Ordem fez o possível para evitar um conflito direto com a seita, mas ficou evidente que essa não é mais uma opção. A hostilidade deles foi amplamente demonstrada, e agora há rumores sobre movimentos da seita em maior escala pela ilha. Estão sem dúvida se preparando para algo e, seja o que for, não será nada bom para o povo de Zefras.\n\nApresente-se a Valennia Tempespunho e informe a ela que a Alta Ordem oferece nosso total apoio aos esforços de Valanaar contra os Al'Aketh, caso haja necessidade.", t = "A serviço de Zefras"},
    [92871] = {ot = "Apresente-se a Valennia Tempespunho e informe-a de que os Moldavento os apoiarão em sua luta contra os Al'Aketh.", st = "Valennia Tempespunho e os pacificadores dela sempre foram os protetores de Zefras, e fizemos o nosso melhor para ajudar no que podíamos. Há rumores sobre movimentos da seita em maior escala pela ilha. Estão sem dúvida se preparando para algo.\n\nApresente-se a Valennia e informe a ela que os Moldavento oferecem total apoio aos esforços de Valanaar contra os Al'Aketh, caso haja necessidade.", t = "A serviço de Zefras"},
    [92880] = {ot = "Leve o Relatório de Yorna para Valennia Tempespunho em Valanaar.", st = "Suspeito que levaremos um tempo para dar cabo do que restou dos atacantes, mas nossas chances são muito melhores agora. Volte a Valanaar e avise que a situação por aqui se estabilizou.\n\nNão tenho como agradecer o suficiente por sua ajuda. Estaríamos em uma situação muito pior sem você. Pedi reforços e parece que, em vez disso, recebi uma alma heroica em ascensão. Eu aceito de bom grado.\n\nQue os quatro ventos abençoem você, $c.", t = "Retorno a Valanaar"},
    [92881] = {ot = "Fale com Talaanis Cantonegro em Valanaar.", st = "Os ataques às torres de guarda oriental e ocidental não são coincidência. Com base no que você nos contou sobre o que ocorreu na torre de guarda ocidental com aquele sacerdote do céu, nosso melhor palpite é que a seita está tentando fazer algo com os pilares de ancoragem.\n\nPor favor, fale com o Sumo Ancião Cantonegro. Ele falará sobre uma pista que pode se mostrar promissora.", t = "O pedido do Sumo Ancião"},
    [92909] = {ot = "Ozwin Giroferro, na Fazenda dos Saldanha, quer que você leve para ele 14 Isomolas de Golem e 5 Giroestabilizadores de Ceifador.", st = "Ah, não... agora eu me dei mal!\n\nOuvi falar dos ceifadores aterrorizando os campos de Cerro Oeste, então viajei lá de Altaforja pra ver se conseguia recalibrá-los. Mas eles são muito mais agressivos do que meus cálculos previam, e me encurralaram nesse estábulo!\n\nSe eu tivesse umas isomolas e giroestabilizadores dos ceifadores, podia construir um dispositivo pra conseguir fugir. Você pode arrumar essas peças pra mim?", t = "Quem ceifa os ceifadores?"},
    [92910] = {ot = "Leve o Conjunto de Autocognição Precessiva para Ozwin Giroferro na Fazenda dos Saldanha.", st = "A peça que você conseguiu recuperar do ceifador parece quase intacta. Alguém interessado em golens de colheita talvez queira dar uma olhada.", t = "Quem ceifa os ceifadores?"},
    [92911] = {ot = "Ozwin Giroferro, da Fazenda dos Saldanha, quer que você leve para ele 8 Isomolas de Golem, 4 Moduladores de Cobre e uma Mira Rudimentar.", st = "Entendi... Isso me deu uma boa noção de como esses monstros funcionam. Eu tenho uma ideia do que pode sobrecarregar os sistemas deles, nem que seja temporário.\n\nVou continuar mexendo com o conjunto que você trouxe. Enquanto isso, pode catar umas peças pro dispositivo?", t = "Quem ceifa os ceifadores?"},
    [92947] = {ot = "Mate $1oa Guardiões Al'Aketh, $2oa Evoca-espíritos Al'Aketh e $3oa Mestres de Espadas Al'Aketh e depois se apresente a Hyusaa Brisaveloz no Santuário de Akir.", st = "Todos estão aqui... Ótimo. Acabei de enviar alguns dos meus melhores combatentes pela frente do santuário para causar problemas e servir de distração, enquanto lidero a porção mais robusta de nossas tropas pelo flanco.\n\nSe tudo correr bem, devemos conseguir romper as defesas rapidamente e eliminar a Suma Sacerdotisa. Quanto a você, entre lá e comece a rachar uns crânios. Encontre minha imediata, Hyusaa Brisaveloz, perto da escada do santuário depois de causar algum estrago.\n\nQue os ventos guiem seu caminho, $c.", t = "Fazendo nossa jogada"},
    [93036] = {ot = "Fale com Sania Fluviprata na Aldeia de Shen'dar.", st = "Não sei se você sabe, mas a Sania Fluviprata ali é uma \"missionária\" dos Al'Aketh. Eles gostam de se passar por um grupo religioso normal e mandam emissários carismáticos para o recrutamento. Toleramos a Sania até agora para evitar o conflito direto com a seita, mas é óbvio que a ilusão de paz não vai durar muito.\n\nVocê acabou de chegar aqui, é praticamente $Gdesconhecido:desconhecida;, por isso gostaria de saber se você pode usar a Sania para se aproximar da seita e descobrir o que pretendem na aldeia.", t = "Infiltrando-se na seita"},
    [93065] = {ot = "Fale com Valennia Tempespunho nos Baixios dos Lufopomos.", st = "Os Pacificadores estão se mobilizando e todos nós estamos nos preparando para partir. Faça os preparativos necessários e encontre-nos na estrada leste que sai da cidade rumo ao norte. Faremos um último repasse com todos antes de avançar.", t = "Prepare-se para a batalha"},
    [93089] = {ot = "Fale com Elaandrin Plenovento quando estiver tudo pronto para deixar a Ilha de Zefras.", st = "Peço que transmita meus agradecimentos a Elaadrin por tudo que a Alta Ordem e seus novos amigos desse tal \"Kirin Tor\" fizeram pela Ilha de Zefras. Estou ciente dos planos da Alta Ordem de deixar a ilha, e a sua ordem tem minha bênção e meus votos de sucesso nesta expedição.\n\nSó posso esperar que qualquer solução arcana que a Alta Ordem encontrar possa realmente nos proporcionar a estabilidade que nos faltou nesses últimos anos. Se você planeja ir com eles... bem, esta missão será ainda mais fortalecida.\n\nQue os ventos estejam com você, $n.", t = "O que vem depois"},
    [93090] = {ot = "Fale com Ayessa Cantalva quando estiver tudo pronto para deixar a Ilha de Zefras.", st = "Por favor, transmita meus agradecimentos a Ayessa por tudo que os Moldavento e seus novos amigos dessa tal \"Harmonia Telúrica\" fizeram pela Ilha de Zefras. Estou ciente do plano de levar os xamãs Moldavento e deixar a ilha, e sua ordem tem minha bênção e meus votos de sucesso em sua expedição.\n\nSó posso esperar que qualquer solução que os Moldavento encontrem possa realmente nos proporcionar a estabilidade que nos faltou nestes últimos anos.\n\nQue os ventos estejam com você, $n.", t = "O que vem depois"},
    [93159] = {ot = "Fale com o Eremita Estranho na Floresta Umbréola e descubra mais a respeito dele.", st = "Hã, é... o-olá, quer dizer, oi! Ou melhor, saudações! Me desculpe... faz, hã, tanto tempo que não falo de verdade com outra pessoa. Receio que eu tenha perdido um pouco a prática.\n\n<A estranha figura encapuzada se mexe desconfortavelmente diante de você.>\n\nEntão, é, hã... como está sendo o seu dia?", t = "O eremita estranho"},
    [93160] = {ot = "Recolha $1oa Bolotas Umbréolas na Floresta Umbréola.", st = "Eu realmente agradeço por você ter parado para conversar comigo! S-se você quiser ajudar, eu aceitaria uma mãozinha para recolher bolotas do chão da floresta. Já recolhi a maioria das que estavam aqui perto, mas com certeza há muitas daquelas coisas parecidas com pássaros-raptores na floresta. É perigoso, e eu prefiro não virar almoço de pássaro gigante!\n\nEntão, se quiser, pode recolhê-las para mim? Vou preparar algo bem gostoso para nós se você fizer isso!", t = "O tesouro da floresta"},
    [93165] = {ot = "Colete $1oa Orelhas de Sectários Al'Aketh na Floresta Umbréola, no Santuário de Akir ou nos Baixios dos Lufopomos.", st = "Os Al'Aketh trouxeram uma grande tragédia ao nosso enclave, e sangue deve ser pago com sangue.\n\nTenho uma proposta para você, viajante. Caso enfrente esses sectários malditos, traga as orelhas dos que você matar. Recompensarei você com moedas a cada orelha que trouxer e, com o tempo, com acesso aos segredos dos Noctigarra, caso prove sua verdadeira amizade.", t = "Menos misericórdia, mais orelhas"},
    [93172] = {ot = "Destrua 10 Abantesmas do Vento na Floresta Umbréola.", st = "A maioria dos elfos desta ilha parece achar que essa floresta é assombrada, e não estão errados.\n\nNas velhas ruínas a nordeste, um tipo estranho de espírito fantasmagórico se reúne. Em algumas noites, quase dá para ouvi-los cantar. Não parece nenhuma canção que eu já tenha ouvido antes, mas sem dúvida é uma canção e é... muito triste.\n\nNão tenho certeza do motivo, mas acho que algo terrível aconteceu lá em algum momento e os espíritos ficaram presos. Se tiver coragem, pode ajudar a libertá-los?", t = "Liberte os Abantesmas"},
    [93317] = {ot = "Colete 6 pedaços de Carne de Rastejante Cantéolo.", st = "Você conhece os rastejantes cantéolos? Veja bem, esses caranguejos só são encontrados no Lago Cantéolo aqui em Zefras, e só podem ser coletados durante algumas semanas do ano.\n\nCom todas as atividades recentes da seita, não consegui ir até o lago para coletá-los, e nossa janela de oportunidade está se fechando rapidamente. Agradeceria muito se pudesse ir e coletar alguns para mim. Eles geralmente podem ser encontrados nas margens ao redor do lago e nos rios.\n\nMas tome cuidado, pois eles são mais bravos do que parecem!", t = "Temporada do caranguejo"},
    [93318] = {ot = "Elimine Vulgara, a Insaciável, no Planalto de Shen'dar e leve a cabeça dela a Danarii Bramivéu.", st = "Por ordem da Oficial Aonda dos Pacificadores, oferecemos por meio deste decreto uma recompensa pelo flagelo do planalto, Vulgara, a Insaciável. Ela foi vista pela última vez no topo da colina a sudoeste da Aldeia de Shen'dar. A terrorista vuldren alada é muito perigosa e deve ser abordada com cuidado.\n\nEntregue a cabeça da fera a Danarii Bramivéu para receber sua recompensa.", t = "PROCURA-SE: Vulgara, a Insaciável"},
    [93319] = {ot = "Colete 10 Pedras Eólicas Roubadas dos Bandidos do Planalto no Planalto de Shen'dar.", st = "Estamos dependendo cada vez mais de pedras eólicas para as atividades diárias aqui em Zefras. Por isso, tentamos manter um estoque delas para emergências. Andei notando ultimamente o desaparecimento de algumas.\n\nEncontramos pedras eólicas com bandidos capturados recentemente, e desconfio que eles sejam os responsáveis por nossa escassez.\n\nSe você passar perto da caverna de bandidos ao norte, se importaria de dar um corretivo em alguns deles e resgatar parte das pedras eólicas roubadas para mim?", t = "Pedras eólicas roubadas"},
    [93320] = {ot = "Apresente-se a Yorana Canavento na torre de guarda oriental nos Baixios dos Lufopomos.", st = "Acabo de receber notícias de que a seita está atacando a torre de guarda do pilar, logo nos arredores da cidade! Enviei os poucos pacificadores extras que temos aqui para tentar romper a retaguarda inimiga e socorrer os defensores, mas qualquer ajuda adicional pode ser a diferença entre a vida e a morte para o nosso povo lá.\n\nSiga imediatamente para a torre de guarda leste e preste a ajuda que puder.\n\nMinha tenente, Yorana Canavento, liderou a força de socorro. Se ela ainda estiver viva, poderá lhe dizer qual é a melhor forma de ajudar.", t = "Defendendo a torre"},
    [93461] = {ot = "Fale com Rathiril Arrebol e Coriella Ventocalmo na Aldeia de Shen'dar.", st = "Você tem um ar de \"Alta Ordem\". Sei porque a ascendência altaneira sempre deixa um ligeiro brilho no olhar da pessoa. Antes de colocar você para trabalhar decentemente aqui, fale com nosso ancião residente da Alta Ordem, Rathiril Arrebol. Você vai encontrá-lo no alojamento principal, só fazendo a curva ali adiante.\n\nAh, e fale também com Coriella Ventocalmo. Ela administra a estalagem local e pode fornecer hospedagem e suprimentos, se você precisar.", t = "Boas-vindas à Aldeia de Shen'dar"},
    [93552] = {ot = "Colete 15 Drusas de Pedra Eólica de Pedras Eólicas Brutas no Bosque Thendal.", st = "As pedras eólicas são um recurso crucial na Ilha de Zefras, já que contêm a energia bruta e concentrada dos ventos. Os elementais do vento que viviam aqui em Zefras conosco desapareceram há muitos anos e, desde então, a magia que sustenta esta ilha está se esvaindo lentamente. Embora tenham suas limitações, as pedras eólicas ainda são uma fonte confiável de energia e têm valor inestimável para nós.\n\nVocê encontrará pedras eólicas brutas espalhadas pelo bosque. Acha que pode me ajudar a coletá-las?", t = "Coleta de pedras eólicas"},
    [93680] = {ot = "Consiga a Chave do Esgoto de Dalaran para Magus Ordínio Olharvazio na Serraria Tarren.", st = "A Aliança tinha um exército de magos conhecido como Kirin Tor. Embora fossem poderosos, os demônios da Legião Ardente provaram ser ainda mais. De um só golpe, o arquidemônio Arquimonde arrasou a cidade como se fosse brinquedo de criança. Os sobreviventes foram reduzidos a meros andarilhos desalojados.\n\nIsso, claro, até eles reconstruírem Dalaran. E bem nos domínios da Dama Sombria, para completar!\n\nEnquanto estiver nos acampamentos deles, procure algo que nos permita entrar na cidade sem chamar atenção. Preciso saber mais.", t = "Chave da cidade"},
    [93735] = {ot = "Encontre Riaani Ventonegro na porção ocidental de Valanaar.", st = "Historicamente, os Moldavento garantem a preservação dos instrumentos e dispositivos mágicos que os espíritos do vento nos concederam. Entre eles, está a miríade de constructos mágicos espalhados pela ilha. Desde a partida dos espíritos, poucos ainda continuam funcionando.\n\nUm dos poucos constructos ainda operantes de Valanaar está avariado. Um dos nossos artífices foi despachado para ajudar, mas talvez ele próprio precise de ajuda. Vá até a região oeste da cidade e ajude como puder.", t = "O constructo quebrado"},
    [93736] = {ot = "Colete 10 Essências de Abantesma do Vento, obtidas de Abantesmas do Vento, na Floresta Umbréola.", st = "A maior meta dos Moldavento é compreender por que os espíritos nos deixaram e o que podemos fazer para trazê-los de volta. A Floresta Umbréola, a norte, tem uma peculiaridade: a presença de uma forma curiosa de espírito de vento à qual alguns dão o nome de \"abantesmas\". Pouco se sabe deles e do porquê de habitarem aquela região, mas é fato conhecido que começaram a surgir depois da partida dos espíritos de vento.\n\nPreciso que vá até lá e os disperse. Reúna os restos e traga para cá.", t = "Espíritos indesejáveis"},
    [93737] = {ot = "Fale com Riaani Ventonegro e escute o que ele tem a dizer.", st = "Ah, olá. Ayessa $Go:a; enviou para me ajudar? Muito bem.\n\nNão sei como alguém tão claramente inexperiente pode ajudar, mas, se me esperar desentalar a cabeça das entranhas desse constructo, posso pensar em alguma tarefa para você.", t = "O constructo quebrado"},
    [93738] = {ot = "Fale novamente com Ayessa Cantalva em Valanaar.", st = "Desebrilho, hum? Então a Alta Ordem quis tirar os componentes por algum motivo. Mas qual seria ele?\n\nA Alta Ordem está sempre querendo fazer experimentos com a magia dos espíritos do vento, e a ousadia deles não conhece limites. Eles são estritamente proibidos de se envolver com conhecimentos que competem aos Moldavento, mas começaram a abusar da nossa paciência nos últimos tempos.\n\nAcho que você devia relatar essas descobertas a Ayessa Cantalva. Ela pode lhe passar instruções do que fazer.", t = "O constructo quebrado"},
    [93740] = {ot = "Colete 10 Patuás da Pedra Eólica de Al'Aketh dos cadáveres de sectários Al'Aketh nos Baixios dos Lufopomos.", st = "Alguns dos nossos noviços Moldavento foram achados mortos no Planalto, esta manhã. Não temos certeza de nada, mas é muito provável que os Al'Aketh sejam responsáveis. Os Moldavento sempre pagam sangue com sangue.\n\nVá para o norte e mate todos os Al'Aketh que encontrar. Como prova, traga-me os patuás de oração da pedra eólica que carregam. Nós não perdoamos, nem esquecemos.", t = "Sangue por sangue"},
    [93746] = {ot = "Confronte Belathaan Desebrilho na estrada para o Santuário de Akir.", st = "A Alta Ordem foi advertida de que não se intrometeria nos assuntos dos Moldavento sem consequências. Acho que temos que punir Belathaan exemplarmente e mandá-lo de volta à Alta Ordem com alguns ferimentos e uma boa dose de respeito pelos limites que estabelecemos.\n\nBelathaan foi avistado deixando a cidade pelo norte, seguindo na direção do Santuário de Akir. Não sei por que ele estava indo para lá, mas confrontá-lo sozinho, na estrada, é o mais seguro. Encontre-o e meta um pouquinho de medo nele.", t = "Reação firme"},
    [93791] = {ot = "Fale com Belann Lenhéolo em Valanaar.", st = "$n, é nítido que sua habilidade com magia está evoluindo e, por isso, creio que chegou a hora de você participar de uma das tradições mais antigas da Alta Ordem para magos jovens e ambiciosos. É hora de você criar seu próprio foco mágico.\n\nProcure Belann Lenhéolo em Valanaar. Ele cria cajados e varinhas para a Alta Ordem há mais de um século, então você estará em boas mãos.", t = "Conversando com Belann"},
    [93797] = {ot = "Leve um Ramo Infuso com Vento a Belann Lenhéolo em Valanaar.", st = "É uma tradição ancestral que jovens magos criem sua própria concentração de feitiço quando demonstram certo grau de proficiência mágica. Tipicamente, isso é feito reunindo galhos caídos de nossas árvores mais antigas, pois eles têm traços remanescentes de vento elemental.\n\nEu descobri que os galhos ideais ficam perto do santuário do vento, um pouco ao sul da Aldeia de Falaath. Vá buscar um galho grande para mim, que eu lhe ensino sobre as tradições enquanto criamos a sua concentração de feitiço.", t = "Ramos ao vento"},
    [93835] = {ot = "Pegue o portal para os Pináculos Rohashi e junte-se a Elaadrin Plenovento e Ayessa Cantalva no confronto contra a Alta-sacerdotisa Lorthuna.", st = "Lorthuna fugiu para os pináculos lá no alto usando algum tipo de portal. Ayessa e Elaadrin entraram atrás dela. Isso foi há poucos instantes.\n\nReceio não estar em condições de ir. Atravesse o portal, encontre Elaadrin e ajude-os a deter Lorthuna.\n\nA menos que a ajuda que Elaadrin e Ayessa disseram ter solicitado chegue logo, você está por conta própria a partir daqui. Boa sorte, $c.", t = "Confronto com Lorthuna"},
    [93836] = {ot = "Fale com Talaanis Cantonegro em Valanaar.", st = "Muln me falou muito sobre os lordes elementais, e temo que tenhamos bons motivos para temer Al'Akir. Agora que as proteções que ocultavam Zefras dele caíram, estamos totalmente vulneráveis. Se ele decidir nos atacar, não teremos a menor chance enquanto estivermos aqui em seu domínio.\n\nO Sumo Ancião Cantonegro precisa saber do perigo que corremos e, mais importante ainda, quais são as nossas intenções para a missão em Azeroth. Encontraremos os meios de salvar o nosso lar. Eu juro.", t = "O destino de Zefras"},
    [93926] = {ot = "Encontre o Pacificador Vaaniel na torre de guarda ocidental.", st = "Qualquer que seja o motivo de a seita atacar a torre, não vale a vida do nosso povo.\n\nPreciso que você vá para o sudoeste e dê uma olhada na torre de guarda para nós. Encontre os pacificadores e peça que voltem à aldeia. A proteção da torre não vale as vidas que custaria, e prefiro concentrar os defensores aqui para proteger os nossos cidadãos.\n\nPeça ao Pacificador Vaaniel, o encarregado, que volte aqui o mais rápido possível. Depressa!", t = "O Posto do Oeste"},
    [93927] = {ot = "Colete o bilhete que você encontrou com o pacificador morto e leia-o para saber os próximos passos.", st = "<Ao inspecionar o corpo do pacificador morto, um bilhete ensanguentado cai das mãos dele. Lendo a mensagem, talvez você tenha uma pista do que fazer a seguir.>", t = "Último pedido"},
    [93948] = {ot = "Entregue o Sinete da Família Cantonegro a Talaanis Cantonegro em Valanaar.", st = "Já que você vai para Valanaar de qualquer jeito, peço que entregue a Talaanis Cantonegro o anel-sinete que você recuperou na torre. \n\nEle vai querer isso de volta e, acima de tudo, vai querer saber o destino do sobrinho dele. Talaanis é o Sumo Ancião da Ilha de Zefras e, o mais importante, ele é um homem bom, adorado pelo povo, apesar das nossas dificuldades atuais. Fico triste só de pensar em como ele vai reagir a essa notícia. Por favor, expresse meus sentimentos pela perda dele.", t = "Entrega de sinete"},
    [93949] = {ot = "Mate Saltacéus em Valanaar até eliminar ao menos $1oa Saltacéus Encantados.", st = "Fomos grampeados.\n\nÉ temporada de saltacéus nos baixios, o que significa que essas pragas estão por toda parte. Um dos magos da Alta Ordem relatou que um dos insetos que mataram tinha algum tipo de encantamento. Quando inspecionamos de perto, parece ser um tipo de feitiço de escuta.\n\nSuspeitamos que a seita esteja usando esses insetos encantados como espiões. Vá e extermine-os para nós. Você não conseguirá saber quais estão encantados só de olhar, então terá que matar todos eles.", t = "De antena em pé"},
    [93951] = {ot = "Colete 8 Plumas de Hipogrifo no Planalto de Shen'dar.", st = "Os hipogrifos que se estabeleceram a sudoeste da aldeia podem ser um estorvo, mas também representam uma oportunidade rara de obter penas. Muitos celonatos amam enfeitar o cabelo com plumas vibrantes, e as penugens dos hipogrifos são excepcionalmente vibrantes e, acima de tudo, macias que nem seda.\n\nSe você estiver indo naquela direção, tente coletar o máximo dessas penas que encontrar caídas nos arredores dos ninhais. Mas tome cuidado: os hipogrifos selvagens não toleram visitas.", t = "Leve beleza"},
    [93958] = {ot = "Fale com Valennia Tempespunho no interior do sanctum santorum do Santuário de Akir.", st = "As forças de Valennia acabaram de invadir o sanctum sanctorum. No começo, o combate estava intenso lá dentro, mas ficou... perturbadoramente silencioso. Entre lá e faça o seu melhor para se juntar a Valennia e sua tropa... se é que restou alguma.\n\nEu ficarei de guarda aqui.", t = "O sanctum sanctorum"},
    [94003] = {ot = "Reivindique o Baluarte do Rompe-céus de Zaal Escudo Tonante no Santuário de Akir.", st = "Sou tudo o que restou da linhagem Rompe-céus aqui na Ilha de Zefras. Os outros foram assassinados pelos Al'Aketh.\n\nA única coisa maior que meu sofrimento é o meu opróbrio. O escudo ancestral da minha família — o Baluarte do Rompe-céus — está agora nas mãos de um sectário chamado Zaal Escudo Tonante. Reza a tradição familiar que nenhum mal recairá a quem seja digno de empunhar o escudo.\n\nZaal é indigno, disso tenho certeza. Encontre esse homem no Santuário de Akir e reivindique o meu escudo. Se fizer isso, eu lhe ensinarei a Defesa Rompe-céus.", t = "O Baluarte do Rompe-céus"},
    [94006] = {ot = "Fale com Urs'endris perto das quedas a nordeste de Valanaar.", st = "Saudações, $n. Seu progresso nos estudos druídicos me obriga a admitir que é hora de você conhecer um dos grandes espíritos que habitam Zefras. Urs'endris é um espírito sábio e nobre que ensina druidas a assumir a forma de ursera há gerações. Infelizmente, os domínios dele começaram a se deteriorar e cair céu adentro, assim como muitas outras regiões de Zefras.\n\nPara encontrá-lo, siga para nordeste, perto da cachoeira à sombra do Santuário de Akir. Ele lhe dará mais instruções.", t = "O grande espírito de ursera"},
    [94013] = {ot = "Use o Bastão de Adestramento para domar um Vuldren Alfa nos Baixios dos Lufopomos. Treine sua perícia e depois devolva o Bastão de Adestramento a Quel'ana Ventiágil em Valanaar.", st = "Você retornou triunfante da doma de duas feras. Agora é hora da sua última provação. Os ventos de Zefras sussurram sobre desafios maiores pela frente. \n\nLeve este Bastão de Adestramento e viaje para os Baixios dos Lufopomos. Lá, dome um Vuldren Alfa e prove sua maestria. \n\nConcluindo esta lição, você estará $Gpronto:pronta; para aprender as tradições mais profundas da caça.", t = "Domando a fera"},
    [94050] = {ot = "Fale com Quel'dora Ventiágil em Valanaar.", st = "Agora você tem o poder de domar um ajudante, mas também precisa aprender a treiná-lo. Não encontrará professor melhor que minha irmã, Quel'dora. Ela lhe dará a habilidade de treinar o seu novo ajudante.\n\nQue os ventos $Go:a; guiem, jovem $c.", t = "Treinando a fera"},
    [94369] = {ot = "Fale com Talaanis Cantonegro em Valanaar.", st = "Ansirem me falou muito sobre os lordes elementais, e temo que tenhamos bons motivos para temer Al'Akir agora que as proteções que ocultavam Zefras caíram. Se o Senhor do Vento decidir nos atacar, não teremos a menor chance de nos defendermos enquanto estivermos aqui em seu domínio.\n\nO Sumo Ancião Cantonegro precisa saber do perigo que corremos e, mais importante ainda, quais são as nossas intenções para a missão em Azeroth. Encontraremos os meios de salvar o nosso lar. Eu juro.", t = "O destino de Zefras"},
    [94373] = {ot = "Leve 2 Pingentes de Urso Jubafria a Teo Tempestelo em Sidermar.", st = "Chegou a hora, jovem xamã. Tu tá firme e $Gforçudo:forçuda;, que nem a rocha que as nossas botas tão pisando. Só de tu seguir a vereda xamânica já demonstrou que tu tem a sabedoria da montanha, antes mesmo de provar o teu valor. Só quem tem a determinação da pedra aguenta trilhar o caminho da terra.\n\nSó que, pra terra ser tua aliada, tu precisa encarar ela como se deve. Tem uns trolls Jubafria que moram numa caverna a sul daqui.\n\nMe traz dois colares de urso garrálgido que eles usam, e aí a gente discute o teu futuro.", t = "O chamado da terra"},
    [94374] = {ot = "Encontre a Pedra de Espírito e beba o Sapta da Terra.", st = "É, sapta é uma bebida preparada com magia que vincula nosso espírito aos elementos. Só alguns xamãs sabem a receita, e não é coisa pra vivente sem coragem. Bebe isso aí que tu vai enxergar o que os outros não veem. Mas segura a onda, tchê, porque só pode tomar em lugar sagrado.\n\nSegue pro norte, até a Pedra de Espírito que fica no final de uma trilha escondida na montanha. Bebe lá... e vê o que a terra tem pra te mostrar.", t = "O chamado da terra"},
    [94375] = {ot = "Leve o Quartzo Grosseiro até Teo Tempestelo em Sidermar.", st = "Pegue este quartzo grosseiro e leve-o até Teo Tempestelo como prova do nosso encontro. Ele vai lhe fazer um totem que terá este quartzo como coração. Por menor que ele possa parecer, você vai acabar descobrindo que tamanho não é documento, e que mesmo as menores coisas podem durar mais que muitas outras.\n\nTenha paciência, $n. Tenha força. E busque a sabedoria. É tudo o que a terra lhe pede. No fim, você e a terra serão uma coisa só. Respeite-a como ela respeita você.", t = "O chamado da terra"},
    [94411] = {ot = "Mate 6 Aprendizes da Alta Ordem no Planalto de Shen'dar.", st = "Esteja ciente: avistamos membros da Alta Ordem nos arredores das pedras erguidas ao norte da aldeia. Já avisamos várias vezes para eles não se intrometerem em nossos locais sagrados, mas estão ficando cada vez mais ousados. Prove sua determinação indo até as pedras erguidas e os dispersando.\n\nSou avessa ao derramamento de sangue puro e simples, mas faça o que for preciso para afugentá-los. Fale comigo quando terminar.", t = "Magos metidos"},
    [94413] = {ot = "Mate 6 Videntes Noviços Moldavento no Planalto de Shen'dar.", st = "O surgimento recente dos meridianos na superfície de Zefras teve um impacto profundo em nossa ordem. Temos um acesso mais direto e tangível às energias que permeiam este lugar, e tudo isso aumentou e muito nossa compreensão dessa magia.\n\nNo entanto, os Moldavento enxergam esses surgimentos como cicatrizes na terra que precisam ser \"curadas\". Isso é uma afronta à nossa ordem, algo que simplesmente não podemos tolerar.\n\nVá até o meridiano na floresta a sudoeste e espante os Moldavento que encontrar por lá.", t = "Uma afronta mágica"},
    [94414] = {ot = "Fale com Halaan Olho-de-Falcão e tome emprestado o dom dele de ver os pilares de ancoragem ao longe.", st = "Saudações, jovem $n. Eu costumo vir aqui para contemplar os antigos pilares de ancoragem. São dádivas dos espíritos dos ventos que unem e sustentam nossa ilha. Ultimamente, no entanto, a magia deles tem se tornado instável e inconstante.\n\nNão vejo neles qualquer sinal de aflição. O esplendor deles não mudou.\n\nSe quiser, posso emprestar a você meu dom para que os contemple com seus próprios olhos.", t = "As âncoras de Zefras"},
    [94427] = {ot = "Fale com Tanis Amieiro na Cidade Baixa.", st = "Um dos princípios fundamentais de ser um paladino é a busca pelo divino. Não estou falando de almejar a condição de deus, mas simplesmente de buscar o bem apenas pelo bem e nada mais. Todos chegamos aqui por causa de alguma tragédia, e seria fácil perder a graça que nos definiu como paladinos em vida.\n\nVá até a Cidade Baixa e procure Tanis Amieiro no Distrito Comercial. Eles estão passando necessidade e têm muito a ganhar com um pouco da sua graça.", t = "Uma lição de divindade"},
    [94434] = {ot = "Leve 10 peças de Linho para Tanis Amieiro na Cidade Baixa.", st = "Calma, você quer... ajudar? Por que $Gum paladino:uma paladina; ia querer ajudar um mendigo como eu?\n\nBom, suponho que você possa me ajudar, sim. \n\nVeja bem, é a minha mulher. Ela, bem... Ela está caindo aos pedaços. E eu falo literalmente. Os boticários podem costurá-la e deixá-la novinha em folha, mas eles estão cuidando dos assuntos da Dama Sombria e não há nenhum disponível para ajudar. Se você me trouxesse um pano novo, pelo menos eu conseguiria fazer ataduras para segurar todas as partes dela no lugar enquanto esperamos os boticários.", t = "Uma lição de divindade"},
    [94435] = {ot = "Fale novamente com Danitha Morr na Bastilha de Bandarion.", st = "Não sei por que você faria todo esse esforço para me ajudar, mas agradeço. Se alguém mandou você até mim, diga também à pessoa que ela tem minha gratidão. Você sempre poderá contar com a amizade de Tanis Amieiro, $c.", t = "Uma lição de divindade"},
    [94436] = {ot = "Fale com o Necroguarda Billmuth na Bastilha de Bandarion.\n\nCaso perca o Símbolo da Vida, fale novamente com Danitha Morr para pegar outro.", st = "É hora de demonstrar sua capacidade de canalizar uma das maiores dádivas da Luz.\n\nO objeto que eu acabei de lhe dar se chama Símbolo da Vida. Tome cuidado, pois manusear um talismã da Luz desse porte pode causar certo desconforto. A Luz pode ser odiada pela força que nos criou, mas ainda é nossa guia e aliada. A dor nos faz lembrar desse fato.\n\nVá ver o Necroguarda Billmuth lá embaixo. Ele acabou de chegar e solicitou nossa ajuda. Mostre a ele e aos Renegados do que $Gum paladino:uma paladina; de verdade é capaz.", t = "Uma lição de divindade"},
    [94438] = {ot = "Pegue o Símbolo da Vida e use-o para ressuscitar o Necroguarda Falgan no Vale Veneracnídeo. \n\nCaso perca o Símbolo da Vida, fale novamente com Danitha Morr para pegar outro.", st = "Eu e Falgan fomos enviados em uma missão para sondar atividade da Cruzada Escarlate no Vale Veneracnídeo. Conseguimos nos aproximar sorrateiramente de um dos acampamentos para escutar novas ordens que envolvessem um ataque a Montalvo. Antes de podermos decidir o que fazer, pisei em um galho e o barulho os alertou de nossa presença.\n\nFalgan gritou para que eu fugisse, então eu corri. Quando me dei conta, ele não estava comigo, e eu já estava no meio do caminho até Montalvo. Aquele idiota corajoso deve ter ficado para trás para segurá-los por mim.\n\nPor favor, encontre meu amigo e ajude-o se puder.", t = "Uma lição de divindade"},
    [94440] = {ot = "Recupere os Planos de Ataque da Cruzada Escarlate com os Cruzados Escarlate em Vale Veneracnídeo, e fale com o Necroguarda Billmuth na Bastilha de Bandarion.", st = "A Cruzada Escarlate geralmente carrega algibeiras com as ordens de mobilização. Sabemos que um ataque está por vir, mas, se pudermos pegar essas ordens, podemos avisar aos outros necroguardas e preparar uma emboscada. \n\nVocê é $Gum paladino:uma paladina; impressionante. Mate essas feras escarlates, pegue uma cópia das ordens e leve-a ao Necroguarda Billmuth. Ele cuida do resto.", t = "Uma lição de divindade"},
    [94441] = {ot = "Fale com Danitha Morr na Bastilha de Bandarion.", st = "Leve os meus agradecimentos a Danitha Morr e diga que o resto da Necroguarda saberá dos serviços que os paladinos da Bastilha de Bandarion prestaram para nós. \n\nVocê tem muito potencial como $Gpaladino:paladina;, e é uma honra ter alguém como você nas fileiras dos Renegados. Que a Dama Sombria zele por você, $n.", t = "Uma lição de divindade"},
    [94449] = {ot = "Ache Bruegs Igninato em Dun Morogh.", st = "Faz tempo que tu não passa por uma provação, $n. Tu demonstrou paciência, tchê... mas é hora de fazer amizade com o caos... com a destruição. O chamado do fogo é estrondoso, só que, se tu estiver $Gpronto:pronta; pra pagar o preço que ele cobra, ele vai falar contigo.\n\nProcura o Bruegs Igninato, no leste profundo das montanhas. Ele mora numa caverna acima do Posto de Guarda do Portão Sul. Ele vai saber se tu tá $Gpronto:pronta; mesmo.", t = "Clamor do fogo"},
    [94465] = {ot = "Leve a Tocha da Chama Latente a Braldir Tefromanto em Loch Modan.", st = "Tchê, tu tem força suficiente pra portar o totem de fogo, $Gguri:guria;, mas força por si só não é sinal de preparo.\n\nPra lá do Vale dos Reis, nos rochedos de Loch Modan, tem um caminho oculto que leva a um dos nossos picos sagrados. Lá, Braldir Tefromanto guarda o Altar da Chama Latente.\n\nLeva essa tocha pra ele — ela demonstra a tua intenção. Devolve ela acesa ao braseiro do Altar, que eu providencio pra que tu receba o totem.", t = "Clamor do fogo"},
    [94466] = {ot = "Leve 1 Piche Ígneo e 1 Bornal de Reagentes para Braldir Tefromanto em Loch Modan.", st = "Bah, tu não veio até aqui por causa dumas lorotas, né, $n? Tu tá atrás da Chama Eterna e do totem de fogo.\n\nPrimeiro, tu precisa de uma sapta pra atrelar teu espírito à chama.\n\nEu posso prepará-la, mas preciso de duas coisas: piche ígneo dos Geomantes Ratatúnel, que ficam nas cavernas dos kobolds a norte daqui, e um bornal de reagentes de um Vidente Lascapedra que ronda as colinas no sul. Tu vai cortar um dobrado pra cumprir a tarefa, mas garanto que a chama vai fazer valer a pena.", t = "Clamor do fogo"},
    [94467] = {ot = "Derrote a Manifestação Menor do Fogo e coloque a Brasa Faiscante no braseiro do Altar da Chama Eterna.", st = "A sapta do fogo tá pronta, $n. Agora tu tem que enfrentar as chamas. Usa ela no altar e depois sobe até o pico. Lá, tu vai ver o espírito. Ele não vai te atacar sem ser provocado, mas tu vai reconhecer ele quando o vir.$B$BAtaca rápido e rasteiro, $Gguri:guria;, que, quanto mais tu esperar, mais forte ele vai queimar. Quando ele cair, pega as brasas faiscantes e mete elas no braseiro. Aí é só acender a tocha pra receber as graças do fogo.", t = "Clamor do fogo"},
    [94468] = {ot = "Leve a Tocha da Chama Eterna a Bruegs Igninato em Dun Morogh.", st = "Segurando a tocha, você dá as costas ao braseiro e olha ao longe, na direção de Loch Modan. Sente uma empolgação enlaçando seu espírito enquanto o vento entra e obriga a chama a dançar violentamente.$B$BVocê começa a fazer o caminho de volta a Dun Morogh em busca de Bruegs Igninato.", t = "Clamor do fogo"},
    [94484] = {ot = "Encontre e fale com Elegael Patacardo na parte nordeste da Floresta Umbréola.", st = "Tem um momento, $n? Você está indo na direção da Floresta Umbréola? Há um conclave de druidas na caverna a nordeste. Estou esperando alguma notícia deles, mas a correspondência não chega faz tempo.\n\nCom Ban'aethall em ruínas e toda a agitação recente, temo que algo terrível tenha acontecido. Por favor, se você puder ir até lá, procure Elegael Patacardo e tranquilize a minha consciência.", t = "Silêncio enervante"},
    [94485] = {ot = "Colete $1oa de Musgo Lágrima-de-dama.", st = "Se quisermos salvar meus colegas na Caverna dos Noctigarra, vou precisar de alguns ingredientes para um cataplasma. O primeiro e mais importante é um musgo fino e comprido chamado lágrima-de-dama. Ele costuma dar ao pé das árvores aqui em Umbréolo.\n\nEsse musgo expele uma substância viscosa que age como antisséptico e é perfeito para cobrir feridas abertas. Consegui coletar um pouco, mas sei que há mais na floresta.\n\nApresse-se. Vamos precisar de muita quantidade se os feridos que deixei para trás ainda estiverem vivos.", t = "Lágrimas da dama"},
    [94486] = {ot = "Colete $1oa penas dos Guinchotes Umbréolos na Floresta Umbréola.", st = "O outro ingrediente de que preciso para o cataplasma são penas dos guinchotes umbréolos que vagam por esta floresta. Em sua forma juvenil, os guinchotes têm penas isolantes ideais para colocar sobre o musgo. Essas penas evitarão que a seiva antisséptica seque e fornecerão pelo menos alguma proteção contra as intempéries.\n\nAtenção: os guinchotes costumam ser dóceis, mas têm estado extremamente hostis. As garras grandes deles podem estripar você com facilidade se não tomar cuidado.", t = "Penas isolantes"},
    [94487] = {ot = "Colete $1oa Relíquias Ensanguentadas dos Soldados de Infantaria Al'Aketh e dos Caça-tempestades Al'Aketh na Floresta Umbréola.", st = "Os sectários Al'Aketh fizeram uma emboscada para nós repentinamente, mas ainda não consegui entender a motivação deles. Eu sabia que esses sectários só tinham nuvens entre as orelhas, mas nunca imaginei que perturbariam o equilíbrio delicado aqui em Zefras com tamanha brutalidade. Peço que vá matar o máximo que conseguir e pegue as relíquias deles, caso tenham alguma.\n\n<Elegael cospe.>\n\nEsses sectários amaldiçoados pela tempestade não merecem ser chamados de shen'dorei. As feras da floresta podem ficar com os cadáveres. As cinzas deles não merecem o vento.", t = "Indesejados e indignos"},
    [94488] = {ot = "Mate o Comandante Haalien e leve a cabeça dele a Elegael Patacardo na Floresta Umbréola.", st = "O motivo da presença dos sectários aqui ainda me desnorteia, mas eu sinto um cheiro familiar por cima de todo esse sangue.\n\nUm dos druidas do nosso círculo, Haalien, desapareceu meses atrás. Ao que tudo indica, ele aliou sua triste carcaça aos sectários.\n\nMostre a ele o que acontece quando se derrama o sangue dos seus! Corte a cabeça dele e traga-a para mim.", t = "Os laços que unem"},
    [94489] = {ot = "Entre no Covil Presa-da-noite e cure $1oa druidas e encontre Jorel Cantavento na Floresta Umbréola.", st = "Terminei os cataplasmas. Rápido, leve-os até os druidas na caverna ao norte, logo depois da clareira. Sei que meus irmãos estão em condições muito piores do que a minha. Provavelmente, estão feridos demais para cuidar dos próprios ferimentos. Somos tão poucos druidas shen'dorei que cada vida é preciosa.\n\nAntes de você ir, tenho um pedido egoísta. Meu parceiro, Jorel Cantavento, estava numa condição terrível quando eu parti. Por favor, cuide dos ferimentos dele, se ele ainda estiver vivo.", t = "As feridas da traição"},
    [94490] = {ot = "Leve a missiva rasgada a Elegael Patacardo na Floresta Umbréola.", st = "<Há um bilhete escondido atrás das braçadeiras de Haalien, ligeiramente rasgado e ensanguentado após a luta. Parece que contém informações úteis sobre as motivações do sectário para o ataque ao covil dos druidas. Elegael vai se interessar por essa informação.>", t = "Missiva rasgada"},
    [94491] = {ot = "Entregue a missiva a Lotheluum em Valanaar e conte a ele o que ocorreu.", st = "Parece que há um correspondente escondido em algum lugar de Valanaar repassando informações para a seita. Claramente não tenho condições de viajar, mas Lotheluum precisa saber o que ocorreu aqui.\n\nEle também deve saber do destino daqueles que se foram. Obrigada pela ajuda. Acho que podemos lidar com a situação daqui, embora o estrago já tenha sido feito.\n\nPeço que se apresse, $n. Espero que nossos caminhos se cruzem de novo algum dia. Até lá, tenho que exterminar sectários.", t = "O destino do esconderijo"},
    [94494] = {ot = "Ache Norric Lochthane em Loch Modan.", st = "Faz um bom tempo que tu foi $Gtestado:testada: pela última vez, $n. Tu demonstrou uma baita paciência nos estudos, e chegou a hora de tu aprender sobre a pureza da água.\n\nProcura Norric Lochthane em Loch Modan. Ele mora na margem noroeste do lago, ao sul do Dique Lapidado, numa cabana que mais parece uma toca. Boa sorte pra ti, $n.", t = "Clamor da Água"},
    [94495] = {ot = "Encontre Hervdana Saegrund no Pantanal.", st = "Se tem uma verdade pra tu saber a respeito da água, é essa: a água simboliza renascimento. Ela esculpe a rocha, purifica a imundície, cura os alquebrados — mas só se for pura. Contaminada, ela estraga tudo o que toca.\n\nSe tu tá atrás da sapta da água, encontre Hervdana Saegrund no Pantanal. A família dela mora numa caverna sob as quedas na região sul.\n\nAgora vai, e seja mais $Grápido:rápida; que o rio.", t = "Clamor da Água"},
    [94497] = {ot = "Encha o Odre Marrom Vazio na base das cascatas, abaixo da caverna de Hervdana, e devolva-o a ela no Pantanal.", st = "Humpf, tu veio atrás da sapta, tchê? Pois só te falo que, pra alcançar a compreensão e merecer a sapta, tu precisa buscar a água nas suas várias formas. Tu não pode recolher as amostras pensando na morte da bezerra: presta atenção às feras que a guarda, à terra que ela nutre, à maneira como transforma vidas.\n\nVamos começar do básico: enche esse odre aqui lá na base das quedas, onde a água doce e a salgada se encontram. Anda logo, e cuidado pra não ficar $Gatolado:atolada; por aí.", t = "Clamor da Água"},
    [94499] = {ot = "Encha o Odre Vermelho Vazio na Cachoeira do Mirante de Pedra, perto dos Reptantes Murlocs, e devolva-o a Hervdana Saegrund, no Pantanal.", st = "Cristarrubra bebe do Lago Plácido com avidez, mas, no momento em que as águas desabam pela Cachoeira do Mirante de Pedra, algo já se infiltrou nelas. Os murlocs lá embaixo são uns monstrengos bitelos, retorcidos. Bem diferentes dos que tu acha aqui ou no Loch. Pra sorte dos moradores da cidade, eles se aboletaram na base das quedas e de lá não saem.\n\nTraz uma amostra pra mim, que eu não vou sossegar enquanto não descobrir se o que está corrompendo as águas lá perto daquela fortaleza velha é magia, veneno ou coisa ainda pior.", t = "Clamor da Água"},
    [94500] = {ot = "Encha o Odre Azul Vazio com a água de Astranaar, no Vale Gris, e devolva-o para Hervdana Saegrund no Pantanal.", st = "Pega esse odre aqui e te embrenha nas sombras esmeralda do Vale Gris. Astranaar jaz entre águas imaculadas. O leito do lago é salpicado dumas ruínas de eras passadas. Me traz uma amostra do lago. A água lá é pura, antiquíssima... capaz que seja até encantada.\n\nÉ o último líquido de que eu preciso antes de poder te mandar de volta pro Norric.\n\nPega o barco em Menethil com destino a Auberdine. No caminho, ele para na Costa Sul.\n\nE fica $Gesperto:esperta;, porque a floresta tá cheia de olhos, e eles não piscam nunca.", t = "Clamor da Água"},
    [94568] = {ot = "Fale com Talaanis Cantonegro e observe a conversa.", st = "O desertor estava claramente com medo do que a seita havia planejado, a ponto de mudar de lado e buscar nossa ajuda. É realmente lamentável que ele esteja morto e tenha levado seus segredos para o túmulo.\n\nPrecisamos discutir isso mais a fundo para determinar nossos próximos passos.", t = "Os verdadeiros planos da seita"},
    [94638] = {ot = "Ache e mate Ur'endra no Planalto de Shen'dar.", st = "Você vem até mim na esperança de aprender a assumir uma forma poderosa. Tenho uma tarefa a lhe dar, embora ela me cause grande pesar.\n\nMinha parceira, Ur'endra, está entregue à loucura e começou a atacar seus semelhantes. Sem a magia dos ventos, muitas criaturas começaram a se perder... inclusive Ur'endra. O covil dela fica em uma caverna a oeste daqui, nos penhascos ao longo da divisa entre o Planalto de Shen'dar e os Baixios dos Lufopomos.\n\nPonha fim ao sofrimento dela e eu lhe transmitirei a minha bênção.", t = "Força e misericórdia"},
    [94774] = {ot = "Fale com a Alta-sacerdotisa Laurena em Ventobravo.", st = "Você despertou a atenção dos nossos superiores, $n. Eles pediram a sua presença na Catedral da Luz, em Ventobravo, o mais rápido possível. Aparentemente, eles perceberam que você já demonstrou estar $Gpronto:pronta; para se aprofundar no treinamento. Quando chegar lá, procure a Suma Sacerdotisa Laurena. Ela $Go:a; guiará daqui por diante. Boa sorte e que a luz esteja com você.", t = "Graça divina"},
    [94792] = {ot = "Use o Bastão de Adestramento para domar um Javali Couropedra. Treine sua perícia e depois devolva o Bastão de Adestramento a Josefina Carsom.", st = "Muitos caçadores preferem viajar com companheiros animais. Com uma fera ao seu lado, você verá que é capaz de sobreviver até às circunstâncias mais adversas. É como dizem: tudo é mais fácil com um amigo. No entanto, conseguir um companheiro animal é algo que deve ser feito com muito cuidado. O equilíbrio natural é delicado e deve sempre ser respeitado.\n\nLeve este Bastão de Adestramento com você para a floresta. Com ele, você será capaz de domar um Javali Couropedra e praticar suas perícias de caçador.", t = "Domando a fera"},
    [94793] = {ot = "Fale com Isaac Chan em Vila d'Ouro.", st = "Agora você tem o poder de domar um ajudante, mas também precisa aprender a treiná-lo. Não encontrará professor melhor que Isaac Chan, um mateiro de longa data. Ele lhe dará a habilidade de treinar o seu novo ajudante.\n\nQue os ventos $Go:a; guiem, jovem $c.", t = "Treinando a fera"},
    [94818] = {t = "Plano de contingência"},
    [94824] = {ot = "Fale com a Suma Sacerdotisa Mims em Altaforja.", st = "É chegada a hora de você partir para Altaforja, $n. A Suma Sacerdotisa Mims, do Salão dos Mistérios, ordenou que você vá tratar com ela. Só um motivo muito bom ou muito ruim para ela pedir que alguém vá até lá em pessoa, mas imagino que você só tenha agido bem, então ela deve estar te chamando para alguma coisa boa.$B$BMas não perca mais tempo por aqui. Se fosse eu, correria para lá o mais rápido possível.", t = "Clarão desconcertante"},
    [94863] = {ot = "Use o Bastão de Adestramento para domar um Lobo Cinza da Floresta. Treine sua perícia e depois devolva o Bastão de Adestramento a Josefina Carsom.", st = "Você já dominou o adestramento de javalis. Agora é hora da próxima lição. Esta floresta esconde companheiros ainda mais ferozes e, com jeito, você pode conquistar a confiança deles.\n\nLeve este bastão de adestramento e procure um lobo cinza da floresta. Lembre-se: o equilíbrio natural deve ser respeitado. Prove sua perícia como $Gcaçador:caçadora; uma vez mais.", t = "Domando a fera"},
    [94864] = {ot = "Use o Bastão de Adestramento para domar um Jovem Urso da Floresta. Treine sua perícia e depois devolva o Bastão de Adestramento a Josefina Carsom.", st = "Você se provou domando um javali e um lobo. Agora é hora do seu desafio final. O equilíbrio de Elwynn depende de perícia e respeito. Leve este bastão de adestramento e procure um jovem urso da floresta. Mostre que você pode ganhar a confiança até do mais poderoso dos companheiros.\n\nConcluir essa lição vai aprofundar sua sintonia com as feras.", t = "Domando a fera"},
    [94896] = {ot = "Colete $1oa Pertences Abandonados nas ruínas de Ban'aethal.", st = "Você parece ser $Gum aventureiro:uma aventureira; competente. Por acaso você está indo na direção da Floresta Umbréola? Ban'aethal está nas profundezas da floresta; é de lá que todos nós viemos.\n\n<Ealaane indica os outros refugiados.>\n\nTivemos que evacuar Ban'aethal recentemente, pois ela começou a cair para o céu. Foi repentino e no meio da noite. Se esse for seu destino, você poderia procurar pertences que tenham ficado pra trás? A floresta e a aldeia estão perigosas demais para voltarmos agora.", t = "Auxílio aos refugiados"},
    [94897] = {ot = "Encontre Resaan nas ruínas de Ban'aethal.", st = "Se você estiver viajando até Ban'aethal, tenho um pedido egoísta. Acredito que meu amor, Resaan... não faz mais parte deste mundo. Ele tentou voltar para pegar suprimentos, apesar das minhas súplicas para que ficasse. Já faz uma semana, e temo pelo pior.\n\nPor favor, se você o encontrar, traga-o de volta. Se ele tiver perecido, imploro que me traga a relíquia dele.", t = "O destino de um amor"},
    [94911] = {ot = "Fale com o Turak Runa Totem no Penhasco do Trovão.", st = "Saudações, jovem $r. Vejo sua aptidão para as artes druídicas. Na cidade do Penhasco do Trovão, tem alguém chamado Turak Runa Totem com quem você vai querer conversar. Ele lhe ensinará a chegar à Clareira da Lua, que é o baluarte do Círculo Cenariano em Kalimdor.\n\nSerá bem $Grecebido:recebida; lá, e os druidas do Círculo vão dividir o que sabem com você.\n\nComo diriam os do seu povo, vá com as bênçãos dos ventos, jovem. Desejo muita sorte nas suas aventuras.", t = "Cria da natureza"},
    [94912] = {ot = "Fale com Sheldras Lunárvore em Ventobravo.", st = "Saudações, jovem $c.\n\nOuviu falar do Círculo Cenariano? Imagino que não. É uma ordem antiquíssima de naturalistas e praticantes das artes druídicas, assim como você. Na cidade de Ventobravo, há um elfo noturno chamado Sheldras Lunárvore. Ele lhe ensinará como chegar a um lugar chamado Clareira da Lua, que é o baluarte do Círculo Cenariano em Kalimdor.\n\nAgora vá. Você tem muito o que aprender se deseja salvar seu lar.", t = "Cria da natureza"},
    [94913] = {ot = "Use o feitiço \"Teleporte: Clareira da Lua\" para viajar para a Clareira da Lua. Ao chegar, fale com Dendrite Stellardor, no vilarejo de Refúgio Noturno.", st = "Todos os druidas são bem-vindos nas terras sagradas da Clareira da Lua. Remulos, o Guardião da Clareira da Lua, cuida de todos os druidas que lá hibernam. Vou ensinar o feitiço para que você se teletransporte para lá. Lance o feitiço sempre que precisar da sabedoria ou do apoio da Clareira da Lua.$B$BPara a sua primeira missão aqui em Azeroth, viaje para a Clareira da Lua e fale com Dendrite Stellardor, no Refúgio Noturno, sobre o caminho que você está trilhando agora. Boa sorte, jovem druidG$a:esa;.", t = "Clareira da Lua"},
    [94946] = {ot = "Pegue o navio rasgacéus da Ilha de Zefras até Dalaran e fale com Denaaris Ventáster quando chegar lá.", st = "Eu pretendia ser o primeiro a pôr os pés em Azeroth, mas eventos recentes com a seita me fizeram mudar os planos. Por isso, ficarei em Valanaar por algum tempo. Não se preocupe, pois há vários magos aguardando a chegada de nosso povo a Dalaran. Eu $Go:a; incentivo a explorar Azeroth enquanto organizamos nossos assuntos por aqui. Chamaremos quando a presença de agentes como você for necessária.\n\nQuando estiver $Gpronto:pronta;, prossiga para a doca nos arredores deste alojamento e embarque no navio rasgacéus.", t = "A cidade mágica de Dalaran"},
    [94947] = {ot = "Pegue o Portal Celonato para Ventobravo e apresente-se a Bolvar Fordragon na Bastilha Ventobravo.", st = "É um mundo grande aqui embaixo, e precisamos que nosso povo comece a se aventurar para explorá-lo. É aí que você entra.\n\nO Kirin Tor é membro de uma chamada Aliança de nações com ideais semelhantes. O coração de fato dessa aliança é a cidade de Ventobravo, ao sul. Elaadrin me pediu para encontrar alguém para viajar até Ventobravo e se encontrar com o lorde regente de lá, um humano chamado Bolvar Fordragon.\n\nQuando você estiver com tudo pronto para ir, os magos do Kirin Tor prepararam um portal especial para a Alta Ordem acessar Ventobravo.", t = "Boas-vindas a Azeroth"},
    [94978] = {ot = "Use o Bastão de Adestramento para domar um Rastejante Cantéolo, que pode ser encontrado perto de corpos d'água. \nTreine sua perícia e depois devolva o Bastão de Adestramento a Quel'ana Ventiágil em Valanaar.", st = "A jornada do caçador começa com o aprendizado do vínculo entre a fera e quem a doma. Este é o seu primeiro desafio. Com o tempo, você domará criaturas de todos os cantos do mundo, mas, por enquanto, comece por nossos rios e lagos em Zefras. \n\nLeve este Bastão de Adestramento e procure um rastejante cantéolo.\n\nMostre que consegue conquistar a confiança dele e inicie seu caminho rumo à verdadeira maestria.", t = "Domando a fera"},
    [94979] = {ot = "Use o Bastão de Adestramento para domar um Vagaventos Turrão nos Baixios dos Lufopomos. \nTreine sua perícia e depois devolva o Bastão de Adestramento a Quel'ana Ventiágil em Valanaar.", st = "Você provou que consegue domar o rastejante do rio. Agora é hora de testar sua habilidade em campo aberto. As planícies de Zefras ecoam com os gritos do vagaventos, um predador alado e altivo que corre como o vento.\n\nLeve este bastão de adestramento e procure um vagaventos. Viaje para os baixios e conquiste a confiança dele.\n\nMostre que tem o preparo necessário para as provações que estão por vir.", t = "Domando a fera"},
    [95034] = {ot = "Fale com Lúmina Cantavento no Sepulcro.", st = "Acho que você devia saber que não foram os gnolls que nos atacaram na estrada.\n\nNa verdade, quem nos atacou foi uma criatura lupina gigantesca que eu descobri que se chama \"worgen\". Ele logo se livrou de nossos guardas e veio atrás de mim, mas o Banon se jogou na frente. Eu consegui lançar um feitiço que assustou a criatura e a fez fugir, mas o Banon já tinha sofrido uma mordida bem feia. Ele insistiu que eu o abandonasse, mas eu me recusei.\n\nEstávamos fazendo o caminho de volta, mancando, quando os gnolls nos encontraram. O que aconteceu depois foi assustador...", t = "A dívida"},
    [95065] = {ot = "Leve $1oa Miçanga Brilhosa e $2oa Reptantes para Gilberto Cinéreo no porto em Ventobravo.", st = "Que vista... O que mais um velhote pode querer?\n\nOs peixes com certeza estão mordendo agora, mas estou na minha última isca. Suponho que você não tenha nenhum suprimento de pesca com você, não é? É claro que não, me perdoe. Fico tão empolgado com a ideia de pescar que nem me ocorre que devo ser um dos poucos a carregar suprimentos aonde quer que eu vá.\n\nVocê me ajudaria a reabastecer meu estoque? Catarina Gurjão tem uma porção de mercadorias de pesca a oeste do Distrito Comercial, ao longo dos canais. Diga a ela que o velho Cinéreo mandou você.", t = "Hora da pesca"},
    [95161] = {ot = "Entregue a Carta Manchada de Sangue a Avette Cortalenha na Floresta do Crepúsculo.", st = "Se está atrás do Jeremias Tececórdio, é melhor procurar Avette Cortalenha na Floresta do Crepúsculo. Ela o adotou recentemente, é uma mulher adorável. Deve estar precisando de ajuda no trabalho, mas é melhor que ficar no orfanato.\n\nSe vir o Jezinho, diga que todos nós mandamos um abraço pra ele, por gentileza.", t = "Lembre-se de que eu te amo"},
    [95189] = {ot = "Devolva o Escudo de Lordaeron a Lady Dina Cápita em Ventobravo.", st = "<Um escudo desgastado com a marca de Lordaeron. As relíquias tornaram-se tão escassas após a queda do reino que deve haver alguém em Ventobravo que se interesse por isto.>", t = "Escudo de Lordaeron"},
    [95195] = {ot = "Colete $1oa Insígnias Ensanguentadas e leve-as ao General Marcus Jonas em Ventobravo.", st = "<A velha insígnia da Aliança pareça ter pertencido a um soldado de Lordaeron. Estas ruínas devem estar cheias de medalhas semelhantes que os parentes vivos receberiam de bom grado.>", t = "Insígnia Ensanguentada"},
    [95204] = {ot = "Leve o Escudo de Lordaeron a Urraca Convulserpe na Cidade Baixa.", st = "<Um escudo desgastado com a marca de Lordaeron. As relíquias tornaram-se tão escassas após a queda do reino que deve haver alguém na Cidade Baixa que se interesse por isto.>", t = "Escudo de Lordaeron"},
    [95212] = {ot = "Colete 6 Pelagens de Leopardo Imaculadas e entregue-as no Rancho Ambarmanso.", st = "A gente tá querendo mandar um bando de carneiros pra dar uma ajuda pra expedição de Alterac, só que acabou o material pra fazer as selas.\n\nTem como tu arrancar a pele dos leopardos mais brabos e mais bitelos que tu achar a leste daqui e trazer pra mim? Tá um frio de lascar, e o nosso pessoal merece se aquecer com pelagem da melhor qualidade!", t = "Sela com selo de qualidade"},
    [95213] = {ot = "Leve o Barril de Pólvora Vazio ao Mestre de Pedreira Thesten na Pedreira Gol'Bolar.", st = "Lê-se no barrilete:\n\nPÓ EXPLOSIVO — PERIGO — NÃO MANUSEAR — PERIGO — MATERIAL RESTRITO AO PESSOAL AUTORIZADO PELO MESTRE DE PEDREIRA — PERIGO\n\nPouco a pouco, você se dá conta de que isso não deveria cair nas mãos dos troggs. Melhor relatar à pedreira antes que seja tarde.", t = "Pó Explosivo Roubado"},
    [95214] = {ot = "Recupere $1oa unidades de Pó Explosivo Roubado dos trogg a leste da Pedreira Gol'Bolar e fale novamente com o Mestre de Pedreira Thesten.", st = "Tinha tanto pó explosivo aí que dava pra mandar a sala do trono do Rei Magni pra outra cidade, com rei, corte e tudo. A gente tem que arrancar isso dos troggs antes que eles aprendam a detonar esse negócio.", t = "Pó Explosivo Roubado"},
    [95216] = {ot = "Colete a Cepa Altamente Tóxica do Sugapresa nas Ruínas de Lordaeron para Teodoro Chaves, na Cidade Baixa.", st = "Boas-vindas ao órgão mais importante da Cidade Baixa: o Boticarium! Aqui, conduzimos experimentos terribilíssimos com espécimes exóticos de Azeroth.\n\nComo você me apanhou de bom humor, deixarei que participe da minha nova pesquisa. Parece que há um artrópode particularmente peçonhento rondando as ruínas em cima da nossa esplêndida cidade. Dizem que as toxinas dele corroem até carne morta-viva. Que emoção!\n\nQuero descobrir se tais afirmações têm fundamento. Caso você definhe em razão da picada dele, vou adorar estudar a amostra.", t = "A nova peste"},
    [95217] = {ot = "Colete 12 Barras de Cobre e 4 Pelegos de Javali Endurecidos e entregue-os a Frast Dokner.", st = "Então tu quer aprender o ofício da ferraria? Acho que dá pra gente se ajudar.\n\nA entrega dos suprimentos atrasou, e eu tô sem material pra fazer consertos no acampamento. Tu me consegue as coisas de que eu preciso, e eu te ensino umas técnicas minhas. Que tal?", t = "O ferreiro da Pedreira"},
    [95250] = {ot = "Colete a Cabeça do Barão nas Ruínas de Lordaeron e leve-a de volta para o Capitão Truman.", st = "O que você quer, $r? Não vê que há uma guerra a ser vencida?\n\nMeu mestre já se lançou à batalha e ordenou que eu mantivesse minha posição. Mas já faz um bom tempo que ele partiu.\n\nDuvido que você sobreviva dez minutos em combate, mas, se for manter sua mente simplória ocupada, por que você não vai atrás do Grão-marechal? Ele é o herói mais alto e imponente que você já viu. Você vai reconhecê-lo assim que o vir.", t = "Criaturas abomináveis"},
    [95314] = {ot = "Colete $1oa Garrafas de Elixir Sussurrante no Vale das Sombras e fale novamente com Carolai Anise em Montalvo.", st = "Antes da invasão do Flagelo, o Vale das Sombras, vilarejo isolado, era conhecido pelo Elixir Sussurrante. Destilado de ervas encontradas somente na Queda de Tyr, o elixir era muito procurado por boticários, místicos e preparadores de veneno, mesmo depois de ser proibido na cidade.\n\nRecebi muitos pedidos de compradores ávidos pelo elixir. Vá até as ruínas do Vale das Sombras, nas profundezas da Floresta do Sussurro, a oeste. Estou disposta a lhe oferecer compensação substancial se conseguir recuperar algumas garrafas para mim.", t = "O elixir verde do Vale das Sombras"},
    [95328] = {ot = "Entregue Resíduo do Horror Sussurrante ao Padre Gusmão no Distrito Bélico da Cidade Baixa.", st = "Contrariando o bom senso, você recolhe os restos ainda pulsantes da fera. Alguém na Cidade Baixa deve achar alguma utilidade para eles.", t = "Resíduo do Horror Sussurrante"},
    [95349] = {ot = "Pegue o navio rasgacéus da Ilha de Zefras até Mulgore e fale com Alaana Tempesvaga quando chegar lá.", st = "Os eventos recentes com a seita atrasaram meus planos de viajar para Azeroth, então devo ficar em Valanaar por um tempo. Você e alguns outros Moldavento serão nossa vanguarda. Alaana Tempesvaga estará esperando para receber nossos Moldavento quando chegarem em Mulgore, e eu $Go:a; incentivo a explorar Azeroth enquanto resolvemos nossas pendências aqui. Nos juntaremos a você em breve.\n\nQuando estiver $Gpronto:pronta;, prossiga para a doca nos arredores deste alojamento e embarque no navio rasgacéus.\n\nBanu-alah, $n.", t = "Harmonia Telúrica"},
    [95350] = {ot = "Viaje a Orgrimmar e fale com Thrall no Vale da Sabedoria.", st = "O mundo aqui é vasto, e a nossa sobrevivência depende dos nossos novos aliados.\n\nA Harmonia Telúrica pertence à \"Horda\", um aglomerado de povos que orgulhosamente partilha dos mesmos princípios. Penhasco do Trovão, a cidade próxima daqui, é domínio da Horda, e mais a leste se encontra a capital de Orgrimmar.\n\nProcure o Mestre de Voo no centro do Penhasco do Trovão. Ele $Go:a; levará a Orgrimmar, onde você travará contato com o Chefe Guerreiro da Horda, Thrall, em nome dos Moldavento. Que os ventos $Go:a; guiem, $n.", t = "Boas-vindas a Azeroth"},
    [95494] = {ot = "Colete 6 Pelegos de Leão da Savana de Matriarcas da Savana e Patriarcas da Savana nos Sertões.", st = "Seria ótimo se aparecesse alguém com uma espada afiada e tempo de sobra para me ajudar a pegar pelegos de leão. Fere o meu orgulho pedir esse favor a $Gum estranho:uma estranha;, mas machuquei a perna há pouco tempo. Estou impossibilitado de caçar até sarar, mas as obrigações não param.\n\nOs leões maiores da região são os que rendem os melhores pelegos, então comece por eles.", t = "Perna e orgulho feridos"},
    [95495] = {ot = "Leve o Pacote de Peles para o eremita no cume com vista para os Montes Áridos, nos Sertões.", st = "Essas peles são para um curtumeiro com quem sempre faço negócios. Ele é meio ermitão, mora isolado no cume ali atrás de mim. Não estou em condições de escalar encostas íngremes agora, então vou ficar devendo um favor se você fizer essa entrega para mim.\n\nAh, e quanto à... aparência do curtumeiro, não se assuste. O aspecto dele espanta, mas ele não faz mal a uma mosca. Dou a minha palavra.", t = "O curtumeiro ermitão"},
    [95507] = {ot = "Colete 8 Caças Encurraladas achadas em Armadilhas Disparadas nos Sertões.", st = "Se puder aproveitar as suas andanças para conferir as minhas armadilhas, vou ficar muito grato. Elas estão espalhadas por todo o vale.\n\nTraga de volta os animais de pequeno porte apanhados. Mas tome cuidado com outros animais selvagens. Essa área é perigosa para quem é descuidado.", t = "A caça de Vrang"},
    [95508] = {ot = "Ajude Walton a sobreviver ao confronto com Téo Tragolongo e os marinheiros kultirenos.", st = "É, eu era da marinha kultirena. Depois que o Lorde-almirante tomou Theramore e começou a sua campanha em Durotar, eu tinha... \"objeções\" às práticas dele. Principalmente a de executar civis.\n\nA história não acaba aí, mas... calma. O que é aquilo?\n\nTem um bando de homens subindo até o cume!", t = "Convidados indesejáveis"},
    [95621] = {ot = "Vá até a caravana destroçada e descubra por que os kultirenos estão aqui.", st = "Hoje de manhã vi um grupo de humanos procurando alguma coisa no vale, lá embaixo. Com a mira do rifle, consegui ver que eram soldados com emblemas de Kul Tiraz.\n\nAceita um trabalho de mim? Vá aonde os soldados montaram acampamento, perto da caravana destroçada a sul. Mate os que encontrar e descubra por que estão aqui.", t = "Problema no vale"},
    [95646] = {ot = "Mate um Horror do Planalto nos Sítios de Escavação e leve o núcleo da raiz para Rethiel, o Verdião, no Pantanal.", st = "Este pantanal salobro abriga um poço ainda maior de águas doces do sul. Isso me entristece, mas em minhas raízes eu sinto uma corrupção se infiltrando por aquela ravina da montanha.\n\nAs criaturas, assim como as dos nossos baixios, reagem mais amargamente à mácula. Desprovidas do sal endurecedor do mar desde a aurora da vida, elas têm pouca força contra esse mal.\n\nVá até aquele planalto e traga o núcleo da raiz do Horror das Terras Altas.", t = "Pavores no planalto"},
    [95647] = {ot = "Encontre Aldo Pastofino nos Sítios de Escavação.", st = "Meu marido, Aldo, tem um dom raro para sentir a natureza. Ele escala qualquer pico para colher as ervas e flores de que preciso para a minha alquimia, mantendo nossas prateleiras e despensa abastecidas.\n\nMas temo que ele tenha se metido em apuros. Uma equipe de escavação passou por aqui à procura de suprimentos. Eles falaram, entre outras coisas, de gramas gigantescas diferentes de tudo que já tinham visto. Foi o que ele me disse que precisava ir ver com os próprios olhos. Ele está fora há tempo demais!\n\nSerei muito grata se trouxer notícias dele.", t = "No olho do matagal"},
    [95663] = {ot = "Viaje até o Pantanal e encontre a Agente Sicária nas colinas acima do acampamento Presa do Dragão.", st = "Os Presa do Dragão são um clã formidável.\n\nSão conhecidos por vincular magia forte o suficiente para fazer dragões servirem, e boatos afirmam que estão preparando alguma amostra disso no Pantanal. Seja verdade ou fanfarrice, os Sicários não podem agir com base em sussurros parciais. Símbolos quebrados trouxeram apenas isso até mim.\n\nUma agente dos sicários precisa de ajuda nas colinas acima do acampamento dos Presa do Dragão. Encontre-a lá. Ela revelará os próximos passos.", t = "Boatos dos Presa do Dragão"},
    [95664] = {ot = "Leve a Relíquia Titânica até o Platô dos Anciãos, no Penhasco do Trovão e procure por alguém que possa lhe dizer mais a respeito dela.", st = "Este estilhaço de composto incomum espalha a luz como um prisma vivo. Sua natureza é incerta, mas seu poder parece ancestral. Os maiores conhecedores de artefatos dessa era esquecida devem residir no Platô dos Anciãos, no Penhasco do Trovão.", t = "Conhecimento ancestral"},
    [95682] = {ot = "Derrote as forças da Presa do Dragão no Sítio de Escavação e fale novamente com a Agente Sicária do lado de fora com qualquer coisa que recuperar.", st = "Presa do Dragão. <Ela solta um riso seco de escárnio>.\n\nOs remanescentes do clã de domadores de dragões acham que encontraram algo que pode reconduzi-los ao poder de outrora. Aos olhos de quem... do seu falso chefe guerreiro? \n\nElimine esse clã esfarrapado dos Sítios de Escavação para que nossos Sicários possam entrar sem serem detectados.\n\nSe os Presa do Dragão carregarem qualquer coisa digna de nota, traga para mim. Essa informação deve permanecer entre nós e nosso comando real.", t = "Presa fácil"},
    [95697] = {ot = "Entre nos Sítios de Escavação no Pantanal e traga Carne de Raptor do Matagal.", st = "Zamja me diz que precisamos de mais comida caseira.\nSe começarmos a vender raptor, ela acha que isso vai atrair clientes que normalmente não visitam a Fogueira de Borsgan.\n\nA ideia dela até que não é ruim, mas eu quero algo que supere o cheiro das nossas aldeias natais. Estamos em Orgrimmar! Borsgan deveria servir uma versão grandiosa dos pratos favoritos deles.\n\nUm caçador voltou recentemente do Pantanal com uma garra gigante dos raptores do matagal nos Sítios de Escavação.\n\nAceita o serviço?", t = "Mudando o cardápio"},
    [95772] = {ot = "Procure o irmão de Dorin Espada-cantante, Daewyn, no Sítio de Escavação de Whelgar.", st = "Meu irmão tentou me arrastar lá pro Pantanal com uma equipe de escavação de Loch Modan. Disse que tavam indo prumas colinas onde nenhum anão jamais pisou a bota, pra fazer algum tipo de escavação.\n\nBah, eu até teria ido se não estivesse tão enrolado com essa pilha de cinturões pra ajustar.\n\nMas o Daewyn sempre escreve depois que sai. Ainda não ouvi um pio dele, o que tá me deixando com a pulga atrás da orelha.\n\nSe tu tá marchando praqueles lados, pode dar uma espiada pra ver como o meu irmão tá?", t = "Em busca do Espada-cantante"},
    [95774] = {ot = "Mate javatuscos e pegue $1oa dos Adornos de Olgra para o memorial de Mankrik.", st = "O curandeiro que me salvou não conseguir salvá-la, e ela morreu em combate. O nome dela era Olgra, e eu nunca vou esquecê-la.\n\nVocê não encontrou os adornos no corpo dela? Ela vestia muitas joias de ossos polidos.\n\nAcabe com os Saqueadores Crinavalha perto de onde ela se foi, e encontre as obras de arte dela!\n\nVou colocá-las no memorial que construí para ela.", t = "O nome dela era Olgra"},
    [95795] = {ot = "Fale novamente com Dorin Espada-cantante.", st = "<Você cobre o corpo do anão com a capa dele.>\n\nViaje para Vila Plácida e informe pessoalmente a Dorin Espada-cantante o que aconteceu ao irmão dele nos Sítios de Escavação.", t = "Caído no brejo"},
    [95803] = {ot = "Leve a cabeça de Rudolph Gelhardt a Sylvana Correventos na Cidade Baixa.", st = "Agora que arrancamos a cabeça do comandante manchado, preciso que você a entregue na Cidade Baixa. Sylvana Correventos desconfia muito de nós e mal faz questão de esconder seu desprezo.\n\nEntregue a cabeça de Rudolph Gelhardt à Dama Sombria. Mostre a ela que cuidamos de nossa própria casa e estamos dedicados à prosperidade dos Renegados.", t = "Uma prova de boa-fé"},
    [95805] = {ot = "Leve o Incenso Fumegante ao santuário de An'she e Mu'sha nas colunas a sudeste antes que o incenso vire cinzas em dez minutos!", st = "O sol e a lua, An'she e Mu'sha, não fazem parte do nosso mundo como os elementos, mas sua luz nos dá vida, orientação e esperança.\n\nRespeitamos os espíritos do mundo, portanto também respeitamos os gêmeos.\n\nSe quiser demonstrar seu respeito, pegue este incenso fumegante e leve-o a um santuário nas colinas a sudeste, voltado para a chapada, ao sul dos javatuscos. Seja $grápido:rápida; para chegar ao santuário antes que o incenso termine de queimar.\n\nNão molhe!", t = "Graça de An'she e Mu'sha"},
    [95809] = {ot = "Fale novamente com Tina Pastofino no Porto de Menethil.", st = "Preciso descansar um pouco antes de procurar o caminho de volta.\n\n<Ele tira alguns juncos da mochila e rapidamente os trança em forma de coração.>\n\nEntregue isso a Tina. Diga a ela que vou estar em casa em breve! Agora que temos um caminho livre graças a você, vou recolher meus feixes e seguir o seu rastro.\n\nObrigado.", t = "Coração trançado"},
    [95810] = {ot = "Leve a Relíquia Titânica para o Prospector Whelgar no sítio de escavação do Pantanal.", st = "Você pega um pedaço lascado do autômato mecânico rochoso. Ele tem uma textura diferente de tudo que você já tocou antes, um material composto de constituição desconhecida. Isso certamente tem mais cara de dispositivo que de sucata.\n\nO Prospector Whelgar pode ter algo útil para partilhar a respeito dessa relíquia no sítio de escavação dele.", t = "O transporte da relíquia perdida"},
    [95883] = {ot = "Colete uma Alma Torturada dos mortos-vivos próximos na Cilada de Beren, que fica na Floresta de Pinhaprata.", st = "<Os preparativos para um ritual feito às pressas foram agrupados sem cerimônia no altar. De acordo com o papel rasgado, quase tudo foi reunido. Faltam apenas a oferenda de sangue e a alma torturada.\n\nOs mortos-vivos ao seu redor parecem bastante torturados. Eles devem ter o que você procura.>", t = "A alma torturada"},
    [95884] = {ot = "Encontre a Pedra de Oferenda na Cilada de Beren, que fica na Floresta de Pinhaprata.", st = "<O papel rasgado está praticamente ilegível. Pelo que ainda dá para ler, parece que são anotações sobre os preparativos para uma oferenda.\n\nMencionam uma pedra de oferenda, bem como um ritual.\n\nTalvez você possa encontrar a pedra de oferenda aqui perto.>", t = "A pedra de oferenda"},
    [95885] = {ot = "Use a Alma Torturada para fazer uma oferenda de sangue na Pedra de Oferenda, na Cilada de Beren.", st = "<Tudo o que falta agora é a oferenda de sangue.\n\nO bilhete rasgado menciona um \"sacrifício voluntário\".\n\nUm pavor sinistro toma conta de você.>", t = "A oferenda de sangue"},
    [95981] = {ot = "Abata $1oa Teurgos de Dalaran e $2oa Vigias de Dalaran para o Sacerdote Sombrio Allister no Sepulcro.", st = "Tomar os pingentes deles é só o primeiro passo. Se o Kirin Tor está mesmo enviando um fornecimento regular de relíquias de Dalaran, precisamos detê-los na fonte.\n\nProcure por vigias e teurgos de Dalaran nas estradas ao redor de Lenhâmbar. Sua presença permitiu que cruzassem nossas fronteiras livremente por muito tempo. Se conseguirmos reduzir seus números, creio que vamos impedir até mesmo que os pingentes cheguem à Floresta de Pinhaprata.", t = "De olho nas estradas"},
    [95998] = {ot = "Sente-se perto da Fogueira Básica de Sam e espere até receber um bônus de Descanso Melhorado.", st = "Opa, tudo bem, $c? Tô vendo que você tem jeitão de $Gaventureiro:aventureira;. Aí sim. O mundo precisa de mais almas inquietas como a gente, atrás de glória e fortuna.\n\nO mundo é imenso, e você vai ter que aprender a se virar no mato pra se dar bem. Não sei como são as suas habilidades campeiras, mas garanto que posso te ensinar uma coisa ou outra, se estiver a fim de aprender.\n\nPuxa um banco aí perto do fogo, fica à vontade. Vou te mostrar como é.", t = "Vida ao ar livre"},
    [95999] = {ot = "Entregue o Cajado Quebrado do Incinerador Gar'im ao Magistrado Salomão em Vila Plácida.", st = "Procura-se! Incinerador Gar'im, líder de uma incursão órquica no Vale dos Laceradores. Suspeito de estar trabalhando com os Rocha Negra da Bastilha Mirante de Pedra.\n\nCuidado com o Incinerador Gar'im. Ele e seus Lança-sombras são perigosíssimos. Oferecemos uma recompensa generosa a qualquer alma corajosa que entregar provas da morte do Incinerador Gar'im ao Magistrado Salomão.", t = "PROCURADO: Incinerador Gar'im"},
    [96031] = {ot = "Fale com Gretta Fusofino em Altaforja para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Você se tornou $Gcoureiro:coureira;. Que bom, $c. Acho que eu conheço alguém que pode lhe ensinar a criar uma tenda que deixará você $Gfresco:fresca; em dias quentes, e $Gseco:seca; em dias chuvosos.\n\nCom uma boa tenda sobre a cabeça, você terá todo o descanso necessário para ficar firme em suas viagens.", t = "Introdução ao acampamento: Couraria"},
    [96044] = {ot = "Fale com Tognus Pederfogo em Kharanos para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Bom, agora você é $Gum ferreiro:uma ferreira;. Ótima escolha se quiser lâminas sempre afiadas.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar uma roda de afiar. Coloque uma dessas em seu acampamento, que todos os guerreiros e ladinos na área farão fila para afiar as armas.", t = "Introdução ao acampamento: Ferraria"},
    [96045] = {ot = "Fale com Vosur Brakthel em Altaforja para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Agora que tu começou a aprender Alquimia, acho que vou poder te ensinar a criar teu próprio poço de mana pro teu acampamento quando tiver aprendido mais um tanto. Constrói um desses, que todos os tipos de curadores e lançadores de feitiços vão vir correndo pra ter um gostinho.", t = "Introdução ao acampamento: Alquimia"},
    [96046] = {ot = "Fale com Yarr Malhapedra em Kharanos para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Mineração não é lá uma coisa muito glamorosa, mas é um trabalho honesto e uma ótima profissão para você se aventurar.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar uma magnetita para o seu acampamento. Crie uma dessas e qualquer um que queira brandir uma espada vai adorar ficar ao redor da sua fogueira para aproveitar aquele \"tchan\" que ela dá, aumentando a capacidade de combate de todos.", t = "Introdução ao acampamento: Mineração"},
    [96047] = {ot = "Fale com Thamner Pol em Kharanos para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Então você assumiu os primeiros socorros? É uma empreitada muito respeitável e... pragmática, sendo você $Gum:uma; $c.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar um kit de primeiros socorros para o seu acampamento. As lesões acontecem no mundo das aventuras, e oferecer a tão necessária cura em seu acampamento pode até salvar vidas.", t = "Introdução ao acampamento: Primeiros Socorros"},
    [96050] = {ot = "Fale com Paxton Ganter perto do Lago Nevado em Dun Morogh para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Talvez você não acredite, mas a habilidade com pesca pode ser muito útil no acampamento.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar um aquário para o seu acampamento. Use esse dispositivo para dar um pouco mais de alegria a si $Gmesmo:mesma; e aos colegas aventureiros. Um aventureiro feliz é um aventureiro forte, e tenho certeza de que sua capacidade em combate refletirá isso.", t = "Introdução ao acampamento: Pesca"},
    [96055] = {ot = "Fale com Reyna Galhopétreo em Altaforja para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Estou notando que você andou praticando o herborismo. Colher flores não é uma perda de tempo. Pode ser útil... e lucrativo.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar uma vela de incenso para o seu acampamento. O moral elevado é um componente importante para manter curadores e lançadores de feitiço na luta, e uma vela de incenso pode dar um reforço que os usuários de magia vão apreciar.", t = "Introdução ao acampamento: Herborismo"},
    [96056] = {ot = "Fale com Balthus Esfolapedra em Altaforja para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Saber coletar com maestria as peles e os pelegos de feras abatidas é uma das habilidades mais úteis que um aventureiro pode ter.\n\nAcho que eu conheço alguém que pode te ensinar a criar uma cadeira de acampamento. Às vezes, é importante descansar um pouco, e você pode usar as peles que coletou para fazer uma cadeira confortável. Um pouquinho de relaxamento ajuda a deixar você em ótima forma para que consiga desferir o golpe certeiro na próxima vez que se meter em uma briga.", t = "Introdução ao acampamento: Esfolamento"},
    [96057] = {ot = "Fale com Uthrar Threx em Altaforja para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Pode te surpreender, mas a alfaiataria é um ofício muito potente para investir, e com certeza tem tudo a ver contigo.\n\nConheço alguém que pode te ensinar a criar um estandarte de facção para o teu acampamento, caso tu tenha a perícia adequada. Inspiração e moral são cruciais para o sucesso em qualquer batalha, e um estandarte inspirador faz milagres quando se trata de te deixar com os ânimos lá em cima.", t = "Introdução ao acampamento: Alfaiataria"},
    [96058] = {ot = "Fale com Bronk Gargrenagem em Kharanos para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "$GEngenheiros:Engenheiras; como você conseguem preparar todo tipo de bomba e bugiganga só por lucro e diversão.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar um robô de reagentes para o seu acampamento. Esse autômato prestativo pode cuidar do seu estoque para você e os seus aliados nunca ficarem sem os materiais necessários pra ativar os feitiços.", t = "Introdução ao acampamento: Engenharia"},
    [96059] = {ot = "Fale com Thonys Pedrapilar em Altaforja para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Agora que tu começou essa jornada no estudo dos Encantamentos, acho que eu vou poder te ensinar a criar um alaúde encantado pro teu acampamento quando tu tiver aprendido mais um tanto.\n\nÉ muito importante se divertir durante o ócio, e esse pouquinho de magia pode te ajudar a te preparar pra suportar todo tipo de desafio quando pegar a velha estrada poeirenta de novo.", t = "Introdução ao acampamento: Encantamento"},
    [96101] = {ot = "Sente-se perto da Fogueira Básica de Raan e espere até receber um bônus de Descanso Melhorado.", st = "Saudações, $c. Vejo que você tem a aparência de $Gaventureiro:aventureira;. Isso é bom. O mundo precisa de mais almas inquietas como nós, que buscam fortuna e glória.\n\nVocê precisará aprender a prosperar na natureza se quiser ter sucesso neste tipo de trabalho. Não conheço suas habilidades ao ar livre, mas posso ensinar uma coisinha ou outra, se você puder aprender.\n\nSente-se perto do fogo e fique à vontade. Vou explicar tudo.", t = "Vida ao ar livre"},
    [96102] = {ot = "Fale com Snang em Orgrimmar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Pode te surpreender, mas a alfaiataria é um ofício muito potente para investir, e com certeza tem tudo a ver com você.\n\nConheço alguém que pode lhe ensinar a criar um estandarte de facção para o seu acampamento, caso você tenha a perícia adequada. Inspiração e moral são cruciais para o sucesso em qualquer batalha, e um estandarte inspirador faz milagres quando se trata de deixar você com os ânimos lá em cima.", t = "Introdução ao acampamento: Alfaiataria"},
    [96130] = {ot = "Derrote Chakuyak e volte com a pelagem dela.", st = "Entre os lobos da pradaria que caçam nas colinas próximas, há uma loba especialmente agressiva. Chamamos ela de Chakuyak. Tornou-se uma ameaça aos viajantes vindos de fora.\n\nEla ronda a floresta a oeste do Lago da Ferradura, indo de arvoredo em arvoredo.\n\nPonha fim a essa ameaça e traga a pele dela. Falarei bem de você ao chefe. Tenha cuidado. Ela é perigosa! É possível que encontre outros caçadores procurando por ela, e talvez vocês possam trabalhar em equipe.", t = "Chakuyak"},
    [96137] = {ot = "Derrote $1oa Assoladores Negros Jovens e $2oa Assoladores Negros, depois retorne para Sirra Von'Indi na Vila Sombria para obter mais informações.", st = "Uma pequena adaga pertencente a Íria, que se autoproclamou uma patrulheira e mantinha as florestas seguras impedindo que as feras atacassem os viajantes.\n\nCom o espírito de Íria ainda vagando pela mata, talvez seu assunto inacabado fosse eliminar os worgs que continuam fazendo vítimas por toda a floresta.", t = "Adaga de Íria"},
    [96139] = {ot = "Procure qualquer coisa de interesse no Monte Corvo e retorne para Sirra Von'Indi na Vila Sombria.", st = "Em tempos sombrios como estes, é importante nos lembrarmos de nossos heróis tanto quanto de nossos inimigos. A Vila Sombria não continuaria de pé se não fosse pela bravura de boa gente como a Aldora ou aqueles que perderam a vida no Monte Corvo.\n\nVocê já leu muito sobre o Monte Corvo? Não, claro que não. A história dele foi apagada junto com seu povo. Minha biblioteca, por mais impressionante que seja, tem pouco sobre o assunto.\n\nSe encontrar qualquer coisa, eu agradeceria se trouxesse aqui. Aquele povo merece ser lembrado.", t = "A família Bravura"},
    [96204] = {ot = "Acompanhe Lúmina Cantavento e ajude-a a fugir do Castelo Fenris.", st = "Agora que estou livre, vou fazer essas criaturas torpes se arrependerem de porem os olhos em uma Moldavento.\n\nVamos sair daqui, $c.", t = "A ira da Moldavento"},
    [96390] = {ot = "Mate $1oa Espiões Ferro Negro em Dun Morogh.", st = "Espiões Ferro Negro se infiltraram em Dun Morogh. Pra quê, eu não sei te dizer, mas a gente precisa cortar esse mal pela raiz antes que a coisa cresça.\n\nToca pro leste, em direção ao Complexo de Bandaferro, e dá cabo dos espiões Ferro Negro que tu achar por lá.", t = "Cortando o mal pela raiz"},
    [96391] = {ot = "Entregue o Mapa Ferro Negro ao Vidente da Terra Farsen em Dun Morogh.", st = "O mapa que você tem em mãos parece mostrar uma intrincada rede de túneis e vias subterrâneas que convergem em um ponto bem abaixo de Altaforja.\n\nNão é possível determinar ao certo o que dizem as runas, pois foram escritas na linguagem rúnica grosseira e angulosa dos anões Ferro Negro. Ainda assim, dá para deduzir a finalidade desses túneis. Enquanto você examina o mapa, uma rajada de vento passa por você, trazendo uma voz enânica quase inaudível. O Vidente da Terra Farsen precisa ver isso.", t = "Mapa subterrâneo"},
    [96392] = {ot = "Fale com o Vidente da Terra Farsen e peça que lhe empreste sua visão distante para observar a ameaça Ferro Negro.", st = "Buenas, vivente. Eu me chamo Vidente da Terra Farsen e eu vim lá do Ninho da Águia pra visitar Dun Morogh. Nas minhas andanças, não pude deixar de notar que a gente temos, bueno... um probleminha com os Anões Ferro Negro.\n\nSe tu tiver um tempinho, posso te mostrar bem o causo. Eu tenho um truquezinho mágico que é tiro e queda, tchê.", t = "Vigília de Farsen"},
    [96393] = {ot = "Adentre o Salão dos Thanes abaixo da Antiga Altaforja e corte a cabeça de Durgen Martelúgubre.", st = "Junta uns parceiros e desce lá pras cavernas embaixo da Antiga Altaforja. Entra no Salão dos Thanes e avança pras câmaras mais fundas.\n\nMeu Ferro Negro tá meio enferrujado, mas consegui pescar um nome: um tal de Durgen Martelúgubre. Capaz que ele seja o comandante. Corta a cabeça dele e entrega pro Rei Magni Barbabronze.\n\nAh, e quando tu fizer isso, avisa ele que o velho amigo Farsen mandou um abraço!", t = "Incursão à Antiga Altaforja"},
    [96394] = {ot = "Mate $1oa Aparições Enfurecidas, $2oa Almas Atormentadas e dê descanso ao espírito de Sidermar.", st = "Alguma coisa alvoroçou as tumbas lá no Salão dos Thanes, e andam escutando uns barulhos esquisitos vindo lá do fundo das câmaras. Os espíritos dos mortos têm o sono leve e, seja lá o que for que tá acontecendo lá embaixo, parece que assustou eles.\n\nDesce lá e vê o que tu pode fazer pra ajeitar isso pra gente. Se algum dos mortos tiver acordado... bueno, tu põe eles pra dormir de novo!", t = "Os mortos inquietos"},
    [96395] = {ot = "Dê descanso ao espírito de Faldrim Sidermar e depois fale novamente com a Atendente Fantasmagórica no Salão dos Thanes.", st = "O... Thane... meu poderoso... Thane... ele... precisa... descansar.\n\nPor favor... ajuda-o... ajuda-o a... descansar...\n\nConsumido... por... antiga... mágoa... Sem... descanso...", t = "Uma mágoa ancestral"},
    [96403] = {ot = "Colete $1oa Heranças Enânicas no Salão dos Thanes.", st = "Ei, você aí, $Gaventureiro:aventureira;! Preciso de uma ajudinha.\n\nEu estava me esgueiran... ahn, digo, patrulhando nos cofres quando uma tropa de anões Ferro Negro surgiu das profundezas em máquinas toupeiras! Céus, não sei o que eles querem por aqui, mas há saqu... quer dizer, heranças culturais inestimáveis lá embaixo! Por favorzinho, recupere qualquer relíquia que você encontrar e traga de volta para cá.\n\nGaranto a você que tudo que for recuperado vai ser catalogado e devolvido para o seu devido lugar de honra.", t = "Heranças importantes"},
    [96408] = {ot = "Investigue o acampamento acima da Pedreira Gol'Bolar.", st = "Ontem à noite, um dos nossos montanhistas avistou uma fogueira numa colina para o leste. Parece ficar bem no alto, com vista pra Pedreira Gol'Bolar.\n\nNão deve ser nada, mas eu queria que tu desse uma olhada naquele acampamento. Se forem amistosos, sem problema. Se não forem... bom, tu sabe o que fazer.", t = "Um visitante em Dun Morogh"},
    [96604] = {ot = "Sente-se perto da Fogueira Básica de Brakk e espere até receber um bônus de Descanso Melhorado.", st = "Lok-tar, $c. Vejo que você tem aparência de $Gaventureiro:aventureira;. Isso é bom. O mundo precisa de mais almas inquietas como nós, que buscam fortuna e glória.\n\nVocê precisará aprender a prosperar na natureza se quiser ter sucesso neste tipo de trabalho. Não conheço suas habilidades ao ar livre, mas posso ensinar uma coisinha ou outra, se quiser aprender.\n\nSente-se perto do fogo e fique à vontade. Vou explicar tudo.", t = "Vida ao ar livre"},
    [96605] = {ot = "Sente-se perto da Fogueira Básica de Kaja e espere até receber um bônus de Descanso Melhorado.", st = "Saudações, $c. Vejo que você tem a aparência de $Gaventureiro:aventureira;. Isso é bom. O mundo precisa de mais almas inquietas como nós, que buscam fortuna e glória.\n\nVocê precisará aprender a prosperar na natureza se quiser ter sucesso neste tipo de trabalho. Não conheço suas habilidades ao ar livre, mas posso ensinar uma coisinha ou outra, se você puder aprender.\n\nSente-se perto do fogo e fique à vontade. Vou explicar tudo.", t = "Vida ao ar livre"},
    [96606] = {ot = "Sente-se perto da Fogueira Básica de Lirena e espere até receber um bônus de Descanso Melhorado.", st = "Saudações, $c. Vejo que você tem aparência de $Gaventureiro:aventureira;. Isso é bom. O mundo precisa de mais almas inquietas como nós, que buscam fortuna e glória.\n\nVocê precisará aprender a prosperar na natureza se quiser ter sucesso neste tipo de trabalho. Não conheço suas habilidades ao ar livre, mas posso ensinar uma coisinha ou outra, se quiser aprender.\n\nSente-se perto do fogo e fique à vontade. Vou explicar tudo.", t = "Vida ao ar livre"},
    [96607] = {ot = "Sente-se perto da Fogueira Básica de Eleonora e espere até receber um bônus de Descanso Melhorado.", st = "Saudações, $c. Vejo que você tem a aparência de $Gaventureiro:aventureira;. Isso é bom. O mundo precisa de mais almas inquietas como nós, que buscam fortuna e glória.\n\nVocê precisará aprender a prosperar na natureza se quiser ter sucesso neste tipo de trabalho. Não conheço suas habilidades ao ar livre, mas posso ensinar uma coisinha ou outra, se você puder aprender.\n\nSente-se perto do fogo e fique à vontade. Vou explicar tudo.", t = "Vida ao ar livre"},
    [96608] = {ot = "Sente-se perto da Fogueira Básica de Éric e espere até receber um bônus de Descanso Melhorado.", st = "Saudações, $c. Vejo que você tem a aparência de $Gaventureiro:aventureira;. Isso é bom. O mundo precisa de mais almas inquietas como nós, que buscam fortuna e glória.\n\nVocê precisará aprender a prosperar na natureza se quiser ter sucesso neste tipo de trabalho. Não conheço suas habilidades ao ar livre, mas posso ensinar uma coisinha ou outra, se você puder aprender.\n\nSente-se perto do fogo e fique à vontade. Vou explicar tudo.", t = "Vida ao ar livre"},
    [96626] = {ot = "Fale com Tomás em Vila d'Ouro para aprender a cozinhar.", st = "Então você quer aprender mais sobre acampamento, é? Que bom, $c. O primeiro passo de qualquer aventureiro é se tornar um cozinheiro e aprender a fazer uma fogueira.\n\nCozinhar não se resume a fazer comida gostosa. Também é a base do seu acampamento.", t = "Introdução ao Acampamento: Cozinha"},
    [96627] = {ot = "Fale com Sam Salsaparrilha nos arredores de Vila d'Ouro.", st = "$n, você já provou sua competência como $Gprotetor:protetora;. É por isso que confio a você uma tarefa incomum.\n\nOuvi falar de um novo aventureiro pela estrada próximo a Vila d'Ouro. Vá até lá e veja o que ele está fazendo.", t = "O aventureiro"},
    [96628] = {ot = "Entregue o Pacote de Suprimentos a Éric Lumartelo, perto de Kharanos.", st = "Calma, $n. Tenho outra tarefa pra ti, antes de tu te embrenhar naquele túnel.\n\nMeus montanheiros informaram que um aventureiro apareceu nos arredores de Kharanos. Tem como tu entregar esses suprimentos pra ele?", t = "O aventureiro"},
    [96629] = {ot = "Fale com Gremlock Pilsnor em Kharanos para aprender a cozinhar.", st = "Então tu quer aprender mais sobre acampamento, é? Que bom, $c. O primeiro passo de qualquer aventureiro é se tornar um cozinheiro e aprender a fazer uma fogueira.\n\nCozinhar não se resume a fazer comida gostosa. Também é a base do teu acampamento.", t = "Introdução ao Acampamento: Cozinha"},
    [96630] = {ot = "Leve o diário para Lirena Gumúmbrio, perto de Dolanaar.", st = "<O diário parece ser bem simples, detalhando a vida e as aventuras de alguém de quem você nunca ouviu falar.\n\nHá vários registros mencionando acampamentos. Parece ser bem... divertido.>", t = "A aventureira"},
    [96634] = {ot = "Fale com Zarrin em Dolanaar para aprender a cozinhar.", st = "Então você quer aprender mais sobre acampamento, é? Que bom, $c. O primeiro passo de qualquer aventureiro é se tornar um cozinheiro e aprender a fazer uma fogueira.\n\nCozinhar não se resume a fazer comida gostosa. Também é a base do seu acampamento.", t = "Introdução ao Acampamento: Cozinha"},
    [96638] = {ot = "Fale com Raan Ventoferoz perto da Aldeia de Shen'dar.", st = "Mais e mais aventureiros como você têm buscado glória e fortuna fora da segurança do Bosque Thendal. Um desses aventureiros montou acampamento do lado de fora da Aldeia de Shen'dar, ao longo da estrada que leva para o sudoeste saindo do Bosque Thendal.\n\nProcure-o e veja o que você pode aprender com ele que possa lhe ajudar em suas próprias jornadas.", t = "O aventureiro"},
    [96646] = {ot = "Fale com Zerril Brisabranda na Aldeia de Shen'dar para aprender a cozinhar.", st = "Então você quer aprender mais sobre acampamento, é? Que bom, $c. O primeiro passo de qualquer aventureiro é se tornar um cozinheiro e aprender a fazer uma fogueira.\n\nCozinhar não se resume a fazer comida gostosa. Também é a base do seu acampamento.", t = "Introdução ao Acampamento: Cozinha"},
    [96652] = {ot = "Leve o diário para Brakk perto do Monte Navalha.", st = "<O diário parece ser bem simples, detalhando a vida e as aventuras de alguém de quem você nunca ouviu falar.\n\nHá vários registros mencionando acampamentos. Parece ser bem... divertido.>", t = "O aventureiro"},
    [96655] = {ot = "Fale com o Cozinheiro Torka no Monte Navalha para aprender a cozinhar.", st = "Então você quer aprender mais sobre acampamento, é? Que bom, $c. O primeiro passo de qualquer aventureiro é se tornar um cozinheiro e aprender a fazer uma fogueira.\n\nCozinhar não se resume a fazer comida gostosa. Também é a base do seu acampamento.", t = "Introdução ao Acampamento: Cozinha"},
    [96656] = {ot = "Fale com Eleonora Grilhões perto de Montalvo.", st = "$n, seus feitos contra a Cruzada Escarlate provaram que você merece a nossa confiança. É por isso que agora dou a você uma tarefa incomum.\n\nOuvi falar que há uma nova aventureira na estrada próximo a Montalvo. Vá até lá e veja o que ela está fazendo.", t = "O aventureiro"},
    [96658] = {ot = "Fale com William Pegome em Montalvo para aprender a cozinhar.", st = "Então você quer aprender mais sobre acampamento, é? Que bom, $c. O primeiro passo de qualquer aventureiro é se tornar um cozinheiro e aprender a fazer uma fogueira.\n\nCozinhar não se resume a fazer comida gostosa. Também é a base do seu acampamento.", t = "Introdução ao Acampamento: Cozinha"},
    [96659] = {ot = "Entregue o Pacote de Suprimentos a Kaja Casco Selvagem perto da Aldeia Casco Sangrento.", st = "Espere, $n. Tenho mais um pedido a fazer antes que você nos deixe.\n\nHá uma aventureira chamada Kaja Casco Selvagem que montou acampamento nos arredores da Aldeia Casco Sangrento. Ela me ajudou muito no passado, e agora vejo minha chance de retribuir. Poderia entregar estes suprimentos a ela?", t = "O aventureiro"},
    [96661] = {ot = "Fale com Pyall Passo Tranquilo na Aldeia Casco Sangrento para aprender a cozinhar.", st = "Então você quer aprender mais sobre acampamento, é? Que bom, $c. O primeiro passo de qualquer aventureiro é se tornar um cozinheiro e aprender a fazer uma fogueira.\n\nCozinhar não se resume a fazer comida gostosa. Também é a base do seu acampamento.", t = "Introdução ao Acampamento: Cozinha"},
    [96779] = {ot = "Encontre o Lorde Tomas dentro do Forte do Desterro, no Contraforte de Eira dos Montes, e mate-o. Depois, fale novamente com Mirokos Formassilente.", st = "Às vezes, $r, uma cortezinho no lugar certo ceifa a vida de um inimigo. O mesmo vale para organizações.\n\nNossos agentes identificaram um alvo-chave nas fileiras da Camarilha: um homem que atende pelo nome de Lorde Tomas.\n\nEle cumpre um papel primordial nas funções do Forte do Desterro, no Contraforte de Eira dos Montes. Se você quiser ajudar Corvoforte, vá até o Forte do Desterro e elimine-o. Quanto mais rápido e quanto menos alarde, melhor.", t = "Sabotagem na Camarilha"},
    [96821] = {ot = "Mate 6 Rastejantes Crista-sombra e 6 Tocaieiro Crista-sombra ao sul de Durotar e depois apresente-se a Gar'thok no Monte Navalha.", st = "Temos visto cada vez menos viajantes do Monte Navalha hoje em dia. Os escorpídeos nunca foram lá muito divertidos, mas agora tenho ouvido falar de aranhas fazendo ninho pela estrada.\n\nSe suas viagens $Go:a; levarem ao norte, mate algumas aranhas pelo caminho. Depois, avise ao Monte Navalha que a estrada está um pouco mais segura para eles.", t = "Dando no pé"},
    [96822] = {ot = "Colete o Machado de Batalha do Saqueador, o Arco do Saqueador e o Escudo do Saqueador da Bastilha Tiragarde nos arredores da Bastilha Tiragarde, depois devolva-os a Turroc no Monte Navalha.", st = "Perdemos muitos guerreiros valentes da Horda quando saqueamos a Bastilha Tiragarde. Agora que os humanos reforçaram as ruínas, não podemos coletar os restos mortais dos nossos soldados para honrar suas mortes adequadamente.\n\nVá para as ruínas que rodeiam a bastilha e procure as armas que nossos irmãos caídos deixaram para trás. Nós as exibiremos num lugar de honra.", t = "Pela honra"},
    [96825] = {ot = "O Cozinheiro Torka no Monte Navalha quer que você colete 8 Peras Espinhosas nas Terras Crinavalha a oeste da cidade.", st = "Os nossos caçadores e pescadores trazem muita comida salgada para as nossas tropas, mas é raro que consigam algo doce.\n\nEu vi um cacto que dá uma fruta espinhosa e bem suculenta. Mas ele só cresce nas colinas a oeste, onde aqueles javatuscos miseráveis montam seus assentamentos. Passe pelos javatuscos e traga algumas daquelas frutas. E tome cuidado: as frutas são tão espinhosas quanto os javatuscos!", t = "A fruta que fura"},
    [96873] = {ot = "Pa'zula na Aldeia Sen'jin quer que você colete 3 Resíduos Luminosos. Resíduos Luminosos podem ser obtidos ao desencantar Pingentes Bagateados largados por trolls nas Ilhas do Eco.", st = "Os trolls a leste daqui estão sob o domínio do mandingueiro Zalazane. Ele usa magias cruéis pra manter o controle da mente dos prisioneiros, mas um dos truques preferidos dele é fazer eles usarem colares envoltos em feitiços malignos de aprisionamento.\n\nTreina tuas habilidades de encantamento tirando a magia desses colares e me traz os resultados. E vê se não bota um no pescoço sem querer, se tu dá valor à tua liberdade!", t = "Uma dor no pescoço"},
    [96874] = {ot = "Ug'thok em Orgrimmar quer que você colete 5 Espinhas Desgastadas de feras no Desfiladeiro do Trovão, juntamente com 5 Pedras de Amolar Rústicas.", st = "Já viu as feras enormes que habitam o Desfiladeiro do Trovão? Eu vivo pensando que as espinhas delas dariam um belo cabeçote de machado. O Saru riu quando falei isso para ele... mas ele não sabe de nada!\n\nComo parte das suas lições de ferraria, me traga algumas dessas espinhas e também algumas pedras de amolar.", t = "Um machado de arrepiar a espinha"},
    [96875] = {ot = "Kamari em Orgrimmar quer que você colete 5 Pelegos Rústicos de Lagarto das feras no Desfiladeiro do Trovão, juntamente com 2 Pelegos Leves Curados.", st = "Orgrimmar está sempre crescendo, $c. E, quando os peões precisam de pelegos para revestir as paredes e telhados das nossas novas construções, eles vêm me procurar!\n\nOs pelegos dos lagartos do Desfiladeiro do Trovão são muito grossos para armadura, mas são muito bons para construir. Traga alguns desses pelegos, junto com alguns pelegos leves curados. Vamos ver sua habilidade na couraria!", t = "As feras do Desfiladeiro do Trovão"},
    [96876] = {ot = "Devolva a mochila para Ukor ao sul de Durotar.", st = "A mochila tem o nome \"Ukor\" costurado grosseiramente ao longo da aba.", t = "Mochila Perdida de Ukor"},
    [96877] = {ot = "Leve o Casco de Halikor para Orgrimmar.", st = "O enorme casco serve como prova da sua vitória sobre o poderoso lagarto.", t = "Casco de Halikor"},
    [96895] = {ot = "Encontre o membro da Aurora Argêntea perto da entrada da Cidade Baixa.", st = "Não sei se você soube, mas dois emissários da Aurora Argêntea acabaram de passar por aqui. Eu não ligo para a Aurora Argêntea, mas também não gosto dela sondando Tirisfal sem supervisão. Eram Renegados... mas não quer dizer que isso não me incomode.\n\nUm deles acabou de passar por aqui e foi para o sudeste. Há um grupo de sectários do Flagelo espreitando os arredores da cidade naquela direção. Se esses dois ficaram sabendo, com certeza essa informação chamou a atenção deles.", t = "O emissário argênteo"},
    [96896] = {ot = "Observe a conversa entre Danitha Morr e Leonid Bartolomeu, o Venerado.", st = "Eu e Danitha lutamos contra o Flagelo na defesa da Cidade Baixa quando Naxxramas atacou. Perdemos muitos bons amigos naquele dia, incluindo o herói cujo nome foi dado a esta bastilha — Garek Bandarion.\n\nEle pode muito bem ter sido o primeiro Renegado a reaprender a empunhar a Luz como paladino. Traz-me grande ânimo ver o legado e o potencial dele perdurando aqui com Danitha e sua coorte.\n\nAh, se os demais Renegados se sentissem da mesma forma...", t = "Uma causa íntegra"},
    [96897] = {ot = "Mate $1oa Neófitos Sombrios e $2oa Impositores Sombrios nas Clareiras de Tirisfal.", st = "O Flagelo é uma praga em nossas terras e seus servos viventes são o pior deles. O povo de Tirisfal já tem muito com que lidar entre os mortos desmiolados e a Cruzada Escarlate. Se quiser ser útil, me ajude a pôr um fim a essa escória.", t = "A Seita dos malditos"},
    [96898] = {ot = "Colete $1oa Fragmentos de Cristal Necrótico nas Clareiras de Tirisfal.", st = "Não faz muito tempo que a cidadela de Naxxramas sobrepujou esta cidade, com a intenção de apagar os Renegados do mapa. Tanto os Renegados quanto a Aurora Argêntea perderam muito naquele dia para garantir o futuro dos Renegados.\n\nDurante a batalha, o grande cristal de concentração necrótico montado no topo de Naxxramas foi estilhaçado e seus fragmentos foram espalhados por toda a área. Suspeito que seja por isso que os sectários estão aqui. Ajude-me a recuperar os fragmentos e privar o Flagelo deles.", t = "Vestígios da guerra"},
    [96899] = {ot = "Encontre Leonid Bartolomeu na Bastilha de Bandarion, nas Clareiras de Tirisfal.", st = "Sua ajuda foi de grande valia para a causa da Aurora Argêntea hoje, e por isso lhe sou grato. Não sei seu nível de familiaridade com a fortaleza da Bastilha de Bandarion, mas eu e meu comandante estávamos a caminho para encontrar os paladinos que vivem por lá. Isso foi antes de sabermos da presença da Seita dos Malditos.\n\nSe quiser saber mais sobre a Aurora Argêntea e nossa missão, procure pelo meu comandante na Bastilha de Bandarion, a noroeste daqui. Eu ficarei aqui para dar cabo do resto desta bagunça.", t = "Bastilha de Bandarion"},
    [96984] = {ot = "Colete a Partícula Arcana em Dalaran para Magus Ordínio Olharvazio na Serraria Tarren.", st = "Você pode não ter as melhores intenções para conosco, mas não vou recusar um par de mãos a mais. E se Dalaran cair, levará tudo consigo, incluindo a sua Cidade Baixa.\n\nEntão, seu benfeitor quer entrar? Tudo bem. Vou imbuir sua chave para que ela passe pelas minhas proteções e garanta sua entrada na cidade. Depois que entrar, me encontre na Cidadela Violeta onde tudo começou. Com tudo que está acontecendo, o Kirin Tor estará ocupado demais para deter você.\n\nSaqueie o que quiser, mas, aconteça o que acontecer, nossa prioridade é evitar uma catástrofe.", t = "No centro da instabilidade"},
    [96986] = {ot = "Derrote Atrexis, o Cavaleiro da Sepultura, em Dalaran para Melissara na Serraria Tarren.", st = "No esgoto da cidade dos magos, ao norte, há um traidor da nossa gente. Um necromante de talento perturbador. Ele está erguendo um exército de morte-viva bem debaixo do nariz do Kirin Tor.\n\nPouco me importa o destino da cidade dos magos, $n, mas esse cavaleiro da sepultura cospe na cara de tudo que nós, Renegados, representamos. Acabe com ele. Mostre que ninguém foge do alcance da Dama Sombria.", t = "O Cavaleiro da Sepultura"},
    [96987] = {ot = "Colete a Fundação de Dalaran, em Dalaran, para Rexxie Caçacobre perto da entrada do esgoto.", st = "Ora, ora, se não é $Gum colega empreendedor:uma colega empreendedora;. Entrando de fininho em Dalaran num momento tão delicado? Tsc tsc tsc.\n\nMeu tipo de $r!\n\nEnquanto nossos amigos magos tão ocupados, talvez a gente consiga achar uns tesouros \"perdidos\". Eles têm bibliotecas inteiras dedicadas a magia arcana chique. Se tu me descolar um daqueles tomos secretos, eu posso vender por uma bolada e dividir os lucros contigo.\n\nEi, não me olha assim, não! Tu também não veio aqui a passeio que eu sei. Tá dentro ou não tá?", t = "Pequenas bibliotecas, grandes negócios"},
    [96988] = {ot = "Colete $1oa Núcleos de Sentinela Rachados em Dalaran para o Doutor Martinho Nunes, na Cidade Baixa.", st = "Com Dalaran sob cerco de seus próprios constructos, essa é a oportunidade perfeita para, digamos, pegar algumas amostras emprestadas.\n\nImagine um exército de abominações movidas por poder arcano. A Dama Sombria não teria opção senão reconhecer meus talentos alquímicos. Quem sabe me nomear chefe da Real Sociedade de Boticários?\n\nVá até a cidade e procure o núcleo dos constructos. É improvável que os entreguem de boa vontade, então faça o que for preciso.", t = "Fonte de poder"},
    [97003] = {ot = "Leve a cabeça de Chol'aruk a Gur'ak nos Sertões.", st = "Você aí, $c. Preciso da sua ajuda. Tem boatos de uma fera que fez seu antro nas profundezas de uma caverna no Morro dos Espinhos, a nordeste daqui. Os Crinavalha a chamam de Chol'aruk, ou \"o Rapinante\". Dizem que ela é cinco vezes maior que um javatusco normal e que tem uma sede de sangue que não acaba nunca.\n\nAs pessoas não acreditam nessas histórias, mas eu, sim — porque já lutei com uma fera assim antes.\n\nProcure o antro de Chol'aruk e mate-o. Traga a cabeça dele. Mas saiba que é melhor você ir $Gpreparado e acompanhado:preparada e acompanhada;.\n\nSangue e trovão, $c.", t = "Chol'aruk, o Rapinante"},
    [97220] = {ot = "Leve o Carregamento da Portaria até a entrada do depósito, na Queijaria Trias, no Distrito Comercial.", st = "Faltaram estivadores todos os dias desta semana.\n\nQue tal nos ajudar a desafogar o cronograma de cargas?\n\nEntregue este pacote na entrada do depósito da Portaria. A entrada fica no segundo andar da Queijaria Trias. Elaine, a proprietária, já está acostumada com essas entregas. A Portaria costuma receber remessas discretas justamente para que os oficiais da guarda possam preparar surpresas cerimoniais sem estragar a ocasião.", t = "Um favor para Philmor"},
    [97222] = {ot = "Leve o Carregamento da Portaria escada acima na loja dos Trias e deixe-o na frente da porta.", st = "Sim, é só um lance de escadas, mas, se é uma tarefa tão simples, você não terá problemas para concluir a entrega por conta própria! \n\nQueijo de Trias não faz parte da Portaria nem do inventário de estoque deles, mas nossos prédios dividem um pavimento.\n\nColoque o caixote na porta do estoque. O guarda vai mandar alguém para fazer a coleta. Eles verão a chegada do pacote e o levarão para dentro quando retornam a seus postos.", t = "Mercadorias da Portaria"},
    [97223] = {ot = "Leve Ovos da Matriarca Garrassangre para Xar'Ti na Aldeia Sen'jin.", st = "Todos esses raptores que tu tá vendo fui eu que treinei. Eles são de todos os cantos de Kalimdor, mas alguns dos melhores vieram dos raptores Garrassangre nas ilhas perto da costa.\n\nTem um raptor entre eles, a Matriarca Garrassangre, que é muito selvagem e já matou muitos dos nossos aldeões. Ela é perigosa demais pra ficar dentro da nossa região. Se tu puder acabar com ela, traz os ovos pra cá pra gente criar os filhotes como aliados em vez de inimigos.", t = "Matriarca Garrassangre"},
    [97225] = {ot = "Colete $1oa Imagens de Loas Esquecidos nas Ilhas do Eco. Leve-os para o Mestre Gadrin na Aldeia Sen'jin.", st = "Quando a gente fugiu pras ilhas onde o Zalazane e o povo dele moram agora, a gente deixou vários ídolos importantes que nos ajudam a comungar com os nossos espíritos sagrados: os loas. Eles são muito importantes pra nossa tribo.\n\nOs seguidores do Zalazane não têm respeito pelos nossos loas e espalharam os ídolos por todas as ilhas.\n\nO pessoal vai notar se a gente não conseguir pegar esses ídolos, e ofender os loas é coisa séria.\n\nVai lá. Encontra o máximo dessas imagens de loas que puder e devolve elas pra mim.", t = "Imagens de loas esquecidos"},
    [97234] = {ot = "Leve o material de leitura embrulhado à Biblioteca de Ventobravo.", st = "Veio conversar sobre os significados ocultos das nossas lendas mais ilustres? Não?\n\nNesse caso, quando terminar de conhecer o clube, poderia levar isto à biblioteca para mim? Estamos substituindo algumas obras menos populares por leituras mais modernas. Tenho uma lista de tomos que a biblioteca certamente conseguirá providenciar dentro do nosso acordo atual.\n\nAjude-nos com isso, e os comes e bebes do clube ficam por nossa conta.", t = "Sala de leitura"},
    [97236] = {ot = "Entregue a Presa de Githyiss a alguém interessado no estudo de aranhas em Aldrassil.", st = "Um espécime fresco de uma fera desse tamanho é um achado e tanto. Talvez alguém em Aldrassil que se dedique ao estudo de aranhas se interesse pela presa.", t = "Presa de Gilthyiss"},
    [97237] = {ot = "Encontre todos os materiais de leitura espalhados pela biblioteca. Em seguida, fale novamente com Rui Lourenço no Parque de Ventobravo.", st = "Conferi nosso inventário, e todas as obras listadas pelo Sr. Lourenço estão disponíveis no momento.\n\nNo entanto, caberá a você retirá-las das estantes. Zelar pelo acervo faz parte do nosso dever; por isso, voltarei à supervisão dos registros.\n\nLevar o material de volta ao Rui em nome do clube não tornará você responsável pela devolução. Assim como no caso do bilhete, você atua apenas como mensageiro oficial do clube do livro. A responsabilidade ficará com o estabelecimento.\n\nTenha um bom dia, $n.", t = "Direto da estante"},
    [97242] = {ot = "Pegue algumas folhas de Taboa e Gramalança que crescem em volta da água no Vale da Honra e fale novamente com Kor'geld na Alquimia e Poções do Yelmak.", st = "Yelmak não quer seu aprendiz quebrando nada. Bom, nada além do que já quebrou.\n\nEle me disse que o jovem aprendiz de misturador é muito orgulhoso para pedir ajuda quando precisa. Yelmak quer dar a ele um gole de uma receita caseira especial.\n\nReúna uma mistura de taboa e gramalança retiradas da vegetação que cresce ao redor da água no Vale da Honra. Eu mesmo pegaria, mas, se eu deixar a loja, Uqueê certamente saberia que estamos cedendo aos caprichos dele.", t = "A mistura de Yelmak"},
    [97243] = {ot = "Leve a Tocha da Chama Latente a Olariaan Queimabreve no Santuário das Chamas, nos Baixios dos Lufopomos.", st = "Embora estejamos no reino da Muralha Celeste, ainda é o plano elemental. Os espíritos de todos os quatro elementos falam conosco, caso nos dignemos a ouvi-los. Um de nossos Moldavento tem uma afinidade especial com o elemento do fogo. É um shen'dorei chamado Olariaan Queimabreve.\n\nLeve esta tocha a ele no Santuário das Chamas, nos Baixios dos Lufopomos. Você encontra o santuário perto da orla da ilha, a oeste de Valanaar.", t = "Clamor do fogo"},
    [97244] = {ot = "Mate o Sacerdote do Céu Faladiel nos Baixios dos Lufopomos e colete o Coração de Faladiel.", st = "Tem um sacerdote do céu Al'Aketh chamado Faladiel. Ele foi arauto do fogo e também um Moldavento determinado. Como muitos Al'Aketh, vendeu a lealdade por poder e agora está com as mãos manchadas do sangue de seus antigos irmãos.\n\nVocê encontra o Sacerdote do Céu Faladiel na fazenda a nordeste de Valanaar, logo ao sul do Santuário de Akir. Mate o traidor e traga o coração dele. É uma tarefa macabra, mas necessária para o ritual que vamos realizar.", t = "Clamor do fogo"},
    [97245] = {ot = "Encontre o lar de Kuramaa no Planalto de Shen'dar e derrote o espírito em combate. Leve a Máscara de Kuramaa a Olariaan Queimabreve nos Baixios dos Lufopomos depois de vencer.", st = "Os moradores do Planalto de Shen'dar falam de um duende da floresta antigo de nome Kuramaa. Dizem que ele mora dentro de um toco retorcido no cume de um morro, perto do pilar de ancoragem do planalto.\n\nVá até o planalto e encontre esse toco. Batuque na casca para fazer Kuramaa aparecer. Vença o espírito em combate e traga a máscara de madeira dele.\n\nMas esteja $Gavisado:avisada; que essa entidade apresentará uma resistência excepcional à maioria das suas magias. Só o toque do fogo será capaz de aplacar o espírito.", t = "Clamor do fogo"},
    [97246] = {ot = "Visite a Fogueira de Borsgan e diga a ele que Thatog pediu para que você entregue o Almoço de Migi ao garoto pessoalmente.", st = "Meu filho Migi sempre sai para brincar com os amigos o dia todo. Eu digo a ele para buscar o almoço com o Borsgan, mas eu sei que ele quase nunca faz isso, porque ele volta para casa faminto. Essas crianças acham que as brincadeiras são mais importantes que os próprios corpos!\n\nVou pedir que você passe na Fogueira de Borsgan e diga a ele que foi levar o almoço do Migi. É quase certo que você encontre o Migi atrás do Castelo Grommash com o resto dos amigos dele.\n\nOs deveres me prendem aqui durante o dia e eu não posso vigiar todas as refeições dele.", t = "A marmita do Migi"},
    [97249] = {ot = "Leve o Almoço de Migi para ele atrás do Castelo Grommash.", st = "Agora que eu sei que os pais dele se preocupam com o que ele está botando no estômago, eu tive uma ideia.\n\nEles me fizeram prometer que não ia a mesma refeição todo dia, para que o Migi aprenda a comer coisas diferentes. Mesmo assim, sempre que o defumador está cheio e fazemos sanduíches de barriga de porco caramelizada, ele sempre aparece para o almoço. Começamos a esfarelar os restos doces e crocantes como cobertura, e dá para incluir isso todo dia.\n\nLeve isto para ele. Talvez ele comece a aparecer cedo e a trazer amigos!", t = "Comida preferida"},
    [97250] = {ot = "Mate soldados da Aliança que se aproximam dos Sertões na fronteira do Pântano Vadeoso e depois fale novamente com o Bruto Logmar no Acampamento Taurajo.", st = "Viajante, você tem planos de seguir rumo ao Pântano Vadeoso? Eu ouvi boatos de que alguns soldados humanos se posicionaram na fronteira de lá e que estão derrubando marcos que os desbravadores taurens deixaram.\n\nDizem por aí que uma taberna muito querida foi reduzida a cinzas e, como é de costume na Aliança, eles logo botaram a culpa na Horda! Não tenho como saber se há alguma verdade nisso, mas a incursão deles em NOSSAS terras tem que parar.\n\nMate primeiro e investigue depois!", t = "Culpa errônea justamente corrigida"},
    [97253] = {ot = "Colete $1oa Punhados de Peças Complicadas do acampamento pirata superior, ao sul da Vila Catraca, e depois fale novamente com Wrenix, o Ignóbil, na Vila Catraca.", st = "Ei, você tem um minuto?\n\nEntão, ao que parece, ninguém que eu mandei pra dar um jeito no problema recente com os piratas voltou vivo. Depois de cinco ou seis tentativas, eu pensei: \"E se eu mandasse uma máquina no lugar das pessoas?\" No fim das contas, parece que, se você tá num aperto, dá pra usar cimitarra como chave de fenda. Antes que eu pudesse redirecionar a máquina pra casa, ela já tava toda desmontada e espalhada pelo acampamento deles!\n\nEu preciso das peças de volta e, já que é uma missão rápida de resgate, aposto que a sua chance de sobreviver é MUITO maior que a dos outros. O que me diz?", t = "Peças e pedaços"},
    [97257] = {ot = "Espere Olariaan iniciar o ritual no Braseiro da Oferenda e siga as instruções dele.\n\nVocê precisa levar a Chama Eterna a Valanaar antes que o tempo se esgote.", st = "Agora vamos realizar o ritual. \n\nVou colocar os materiais no altar e evocar os espíritos das chamas. Se a oferenda for aceita, eles aparecerão para acender a Chama Eterna. Depois, erga a tocha e capture a chama.\n\nLeve a tocha acesa até Valanaar e coloque-a no Braseiro das Chamas Eternas. Não se demore, pois as chamas das Terras do Fogo se dissipam rápido aqui na Muralha Celeste.", t = "Clamor do fogo"},
    [97275] = {ot = "Dê a Poção de Yelmak a Uqueê.", st = "Uqueê é um prodígio. Isso é verdade. Mas ele ainda não tem a experiência, a sabedoria e o tempo com o pistilo para saber respeitar os processos alquímicos.\n\nEle está esgotando todos os reagentes mais raros e exóticos que temos sem fazer uma pausa para praticar e refinar as habilidades básicas.\n\nDê a ele esta poção que eu preparei com um método de tônico rápido. Ele vai reconsiderar tudo o que está fazendo quando aprender que os remédios locais e um pouco de cuidado são a primeira verdadeira maestria.", t = "Por Uqueê a pressa?"},
    [97277] = {ot = "Ache o acampamento de Grund e Gozwin nas colinas a noroeste. Recupere o Registro de Mecânico de Gozwin e mate o Leopardo da Neve Predador.", st = "Bah, eu tava de costas fazendo um javali assado quando meu amigo Gozwin começou a se esgoelar de medo!\n\nNo que eu me viro, só vejo uns dentes escabrosas e um borrão. Umas patas enormes! Um leopardo da neve tava levando a presa gnômica. Eu só passei a mão na escopeta e dei um tiro pro alto, e o bicho saiu zunindo.\n\nAinda bem que o Goz só ficou com uns cortes.\n\nFaz o favor de voltar pro acampamento nas colinas a noroeste e pegar de volta o Registro de Mecânico de Gozwin. E mata o leopardo da neve se topar com ele!", t = "Grund e Gozwin"},
    [97279] = {ot = "Colete $1oa Armas de Treino Abandonadas e vá até Kzan Cortarrasga, no Covil.", st = "Com a chegada de novos recrutas como você, tem sido difícil manter o suprimento de armas. Nosso artesão de armas, Kzan, está ficando sem armas de treino, e eu gostaria de conhecer melhor as suas habilidades, para saber como elas podem ser úteis. Felizmente, tenho uma solução para ambos os problemas.\n\nEnquanto estiver atrás de javalis por aí, recupere seis armas de treino abandonadas. Foram largadas pelos nossos recrutas menos competentes. Quando cumprir a tarefa, devolva-as ao artesão de armas Kzan, no Covil, ali atrás.", t = "Armas extraviadas"},
    [97281] = {ot = "Leve o Orbe da Tempestade Opaco para Rezlak perto do Barranco da Ravina Seca.", st = "<Há um orbe de superfície opaca diante de você. Quando você o pega, uma pequena corrente elétrica parece vibrar dentro dele. Ao inspecioná-lo, parece que uma névoa sombria rodopia em seu interior, e só uma pequena fagulha elétrica é visível.\n\nCertamente a harpia estava usando ele por algum motivo. Será que Rezlak estaria interessado neste objeto?>", t = "Uma tempestade se formando"},
    [97282] = {ot = "Leve $1oa Órgãos de Lagarto Trovejante Carregados para Rezlak perto do Barranco da Ravina Seca.", st = "\"Rezlak, quando uma oportunidade aparece, a gente tem que aproveitar.\" Essa era mais uma lição que o Gasganete me ensinou, e é isso que eu vou fazer.\n\nParece que esse orbe tá intacto, só tá sem energia, mas eu vou dar um jeito de carregar ele pra ficar com força total!\n\nTem um bando de lagartos trovejantes numa gorja a oeste daqui. Eles têm uns órgãos que soltam uma descarga elétrica daquelas, e é disso que eu o orbe tá precisando.\n\nVai lá pegar alguns deles e traz pra mim!", t = "Potencial trovejante"},
    [97287] = {ot = "Fale com a Arquimaga Celindra em Dalaran.", st = "Você fez um bom trabalho ao se infiltrar na cidade dos magos, mas creio que chegou a hora de sermos mais... pragmáticos.\n\nPor mais que me doa admitir, não há outro lugar em Azeroth com tamanho conhecimento do arcano. Meu trabalho brilhante nem se compara à sabedoria ancestral que o Kirin Tor acumulou ao longo dos anos. Acho que já passou da hora de nos concederem acesso a essa ordem exclusiva, não acha?\n\nLeve o grânulo que você adquiriu. Eles certamente dariam qualquer coisa para tê-lo de volta. Qualquer coisa.", t = "Negociações arguciosas"},
    [97288] = {ot = "Entregue a Cabeça Abominável ao Mestre-boticário Faranello na Cidade Baixa.", st = "<À medida que a criatura tomba, a cabeça dela se desprende. Parece que já foi recolocada várias vezes, e a ligação se enfraquece a cada vez que isso se repete.\n\nAlguém na Cidade Baixa deve saber mais sobre uma abominação tão peculiar.>", t = "Tormento sem fim"},
    [97289] = {ot = "Leve a Cabeça do Barão ao corpo de Othmar na Cidade Baixa.", st = "Criar cabeças de abominação por aqui é coisa corriqueira, mas esta é especial. Pertenceu a um Grão-marechal da Aliança — um particularmente detestável, diga-se de passagem. Creio que seu nome era Othmar. A Dama Sombria teve o prazer de dar cabo dele com as próprias mãos.\n\nAh, os segredos que ela revelaria se pudesse falar... E pode! Basta ligá-la a um hospedeiro adequado.\n\nColoque-a no corpo disponível na sala ao lado. Mas não faça a ligação. Não ainda.", t = "Tormento sem fim"},
    [97290] = {ot = "Relate suas descobertas ao Mestre-boticário Faranello na Cidade Baixa.", st = "Você... abominação...\n\nPor que... ajudar você...\n\nVá embora...", t = "Tormento sem fim"},
    [97291] = {ot = "Obtenha um Morrião Tóxico com Clorinda Grisette no Distrito Comercial, Pustulerva perto do local de Treinamento de Herborismo, e Essência da Agonia com o comerciante de venenos no Distrito dos Ladinos para entregar ao Mestre-boticário Faranello na Cidade Baixa.", st = "Com a cabeça devolvida ao lugar, só o que falta é submetê-la à vontade da Dama Sombria, o que não deve ser problema. Mal se pode dizer que a fera ainda tem cérebro, depois de todas as pancadas que levou.\n\nSó precisamos lhe oferecer uma motivação.\n\nProvidencie para mim um morrião tóxico com a Srta. Grisette, no Distrito Comercial. Ah, pustulerva com as treinadoras herboristas locais, as Basílico. Elas me devem, então pode apanhar as plantas à vontade. Por fim, um pouco de essência da agonia, que é coisa que se encontra em qualquer loja de venenos.\n\nTemos uma poção a preparar!", t = "Tormento sem fim"},
    [97292] = {ot = "Injete Soro Sibilante nos mecanismos sobre o corpo de Othmar para o Mestre-boticário Faranello.", st = "Preparei um soro maravilhoso que nosso convidado certamente achará muito... estimulante.\n\nPegue e despeje no mecanismo que goteja sobre ele. Vamos mostrar a ele que lhe convém servir com lealdade.\n\nE não deixe cair, porque vai ser difícil achar um outro assistente.", t = "Tormento sem fim"},
    [97326] = {ot = "Leve $1oa Pedregulhos Lisos para Thra atrás do Castelo Grommash.", st = "Ei! Você tem tempo pra ajudar a gente! Eu sei que tem porque eu vi o jeito que você sorriu enquanto tava vendo a gente brincando.\n\nEsse lugar atrás do Castelo Grommash é legal porque é limpo pra gente arrumar os bonequinhos. Mas o chato é que a gente não tem pedra suficiente pra usar de cadeira ou mesa.\n\nVocê, que é grande e forte... acha que consegue trazer umas pedras médias, lisinhas o bastante pra gente sentar se precisar descansar?", t = "Pedra pra sentar"},
    [97485] = {ot = "Compre um Maço de Ervas com Nida, a herborista, um Maço de Galhos de Cedro com Nata, a fornecedora de encantamento, Fio de Tendão com Mahu, o fornecedor de couraria, e Pederneira e Lenhas Cerimoniais com Naal, o fornecedor de culinária.\n\nCombine os itens e espalhe o incenso do Platô dos Caçadores.", st = "Que An'she te abençoe, $Gamigo:amiga;.\n\nNós taurens temos uma tradição de espalhar incenso pelos ventos, e gostaria de saber se você teria interesse em honrar essa tradição.\n\nSerá necessário criar o incenso comprando ervas com a Nida, cedro com a Nata, fio de tendão com o Mahu no platô intermediário, e pederneira e lenha cerimoniais com o Naal no platô superior. Assim que tiver esses itens, combine-os e espalhe-os lá do penhasco voltado para o sul do Platô dos Caçadores.\n\nVocê encontra um tapete e incenso no local cerimonial.", t = "Tradições do Penhasco"},
    [97538] = {ot = "Tah Casco Invernal, no Penhasco do Trovão, deseja $1oa Vagens de Erva-turva do Lago Mirkfallon.", st = "Saudações, $Gamigo:amiga;. Será que eu poderia lhe pedir um favor? Acabei de ficar sem pigmento vermelho para as minhas tintas, e preciso de alguém com cascos mais jovens para fazer a longa viagem até a Cordilheira das Torres de Pedra por mim.\n\nNo meio da passagem da montanha há um grande lago circular, o Lago Mirkfallon, que abriga uma planta única em suas águas. As vagens dessa planta, a erva-turva, ficam de um vermelho vibrante quando secas. Colete as vagens para mim, e será bem $Grecompensado:recompensada; pelos seus esforços.", t = "Pigmento para tinta"},
    [97558] = {ot = "Leve $1oa Membranas de Asa de Quiropúsculo, $2oa Pelego de Cão das Trevas e $3oa Pele de Murloc Pinavil para Lenita Ravais.", st = "Há uma coisa sobre a morte-viva que ninguém menciona: o que acontece quando nos ferimos. Como a pele de um morto-vivo cicatriza?\n\nBem, ela não cicatriza.\n\nVivemos uma existência amaldiçoada, $n. Precisamos tirar dos vivos aquilo que prolonga a nossa existência.\n\nQuando nos ferimos, precisamos substituir nossa pele. Na falta de algo melhor, recorremos a couros de animais. Como cada parte do corpo pede uma espessura diferente, a variedade é essencial!\n\nTraga-me membranas de asa de quiropúsculo, pelegos de cão das trevas e pele de murloc Pinavil.", t = "Pelegos para os Renegados"},
    [97891] = {ot = "Leve a Poção Instável ao Doutor Martinho Nunes, no Boticarium, dentro do tempo estipulado.", st = "Você! Depressa, preciso que leve esta poção ao Doutor Martinho Nunes, no Boticarium, que fica do outro lado do canal de visgo!\n\nO prazo de validade dela é curtíssimo, e eu não consigo ir rápido. Quando tento correr, meus joelhos crepitam feito dois chocalhos e caem.\n\nO que não passa de um efeito colateral da morte-viva.\n\nMas o tempo urge! Aqui está a poção, vá de uma vez!\n\n<Alessandro dispensa você com um gesto.>", t = "Entrega expressa de poções"},
    [97899] = {ot = "Fale com Uqueê em Orgrimmar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Então você decidiu ser Alquimista e preparar bebidas e poções. Com certeza será útil em suas viagens.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar seu próprio poço de mana para o seu acampamento. Construa um desses, que todos os tipos de curadores e lançadores de feitiços virão correndo para ter um gostinho.", t = "Introdução ao acampamento: Alquimia"},
    [97900] = {ot = "Fale com Dwukk no Monte Navalha para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Bom, agora você é $Gum ferreiro:uma ferreira;. Ótima escolha se quiser lâminas sempre afiadas.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar uma roda de afiar. Coloque uma dessas em seu acampamento, que todos os guerreiros e ladinos na área farão fila para afiar as armas.", t = "Introdução ao acampamento: Ferraria"},
    [97901] = {ot = "Fale com Jhag em Orgrimmar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Encantadores deixam tudo melhor e são sempre bem-vindos em qualquer acampamento na natureza.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar um alaúde encantado para o seu acampamento. É muito importante se divertir durante o ócio, e esse pouquinho de magia pode ajudar você a se preparar para suportar todo tipo de desafio quando pegar a velha estrada poeirenta de novo.", t = "Introdução ao acampamento: Encantamento"},
    [97902] = {ot = "Fale com Mukdrak no Monte Navalha para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "$GEngenheiros:Engenheiras; como você conseguem preparar todo tipo de bomba e bugiganga só por lucro e diversão.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar um robô de reagentes para o seu acampamento. Esse autômato prestativo pode cuidar do seu estoque para você e os seus aliados nunca ficarem sem os materiais necessários pra ativar os feitiços.", t = "Introdução ao acampamento: Engenharia"},
    [97903] = {ot = "Fale com Rawrk no Monte Navalha para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Então você assumiu os primeiros socorros? É uma empreitada muito respeitável e... pragmática, sendo você $Gum:uma; $c.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar um kit de primeiros socorros para o seu acampamento. As lesões acontecem no mundo das aventuras, e oferecer a tão necessária cura em seu acampamento pode até salvar vidas.", t = "Introdução ao acampamento: Primeiros Socorros"},
    [97904] = {ot = "Fale com Lau'Tiki perto da Aldeia Sen'jin para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Talvez você não acredite, mas a habilidade com pesca pode ser muito útil no acampamento.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar um aquário para o seu acampamento. Use esse dispositivo para dar um pouco mais de alegria a si $Gmesmo:mesma; e aos colegas aventureiros. Um aventureiro feliz é um aventureiro forte, e tenho certeza de que sua capacidade em combate refletirá isso.", t = "Introdução ao acampamento: Pesca"},
    [97905] = {ot = "Fale com Jandi em Orgrimmar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Estou notando que você andou praticando o herborismo. Colher flores não é uma perda de tempo. Pode ser útil... e lucrativo.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar uma vela de incenso para o seu acampamento. O moral elevado é um componente importante para manter curadores e lançadores de feitiço na luta, e uma vela de incenso pode dar um reforço que os usuários de magia vão apreciar.", t = "Introdução ao acampamento: Herborismo"},
    [97906] = {ot = "Fale com Karolek em Orgrimmar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Você se tornou $Gcoureiro:coureira;. Que bom, $c. Acho que eu conheço alguém que pode lhe ensinar a criar uma tenda que deixará você $Gfresco:fresca; em dias quentes, e $Gseco:seca; em dias chuvosos.\n\nCom uma boa tenda sobre a cabeça, você terá todo o descanso necessário para ficar firme em suas viagens.", t = "Introdução ao acampamento: Couraria"},
    [97907] = {ot = "Fale com Krunn no Monte Navalha para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Mineração não é lá uma coisa muito glamorosa, mas é um trabalho honesto e uma ótima profissão para você se aventurar.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar uma magnetita para o seu acampamento. Crie uma dessas e qualquer um que queira brandir uma espada vai adorar ficar ao redor da sua fogueira para aproveitar aquele \"tchan\" que ela dá, aumentando a capacidade de combate de todos.", t = "Introdução ao acampamento: Mineração"},
    [97908] = {ot = "Fale com Thuwd em Orgrimmar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Saber coletar com maestria as peles e os pelegos de feras abatidas é uma das habilidades mais úteis que um aventureiro pode ter.\n\nAcho que eu conheço alguém que pode te ensinar a criar uma cadeira de acampamento. Às vezes, é importante descansar um pouco, e você pode usar as peles que coletou para fazer uma cadeira confortável. Um pouquinho de relaxamento ajuda a deixar você em ótima forma para que consiga desferir o golpe certeiro na próxima vez que se meter em uma briga.", t = "Introdução ao acampamento: Esfolamento"},
    [97914] = {ot = "Leve a Carta de Trovejius para Baros Aleixo em Ventobravo.\n\nTrovejius falou sobre um barco em Auberdine que pode levar você até lá.", st = "Auberdine é um lugar simples, $c. Você não ouvirá menção a esse nome no dossel de Darnassus. Só se fala daquilo que a Cisão nos arrancou — as cidades prósperas de Ameth'Aran, Bashal'Aran e... Lathar'Lazal.\n\nNo entanto, Auberdine continua na sombra delas.\n\nQueria muito que o nosso trabalho fosse reconhecido. Uma nova embarcação nos liga ao reino de Ventobravo, trazendo vida e suprimentos à nossa costa. Peço que apanhe a embarcação e leve essa carta a um humano chamado Baros Aleixo.\n\nFaça com que conheçam a nossa terra natal.", t = "Novos horizontes"},
    [97915] = {ot = "Fale com o Alquimista Malheiro na Floresta de Elwynn perto de Ventobravo para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Então você decidiu ser Alquimista e preparar bebidas e poções. Com certeza será útil em suas viagens.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar seu próprio poço de mana para o seu acampamento. Construa um desses, que todos os tipos de curadores e lançadores de feitiços virão correndo para ter um gostinho.", t = "Introdução ao acampamento: Alquimia"},
