    [97923] = {ot = "Fale com Gelman Manopedra em Ventobravo para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Mineração não é lá uma coisa muito glamorosa, mas é um trabalho honesto e uma ótima profissão para você se aventurar.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar uma magnetita para o seu acampamento. Crie uma dessas e qualquer um que queira brandir uma espada vai adorar ficar ao redor da sua fogueira para aproveitar aquele \"tchan\" que ela dá, aumentando a capacidade de combate de todos.", t = "Introdução ao acampamento: Mineração"},
    [97924] = {ot = "Fale com Helene Esfoladora em Vila d'Ouro para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Saber coletar com maestria as peles e os pelegos de feras abatidas é uma das habilidades mais úteis que um aventureiro pode ter.\n\nAcho que eu conheço alguém que pode te ensinar a criar uma cadeira de acampamento. Às vezes, é importante descansar um pouco, e você pode usar as peles que coletou para fazer uma cadeira confortável. Um pouquinho de relaxamento ajuda a deixar você em ótima forma para que consiga desferir o golpe certeiro na próxima vez que se meter em uma briga.", t = "Introdução ao acampamento: Esfolamento"},
    [97925] = {ot = "Fale com Elgin na Madeireira Vale do Leste, que fica na Floresta de Elwynn, para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Pode te surpreender, mas a alfaiataria é um ofício muito potente para investir, e com certeza tem tudo a ver com você.\n\nConheço alguém que pode lhe ensinar a criar um estandarte de facção para o seu acampamento, caso você tenha a perícia adequada. Inspiração e moral são cruciais para o sucesso em qualquer batalha, e um estandarte inspirador faz milagres quando se trata de deixar você com os ânimos lá em cima.", t = "Introdução ao acampamento: Alfaiataria"},
    [97927] = {ot = "Fale com Kray no Penhasco do Trovão para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Então você decidiu ser Alquimista e preparar bebidas e poções. Com certeza será útil em suas viagens.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar seu próprio poço de mana para o seu acampamento. Construa um desses, que todos os tipos de curadores e lançadores de feitiços virão correndo para ter um gostinho.", t = "Introdução ao acampamento: Alquimia"},
