    [97936] = {ot = "Fale com Yonn Corte Profundo na Aldeia Casco Sangrento para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Saber coletar com maestria as peles e os pelegos de feras abatidas é uma das habilidades mais úteis que um aventureiro pode ter.\n\nAcho que eu conheço alguém que pode te ensinar a criar uma cadeira de acampamento. Às vezes, é importante descansar um pouco, e você pode usar as peles que coletou para fazer uma cadeira confortável. Um pouquinho de relaxamento ajuda a deixar você em ótima forma para que consiga desferir o golpe certeiro na próxima vez que se meter em uma briga.", t = "Introdução ao acampamento: Esfolamento"},
    [97937] = {ot = "Fale com Vhan no Penhasco do Trovão para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Pode te surpreender, mas a alfaiataria é um ofício muito potente para investir, e com certeza tem tudo a ver com você.\n\nConheço alguém que pode te ensinar a criar um estandarte de facção para o seu acampamento, caso você tenha a perícia adequada. Inspiração e moral são cruciais para o sucesso em qualquer batalha, e um estandarte inspirador faz milagres quando se trata de deixar você com os ânimos lá em cima.", t = "Introdução ao acampamento: Alfaiataria"},
    [97938] = {ot = "Fale com Cyndra Murmuramável em Dolanaar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Então você decidiu ser Alquimista e preparar bebidas e poções. Com certeza será útil em suas viagens.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar seu próprio poço de mana para o seu acampamento. Construa um desses, que todos os tipos de curadores e lançadores de feitiços virão correndo para ter um gostinho.", t = "Introdução ao acampamento: Alquimia"},
    [97939] = {ot = "Fale com Elisa Manácero em Auberdine, na Costa Negra, para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Bom, agora você é $Gum ferreiro:uma ferreira;. Ótima escolha se quiser lâminas sempre afiadas.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar uma roda de afiar. Coloque uma dessas em seu acampamento, que todos os guerreiros e ladinos na área farão fila para afiar as armas.", t = "Introdução ao acampamento: Ferraria"},
    [97940] = {ot = "Fale com Aline Corvolhar na Clareira do Oráculo, em Teldrassil, para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Encantadores deixam tudo melhor e são sempre bem-vindos em qualquer acampamento na natureza.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar um alaúde encantado para o seu acampamento. É muito importante se divertir durante o ócio, e esse pouquinho de magia pode ajudar você a se preparar para suportar todo tipo de desafio quando pegar a velha estrada poeirenta de novo.", t = "Introdução ao acampamento: Encantamento"},
    [97941] = {ot = "Fale com Jenna Lemkenilli em Auberdine, na Costa Negra, para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "$GEngenheiros:Engenheiras; como você conseguem preparar todo tipo de bomba e bugiganga só por lucro e diversão.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar um robô de reagentes para o seu acampamento. Esse autômato prestativo pode cuidar do seu estoque para você e os seus aliados nunca ficarem sem os materiais necessários pra ativar os feitiços.", t = "Introdução ao acampamento: Engenharia"},
    [97942] = {ot = "Fale com Byonsa em Dolanaar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Então você assumiu os primeiros socorros? É uma empreitada muito respeitável e... pragmática, sendo você $Gum:uma; $c.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar um kit de primeiros socorros para o seu acampamento. As lesões acontecem no mundo das aventuras, e oferecer a tão necessária cura em seu acampamento pode até salvar vidas.", t = "Introdução ao acampamento: Primeiros Socorros"},
    [97943] = {ot = "Fale com Astaia em Darnassus para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Talvez você não acredite, mas a habilidade com pesca pode ser muito útil no acampamento.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar um aquário para o seu acampamento. Use esse dispositivo para dar um pouco mais de alegria a si $Gmesmo:mesma; e aos colegas aventureiros. Um aventureiro feliz é um aventureiro forte, e tenho certeza de que sua capacidade em combate refletirá isso.", t = "Introdução ao acampamento: Pesca"},
    [97944] = {ot = "Fale com Malorne Folhâmina em Dolanaar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Estou notando que você andou praticando o herborismo. Colher flores não é uma perda de tempo. Pode ser útil... e lucrativo.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar uma vela de incenso para o seu acampamento. O moral elevado é um componente importante para manter curadores e lançadores de feitiço na luta, e uma vela de incenso pode dar um reforço que os usuários de magia vão apreciar.", t = "Introdução ao acampamento: Herborismo"},
    [97946] = {ot = "Fale com Nadyia Tecegrenhas na estrada que vai de Dolanaar a Darnassus para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Você se tornou $Gcoureiro:coureira;. Que bom, $c. Acho que eu conheço alguém que pode lhe ensinar a criar uma tenda que deixará você $Gfresco:fresca; em dias quentes, e $Gseco:seca; em dias chuvosos.\n\nCom uma boa tenda sobre a cabeça, você terá todo o descanso necessário para ficar firme em suas viagens.", t = "Introdução ao acampamento: Couraria"},
    [97948] = {ot = "Fale com Kordram Rochamalho em Auberdine para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Mineração não é lá uma coisa muito glamorosa, mas é um trabalho honesto e uma ótima profissão para você se aventurar.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar uma magnetita para o seu acampamento. Crie uma dessas e qualquer um que queira brandir uma espada vai adorar ficar ao redor da sua fogueira para aproveitar aquele \"tchan\" que ela dá, aumentando a capacidade de combate de todos.", t = "Introdução ao acampamento: Mineração"},
    [97949] = {ot = "Fale com Radnaal Tecegrenhas na estrada que vai de Dolanaar a Darnassus para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Saber coletar com maestria as peles e os pelegos de feras abatidas é uma das habilidades mais úteis que um aventureiro pode ter.\n\nAcho que eu conheço alguém que pode te ensinar a criar uma cadeira de acampamento. Às vezes, é importante descansar um pouco, e você pode usar as peles que coletou para fazer uma cadeira confortável. Um pouquinho de relaxamento ajuda a deixar você em ótima forma para que consiga desferir o golpe certeiro na próxima vez que se meter em uma briga.", t = "Introdução ao acampamento: Esfolamento"},
    [97950] = {ot = "Fale com Trianna em Darnassus para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Pode te surpreender, mas a alfaiataria é um ofício muito potente para investir, e com certeza tem tudo a ver com você.\n\nConheço alguém que pode lhe ensinar a criar um estandarte de facção para o seu acampamento, caso você tenha a perícia adequada. Inspiração e moral são cruciais para o sucesso em qualquer batalha, e um estandarte inspirador faz milagres quando se trata de deixar você com os ânimos lá em cima.", t = "Introdução ao acampamento: Alfaiataria"},
