    [97971] = {ot = "Fale com Mendalass Emendarrapo na Aldeia de Shen'dar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Saber coletar com maestria as peles e os pelegos de feras abatidas é uma das habilidades mais úteis que um aventureiro pode ter.\n\nAcho que eu conheço alguém que pode te ensinar a criar uma cadeira de acampamento. Às vezes, é importante descansar um pouco, e você pode usar as peles que coletou para fazer uma cadeira confortável. Um pouquinho de relaxamento ajuda a deixar você em ótima forma para que consiga desferir o golpe certeiro na próxima vez que se meter em uma briga.", t = "Introdução ao acampamento: Esfolamento"},
    [97972] = {ot = "Fale com Taleen Cintilinha na Aldeia de Shen'dar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Pode te surpreender, mas a alfaiataria é um ofício muito potente para investir, e com certeza tem tudo a ver com você.\n\nConheço alguém que pode te ensinar a criar um estandarte de facção para o seu acampamento, caso você tenha a perícia adequada. Inspiração e moral são cruciais para o sucesso em qualquer batalha, e um estandarte inspirador faz milagres quando se trata de deixar você com os ânimos lá em cima.", t = "Introdução ao acampamento: Alfaiataria"},
    [97973] = {ot = "Fale com Taleen Cintilinha na Aldeia de Shen'dar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Pode te surpreender, mas a alfaiataria é um ofício muito potente para investir, e com certeza tem tudo a ver com você.\n\nConheço alguém que pode te ensinar a criar um estandarte de facção para o seu acampamento, caso você tenha a perícia adequada. Inspiração e moral são cruciais para o sucesso em qualquer batalha, e um estandarte inspirador faz milagres quando se trata de deixar você com os ânimos lá em cima.", t = "Introdução ao acampamento: Alfaiataria"},
    [97977] = {ot = "Colete $1oa Totens Masca-pinho e leve-os a Tarindrella.", st = "Os pelursos Masca-pinho não se voltariam contra os antigos aliados deles tão facilmente. Precisamos saber mais sobre o sofrimento deles.\n\nProcure totens nas casas abandonadas deles. Se algum sobreviveu ao caos da partida, as inscrições podem nos contar mais sobre o que aconteceu aqui.\n\nVocê vai encontrar os acampamentos deles na extremidade ocidental do vale, embora os capetas e sua estirpe possam tê-los espalhado mais longe.", t = "O chamado da natureza"},
    [97979] = {ot = "Lance Luz de Eluna e Fusão Sombria.", st = "Você nasceu kaldorei — filhos das estrelas — e herdou um direito inato diferente de qualquer outro neste mundo. A graça de Eluna pode iluminar nossas forças, ajudando nossos ataques a serem precisos, ou pode ajudar a nos esconder, assim como a lua pode eclipsar o sol.\n\nNossa Longa Vigília após a defesa do Monte Hyjal terminou, e nos unimos a uma Aliança de outros — que você conhecerá em breve. Por ora, você repousa nos ramos da Teldrassil.\n\nDemonstre as dádivas da Mãe Lua e regozije-se em suas bênçãos.", t = "A Deusa provê"},
    [98013] = {ot = "Elimine $1oa Mirmidões Escamarraio, $2oa Feiticeiras Escamarraio e $3oa Guerreiros Escamarraio para Arbal no Bosque dos Ancientes.", st = "Reúna sua coragem para adentrar as ruínas, $Gmeu:minha; jovem... Não lhe será concedida passagem livre em seu interior.\n\nDezenas de altaneiros amaldiçoados, agora conhecidos como nagas, vagam pela cidade outrora grandiosa. Viaje para o nordeste e elimine-os desta terra.\n\nO que eles foram um dia... já não existe. Se auxiliarem o Martelo do Crepúsculo, só trarão ainda mais dor às florestas que outrora lhes deram abrigo.\n\nGuerra é o que buscam, $c. Guerra... é o que levaremos a eles.", t = "Forças crescentes"},
    [98021] = {ot = "Apresente-se a Miguel Mantoforte no Morro da Sentinela, em Cerro Oeste.", st = "Se você quiser começar a fazer algo de bom pelo nosso mundo, recomendo se apresentar a um homem de nome Miguel Mantoforte. Ele fica em um assentamento chamado Morro da Sentinela, mais ao sul, em Cerro Oeste. O povo dele precisa de ajuda.\n\nDepois de uma jornada até aqui vindo de outro plano de existência, os problemas que nossas terras enfrentam parecem até pequenos. Garanto que a ajuda que você fornecer a quem sofreu o impacto desses problemas terá um peso gigantesco para eles, e você ficará mais forte por conta desses trabalhos.\n\nBoa sorte, $Gaventureiro:aventureira;!", t = "Jornada ao Morro da Sentinela"},
    [98024] = {ot = "Fale com Thork na Encruzilhada, que fica nos Sertões.", st = "Depois de fazer a jornada do plano elemental até aqui, os problemas que a nossa terra enfrenta parecem pequenos. Tenha certeza de que os perigos que a Horda enfrenta são bem reais e que hão de ser ainda mais terríveis caso você sobreviva ao serviço.\n\nCaso queira começar a fazer algum bem pelo nosso mundo, viaje rumo ao sudoeste, até as terras vastas conhecidas como Sertões. Há um assentamento lá a que chamam Encruzilhada. Os honrados cidadãos de lá estão sempre precisando de ajuda.\n\nVá com honra, $Gaventureiro:aventureira;!", t = "Jornada para a Encruzilhada"},
    [98025] = {ot = "Encontre e mate a coruja conhecida como Jai'vhanel e pegue uma das penas dela. A coruja preta foi vista pela última vez ao norte das ruínas de Ameth'Aran, perto da base da montanha. Relate a morte de Jai'vhanel à Sentinela Glynda Nal'Shea em Auberdine.", st = "Atenção!\n\nOferece-se uma recompensa pela morte da coruja \"Jai'vhanel\", também conhecida como \"Pena-de-espada\".\n\nInfelizmente, esta coruja enlouqueceu e começou a atacar viajantes que passam pela estrada perto de Auberdine.\n\nJai'vhanel foi vista pela última vez ao norte das ruínas de Ameth'Aran, perto da base da montanha. Traga uma de suas penas escuras como prova de sua morte.\n\nA recompensa por esta caçada deve ser solicitada à Sentinela Glynda Nal'Shea em Auberdine.\n\nConselho da Aldeia de Auberdine", t = "PROCURA-SE: Jai'vhanel"},
    [98027] = {ot = "Entregue o Colar de Crescente para Maliynn em Astranaar.", st = "<O colar de prata em suas mãos emite um brilho suave enquanto você o examina. O pequeno formato de lua crescente se parece com outros símbolos dos elfos noturnos que você já viu.\n\nAo virar o colar, há uma pequena inscrição: \"Alor'lormah, Maliynn\". Talvez pertença à Maliynn de Astranaar?>", t = "Colar de Crescente Rebrilhante"},
    [98042] = {ot = "Obtenha um Olho Sem Igual de um Discípulo ou Capanga do Crepúsculo na Glaive do Mestre, na Costa Negra, e encontre alguém em Auberdine que esteja disposto a ficar com ele.", st = "<Ao arrancar a página solta do Tomo do Crepúsculo, uma voz agourenta inunda sua mente sem ser convidada.>\n\nEles fracassaram.\n\nVocê será $Gesquecido:esquecida;.\n\nEles perderão o olho que conquistaram.", t = "É tudo muito divertido, até que..."},
    [98046] = {ot = "Leve o Recipiente Drenado a Lariia no Templo da Lua, em Darnassus.", st = "<O Arquidruida Fandral Guenelmo aperta os olhos.>\n\nVocê ainda está aqui?\n\nPegue o frasco e suma da minha frente, $c. Está claro que minhas respostas não estão nas águas, como não estavam antes. \n\nTalvez uma das sacerdotisas do Templo da Lua ao sul possa dar um fim nisso.\n\n<Fandral afasta o olhar, sem falar mais com você.>\n\nTenho que procurar em outro lugar se eu quiser que isso funcione...", t = "Coroa da Terra"},
    [98065] = {ot = "Leve os Restos do Poço Lunar para Tyrande Murmuréolo no Templo da Lua, em Darnassus.", st = "Leve isso para Tyrande imediatamente! Vou transferir para um recipiente mais cerimonial pra você.\n\nNão se preocupe. A Alta-sacerdotisa de Eluna é firme, mas gentil. Ela protege todos que entram em Darnassus e leva a luz da deusa para todos.\n\nEla ficará feliz em receber essa água sagrada. Está bem acima de nós.", t = "Coroa da Terra"},
    [98067] = {ot = "Posicione Corujas Sentinelas na entrada das profundezas do Forte Cenariano, no Banco de Darnassus, na estalagem do Terraço dos Artesãos e no Portão da Cidade para a Sentinela Dália Gumélion no Templo da Lua, em Darnassus.", st = "A General Plumaluna faz questão que todas as sentinelas tenham tempo para orar a Eluna. Uma verdadeira caçadora não empunha apenas a lâmina, mas também os dons da deusa para superar nossos inimigos.\n\nVocê pode me ajudar com minhas tarefas diárias. Posicione sentinelas pela cidade: comece pelos túneis que levam às profundezas do Forte Cenariano ao norte, o banco no centro da cidade, a estalagem do Terraço dos Artesãos a nordeste e os portões da cidade. As guardas podem lhe ajudar.\n\nAlgo está errado em Teldrassil... Devemos permanecer vigilantes.", t = "Olhos das sentinelas"},
    [98069] = {ot = "Leve 8 Suprimentos de Vento Livre Roubados para Jandia, na Aldeia Vento Livre.", st = "Essas harpias malditas! Elas atacaram a última caravana que eu havia escalado para entregar suprimentos na Aldeia Vento Livre. Por enquanto temos suprimentos suficientes, mas, sem mais reposição, logo ficaremos em falta.\n\nNão sei o que as harpias pretendem fazer com os suprimentos extras, mas ficaria grata se você os recuperasse para mim. O covil delas fica a oeste daqui. Costumam ficar tanto na base do penhasco quanto dentro de uma caverna no topo.", t = "Suprimentos de Vento Livre Roubados"},
    [98070] = {ot = "Mate $1oa Harpias Guinchadoras, $2oa harpias Plumerrantes Guinchadoras e $3oa harpias Arautas do Vento Guinchadoras.", st = "A Garganta Uivante abriga um bando local de harpias conhecido por suas táticas de ataque e sua natureza feroz. Elas emboscaram as últimas caravanas de suprimentos que tiveram a coragem de fazer a travessia.\n\nTemo que, se nada for feito logo, não restarão caravanas que se atrevam a fazer a viagem até a Aldeia Vento Livre.\n\nVá e mate quantas dessas harpias conseguir. Fale novamento comigo quando terminar, e será bem $Grecompensado:recompensada; pelos seus esforços.", t = "Um fim para as guinchadoras"},
    [98093] = {ot = "Sulhasa, na parte sul dos Sertões, quer que você elimine $1oa Lagartos Borrascouro e $2oa Espreitadores Presavaia na área para que ela possa descer da árvore com segurança.", st = "Ainda bem que você me viu!\n\nO tempo estava ótimo de manhã, então saí do Acampamento Taurajo e fiz uma caminhada pela estrada dourada. Mas não consegui voltar: um bando de hienas começou a me rodear, e tinha Lagartos Borrascouro obstruindo a única rota de fuga.\n\nEu subi nessa árvore a duras penas, e agora os campos estão cheios demais de perigos para eu conseguir voltar.\n\nPoderia se livrar dos lagartos Borrascouro e dos Espreitadores Presavaia para mim?", t = "Trabalho de campo"},
    [98094] = {ot = "A Alta-executora Darthalia quer que você entregue as ordens atualizadas para o Sicário Masoj, ao sul da Serraria Tarren, nos arredores de Dun Garok.", st = "Agora que podemos confiar em você para levar informações críticas para nossos espiões, temos uma tarefa extra para lhe oferecer.\n\nLeve isto para o Sicário Masoj, quase diretamente ao sul da nossa posição. Ele terá mais trabalho para você assim que chegar e entregar isso a ele. Ele está posicionado em um terreno elevado ao norte do vinhedo apodrecido que eles chamam de Sítio de Nethander.\n\nNosso plano para assumir o controle destas terras avança de vento em popa.", t = "Suporte aos batedores"},
    [98095] = {ot = "O Sicário Masoj precisa que você deixe as três Ampolas de Boticário nos picos ao redor do Contraforte de Eira dos Montes e depois retorne até ele.", st = "Nosso alto comando usa cavalga-morcegos para posicionar tropas estrategicamente. Pontos-chave ao redor das colinas perderam seus sinalizadores.\n\nPegue estas ampolas. Destampe-as em três locais: nas colinas que fazem fronteira com Dun Garok, no planalto com vista para o Forte do Desterro, e a última no cume do promontório acima da cidade de Eira dos Montes. Os vapores que emanarem serão como um farol poderoso para os sentidos dos morcegos, atraindo-os mais uma vez para os pontos de desembarque desejados.\n\nProcure ampolas vazias esmagadas e renove nossas marcações.", t = "Vantagens valiosas"},
    [98189] = {ot = "Leve a Estatueta de Menethil ao Capitão Punhoforte na Bastilha Menethil.", st = "Minha nossa, é... é linda!\n\nO Princesa Cega devia entregar isto ao Porto de Menethil antes da tragédia. Estávamos tão perto!\n\nCreio que o Capitão Punhoforte, na Bastilha Menethil ali atrás, deveria receber a entrega. Que tal fazer as honras e concluir a entrega?", t = "Devolva a estatueta"},
    [98190] = {ot = "Leve a Estatueta de Menethil ao Grão-lorde Bolvar Fordragon na Bastilha Ventobravo.", st = "É melhor tu levar isso pra Ventobravo sem demora. Eu tenho muito orgulho de ver esta bastilha e este porto levarem o nome do Rei Terenas Menethil II, mas somos apenas um porto tranquilo em meio a uma tormenta de inimigos. Aqui não é seguro.\n\nOs Presa do Dragão, em especial, não mediriam esforços pra pôr as mãos numa peça dessas... e me arrepia pensar no que fariam com ela.\n\nNão perde tempo esperando as ordens de ninguém, $Gguri:guria;. Leva isso direto pro Grão-lorde Fordragon. Ele vai saber onde guardar.", t = "Amigo da família"},
    [98191] = {ot = "Leve a Estatueta de Menethil ao Lorde Grayson Quebrassombra na Catedral da Luz.", st = "O Rei Terenas foi um bom homem. Um homem devoto. Amado pelo povo, e foi mesmo graças a ele que esta Aliança veio a existir.\n\nO irônico é que ele era humilde. Detestava memoriais como este, e é por isso que existem tão poucos. E poucos desses sobreviveram à queda de Lordaeron.\n\nA Luz parece ter se concentrado nesta estatueta. O lugar mais seguro para guardá-la é a Catedral da Luz, na Praça da Catedral, no centro da cidade. Leve-a ao Lorde Grayson Quebrassombra para que a proteja.", t = "Amigo da família"},
    [98197] = {ot = "Recupere $1oa Madeiras Serradas de Khaz Modan e $2oa Ferros de Khaz Modan no Porto de Menethil para Valstag Ferroqueixo.", st = "Este porto foi erguido pela Velha Horda como ponto de partida para a invasão naval de Eira dos Montes. Foi assim que evitaram as defesas de Lordaeron!\n\nTanta gente morreu...\n\nE o pior é que aquela frota foi construída justo com os recursos que eles roubaram de Khaz Modan, tchê!\n\nAinda sobrou material aos montes no porto depois que o Almirante Proudmore expulsou aqueles brutos e construiu este lugar para a Aliança. Vamos precisar desses recursos para reforçar as defesas da cidade, agora que os Presa do Dragão tão se mexendo.", t = "Espólios da guerra"},
    [98219] = {ot = "Fale com o Tenente Fárrio Orinelle na Costa Sul, no Contraforte de Eira dos Montes.", st = "Agradeço novamente por entregar a estatueta em segurança, $n.\n\nPreciso de ajuda com outro assunto. Um membro da guarda da cidade foi transferido para servir na Costa Sul, no Contraforte de Eira dos Montes.\n\nO pai dele era meu amigo e, embora eu reconheça que essa experiência possa lhe servir de lição... ainda quero que ele se saia bem. A ajuda de alguém como você seria muito valiosa.\n\nCaso pretenda passar pelo Porto de Menethil outra vez, há um barco que pode levar você até a Costa Sul.", t = "O tenente desonrado"},
    [98245] = {ot = "Colete $1oa Incisivos de Rasgaqueixo para Alvinho Penagentil.", st = "Não sei quem eu odeio mais: os malditos Ferro Negro, os Presa do Dragão ou os dracos que eles montavam.\n\n<Alvinho cospe no chão.>\n\nEu pretendo botar as coisas nos eixos. Mas vamo precisar de suprimento.\n\nEssas escamas de dragonete protegem bem contra fogo de dragão, mas juntar as danadas é uma trabalheira dos diabos.\n\nOs raptores Rasgaqueixo lá da Serra dos Raptores, a nordeste, e do Vale Espuma de Sal, a noroeste, ganharam esse nome por causa dos dentes pontudos. Devem dar conta de furar as escamas, tchê.\n\nTraz um punhado de incisivos deles pra mim.", t = "Costura Rasgaqueixo"},
    [98246] = {ot = "Colete $1oa Ovos de Rasgaqueixo Perfeitos para Alvinho Penagentil.", st = "Vou precisar de uns ovos pra esse meu plano dar certo. Bicograve precisa ficar de bucho bem cheio. Não tô a fim de subir no lombo de um grifo mal-humorado.\n\nOs ovos precisam estar perfeitos, sem rachaduras nem nada.\n\nPega alguns dos raptores Rasgaqueixo. Eles são conhecidos por terem gemas do tamanho da cabeça de um gnomo. Tu encontra esses ovos na Serra dos Raptores, a nordeste, e no Vale Espuma de Sal, a noroeste.\n\nMelhor pegar uma dúzia, só pra garantir.", t = "Tempos de penúria"},
    [98251] = {ot = "Mate $1oa Cervo Galhassombra e $2oa Urso do Vale Gris e depois fale novamente com Va'xug Furiflama a noroeste do Lago Céu Caído.", st = "Gaaah!\n\nQue raiva. Disseram que era fácil seguir o Vale Gris. Fácil pra quem? Pras feras? Pros pássaros?\n\nNum momento, eu estava colhendo uma planta e, no outro, estava nesta ravina. Tenho que percorrer metade da floresta para chegar aonde eu estava há alguns momentos?\n\nQuando eu fico assim, meus feitiços ficam voláteis e se comportam... de um jeito diferente.\n\nVocê poderia reduzir a quantidade de animais silvestres aqui por perto? Até o barulho dos cascos deles me irrita. Eu detesto esta floresta maldita.", t = "Não volto nunca mais"},
    [98252] = {ot = "Mostre o caminho de volta à estrada do Vale Gris ao Olho de Kilrogg de Va'xug.", st = "Mostre a meu Olho de Kilrogg a saída desta ravina, de volta à estrada do Vale Gris. Continue indo em frente que eu seguirei ao ver o caminho aberto.\n\nVou ficar aqui. Um de nós precisa manter o ponto de referência. Se você perder o caminho, eu posso guiar você de volta pelo olho. Não quero que nós dois vaguemos às cegas por esta floresta maligna.\n\nConsigo segurar o canal aberto por quatro minutos. Nada mais. Chegue à estrada antes que a visão se perca. Caso contrário, volte aqui para recomeçar.", t = "Um caminho no Caos"},
    [98282] = {ot = "Colete uma Glândula Intacta de Espreitador na Rocha de Thelgen para Tina Pastofino, no Porto de Menethil.", st = "Certas receitas alquímicas exigem ingredientes vindos de lugares... digamos... perigosíssimos. E isso muitas vezes só para as plantas básicas! Os outros ingredientes são ainda piores!\n\nPreciso preparar mais antídoto antes de partir de novo. Juro que tudo neste pântano é peçonhento. Parece que a peçonha corre pela própria terra!\n\nVocê pode me ajudar? Preciso de uma glândula de peçonha das aranhas na Rocha de Thelgen, bem ao sudeste. Mas ela precisa estar intacta, senão a peçonha em excesso vai vazar antes que você consiga chegar aqui. Desculpe!", t = "Perigos alquímicos"},
    [98284] = {ot = "Fale com Nasalanna Cantavento na Aldeia de Shen'dar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Encantadores deixam tudo melhor e são sempre bem-vindos em qualquer acampamento na natureza.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar um alaúde encantado para o seu acampamento. É muito importante se divertir durante o ócio, e esse pouquinho de magia pode ajudar você a se preparar para suportar todo tipo de desafio quando pegar a velha estrada poeirenta de novo.", t = "Introdução ao acampamento: Encantamento"},
    [98285] = {ot = "Fale com o Eremita Estranho na Floresta Umbréola para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Todo engenheiro sempre dá um jeito. Se você estiver sozinho no ermo, é sempre bom poder colocar seu ofício em prática. Um bom acampamento só está completo se tiver alguns constructos úteis!\n\nSim, venha me ver de novo quando tiver adquirido um pouco mais de experiência como $Gengenheiro:engenheira;, que eu lhe ensino a fazer algo especial!", t = "Introdução ao acampamento: Engenharia"},
    [98286] = {ot = "Fale com Nasalanna Cantavento na Aldeia de Shen'dar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", st = "Encantadores deixam tudo melhor e são sempre bem-vindos em qualquer acampamento na natureza.\n\nAcho que eu conheço alguém que pode lhe ensinar a criar um alaúde encantado para o seu acampamento. É muito importante se divertir durante o ócio, e esse pouquinho de magia pode ajudar você a se preparar para suportar todo tipo de desafio quando pegar a velha estrada poeirenta de novo.", t = "Introdução ao acampamento: Encantamento"},
    [98299] = {ot = "Mate $1oa Refugiados Adoentados e $2oa Refugiados Famintos para Dalar Tessalba no Sepulcro.", st = "Se tem uma coisa que sabemos, é que Arugal é o culpado pelos worgens em Pinhaprata — seja pelas próprias maquinações dele ou por outro motivo. O que não sabemos é como eles se espalham.\n\nEnquanto eu pesquiso um jeito de deter a maldição, nossa prioridade máxima é contê-la. Parece que ela não afeta renegados, mas uma grande quantidade de humanos se reuniu na Muralha Greymane.\n\nVá até a muralha e acabe com esses refugiados antes que se tornem servos de Arugal. E cuidado para não levar uma mordida, $r.", t = "Combate à proliferação"},
    [98319] = {ot = "Encontre o Montanhista Cornélio no Covil Cinzento para a Montanhista Gretchen.", st = "Como se já não bastasse o problema dos trolls, as montanhas agora estão cheinhas de wendigos! Eles normalmente ficam nas cavernas, mas parece que se espalharam que nem coelho. Agora eles já encheram o Covil Cinzento ao norte daqui.\n\nPra conseguir o relatório do Barbabranca, a gente tem que encontrar o meu parceiro Cornélio. O cabeça de vento ficou empolgado demais e foi na frente sozinho. Bah, o que ele não tem de medo, tem de idiota.\n\nVai até a caverna e vê onde ele tá. E aproveita pra matar umas feras enquanto está lá.", t = "Protegendo a montanha"},
    [98321] = {ot = "Colete $1oa Carregamentos do Pederfogo no Covil Cinzento para Tognus Pederfogo em Kharanos.", st = "Opa! Que bom ver $Gum:uma; $r que não tem medo de sujar as mãos.\n\nSe estiver procurando trabalho, infelizmente eu tô com pouco suprimento no momento. Nossa fonte mais confiável de minério foi dominada por wendigos e agora a caverna foi abandonada. Os mineradores tiveram que deixar tudo quando fugiram!\n\nO que acha de enfiar a cabeça no Covil Cinzento lá pro oeste e ver se tu acha uns carregamentos perdidos. Pouparia muitos problemas pra gente.", t = "Carregamento do Pederfogo"},
    [98322] = {ot = "Fale com a Montanhista Gretchen a oeste de Kharanos.", st = "Explorar cavernas sombrias é negócio de aventureiro. Meu trabalho é fazer relatórios e mandar pra Altaforja.\n\nMas o negócio é que os meus relatórios não receberam os... relatórios de resposta. Eu pedi a alguns montanhistas pra saber mais sobre o problema de wendigos que a gente tem aqui, mas nunca falaram nada.\n\nSe tu já está andando por aí, por que não fala com a Montanhista Gretchen a oeste da cidade? As coisas já andam atrasadas demais, tchê!", t = "Protegendo a montanha"},
    [98323] = {ot = "Entregue o Relatório da Montanhista Gretchen para Senir Barbabranca em Kharanos.", st = "Tomara que tu tenha acabado com um monte daqueles monstrengos enquanto tava por lá. Mas é uma pena o que aconteceu com o Cornélio.\n\nPelo que tu disse, não tem muito o que fazer, já que a caverna é uma causa perdida. O Barbabranca não vai gostar da resposta, mas eu é que não vou mandar alguém praquela armadilha.\n\nFique à vontade pra passar a mensagem, $n. Eu não vou arredar o pé daqui até a montanha estar segura.", t = "Protegendo a montanha"},
    [98326] = {ot = "Mate o Uivo de Gelo e pegue o Saco de Peixes para Gretta Ganter na Aldeia da Cevada.", st = "Você sabe como é difícil pescar num lago congelado? O coitado do meu marido Paxton passou dias tentando pescar alguma coisa e voltou com só um saquinho de nada.\n\nE a gente TINHA o saquinho de nada... Até que um wendigo desgraçado me atacou e saiu com o nosso sustento. A gente vai levar semanas pra pescar tudo de novo! Isso se aquele Uivo de Gelo barulhento não tivesse assustado todos eles...\n\nPode fazer um favor pra gente e ir pegar tudo de volta? Aquele brutamontes babão se escondeu em algum lugar nas profundezas do Covil Cinzento ao sudoeste.", t = "Uivo de gelo"},
    [98340] = {ot = "Fale com Dendrite Stellardor no vilarejo do Refúgio Noturno, na Clareira da Lua.", st = "Parece que chegou o momento do próximo passo em sua jornada, jovem $Gdruida:druidesa;. Dendrite Stellardor solicitou sua presença mais uma vez na Clareira da Lua.\n\nVocê já aprendeu a invocar a magia que leva até lá, então poderá partir imediatamente se quiser. Sugiro que vá sem demora se deseja continuar seu treinamento druídico.", t = "O Espírito do Grande Felino"},
    [98341] = {ot = "Procure o Avatar de Saeyleenan na porção meridional da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do gato pairavento.", st = "Um espírito da sua terra natal apareceu recentemente e me pediu para guiar você até ele. Esse espírito de gato pairavento veio para instruir e orientar você, para que você possa assumir a forma felina do espírito em Zefras.\n\nCedo ou tarde, todos os druidas buscam essa sabedoria, embora pareça que a sua terra natal seja um pouco diferente da nossa, já mais tradicional. Caso deseje assumir a forma desse espírito felino, você precisará passar por nossa provação.\n\nVocê encontra o espírito na porção meridional da Clareira da Lua, ao sul das pontes gêmeas.", t = "O grande espírito felino pairavento"},
    [98342] = {ot = "Recupere a Relíquia da Presa, a Relíquia da Garra e a Relíquia da Sombra Silenciosa do Templo de Tempesfúria e depois leve-as ao Espírito do Grande Felino.", st = "Para recorrer ao meu espírito, você vai precisar de mais do que algumas palavras. Para compreender e respeitar minha forma, você deve provar que é capaz de incorporar a astúcia, a furtividade e, caso seja $Gencurralado:encurralada;, a ferocidade.\n\nNos templos a leste daqui, há três relíquias que você precisa adquirir em meu nome. Elas são protegidas por espíritos enfurecidos poderosos que atacarão assim que virem você. Há uma estátua na entrada que abençoará você com uma furtividade temporária para que possa passar pelos espíritos.\n\nDevolva essas relíquias a mim. Veremos se está $Gpronto:pronta; para assumir minha forma.", t = "O Espírito do Grande Felino"},
    [98362] = {ot = "Volte ao Penhasco do Trovão e fale com Turak Runa Totem no Platô dos Anciãos.", st = "Chegou a hora de nos separarmos mais uma vez, $Gmeu:minha; jovem, pois a aplicação de suas lições leva você de volta àquele que $Go:a; enviou até mim. Ao que parece, seu instrutor, Turak Runa Totem, encontrou em você alguém digno de seus ensinamentos. Também vejo isso, creio eu. Atente às lições dele, que logo será capaz de recorrer ao Espírito do Grande Felino para assumir sua forma.\n\nRetorne ao lugar de onde veio. Quando a hora chegar, nos encontraremos de novo.", t = "Para o Penhasco do Trovão"},
    [98386] = {ot = "Mate $1oa Grandes Tarântulas e destrua $2oa Ovos de Tarântula na Serraria Alther para o Encarregado Oslow, em Cristarrubra.", st = "Orcs, gnolls, murlocs. Todos parecem conspirar para me impedir de terminar essa ponte a tempo. E agora recebemos notícias de uma infestação de tarântulas na nossa serraria!\n\nSe você quiser ganhar umas moedas, poderia ir até a Serraria Alther, a leste daqui, e acabar com o problema de aranhas por lá? Aquele lugar é inútil pra mim se eu não puder mandar trabalhadores pra buscar os carregamentos em segurança.\n\nAh, e se você vir o velho Alther, diga que ele me deve uma por eu ter limpado a bagunça dele.", t = "Serraria Alther"},
    [98387] = {ot = "Traga $1oa Armas Roubadas e $2oa Suprimentos Rocha Negra para o Oficial Marris na Vila Plácida.", st = "Não dá para lutar uma guerra sem armas.\n\nEmbora os orcs Rocha Negra tenham avançado sobre estas terras, seus esforços ousados não deixam de ter certas vulnerabilidades.\n\nSiga para sudeste, abaixo da Bastilha Mirante de Pedra e procure os acampamentos deles, visando as armas e os suprimentos.\n\nVamos ver o tamanho da ameaça que eles representam sem suas ferramentas de guerra.", t = "Bloqueio aos Rocha Negra"},
    [98389] = {ot = "Liberte $1oa Vítimas Encasuladas na Caverna da Teia da Noite para Aramis Cerramartelo em Plangemortis.", st = "Saudações, $c. Sim, sou um paladino. Nem mesmo a morte pode deter a Luz.\n\nIsso é algo que meu povo tem em comum com todos os Renegados: superamos aquilo que os vivos enxergam como o fim. Porém, alguns ainda nos temem, mesmo dentre os nossos. Imaginam que vamos abatê-los como se fossem alguma monstruosidade.\n\nNa verdade, nossa relação com a morte-viva é complexa, mas não estou aqui para ferir meus iguais. Ajude-me a mostrar isso aos outros. Vá até a Caverna da Teia da Noite, a noroeste, e liberte os pobres tolos recém-erguidos que foram presos pelas aranhas.", t = "Uma luz na escuridão"},
    [98391] = {ot = "Fale com a Irmã Aquinne em Darnassus.", st = "Bênçãos para você, $c. A Irmandade de Eluna é um pilar da sociedade kaldorei há milhares de anos.\n\nAntes da Grande Cisão, antes da Guerra dos Antigos, por toda a Longa Vigília, guiamos e curamos nossas pessoas por meio da escuridão. Esse é o nosso fardo, e essa é a demanda da inigualável Mãe Lua.\n\nAgora, precisamos da sua ajuda numa questão de grande importância. A Irmã Aquinne espera sua chegada em Darnassus.", t = "A Irmandade de Eluna"},
    [98392] = {ot = "Colete o Amuleto de Guinchódio, o Amuleto da Dama dos Ventos Gaedress e o Amuleto da Bruxa Matriarca Arysa para a Sentinela Arynia Rasganimbus na Clareira do Oráculo.", st = "Esses cintos... olhe com atenção para o couro, $n. Você vê a mácula correndo pelas fibras?\n\nTenho uma suspeita da origem, mas precisaremos de mais provas para termos certeza.\n\nAventure-se nos ninhos das harpias a oeste e acabe com as líderes delas. Se os colares delas tiverem a mesma escuridão destes cintos, teremos a nossa resposta.", t = "Escuridão na clareira"},
    [98393] = {ot = "Fale com Dendrite Stellardor no vilarejo do Refúgio Noturno, na Clareira da Lua.", st = "Parece que chegou o momento do próximo passo em sua jornada, jovem $Gdruida:druidesa;. Dendrite Stellardor solicitou sua presença mais uma vez na Clareira da Lua.\n\nVocê já aprendeu a invocar a magia que leva até lá, então poderá partir imediatamente se quiser. Sugiro que vá sem demora se deseja continuar seu treinamento druídico.", t = "O Espírito do Grande Felino"},
    [98394] = {ot = "Procure o Espírito do Grande Felino na porção meridional da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do gato.", st = "Na parte sul da Clareira da Lua, em uma colina com vista para a ponte, reside um ser sábio e astuto a quem chamamos de Espírito do Grande Felino.\n\nAssim como o Espírito do Grande Urso, esse espírito serve de mentor aos druidas que desejam assumir a forma felina. Todos os druidas acabam buscando sua sabedoria. Se deseja assumir a forma de felino, você também deve fazer isso.\n\nVá se encontrar com o Espírito do Grande Felino e aprenda o que ele tiver a lhe ensinar.", t = "O Espírito do Grande Felino"},
    [98396] = {ot = "Recupere a Relíquia da Presa, a Relíquia da Garra e a Relíquia da Sombra Silenciosa do Templo de Tempesfúria e depois leve-as ao Espírito do Grande Felino.", st = "Para recorrer ao meu espírito, você vai precisar de mais do que algumas palavras. Para compreender e respeitar minha forma, você deve provar que é capaz de incorporar a astúcia, a furtividade e, caso seja $Gencurralado:encurralada;, a ferocidade.\n\nNos templos a leste daqui, há três relíquias que você precisa adquirir em meu nome. Elas são protegidas por espíritos enfurecidos poderosos que atacarão assim que virem você. Há uma estátua na entrada que abençoará você com uma furtividade temporária para que possa passar pelos espíritos.\n\nDevolva essas relíquias a mim. Veremos se está $Gpronto:pronta; para assumir minha forma.", t = "O Espírito do Grande Felino"},
    [98397] = {ot = "Volte a Darnassus e fale com Mathrengyl Ursivagus no Enclave Cenariano.", st = "Chegou a hora de nos separarmos mais uma vez, $Gmeu:minha; jovem, pois a aplicação de suas lições leva você de volta àquele que $Go:a; enviou até mim. Ao que parece, seu instrutor, Mathrengyl Ursivagus, encontrou em você alguém digno de seus ensinamentos. Também vejo isso, creio eu. Atente às lições dele, que logo será capaz de recorrer ao Espírito do Grande Felino para assumir sua forma.\n\nRetorne ao lugar de onde veio. Quando a hora chegar, nos encontraremos de novo.", t = "Para Darnassus"},
    [98398] = {ot = "Encontre o Oráculo da Casca de Árvore por perto para receber a mensagem dele.", st = "Estou impressionada com o quanto você conquistou em tão pouco tempo, $n. Gostaria de pedir para que ficasse e me ajudasse com outras tarefas... mas meu coração sabe que conquistas muito mais grandiosas lhe aguardam.$b$bPercebi que a Árvore dos Oráculos acabou de soltar um pedaço da casca. Com certeza essa casca traz uma missão que a árvore quer ver cumprida. Fale com ela.", t = "Árvore do Oráculo"},
    [98403] = {ot = "Mate $1oa Lenhateias Conspurcados e leve o Limo Vil Adulto de Xethorr, o Perverso, para Tallonkai Radicélere em Dolanaar.", st = "O Senhor Málinus não agiu sozinho: ele estava sob ordens de outrem. Quem você procura é Xethorr, o Perverso. Parece que ele corrompeu as aranhas que vivem em Teldrassil, pretendendo usar a peçonha deles para algum plano maligno.\n\nEle firmou residência bem nas profundezas da floresta, na área a noroeste daqui conhecida como a Fenda. Tome cuidado e leve aliados, pois Xethorr não é um oponente qualquer.\n\nAcabe com a prole dele e traga algo que elucide um pouco mais as ações dos sátiros aqui.", t = "Aversão pervertida"},
    [98404] = {ot = "Recupere a Relíquia da Presa, a Relíquia da Garra e a Relíquia da Sombra Silenciosa do Templo de Tempesfúria e depois leve-as ao Avatar de Saeyleenan.", st = "Para recorrer ao meu espírito, você precisa passar por uma provação. Para compreender e respeitar minha forma, você deve provar que é capaz de incorporar a astúcia, a furtividade e, caso seja $Gencurralado:encurralada;, a ferocidade.\n\nNos templos a leste daqui, há três relíquias que você precisa adquirir. Elas são protegidas por espíritos enfurecidos poderosos que atacarão assim que virem você. Há uma estátua na entrada que abençoará você com uma furtividade temporária para que possa passar pelos espíritos.\n\nDevolva-me essas relíquias para passar na provação druídica dessa região.", t = "O grande espírito felino pairavento"},
    [98405] = {ot = "Procure o Espírito do Grande Felino na porção meridional da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do gato.", st = "Na parte sul da Clareira da Lua, em uma colina com vista para a ponte, reside um ser sábio e astuto a quem chamamos de Espírito do Grande Felino.\n\nAssim como o Espírito do Grande Urso, esse espírito serve de mentor aos druidas que desejam assumir a forma felina. Todos os druidas acabam buscando sua sabedoria. Se deseja assumir a forma de felino, você também deve fazer isso.\n\nVá se encontrar com o Espírito do Grande Felino e aprenda o que ele tiver a lhe ensinar.", t = "O Espírito do Grande Felino"},
    [98407] = {ot = "Colete $1oa Coleiras Farpadas de Espancadores de Cristarrubra para o Subdelegado David, perto da Vila Plácida.", st = "Se os gnolls estão ficando ousados a ponto de acampar tão perto dos humanos, não há como saber até onde eles irão. Precisamos detê-los.\n\nSão feras sem organização, mas parecem respeitar a força acima de tudo. Se matarmos os piores deles e pegarmos alguns troféus, vamos lembrar a esses gnolls por que devem ficar nas colinas, que é o lugar deles.\n\nSe você vir algum dos espancadores deles, traga-me as coleiras. Isso deve lembrar esses gnolls de terem medo da Aliança.", t = "Demonstração de força"},
    [98417] = {ot = "Maseara Lunautumna quer que você vasculhe a região oeste de Cantilenda, em meio aos demônios de Satyrnaar. Ao retornar, relate qualquer sinal que tenha encontrado de Kurothel, marido dela.", st = "Justamente quando o destino nos uniu em nosso momento de maior vulnerabilidade, uma tragédia se abateu sobre nossas aldeias. Os sátiros profanaram nossos templos, com seu toque impuro maculando ramos sagrados, e massacraram os inocentes sem dó.\n\nKurothel foi tomado pela ira. Os druidas saíram atrás dos sátiros para lutar, e ele foi atrás.\n\nNossos laços permanecem. Estou sentindo meu marido a oeste, dentro da floresta. Por favor, traga notícias do destino dele.", t = "Trilha de vingança"},
    [98418] = {ot = "Mate $1oa Ladinos Xavianos, $2oa Devotos Vis Xavianos, $3oa Traidores Xavianos e $4oa Infernarautos Xavianos.\nDepois, fale novamente com Maseara Lunautumna em Cantilenda.", st = "Kurothel mencionou avistamentos de algo descrito como homens-lobo. Os membros da alcateia estão à espreita em grandes números na nossa floresta. Na última vez que nos falamos, os druidas estavam tentando se comunicar com as feras cujo coração demonstrava certo controle sobre seus instintos animais.\n\nAs palavras que ele escreveu relatam uma luta mais sombria. Se ainda houver alguma forma de trazer ELE de volta, certamente eliminar a ameaça demoníaca que o está levando a essa transformação terrível aliviará sua alma atormentada.\n\nMate os xavianos, $n.", t = "Fúria compartilhada"},
    [98423] = {ot = "Entregue o Tratado de Entendimento para Magni Barbabronze em Altaforja.", st = "Dentro do cofre você encontra uma tabuleta detalhando os termos de um tratado de paz entre os clãs enânicos Barbabronze e Martelo Feroz. Ela parece datar do período posterior à Guerra dos Três Martelos e provavelmente se trata de uma peça notável da história enânica. O rei de Altaforja sem dúvida terá interesse neste artefato.", t = "O Tratado de Entendimento"},
    [98424] = {ot = "Colete o restante das páginas do Supervisor Geringonça dentro da Mina da Empreendimentos S.A. e leve-as a Morin Espreita Nuvem, perto da Aldeia Casco Sangrento.", st = "Alguns papéis especialmente gastos estão separados, dobrados no bolso interno do paletó de Geringonça.\n\nEles parecem conter informações importantes que podem ser usadas contra a Empreendimentos S.A. e suas operações na região. Seria prudente procurar mais desses papéis antes de retornar a Morin Espreita Nuvem.", t = "Anotações do Geringonça"},
    [98427] = {ot = "Leve a Chave de Fio-afiado a Morin Espreita Nuvem, nos arredores da Aldeia Casco Sangrento.", st = "O retalhador mencionado numa das páginas... Já vi máquinas assim em minhas viagens. Elas conseguem dizimar uma floresta em muito menos tempo que braços e machados.\n\nClareiras inteiras, lares dos filhos da Mãe Terra por milênios, apagadas em poucos dias.\n\nNão permitiremos que isso aconteça em nosso lar, a poucos passos de onde nossos jovens dão os primeiros passos.\n\n$n, preciso que reúna aliados, volte à mina a nordeste e garanta que o retalhador não derrube nem mais uma árvore.", t = "Encerrando as operações"},
    [98430] = {ot = "Ajude Perith Casco Feroz a escapar do Rochedo Jubalba e informe Caerne Casco Sangrento, no Penhasco do Trovão, de que Perith está a salvo.", st = "Saudações, $c. O que traz você às profundezas de um lugar tão sombrio e violento?\n\nFui enviado pelo Grande Chefe Caerne Casco Sangrento como parte dos nossos esforços para falar com os gnolls que se instalaram aqui. O restante da minha missão deve permanecer em segredo, como tudo que envolve os Passo-longo, batedores de confiança do nosso chefe.\n\nBasta você saber que nossa diplomacia foi recebida com violência, e temo que virarei banquete dos gnolls esta noite se você não me ajudar a escapar.\n\nVocê está à altura da tarefa?", t = "Os Passo-longo"},
    [98435] = {ot = "Leve o Relatório de Chifre Troante ao Arquidruida Hamuul Runa Totem, no Penhasco do Trovão.", st = "Nossos anciãos no Penhasco do Trovão precisam saber do progresso que alcançamos aqui graças à sua ajuda.\n\nPor favor, leve isto ao Arquidruida Hamuul Runa Totem, no Penhasco do Trovão. Você o encontrará no Platô dos Anciãos, no lado leste da cidade. Pegue os elevadores até o centro da cidade e então cruze as pontes para chegar lá.", t = "Relatório de Chifre Troante"},
    [98461] = {ot = "Entregue o Bilhete de Hollee para Tarrel Tecepedra perto do Porto de Menethil no Pantanal.", st = "Se tu vai para Auberdine, eu aceito uma ajuda!\n\nMeu grande amigo Tarrel e eu éramos colegas na escola. Bah, ele era empolgadíssimo com escavações! A gente se separou depois da formatura. Ele foi pro Pantanal e eu fui pra Costa Negra.\n\n<Hollee suspira, depois franze a sobrancelha levemente.>\n\nDesculpa. E a esposa dele... a Marina.\n\nNão importa. Se tu for pro Pantanal, pode ver se ele tá bem? E talvez entregar isso pra ele? Ele deve estar perto do Porto de Menethil. Tem um barco lá.", t = "Amor não correspondido"},
    [98512] = {ot = "Mate 10 Assassinos Al'Aketh no Planalto de Shen'dar.", st = "Ei, você aí. Abaixe-se e fique em silêncio. Não estamos a sós.\n\nEu estava em patrulha perto da fronteira e percebi que há vários Al'Aketh rondando a casa logo ali em cima da colina, ao norte. Não sei o que estão fazendo aqui, mas não pode ser coisa boa.\n\nSe quiser ser útil, entre lá e acabe com eles. Vou esperar aqui e cobrir sua retaguarda.", t = "Assassinos Al'Aketh"},
    [98545] = {ot = "Entregue a Carta Selada para Glix Xizzix na Cidade Baixa.", st = "Já que você está aqui, gostaria que entregasse esta carta a um velho amigo meu na Cidade Baixa. Eu mesmo entregaria, mas tenho um passado um tanto conturbado com a Dama Sombria, e seria melhor se terceiros neutros fizessem a entrega.\n\nVocê deve procurar um goblin chamado Glix Xizzix no Distrito Comercial da Cidade Baixa. Tenho certeza de que ele compensará você pelo seu tempo com muito prazer.\n\n<Leonid deixa escapar uma risada contida ao lhe entregar a carta.>", t = "A carta de Leonid"},
    [98574] = {ot = "Leia o Memorando Santificado e fale com Branstock Khalder em Sidermar.", st = "Enquanto tu tava me dando uma mãozinha, eu recebi esse memorando aqui pra te passar. Seria muy bueno tu dar uma lida nele. Acho que foi o instrutor de sacerdotes Branstock quem te mandou. Depois que ler, tu pode procurar ele em Sidermar quando tiver um tempinho.", t = "Memorando Santificado"},
    [98575] = {ot = "Leia a Tabuleta Turbada e fale com Nartok dentro do Covil, no Vale das Provações.", st = "Ah, chegou uma tabuleta para você na sua ausência, $n.$B$BGeralmente, evito lidar com bruxos, mas é melhor você ler o pergaminho assim que tiver tempo. Se não me engano, é do instrutor recém-designado, Nartok. Ele quer falar com você assim que você estiver $Gpronto:pronta;.", t = "Tabuleta turbada"},
    [98576] = {ot = "Leia o Pergaminho Glífico e fale com Mai'ah perto da entrada Covil, no Vale das Provações.", st = "Ah, chegou um pergaminho chegou você durante a sua ausência, $n.$B$BLeia-o quando tiver tempo. Se não me engano, foi Mai'ah, a instrutora de magos, que o enviou. Ela vai falar com você quando você estiver $Gpronto:pronta;.", t = "Pergaminho Glífico"},
    [98581] = {ot = "Leia a Runa Arcaica e fale com Teo Tempestelo em Sidermar.", st = "Enquanto tu me ajudava, recebi esta runa para ti. Te acomoda uma hora para ler o que ela diz. Levando em conta o estilo Martelo Feroz nestas inscrições, penso eu que foi o instrutor de xamãs Teo Tempestelo quem a enviou. Dá uma olhada e depois fala com ele em Sidermar quando tiver a oportunidade.", t = "Runa arcaica"},
    [98601] = {ot = "Leia o Pergaminho Consagrado e fale com Aramis Cerramartelo na igreja de Plangemortis.", st = "Enquanto esteve fora lidando com o Flagelo desmiolado, este pergaminho chegou para você. Ele fede a Luz, então imagino que tenha alguma importância para $Gum paladino:uma paladina; como você.\n\nLeia-o antes de partir novamente. Só peço que... se afaste quando for ler. Paladinos me deixam bastante desconfortável.", t = "Um caminho árduo"},
    [98731] = {ot = "Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua.", st = "Agora que você recebeu minha bênção, fale novamente com Dendrite. Ele vai lhe passar mais instruções. Espero que nos reencontremos algum dia.\n\nQue as sombras sempre ocultem você, e que os seus inimigos sejam vítimas das suas garras, $Gjovenzinho:jovenzinha;.", t = "Bênçãos do Espírito do Grande Felino"},
    [98738] = {ot = "Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua.", st = "Agora que você recebeu minha bênção, fale novamente com Dendrite. Ele vai lhe passar mais instruções.\n\nInfelizmente, não tenho muito mais a lhe ensinar no momento. Espero que você volte a me visitar em Zefras algum dia. Sinto que você é uma grande promessa, jovem shen'dorei.\n\nQue as sombras sempre ocultem você, que os seus inimigos sejam vítimas das suas garras, e que os ventos guiem seus passos.", t = "Bênçãos do Grande Espírito Felino Pairavento"},
    [98739] = {ot = "Fale com Dendrite.", st = "Agora que você recebeu minha bênção, fale novamente com Dendrite. Ele vai lhe passar mais instruções. Espero que nos reencontremos algum dia.\n\nQue as sombras sempre ocultem você, e que os seus inimigos sejam vítimas das suas garras, $Gjovenzinho:jovenzinha;.", t = "Bênçãos do Espírito do Grande Felino"},
    [98815] = {ot = "Leve $1oa Couros de Raptor do Matagal para Iago Halberque, o curtumeiro, no Porto de Menethil.", st = "Os Planaltos abrigam algum tipo de ruína, segredos que agora estão sendo explorados por uma equipe de expedição. O que eu sei é que eles têm sua própria vida selvagem e feras espreitando naquele charco montanhoso. Que tal você fazer uma incursão por lá com uns amigos bem equipados pra fecharmos um negócio?\n\nEu não ligo se eles estão se escondendo; eu quero é arrancar o couro deles! Me traga as peles de quatro Raptores do Matagal e vou bolar uma troca pra fazer isso valer a pena.", t = "Os couros do planalto"},
    [98823] = {ot = "Leve a Relíquia Titânica para Muln Terrafúria no Platô do Vigia dos Céus, no noroeste de Mulgore.", st = "Este objeto é mesmo fascinante.\n\nEle traz indícios de ser muito mais do que um mero entalhe ou escultura.\n\nEmbora nossos anciãos possam ter interesse em observar este artefato, a Harmonia Telúrica é quem detém mais sabedoria a respeito de nossas ruínas enterradas e nossas terras esquecidas. Busque por Muln Terrafúria. Recomendo uma abordagem direta dada a importância do que você carrega.\n\nVocê pode encontrá-lo junto a outros anciãos do conselho da Harmonia Telúrica no Platô do Vigia dos Céus, no noroeste de Mulgore.", t = "Eco telúrico"},
    [98824] = {ot = "Leve a Relíquia Titânica para a Alto-explorador Magellas no Salão dos Exploradores em Altaforja.", st = "Com essas inscrições titânicas nas facetas, o Salão dos Exploradores de Altaforja é o único lugar certo pra levar isso.\n\nGosto de pensar que tu vai entrar pra história no catálogo: \"Recuperado por $n! Autenticado pelo Prospector Whelgar...\" Bah, já tô me deixando levar.\n\nO Alto-explorador Magellas vai te receber, e, dada a natureza espetacular do que tu carrega, com certeza vai ser muito generoso se tu doar isso pro museu.\n\nBaita achado!", t = "Prisma pré-histórico"},
    [99046] = {ot = "Procure a Sentinela Eralya Sombrafolha na estrada que leva à Clareira do Oráculo.", st = "O Conselho da Floresta enviou um pequeno grupo de sentinelas até a Árvore dos Oráculos há algum tempo. A árvore envia mensagens aos nossos anciãos, e cabe a nós entregá-las em segurança a Darnassus.\n\nRecebi a notícia de que nossa última mensageira ainda não chegou. A frequência das mensagens do Oráculo varia, mas já se passou um tempo anormalmente longo.\n\nPor favor, siga pela estrada a oeste em direção à Clareira do Oráculo e procure por ela. Era a vez de Eralya Sombrafolha, e ela ainda está em treinamento. Que Eluna guie você.", t = "A mensageira perdida"},
    [99047] = {ot = "Procure Byonsa em Dolanaar e peça ajuda para a Sentinela Eralya Sombrafolha.", st = "Minhas irmãs e eu... fomos enviadas... à Árvore dos Oráculos...\n\nÁrvore... mensagem. Eu... harpias... por toda parte...\n\n<Eralya tosse sangue, contorcendo o rosto de dor.>\n\nNão sei quanto tempo me resta... Ninguém está vindo. Por favor... Byonsa... em Dolanaar...", t = "Ainda há esperança"},
    [99048] = {ot = "Encontre Heglan Sombrolho ao norte da Bastilha Tiragarde.", st = "Uma integrante da Mão Despedaçada, um grupo de combatentes mais... discretos, estava observando a Bastilha Tiragarde à distância. De repente, os relatórios dela pararam de chegar.\n\nDuvido que os humanos tenham conseguido capturar ela, então acho que tem algo mais perigoso por trás disso. Veja se encontra ela. Espero que as mensagens estejam apenas atrasadas.", t = "A mão desaparecida"},
    [99049] = {ot = "Encontre sinais do que atacou Heglan Sombrolho.", st = "A área ao redor está destruída e apresenta sinais claros de confronto. O que quer que tenha emboscado Heglan não saiu ileso. Deve haver sinais do que aconteceu por perto.\n\nOrgnil provavelmente vai querer ver qualquer vestígio deixado pelos agressores.", t = "Ameaça vinda de baixo"},
    [99050] = {ot = "Colete $1oa Frondes Orvalhadas de Açoitadeira, uma Ampola Vazia e uma Água Refrescante da Fonte para Byonsa em Dolanaar.", st = "Vou precisar da sua ajuda para conseguir os ingredientes necessários para conter o suplício por tempo suficiente para que Eralya consiga voltar até aqui e receber tratamento adequado.\n\nFelizmente, nosso lar ainda é abundante e nos proverá neste momento de necessidade.\n\nO ingrediente principal são frondes orvalhadas de açoitadeira. Você as encontra ao redor do Lago Al'Ameth, diretamente ao sul daqui, ou no Lago Olho-d'Água e em seu rio, a noroeste.\n\nAlém disso, vou precisar de uma ampola vazia e um pouco de água da fonte. Ambos podem ser comprados aqui na cidade ou obtidos por meio de troca.", t = "A Grande Árvore provê"},
    [99051] = {ot = "Colete $1oa Espinhapinas de Naga.", st = "Não é a primeira vez que essas serpentes causam problemas. Precisamos deixar claro que a presença delas não é tolerada aqui.\n\nDescubra onde os batedores delas estão montando acampamento e mate todos. Traga as barbatanas deles como prova. Temos que agir rápido pra garantir que entendam o recado.", t = "Ameaça vinda de baixo"},
    [99052] = {ot = "Mate o Gigante do Mar na costa norte de Durotar e traga uma prova do seu feito.", st = "Um dos meus batedores informou que um gigante do mar seguiu aquelas nagas até aqui. Não sei se elas trouxeram ele de propósito ou o quê, mas, de qualquer forma, ele é perigoso.\n\nÉ jovem, mas ainda assim poderia partir um orc ao meio num piscar de olhos se pegasse ele desprevenido. Preciso que você dê um fim nele. Mas é melhor conseguir ajuda pra lidar com isso.", t = "Ameaça vinda de baixo"},
    [99053] = {ot = "Ajude a Sentinela Lynessa Flor do Ocaso a escapar da Gruta de Ban'ethil e informe à Sentinela Kyra Stelacanto, em Dolanaar, que ela está a salvo.", st = "Minhas preces foram atendidas! Sou grata por você ter conseguido chegar até mim.\n\nA Árvore do Oráculo me enviou para entregar uma mensagem aos druidas adormecidos, mas encontrei o local completamente tomado por pelursos! Eles me emboscaram antes que eu pudesse voltar e me trouxeram para cá... Temo acabar sendo a próxima refeição deles.\n\nNão sei quanto a você, mas eu detesto isso aqui. O subterrâneo não é lugar para os kaldorei.", t = "Escapando de Ban'ethil"},
    [99073] = {ot = "Leve o Bálsamo de Açoitágua até a Sentinela Eralya Sombrafolha na estrada que dá na Árvore dos Oráculos.", st = "O bálsamo está pronto. Leve-o depressa até Eralya.\n\nNão sei se ele será capaz de curá-la. A podridão se agrava rapidamente e se fortalece conforme se espalha.\n\nNo mínimo, vai aliviar o sofrimento dela. E isso já faz valer a pressa.", t = "Alívio para o sofrimento"},
    [99079] = {ot = "Encontre a Passo-longo Malah Vento Longo a leste da Aldeia Casco Sangrento, perto da divisa de Mulgore.", st = "Os Passo-longo são os batedores de maior confiança do nosso povo. Embora sejam leais apenas ao Grande Chefe, o jovem Baine às vezes recorre à ajuda deles.\n\nEsta é uma dessas ocasiões. A Passo-longo Malah foi enviada pra perto das nossas fronteiras a leste e não voltou ontem à noite, depois de três dias. Quando isso acontece, é nosso dever confirmar que estão em segurança.\n\nPreciso garantir que a aldeia permaneça segura. Prove seu valor e procure Malah. Você reconhecerá ela pela faixa na cabeça e pelo cajado emplumado, símbolos dos Passo-longo.", t = "Passo-longo Malah"},
    [99080] = {ot = "Mate $1oa Centauros Galath e $2oa Vanguardeiros Galath e leve a cabeça de Herak, o Pilhador, até Baine Casco Sangrento.", st = "Ouça bem minhas palavras: não cederemos aos centauros nem um único tufo de grama.\n\nVá ao acampamento deles agora, antes que tenham descansado e possam cavalgar até nossa aldeia. Mate todos eles. Não deixe nenhum escapar para os Sertões em busca de reforços.\n\nSe encontrar o líder desse pretenso grupo de ataque, traga-me a cabeça dele para que sirva de aviso a todos que ousarem pisar em nossa terra ancestral.", t = "Expulse todos"},
    [99081] = {ot = "Leve o Relatório da Passo-longo Malah ao Valente Trilha Selvagem na Aldeia Casco Sangrento.", st = "Você vê o que parece ser um novo acampamento de centauros na direção de onde teriam vindo as flechas cravadas nas costas de Malah. Há movimentação no local, o que sugere que um pequeno grupo de ataque conseguiu entrar em Mulgore.\n\nA Passo-longo ainda segura um relatório na mão cerrada. O Valente Trilha Selvagem vai querer saber o que aconteceu com Malah... e quem a matou.", t = "Augúrios sinistros"},
    [99082] = {ot = "Peça uma audiência com o Grande Chefe Caerne Casco Sangrento no Penhasco do Trovão.", st = "Sua bravura ao defender seu povo merece reconhecimento. Viaje até o Penhasco do Trovão, a noroeste, nossa poderosa cidade, cuja sombra nos abriga do calor nos meses mais quentes, e peça uma audiência com meu pai.\n\nFoi ele quem liderou o ataque ao lado do jovem Chefe Guerreiro Thrall para reconquistar estas planícies e expulsar os centauros de uma vez por todas. Como Grande Chefe, ele recompensará você generosamente por sua contribuição para honrar a coragem que ele demonstrou.\n\nVocê terá que usar um elevador para chegar até o Grande Chefe, que se encontra na elevação central.", t = "O Grande Chefe"},
    [99101] = {ot = "Leve o Relatório da Passo-longo Malah a Baine Casco Sangrento.", st = "Baine Casco Sangrento lidera nossa aldeia. Ele precisa saber desta incursão imediatamente.\n\nLeve a ele o relatório da Passo-longo Malah. Você o encontrará no centro da aldeia.\n\nRápido. Não há tempo a perder!", t = "Nosso inimigo ancestral"},
    [99108] = {ot = "Derrote outros 3 jogadores em duelos ou Guerreiros Novatos para Tang Casco de Pedra.", st = "Saudações, jovem $c. Apesar de você não ser $Gguerreiro:guerreira; e eu não poder lhe ensinar esse ofício, não significa que minha tutela não lhe trará benefícios.\n\nÀ sua frente está a arena. Ali, não importa quem você chama de mãe nem se empunha espada ou arco. Todos são iguais, e é no combate direto que aprendem a afiar os chifres.\n\nVocê entrará em nosso espaço e aprenderá nossas tradições? Você pode enfrentar qualquer um desses novatos ou qualquer outro adversário disposto a lutar. Não me importa quem.", t = "Treino de pugilato"},
    [99123] = {ot = "Ajude Pal'juh a escapar do Penedo de Kolkar e avise o Mestre Vornal na Aldeia Sen'jin quando conseguir.", st = "Eu decidi fazer um serviço de escolta no penedo sozinha. Infelizmente, minha magia se esgotou na hora errada e fique escondida aqui desde então.\n\nSe você puder me ajudar a escapar, ficarei grata.", t = "Perdida nas sombras"},
    [99127] = {ot = "Verifique as armadilhas de pesca no Lago de Cristal.", st = "Os peixes não estão mordendo hoje, e tem alguma coisa estranha acontecendo com eles. O anzol vazio não é o único problema. Eu não vi uma única manjubinha na superfície.\n\nLee armou umas armadilhas à noite. Veja se conseguimos pegar alguma coisa lá. Se notar algo estranho, me mostre.", t = "Rede furada"},
    [99128] = {ot = "Mate $1oa Murlocs e $2oa Murlocs Corredores no Lago de Cristal, depois fale novamente com Jasão Matreiro.", st = "Isso só pode ser obra daqueles murlocs do outro lado do lago. Aquelas coisinhas nojentas têm um temperamento tão horrível quanto seus dentes. \n\nSe isso continuar, não vai sobrar peixe em lugar nenhum do lago. Você pode reduzir o contingente deles? Seria uma ajuda e tanto.", t = "Viscosos e perigosos"},
    [99129] = {ot = "Fale com Remy \"Duas Vezes\" sobre os problemas com os murlocs do Jasão.", st = "Remy falou sobre os murlocs noutro dia... Tenho certeza de que ele odeia esses pestinhas tanto quanto eu. \n\nTalvez ele tenha alguma ideia de como afastá-los dos meus peixes. Você poderia ir até lá ver se ele consegue pensar em alguma coisa?", t = "Como matar seu Murloc"},
    [99130] = {ot = "Colete $1oa Ampolas de Sangue de Animal e $2oa Pétalas de Erva-poente como isca para pegar murloc, depois fale novamente com Remy \"Duas Vezes\" na Vila d'Ouro.", st = "Tenho algumas ideias de como lidar com os murlocs. E uma delas também ajuda umas pessoas no processo.\n\nHá uma planta nas fazendas da área chamada erva-poente e, em grandes quantidades, as pétalas são tóxicas pra maioria dos animais. Se fizermos iscas de murloc com a planta, talvez a gente consiga ensinar esses bichos a manter distância.\n\nE alguns fazendeiros ganham uma limpeza de campo. Dois coelhos com uma cajadada só.", t = "Uma oferta irresistível"},
    [99131] = {ot = "Fale novamente com Jasão Matreiro.", st = "Fale ao Matreiro que ele pode vir buscar a isca hoje mais tarde. Vou passar um resumo de como usá-la do jeito certo.\n\nEspero que ele consiga voltar a vender peixes. E teremos menos murlocs neste mundo também.", t = "Isca do sucesso"},
    [99134] = {ot = "Puna $1oa Necroguardas para o Executor Zigano.", st = "Você não faz parte da Necroguarda e, por isso, ainda não me decepcionou.\n\nComo recompensa por sua relativa falta de incompetência, você deverá punir aqueles que demonstraram tais talentos em excesso.\n\nRápido — $n, não é? —, senão vou adicionar seu nome aos meus registros e dar a recompensa a outra pessoa.", t = "Disciplina"},
    [99141] = {ot = "Obtenha os relatórios do Necroguarda Dinis, do Necroguarda Kristof e de Gordo para o Executor Zigano.", st = "Não se engane, $c — a Dama Sombria exige a execução perfeita de sua vontade. Por ser um Executor, é meu dever garantir que isso aconteça.\n\nOs relatórios de vários dos meus Necroguardas estão atrasados. Nem preciso dizer que minha paciência já se esgotou. Obtenha esses relatórios e traga-os pra mim em nome da Dama Sombria.\n\nEncontre o Necroguarda Dinis a oeste daqui, perto do cemitério. O Necroguarda Kristof está posicionado na estação ao leste. E confira Gordo, aquela abominação. Ele perambula a oeste, perto da Lagoa das Águas Paradas.", t = "Paciência"},
    [99142] = {ot = "Colete $1oa Ervas de Tumba e entregue para o Boticário-júnior Hollanda.", st = "Se você estiver indo para o leste, rumo à Fazenda dos Balnir, há mais coisas que você pode fazer por mim. Está muito difícil encontrar ajuda ultimamente, como ficou muito claro com a discussão com o Gordo.\n\nCom a erva-do-demo em mãos, opero pequenas transmutações alquímicas e torno a plantá-la naquela fazenda a fim de cultivar minha obra definitiva. Chamo-a de erva de tumba, e ela há de ser o prenúncio do meu destino glorioso.\n\nEnquanto estiver na área, fique de olho no Flagelo. Parece que ele é... atraído... pela erva. Curioso.", t = "Erva de Tumba"},
    [99143] = {ot = "Colete $1oa pedaços de Sucata Brilhante do agrupamento próximo de murlocs.", st = "Aqueles homens-peixe devem pensar como peixes, não devem? Ou seja, isso significa que eles gostam das mesmas coisas que os peixes!\n\nSe você revirar o lixo deles e voltar aqui com algo que pareça uma boa isca, eu lhe dou uma recompensa.", t = "Botijas e badulaques"},
    [99144] = {ot = "Ajude Barreto Aurolita a fugir da Guarita do Cruzado e informe Shária Calmafonte, em Montalvo, de que ele está a salvo.", st = "Que a Luz abençoe você por ter me encontrado. Eu vinha da Bastilha de Bandarion para entregar uma mensagem a Shária Calmafonte em Montalvo, quando esses monstros me capturaram. Eles empunham a Luz com tanto ódio no coração que fazem ferver o pouco sangue que me resta. Isso vai contra tudo pelo que medito... tudo que eu almejo proteger!\n\n<Barreto Aurolita se recompõe.>\n\nSei que ainda há muita desconfiança acerca da nossa raça, mas garanto que nossas intenções são puras. Se me ajudar a fugir daqui, serei eternamente grato.", t = "Em busca de refúgio"},
    [99152] = {ot = "Colete $1oa Ossos Levemente Brilhantes para Hilda, a Devastadora.", st = "Embora os Manchados no Vale das Sombras a sudoeste sejam um problemão, não podemos permitir que os porões sob a cidade se transformem numa insurreição do Flagelo na Bastilha de Bandarion.\n\nEu preciso deixar os novatos preparados caso isso aconteça. Mas você vai receber o que eu gosto de chamar de \"intensivão\".\n\nVá até o subsolo do Vale das Sombras e obtenha alguns daqueles ossos desprezíveis para podermos estudá-los mais. Preciso daqueles que ainda retêm parte da magia de reanimação inicial — aqueles que brilham.", t = "Assim na terra como no céu"},
    [99153] = {ot = "Encontre o Fragmento de Cristal Oculto abaixo do Vale das Sombras para Efraim Barbaro.", st = "Opa, e aí! As notícias andam rápido por nossas fileiras. Eu soube do trabalho que tu fez com os sectários com relação aos restos da batalha com Naxxramas.\n\nO problema é que um dos sectários fugiu com uma parte do cristal de concentração que parece ainda conter alguma essência. Nosso melhor palpite é que tá em algum lugar abaixo do Vale das Sombras. Ou ele tá criando novos, ou fortalecendo os que já existem, e nenhuma opção é boa.\n\nEncontre esse cristal antes que tudo saia do controle.", t = "E o sectário levou"},
    [99156] = {ot = "Leve o Coração de Talharretalha até a Necroguarda Lina.", st = "Mas que droga! Chegou um novo relatório enquanto você estava em patrulha. Avistaram uma abominação perigosa vagando nas Clareiras de Tirisfal ao leste, perto do Vale Veneracnídeo.\n\nTem alguma coisa errada. Abominações não passam despercebidas pelo Baluarte.\n\nMantenha esse assunto em absoluto sigilo, fale apenas com quem for necessário. Dito isso, essa criatura não morrerá facilmente. Você precisará de aliados se não quiser ser a próxima refeição.\n\nSe tiver sucesso, ganhará uma boa recompensa. Traga-me o coração dela como prova.", t = "Patrulha da retaguarda"},
    [99158] = {ot = "Leve o Caixote de Velas até o Padre Gavin no Refúgio Pinhal das Brumas.", st = "Há um sacerdote nas montanhas que pertence a uma organização chamada Aurora Argêntea. Eles são um grupo sagrado dedicado a encontrar e destruir o profano e o sobrenatural.\n\nMas o Padre Gavin é mais do tipo que procura ajudar e curar todo mundo, em vez de pegar em armas. Ele arrumou um prédio antigo pra servir de local de repouso para os viajantes e o chamou de Refúgio Pinhal das Brumas. Preciso levar um carregamento de velas sagradas até ele. Você tem como levá-las até ele, se for caminho?", t = "Aurora nas montanhas"},
    [99159] = {ot = "Colete $1oa pedaços de Lenha.", st = "Meu coração está aberto para confortar todas as almas, mas eu gostaria de pedir sua ajuda, se possível.\n\nEu só preciso de mais lenha. É algo que eu faria por conta própria, mas minha preocupação com outras tarefas anda muito alta.", t = "Aquele calorzinho reconfortante"},
    [99160] = {ot = "Destrua $1oa Elementais de Gelo Menores.", st = "Você deve ter percebido os elementais aqui perto. Uma plataforma de pedra e gelo caiu do alto das montanhas há alguns dias e os irritou.\n\nEssas montanhas congeladas já são traiçoeiras para o anão ou humano médio sem os elementos tomando forma. Não sirvo mais para lutar, então qualquer espírito que você consiga matar deixará a estrada mais segura.", t = "A ira da geada"},
    [99161] = {ot = "Mate Avala e pegue o núcleo dele.", st = "Notei que o primeiro elemental que apareceu após a avalanche era maior do que os outros. Até onde eu pude ver, ele é a causa de mudanças climáticas ocasionais e outros deslizamentos menores.\n\nBatizei ele de \"Avala\". Mate-o e traga o núcleo dele como prova. Darei uma recompensa.", t = "A ira da geada"},
    [99162] = {ot = "Colete os Rifles dos montanhistas mortos.", st = "Até os montanhistas de Altaforja precisam ficar atentos ao atravessar os picos de Dun Morogh. Neve e gelo caindo costumam significar o fim da vida de alguns membros mais novatos.\n\nDepois de um deslizamento, eu costumo procurar qualquer sinal de sobreviventes ou vítimas — enquanto rezo para a Luz que não encontre nada. Mas, com a instabilidade dos elementos, tenho evitado me afastar muito. Se você puder procurar alguns montanhistas perdidos e me trazer os rifles deles, eu os devolverei a Altaforja.", t = "Frio traiçoeiro"},
    [99260] = {ot = "Fale com Elaadrin Plenovento em Valanaar.", st = "Recebi a tarefa de recuperar dados importantes sobre o fluxo de energia elemental nas Pedras Erguidas do Mirante. Esses dados são vitais para nossos planos de viajar em segurança entre a Muralha Celeste e Azeroth. Sem esses dados para auxiliar nossos cálculos, nossas tentativas de conduzir nossas naus rasgacéus pelo plano elemental fracassarão.\n\nOs dados provavelmente já se perderam, e eu não estou em condições de tentar reuni-los outra vez. Contei ao Magíster Supremo sobre seu papel em me salvar, e ele deseja falar com você de novo.", t = "A missão de Filião"},
    [99411] = {ot = "Ahab Casco Trigo, na Aldeia Casco Sangrento em Mulgore, quer que você alimente o bichinho de estimação dele, Kyle, o Frenético.$B$BAlimente Kyle com Carne Tenra de Moa e fale novamente com Ahab Casco Trigo.", st = "Me ajude, $n! Kyle, meu bichinho de estimação, fugiu! Só sei que ele está à solta na Aldeia Casco Sangrento, perdido e faminto.$B$BVocê poderia encontrá-lo e alimentá-lo? Quando comer, ele vai se acalmar e voltar para casa.$B$BPara alimentá-lo, você precisa encontrar comida. A comida predileta dele é carne tenra de moa. Siga para o leste e você encontrará moas de sobra. Cace um e leve a carne suculenta para Kyle. Quando encontrar Kyle na cidade, ponha a carne no chão que ele irá até você.", t = "Kyle sumiu!"},
  },
})
end)
